(1, 'Bí quyết nấu món Phở Bò truyền thống đậm đà', 'bi-quyet-nau-mon-pho-bo-truyen-thong-dam-da', 'https://images.unsplash.com/photo-1582878826629-29b7ad1cdc43?w=800', 'Bí quyết, Truyền thống', 'Khám phá những bí quyết gia truyền để có nồi nước dùng phở trong veo, ngọt thanh và thơm nồng nàn.', 'Nội dung chi tiết về cách nấu phở...', 0, 1, 1, 459, '2026-05-15 14:21:27', '2026-05-26 14:13:21', NULL),
(2, 'Top 10 thực phẩm tốt nhất cho sức khỏe mùa hè', 'top-10-thuc-pham-tot-nhat-cho-suc-khoe-mua-he', 'https://images.unsplash.com/photo-1490818387583-1baba5e638af?w=800', 'Sức khỏe, Mùa hè', 'Mùa hè nắng nóng, hãy bổ sung ngay những thực phẩm này để giữ cơ thể luôn tươi trẻ và tràn đầy năng lượng.', 'Nội dung chi tiết về thực phẩm mùa hè...', 0, 1, 1, 296, '2026-05-15 14:21:27', '2026-06-02 02:47:28', NULL),
(3, 'Xu hướng ẩm thực xanh và bền vững năm 2026', 'xu-huong-am-thuc-xanh-va-ben-vung-nam-2026', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=800', 'Xu hướng, Sống xanh', 'Ẩm thực không chỉ là ăn ngon mà còn là trách nhiệm với môi trường. Cùng điểm qua những xu hướng mới nhất.', 'Nội dung chi tiết về ẩm thực xanh...', 0, 1, 1, 166, '2026-05-15 14:21:27', '2026-05-26 14:13:22', NULL);
