(2, 'Người Truyền Cảm Hứng', 'nguoi-truyen-cam-hung', 'Công thức của bạn nhận được tổng cộng hơn 1000 lượt yêu thích.', '🌟', 1, '2026-05-04 07:22:18', '2026-05-04 07:22:18', NULL),
(3, 'Thành Viên Tích Cực', 'thanh-vien-tich-cuc', 'Đăng nhập liên tục trong 7 ngày để nhận huy hiệu này.', '🔥', 1, '2026-05-04 07:22:18', '2026-05-04 07:22:18', NULL),
(4, 'Chuyên Gia Bình Luận', 'chuyen-gia-binh-luan', 'Có hơn 100 bình luận đóng góp ý kiến cho các đầu bếp khác.', '💬', 1, '2026-05-04 07:22:18', '2026-05-04 07:22:18', NULL),
(5, 'Đầu Bếp Mới (Newbie)', 'dau-bep-moi-newbie', 'Huy hiệu chào mừng bạn gia nhập cộng đồng Góc Bếp.', '🌱', 1, '2026-05-04 07:22:18', '2026-05-04 07:22:18', NULL),
(6, 'Bậc Thầy Gia Vị', 'bac-thay-gia-vi', 'Sử dụng thành thạo và chia sẻ các bí quyết nêm nếm độc đáo.', '🧂', 1, '2026-05-04 07:22:18', '2026-05-04 07:22:18', NULL),
(7, 'Thánh Nấu Ăn', 'thanh-nau-an', 'Hoàn thành thử thách 100 món ăn.', '🏆', 1, '2026-05-16 09:28:55', '2026-05-16 09:28:55', NULL),
(8, 'Ngôi Sao Triển Vọng', 'ngoi-sao-trien-vong', 'Hoàn thành thử thách dành cho người mới nổi.', '⭐', 1, '2026-05-16 09:28:55', '2026-05-16 09:28:55', NULL),
(9, 'Bậc Thầy Ẩm Thực', 'bac-thay-am-thuc', 'Đạt mức điểm tối đa trong sự kiện Mùa Đông.', '🏅', 1, '2026-05-16 09:28:55', '2026-05-16 09:28:55', NULL),
(10, 'Phù Thủy Hương Vị', 'phu-thuy-huong-vi', 'Nhận được 5000 lượt yêu thích trên tất cả món ăn.', '🪄', 1, '2026-05-16 09:28:55', '2026-05-16 09:28:55', NULL);
INSERT INTO `banners` (`id`, `title`, `tag`, `description`, `image`, `rating`, `link`, `is_active`, `order`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Lễ hội Ẩm thực Mùa Hè 2026', 'Sự kiện Hot', 'Tham gia ngay chuỗi sự kiện ẩm thực đường phố và nhận hàng ngàn voucher quà tặng hấp dẫn từ các đầu bếp hàng đầu.', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?q=80&w=1974&auto=format&fit=crop', '4.9/5.0', '#', 1, 1, '2026-05-19 23:33:38', '2026-05-19 23:33:38', NULL),
(2, 'Cuộc thi: Đầu bếp tại gia xuất sắc', 'Khám phá', 'Trổ tài nấu nướng đỉnh cao, chia sẻ công thức độc quyền và nhận cúp vàng danh giá cùng phần thưởng 50.000.000đ.', 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?q=80&w=2070&auto=format&fit=crop', '4.8/5.0', '#', 1, 2, '2026-05-19 23:33:38', '2026-05-19 23:33:38', NULL),
(3, 'Bí quyết nấu ăn chay thanh lọc cơ thể', 'Mẹo hay', 'Khám phá các công thức chay độc đáo, đủ dưỡng chất từ đầu bếp 5 sao giúp thanh mát cơ thể và tràn đầy năng lượng mỗi ngày.', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?q=80&w=2070&auto=format&fit=crop', '4.9/5.0', '#', 1, 3, '2026-05-19 23:33:38', '2026-05-19 23:33:38', NULL),
(4, 'Hương vị Việt Nam: Đậm đà bản sắc', 'Ẩm thực Việt', 'Tổng hợp hàng trăm công thức món Việt truyền thống chuẩn vị ba miền từ phở, bún chả đến cơm tấm sườn bì chả.', 'https://images.unsplash.com/photo-1596797038530-2c107229654b?q=80&w=2070&auto=format&fit=crop', '5.0/5.0', '#', 1, 4, '2026-05-19 23:33:38', '2026-05-19 23:33:38', NULL);
