(1, 36, 1, NULL, 'Đây là công thức chuẩn nhất mà mình từng thử qua, không chê vào đâu được.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(2, 17, 1, NULL, 'Nấu cho bé nhà mình ăn, bé ăn rất ngon miệng. Cảm ơn bạn nhiều nhé!', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(3, 12, 1, NULL, 'Mẹo nhỏ cho món phở bò của bạn giúp nước dùng trong veo, thơm nồng mùi quế hồi.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(4, 22, 1, NULL, 'Cảm ơn tác giả, mình đã thử và thành công ngay lần đầu. Bí quyết hầm xương rất hữu ích.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(5, 9, 1, 4, 'Chúc bạn nấu thêm được nhiều món ngon cho gia đình từ các công thức của mình.', '2026-05-02 08:44:52', '2026-05-02 08:44:52'),
(9, 34, 3, NULL, 'Nguyên liệu dễ tìm, cách làm đơn giản mà kết quả lại ngoài mong đợi.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(10, 34, 3, 9, 'Lần đầu mình làm món này mà đã thành công rực rỡ rồi, vui quá!', '2026-05-01 11:15:52', '2026-05-01 11:15:52'),
(11, 13, 3, NULL, 'Mình đã làm thử và cho thêm một chút hành phi, vị thơm hơn hẳn.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(12, 6, 3, 11, 'Rất vui vì bạn đã thành công. Hãy chia sẻ thành quả lên nhóm nhé!', '2026-05-01 20:18:52', '2026-05-01 20:18:52'),
(13, 11, 3, NULL, 'Món này ngon tuyệt, cả nhà mình đều thích! Nước dùng rất đậm đà.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(15, 20, 4, NULL, 'Món này ăn kèm với rau sống và nước mắm chua ngọt thì đúng là cực phẩm.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(16, 31, 4, 15, 'Đúng rồi bạn, cho thêm hành phi sẽ làm món ăn dậy mùi hơn rất nhiều.', '2026-05-02 13:57:52', '2026-05-02 13:57:52'),
(17, 33, 4, NULL, 'Tuyệt vời! Cách trình bày của bạn rất đẹp, mình sẽ học theo.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(19, 33, 4, NULL, 'Gia đình mình vừa ăn xong, ai cũng tấm tắc khen ngon. Sẽ ủng hộ bạn dài dài.', '2026-05-01 01:20:52', '2026-05-01 01:20:52'),
(20, 7, 4, NULL, 'Bài viết rất hữu ích cho người mới tập nấu ăn như mình. Các bước hướng dẫn rất dễ hiểu.', '2026-05-01 01:20:52', '2026-05-16 13:18:29'),
