INSERT INTO `quotes` (`id`, `content`, `author`, `source`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Nấu ăn là nghệ thuật, và người nấu ăn giỏi nhất là người pha trộn được yêu thương vào từng món ăn.', 'Kitchen Corner', NULL, 1, 1, '2026-04-17 01:04:21', '2026-04-17 01:04:21'),
(2, 'Nấu ăn là một nghệ thuật, và người đầu bếp là một nghệ sĩ.', 'Khuyết danh', NULL, 0, 1, '2026-04-30 18:33:54', '2026-04-30 18:33:54'),
(3, 'Hạnh phúc là được ăn món mình thích cùng người mình yêu.', 'Chef Gordon', NULL, 0, 1, '2026-04-30 18:33:54', '2026-04-30 18:33:54');
INSERT INTO `recipes` (`id`, `user_id`, `category_id`, `title`, `slug`, `description`, `cooking_time`, `difficulty`, `total_calories`, `total_protein`, `total_carbs`, `total_fat`, `image`, `view_count`, `is_featured`, `is_premium`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 17, 5, 'Sườn Xào Chua Ngọt Đậm Đà', 'suon-xao-chua-ngot-dam-da-32ue', 'Món sườn xào chua ngọt truyền thống với lớp sốt bóng bẩy, thịt sườn mềm thơm quyện cùng vị chua dôn dốt của cà chua và chút cay nồng của tiêu đỏ. Tuyệt hảo khi dùng kèm cơm trắng nóng hổi.', 45, 'medium', 550, 30, 45, 25, 'https://images.unsplash.com/photo-1544025162-811cffd92ef7?q=80&w=1000&auto=format&fit=crop', 1561, 1, 0, 'published', '2026-05-15 14:21:26', '2026-05-26 14:13:31', NULL),
(3, 7, 5, 'Salad Ức Gà Áp Chảo Healthy', 'salad-uc-ga-ap-chao-healthy-8lx2', 'Món salad tràn ngập màu sắc và dinh dưỡng. Thích hợp cho chế độ ăn kiêng Eat Clean, giữ trọn hương vị tươi mát của rau củ kết hợp với ức gà áp chảo mọng nước, đậm đà.', 20, 'easy', 320, 45, 15, 10, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?q=80&w=1000&auto=format&fit=crop', 3420, 0, 0, 'published', '2026-05-15 14:21:26', '2026-05-26 14:13:32', NULL),
(4, 2, 6, 'Spaghetti Bolognese (Sốt Bò Bằm)', 'spaghetti-bolognese-sot-bo-bam-bo9s', 'Tuyệt tác của nền ẩm thực Ý mang đến hương vị quyến rũ không thể cưỡng lại. Sốt thịt bò bằm với cà chua tươi hòa quyện cùng mì Ý sợi dai dai, phủ một lớp phô mai Parmesan bào sợi thơm lừng.', 30, 'easy', 600, 25, 70, 20, 'https://images.unsplash.com/photo-1598866594230-a7c12756260f?q=80&w=1000&auto=format&fit=crop', 355, 1, 0, 'published', '2026-05-15 14:21:26', '2026-05-26 14:24:54', NULL),
(5, 50, 9, 'Bánh Pancake Dâu Tây Mềm Xốp', 'banh-pancake-dau-tay-mem-xop-ksdx', 'Món tráng miệng hoặc bữa sáng kiểu Tây cực kỳ dễ làm. Những lớp bánh pancake mềm mịn tơi xốp, thơm mùi bơ sữa và trứng gà, rưới thêm siro phong và kết hợp với dâu tây tươi chua ngọt.', 20, 'easy', 380, 10, 55, 12, 'https://images.unsplash.com/photo-1567620905732-2d1ec7bb7445?q=80&w=1000&auto=format&fit=crop', 2659, 0, 0, 'published', '2026-05-15 14:21:26', '2026-05-26 14:13:25', NULL),
(6, 5, 1, 'Cá Hồi Nướng Măng Tây Sốt Chanh Bơ', 'ca-hoi-nuong-mang-tay-sot-chanh-bo-0tnu', 'Món ăn Âu mang đậm phong cách nhà hàng 5 sao nay có thể thực hiện tại nhà siêu nhanh. Cá hồi Na Uy chứa nhiều Omega-3 áp chảo giữ được độ ẩm mềm béo, ăn kèm măng tây giòn ngọt và sốt chanh bơ tan chảy đầu lưỡi.', 25, 'medium', 450, 40, 8, 28, 'https://images.unsplash.com/photo-1467003909585-2f8a72700288?q=80&w=1000&auto=format&fit=crop', 2741, 1, 0, 'published', '2026-05-15 14:21:26', '2026-05-26 14:13:05', NULL),
(8, 19, 9, 'Chè Trôi Nước Ngũ Sắc', 'che-troi-nuoc-ngu-sac-krh7', 'Món chè truyền thống được nâng tầm thành một tác phẩm nghệ thuật với 5 màu sắc hoàn toàn từ thiên nhiên: gấc, lá cẩm, lá dứa, nghệ và khoai môn. Lớp vỏ dẻo quánh bọc nhân đậu xanh bùi bùi, tắm trong nồi nước cốt dừa nồng nàn vị gừng tươi.', 90, 'medium', 410, 8, 75, 15, 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?q=80&w=1000&auto=format&fit=crop', 2115, 0, 0, 'published', '2026-05-15 14:21:27', '2026-05-26 14:13:37', NULL),
(9, 17, 5, 'Cà Ri Gà Kiểu Thái (Thai Green Curry)', 'ca-ri-ga-kieu-thai-thai-green-curry-8n9f', 'Đánh thức mọi giác quan với món cà ri xanh kiểu Thái chuẩn vị siêu bắt cơm. Nước dùng là sự pha trộn diệu kỳ của cốt dừa béo ngậy bùng nổ cùng cốt lá chanh kaffir, sả, riềng và vị cay xé lưỡi từ ớt xanh.', 40, 'medium', 520, 28, 22, 38, 'https://images.unsplash.com/photo-1455619411412-d5e810614868?q=80&w=1000&auto=format&fit=crop', 1629, 0, 0, 'published', '2026-05-15 14:21:27', '2026-06-03 13:24:49', NULL),
(10, 3, 7, 'Bún Chả Hà Nội Nướng Than Hoa', 'bun-cha-ha-noi-nuong-than-hoa-etjv', 'Đậm đà phong vị Bắc Bộ với những miếng chả băm và chả miếng được ướp sả ớt, nướng xèo xèo trên lửa than hoa hồng rực. Quyện cùng bát nước mắm chua ngọt ấm nóng suýt xoa ăn kèm rau sống và bún tươi dai dẻo.', 60, 'medium', 580, 32, 65, 20, 'https://images.unsplash.com/photo-1622312674312-d81a942defff?q=80&w=1000&auto=format&fit=crop', 1433, 1, 0, 'published', '2026-05-15 14:21:27', '2026-05-26 14:49:47', NULL),
(11, 5, 9, 'Bánh Mì Chảo Thập Cẩm Pate', 'banh-mi-chao-thap-cam-pate-8kps', 'Tuổi thơ mỗi cuối tuần luôn khao khát chảo gang xì xèo bò bít tết băm, xúc xích dai dai, trứng ốp la đào vàng mọng, trét kèm lớp pate gan mịn mượt đẫm ngậy chấm một miếng bánh mì giòn tan hổi.', 15, 'easy', 650, 25, 50, 35, 'https://images.unsplash.com/photo-1627308595229-7830f5c92135?q=80&w=1000&auto=format&fit=crop', 3627, 0, 0, 'published', '2026-05-15 14:21:27', '2026-05-27 03:35:32', NULL),
(12, 45, 5, 'Tacos Gà Nướng Mexico', 'tacos-ga-nuong-mexico-bb1y', 'Món Tacos giòn tan cuộn trọn vẹn gia vị ướp Mexican đầy hoang dã. Gà xé đậm đà cay nồng hòa cùng gừng và sốt Salsa chu chua tươi mát, phủ thật nhiều ngò gai và bơ xắt cục hạt lựu béo bùi.', 35, 'easy', 450, 28, 35, 20, 'https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?auto=format&fit=crop&q=80&w=900', 1674, 1, 0, 'published', '2026-05-15 14:21:27', '2026-05-26 14:13:36', NULL),
(13, 47, 7, 'Ếch Om Chuối Đậu', 'ech-om-chuoi-dau-9uta', 'Món nhậu gắn liền với ẩm thực đồng quê miền Bắc, nồi ếch om dẻo sánh thơm lựng thứ mùi đặc trưng từ tía tô lá lốt, miếng ếch dai chắc thịt hòa quyện cùng chuối xanh bùi dẻo quánh tơi, mẻ chua thanh nhẹ ngon rạo rực.', 50, 'medium', 450, 38, 45, 12, 'https://images.unsplash.com/photo-1580476262798-bddd9f4b7369?auto=format&fit=crop&q=80&w=900', 1305, 1, 0, 'published', '2026-05-15 14:21:27', '2026-05-26 14:24:29', NULL),
(14, 33, 5, 'Algeria Kefta (Thịt viên)', 'algeria-kefta-thit-vien-QTE3', 'Algeria Kefta (Thịt viên) là một Món chính đặc sắc, mang đậm phong vị ẩm thực hấp dẫn. Món ăn này được chế biến từ những nguyên liệu tươi ngon, tạo nên sự hòa quyện hoàn hảo về cả màu sắc lẫn hương vị. Với công thức chi tiết và dễ thực hiện, Algeria Kefta (Thịt viên) hứa hẹn sẽ là điểm nhấn tuyệt vời cho thực đơn gia đình bạn. Hãy bắt tay vào bếp và cùng thực hiện ngay món ăn này nhé!', 55, 'medium', 616, 25, 26, 18, 'assets/recipes/mealdb_53281.jpg', 720, 0, 1, 'published', '2026-05-15 14:27:28', '2026-05-26 09:54:54', NULL),
(15, 45, 5, 'Arepa Pabellón', 'arepa-pabellon-CXDL', 'Arepa Pabellón là một Món chính đặc sắc, mang đậm phong vị ẩm thực hấp dẫn. Món ăn này được chế biến từ những nguyên liệu tươi ngon, tạo nên sự hòa quyện hoàn hảo về cả màu sắc lẫn hương vị. Với công thức chi tiết và dễ thực hiện, Arepa Pabellón hứa hẹn sẽ là điểm nhấn tuyệt vời cho thực đơn gia đình bạn. Hãy bắt tay vào bếp và cùng thực hiện ngay món ăn này nhé!', 52, 'medium', 533, 33, 66, 25, 'assets/recipes/mealdb_53334.jpg', 473, 0, 1, 'published', '2026-05-15 14:27:31', '2026-05-17 16:18:54', NULL),
