INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'Rửa sạch sườn, chần sơ qua nước sôi để khử mùi hôi. Vớt ra để ráo nước.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(2, 1, 2, 'Chiên sườn vàng đều các mặt trên chảo dầu nóng, vớt ra đĩa có giấy thấm dầu.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(3, 1, 3, 'Phi thơm hành tỏi băm, cho cà chua xào nát tạo màu. Thêm giấm, đường, nước mắm, xì dầu và nửa chén nước lọc đun sôi.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(4, 1, 4, 'Trút sườn vào chảo sốt, đảo đều tay trên lửa nhỏ riu riu cho đến khi sốt sánh lại, bám đều quanh miếng sườn.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(5, 1, 5, 'Tắt bếp, rắc hành lá và tiêu đen. Bày ra đĩa thưởng thức.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(11, 3, 1, 'Sơ chế ức gà, khía các đường chéo để ngấm gia vị. Ướp ức gà với xíu muối, tiêu đen, 1 muỗng dầu oliu trong 10 phút.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(12, 3, 2, 'Làm nóng chảo, áp chảo ức gà lửa vừa mỗi mặt khoảng 4-5 phút cho xém vàng và chín tới bên trong. Vớt ra thái lát.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(13, 3, 3, 'Pha nước sốt: Trộn đều dầu oliu còn lại, mật ong, giấm táo, chút muối và tiêu thành hỗn hợp đồng nhất.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(14, 3, 4, 'Xếp xà lách, cà chua bi, dưa chuột ra đĩa. Trải ức gà lên trên.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(15, 3, 5, 'Rưới nước sốt đều lên đĩa salad trước khi ăn và trộn nhẹ nhàng.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(16, 4, 1, 'Luộc mì với 1 muỗng muối và chút dầu ăn trong 8 - 10 phút. Vớt ra để ráo, xóc qua xíu dầu ăn cho các sợi không dính nhau.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(17, 4, 2, 'Phi thơm tỏi và hành tây, cho thịt bò băm vào xào săn lại lửa lớn.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(18, 4, 3, 'Đổ cà chua xay nhuyễn và sốt tomato paste vào chảo, đảo đều. Nêm chút muối, đường, hạt tiêu.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(19, 4, 4, 'Thêm nửa bát nước, đun liu riu cho sốt sền sệt lại khoảng 15 phút. Rắc lá oregano nếm lại vừa miệng rồi tắt bếp.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(20, 4, 5, 'Bày mì ra đĩa, rưới đẫm sốt bò băm lên trên và rắc phô mai Parmesan bào sợi. Ăn ngay khi nóng.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(21, 5, 1, 'Trộn bột mì, nửa lượng đường, bột nở với nhau. Đánh tan lòng đỏ trứng với bơ đun chảy và sữa tươi, đổ vào hỗn hợp bột khuấy nhẹ tay.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(22, 5, 2, 'Dùng máy đánh trứng đánh bông lòng trắng với nửa lượng đường còn lại đến khi chóp mềm.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(23, 5, 3, 'Chia lòng trắng đánh bông làm 3 phần, nhẹ nhàng trộn fold vào âu bột ở bước 1.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(24, 5, 4, 'Làm nóng chảo chống dính, phết một lớp bơ siêu mỏng. Múc 1 muôi bột đổ thẳng vào giữa chảo để bột tự dàn tròn.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(25, 5, 5, 'Rán nhỏ lửa khoảng 2 phút đến khi mặt bánh nổi bọt khí, lật bánh rán tiếp 1 phút.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(26, 5, 6, 'Xếp các miếng bánh pancake xếp chồng lên nhau, rải dâu tây và rưới siro phong lên đỉnh bánh. Có thể rắc thêm xíu đường bột.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(27, 6, 1, 'Thấm khô miếng cá hồi. Ướp cá với muối, tiêu và chút vỏ chanh vàng bào nhuyễn trong 5 phút.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(28, 6, 2, 'Măng tây rửa sạch, luộc sơ qua nước sôi 1 phút rồi vớt ra ngâm nước đá, để ráo.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(29, 6, 3, 'Làm nóng chảo với chút dầu oliu, áp chảo mặt có da cá hồi trước ở lửa lớn 3 phút đến khi da giòn rụm, lật mặt áp chảo thêm 1.5 phút cho cá chín tái bên trong rồi lấy ra.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(30, 6, 4, 'Dùng cùng chảo đó (hạ lửa nhỏ), đun chảy phần bơ nhạt, phi thơm tỏi băm. Thêm rượu vang trắng, nước cốt chanh vào đun sôi.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(31, 6, 5, 'Đợi sốt hơi sệt lại, cho ngò tây băm vào. Tắt bếp.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(32, 6, 6, 'Bày măng tây ra đĩa, đặt fillet cá hồi lên trên, rưới sốt bơ chanh vàng óng lên cá và thưởng thức cùng khoai tây nghiền nếu thích.', NULL, '2026-05-15 14:21:26', '2026-05-15 14:21:26'),
(39, 8, 1, 'Làm nhân: Đậu xanh hấp chín mềm, tán nhuyễn. Phi thơm hành tím với dầu ăn, trút đậu xanh dừa nạo và đường xào đến khi nhân tróc chảo dính viên không vỡ. Nặn thành các viên tròn nhỏ.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(40, 8, 2, 'Làm vỏ: Chia bột nếp làm 5 âu. Lần lượt nhồi bột với các loại nước màu đun nóng già (gấc đỏ, dứa xanh, cẩm tím...) cho đến khi bột thành khối dẻo không dính tay.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(41, 8, 3, 'Nặn chè: Lấy lượng bột vừa đủ, ấn dẹt, đặt viên nhân đậu xanh vào giữa rồi vo tròn kín mít.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(42, 8, 4, 'Luộc chè: Thả các viên trôi nước vào nồi nước đang sôi. Khi chè nổi lên mặt nước và vỏ bóng láng nghĩa là đã chín. Vớt ngay vào thau nước lạnh múc ra rổ.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(43, 8, 5, 'Nấu canh đường: Đun 1 lít nước với đường thốt nốt và gừng sợi. Nước sôi thơm thì thả viên chè đã luộc vào, đun lửa nhỏ liu riu thêm 5 phút cho chè thấm đường.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(44, 8, 6, 'Múc chè ra bát, chan nước cốt dừa đun lá nếp lên trên và rắc xíu hạt mè rang trắng.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(45, 9, 1, 'Bắt chảo nóng, múc lớp cream béo dầy trên bề mặt lon nước cốt dừa đun nóng phi thơm đến khi ra chút dầu. Cho sốt cà ri xanh vào rang thật thơm.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(46, 9, 2, 'Đổ ức gà thái mỏng vào xào săn với lớp sốt cay để thịt thấm đẫm mùi hương viền trong ngoài.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(47, 9, 3, 'Châm thêm nước dùng gà và phần cốt dừa còn lại vào nồi. Nêm đường thốt nốt nấu chảy và nước mắm, khuấy nhẹ cho vị hòa quyện.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(48, 9, 4, 'Cho cà tím, đậu que và lá chanh Kaffir xé nhỏ vào hầm tiếp khoảng 7 phút đến khi rau củ mềm nhưng chưa bị nát nhừ rã.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(49, 9, 5, 'Tắt bếp, vo tròn lá húng quế thả vào cùng vài lát ớt sừng đỏ trang trí trên cùng.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(50, 9, 6, 'Múc ra tô sâu, thưởng thức nóng với cơn gạo lài (Jasmine rice) bốc khói siêu lôi cuốn.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(51, 10, 1, 'Pha sốt ướp chả: Trộn đều nước cốt sả, hành tỏi băm, tiêu đen, đường, nước mắm, nước hàng và dầu hào. Chia sốt ướp làm đôi.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(52, 10, 2, 'Ướp chả: Trộn 1 nửa sốt với thịt nạc vai xay, vo thành từng viên tròn dẹt dẹt. Trộn nửa sốt còn lại với thịt ba chỉ thái lát mỏng. Ướp bọc kín trong tủ lạnh ít nhất 2 giờ thấm vị.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(53, 10, 3, 'Làm đồ chua: Đu đủ, cà rốt tỉa hoa mỏng, bóp muối rửa sạch rồi ngâm với dấm, đường, xíu muối pha chua chua ngọt ngọt.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(54, 10, 4, 'Nướng chả: Kẹp thịt lên vỉ than hoa quạt hồng, lật liên tục đều tay để chả chín vàng xém xém dậy mùi sả mà không bị cháy đen đắng chát. Thỉnh thoảng rưới chút mỡ lên mặt chả khỏi khô.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(55, 10, 5, 'Pha nước chấm ấm nóng: Đun tỉ lệ 4 nước lọc, 1 mắm cốt, 1 đường, 1 giấm thành dung dịch ấm tản mạn. Đổ ra bát, thêm tỏi ớt băm.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(56, 10, 6, 'Bày bún ra đĩa lớn kèm rổ rau sống. Múc thịt nướng ra bát gốm, cho đồ chua vào và chan ngập nước mắm ấm. Vừa thổi vừa ăn ngon bá cháy.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(57, 11, 1, 'Làm chảo gang lên bếp lửa lớn, cho bơ phết vào tan chảy sôi lên kêu xèo lạch cạch sướng lỗ tai.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(58, 11, 2, 'Thả xúc xích khía vào đảo một lúc cho da bung hoa đều lên. Cho tiếp hành tây thái sợi và miếng thịt bò vào chỉ chừng 30 giây đến khi bò tái đổi màu tươm nước áp ra.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(59, 11, 3, 'Đập trực tiếp 2 quả trứng gà vào góc trống trong chảo đun ốp la lên mắt ngà ngà chưa tới để lòng đỏ chảy.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(60, 11, 4, 'Dùng thìa múc nhanh lượng pate béo để vào góc trống còn lại. Cắt mỏng thêm miếng cà chua thả góc chảo cho nước sốt hòa vào nhau.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(61, 11, 5, 'Đợi mặt trứng viền xém giòn, rắc hành ngò lên trên cùng xíu tiêu đen và tương ớt/tương cà xịt tròn xung quanh. Nhấc nguyên chảo xuống đệm gỗ kê bàn nóng!', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(62, 11, 6, 'Cầm ổ bánh mì xé thành đôi, quẹt cái lòng đỏ trứng vàng óng pha với pate tủy chấm rã vào rã vào miệng cực mê.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(63, 12, 1, 'Làm nhân gà: Phi chút tỏi với dầu, đổ thịt gà xay vào xào lăn. Khi gà tiết nước và chuyển màu, rắc bột gia vị Taco cùng chút xíu nước. Đun lửa nhỏ đến khi sốt rút keo lại bao phủ miễng gà khô khô thơm thơm.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(64, 12, 2, 'Làm sốt Salsa (Pico de Gallo): Trộn đều cà chua băm, hành tây đỏ băm, rau mùi, một xíu muối, tiêu đỏ và vắt đẫm nước cốt 1 quả chanh xanh. Xóc đều để tủ lạnh dịu vị.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(65, 12, 3, 'Làm Tacos: Lấy bột Tacos nướng giòn trên chảo hoặc lò. Lấy vỏ gập hình chiếc móng ngựa.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(66, 12, 4, 'Gắn nhân: Xúc lớp gà Mexico bỏ vào ruột Taco đầu tiên, rồi rải bơ xắt hạt lựu dẻo mịn bọc lên.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(67, 12, 5, 'Múc dồi dào thìa salsa cà chua trải phủ kín phần kem dư thừa. Rắc rau mùi xanh thơm tươi cuối cùng. Ăn kèm sốt chua hoặc tabasco rụm!', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(68, 13, 1, 'Sơ chế ếch ướp với chút xíu mắm, hạt tiêu đen và một nửa nước cốt nghệ tươi trong 15p.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(69, 13, 2, 'Chuối xanh ngâm nước dấm loãng cho k thâm gỉ. Rửa tráng đem luộc qua hoặc chiên chiên vàng giòn ở mặt tùy thích để dai vỏ.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(70, 13, 3, 'Bật chảo chiên đậu phụ xong cất góc, tiện tay rang cháy cạnh thịt ba rọi heo tươm ra chút mỡ béo bùi cho vào rổ.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(71, 13, 4, 'Dùng lại cái chảo phi thơm hành khô, trút thịt ếch xào lăn trên ngọn lửa bùng săn lại tươm dậy mùi thơm vàng nghệ.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(72, 13, 5, 'Cho tất cả thịt lợn, tôm đậu, hạt ếch, chuối thái miếng vào xào chung nồi. Đổ nước mẻ dầm chua hòa nhập đổ săm sắp.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(73, 13, 6, 'Hầm nhỏ lửa vung kĩ 15 phút. Nêm bột ngọt, nếm chua vừa đủ. Rưới cuối cùng tía tô lá lốt lên là tỏa khói sôi xừng xực múc ra bát canh bún.', NULL, '2026-05-15 14:21:27', '2026-05-15 14:21:27'),
(74, 14, 1, 'Cho thịt bò xay với 1/2 củ tỏi băm và 1 thìa hành tây băm nhỏ vào tô lớn. Trộn bằng tay cho đến khi hòa quyện hoàn toàn. Nặn hỗn hợp thịt thành từng miếng hình thuôn dài 1/2 inch; bạn nên có 12 đến 14 viên thịt.', NULL, '2026-05-15 14:27:29', '2026-05-15 14:27:29'),
(75, 14, 2, 'Đun nóng chảo lớn trên lửa vừa cao. Từng miếng chả màu nâu được cho vào chảo nóng cho đến khi giòn cả hai mặt và không còn màu hồng ở giữa, khoảng 10 phút. Đặt thịt viên sang một bên trong đĩa phục vụ có viền.', NULL, '2026-05-15 14:27:29', '2026-05-15 14:27:29'),
(76, 14, 3, 'Giảm nhiệt ở mức trung bình và khuấy hành tây xắt nhỏ còn lại vào chảo. Nêm muối và hạt tiêu. Nấu, khuấy liên tục cho đến khi hành tây mềm và chuyển sang màu trong, khoảng 5 phút. Khuấy tỏi còn lại và nấu trong 30 giây. Khuấy cà chua Roma, rau mùi tây khô và ras el hanout. Đổ nước vào. Nấu cho đến khi cà chua mềm, khoảng 5 phút.', NULL, '2026-05-15 14:27:29', '2026-05-15 14:27:29'),
(77, 14, 4, 'Đổ nước sốt cà chua lên thịt viên để thưởng thức.', NULL, '2026-05-15 14:27:29', '2026-05-15 14:27:29'),
(78, 15, 1, 'Chuẩn bị thịt trong chảo, thêm muối và hạt tiêu cho vừa ăn, đun đậu trên lửa vừa trong chảo, chiên hoặc nướng chuối chín như hướng dẫn trên bao bì và cắt cà chua thành khối nhỏ. Dự trữ các thành phần này cho đến khi đầy.', NULL, '2026-05-15 14:27:32', '2026-05-15 14:27:32'),
(79, 15, 2, 'Làm nóng lò nướng hoặc chảo trước và nướng arepa, đặt mỗi mặt một lần cho đến khi chúng có màu vàng nâu.', NULL, '2026-05-15 14:27:32', '2026-05-15 14:27:32'),
(80, 15, 3, 'Với sự trợ giúp của một con dao, mở nó bằng mép xuyên qua giữa, tạo khoảng trống để lấp đầy chuối chín, đậu, thịt và cà chua cắt nhỏ.', NULL, '2026-05-15 14:27:32', '2026-05-15 14:27:32'),
(81, 15, 4, 'Ăn kèm với một ít nước chấm pico de gallo hoặc guacamole.', NULL, '2026-05-15 14:27:32', '2026-05-15 14:27:32'),
(82, 16, 1, 'Nấu thịt: Cho sườn vào nồi cùng nước dùng hoặc nước và muối. Nấu trên lửa nhỏ trong khoảng 2 giờ cho đến khi mềm và dễ cắt nhỏ.', NULL, '2026-05-15 14:27:34', '2026-05-15 14:27:34'),
(83, 16, 2, 'Xé thịt: Sau khi chín, để ráo nước và xé thịt bằng hai chiếc nĩa.', NULL, '2026-05-15 14:27:34', '2026-05-15 14:27:34'),
(84, 16, 3, 'Sơ chế rau củ: Phi thơm hành tây, ớt chuông, tỏi băm nhỏ với một ít dầu. Thêm thì là, lá oregano, ớt bột và muối. Khuấy thịt và nấu trong vài phút cho đến khi hương vị được kết hợp tốt.', NULL, '2026-05-15 14:27:34', '2026-05-15 14:27:34'),
(85, 16, 4, 'Làm bột: Trong một cái bát, trộn bột ngô với nước ấm và muối cho đến khi tạo thành một khối bột mềm. Hãy để nó nghỉ ngơi trong 5 phút.', NULL, '2026-05-15 14:27:34', '2026-05-15 14:27:34'),
(86, 16, 5, 'Tạo hình bánh arepas: Chia bột thành 6 phần, vo thành những quả bóng và dẹt thành những đĩa dày.', NULL, '2026-05-15 14:27:34', '2026-05-15 14:27:34'),
(87, 16, 6, 'Nấu: Nấu bánh arepas trên vỉ nướng hoặc chảo trên lửa vừa trong 2–3 phút mỗi mặt cho đến khi chín vàng. Sau đó, bạn có thể nướng chúng trong vài phút nếu bạn thích chúng giòn hơn.', NULL, '2026-05-15 14:27:34', '2026-05-15 14:27:34'),
(88, 16, 7, 'Phần nhân: Cắt miếng arepas ở một bên, cho thịt bò băm nóng vào và phủ phô mai bào lên trên.', NULL, '2026-05-15 14:27:34', '2026-05-15 14:27:34'),
(89, 17, 1, 'Chuẩn bị lửa: Đốt củi trong vỉ nướng của bạn và để lửa cháy thành than.', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(90, 17, 2, 'Nêm thịt: Ướp muối thật kỹ vào miếng thịt bò.', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(91, 17, 3, 'Nướng thịt: Đặt thịt bò lên vỉ nướng, bắt đầu từ những miếng thịt dày nhất, cách xa than nhất. Thêm chorizo ​​và morcilla sau khi thịt bò đã nấu được một lúc.', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(92, 17, 4, 'Nấu chín tới mức hoàn hảo: Nấu thịt, thỉnh thoảng lật miếng thịt cho đến khi đạt độ chín mong muốn. Thông thường, sườn có thể mất tới 2 giờ; vết cắt mỏng hơn sẽ nấu nhanh hơn.', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(93, 17, 5, 'Nghỉ ngơi và phục vụ: Để thịt nghỉ khoảng 10 phút trước khi cắt. Ăn kèm với sốt chimichurri và rau củ nướng.', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(94, 17, 6, 'Lời khuyên chuyên nghiệp:', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(95, 17, 7, 'Sử dụng hỗn hợp gỗ và than để có nguồn nhiệt ổn định. Gỗ thêm hương vị, trong khi than duy trì nhiệt độ.', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(96, 17, 8, 'Nêm thịt ngay trước khi nướng để đảm bảo thịt giữ được độ ẩm và hương vị.', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(97, 17, 9, 'Đề xuất phục vụ:', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(98, 17, 10, 'Ăn kèm với sốt chimichurri, salad cà chua tươi và bánh mì giòn. Kết hợp với rượu vang Malbec mạnh mẽ để bổ sung hương vị đậm đà của thịt.', NULL, '2026-05-15 14:27:37', '2026-05-15 14:27:37'),
(100, 18, 1, 'Làm bánh mì kẹp thịt: Cho thịt vào tô và rắc lên trên 1 thìa cà phê muối và một ít tiêu đen xay. Dùng tay ướt để trộn gia vị. Dùng tay chia làm bốn phần và tạo hình bánh mì kẹp thịt. (Nó có thể được đông lạnh ở giai đoạn này.)', NULL, '2026-05-15 14:27:41', '2026-05-16 12:35:33'),
(102, 18, 2, 'Phân loại nguyên liệu: Cắt củ cải đường và chia bánh mì naan.', NULL, '2026-05-15 14:27:41', '2026-05-16 12:35:33'),
(104, 18, 3, 'Nướng bánh naan: Làm nóng chảo nướng hoặc vỉ nướng. Nướng naan ở cả hai mặt cho đến khi nướng nhẹ và đặt sang một bên. Cho bánh mì kẹp thịt vào vỉ nướng hoặc thịt nướng và nướng trong 2-3 phút, sau đó lật mặt và nướng mặt còn lại thêm 2-3 phút.', NULL, '2026-05-15 14:27:41', '2026-05-16 12:35:33'),
(106, 18, 4, 'Bày biện món ăn: Đặt nửa miếng naan nướng lên mỗi đĩa phục vụ và đặt một đống tên lửa lên mỗi đĩa. Phủ lên trên một chiếc bánh mì kẹp thịt, sau đó là vài lát củ cải đường và một ít kem chua. Rắc muối và hạt tiêu đen mới xay và dùng ngay với món salad xanh lớn và khoai tây chiên. Một ly rượu vang đỏ cũng không sao cả.', NULL, '2026-05-15 14:27:41', '2026-05-16 12:35:33'),
(107, 19, 1, 'Ướp thịt bò:', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(108, 19, 2, 'Khuấy đều các nguyên liệu ướp thịt bò (1 thìa cà phê nước tương, 1 thìa cà phê rượu gạo Trung Quốc, 1/2 thìa cà phê bột bắp, 1/8 thìa cà phê tiêu đen) trong tô vừa.', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(109, 19, 3, 'Thêm các lát thịt bò và khuấy cho đến khi phủ đều. Để yên trong 10 phút.', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(110, 19, 4, 'Chuẩn bị nước sốt:', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(111, 19, 5, 'Khuấy đều các nguyên liệu làm nước sốt (2 thìa dầu hào, 1 thìa cà phê rượu gạo Trung Quốc, 1 thìa cà phê nước tương, 1/4 chén nước luộc gà) trong một tô nhỏ. Đặt sang một bên.', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(112, 19, 6, 'Chần hoặc hấp bông cải xanh:', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(113, 19, 7, 'Đun sôi một nồi nước. Thêm bông cải xanh và nấu cho đến khi mềm giòn, khoảng 2 phút. Xả thật kỹ.', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(114, 19, 8, 'Xào thịt bò:', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(115, 19, 9, 'Đun nóng chảo rán lớn hoặc chảo trên lửa cao cho đến khi một hạt nước sủi bọt và bay hơi ngay lập tức khi tiếp xúc. Thêm dầu ăn và xoáy đều.', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(116, 19, 10, 'Thêm thịt bò vào và ngay lập tức dàn đều khắp bề mặt chảo hoặc chảo thành một lớp (tốt nhất là không chạm vào).', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(117, 19, 11, 'Để thịt bò chiên yên trong 1 phút. Lật các lát thịt bò lên, cho tỏi vào chảo rồi chiên thêm 30 giây đến 1 phút cho đến khi không còn màu hồng.', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(118, 19, 12, 'Thêm nước sốt, bột bắp và bông cải xanh:', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(119, 19, 13, 'Đổ nước sốt và hỗn hợp bột bắp vào (1 thìa cà phê bột bắp hòa tan trong 1 thìa nước). Khuấy cho đến khi nước sốt sôi và đặc lại, khoảng 30 giây. Khuấy bông cải xanh.', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(120, 19, 14, 'Ăn ngay, với cơm trắng hoặc ăn riêng.', NULL, '2026-05-15 14:27:44', '2026-05-15 14:27:44'),
(121, 20, 1, 'Làm nóng lò ở mức 150C/300F/Gas 2.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(122, 20, 2, 'Cho thịt bò và bột mì vào tô cùng với một ít muối và tiêu đen.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(123, 20, 3, 'Đun một nồi lớn cho đến khi nóng, cho một nửa dầu hạt cải và lượng thịt bò vừa đủ ngập đáy nồi.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(124, 20, 4, 'Chiên cho đến khi chín vàng ở mỗi mặt, sau đó lấy ra và đặt sang một bên. Lặp lại với dầu và thịt bò còn lại.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(125, 20, 5, 'Cho thịt bò vào chảo, thêm rượu và nấu cho đến khi lượng chất lỏng giảm đi một nửa, sau đó thêm nước kho, hành tây, cà rốt, húng tây và mù tạt, nêm muối và hạt tiêu.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(126, 20, 6, 'Đậy nắp và cho vào lò nướng trong hai giờ.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(127, 20, 7, 'Lấy ra khỏi lò, kiểm tra gia vị và để nguội. Loại bỏ húng tây.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(128, 20, 8, 'Khi thịt bò nguội và bạn đã sẵn sàng gói bánh, hãy làm nóng lò nướng ở nhiệt độ 200C/400F/Gas 6.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(129, 20, 9, 'Chuyển thịt bò sang đĩa bánh nướng, phết lòng đỏ trứng đã đánh bông lên vành và phủ bánh ngọt lên trên. Quét thêm trứng đã đánh lên trên mặt bánh.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(130, 20, 10, 'Cắt bớt phần bánh sao cho phần thừa vừa đủ để gấp mép, sau đó cho vào lò nướng và nướng trong 30 phút hoặc cho đến khi bánh có màu nâu vàng và chín đều.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(131, 20, 11, 'Đối với đậu xanh, đun sôi một nồi nước muối, cho đậu vào nấu khoảng 4-5 phút hoặc cho đến khi đậu mềm.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(132, 20, 12, 'Để ráo nước và trộn với bơ, sau đó nêm hạt tiêu đen.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(133, 20, 13, 'Để phục vụ, đặt một thìa bánh lớn lên mỗi đĩa cùng với một ít đậu xanh bên cạnh.', NULL, '2026-05-15 14:27:46', '2026-05-15 14:27:46'),
(134, 21, 1, 'Nêm các khối thịt bò với muối và hạt tiêu đen. Đun nóng một thìa dầu trong chảo rồi cho thịt vào chiên ở lửa lớn. Thực hiện việc này thành ba mẻ để chảo không bị quá đông, chuyển thịt sang đĩa thịt hầm lớn chống cháy sau khi thịt đã chín vàng toàn bộ. Thêm dầu nếu chảo có vẻ khô.', NULL, '2026-05-15 14:27:48', '2026-05-15 14:27:48'),
(135, 21, 2, 'Trong cùng một chảo, thêm một thìa dầu khác và nấu hẹ trong 4-5 phút, sau đó thêm tỏi và chiên trong 30 giây. Thêm thịt xông khói và chiên cho đến khi hơi chín. Chuyển hỗn hợp hành tây và thịt xông khói vào đĩa thịt hầm và thêm các loại thảo mộc.', NULL, '2026-05-15 14:27:48', '2026-05-15 14:27:48'),
(136, 21, 3, 'Làm nóng lò ở 180C/350F/Gas 4.', NULL, '2026-05-15 14:27:48', '2026-05-15 14:27:48'),
(137, 21, 4, 'Đổ bia đen vào chảo rán và đun sôi, khuấy đều để nhấc những phần màu nâu còn dính ra khỏi đáy chảo. Đổ bia đen lên thịt bò trong đĩa thịt hầm và thêm nước kho. Đậy nắp nồi và cho vào lò nướng trong 1½-2 giờ hoặc cho đến khi thịt bò mềm và nước sốt giảm bớt.', NULL, '2026-05-15 14:27:48', '2026-05-15 14:27:48'),
(138, 21, 5, 'Hớt bỏ lớp mỡ trên bề mặt, nếm thử và thêm muối, tiêu nếu cần, sau đó cho bột ngô vào khuấy đều. Đặt đĩa thịt hầm lên bếp - đừng quên đĩa còn nóng - và đun nhỏ lửa trong 1-2 phút, khuấy đều cho đến khi đặc lại. Để nguội.', NULL, '2026-05-15 14:27:48', '2026-05-15 14:27:48'),
(139, 21, 6, 'Tăng lò nướng lên 200C/400F/Gas 6. Để làm bánh ngọt, cho bột mì và muối vào một cái tô thật lớn. Nghiền bơ và trộn vào bột thành ba mẻ. Dần dần thêm 325ml/11fl oz nước lạnh – bạn có thể không cần hết – và khuấy bằng dao có lưỡi tròn cho đến khi hỗn hợp vừa quyện lại với nhau. Nhào nhẹ bánh ngọt thành một quả bóng trên bề mặt đã phủ bột mì nhẹ và dành 250g/9oz cho nắp bánh.', NULL, '2026-05-15 14:27:48', '2026-05-15 14:27:48'),
(140, 21, 7, 'Cán phần còn lại của chiếc bánh ngọt cho đến khi lớn hơn đĩa bạn đang dùng khoảng 2 cm/¾ inch. Xếp bánh ngọt lên đĩa rồi xếp nhân vào, nhét hàu vào. Quét mép bánh bằng trứng đã đánh bông.', NULL, '2026-05-15 14:27:48', '2026-05-15 14:27:48'),
(141, 21, 8, 'Cuộn phần bánh ngọt còn lại cho đến khi lớn hơn đĩa của bạn một chút và nhẹ nhàng nhấc phần nhân lên, ấn chặt các mép để bịt kín, sau đó dùng dao sắc cắt bớt. Quét một lớp trứng đánh lên để tráng men. Đặt đĩa lên khay nướng và nướng trong 25-30 phút hoặc cho đến khi bánh có màu nâu vàng và phần nhân sủi bọt.', NULL, '2026-05-15 14:27:48', '2026-05-15 14:27:48'),
(142, 22, 1, '0. Trộn thịt bò, hạt tiêu xay, nước tương, giấm, lá nguyệt quế khô, chanh và sốt cà chua. Trộn đều. Ướp thịt bò ít nhất 30 phút.', NULL, '2026-05-15 14:27:51', '2026-05-15 14:27:51'),
(143, 22, 2, '1. Cho thịt bò đã ướp vào nồi nấu cùng với phần nước xốt còn lại. Thêm nước. Hãy đun sôi.', NULL, '2026-05-15 14:27:51', '2026-05-15 14:27:51'),
(144, 22, 3, '2. Thêm viên bò Knorr vào. Khuấy. Đậy nắp nồi và nấu trong 40 phút ở nhiệt độ thấp.', NULL, '2026-05-15 14:27:51', '2026-05-15 14:27:51'),
(145, 22, 4, '3. Lật thịt bò lại. Thêm bột cà chua. Tiếp tục nấu cho đến khi thịt bò mềm. Đặt sang một bên.', NULL, '2026-05-15 14:27:51', '2026-05-15 14:27:51'),
(146, 22, 5, '4. Đun nóng dầu trong chảo. Chiên khoai tây cho đến khi có màu nâu. Lật lại và tiếp tục chiên mặt đối diện. Lấy ra khỏi chảo và đặt lên đĩa sạch. Làm tương tự với cà rốt.', NULL, '2026-05-15 14:27:51', '2026-05-15 14:27:51'),
(147, 22, 6, '5. Tiết kiệm 3 thìa dầu ăn trong chảo chiên khoai tây. Xào hành và tỏi cho đến khi hành mềm.', NULL, '2026-05-15 14:27:51', '2026-05-15 14:27:51'),
(148, 22, 7, '6. Đổ nước sốt từ thịt bò hầm vào. Hãy đun sôi. Thêm thịt bò. Nấu trong 2 phút.', NULL, '2026-05-15 14:27:51', '2026-05-15 14:27:51'),
(149, 22, 8, '7. Thêm bơ vào và đun chảy. Tiếp tục nấu cho đến khi nước sốt giảm còn một nửa.', NULL, '2026-05-15 14:27:51', '2026-05-15 14:27:51'),
(150, 23, 1, 'Thành phần bổ sung: mayonnaise, siracha', NULL, '2026-05-15 14:27:54', '2026-05-15 14:27:54'),
(151, 23, 2, 'Đặt gạo vào một cái rây mịn và rửa sạch cho đến khi nước trong. Cho vào nồi nhỏ cùng 1 cốc nước (2 cốc cho 4 phần ăn) và một chút muối. Đun sôi, sau đó đậy nắp và giảm nhiệt xuống thấp. Nấu cho đến khi gạo mềm, 15 phút. Đậy kín lửa trong ít nhất 10 phút hoặc cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:27:54', '2026-05-15 14:27:54'),
(152, 23, 3, 'Trong khi đó, rửa sạch và lau khô tất cả sản phẩm. Bóc vỏ và băm nhuyễn tỏi. Vỏ và quý chanh (cho 4 phần ăn, vỏ 1 quả chanh và cả hai phần tư). Cắt và cắt đôi quả dưa chuột theo chiều dọc; thái mỏng theo chiều ngang thành hình bán nguyệt. Cắt đôi, gọt vỏ và thái hạt lựu vừa. Cắt nhỏ, gọt vỏ và xay cà rốt.', NULL, '2026-05-15 14:27:54', '2026-05-15 14:27:54'),
(153, 23, 4, 'Trong một tô vừa, trộn dưa chuột, nước ép từ nửa quả chanh, ¼ thìa cà phê đường (½ thìa cho 4 phần ăn) và một chút muối. Trong một bát nhỏ, trộn sốt mayonnaise, một nhúm tỏi, vắt nước cốt chanh và bao nhiêu sriracha tùy thích. Nêm muối và hạt tiêu.', NULL, '2026-05-15 14:27:54', '2026-05-15 14:27:54'),
(154, 23, 5, 'Đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm hành tây và nấu, khuấy đều cho đến khi mềm trong 4-5 phút. Thêm thịt bò, tỏi còn lại và 2 muỗng cà phê đường (4 muỗng cà phê cho 4 phần ăn). Nấu, chia thịt thành từng miếng cho đến khi thịt bò chín vàng, khoảng 4-5 phút. Khuấy nước tương. Tắt nhiệt; nếm và nêm muối và hạt tiêu.', NULL, '2026-05-15 14:27:54', '2026-05-15 14:27:54'),
(155, 23, 6, 'Xới cơm bằng nĩa; khuấy vỏ chanh và 1 muỗng canh bơ. Chia cơm vào các bát. Xếp thịt bò, cà rốt bào sợi và dưa chuột muối lên trên. Top với một vắt nước cốt chanh. Rưới thêm sriracha mayo.', NULL, '2026-05-15 14:27:54', '2026-05-15 14:27:54'),
(156, 24, 1, 'Làm nóng chảo lớn và thêm 1 muỗng canh mỡ ngỗng. Nêm thịt bò và chiên cho đến khi vàng nâu, khoảng 3-5 phút, sau đó lật mặt lại và chiên mặt còn lại cho đến khi thịt chín vàng đều, thêm mỡ nếu cần. Làm điều này thành 2-3 mẻ, chuyển thịt vào một cái rây đặt trên bát khi đã chín vàng.', NULL, '2026-05-15 14:27:57', '2026-05-15 14:27:57'),
(157, 24, 2, 'Trong cùng một chảo, chiên thịt xông khói, hẹ tây hoặc hành tây trân châu, nấm, tỏi và bó hoa trang trí cho đến khi có màu nâu nhạt. Cho cà chua xay nhuyễn vào và nấu trong vài phút, khuấy đều hỗn hợp. Điều này làm phong phú thêm rượu bourguignon và tạo thành nền tảng tuyệt vời cho món hầm. Sau đó cho thịt bò và phần nước đã ráo nước vào chảo và đảo đều.', NULL, '2026-05-15 14:27:57', '2026-05-15 14:27:57'),
(158, 24, 3, 'Đổ rượu và khoảng 100ml nước vào để thịt nổi lên nhưng không bị ngập hoàn toàn. Đun sôi và dùng thìa cạo phần nước nấu caramen khỏi đáy chảo - điều này sẽ giúp món hầm có thêm hương vị.', NULL, '2026-05-15 14:27:57', '2026-05-15 14:27:57'),
(159, 24, 4, 'Làm nóng lò nướng ở nhiệt độ 150C/quạt 130C/gas 2. Làm vỏ bánh: xé một tờ giấy bạc hình vuông lớn hơn soong một chút, xếp vào chảo sao cho phủ kín mặt trên của món hầm và cắt bỏ phần giấy bạc thừa. Sau đó nấu trong 3 giờ. Nếu nước sốt có vẻ chảy nước, hãy dùng thìa có rãnh loại bỏ thịt bò và rau rồi đặt sang một bên. Nấu nước sốt trên lửa lớn trong vài phút cho đến khi nước sốt đặc lại một chút, sau đó cho thịt bò và rau vào chảo.', NULL, '2026-05-15 14:27:57', '2026-05-15 14:27:57'),
(160, 24, 5, 'Để làm món củ cải nghiền, hãy gọt vỏ củ cải và cắt thành khối vuông. Đun nóng dầu ô liu trong chảo rán lớn. Cho củ cải vào và chiên trong 5 phút cho đến khi chuyển sang màu vàng. Nêm kỹ với muối và hạt tiêu. Khuấy vỏ hương thảo, húng tây, nguyệt quế và bạch đậu khấu, sau đó đổ hơn 200ml nước, đủ gần ngập củ cải. Vặn lửa nhỏ, đậy nắp một phần chảo và để sôi trong 25-30 phút.', NULL, '2026-05-15 14:27:57', '2026-05-15 14:27:57'),
(161, 24, 6, 'Sau 25-30 phút, củ cải sẽ mềm và phần lớn nước sẽ bay hơi hết. Xả hết nước còn lại, sau đó loại bỏ các nhánh thảo mộc, vỏ nguyệt quế và bạch đậu khấu. Nghiền nhẹ bằng máy nghiền khoai tây, sau đó kết thúc với một chút dầu ô liu và nêm nếm cho vừa ăn. Múc thịt bò bourguignon vào bát phục vụ và đặt một thìa lớn củ cải nghiền lên trên. Trang trí bằng một trong những chiếc lá nguyệt quế nếu bạn thích.', NULL, '2026-05-15 14:27:57', '2026-05-15 14:27:57'),
(162, 25, 1, '1 Chuẩn bị miếng ức để nấu: Ở một bên của miếng ức phải có một lớp mỡ tùy thích. Nếu có bất kỳ khối mỡ lớn nào, hãy cắt chúng ra và loại bỏ chúng. Những miếng mỡ lớn sẽ không thể thoát ra ngoài hoàn toàn.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(163, 25, 2, 'Dùng dao sắc vạch mỡ thành các đường song song, cách nhau khoảng 3/4 inch. Cắt qua mỡ chứ không phải thịt bò. Lặp lại theo hướng ngược lại để tạo thành một đường chéo.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(164, 25, 3, 'Muối kỹ và để yên ở nhiệt độ phòng trong 30 phút.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(165, 25, 4, '2 Áp chảo thịt ức: Bạn sẽ cần một chiếc nồi có đáy dày, chịu nhiệt bằng lò nướng có nắp đậy hoặc lò nướng kiểu Hà Lan, vừa đủ rộng để nướng thịt ức với một khoảng trống nhỏ cho hành tây.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(166, 25, 5, 'Vỗ nhẹ cho ức ức khô rồi đặt mặt có mỡ xuống dưới vào nồi rồi đặt trên lửa vừa cao. Nấu trong 5-8 phút, đun nhỏ lửa cho đến khi mặt mỡ có màu nâu đẹp mắt. (Nếu món nướng có vẻ chín quá nhanh, hãy giảm nhiệt xuống mức trung bình. Bạn muốn có tiếng xèo xèo đều đặn chứ không phải tiếng cháy dữ dội.)', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(167, 25, 6, 'Lật miếng ức lại và nấu thêm vài phút nữa cho mặt còn lại chín vàng.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(168, 25, 7, '3 Xào hành và tỏi: Khi ức đã chín vàng thì vớt ra khỏi nồi và đặt sang một bên. Trong nồi nên có vài thìa mỡ, nếu không thì thêm một ít dầu ô liu.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(169, 25, 8, 'Thêm hành tây xắt nhỏ và tăng nhiệt lên cao. Rắc một ít muối lên hành tây. Xào, khuấy thường xuyên cho đến khi hành tây có màu nâu nhạt, khoảng 5-8 phút. Khuấy tỏi và nấu thêm 1-2 phút nữa.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(170, 25, 9, '4 Cho ức vào nồi, thêm rau thơm, kho, đun nhỏ lửa, đậy nắp, nấu trong lò: Làm nóng lò ở nhiệt độ 300°F. Dùng dây nhà bếp buộc lá nguyệt quế, hương thảo và húng tây lại với nhau.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(171, 25, 10, 'Chuyển hành và tỏi sang các cạnh của nồi và nhét thịt ức vào bên trong. Thêm nước luộc thịt bò và các loại rau thơm buộc lại. Đun sôi nước kho trên bếp.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(172, 25, 11, 'Đậy nắp nồi, đặt nồi vào lò nướng ở nhiệt độ 300°F và nấu trong 3 giờ. Cẩn thận lật miếng ức mỗi giờ để nó chín đều.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(173, 25, 12, '5 Thêm cà rốt, tiếp tục nấu: Sau 3 giờ, thêm cà rốt. Đậy nắp nồi và nấu thêm 1 giờ nữa hoặc cho đến khi cà rốt chín và thịt ức mềm ra.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(174, 25, 13, '6 Lấy ức ra thớt, lều có lót giấy bạc: Khi ức đã mềm, lấy nồi ra khỏi lò và lấy ức lên thớt. Che nó bằng giấy bạc. Kéo ra và loại bỏ các loại thảo mộc.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(175, 25, 14, '7 Làm nước sốt (tùy chọn): Lúc này bạn có hai lựa chọn. Bạn có thể dùng nguyên hoặc có thể làm nước sốt với nước xốt và một ít hành tây. Nếu bạn phục vụ như cũ, hãy bỏ qua bước này.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(176, 25, 15, 'Để làm nước sốt, loại bỏ cà rốt và một nửa số hành tây, đặt sang một bên và bọc chúng bằng giấy bạc. Đổ các nguyên liệu còn lại vào nồi vào máy xay sinh tố, xay nhuyễn cho đến khi mịn. Nếu muốn, hãy thêm 1 thìa mù tạt vào hỗn hợp. Cho vào nồi nhỏ và giữ ấm.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(177, 25, 16, '8 Cắt thịt theo thớ: Chú ý các đường thớ thịt của miếng thịt quay. Đây là \"hạt\" của thịt. Cắt thịt vuông góc với những đường này hoặc ngang thớ (cắt theo cách này giúp thịt mềm hơn), thành các lát từ 1/4 inch đến 1/2 inch.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(178, 25, 17, 'Ăn kèm hành tây, cà rốt và nước sốt. Ăn kèm với khoai tây nghiền, nướng hoặc luộc, mì trứng hoặc polenta.', NULL, '2026-05-15 14:28:01', '2026-05-15 14:28:01'),
(179, 26, 1, '0. Đun nóng dầu trong nồi nấu. Xào hành và tỏi cho đến khi hành mềm', NULL, '2026-05-15 14:28:04', '2026-05-15 14:28:04'),
(180, 26, 2, '1. Thêm thịt bò. Xào cho đến khi phần bên ngoài chuyển sang màu nâu nhạt.', NULL, '2026-05-15 14:28:04', '2026-05-15 14:28:04'),
(181, 26, 3, '2. Thêm nước tương. Đổ nước sốt cà chua và nước. Hãy đun sôi.', NULL, '2026-05-15 14:28:04', '2026-05-15 14:28:04'),
(182, 26, 4, '3. Thêm viên bò Knorr vào. Đậy nắp nồi áp suất. Nấu trong 30 phút.', NULL, '2026-05-15 14:28:04', '2026-05-15 14:28:04'),
(183, 26, 5, '4. Chiên cà rốt và khoai tây cho đến khi chín vàng. Đặt sang một bên.', NULL, '2026-05-15 14:28:04', '2026-05-15 14:28:04'),
(184, 26, 6, '5. Thêm ớt, phết gan và bơ đậu phộng. Khuấy.', NULL, '2026-05-15 14:28:04', '2026-05-15 14:28:04'),
(185, 26, 7, '6. Thêm ớt chuông, khoai tây chiên và cà rốt. Đậy nắp nồi. Tiếp tục nấu trong 5 đến 7 phút.', NULL, '2026-05-15 14:28:04', '2026-05-15 14:28:04'),
(186, 26, 8, '7. Nêm muối và tiêu đen xay. Phục vụ.', NULL, '2026-05-15 14:28:04', '2026-05-15 14:28:04'),
(187, 27, 1, 'Làm nóng lò ở 180C/350F/Gas 4.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(188, 27, 2, 'Đối với món thịt bò hầm, đun nóng dầu và bơ trong nồi chịu nhiệt rồi chiên thịt bò cho đến khi chín vàng đều các mặt.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(189, 27, 3, 'Rắc bột lên và nấu thêm 2-3 phút nữa.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(190, 27, 4, 'Thêm tỏi và tất cả các loại rau vào xào trong 1-2 phút.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(191, 27, 5, 'Khuấy rượu, nước kho và các loại thảo mộc, sau đó thêm sốt Worcestershire và giấm balsamic để nếm thử. Nêm muối và hạt tiêu đen mới xay.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(192, 27, 6, 'Đậy nắp, chuyển vào lò nướng và nấu trong khoảng hai giờ hoặc cho đến khi thịt mềm.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(193, 27, 7, 'Đối với phần bánh bao, rây bột mì, bột nở và muối vào tô.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(194, 27, 8, 'Thêm mỡ và đủ nước để tạo thành một khối bột dày.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(195, 27, 9, 'Dùng bàn tay tẩm bột mì vo từng thìa bột thành những viên tròn nhỏ.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(196, 27, 10, 'Sau hai giờ, mở nắp ra khỏi món hầm và đặt các viên bi lên trên món hầm. Đậy nắp lại, cho vào lò nướng thêm 20 phút nữa hoặc cho đến khi bánh bao phồng lên và mềm. (Nếu bạn thích bánh bao có mặt vàng ở trên, hãy mở nắp khi cho vào lò nướng.)', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(197, 27, 11, 'Để phục vụ, đặt một thìa khoai tây nghiền lên mỗi đĩa trong số bốn đĩa phục vụ và đặt món hầm và bánh bao lên trên. Rắc rau mùi tây cắt nhỏ.', NULL, '2026-05-15 14:28:06', '2026-05-15 14:28:06'),
(198, 28, 1, 'Đối với bột, đặt mỡ lợn, nước ấm và muối vào tô nhào lớn và khuấy đều. Thêm bột mì và lá oregano rồi nhào trong 5 phút bằng tay hoặc bằng chức năng nhào của máy. Để yên trong ít nhất nửa giờ hoặc qua đêm trong tủ lạnh.', NULL, '2026-05-15 14:28:09', '2026-05-15 14:28:09'),
(199, 28, 2, 'Để làm nhân, cho cà chua vào nước sôi khoảng 30 giây, sau đó làm nguội bằng nước lạnh, gọt vỏ rồi cắt thành khối vuông. Nhấn tỏi qua máy ép tỏi, cắt hành tây thành khối. Đun nhỏ tỏi và hành tây trong một ít dầu ô liu cho đến khi trong suốt. Vớt hành, tỏi ra rồi đun chín thịt ở nhiệt độ cao từ mọi phía. Nêm tất cả các loại thảo mộc và thêm hành, tỏi và cà chua. Để sôi trong vài phút, thêm muối, hạt tiêu và gia vị bổ sung cho vừa ăn. Bạn có thể chuẩn bị thịt từ tối hôm trước, bảo quản trong tủ lạnh nếu làm như vậy. Luộc trứng rồi cắt thành khối vuông rồi trộn với thịt đã chuẩn bị.', NULL, '2026-05-15 14:28:09', '2026-05-15 14:28:09'),
(200, 28, 3, 'Cắt bột làm đôi và cán mỏng một nửa trên bề mặt đã rắc bột mì. Cắt các hình tròn có đường kính khoảng 12-15 cm. Của tôi có đường kính 12,5 cm. Đặt khoảng 2-4 muỗng cà phê nhân vào một hình tròn, cho một chút nước xung quanh các cạnh và gấp nửa còn lại lại để bạn có được một nửa mặt trăng. Hãy chắc chắn để bịt kín các cạnh bằng một cái nĩa. Lặp lại cho đến khi không còn bột và nhân.', NULL, '2026-05-15 14:28:09', '2026-05-15 14:28:09'),
(201, 28, 4, 'Trong khi đó làm nóng lò trước ở nhiệt độ 200 độ C. Quét nước rửa trứng lên bánh empanadas và nướng khoảng 8 chiếc bánh empanadas trên khay nướng có lót giấy da trong khoảng 25 phút hoặc cho đến khi vàng. Ăn ấm với sốt chimichurri.', NULL, '2026-05-15 14:28:09', '2026-05-15 14:28:09'),
(202, 29, 1, 'BƯỚC 1 – Ướp THỊT BÒ', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(203, 29, 2, 'Cho thịt bò, muối, 1 nhúm tiêu trắng, 1 thìa dầu mè, 1/2 quả trứng, tinh bột ngô, 1 thìa dầu vào trộn đều.', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(204, 29, 3, 'BƯỚC 2 - LUÔN MÌ', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(205, 29, 4, 'Trong nồi 6 qt, cho mì vào nước sôi cho đến khi ngập mì và đun ở lửa lớn trong 10 giây. Sau khi luộc xong mì, vớt ra để nguội bằng nước lạnh.', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(206, 29, 5, 'BƯỚC 3 - Xào', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(207, 29, 6, 'Thêm 2 muỗng canh dầu, thịt bò vào nấu trên lửa lớn cho đến khi thịt bò chín vừa.', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(208, 29, 7, 'Đặt thịt bò nấu chín sang một bên', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(209, 29, 8, 'Cho 2 thìa canh dầu, hành tây, tỏi băm, gừng băm, giá đỗ, nấm, đậu Hà Lan và 1,5 cốc nước vào hoặc cho đến khi rau ngập trong nước.', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(210, 29, 9, 'Thêm mì vào chảo', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(211, 29, 10, 'Để làm nước sốt, thêm dầu hào, 1 nhúm tiêu trắng, 1 thìa dầu mè, đường và 1 thìa nước tương.', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(212, 29, 11, 'Tiếp theo cho thịt bò vào chảo xào chín', NULL, '2026-05-15 14:28:11', '2026-05-15 14:28:11'),
(213, 30, 1, '1. Thịt bò rửa sạch và cắt thành từng miếng lớn. Nêm nhẹ với muối và bột nghệ.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(214, 30, 2, '2. Đun nóng ghee/dầu trong nồi lớn. Thêm hành tây thái lát và xào cho đến khi vàng nhạt.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(215, 30, 3, '3. Thêm tỏi, ớt xanh và cà chua; nấu cho đến khi mềm.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(216, 30, 4, '4. Thêm hỗn hợp gia vị mandi: rau mùi, thì là, tiêu đen, quế, bạch đậu khấu, đinh hương và lá nguyệt quế.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(217, 30, 5, '5. Thêm miếng thịt bò vào và đảo đều trên lửa vừa cho đến khi thịt thấm đều gia vị.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(218, 30, 6, '6. Đổ nước hoặc nước luộc thịt bò vào. Đậy nắp và đun nhỏ lửa cho đến khi thịt bò mềm (khoảng 1,5–2 giờ tùy theo vết cắt).', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(219, 30, 7, '7. Cẩn thận lấy thịt bò ra và đặt sang một bên. Lọc và đo nước dùng.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(220, 30, 8, '8. Thêm gạo basmati đã vo sạch, ngâm vào nước dùng (thường 1 chén gạo = 1,5–2 chén chất lỏng). Điều chỉnh gia vị và đun sôi.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(221, 30, 9, '9. Giảm nhiệt, đậy nắp và nấu cơm cho đến khi mềm.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(222, 30, 10, '10. Đặt các miếng thịt bò lên cơm và hấp ở lửa nhỏ trong 10 phút để hương vị hòa quyện.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(223, 30, 11, '11. Tùy chọn: Để có vị khói, đặt một cục than nóng nhỏ lên giấy bạc trong nồi, thêm 1 thìa cà phê bơ/dầu, đậy nắp ngay trong 5 phút. Loại bỏ than trước khi phục vụ.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(224, 30, 12, '12. Xới cơm và dùng mandi thịt bò với salad hoặc tương ớt.', NULL, '2026-05-15 14:28:14', '2026-05-15 14:28:14'),
(225, 31, 1, '0. Làm nước sốt thăn bò bằng cách trộn nước tương, giấm, gừng, tỏi, dầu mè, dầu ô liu, đường, muối và tiêu đen xay trong một tô lớn. Trộn đều.', NULL, '2026-05-15 14:28:19', '2026-05-15 14:28:19'),
(226, 31, 2, '1. Cho thăn bò thái miếng vào tô cùng với nước xốt thăn bò. Đảo nhẹ để thịt bò ngấm đều. Hãy để nó ở lại trong 1 giờ.', NULL, '2026-05-15 14:28:19', '2026-05-15 14:28:19'),
(227, 31, 3, '2. Dùng xiên tre hoặc kim loại để xiên thịt bò kebob bằng cách xiên rau và thăn bò đã ướp.', NULL, '2026-05-15 14:28:19', '2026-05-15 14:28:19'),
(228, 31, 4, '3. Làm nóng lò nướng và bắt đầu nướng thịt bò kebob trong 3 phút mỗi mặt. Điều này sẽ mang lại cho bạn một miếng thịt bò vừa, ngon ngọt và mềm ở bên trong. Hãy thêm thời gian nếu bạn muốn thịt bò chín kỹ nhưng sẽ kém mềm hơn.', NULL, '2026-05-15 14:28:19', '2026-05-15 14:28:19'),
(229, 31, 5, '4. Chuyển sang đĩa phục vụ. Ăn kèm cơm Saffron.', NULL, '2026-05-15 14:28:19', '2026-05-15 14:28:19'),
(230, 31, 6, '5. Chia sẻ và tận hưởng!', NULL, '2026-05-15 14:28:19', '2026-05-15 14:28:19'),
(232, 32, 1, 'Đổ nước luộc thịt bò cùng 500ml nước vào nồi lớn. Cho hành tây và gừng vào chảo rán ở nhiệt độ cao và nướng chín đều các mặt trong khoảng 3-5 phút (bạn cũng có thể làm điều này dưới vỉ nướng). Sau khi cháy, thêm vào thịt bò. Trong cùng một chảo, nướng các loại gia vị trong 2-3 phút và khi chúng bắt đầu có mùi thơm, hãy thêm chúng vào nước luộc thịt bò. Đun sôi nước kho, sau đó vặn nhỏ lửa và nấu trong 30 phút trước khi lọc.', NULL, '2026-05-15 14:28:21', '2026-05-16 12:35:33'),
(234, 32, 2, 'Trong khi đó, cắt mỡ từ miếng bít tết và bọc trong màng dính, sau đó cho vào tủ đá trong 15 phút - điều này sẽ giúp miếng bít tết của bạn thực sự dễ cắt! Cắt mỏng rồi dùng màng bọc thực phẩm bọc lại và cho vào tủ lạnh.', NULL, '2026-05-15 14:28:21', '2026-05-16 12:35:33'),
(236, 32, 3, 'Nếm thử nước luộc bò rồi dùng đường thốt nốt, nước mắm và đậu nành để nêm nếm. Nấu mì theo hướng dẫn trên bao bì và chia thành hai bát, đặt thịt bò thái lát lên trên mỗi bát. Đun sôi nước kho rồi đổ vào bát (nhiệt sẽ làm chín thịt bò). Xếp hành lá, lát ớt và rau thơm lên trên. Ăn kèm với chanh để vắt.', NULL, '2026-05-15 14:28:21', '2026-05-16 12:35:33'),
(237, 33, 1, 'Cắt nhỏ các thành phần gia vị rồi cho vào máy xay thực phẩm xay cho đến khi mịn.', NULL, '2026-05-15 14:28:25', '2026-05-15 14:28:25'),
(238, 33, 2, 'Đun nóng dầu trong nồi hầm, thêm bột gia vị, quế, đinh hương, hoa hồi, bạch đậu khấu vào xào cho đến khi có mùi thơm. Thêm thịt bò và sả giã nhuyễn vào đảo đều trong 1 phút. Thêm nước cốt dừa, nước me, nước vào đun trên lửa vừa, khuấy thường xuyên cho đến khi thịt gần chín. Thêm lá chanh kaffir, kerisik (dừa nướng), đường hoặc đường cọ vào, khuấy đều để hòa quyện với thịt.', NULL, '2026-05-15 14:28:25', '2026-05-15 14:28:25'),
(239, 33, 3, 'Hạ nhiệt xuống thấp, đậy nắp và đun nhỏ lửa trong 1 đến 1 tiếng rưỡi hoặc cho đến khi thịt thực sự mềm và nước sốt đã khô. Thêm nhiều muối và đường cho vừa ăn. Ăn ngay với cơm trắng và để dành một ít để qua đêm.', NULL, '2026-05-15 14:28:25', '2026-05-15 14:28:25'),
(240, 34, 1, 'Đun nóng dầu ô liu trong chảo chống dính, sau đó cho hành tây thái lát vào nấu trên lửa vừa cho đến khi mềm hoàn toàn, khoảng 15 phút, thêm một ít nước nếu chúng bắt đầu dính. Nghiền tỏi và nấu thêm 2-3 phút nữa, sau đó thêm bơ. Khi bơ nổi bọt một chút, thêm nấm vào và nấu khoảng 5 phút cho đến khi mềm hoàn toàn. Nêm kỹ mọi thứ rồi bày ra đĩa.', NULL, '2026-05-15 14:28:27', '2026-05-15 14:28:27'),
(241, 34, 2, 'Đổ bột mì vào tô với một chút muối và hạt tiêu, sau đó lăn miếng bít tết vào bột mì đã nêm. Cho các miếng bít tết vào chảo, rưới một ít dầu nếu chảo trông đặc biệt khô và chiên trong 3-4 phút cho đến khi có màu vàng đẹp. Cho hành và nấm trở lại chảo. Đánh đều kem tươi, mù tạt và nước kho thịt bò với nhau rồi đổ vào chảo. Nấu trên lửa vừa trong khoảng 5 phút. Rắc thêm rau mùi tây, sau đó dùng kèm với pappardelle hoặc cơm.', NULL, '2026-05-15 14:28:27', '2026-05-15 14:28:27'),
(242, 35, 1, 'Nấu bông cải xanh và cà rốt trong chảo nước sôi cho đến khi mềm.', NULL, '2026-05-15 14:28:30', '2026-05-15 14:28:30'),
(243, 35, 2, 'Nướng Thịt bò và Khoai tây trong lò trong 45 phút, khoai tây có thể cần được kiểm tra thường xuyên để không bị chín quá.', NULL, '2026-05-15 14:28:30', '2026-05-15 14:28:30'),
(244, 35, 3, 'Cách làm bánh pudding Yorkshire:', NULL, '2026-05-15 14:28:30', '2026-05-15 14:28:30'),
(245, 35, 4, 'Làm nóng lò ở 230C/quạt 210C/gas 8. Rưới đều một ít dầu hướng dương vào 2 hộp thiếc làm bánh pudding Yorkshire 4 lỗ hoặc khuôn làm bánh nướng xốp chống dính 12 lỗ rồi cho vào lò nướng để hâm nóng.', NULL, '2026-05-15 14:28:30', '2026-05-15 14:28:30'),
(246, 35, 5, 'Để làm bột, cho 140g bột mì vào tô và đánh 4 quả trứng cho đến khi mịn. Thêm từ từ 200ml sữa vào và tiếp tục đánh cho đến khi hỗn hợp không bị vón cục. Nêm muối và hạt tiêu. Đổ bột vào bình, sau đó lấy khuôn nóng ra khỏi lò. Đổ bột vào các lỗ một cách cẩn thận và đều. Đặt các hộp thiếc trở lại lò và để yên trong 20-25 phút cho đến khi bánh pudding phồng lên và chuyển sang màu nâu. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:28:30', '2026-05-15 14:28:30'),
(247, 35, 6, 'Bày ra đĩa và thêm nước sốt theo ý muốn.', NULL, '2026-05-15 14:28:30', '2026-05-15 14:28:30'),
(248, 36, 1, 'Cho nấm vào máy xay thực phẩm với một ít gia vị rồi xay thành hỗn hợp sệt. Cạo hỗn hợp này vào chảo và nấu trên lửa cao trong khoảng 10 phút, đảo thường xuyên để loại bỏ hơi ẩm trong nấm. Bày ra đĩa cho nguội.', NULL, '2026-05-15 14:28:35', '2026-05-15 14:28:35'),
(249, 36, 2, 'Đun nóng chảo và thêm một ít dầu ô liu. Nêm thịt bò và nướng trên chảo nóng chỉ trong 30 giây mỗi mặt. (Bạn không muốn nấu nó ở giai đoạn này, chỉ cần tô màu thôi). Lấy thịt bò ra khỏi chảo và để nguội rồi phết mù tạt lên khắp mặt.', NULL, '2026-05-15 14:28:35', '2026-05-15 14:28:35'),
(250, 36, 3, 'Đặt một tấm màng bám lên bề mặt làm việc và sắp xếp các lát giăm bông Parma trên đó thành các hàng hơi chồng lên nhau. Dùng dao trộn phết hỗn hợp nấm lên giăm bông, sau đó đặt phi lê thịt bò xào vào giữa. Giữ chặt màng bám ở mép, cuộn gọn giăm bông Parma và nấm xung quanh miếng thịt bò để tạo thành hình thùng chặt. Vặn các đầu của màng bám để cố định. Làm lạnh trong 15-20 phút để thịt bò đông lại và giữ được hình dạng.', NULL, '2026-05-15 14:28:35', '2026-05-15 14:28:35'),
(251, 36, 4, 'Cán miếng bánh phồng trên bề mặt đã phủ bột mì thành một hình chữ nhật lớn, có độ dày bằng đồng xu 1 bảng Anh. Loại bỏ lớp màng bám trên thịt bò rồi đặt vào giữa. Quét lòng đỏ trứng xung quanh bánh ngọt. Gấp các đầu lại, bọc bánh ngọt quanh thịt bò, cắt bỏ phần thừa. Lật lại sao cho đường may nằm bên dưới và đặt lên khay nướng. Quét trứng lên toàn bộ bánh và để lạnh trong khoảng 15 phút để bánh nghỉ.', NULL, '2026-05-15 14:28:35', '2026-05-15 14:28:35'),
(252, 36, 5, 'Làm nóng lò ở nhiệt độ 200C, 400F, gas 6.', NULL, '2026-05-15 14:28:35', '2026-05-15 14:28:35'),
(253, 36, 6, 'Chấm nhẹ lên bánh cách nhau 1cm và tráng lại bằng lòng đỏ trứng đã đánh bông. Nướng trong 20 phút, sau đó hạ nhiệt độ lò xuống 180C, 350F, gas 4 và nấu thêm 15 phút nữa. Để yên khoảng 10-15 phút trước khi cắt lát và dùng với các món ăn phụ mà bạn chọn. Thịt bò vẫn còn màu hồng ở giữa khi bạn phục vụ.', NULL, '2026-05-15 14:28:35', '2026-05-15 14:28:35'),
(254, 37, 1, 'Đối với nước sốt Big Mac, trộn tất cả nguyên liệu vào tô, nêm muối và để lạnh cho đến khi dùng.', NULL, '2026-05-15 14:28:55', '2026-05-15 14:28:55'),
(255, 37, 2, '2. Để làm chả, nêm thịt băm với muối và hạt tiêu rồi vo thành 4 viên, mỗi viên khoảng 1/3 cốc thịt băm. Đặt từng miếng lên một tờ giấy nướng hình vuông và dẹt để tạo thành hình tròn 4 x 15cm. Đun nóng dầu trong chảo lớn trên lửa cao. Làm 2 mẻ, nấu từng miếng thịt bò trong 1-2 phút mỗi mặt cho đến khi cháy xém và chín đều. Hủy bỏ nhiệt và giữ ấm. Lặp lại với hai miếng còn lại.', NULL, '2026-05-15 14:28:55', '2026-05-15 14:28:55'),
(256, 37, 3, '3. Cẩn thận cắt từng chiếc bánh mì kẹp thịt thành ba đường ngang, sau đó nướng nhẹ.', NULL, '2026-05-15 14:28:55', '2026-05-15 14:28:55'),
(257, 37, 4, '4. Để gói bánh mì kẹp thịt, phết một ít nước sốt Big Mac lên phần đế dưới. Phủ lên trên một ít hành tây xắt nhỏ, rau diếp thái nhỏ, lát phô mai, miếng thịt bò và vài lát dưa chua. Phủ lớp bánh mì ở giữa lên trên, phết thêm sốt Big Mac, hành tây, xà lách, dưa chua, chả bò rồi cuối cùng rưới thêm sốt. Phủ nắp bánh burger lên trên để phục vụ.', NULL, '2026-05-15 14:28:55', '2026-05-15 14:28:55'),
(258, 37, 5, '5. Sau khi đợi nửa giờ để thức ăn ổn định, hãy chạy bộ.', NULL, '2026-05-15 14:28:55', '2026-05-15 14:28:55');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(260, 38, 1, 'Cho bắp cải vào đĩa hầm dày, thêm nước luộc và nấu trên lửa nhỏ trong khoảng 50 phút cho đến khi bắp cải mềm.', NULL, '2026-05-15 14:28:57', '2026-05-16 12:35:33'),
(262, 38, 2, 'Cắt nấm ngâm thành dải và tiết kiệm nước ngâm. Đun nóng mỡ rồi cho xúc xích và thịt xông khói vào xào chín rồi múc ra, để lại mỡ trong chảo. Chiên hành tây trong cùng một chảo trong 5-8 phút cho đến khi có màu nâu nhạt.', NULL, '2026-05-15 14:28:57', '2026-05-16 12:35:33'),
(264, 38, 3, 'Thêm nấm và chất lỏng của chúng cùng với tất cả thịt, hành tây và mận đã nấu chín, sau đó đậy nắp và nấu trong 20 phút. Thêm gia vị, rượu vang đỏ và cà chua xay nhuyễn rồi đun nhỏ lửa, sau đó đậy nắp và nấu trong 1 giờ. Nêm kỹ và để nguội. Sẽ được đậy kín và ướp lạnh trong tối đa hai ngày. Bigos cải thiện hương vị trong vài ngày. Để nguội trước. Đun nóng lại cho đến khi nóng trước khi dùng.', NULL, '2026-05-15 14:28:57', '2026-05-16 12:35:33'),
(265, 39, 1, '0. Ướp thịt bò trong nước tương, chanh (hoặc calamansi) và tiêu đen xay trong ít nhất 1 giờ. Lưu ý: ướp qua đêm để có kết quả tốt nhất', NULL, '2026-05-15 14:29:00', '2026-05-15 14:29:00'),
(266, 39, 2, '1. Đun nóng dầu ăn trong chảo rồi cho nửa củ hành vào xào cho đến khi mềm. Đặt sang một bên', NULL, '2026-05-15 14:29:00', '2026-05-15 14:29:00'),
(267, 39, 3, '2. Xả nước xốt ra khỏi thịt bò. Đặt nó sang một bên. Chiên thịt bò trên cùng một chảo đã chiên hành tây trong 1 phút mỗi mặt. Lấy ra khỏi chảo. Đặt sang một bên', NULL, '2026-05-15 14:29:00', '2026-05-15 14:29:00'),
(268, 39, 4, '3. Thêm dầu nếu cần. Xào tỏi và hành sống còn lại cho đến khi hành mềm.', NULL, '2026-05-15 14:29:00', '2026-05-15 14:29:00'),
(269, 39, 5, '4. Đổ phần nước xốt còn lại và nước. Đun sôi.', NULL, '2026-05-15 14:29:00', '2026-05-15 14:29:00'),
(270, 39, 6, '5. Thêm thịt bò. Đậy chảo và đun nhỏ lửa cho đến khi thịt mềm. Lưu ý: Thêm nước khi cần thiết.', NULL, '2026-05-15 14:29:00', '2026-05-15 14:29:00'),
(271, 39, 7, '6. Nêm hạt tiêu đen xay và muối nếu cần. Rắc hành tây chiên lên trên.', NULL, '2026-05-15 14:29:00', '2026-05-15 14:29:00'),
(272, 39, 8, '7. Chuyển sang đĩa phục vụ. Ăn nóng. Chia sẻ và thưởng thức!', NULL, '2026-05-15 14:29:00', '2026-05-15 14:29:00'),
(273, 40, 1, 'Đun chảy bơ trong chảo hoặc chảo. Khi tan chảy, thêm từng chút bột vào và khuấy thành hỗn hợp sệt. Từ từ khuấy nước kho để đảm bảo roux hấp thụ chất lỏng. Đun nhỏ lửa trong vài phút ở lửa nhỏ trong khi cho hành tây, rau mùi tây và thịt xé nhỏ vào xào. Hỗn hợp sẽ đặc lại và chuyển thành nước sốt đặc, đặc.', NULL, '2026-05-15 14:29:02', '2026-05-15 14:29:02'),
(274, 40, 2, 'Đổ hỗn hợp vào hộp nông, đậy nắp và để lạnh trong vài giờ hoặc cho đến khi nước sốt đông lại.', NULL, '2026-05-15 14:29:02', '2026-05-15 14:29:02'),
(275, 40, 3, 'Lấy một thìa đầy nước sốt đặc, lạnh và nhanh chóng vo tròn thành một quả bóng nhỏ. Lăn nhẹ qua bột mì, trứng và cuối cùng là vụn bánh mì. Hãy chắc chắn rằng trứng bao phủ toàn bộ bề mặt của quả đắng. Khi hoàn tất, hãy để đồ ăn nhẹ vào tủ lạnh trong khi dầu trong nồi chiên của bạn nóng lên tới 190C (375F). Chiên bốn quả đắng cùng một lúc cho đến khi vàng.', NULL, '2026-05-15 14:29:02', '2026-05-15 14:29:02'),
(276, 40, 4, 'Bày ra đĩa với mù tạt dạng hạt hoặc cay.', NULL, '2026-05-15 14:29:02', '2026-05-15 14:29:02'),
(278, 41, 1, 'Để làm nước kho, cho thịt, toàn bộ hành tây, lá nguyệt quế và 2 lít nước lạnh có pha chút muối vào nồi lớn. Nấu ở nhiệt độ rất thấp trong 1 giờ 30 phút hoặc cho đến khi thịt bò mềm và dễ tách ra - quá trình này có thể mất đến 3 giờ. Thỉnh thoảng hớt cặn bằng thìa. Chia miếng thịt bò lớn hơn vào nước dùng, loại bỏ toàn bộ hành tây và bỏ đi.', NULL, '2026-05-15 14:29:07', '2026-05-16 12:35:33'),
(280, 41, 2, 'Thêm khoai tây vào borscht, nêm muối và hạt tiêu rồi nấu trong vòng 10-15 phút cho đến khi mềm. Trong khi đó, đun nóng dầu hướng dương trong chảo rán lớn, sâu lòng. Thêm hành tây và cà rốt thái hạt lựu vào nấu trên lửa vừa, khuấy đều cho đến khi cà rốt mềm và sắp bắt đầu chuyển sang màu caramen.', NULL, '2026-05-15 14:29:07', '2026-05-16 12:35:33'),
(282, 41, 3, 'Thêm củ cải đường và nấu khoảng 5 phút, thỉnh thoảng khuấy. Thêm ớt đỏ, nếu dùng và nấu thêm 2 phút nữa, sau đó thêm cà chua và mận khô, khuấy đều, sau đó tăng lửa và đun sôi để giảm bớt một chút trước khi thêm mọi thứ vào borscht.', NULL, '2026-05-15 14:29:07', '2026-05-16 12:35:33'),
(284, 41, 4, 'Thêm bắp cải cắt nhỏ và đậu thận vào nấu trong 7-10 phút hoặc cho đến khi mềm. Ăn kèm với một ít kem chua hoặc crème fraîche, nhiều thì là cắt nhỏ và một ít bánh mì giòn.', NULL, '2026-05-15 14:29:07', '2026-05-16 12:35:33'),
(285, 42, 1, 'Làm nóng lò ở mức 120C/225F/mốc gas 1.', NULL, '2026-05-15 14:29:10', '2026-05-15 14:29:10'),
(286, 42, 2, 'Lấy thịt ra khỏi tủ lạnh để nguội. Cho hành và tỏi vào máy xay thực phẩm cho đến khi thái nhỏ. Đun nóng 2 muỗng canh dầu ô liu trong một cái chảo lớn và áp chảo thịt các mặt cho đến khi vàng.', NULL, '2026-05-15 14:29:10', '2026-05-15 14:29:10'),
(287, 42, 3, 'Đặt sang một bên và thêm một chút dầu nhỏ khác để làm cho chorizo ​​có màu nâu. Hủy bỏ và thêm hành tây và tỏi, gia vị, rau thơm và ớt sau đó nấu cho đến khi mềm trong dầu chorizo. Nêm muối và hạt tiêu rồi thêm giấm, cà chua, sốt cà chua và đường.', NULL, '2026-05-15 14:29:10', '2026-05-15 14:29:10'),
(288, 42, 4, 'Cho toàn bộ thịt vào nồi cùng 400ml nước (hoặc rượu vang đỏ nếu thích), đun nhỏ lửa rồi đậy nắp nấu trong lò lửa nhỏ.', NULL, '2026-05-15 14:29:10', '2026-05-15 14:29:10'),
(289, 42, 5, 'Sau 2 giờ, kiểm tra thịt và thêm đậu. Nấu thêm một giờ nữa và ngay trước khi dùng, hãy dùng nĩa tách thịt ra.', NULL, '2026-05-15 14:29:10', '2026-05-15 14:29:10'),
(290, 43, 1, 'Đun nóng dầu ô liu trong nồi lớn. Cắt thịt bò thành khối vuông 1 inch (2,5 cm) và chiên vàng trong dầu.', NULL, '2026-05-15 14:29:12', '2026-05-15 14:29:12'),
(291, 43, 2, 'Cắt nhỏ hành tây và thêm vào thịt bò đang xào. Thêm nước kho vào và đun sôi, sau đó giảm nhiệt, đậy nắp và đun nhỏ lửa trong khoảng 30 phút.', NULL, '2026-05-15 14:29:12', '2026-05-15 14:29:12'),
(292, 43, 3, 'Gọt vỏ và cắt củ rutabaga và rễ cần tây thành khối 1 inch (2,5 cm). Cho vào nồi, đậy nắp và tiếp tục đun nhỏ lửa thêm 30 phút nữa.', NULL, '2026-05-15 14:29:12', '2026-05-15 14:29:12'),
(293, 43, 4, 'Gọt vỏ và cắt phần rau còn lại thành khối 1 inch (2,5 cm) rồi cho vào nồi. Cắt tỏi tây thành từng khoanh. Đậy nắp và tiếp tục đun nhỏ lửa trong khoảng 20 phút. Khuấy càng ít càng tốt.', NULL, '2026-05-15 14:29:12', '2026-05-15 14:29:12'),
(294, 43, 5, 'Rắc mùi tây tươi lên trên.', NULL, '2026-05-15 14:29:12', '2026-05-15 14:29:12'),
(295, 44, 1, 'Nâu thịt bò: Trong một cái nồi lớn, nâu các khối thịt bò. Loại bỏ và đặt sang một bên.', NULL, '2026-05-15 14:29:17', '2026-05-15 14:29:17'),
(296, 44, 2, 'Xào rau: Trong cùng một nồi, nấu hành tây cho đến khi chín trong. Thêm cà rốt, khoai tây và bí ngô vào nấu trong vài phút.', NULL, '2026-05-15 14:29:17', '2026-05-15 14:29:17'),
(297, 44, 3, 'Đun nhỏ lửa: Cho thịt bò vào nồi. Thêm nước dùng và mơ khô. Nêm muối và hạt tiêu. Đun nhỏ lửa trong 1-2 giờ cho đến khi thịt bò mềm.', NULL, '2026-05-15 14:29:17', '2026-05-15 14:29:17'),
(298, 44, 4, 'Cách dùng: Thưởng thức nóng với một miếng bánh mì giòn.', NULL, '2026-05-15 14:29:17', '2026-05-15 14:29:17'),
(299, 44, 5, 'Lời khuyên chuyên nghiệp:', NULL, '2026-05-15 14:29:17', '2026-05-15 14:29:17'),
(300, 44, 6, 'Nướng thịt bò theo từng mẻ để đảm bảo thịt có độ chín vừa phải, giúp tăng thêm hương vị cho món hầm.', NULL, '2026-05-15 14:29:17', '2026-05-15 14:29:17'),
(301, 44, 7, 'Thêm trái cây vào cuối quá trình nấu sẽ giữ nguyên kết cấu của chúng và tăng thêm vị ngọt tinh tế cho món ăn.', NULL, '2026-05-15 14:29:17', '2026-05-15 14:29:17'),
(302, 45, 1, 'Đặt thịt xay vào tô. Băm hành thật nhuyễn và băm nhuyễn tép tỏi. Thêm vào bát. Thêm rau mùi tây cắt nhỏ, các loại ớt bột, baking soda, vụn bánh mì khô, nước, rau củ, muối và hạt tiêu.', NULL, '2026-05-15 14:29:22', '2026-05-15 14:29:22'),
(303, 45, 2, 'Trộn đều bằng máy trộn cầm tay có gắn móc bột. Đậy bát bằng màng dính/giấy nhựa và để yên trong tủ lạnh trong 1 hoặc 2 giờ.', NULL, '2026-05-15 14:29:22', '2026-05-15 14:29:22'),
(304, 45, 3, 'Lấy các phần hỗn hợp thịt, khoảng 50-55 g/ 1,7-1,9 oz/ ¼ cốc và tạo thành cevapi. Các cuộn bánh phải dày bằng ngón tay cái của bạn và dài khoảng 7-10 cm/ 3-4 inch. Tôi có 18 cái xúc xích. Công thức có thể dễ dàng tăng gấp đôi.', NULL, '2026-05-15 14:29:22', '2026-05-15 14:29:22'),
(305, 45, 4, 'Nướng cevapcici trên chảo nướng nóng hoặc trên vỉ nướng trong khoảng 12-14 phút, lật chúng vài lần giữa các lần hoặc cho đến khi có màu nâu và chín đều. Tôi kiểm tra bằng cách cắt một cái ở giữa rồi nướng các mẻ sau trong cùng một khoảng thời gian.', NULL, '2026-05-15 14:29:22', '2026-05-15 14:29:22'),
(306, 45, 5, 'Dùng nóng như gợi ý ở trên. Cevapcici có thể được hâm nóng trong lò ở nhiệt độ 180 độ C/350 độ F trong khoảng 10 phút hoặc cho đến khi nóng hoàn toàn. Kiểm tra một cái, nếu chưa đủ nóng thì cho xúc xích thêm vài phút nữa.', NULL, '2026-05-15 14:29:22', '2026-05-15 14:29:22'),
(307, 46, 1, 'Đối với bánh brioche, đun nóng sữa với bơ và mật đường cho đến khi bơ tan chảy. Thêm nước lạnh và trứng vào hỗn hợp này.', NULL, '2026-05-15 14:29:25', '2026-05-15 14:29:25'),
(308, 46, 2, 'Trong một tô lớn cho bột mì, muối và men vào rồi trộn đều. Sau đó thêm sữa và nước trộn vào rồi dùng thìa gỗ khuấy đều cho đến khi hòa quyện. Bạn không cần phải nhào bột, bạn có thể làm bằng tay với thìa gỗ, việc này không cần quá kỹ lưỡng. Che lại bằng khăn ẩm và để trong tủ lạnh qua đêm.', NULL, '2026-05-15 14:29:25', '2026-05-15 14:29:25'),
(309, 46, 3, 'Sáng hôm sau, nhào bột một chút trên bề mặt đã rắc bột mì rồi cắt thành tám miếng bằng nhau. Nặn chúng thành những quả bóng và đặt trên khay nướng có lót giấy da. Đậy lại bằng khăn ẩm và để bột nở trong khoảng một giờ hoặc cho đến khi nở gấp đôi.', NULL, '2026-05-15 14:29:25', '2026-05-15 14:29:25'),
(310, 46, 4, 'Làm nóng lò ở nhiệt độ 220 độ C. Quét lên bánh một lớp sữa, kem đặc hoặc nước rửa trứng và rắc hạt vừng nếu muốn. Nướng khoảng 15-20 phút hoặc cho đến khi vàng. Để nguội.', NULL, '2026-05-15 14:29:25', '2026-05-15 14:29:25'),
(311, 46, 5, 'Đối với phần trên, cắt nhỏ hành tây và xào với một chút bơ, để caramen, quá trình này có thể mất 10 đến 15 phút, thỉnh thoảng khuấy. Chà bít tết với một chút tỏi rồi nướng hoặc chiên bít tết, thịt xông khói và trứng với muối tiêu, nướng bánh sau khi cắt làm đôi. Trải mù tạt lên một nửa chiếc bánh mì, xếp từng lớp chivito với bít tết, một lát giăm bông, một lát phô mai, một sọc thịt xông khói, một lát cà chua và một ít rau diếp. Đặt trứng chiên lên trên và rắc nhiều chimichurri và một ít hành tây ngay trước khi ăn.', NULL, '2026-05-15 14:29:25', '2026-05-15 14:29:25'),
(312, 47, 1, 'Nghiền thịt sao cho thật nhuyễn rồi cho lên vỉ nướng cho chín vàng. Cho trứng, thịt xông khói và giăm bông vào chiên.', NULL, '2026-05-15 14:29:28', '2026-05-15 14:29:28'),
(313, 47, 2, 'Cắt đôi chiếc bánh mì, cho ức bò, trứng chiên, thịt xông khói, giăm bông, phô mai mozzarella, cà chua và rau diếp vào. Che nửa còn lại của bánh mì và phục vụ.', NULL, '2026-05-15 14:29:28', '2026-05-15 14:29:28'),
(314, 48, 1, 'Đun nóng dầu trên lửa vừa cao trong chảo hoặc chảo xào lớn, sau đó xào hành và tỏi cho đến khi mềm, khoảng 5 phút. Thêm thịt bò xay, thịt lợn và gia vị vào nấu cho đến khi thịt chín vàng.', NULL, '2026-05-15 14:29:31', '2026-05-15 14:29:31'),
(315, 48, 2, 'Thêm nước dùng thịt bò và đun sôi rồi giảm nhiệt xuống mức trung bình thấp. Thêm khoai tây bào vào và khuấy đều. Nấu cho đến khi chất lỏng gần như hấp thụ, khoảng 15 phút. Loại bỏ lá nguyệt quế và thêm muối cho vừa ăn. Lấy chảo ra khỏi bếp và để hỗn hợp nguội hoàn toàn - bánh sẽ ngon nhất nếu nhân được làm lạnh.', NULL, '2026-05-15 14:29:31', '2026-05-15 14:29:31'),
(316, 48, 3, 'Làm nóng lò ở nhiệt độ 375°F (190°C). Trên một bề mặt đã phủ bột nhẹ, cán mỏng một đĩa bột bánh có độ dày nhỏ hơn 1/4 inch và lót vào đĩa bánh 9 inch. Đổ đầy hỗn hợp tourtière đã nguội vào đây và trải đều. Cán khối bột còn lại có độ dày như nhau, khoét một lỗ ở giữa (để hơi thoát ra) và đặt lên trên phần nhân. Cắt bột còn 1/2 inch ngoài mép của đĩa bánh và kẹp các mép của vỏ bánh lại với nhau. Quét lớp vỏ bằng nước rửa trứng.', NULL, '2026-05-15 14:29:31', '2026-05-15 14:29:31'),
(317, 48, 4, 'Nướng tourtière trong khoảng 45 phút hoặc cho đến khi bánh có màu nâu vàng đậm. Để nguội trong 15 phút trước khi cắt lát để phục vụ.', NULL, '2026-05-15 14:29:31', '2026-05-15 14:29:31'),
(318, 48, 5, 'Phục vụ: 8-10 (làm 2 chiếc bánh 9 inch)', NULL, '2026-05-15 14:29:31', '2026-05-15 14:29:31'),
(319, 49, 1, 'Đặt thịt bò bắp vào nồi lớn hoặc lò nướng kiểu Hà Lan và đậy nắp bằng nước. Thêm gói gia vị đi kèm với thịt bò bắp. Đậy nắp nồi và đun sôi, sau đó giảm nhỏ lửa. Đun nhỏ lửa khoảng 50 phút mỗi pound hoặc cho đến khi mềm.', NULL, '2026-05-15 14:29:33', '2026-05-15 14:29:33'),
(320, 49, 2, 'Thêm toàn bộ khoai tây và cà rốt gọt vỏ và cắt nhỏ vào nấu cho đến khi rau gần như mềm. Thêm bắp cải và nấu thêm 15 phút nữa. Lấy thịt ra và để yên 15 phút.', NULL, '2026-05-15 14:29:34', '2026-05-15 14:29:34'),
(321, 49, 3, 'Đặt rau vào tô và đậy nắp. Thêm bao nhiêu nước dùng (nước nấu dành riêng cho nồi Hà Lan hoặc nồi lớn) tùy thích. Cắt thịt theo thớ.', NULL, '2026-05-15 14:29:34', '2026-05-15 14:29:34'),
(322, 50, 1, 'Đun nóng dầu ô liu trong chảo hoặc nồi Hà Lan trên lửa vừa cao. Thêm hành tây và ớt xanh vào xào khoảng 3-5 phút.', NULL, '2026-05-15 14:29:36', '2026-05-15 14:29:36'),
(323, 50, 2, 'Thêm tỏi và khuấy trong khoảng 1 phút.', NULL, '2026-05-15 14:29:36', '2026-05-15 14:29:36'),
(324, 50, 3, 'Thêm bắp cải cắt nhỏ vào và khuấy đều. Nấu khoảng 3-5 phút, khuấy thường xuyên cho đến khi mềm.', NULL, '2026-05-15 14:29:36', '2026-05-15 14:29:36'),
(325, 50, 4, 'Thêm thịt bò bắp, cà chua Roma, húng tây và khuấy đều. Thêm sốt cà chua và sốt tiêu scotch nắp ca-pô vào rồi khuấy đều. Giảm nhiệt và nấu ở mức trung bình trong khoảng 3-5 phút, cho đến khi thịt bò bắp chín đều. Loại bỏ khỏi nhiệt.', NULL, '2026-05-15 14:29:36', '2026-05-15 14:29:36'),
(326, 50, 5, 'Ăn kèm cơm trắng, bánh mì hoặc ăn riêng.', NULL, '2026-05-15 14:29:36', '2026-05-15 14:29:36'),
(327, 51, 1, 'Xào hành tây:', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(328, 51, 2, 'Đun nóng bơ trong chảo lớn (tốt nhất là chảo gang) trên lửa vừa. Thêm hành tây và nấu vài phút cho đến khi trong suốt.', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(329, 51, 3, 'Thêm khoai tây và thịt bò bắp:', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(330, 51, 4, 'Trộn thịt bò và khoai tây cắt nhỏ vào. Trải đều trên chảo. Tăng nhiệt lên cao hoặc trung bình cao và ấn hỗn hợp xuống bằng thìa kim loại.', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(331, 51, 5, 'Nấu cho đến khi chín vàng rồi lật:', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(332, 51, 6, 'Đừng khuấy khoai tây và thịt bò bắp mà hãy để chúng có màu nâu. Nếu bạn nghe thấy chúng kêu xèo xèo thì điều này là tốt.', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(333, 51, 7, 'Dùng thìa kim loại để quan sát bên dưới và xem chúng có chuyển sang màu nâu không. Nếu bánh đã chín vàng đẹp mắt, hãy dùng thìa lật các phần trong chảo để chúng có màu nâu ở mặt còn lại. Nhấn xuống một lần nữa bằng thìa.', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(334, 51, 8, 'Nếu dính quá, bạn có thể cho thêm một ít bơ vào chảo. Tiếp tục nấu theo cách này cho đến khi khoai tây và thịt bò bắp có màu nâu đẹp mắt.', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(335, 51, 9, 'Khuấy rau mùi tây và nêm gia vị:', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(336, 51, 10, 'Tắt bếp, cho rau mùi tây cắt nhỏ vào khuấy đều. Thêm nhiều hạt tiêu đen mới xay và thêm muối cho vừa ăn.', NULL, '2026-05-15 14:29:38', '2026-05-15 14:29:38'),
(337, 52, 1, 'Đun nóng dầu trong chảo', NULL, '2026-05-15 14:29:41', '2026-05-15 14:29:41'),
(338, 52, 2, 'Thêm rau xắt nhỏ và xào cho đến khi mềm', NULL, '2026-05-15 14:29:41', '2026-05-15 14:29:41'),
(339, 52, 3, 'Lấy một cái nồi, đổ đậu và rau vào nồi, cho xúc xích vào nấu thêm 20 phút ở lửa nhỏ', NULL, '2026-05-15 14:29:41', '2026-05-15 14:29:41'),
(340, 52, 4, 'Hoặc cho vào lò nướng và nướng ở nhiệt độ 180°C/350°F trong 30 phút', NULL, '2026-05-15 14:29:41', '2026-05-15 14:29:41'),
(341, 52, 5, 'Món ăn này thậm chí còn ngon hơn nếu được hâm nóng lại vào ngày hôm sau', NULL, '2026-05-15 14:29:41', '2026-05-15 14:29:41'),
(342, 53, 1, 'Làm nóng lò ở mức quạt 200°C / 220°C / 425°F / Dấu gas 7', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(343, 53, 2, 'Nếu bạn chưa mua thịt cừu thái hạt lựu, hãy cắt vai hoặc chân cừu thành từng miếng lớn và đặt sang một bên.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(344, 53, 3, 'Những miếng thịt cừu băm nhỏ trên thớt đỏ', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(345, 53, 4, 'Làm dầu ướp -', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(346, 53, 5, 'Trộn 80ml dầu ô liu vào tô với tỏi xay nhuyễn, cà chua xay nhuyễn, hạt tiêu đen và muối.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(347, 53, 6, 'dầu ô liu, cà chua xay nhuyễn gia, tỏi gia nghiền nhuyễn và tiêu đen trộn với nhau trong một chiếc bát bạc để làm món peka Croatia', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(348, 53, 7, 'Cho khoai tây và rau vào một đĩa thịt hầm lớn có nắp đậy.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(349, 53, 8, 'Rau củ xắt nhỏ bao gồm hành tây đỏ xắt nhỏ, bí xanh, khoai tây ớt đỏ trong chảo gang', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(350, 53, 9, 'Đặt thịt cừu thái hạt lựu lên trên các loại rau, rưới nước xốt và rượu lên trên.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(351, 53, 10, 'Những miếng thịt cừu phủ sốt dầu cà chua khô đặt trên cùng với hành tây đỏ xắt nhỏ, cà tím, bí xanh và khoai tây trong chảo gang', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(352, 53, 11, 'Thêm hương thảo, húng tây và cây xô thơm, cố gắng giữ các loại thảo mộc ở trên.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(353, 53, 12, 'Vì vậy, bạn có thể dễ dàng loại bỏ cuống thảo mộc sau khi nấu chín.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(354, 53, 13, 'Những miếng thịt cừu phủ sốt dầu cà chua khô và phủ húng tây, hương thảo và cây xô thơm đặt trên cùng với hành tây đỏ xắt nhỏ, cà tím, bí xanh và khoai tây trong chảo gang', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(355, 53, 14, 'Đậy nắp lên đĩa thịt hầm và nấu trong 1 giờ 30 phút', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(356, 53, 15, 'Nếu bạn không có nắp đậy thật tốt bằng giấy bạc nhà bếp', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(357, 53, 16, 'Đĩa gang có nắp đậy trong lò', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(358, 53, 17, 'Mở nắp, loại bỏ những cọng thảo mộc dày. Khuấy 2 muỗng canh dầu ô liu.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(359, 53, 18, 'Nấu thêm 20-30 phút nữa.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(360, 53, 19, 'Thịt cừu Croatia Peka nấu chín trong chảo gang trong lò nướng', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(361, 53, 20, 'Ăn kèm với bánh mì tươi tự làm để nhúng vào nước ép.', NULL, '2026-05-15 14:29:44', '2026-05-15 14:29:44'),
(363, 54, 1, 'Làm nóng lò nướng ở mức quạt/khí 160C/140C 3. Làm mềm cần tây, hành tây, cà rốt, nguyệt quế và 1 nhánh húng tây trong nồi với 1 muỗng canh dầu và bơ trong 10 phút. Khuấy bột mì, tiếp theo là bột nhuyễn, sốt Worcestershire và nước kho.', NULL, '2026-05-15 14:29:47', '2026-05-16 12:35:33'),
(365, 54, 2, 'Khuấy dần dần với 600ml nước nóng, sau đó cho thịt bò vào đun sôi nhẹ. Đậy nắp và nướng trong lò khoảng 2 giờ 30 phút, sau đó mở nắp và nấu thêm 30 phút -1 giờ nữa cho đến khi thịt thực sự mềm và nước sốt đặc lại.', NULL, '2026-05-15 14:29:47', '2026-05-16 12:35:33'),
(367, 54, 3, 'Trong khi đó, nấu khoai tây trong chảo nước sôi cho đến khi chưa chín nhưng còn khoảng ¾ chặng đường.', NULL, '2026-05-15 14:29:47', '2026-05-16 12:35:33'),
(369, 54, 4, 'Chuyển thịt sang đĩa nướng. Cắt khoai tây thành những viên tròn dày 1cm và trộn nhẹ nhàng với gia vị, dầu còn lại và lá húng tây. Xếp lớp thịt bò lên trên, rải đều phô mai khi bạn xếp lớp. Bây giờ bạn có thể đậy nắp và làm lạnh chiếc bánh trong 1 ngày hoặc để đông lạnh tối đa 3 tháng.', NULL, '2026-05-15 14:29:47', '2026-05-16 12:35:33'),
(371, 54, 5, 'Tăng lò nướng lên 200C/180C quạt/gas 6 và nướng trong 30-40 phút cho đến khi vàng và giòn, và nước sốt sủi bọt nếu món ăn để nguội. Ăn kèm với đậu Hà Lan.', NULL, '2026-05-15 14:29:47', '2026-05-16 12:35:33'),
(373, 55, 1, 'Chuẩn bị mì theo hướng dẫn gói, sau đó để ráo nước và đặt sang một bên. Trộn tất cả các nguyên liệu làm nước sốt vào một cái bát hoặc bình nhỏ và đặt sang một bên.', NULL, '2026-05-15 14:29:51', '2026-05-16 12:35:33'),
(375, 55, 2, 'Đun nóng dầu trong chảo lớn hoặc chảo rán trên lửa cao rồi xào tỏi và ớt trong 20 giây cho đến khi bắt đầu chuyển sang màu vàng. Thêm bít tết và xào trong 1 phút cho đến khi chín và bắt đầu có màu nâu. Thêm bông cải xanh và xào thêm một phút nữa, sau đó cho mì vào và thêm nước sốt. Xào thêm 1-2 phút nữa cho đến khi hòa quyện và nóng hổi.', NULL, '2026-05-15 14:29:51', '2026-05-16 12:35:33'),
(377, 55, 3, 'Khuấy húng quế và tắt lửa. Phục vụ ngay lập tức để tránh nấu quá chín.', NULL, '2026-05-15 14:29:51', '2026-05-16 12:35:33'),
(378, 56, 1, 'Chuẩn bị bánh mì cho phần dưới cùng của món ăn: Lấy bánh mì pita và xé thành từng miếng vừa ăn. Trong chảo rán, thêm khoảng 1/4 que bơ, thêm miếng bánh mì vào và chiên cho đến khi vàng nâu và giòn. Đặt những miếng này vào đĩa nướng thủy tinh, tốt nhất là đĩa có kích thước hình vuông. Đặt sang một bên.', NULL, '2026-05-15 14:29:54', '2026-05-15 14:29:54'),
(379, 56, 2, 'Sau đó cho vào chảo, thêm một ít bơ, muối, khoảng 2 tép tỏi tươi giã nhuyễn, khoảng một thìa cà phê thì là khuấy đều cho đến khi ngửi thấy mùi thơm thì cho các miếng bánh mì đã chiên vào hỗn hợp này, đảo đều cho bánh mì phủ đều rồi cho vào khay nướng thủy tinh. Đặt sang một bên.', NULL, '2026-05-15 14:29:54', '2026-05-15 14:29:54'),
(380, 56, 3, 'Chuẩn bị thịt: cho một ít bơ vào nồi, xào thịt cho đến khi chín vàng, thêm 1 củ hành tây cắt tư, muối tiêu, 1 viên nước luộc gà và nước cho ngập thịt. Đun sôi, vặn nhỏ lửa, đậy nắp và nấu cho đến khi mềm, khoảng 2 giờ. Sau khi thịt nguội, lấy từng miếng thịt ra cho vào tô, để riêng. Dự trữ súp từ thịt riêng biệt.', NULL, '2026-05-15 14:29:54', '2026-05-15 14:29:54'),
(381, 56, 4, 'Chuẩn bị cơm: Cho một ít bơ vào nồi, thêm khoảng một nắm shareya (mì fideo), khuấy liên tục cho đến khi có màu vàng nâu, không quá đậm mà rất vàng. Sau đó cho hai chén gạo vào, khuấy một chút cho đến khi một ít gạo chuyển sang màu trắng đục. Thêm 2-1/4 cốc nước và muối cho vừa ăn. Đun sôi, đậy nắp và vặn nhỏ lửa, nấu cho đến khi mềm. Kiểm tra độ mềm của gạo sau khoảng 35 phút.', NULL, '2026-05-15 14:29:54', '2026-05-15 14:29:54'),
(382, 56, 5, 'Bây giờ lấy một ít nước súp từ thịt và thêm lên trên các miếng bánh mì trong khay nướng để thấm đẫm. Thêm cơm đã nấu chín lên trên các miếng bánh mì. Từ từ múc phần súp còn lại lên cơm, nhìn vào mặt đĩa thủy tinh để biết mức súp, chỉ nên chạm tới mặt trên của cơm, đừng lo lắng, điều này không cần phải chính xác. Bây giờ bạn đã sẵn sàng làm nước sốt và chiên thịt để đặt lên trên.', NULL, '2026-05-15 14:29:54', '2026-05-15 14:29:54'),
(383, 56, 6, 'Để chuẩn bị nước sốt đỏ: Cho một ít dầu hoặc bơ vào chảo, cà chua nghiền, nửa thìa cà phê bột cà chua, muối và tiêu, 2 tép tỏi tươi nghiền và thì là. Thêm khoảng 3 thìa giấm vào, khuấy đều cho đến khi ngửi thấy mùi thơm và hơi mịn. Nên đặc một chút, không bị chảy nước, nhưng nếu đặc quá bạn có thể thêm một chút nước. Dùng thìa gỗ trải cơm lên trên để phủ.', NULL, '2026-05-15 14:29:54', '2026-05-15 14:29:54'),
(384, 56, 7, 'Chiên thịt: Cho một ít bơ hoặc dầu vào chảo, cho thịt vào một chút tương cà chua, khoảng một thìa tỏi tươi giã nhuyễn, muối tiêu, một thìa thì là. Nấu cho đến khi thịt chín vàng.', NULL, '2026-05-15 14:29:54', '2026-05-15 14:29:54'),
(385, 56, 8, 'Múc thứ này lên trên cơm và thưởng thức. Thưởng thức!', NULL, '2026-05-15 14:29:54', '2026-05-15 14:29:54'),
(386, 57, 1, 'Làm bột: Trộn bột mì và muối trong một tô lớn. Thêm bơ vào, dùng ngón tay trộn đều thành hỗn hợp vụn. Dần dần thêm nước, trộn cho đến khi tạo thành bột. Bọc và thư giãn trong 30 phút.', NULL, '2026-05-15 14:29:57', '2026-05-15 14:29:57'),
(387, 57, 2, 'Chuẩn bị nhân: Nấu hành tây trong chảo cho đến khi trong suốt. Thêm thịt bò xay vào, nấu cho đến khi chín vàng. Khuấy đều gia vị rồi tắt bếp. Sau khi nguội, trộn trứng và ô liu vào.', NULL, '2026-05-15 14:29:57', '2026-05-15 14:29:57'),
(388, 57, 3, 'Làm: Cán bột và cắt thành hình tròn. Múc từng thìa nhân vào, gấp lại và dán kín các mép.', NULL, '2026-05-15 14:29:57', '2026-05-15 14:29:57'),
(389, 57, 4, 'Nấu: Nướng ở 200°C (400°F) trong 20-25 phút hoặc cho đến khi vàng.', NULL, '2026-05-15 14:29:57', '2026-05-15 14:29:57'),
(390, 57, 5, 'Lời khuyên chuyên nghiệp:', NULL, '2026-05-15 14:29:57', '2026-05-15 14:29:57'),
(391, 57, 6, 'Để có lớp vỏ bong tróc hơn, hãy thêm một thìa giấm vào hỗn hợp bột. Điều này giúp ngăn ngừa sự hình thành gluten.', NULL, '2026-05-15 14:29:57', '2026-05-15 14:29:57'),
(392, 57, 7, 'Dùng nĩa bịt kín các cạnh của bánh empanadas để đảm bảo chúng không bị bung ra trong khi nướng hoặc chiên.', NULL, '2026-05-15 14:29:57', '2026-05-15 14:29:57'),
(393, 58, 1, 'Đun sôi một nồi lớn nước muối nhẹ. Cho đầu bắp cải vào nước, đậy nắp nồi và nấu cho đến khi lá bắp cải hơi mềm, có thể lấy ra khỏi đầu, trong 3 phút. Lấy bắp cải ra khỏi nồi và để bắp cải ngồi cho đến khi lá đủ nguội để cầm, khoảng 10 phút.', NULL, '2026-05-15 14:30:00', '2026-05-15 14:30:00'),
(394, 58, 2, 'Cắt bỏ toàn bộ 18 lá ở đầu bắp cải, cắt bỏ những gân dày, cứng ở giữa. Đặt toàn bộ lá sang một bên. Cắt nhỏ phần đầu bắp cải còn lại và trải vào đáy đĩa thịt hầm.', NULL, '2026-05-15 14:30:00', '2026-05-15 14:30:00'),
(395, 58, 3, 'Đun chảy bơ trong chảo lớn trên lửa vừa cao. Nấu và khuấy hành tây trong bơ nóng cho đến khi mềm, từ 5 đến 10 phút. Mát mẻ.', NULL, '2026-05-15 14:30:00', '2026-05-15 14:30:00'),
(396, 58, 4, 'Khuấy hành tây, thịt bò, thịt lợn, gạo, tỏi, 1 muỗng cà phê muối và 1/4 muỗng cà phê tiêu với nhau trong một tô lớn.', NULL, '2026-05-15 14:30:00', '2026-05-15 14:30:00'),
(397, 58, 5, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C).', NULL, '2026-05-15 14:30:00', '2026-05-15 14:30:00'),
(398, 58, 6, 'Đặt khoảng 1/2 chén hỗn hợp thịt bò lên lá bắp cải. Cuộn bắp cải quanh hỗn hợp thịt bò, nhét từng bên để tạo lớp bao quanh miếng thịt. Lặp lại với hỗn hợp lá và thịt còn lại. Xếp các cuộn bắp cải thành một lớp lên trên bắp cải đã cắt nhỏ trong đĩa thịt hầm; cuộn mùa với muối và hạt tiêu đen.', NULL, '2026-05-15 14:30:00', '2026-05-15 14:30:00'),
(399, 58, 7, 'Đánh đều súp cà chua, nước ép cà chua và sốt cà chua trong một cái bát. Đổ hỗn hợp súp cà chua lên cuộn bắp cải và bọc đĩa bằng giấy nhôm.', NULL, '2026-05-15 14:30:00', '2026-05-15 14:30:00'),
(400, 58, 8, 'Nướng trong lò làm nóng trước cho đến khi bắp cải mềm và thịt chín, khoảng 1 giờ.', NULL, '2026-05-15 14:30:00', '2026-05-15 14:30:00'),
(401, 59, 1, 'Làm nóng lò nướng đến 180C/350F/mốc gas 4. Xả và rửa sạch lúa mì đã ngâm, cho vào chảo vừa với nhiều nước, đun sôi và đun nhỏ lửa trong một giờ cho đến khi chín. Xả và đặt sang một bên.', NULL, '2026-05-15 14:30:04', '2026-05-15 14:30:04'),
(402, 59, 2, 'Nêm thịt cừu với một thìa cà phê muối và một ít hạt tiêu đen. Cho một thìa dầu vào chảo xào sâu, lớn có nắp đậy; đặt trên lửa vừa cao. Thêm một ít thịt cừu vào chảo - đừng đổ quá nhiều thịt vào chảo - và nướng trong bốn phút cho tất cả các mặt. Chuyển sang tô và lặp lại với miếng thịt cừu còn lại, thêm dầu nếu cần.', NULL, '2026-05-15 14:30:04', '2026-05-15 14:30:04'),
(403, 59, 3, 'Giảm nhiệt xuống mức trung bình và thêm một muỗng dầu vào chảo. Thêm hẹ tây và chiên trong bốn phút cho đến khi có màu caramen. Đổ những thứ này vào bát thịt cừu, và lặp lại với các loại rau còn lại cho đến khi chúng đều có màu nâu đẹp mắt, thêm dầu nếu bạn cần.', NULL, '2026-05-15 14:30:04', '2026-05-15 14:30:04'),
(404, 59, 4, 'Sau khi tất cả các loại rau đã chín và lấy ra khỏi chảo, hãy thêm rượu cùng với đường, rau thơm, một thìa cà phê muối và một hạt tiêu đen xay nhuyễn. Đun sôi ở nhiệt độ cao trong khoảng ba phút.', NULL, '2026-05-15 14:30:04', '2026-05-15 14:30:04'),
(405, 59, 5, 'Đổ thịt cừu, rau và lúa mì nguyên hạt vào nồi rồi thêm nước kho vào. Đậy nắp và đun sôi trong năm phút, sau đó chuyển vào lò nướng trong một tiếng rưỡi.', NULL, '2026-05-15 14:30:04', '2026-05-15 14:30:04'),
(406, 59, 6, 'Lấy món hầm ra khỏi lò và kiểm tra chất lỏng; nếu có nhiều thì đậy nắp và đun sôi trong vài phút.', NULL, '2026-05-15 14:30:04', '2026-05-15 14:30:04'),
(436, 61, 1, 'Tối hôm trước, bẻ thịt bò muối thành từng miếng lớn rồi ngâm nước qua đêm ít nhất 8-10 tiếng. Cho đậu đã tách đôi vào tô, đổ ngập nước để ngâm qua đêm.', NULL, '2026-05-15 14:30:11', '2026-05-15 14:30:11'),
(437, 61, 2, 'Xả thịt bò muối và cho vào nồi kho lớn. Đổ đầy nước ngọt, ít nhất 6-7 lít. Đặt đậu Hà Lan đã tách đôi vào túi vải đựng bánh pudding đậu Hà Lan hoặc ba lớp vải thưa và buộc lại, đảm bảo chừa chỗ cho đậu Hà Lan nở ra bên trong túi.', NULL, '2026-05-15 14:30:11', '2026-05-15 14:30:11'),
(438, 61, 3, 'Đặt túi vào trong nồi, buộc dây vào tay cầm bên ngoài để túi không bị dính vào đáy nồi cùng thịt bò muối. Đun sôi, sau đó giảm nhiệt và đun nhỏ lửa trong 2 giờ.', NULL, '2026-05-15 14:30:11', '2026-05-15 14:30:11'),
(439, 61, 4, 'Lấy túi bánh pudding đậu Hà Lan và đổ hết vào tô, trộn với bơ và hạt tiêu cho vừa ăn. Đặt sang một bên.', NULL, '2026-05-15 14:30:11', '2026-05-15 14:30:11'),
(440, 61, 5, 'Cho bắp cải vào nồi và đun thêm 20 phút nữa. Sau đó thêm củ cải, cà rốt và khoai tây rồi đun thêm 20 phút nữa hoặc cho đến khi rau mềm.', NULL, '2026-05-15 14:30:11', '2026-05-15 14:30:11'),
(441, 61, 6, 'Lấy thịt bò muối và rau củ ra khỏi nồi rồi bày ra đĩa.', NULL, '2026-05-15 14:30:11', '2026-05-15 14:30:11'),
(442, 61, 7, 'Sử dụng nước nấu theo hai cách; như một loại rượu nồi mà một số người thích uống hoặc giảm bớt nó để làm nước sốt hoặc nước xốt để rưới lên bữa ăn.', NULL, '2026-05-15 14:30:11', '2026-05-15 14:30:11'),
(443, 62, 1, 'Nghiền nửa củ hành tây và đặt sang một bên. Cắt phần hành còn lại và chiên bơ ở nhiệt độ thấp/trung bình cho đến khi có màu caramen.', NULL, '2026-05-15 14:30:13', '2026-05-15 14:30:13'),
(444, 62, 2, 'Trong một bát, trộn đều thịt bò xay, hành tây nghiền, muối, tiêu, nhục đậu khấu, tinh bột khoai tây/ngô và nước.', NULL, '2026-05-15 14:30:13', '2026-05-15 14:30:13'),
(445, 62, 3, 'Tạo thành xúc xích và cắt 6 miếng. Dùng dao tạo hoa văn lưới nhẹ trên mỗi miếng bánh.', NULL, '2026-05-15 14:30:13', '2026-05-15 14:30:13'),
(446, 62, 4, 'Nâu vàng cả hai mặt của karbonader trong bơ ở nhiệt độ cao, sau đó giảm nhiệt độ xuống và chiên thêm 2 – 3 phút nữa.', NULL, '2026-05-15 14:30:13', '2026-05-15 14:30:13'),
(447, 62, 5, 'Phục vụ món karbonader và hành tây với khoai tây, đậu Hà Lan hầm và nước sốt nâu cho bữa tối hoặc trên một lát bánh mì cho bữa trưa hoặc bữa ăn nhẹ.', NULL, '2026-05-15 14:30:13', '2026-05-15 14:30:13'),
(448, 63, 1, 'Đun sôi 4 cốc nước trong lò nướng hoặc nồi súp kiểu Hà Lan. Thêm thịt bò, tỏi và gừng vào rồi khuấy đều. Đun sôi nhẹ, đậy nắp và nấu, thỉnh thoảng khuấy trong 20 phút. Nếu bạn thấy có váng bọt ở trên, đừng lo lắng, bạn chỉ cần múc nó đi hoặc khuấy lại.', NULL, '2026-05-15 14:30:15', '2026-05-15 14:30:15'),
(449, 63, 2, 'Tắt bếp và để ráo nước, nhưng để dành phần nước thừa để dùng sau.', NULL, '2026-05-15 14:30:15', '2026-05-15 14:30:15'),
(450, 63, 3, 'Cho nồi hoặc lò nướng Hà Lan lên lửa vừa cùng với 2 thìa dầu ăn. Khi dầu đã sủi bọt, thêm hành vào và nấu, thỉnh thoảng khuấy cho đến khi mềm, từ 5 đến 7 phút.', NULL, '2026-05-15 14:30:15', '2026-05-15 14:30:15'),
(451, 63, 4, 'Thêm cà chua vào hành tây và tiếp tục nấu, thỉnh thoảng khuấy cho đến khi cà chua rơi ra, từ 3 đến 5 phút.', NULL, '2026-05-15 14:30:15', '2026-05-15 14:30:15'),
(452, 63, 5, 'Thêm thịt bò đã ráo nước vào hỗn hợp cà chua và hành tây rồi khuấy đều. Tiếp tục nấu trên lửa vừa trong 5 phút, thỉnh thoảng khuấy.', NULL, '2026-05-15 14:30:15', '2026-05-15 14:30:15'),
(453, 63, 6, 'Thêm ớt bột, hạt tiêu, bột cà ri, bột cà chua và muối cho vừa ăn rồi khuấy đều.', NULL, '2026-05-15 14:30:15', '2026-05-15 14:30:15'),
(454, 63, 7, 'Thêm lại lượng nước dư dùng để nấu thịt bò, cùng với lượng nước vừa đủ để ngập. Đun sôi, giảm nhiệt và đun nhỏ lửa, không đậy nắp, thỉnh thoảng khuấy trong khoảng 1 giờ hoặc cho đến khi thịt mềm và nước sốt đặc lại. Thêm nước bổ sung nếu cà ri thịt bò của bạn bắt đầu khô và dính, hoặc nếu bạn muốn cà ri của bạn có độ đặc sệt hơn.', NULL, '2026-05-15 14:30:15', '2026-05-15 14:30:15'),
(455, 63, 8, 'Khi cà ri bò đã sẵn sàng, tắt bếp, nếm thử và điều chỉnh gia vị theo ý muốn. Trang trí với ớt tươi và ngò.', NULL, '2026-05-15 14:30:15', '2026-05-15 14:30:15'),
(457, 64, 1, 'Cho gừng, tỏi, sả, rau mùi và 1 quả ớt vào máy xay thực phẩm rồi xay nhuyễn. Đun nóng dầu trong chảo ở lửa nhỏ. Thêm bột nhuyễn và nấu trong 5 phút. Cho thịt bò, đậu nành, ngũ vị hương, đường và nước kho vào trộn đều. Đậy nắp và đun sôi, sau đó giảm nhiệt và đun nhỏ lửa trong 1 giờ 15 phút. Đậy nắp và nấu thêm 15 phút nữa cho đến khi thịt bò mềm.', NULL, '2026-05-15 14:30:20', '2026-05-16 12:35:33'),
(459, 64, 2, 'Ngay trước khi ăn, hãy chuẩn bị mì theo hướng dẫn trên bao bì. Để ráo nước rồi chia ra 2 tô và dùng thìa rưới lên thịt bò hầm. Ăn kèm với ớt và lá rau mùi còn lại, thêm chanh để ép.', NULL, '2026-05-15 14:30:20', '2026-05-16 12:35:33'),
(460, 65, 1, 'Thêm một chút muối và dầu mè vào thịt bò băm. Trộn đều và đặt sang một bên.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(461, 65, 2, 'Trộn 1 thìa bột ngô với 2, ½ thìa nước vào tô nhỏ để tạo thành bột nước.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(462, 65, 3, 'Đậu phụ cắt thành khối vuông (khoảng 2cm). Đun sôi một lượng nước lớn rồi thêm một chút muối. Cho đậu phụ vào và nấu trong 1 phút. Di chuyển ra ngoài và thoát nước.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(463, 65, 4, 'Bắt chảo lên bếp đun nóng khoảng 2 thìa dầu, cho thịt băm vào chiên giòn. Gắp thịt bò ra và để lại dầu.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(464, 65, 5, 'Chiên doubanjiang trong 1 phút trên lửa nhỏ rồi cho tỏi, hành lá trắng, gừng và đậu đen lên men vào nấu trong 30 giây cho đến khi có mùi thơm. Sau đó trộn hạt tiêu vào.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(465, 65, 6, 'Thêm nước vào gia vị và đun sôi trên lửa lớn. Nhẹ nhàng trượt các khối đậu phụ. Thêm nước tương nhạt và thịt bò. Sau khi đun sôi, giảm lửa nhỏ rồi đun nhỏ lửa trong 6-8 phút. Sau đó thêm tỏi xanh xắt nhỏ.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(466, 65, 7, 'Khuấy đều tinh bột nước rồi đổ một nửa hỗn hợp vào nồi đun sôi. Đợi khoảng 30 giây rồi đổ nửa còn lại. Bạn có thể nêm nếm đậu phụ một chút và thêm chút muối nếu chưa đủ mặn. Nhân tiện, nếu bạn cảm thấy nó quá cay, hãy thêm một ít đường có thể làm dịu hương vị. Nhưng hãy cẩn thận vì nước dùng lúc này rất nóng.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(467, 65, 8, 'Chuyển ra ngoài khi gần như tất cả gia vị đã dính vào các viên đậu phụ. Rắc bột tiêu Tứ Xuyên (tùy khẩu vị) và tỏi băm nhỏ nếu dùng.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(468, 65, 9, 'Ăn ngay với cơm hấp.', NULL, '2026-05-15 14:30:23', '2026-05-15 14:30:23'),
(469, 66, 1, 'Làm nóng lò ở nhiệt độ 200C/180C quạt/gas 6, sau đó rang đậu phộng trên khay nướng trong 5 phút cho đến khi có màu vàng nâu. Khi đủ nguội để xử lý, hãy cắt nhỏ. Giảm nhiệt độ lò/quạt xuống 180C/160C 4.', NULL, '2026-05-15 14:30:25', '2026-05-15 14:30:25'),
(470, 66, 2, 'Đun nóng 2 muỗng canh nước cốt dừa trong một cái nồi lớn có nắp đậy. Thêm bột cà ri và chiên trong 1 phút, sau đó cho thịt bò vào xào cho đến khi được phủ đều và kín. Khuấy phần dừa còn lại với nửa lon nước, khoai tây, hành tây, lá chanh, quế, me, đường, nước mắm và hầu hết đậu phộng. Đun sôi, sau đó đậy nắp và nấu trong lò trong 2 giờ cho đến khi thịt bò mềm.', NULL, '2026-05-15 14:30:25', '2026-05-15 14:30:25'),
(471, 66, 3, 'Rắc ớt thái lát và số đậu phộng còn lại, sau đó dùng ngay từ đĩa với cơm hoa nhài.', NULL, '2026-05-15 14:30:25', '2026-05-15 14:30:25'),
(472, 67, 1, 'Chuẩn bị bít tết: Nêm bít tết với muối và hạt tiêu. Nướng một mặt cho đến khi chín một nửa.', NULL, '2026-05-15 14:30:27', '2026-05-15 14:30:27'),
(473, 67, 2, 'Thêm lớp phủ bên trên: Phết nước sốt cà chua lên mặt đã nấu chín, sau đó thêm phô mai, lá oregano và ô liu.', NULL, '2026-05-15 14:30:27', '2026-05-15 14:30:27'),
(474, 67, 3, 'Nướng xong: Nướng cho đến khi phô mai tan chảy và sủi bọt.', NULL, '2026-05-15 14:30:27', '2026-05-15 14:30:27'),
(475, 67, 4, 'Dùng: Cắt miếng và dùng nóng.', NULL, '2026-05-15 14:30:27', '2026-05-15 14:30:27'),
(476, 67, 5, 'Lời khuyên chuyên nghiệp:', NULL, '2026-05-15 14:30:27', '2026-05-15 14:30:27'),
(477, 67, 6, 'Làm mềm matambre bằng cách chấm nhẹ lên cả hai mặt. Điều này giúp cơm chín đều hơn và thấm gia vị.', NULL, '2026-05-15 14:30:27', '2026-05-15 14:30:27'),
(478, 67, 7, 'Nướng trước matambre trên vỉ nướng trước khi thêm lớp phủ bên trên để đảm bảo nó chín hoàn toàn mà không làm cháy phô mai.', NULL, '2026-05-15 14:30:27', '2026-05-15 14:30:27'),
(479, 68, 1, 'Nêm các miếng cốt lết: Muối và hạt tiêu.', NULL, '2026-05-15 14:30:29', '2026-05-15 14:30:29'),
(480, 68, 2, 'Bánh mỳ cốt lết: Nhúng từng miếng cốt lết vào trứng, sau đó phủ một lớp hỗn hợp vụn bánh mì, mùi tây và tỏi.', NULL, '2026-05-15 14:30:29', '2026-05-15 14:30:29'),
(481, 68, 3, 'Chiên: Đun nóng dầu trong chảo lớn trên lửa vừa. Chiên các miếng cốt lết cho đến khi chín vàng, khoảng 3-4 phút mỗi mặt.', NULL, '2026-05-15 14:30:29', '2026-05-15 14:30:29'),
(482, 68, 4, 'Phục vụ: Dùng nóng với chanh hoặc salad ăn kèm.', NULL, '2026-05-15 14:30:29', '2026-05-15 14:30:29'),
(483, 68, 5, 'Lời khuyên chuyên nghiệp:', NULL, '2026-05-15 14:30:29', '2026-05-15 14:30:29'),
(484, 68, 6, 'Để có lớp vỏ giòn hơn, hãy dùng vụn bánh mì panko trộn với phô mai Parmesan bào mịn.', NULL, '2026-05-15 14:30:29', '2026-05-15 14:30:29'),
(485, 68, 7, 'Nhẹ nhàng giã các miếng cốt lết đến độ dày đều để nấu chín đồng đều.', NULL, '2026-05-15 14:30:29', '2026-05-15 14:30:29'),
(486, 69, 1, 'Làm nóng lò ở 200C/400F/Gas 6.', NULL, '2026-05-15 14:30:32', '2026-05-15 14:30:32'),
(487, 69, 2, 'Đun nóng dầu trong chảo sâu lòng và chiên thịt bò băm trong 4-5 phút, dùng thìa gỗ bẻ nhỏ khi thịt có màu nâu.', NULL, '2026-05-15 14:30:32', '2026-05-15 14:30:32'),
(488, 69, 3, 'Thêm hành tây và nấu trong 2-3 phút, sau đó cho cà chua xay nhuyễn vào và nấu thêm 2-3 phút nữa. Khuấy bột và nấu thêm một phút nữa, sau đó thêm nấm cắt nhỏ, thịt bò hoặc thịt bò kho và một chút sốt Worcestershire. Đun sôi, sau đó giảm nhiệt, đậy nắp chảo và đun nhỏ lửa trong 20 phút. Đặt sang một bên và để nguội, sau đó biến hỗn hợp thịt thành đĩa bánh một lít.', NULL, '2026-05-15 14:30:32', '2026-05-15 14:30:32'),
(489, 69, 4, 'Lăn bánh ngọt trên bề mặt đã phủ bột mì cho đến khi nó lớn hơn đĩa bánh một chút. Nhẹ nhàng phủ bánh lên trên đĩa, ấn chặt vào các cạnh. Cắt tỉa, sau đó định hình các cạnh thành hình rãnh.', NULL, '2026-05-15 14:30:32', '2026-05-15 14:30:32'),
(490, 69, 5, 'Cắt một số hình chiếc lá ra khỏi phần trang trí bánh ngọt và trang trí mặt trên của chiếc bánh, dán chúng lên bánh ngọt với lòng đỏ trứng đã đánh bông.', NULL, '2026-05-15 14:30:32', '2026-05-15 14:30:32'),
(491, 69, 6, 'Tạo ba hoặc bốn khe trên bánh để hơi nước thoát ra ngoài, sau đó phết phần lòng đỏ trứng đã đánh còn lại lên bánh và nướng trong lò khoảng 20-25 phút hoặc cho đến khi có màu vàng nâu.', NULL, '2026-05-15 14:30:32', '2026-05-15 14:30:32'),
(492, 69, 7, 'Để phục vụ, cắt thành nêm.', NULL, '2026-05-15 14:30:32', '2026-05-15 14:30:32'),
(494, 70, 1, 'Để làm ớt, đun nóng dầu trong chảo và xào hành tây trong 5 phút cho đến khi mềm. Thêm gia vị; chiên trong 1 phút. Khuấy thịt bò và nấu trong vài phút. Thêm bột cà chua, nước kho và quế. Khuấy đều, đun sôi, sau đó đun nhỏ lửa trong 15-20 phút cho đến khi còn lại rất ít chất lỏng. Thêm đậu 5 phút trước khi kết thúc nấu. Kiểm tra gia vị và để nguội.', NULL, '2026-05-15 14:30:34', '2026-05-16 12:35:33'),
(496, 70, 2, 'Làm nóng lò nướng ở 200C/quạt 180C/gas 6. Dùng dao cắt bánh ngọt 7cm, dập 12 hình tròn từ bánh ngọt. Dùng để lót khay bánh muffin nhỏ 12 lỗ, dùng nĩa chọc vào đế bánh và nướng trong 10 phút. Lấy ra khỏi lò và để nguội trên khay lưới. Lặp lại với bánh ngọt còn lại.', NULL, '2026-05-15 14:30:34', '2026-05-16 12:35:33'),
(498, 70, 3, 'Trong khi đó, luộc khoai tây trong nước sôi cho đến khi mềm. Để ráo nước, nghiền nhuyễn với kem chua và gia vị rồi đảo qua hẹ. Múc 1-2 thìa ớt trộn vào vỏ bánh ngọt và phủ lên trên một thìa cà phê nghiền. Nghiền nhuyễn bằng nĩa; quay trở lại lò nướng trong 15 phút hoặc cho đến khi vàng.', NULL, '2026-05-15 14:30:34', '2026-05-16 12:35:33'),
(499, 71, 1, 'Để làm thuốc, trộn đều muối, muối hồng, tiêu đen, rau mùi, đường, lá nguyệt quế và đinh hương trong một bát nhỏ. Phủ toàn bộ ức bằng thuốc chữa và cho vào một túi nhựa cực lớn có thể khóa lại. Đặt ở nơi lạnh nhất của tủ lạnh và để trong 4 ngày, lật ức hai lần một ngày.', NULL, '2026-05-15 14:30:37', '2026-05-15 14:30:37'),
(500, 71, 2, 'Lấy thịt ức ra khỏi túi và rửa sạch càng nhiều càng tốt dưới vòi nước lạnh. Đặt thịt ức vào một thùng chứa lớn, đổ đầy nước và ngâm trong 2 giờ, thay nước sau mỗi 30 phút. Lấy ra khỏi nước và lau khô bằng khăn giấy.', NULL, '2026-05-15 14:30:37', '2026-05-15 14:30:37'),
(501, 71, 3, 'Để làm hỗn hợp chà xát, trộn hạt tiêu đen, rau mùi, ớt bột, bột tỏi, bột hành tây, thì là, mù tạt, hạt cần tây và ớt đỏ nghiền vào một cái bát nhỏ. Phủ toàn bộ ức bằng chà xát.', NULL, '2026-05-15 14:30:37', '2026-05-15 14:30:37'),
(502, 71, 4, 'Đốt lửa hoặc nướng ở nhiệt độ 225 độ, thêm các khối gỗ hút thuốc khi ở nhiệt độ. Khi gỗ bốc cháy và tạo ra khói, đặt miếng ức vào, mặt mỡ hướng lên trên và hun khói cho đến khi nhiệt kế đọc tức thời ghi 165 độ khi đưa vào phần dày nhất của miếng ức, khoảng 6 giờ.', NULL, '2026-05-15 14:30:37', '2026-05-15 14:30:37'),
(503, 71, 5, 'Chuyển thịt ức vào chảo rang lớn có giá chữ V. Đặt chảo rang lên hai đầu đốt trên bếp và đổ đầy nước khoảng 1 inch. Đun sôi nước ở nhiệt độ cao, giảm nhiệt ở mức trung bình, đậy chảo rang bằng giấy nhôm và hấp ức cho đến khi nhiệt kế đọc tức thời ghi 180 độ khi đưa vào phần dày nhất của thịt, từ 1 đến 2 giờ, thêm nước nóng nếu cần.', NULL, '2026-05-15 14:30:37', '2026-05-15 14:30:37'),
(504, 71, 6, 'Chuyển thịt ức vào thớt và để nguội một chút. Cắt lát và phục vụ, tốt nhất là trên lúa mạch đen với mù tạt.', NULL, '2026-05-15 14:30:37', '2026-05-15 14:30:37'),
(505, 72, 1, 'Làm nóng lò nướng ở mức cao. Cho thịt bò vào chảo chiên sâu lòng trong lò nướng ở nhiệt độ cao trong 5 phút. Trong khi đó, dùng nĩa chọc vào cà tím, sau đó cho vào lò vi sóng ở chế độ Cao trong 3-5 phút cho đến khi mềm. Trộn sữa chua, trứng và parmesan với nhau rồi thêm một chút gia vị.', NULL, '2026-05-15 14:30:38', '2026-05-15 14:30:38'),
(506, 72, 2, 'Khuấy cà chua, khoai tây nghiền nhuyễn và khoai tây với thịt bò cùng một ít gia vị rồi đun nóng. Dùng thìa làm mịn bề mặt hỗn hợp thịt bò, sau đó cắt lát cà tím đã nấu chín và xếp lên trên. Đổ hỗn hợp sữa chua lên cà tím, dàn đều rồi nướng cho đến khi mặt trên chín và chuyển sang màu vàng.', NULL, '2026-05-15 14:30:38', '2026-05-15 14:30:38'),
(507, 73, 1, 'Xào hành tây với 3-4 thìa dầu ô liu', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(508, 73, 2, 'Thêm thịt bò viên hoặc thịt gà cốt lết vào, nướng trong 3-4 phút mỗi mặt', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(509, 73, 3, 'Thêm 1 lít nước hoặc vừa đủ ngập thịt', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(510, 73, 4, 'Nấu trên lửa vừa cho đến khi thịt chín (mình thường nấu trong nồi áp suất và ấn trong 5 phút)', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(511, 73, 5, 'Thêm Mulukhyia đông lạnh vào và khuấy cho đến khi tan hoàn toàn rồi đun sôi.', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(512, 73, 6, 'Trong một chảo khác, thêm 1/4 đến 1/2 cốc dầu ô liu và vài tép tỏi rồi nấu trên lửa vừa thấp cho đến khi bạn có thể ngửi thấy mùi tỏi (không làm nâu tỏi, tỏi sẽ có vị đắng)', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(513, 73, 7, 'Thêm dầu và tỏi vào mulukhyia rồi giảm nhiệt và đun nhỏ lửa trong 5-10 phút', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(514, 73, 8, 'Thêm muối cho vừa ăn', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(515, 73, 9, 'Ăn kèm với một lượng lớn nước cốt chanh.', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(516, 73, 10, 'Bạn có thể dùng nó với một ít cơm hạt ngắn hoặc một ít bánh mì pita', NULL, '2026-05-15 14:30:41', '2026-05-15 14:30:41'),
(517, 74, 1, 'Trộn đuôi bò với hành tây, hành lá, tỏi, gừng, ớt, nước tương, húng tây, muối và tiêu. Đun nóng dầu thực vật trong chảo lớn trên lửa vừa cao. Chiên đuôi bò trong chảo cho đến khi chín vàng toàn bộ, khoảng 10 phút. Cho vào nồi áp suất, đổ vào 375ml nước. Nấu ở áp suất trong 25 phút, sau đó tắt bếp và tháo nắp theo hướng dẫn của nhà sản xuất.', NULL, '2026-05-15 14:30:44', '2026-05-15 14:30:44'),
(518, 74, 2, 'Thêm đậu tằm và quả pimento vào, đun sôi trên lửa vừa cao. Hòa tan bột ngô với 2 thìa nước rồi cho vào đuôi bò đang sôi lăn tăn. Nấu và khuấy vài phút cho đến khi nước sốt đặc lại và đậu mềm.', NULL, '2026-05-15 14:30:44', '2026-05-15 14:30:44'),
(519, 75, 1, 'Rây bột mì và muối vào tô trộn lớn.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(520, 75, 2, 'Dùng thìa đẩy lòng đỏ trứng qua rây mịn vào bột.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(521, 75, 3, 'Thêm trứng sống và trộn đều.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(522, 75, 4, 'Đánh bơ 1 muỗng canh mỗi lần.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(523, 75, 5, 'Đặt bột lên bề mặt đã rắc bột mì và nhào cho đến khi mịn và đàn hồi, sau đó bọc trong giấy sáp và để trong tủ lạnh cho đến khi cứng lại (ít nhất 30 phút).', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(524, 75, 6, 'Trong một chiếc chảo nặng, làm tan chảy 2 thìa bơ trên lửa vừa; xào hành tây và rutabaga cho đến khi hành tây mềm và trong suốt (5 phút).', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(525, 75, 7, 'Cho hành tây, rutabaga và thịt bò vào máy xay thịt hai lần nếu có, nếu không chỉ cần cắt chúng càng mịn càng tốt.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(526, 75, 8, 'Đun chảy 4 thìa bơ còn lại trên lửa vừa và thêm hỗn hợp thịt vào.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(527, 75, 9, 'Nấu trên lửa nhỏ, thỉnh thoảng khuấy cho đến khi toàn bộ chất lỏng bay hơi và hỗn hợp đủ đặc để giữ được hình dạng.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(528, 75, 10, 'Tắt bếp và để nguội, sau đó cho 1 quả trứng vào khuấy đều, nêm muối và tiêu.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(529, 75, 11, 'Làm nóng lò ở nhiệt độ 350°F.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(530, 75, 12, 'Trên bề mặt đã phủ một ít bột mì, cán bột thành hình chữ nhật 13x8\" (dày 1/8\").', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(531, 75, 13, 'Đổ nhân vào giữa hình chữ nhật theo chiều dọc, chừa khoảng trống khoảng 1 inch ở mỗi đầu.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(532, 75, 14, 'Nhẹ nhàng chải các cạnh dài bằng nước lạnh, sau đó gấp một trong các cạnh dài lên phần nhân và mặt còn lại lên trên.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(533, 75, 15, 'Chải các đầu ngắn bằng nước lạnh và gấp chúng lên trên, bao bọc phần nhân.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(534, 75, 16, 'Đặt mặt bánh ngọt úp xuống khay nướng và phết đều phần trứng bác còn lại lên trên.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(535, 75, 17, 'Nướng trong lò làm nóng trước cho đến khi có màu vàng nâu đậm (30 phút).', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(536, 75, 18, 'Cắt bánh ngọt theo đường chéo thành những miếng dài 1,5 inch và dùng làm món khai vị hoặc dùng kèm với súp.', NULL, '2026-05-15 14:30:46', '2026-05-15 14:30:46'),
(537, 76, 1, 'Trong một nồi nước muối lớn, nấu khoai tây cho đến khi chúng thật mềm. Làm khô hạn.', NULL, '2026-05-15 14:31:00', '2026-05-15 14:31:00'),
(538, 76, 2, 'Dùng máy nghiền nghiền nhuyễn khoai tây với ít nhất 30 ml (2 thìa canh) bơ. Dùng máy trộn điện, xay nhuyễn với sữa. Nêm muối và hạt tiêu. Đặt sang một bên.', NULL, '2026-05-15 14:31:00', '2026-05-15 14:31:00'),
(539, 76, 3, 'Để giá đỡ ở vị trí giữa, làm nóng lò trước ở nhiệt độ 190°C (375°F).', NULL, '2026-05-15 14:31:00', '2026-05-15 14:31:00'),
(540, 76, 4, 'Trong một cái chảo lớn, phi vàng hành tây với phần bơ còn lại. Thêm thịt và nấu cho đến khi vàng nâu. Nêm muối và hạt tiêu. Hủy bỏ khỏi nhiệt.', NULL, '2026-05-15 14:31:00', '2026-05-15 14:31:00'),
(541, 76, 5, 'Ấn nhẹ miếng thịt xuống đáy khay nướng hình vuông 20 cm (8 inch). Phủ ngô và khoai tây nghiền lên. Rắc ớt bột và mùi tây.', NULL, '2026-05-15 14:31:00', '2026-05-15 14:31:00'),
(542, 76, 6, 'Nướng trong khoảng 30 phút. Nấu xong dưới lò gà thịt. Để nguội trong 10 phút.', NULL, '2026-05-15 14:31:00', '2026-05-15 14:31:00'),
(543, 77, 1, 'BƯỚC 1', NULL, '2026-05-15 14:31:02', '2026-05-15 14:31:02'),
(544, 77, 2, 'Chà tỏi lên miếng bít tết, sau đó cho vào túi đựng bánh sandwich và rắc dầu ô liu, giấm sherry và cọng mùi tây vào. Trộn đều mọi thứ lại với nhau, sau đó dùng cây lăn để đập miếng bít tết vài lần. Để trong 1-2 giờ.', NULL, '2026-05-15 14:31:02', '2026-05-15 14:31:02'),
(545, 77, 3, 'BƯỚC 2', NULL, '2026-05-15 14:31:02', '2026-05-15 14:31:02'),
(546, 77, 4, 'Để làm nước sốt, cho tất cả nguyên liệu vào máy xay sinh tố với 1 muỗng canh nước và xay cho đến khi mịn nhất có thể. Điều này sẽ tạo ra nhiều hơn mức bạn cần cho công thức nhưng sẽ giữ được trong một tuần trong lọ kín.', NULL, '2026-05-15 14:31:02', '2026-05-15 14:31:02'),
(547, 77, 5, 'BƯỚC 3', NULL, '2026-05-15 14:31:02', '2026-05-15 14:31:02');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(548, 77, 6, 'Đun nóng vỉ nướng hoặc chảo rán ở mức cao. Loại bỏ cọng tỏi và mùi tây khỏi miếng bít tết và nêm gia vị thật kỹ. Áp chảo bít tết mỗi mặt trong 2 phút rồi đặt lên đĩa. Đặt nửa ciabatta lên đĩa, nướng úp mặt xuống để thấm hết nước.', NULL, '2026-05-15 14:31:02', '2026-05-15 14:31:02'),
(549, 77, 7, 'BƯỚC 4', NULL, '2026-05-15 14:31:02', '2026-05-15 14:31:02'),
(550, 77, 8, 'Cắt miếng bít tết sau đó nhồi vào cuộn với nước sốt xanh và tên lửa.', NULL, '2026-05-15 14:31:02', '2026-05-15 14:31:02'),
(551, 78, 1, 'Đậu thận khô rửa sạch.. sau đó ngâm với nước trong một cái bát sâu lòng. Hãy nhớ rằng khi ngâm chúng sẽ nở ra ít nhất gấp ba lần kích thước ban đầu, vì vậy hãy thêm nhiều nước vào bát. Ngâm chúng qua đêm hoặc ít nhất 2 giờ để quá trình nấu diễn ra nhanh hơn. Tôi đổ nước mà chúng đã ngâm sau khi nó hoạt động.', NULL, '2026-05-15 14:31:07', '2026-05-15 14:31:07'),
(552, 78, 2, 'Yêu cầu người bán thịt cắt bím tóc muối thành những miếng dài 2 inch vì sẽ rất khó cắt bằng dao làm bếp thông thường. Rửa sạch, sau đó đặt một nồi sâu với nước vào và đun sôi. Nấu trong 20 phút, sau đó vớt ra + rửa sạch và lặp lại (đun sôi lại trong nước). Mục đích là làm cho các miếng đuôi lợn mềm và loại bỏ hầu hết muối đã được ngâm trong đó.', NULL, '2026-05-15 14:31:07', '2026-05-15 14:31:07'),
(553, 78, 3, 'Đã đến lúc bắt đầu món súp. Cho tất cả mọi thứ vào nồi (trừ bột mì và khoai tây), sau đó đổ nước vào và đặt trên lửa lớn để đun sôi. Khi nước sôi, hớt bỏ váng/bọt ở trên và bỏ đi. Giảm nhiệt đến mức sôi nhẹ và để nấu trong 1 giờ 15 phút.. về cơ bản cho đến khi đậu mềm và bắt đầu tách rời.', NULL, '2026-05-15 14:31:07', '2026-05-15 14:31:07'),
(554, 78, 4, 'Bây giờ là lúc thêm khoai tây (và Yams, v.v. nếu bạn thêm nó) cũng như nước cốt dừa và tiếp tục nấu trong 15 phút.', NULL, '2026-05-15 14:31:07', '2026-05-15 14:31:07'),
(555, 78, 5, 'Bây giờ là thời điểm thích hợp để bắt đầu làm loại bột cơ bản cho món bánh bao quay. Trộn bột mì và nước (thêm một chút muối nếu muốn) cho đến khi thu được khối bột mềm/mịn. Để yên trong 5 phút, sau đó múc từng muỗng canh và lăn giữa hai bàn tay để tạo thành hình điếu thuốc.', NULL, '2026-05-15 14:31:07', '2026-05-15 14:31:07'),
(556, 78, 6, 'Thêm chúng vào nồi, khuấy đều và tiếp tục đun sôi thêm 15 phút nữa.', NULL, '2026-05-15 14:31:07', '2026-05-15 14:31:07'),
(557, 78, 7, 'Bạn sẽ nhận thấy rằng tôi không thêm muối vào nồi vì lượng muối còn lại từ bím tóc muối sẽ đủ để nêm món ăn này. Tuy nhiên bạn có thể nếm thử và điều chỉnh cho phù hợp. Hãy tóm tắt lại phần thời gian của mọi thứ để bạn không bị nhầm lẫn. Nấu phần đáy súp trong 1 giờ 15 phút hoặc cho đến khi mềm, sau đó thêm khoai tây vào nấu trong 15 phút, sau đó thêm bánh bao vào nấu thêm 15 phút nữa. Hãy nhớ rằng món súp này sẽ đặc lại một chút khi nguội.', NULL, '2026-05-15 14:31:07', '2026-05-15 14:31:07'),
(558, 78, 8, 'Mặc dù đây không phải là công thức nấu ăn truyền thống của bất kỳ hòn đảo cụ thể nào, nhưng các phiên bản của món súp này (đôi khi được gọi là đậu hầm) có thể được tìm thấy trên khắp vùng Caribe, Châu Mỹ Latinh và Châu Phi. Một bát canh thịnh soạn này chắc chắn sẽ khiến bạn buồn ngủ (có người gọi là mệt mỏi dân tộc). Bạn chắc chắn có thể đông lạnh thức ăn thừa và hâm nóng vào ngày khác.', NULL, '2026-05-15 14:31:07', '2026-05-15 14:31:07'),
(559, 79, 1, 'Trộn tất cả các thành phần trong một cái bát.', NULL, '2026-05-15 14:31:09', '2026-05-15 14:31:09'),
(560, 79, 2, 'Làm nóng chảo hoặc vỉ nướng với một ít dầu thực vật.', NULL, '2026-05-15 14:31:09', '2026-05-15 14:31:09'),
(561, 79, 3, 'Đổ hỗn hợp lên chảo và đặt một miếng bánh mì baguette có mặt mở lên trên.', NULL, '2026-05-15 14:31:09', '2026-05-15 14:31:09'),
(562, 79, 4, 'Dùng thìa ấn vào bánh mì và nướng trong 2 phút.', NULL, '2026-05-15 14:31:09', '2026-05-15 14:31:09'),
(563, 79, 5, 'Lật bánh lại để bánh giòn một chút.', NULL, '2026-05-15 14:31:09', '2026-05-15 14:31:09'),
(564, 79, 6, 'Lấy bánh ra khỏi chảo và cắt bánh mì thành từng phần nhỏ.', NULL, '2026-05-15 14:31:09', '2026-05-15 14:31:09'),
(565, 79, 7, 'Thêm sốt mayonnaise và/hoặc Sambal trước khi cắt bánh sandwich (tùy chọn).', NULL, '2026-05-15 14:31:09', '2026-05-15 14:31:09'),
(566, 80, 1, 'Trong lò nướng kiểu Hà Lan hoặc nồi nấu chậm, thêm tất cả gia vị, nước luộc thịt bò và nước cốt chanh. Khuấy đều để hòa quyện..', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(567, 80, 2, 'Thêm thịt bò vào và đảo đều, rưới một ít nước sốt lên trên.', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(568, 80, 3, 'Đậy nắp và nấu ở nhiệt độ thấp trong 8-10 giờ.', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(569, 80, 4, 'Sau khi nấu chín, lấy thịt bò ra và dùng 2 chiếc nĩa để xé nhỏ. Loại bỏ bất kỳ chất béo dư thừa.', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(570, 80, 5, 'Hớt bỏ phần mỡ phía trên phần chất lỏng còn lại.', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(571, 80, 6, 'Trộn thịt bò thái nhỏ vào nước sốt. Giữ ấm cho đến khi bạn sẵn sàng phục vụ.', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(572, 80, 7, 'Tạo lớp bọc bằng cách phết nước sốt tỏi lên bánh pita. Phủ thịt bò lên trên và thêm đồ trang trí theo ý thích của bạn.', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(573, 80, 8, 'Gấp nó theo phong cách burrito.', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(574, 80, 9, 'Làm nóng chảo nướng và nướng bọc.', NULL, '2026-05-15 14:31:11', '2026-05-15 14:31:11'),
(575, 81, 1, '1. Làm nóng lò ở nhiệt độ 425 độ. Rửa và lau khô tất cả sản phẩm. Cắt khoai tây thành miếng 1/2 inch. Cắt, gọt vỏ và cắt cà rốt theo đường chéo thành từng miếng dày 1/2 inch. Cắt và thái mỏng hành lá, tách lòng trắng khỏi rau xanh; thái nhỏ lòng trắng. Bóc vỏ và băm nhuyễn tỏi.', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(576, 81, 2, '2. Trong một tô vừa, ngâm bánh mì với 2 muỗng canh nước (4 muỗng canh cho 4 phần ăn); chia tay cho đến khi nhão. Khuấy thịt bò, sriracha, lòng trắng hành lá, một nửa số tỏi, muối (chúng tôi sử dụng 3/4 muỗng cà phê muối kosher; 11/2 muỗng cà phê cho 4) và hạt tiêu. Tạo thành hai ổ bánh cao 1 inch (bốn ổ cho 4 ổ). Đặt trên một mặt của một tấm nướng bánh. Đổ cà rốt lên mặt trống của tờ giấy với một chút dầu, muối và hạt tiêu. (Đối với 4 người, trải bánh mì thịt ra toàn bộ tấm và thêm cà rốt vào tấm thứ hai.) Nướng trong 20 phút (sau đó chúng ta sẽ tráng men bánh mì thịt).', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(577, 81, 3, '3. Trong khi đó, đặt khoai tây vào nồi vừa với lượng nước muối vừa đủ ngập 2 inch. Đun sôi và nấu cho đến khi thật', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(578, 81, 4, 'đấu thầu, 12-15 phút. Dự trữ 1/2 chén nước nấu khoai tây, sau đó để ráo nước. Trong khi nấu khoai tây, trong một bát nhỏ, trộn nước tương, bột tỏi, 1/4 cốc sốt cà chua (1/2 cốc cho 4 phần ăn) và 2 thìa cà phê đường (4 thìa cà phê cho 4 phần ăn).', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(579, 81, 5, '4. Sau khi bánh mì thịt và cà rốt đã nướng được 20 phút, hãy lấy ra khỏi lò. Múc một nửa lớp sốt cà chua lên bánh mì thịt (tiết kiệm', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(580, 81, 6, 'phần còn lại để phục vụ); quay trở lại lò nướng cho đến khi cà rốt chín vàng và mềm, bánh mì thịt chín và men dính lại, thêm 4-5 phút nữa.', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(581, 81, 7, '5. Trong khi đó, đun chảy 2 muỗng canh bơ (4 muỗng canh cho 4 phần ăn) trong nồi dùng cho khoai tây trên lửa vừa. Thêm tỏi còn lại và nấu', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(582, 81, 8, 'cho đến khi có mùi thơm, 30 giây. Thêm khoai tây và 1/4 muỗng cà phê wasabi. Nghiền, thêm một ít nước nấu khoai tây dành riêng nếu cần cho đến khi mịn. Nêm muối và hạt tiêu. (Nếu bạn thích ăn cay thì cho thêm wasabi vào nhé!)', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(583, 81, 9, '6. Chia bánh mì thịt, khoai tây nghiền và cà rốt nướng vào các đĩa. Rắc thêm hành lá và dùng kèm với sốt cà chua còn sót lại để chấm.', NULL, '2026-05-15 14:31:16', '2026-05-15 14:31:16'),
(584, 82, 1, 'Cho hành tây và dầu vào chảo lớn rồi chiên trên lửa khá cao trong 3-4 phút. Thêm tỏi và thịt băm vào xào cho đến khi cả hai đều có màu nâu. Thêm nấm và thảo mộc vào nấu thêm vài phút nữa.', NULL, '2026-05-15 14:31:19', '2026-05-15 14:31:19'),
(585, 82, 2, 'Khuấy cà chua, thịt bò kho, sốt cà chua hoặc bột nhuyễn, sốt Worcestershire và gia vị. Đun sôi, sau đó giảm nhiệt, đậy nắp và đun nhỏ lửa, thỉnh thoảng khuấy trong 30 phút.', NULL, '2026-05-15 14:31:19', '2026-05-15 14:31:19'),
(586, 82, 3, 'Trong khi đó, nấu mì spaghetti trong một chảo lớn nước sôi có muối, theo hướng dẫn trên bao bì. Xả thật sạch, cho nước nóng chảy qua, cho lại vào chảo và thêm một chút dầu ô liu, nếu thích thì cho nước sốt thịt vào khuấy đều. Bày ra bát nóng và dùng phô mai Parmesan tròn để rắc lên trên.', NULL, '2026-05-15 14:31:19', '2026-05-15 14:31:19'),
(588, 83, 1, 'Trộn tất cả các nguyên liệu làm nước sốt vào tô với 1 thìa canh nước cho đến khi đường tan.', NULL, '2026-05-15 14:31:21', '2026-05-16 12:35:33'),
(590, 83, 2, 'Luộc mì theo hướng dẫn trên bao bì, sau đó ngâm vào tô nước lạnh cho mì nguội hoàn toàn. Để ráo mì, sau đó cho cà rốt, bắp cải, hành lá và nước sốt vào trộn đều.', NULL, '2026-05-15 14:31:21', '2026-05-16 12:35:33'),
(592, 83, 3, 'Đun nóng dầu trong chảo trên lửa cao. Nêm bít tết, sau đó nấu theo ý thích của bạn; 2-3 phút mỗi mặt đối với loại vừa hiếm. Để yên trong 5 phút rồi cắt lát. Chia các lát salad và bít tết vào giữa các bát và rắc lên một ít rau mùi để thưởng thức.', NULL, '2026-05-15 14:31:21', '2026-05-16 12:35:33'),
(593, 84, 1, 'Làm nóng lò ở 220C/425F/Gas 7', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(594, 84, 2, 'Đun nóng dầu thực vật trong chảo lớn, cho thịt bò vào chiên vàng đều. (Bạn có thể cần phải thực hiện việc này theo từng đợt.) Đặt sang một bên, sau đó làm chín thận ở cả hai mặt trong cùng một chảo. Thêm hành tây và nấu trong 3-4 phút.', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(595, 84, 3, 'Cho thịt bò vào chảo, rắc bột mì lên rồi phủ thịt và hành tây lên', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(596, 84, 4, 'Thêm nước kho vào chảo, khuấy đều và đun sôi.', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(597, 84, 5, 'Giảm nhiệt và đun nhỏ lửa trong 1 tiếng rưỡi mà không cần đậy nắp. Nếu chất lỏng bay hơi quá nhiều, hãy đổ thêm nước kho.', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(598, 84, 6, 'Hủy bỏ khỏi nhiệt. Thêm muối, hạt tiêu và sốt Worcestershire và để nguội hoàn toàn. Đặt hỗn hợp thịt đã nấu chín vào đĩa bánh.', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(599, 84, 7, 'Cán miếng bánh dày 5mm/¼in và lớn hơn 5cm/2in so với đĩa bạn đang dùng.', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(600, 84, 8, 'Dùng cây cán bột, nhấc bánh lên và đặt lên trên đĩa bánh. Cắt và uốn các cạnh bằng ngón tay cái của bạn.', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(601, 84, 9, 'Quét hỗn hợp trứng đã đánh lên bề mặt và nướng trong 30-40 phút cho đến khi có màu nâu vàng và phồng lên.', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(602, 84, 10, 'Ăn kèm với kem nghiền và rau hấp để thấm nước sốt.', NULL, '2026-05-15 14:31:26', '2026-05-15 14:31:26'),
(603, 85, 1, 'Đun nóng dầu trong chảo 12 inch trên lửa vừa cao. Nêm bít tết với muối và hạt tiêu rồi cho vào chảo; nấu, lật một lần cho đến khi chín vàng cả hai mặt và chín đến độ chín mong muốn, khoảng 4 đến 5 phút đối với thịt vừa tái. Chuyển bít tết ra đĩa và đặt sang một bên.', NULL, '2026-05-15 14:31:29', '2026-05-15 14:31:29'),
(604, 85, 2, 'Cho chảo lên lửa cao và thêm nước kho vào; nấu cho đến khi giảm còn 1⁄2 cốc, khoảng 10 phút. Đổ vào tô, đặt sang một bên. Đun nóng chảo và thêm bơ; thêm tỏi và hẹ vào, nấu, khuấy đều cho đến khi mềm, khoảng 2 phút. Thêm nấm vào, nấu, khuấy đều cho đến khi nấm tiết ra chất lỏng và bay hơi và nấm bắt đầu chuyển sang màu nâu, khoảng 2 phút. Thêm rượu cognac và châm diêm vào flambée; nấu cho đến khi ngọn lửa tắt. Khuấy nước kho dự trữ, kem, Dijon, Worcestershire và nước sốt nóng, sau đó cho bít tết vào chảo; nấu, cho nước sốt vào, cho đến khi ấm và nước sốt đặc lại, khoảng 4 phút. Chuyển bít tết ra đĩa và trộn mùi tây và hẹ vào nước sốt; rưới nước sốt lên bít tết để phục vụ.', NULL, '2026-05-15 14:31:29', '2026-05-15 14:31:29'),
(605, 86, 1, 'BƯỚC 1 – Ướp THỊT BÒ', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(606, 86, 2, 'Cho thịt bò, muối, dầu mè, tiêu trắng, lòng trắng trứng, 2 thìa tinh bột ngô và 1 thìa dầu vào tô.', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(607, 86, 3, 'BƯỚC 2 - Xào', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(608, 86, 4, 'Đầu tiên, nấu thịt bò bằng cách thêm 2 muỗng canh dầu cho đến khi thịt bò có màu vàng nâu.', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(609, 86, 5, 'Đặt thịt bò sang một bên', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(610, 86, 6, 'Trong chảo, thêm 1 muỗng canh dầu, gừng băm, tỏi băm và xào trong vài giây.', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(611, 86, 7, 'Tiếp theo cho tất cả các loại rau vào rồi thêm rượu nấu sherry và 1 cốc nước.', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(612, 86, 8, 'Để làm nước sốt, thêm dầu hào, sốt ớt cay và đường.', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(613, 86, 9, 'thêm thịt bò nấu chín và 1 thìa nước tương', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(614, 86, 10, 'Để làm đặc nước sốt, trộn 1 thìa bột ngô và 2 thìa nước vào tô rồi từ từ thêm vào món xào cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:31:32', '2026-05-15 14:31:32'),
(616, 87, 1, 'Đun nóng chảo hoặc chảo lớn cho đến khi bốc khói. Đổ dầu vào và đảo quanh chảo, sau đó cho các dải thịt bò và ớt vào. Nấu, khuấy liên tục cho đến khi thịt có màu nâu nhạt, khoảng 3 phút thì rưới dầu hào lên trên. Nấu cho đến khi nóng và nước sốt thấm vào thịt. khuấy lá húng quế và dùng với cơm trắng.', NULL, '2026-05-15 14:31:34', '2026-05-16 12:35:33'),
(617, 88, 1, 'Thịt rửa sạch nếu có gân và cắt thành từng miếng nhỏ hơn, kích thước 3 × 3 cm. Ướp thịt với mù tạt và gia vị rồi để trong tủ lạnh khoảng một giờ', NULL, '2026-05-15 14:31:36', '2026-05-15 14:31:36'),
(618, 88, 2, 'Đun nóng một thìa mỡ lợn hoặc dầu thực vật trong nồi rồi chiên thịt các mặt cho đến khi chín vàng. Thịt chín thì múc ra đĩa rồi cho thêm 1 thìa mỡ vào nồi', NULL, '2026-05-15 14:31:36', '2026-05-15 14:31:36'),
(619, 88, 3, 'Cắt hành thật nhuyễn, gọt vỏ cà rốt và dùng dụng cụ bào cắt nhỏ. Nấu hành tây và cà rốt trên lửa nhỏ trong 15 phút. Bạn có thể muối rau một chút để rau mềm nhanh hơn', NULL, '2026-05-15 14:31:36', '2026-05-15 14:31:36'),
(620, 88, 4, 'Khi rau đã chín vàng và hơi nhão, hãy cho thịt, lá nguyệt quế và tỏi vào. Đổ rượu vào và đun nhỏ lửa trong vòng 10 - 15 phút để rượu bay hơi. Bây giờ là thời điểm thích hợp để thêm 2/3 lượng chất lỏng', NULL, '2026-05-15 14:31:36', '2026-05-15 14:31:36'),
(621, 88, 5, 'Đậy nắp nồi và nấu trên lửa nhỏ trong một giờ, thỉnh thoảng khuấy đều. Sau giờ đầu tiên, đổ phần nước hoặc kho còn lại lên và nấu thêm 30-45 phút nữa.', NULL, '2026-05-15 14:31:36', '2026-05-15 14:31:36'),
(622, 88, 6, 'Để món hầm nguội một chút và dùng kèm với rắc rau mùi tây cắt nhỏ và vài lát ớt tươi nếu bạn muốn thêm gia vị một chút.', NULL, '2026-05-15 14:31:36', '2026-05-15 14:31:36'),
(623, 88, 7, 'Cắt một ít bánh mì tươi, nêm salad và đơn giản là thưởng thức những hương vị tuyệt vời này', NULL, '2026-05-15 14:31:36', '2026-05-15 14:31:36'),
(625, 89, 1, 'Rây bột vào tô lớn, tạo một cái giếng ở giữa rồi rắc men vào. Đổ 125ml nước lên men, sau đó vẩy bột mì lên trên để tạo lớp. Đậy nắp và để ở nơi ấm áp trong 15 phút cho đến khi các vết nứt xuất hiện trên bề mặt của lớp đó.', NULL, '2026-05-15 14:31:39', '2026-05-16 12:35:33'),
(627, 89, 2, 'Dùng tay trộn thêm 250ml nước cùng 1 thìa muối vào rồi nhào bột khoảng 10 phút cho đến khi bột dẻo và không còn dính tay. Thêm một chút bột mì nếu bạn cần. Đậy nắp và để bột nở lại ở nơi ấm áp trong 30 phút cho đến khi nở gấp đôi.', NULL, '2026-05-15 14:31:39', '2026-05-16 12:35:33'),
(629, 89, 3, 'Làm nóng lò ở mức cao nhất có thể (khoảng 240C/220C quạt/gas 9) và rắc mỏng bột ngô lên một hoặc hai khay nướng.', NULL, '2026-05-15 14:31:39', '2026-05-16 12:35:33'),
(631, 89, 4, 'Đổ nước sôi từ ấm lên cà chua, để yên một lúc rồi để ráo nước và lột vỏ. Cà chua cắt làm đôi, cắt bỏ cuống, bỏ hạt và bỏ đi, sau đó băm nhỏ lấy thịt.', NULL, '2026-05-15 14:31:39', '2026-05-16 12:35:33'),
(633, 89, 5, 'Ớt bổ đôi theo chiều dọc, cắt bỏ cuống, hạt và lớp màng trắng bên trong rồi rửa sạch. Cắt theo chiều dọc thành dải mịn, sau đó cắt ngang thành xúc xắc mịn.', NULL, '2026-05-15 14:31:39', '2026-05-16 12:35:33'),
(635, 89, 6, 'Cho cà chua, ớt, hành lá, rau mùi tây thái nhỏ, thịt bò bằm, gia vị, 1 thìa muối và ½ thìa tiêu đen mới xay vào tô rồi trộn đều.', NULL, '2026-05-15 14:31:39', '2026-05-16 12:35:33'),
(637, 89, 7, 'Lấy bột và nhào thật nhanh, sau đó chia thành bốn phần và nặn từng phần thành một quả bóng. Lăn từng viên thành từng hình tròn mỏng, đặt lên khay nướng đã chuẩn bị sẵn. Trải một lớp mỏng hỗn hợp thịt.', NULL, '2026-05-15 14:31:39', '2026-05-16 12:35:33'),
(639, 89, 8, 'Nướng từng chiếc bánh mỳ dẹt trong vòng 10-15 phút cho đến khi các cạnh bắt đầu sẫm màu. Sau khi lấy ra khỏi lò, rắc lahmacun với rau mùi tây cắt nhỏ và hành tây thái lát, sau đó vắt thêm vài giọt nước cốt chanh. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:31:39', '2026-05-16 12:35:33'),
(640, 90, 1, 'Thêm thành phần:', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(641, 90, 2, '12 chén rau trộn xắt nhỏ', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(642, 90, 3, '1 chén nấm tươi xắt nhỏ', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(643, 90, 4, '1 chén hành ngọc trai', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(644, 90, 5, 'ĐỨNG ĐẦU:', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(645, 90, 6, 'Làm nóng lò ở nhiệt độ 450°. Nướng khoai tây trên khay nướng có lót giấy bạc cho đến khi mềm, khoảng 45 phút. Để nguội một chút rồi bóc vỏ. Nhấn khoai tây qua máy xay, máy xay thực phẩm hoặc rây vào tô lớn. Thêm bơ; khuấy cho đến khi trộn đều. Khuấy sữa. Nêm muối cho vừa ăn.', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(646, 90, 7, 'ĐIỀN:', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(647, 90, 8, 'Ngâm porcini khô trong 3 cốc nước nóng; đặt sang một bên. Kết hợp đậu lăng, 1 tép tỏi, 1 muỗng cà phê. muối và 4 cốc nước vào nồi vừa. Đun sôi; giảm nhiệt và đun nhỏ lửa, thỉnh thoảng khuấy cho đến khi đậu lăng mềm nhưng không nhão, trong 15–20 phút. Xả đậu lăng và loại bỏ tỏi.', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(648, 90, 9, 'Đun nóng 3 muỗng canh. dầu trong một nồi nặng lớn trên lửa vừa. Thêm hành tây và nấu, thỉnh thoảng khuấy cho đến khi mềm, khoảng 12 phút. Thêm tỏi băm nhỏ và nấu trong 1 phút. Khuấy bột cà chua. Nấu, khuấy liên tục cho đến khi bột cà chua có màu caramen, 2–3 phút.', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(649, 90, 10, 'Thêm lá nguyệt quế và rượu; khuấy đều, cạo sạch những phần màu nâu. Khuấy porcini, từ từ đổ chất lỏng ngâm porcini vào chảo nhưng để lại cặn. Đun nhỏ lửa và nấu cho đến khi chất lỏng giảm đi một nửa, khoảng 10 phút. Khuấy nước dùng và nấu, thỉnh thoảng khuấy cho đến khi giảm một nửa, khoảng 45 phút.', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(650, 90, 11, 'Lọc hỗn hợp vào nồi lớn và đun sôi; loại bỏ chất rắn trong bộ lọc. Khuấy bột ngô và 2 muỗng canh. nước vào một cái bát nhỏ để hòa tan. Thêm hỗn hợp bột ngô; đun nhỏ lửa cho đến khi đặc lại, khoảng 5 phút. Đánh đều trong miso. Nêm nước sốt với muối và hạt tiêu. Đặt sang một bên.', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(651, 90, 12, 'Làm nóng lò ở nhiệt độ 450°. Trộn rau và hành tây với 2 muỗng canh còn lại. dầu, 5 tép tỏi và nhánh hương thảo trong tô lớn; nêm muối và hạt tiêu. Chia giữa 2 tấm nướng có viền. Nướng, khuấy một lần cho đến khi mềm, khoảng 20–25 phút. Chuyển tép tỏi vào một cái bát nhỏ; nghiền nhuyễn bằng nĩa và khuấy thành nước sốt. Bỏ cây hương thảo. LÀM TRƯỚC: Đậu lăng, nước sốt và rau có thể được làm trước 1 ngày. Che riêng; sự ớn lạnh.', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(652, 90, 13, 'Sắp xếp đậu lăng thành một lớp chẵn trong 3-qt. món nướng; đặt đĩa lên khay nướng có viền lót giấy bạc. Trộn rau củ nướng với nấm tươi và rau thơm cắt nhỏ; lớp trên cùng của đậu lăng. Đổ nước sốt lên rau. Đổ đều hỗn hợp khoai tây lên trên.', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(653, 90, 14, 'Nướng cho đến khi chín vàng và sủi bọt, khoảng 30 phút. Hãy đứng trong 15 phút trước khi phục vụ.', NULL, '2026-05-15 14:31:41', '2026-05-15 14:31:41'),
(654, 91, 1, 'Cho phần thân sau, 1 củ hành tây nhỏ cắt đôi, ớt chuông cắt đôi, 4 tép tỏi nguyên củ, lá tỏi tây màu xanh đậm rồi cho vào nồi kho lớn. Nấu khoảng 45-60 phút cho đến khi thịt mềm. LƯU Ý: thịt có thể mất nhiều thời gian hơn một chút để mềm; không sao cả, chỉ cần tăng thêm thời gian nấu nếu cần thiết.', NULL, '2026-05-15 14:31:46', '2026-05-15 14:31:46'),
(655, 91, 2, 'Khi thịt mềm, vớt ra những miếng rau và xương lớn. Vứt bỏ.', NULL, '2026-05-15 14:31:46', '2026-05-15 14:31:46'),
(656, 91, 3, 'Thêm hành tây thái hạt lựu, 2 củ tỏi băm, ớt ngọt nhỏ, tỏi tây thái lát (phần xanh nhạt), hành lá, yucca và ngô; Trộn và đun nhỏ lửa trên lửa vừa trong 5-8 phút cho đến khi yucca bắt đầu mềm. LƯU Ý: yuca có thể mất nhiều thời gian hơn để bắt đầu mềm; không sao cả, chỉ cần tăng thêm thời gian nấu nếu cần thiết.', NULL, '2026-05-15 14:31:46', '2026-05-15 14:31:46'),
(657, 91, 4, 'Thêm yautia, khoai lang trắng và bí đỏ. Trộn để kết hợp. Đun nhỏ lửa ở lửa vừa trong 5 – 6 phút cho đến khi tất cả các loại rau củ đều mềm. LƯU Ý: Đừng nấu quá nhiều, nếu không chúng sẽ bị nát.', NULL, '2026-05-15 14:31:46', '2026-05-15 14:31:46'),
(658, 91, 5, 'Hương vị và thêm muối theo khẩu vị của bạn, nếu cần thiết. Thêm ngò và 2 tép tỏi băm còn lại vào. Trộn và để sôi thêm 2 phút nữa.', NULL, '2026-05-15 14:31:46', '2026-05-15 14:31:46'),
(659, 91, 6, 'Ăn nóng trong tô súp lớn, chia đều thịt và rau. Thêm một ít nước cốt chanh và/hoặc nước sốt nóng nếu muốn. Ăn kèm với arepas và casabe (bánh mì sắn).', NULL, '2026-05-15 14:31:46', '2026-05-15 14:31:46'),
(660, 92, 1, 'Ướp thịt bò với muối, tiêu và tỏi băm', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(661, 92, 2, 'Cắt 1 củ hành tây thành 4 miếng lớn', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(662, 92, 3, 'Cho vào nồi áp suất thịt bò cùng 4 củ hành tây và nước luộc', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(663, 92, 4, 'Nấu áp suất trong 20 phút', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(664, 92, 5, 'Xả áp suất và mở nắp', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(665, 92, 6, 'Lấy thịt bò ra và TIẾT KIỆM 2 cốc nước dùng vào hộp đựng khác', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(666, 92, 7, 'Dùng 2 nĩa, xé thịt bò. Thịt bò phải đủ mềm để dễ dàng như vậy. Nếu chưa thì nấu thêm 10 phút nữa', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(667, 92, 8, 'Nhấn nút xào của nồi Instant pot. Thêm dầu ô liu', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(668, 92, 9, 'Khi máy phát ra tiếng bíp, cho hành tây, hạt tiêu và cà chua thái lát vào. Nấu cho đến khi mềm', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(669, 92, 10, 'Thêm thịt bò thái nhỏ vào nồi và trộn đều', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(670, 92, 11, 'Đổ 1 1/2 cốc nước dùng đã để sẵn, sốt Worcestershire, bột cà chua, sốt cà chua và thì là vào. Trộn', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(671, 92, 12, 'Nếu nước sốt có vẻ khô, hãy thêm một chút nước kho', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(672, 92, 13, 'Nêm muối và hạt tiêu', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(673, 92, 14, 'Phục vụ!', NULL, '2026-05-15 14:31:50', '2026-05-15 14:31:50'),
(674, 93, 1, 'BƯỚC 1', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(675, 93, 2, 'Đặt ức gà vào giữa hai miếng giấy nến rồi dùng cây lăn cán nhẹ cho đến khi dày khoảng 1cm. Cắt mỗi ức gà thành hai miếng đều nhau.', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(676, 93, 3, 'BƯỚC 2', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(677, 93, 4, 'Nếu bạn đang sử dụng chảo rán, hãy làm nóng hai chảo rán trên lửa vừa cao, trong đó một chảo có chứa dầu. Chiên gà trong chảo dầu khoảng 3-4 phút mỗi mặt cho đến khi gà chín. Nêm gà, giảm lửa, rưới tương ớt và nửa nước cốt chanh vào, nấu thêm 1-2 phút cho đến khi nước sốt giảm bớt. Lấy gà ra khỏi lửa.', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(678, 93, 5, 'BƯỚC 3', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(679, 93, 6, 'Nếu bạn đang sử dụng nồi chiên không dầu, hãy làm nóng trước ở nhiệt độ 180C trong 4 phút. Cho gà vào nồi chiên không khí và nấu trong 12 phút. Rưới nước sốt ớt và nửa quả chanh lên rồi nấu thêm 1-2 phút cho đến khi gà chín và bớt nước sốt. Lấy gà ra và giữ ấm.', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(680, 93, 7, 'BƯỚC 4', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(681, 93, 8, 'Trong khi nướng gà, nướng bánh trong chảo rán khô trong 30 giây. Chuyển chúng vào đĩa. Nếu bạn sử dụng nồi chiên không dầu, hãy cho bánh vào nồi chiên không khí trong 1-2 phút cho đến khi bánh ấm. Tăng nhiệt độ nồi chiên không khí lên 200C. Thêm halloumi vào giỏ nồi chiên không dầu và nấu trong 10 phút, lật nửa chừng cho đến khi vàng. Trộn bắp cải với mayo và nước cốt chanh còn lại.', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(682, 93, 9, 'BƯỚC 5', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(683, 93, 10, 'Múc hummus (hoặc nhúng theo sở thích của bạn) vào bánh mì nướng, sau đó phủ rocket, gà ớt, halloumi và ớt lên trên. Rắc thêm một ít tương ớt, rưới lên bắp cải, nêm tiêu đen và đậy nắp bánh mì lên trên. Ăn kèm với bất kỳ bắp cải bổ sung nào ở bên cạnh hoặc salad xanh.', NULL, '2026-05-15 14:31:54', '2026-05-15 14:31:54'),
(684, 94, 1, 'Trong máy xay sinh tố, thêm các nguyên liệu làm bột gia vị và trộn cho đến khi mịn.', NULL, '2026-05-15 14:31:56', '2026-05-15 14:31:56'),
(685, 94, 2, 'Trên lửa vừa, đổ hỗn hợp gia vị vào chảo hoặc chảo và chiên trong 10 phút cho đến khi có mùi thơm. Thêm nước hoặc dầu, mỗi lần 1 muỗng canh nếu hỗn hợp trở nên quá khô. Đừng đốt bột nhão. Giảm lửa một chút nếu cần.', NULL, '2026-05-15 14:31:56', '2026-05-15 14:31:56'),
(686, 94, 3, 'Thêm đinh hương, bạch đậu khấu, bột me, nước cốt dừa, nước, đường và muối. Bật lửa lên và đun sôi hỗn hợp. Vặn lửa ở mức trung bình thấp và đun nhỏ lửa trong 10 phút. Thỉnh thoảng khuấy. Nó sẽ giảm đi một chút. Đây là nước xốt/nước sốt, vì vậy hãy nếm và điều chỉnh gia vị nếu cần. Đừng lo lắng nếu nó hơi đắng. Nó sẽ biến mất khi rang.', NULL, '2026-05-15 14:31:56', '2026-05-15 14:31:56'),
(687, 94, 4, 'Khi nước xốt/nước sốt đã nguội, đổ mọi thứ lên gà và ướp qua đêm đến hai ngày.', NULL, '2026-05-15 14:31:56', '2026-05-15 14:31:56'),
(688, 94, 5, 'Làm nóng lò ở nhiệt độ 425 F.', NULL, '2026-05-15 14:31:56', '2026-05-15 14:31:56'),
(689, 94, 6, 'Lấy gà ra khỏi nước ướp. Múc nước xốt lên khay nướng đã phết mỡ (hoặc lót nhôm). Đặt gà lên trên nước sốt (đảm bảo gà phủ nước sốt và nước sốt không bị lộ ra nếu không sẽ bị cháy) và phết phần nước xốt còn lại lên gà. Nướng trong 35-45 phút hoặc cho đến khi nhiệt độ bên trong phần dày nhất của thịt gà ít nhất là 175 F.', NULL, '2026-05-15 14:31:56', '2026-05-15 14:31:56'),
(690, 94, 7, 'Để gà nghỉ 5 phút. Quét gà với một ít dầu. Ăn gà với nước sốt trên cơm trắng (hoặc cơm dừa).', NULL, '2026-05-15 14:31:56', '2026-05-15 14:31:56'),
(691, 95, 1, 'Vắt chanh lên gà và chà xát đều. Xả hết nước cốt chanh dư thừa.', NULL, '2026-05-15 14:32:00', '2026-05-15 14:32:00'),
(692, 95, 2, 'Kết hợp cà chua, hành lá, hành tây, tỏi, hạt tiêu, húng tây, ớt và nước tương vào tô lớn cùng với các miếng thịt gà. Che và ướp ít nhất một giờ.', NULL, '2026-05-15 14:32:00', '2026-05-15 14:32:00'),
(693, 95, 3, 'Đun nóng dầu trong nồi Hà Lan hoặc chảo lớn. Lắc bỏ gia vị khi lấy từng miếng thịt gà ra khỏi nước xốt. Dự trữ nước xốt cho nước sốt.', NULL, '2026-05-15 14:32:00', '2026-05-15 14:32:00'),
(694, 95, 4, 'Chiên từng miếng gà một vài miếng trong dầu thật nóng. Đặt các miếng thịt gà đã chiên vàng lên đĩa để nghỉ trong khi chiên các miếng còn lại.', NULL, '2026-05-15 14:32:00', '2026-05-15 14:32:00'),
(695, 95, 5, 'Xả bớt dầu thừa và cho gà trở lại chảo. Đổ nước xốt lên gà và thêm cà rốt. Khuấy và nấu trên lửa vừa trong 10 phút.', NULL, '2026-05-15 14:32:00', '2026-05-15 14:32:00'),
(696, 95, 6, 'Trộn bột mì và nước cốt dừa rồi cho vào hầm, khuấy liên tục. Giảm nhiệt xuống mức tối thiểu và nấu thêm 20 phút nữa hoặc cho đến khi mềm.', NULL, '2026-05-15 14:32:00', '2026-05-15 14:32:00'),
(697, 96, 1, 'Bọc gà lỏng lẻo giữa màng bọc thực phẩm và giã nhẹ nhàng bằng mặt phẳng của máy làm mềm thịt cho đến khi dày khoảng 1/2 inch xung quanh.', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(698, 96, 2, 'Cắt thành hai mảnh, càng đều càng tốt.', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(699, 96, 3, 'Ướp trong nước dưa chua trong 30 phút đến một giờ (thêm một thìa cà phê nước sốt Tabasco bây giờ để có bánh mì cay).', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(700, 96, 4, 'Đánh trứng với sữa vào tô.', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(701, 96, 5, 'Trộn bột mì, đường và gia vị vào một tô khác.', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(702, 96, 6, 'Nhúng từng miếng gà vào trứng ở cả hai mặt, sau đó phủ bột mì lên cả hai mặt.', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(703, 96, 7, 'Đun nóng dầu trong chảo (sâu 1/2 inch) đến khoảng 345-350.', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(704, 96, 8, 'Chiên từng miếng cốt lết trong 2 phút mỗi mặt hoặc cho đến khi chín vàng.', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(705, 96, 9, 'Chấm lên giấy và dùng trên bánh nướng với lát dưa chua.', NULL, '2026-05-15 14:32:03', '2026-05-15 14:32:03'),
(707, 97, 1, 'Đun nóng dầu trong một đĩa thịt hầm lớn chống cháy và làm chín các miếng thịt gà ở tất cả các mặt – bạn có thể phải làm việc này theo từng mẻ. Lấy ra khỏi đĩa và đặt sang một bên.', NULL, '2026-05-15 14:32:06', '2026-05-16 12:35:33'),
(709, 97, 2, 'Giảm nhiệt, thêm hành tây và hạt tiêu vào nấu nhẹ trong 10 phút cho đến khi mềm. Thêm tỏi và chorizo ​​vào, nấu thêm 2 phút nữa cho đến khi chorizo ​​tiết ra một ít dầu vào đĩa. Khuấy nhuyễn cà chua và nấu thêm 1 phút nữa.', NULL, '2026-05-15 14:32:06', '2026-05-16 12:35:33'),
(711, 97, 3, 'Cho các miếng thịt gà vào đĩa cùng với húng tây, rượu trắng và nước kho. Đun sôi chất lỏng, đậy nắp kín đĩa và giảm nhiệt. Nấu trong 30 phút.', NULL, '2026-05-15 14:32:06', '2026-05-16 12:35:33'),
(713, 97, 4, 'Đổ cơm vào và khuấy đều mọi thứ lại với nhau. Đậy nắp, đặt ở lửa nhỏ và nấu thêm 15 phút nữa hoặc cho đến khi cơm chín và ngấm hầu hết nước nấu. Tắt bếp và để đĩa trong 10 phút để hấp thụ chất lỏng còn lại. Nêm nếm vừa ăn và rải với rau mùi tây để phục vụ.', NULL, '2026-05-15 14:32:06', '2026-05-16 12:35:33'),
(714, 98, 1, 'Làm nóng lò ở nhiệt độ 200C/180C quạt/gas 6. Cho bơ vào nồi cỡ vừa và đặt trên lửa vừa. Thêm hành tây và để nấu trong 5 phút, thỉnh thoảng khuấy. Cho nấm vào nồi cùng hành tây.', NULL, '2026-05-15 14:32:07', '2026-05-15 14:32:07'),
(715, 98, 2, 'Khi hành tây và nấm gần chín, cho bột mì vào khuấy đều - điều này sẽ tạo thành một hỗn hợp sệt gọi là roux. Nếu bạn đang sử dụng viên nước kho, hãy nghiền khối đó vào roux và khuấy đều. Đặt roux trên lửa nhỏ và khuấy liên tục trong 2 phút - điều này sẽ làm chín bột và ngăn nước sốt có vị bột.', NULL, '2026-05-15 14:32:07', '2026-05-15 14:32:07'),
(716, 98, 3, 'Lấy roux ra khỏi lửa. Từ từ thêm nước kho tươi nếu sử dụng hoặc đổ vào 500ml nước nếu bạn dùng nước kho, khuấy liên tục. Khi tất cả chất lỏng đã được thêm vào, nêm hạt tiêu, một chút hạt nhục đậu khấu và bột mù tạt. Đặt chảo trở lại lửa vừa và từ từ đun sôi, khuấy đều. Khi nước sốt đã đặc lại, đặt ở nhiệt độ rất thấp. Thêm thịt gà và rau đã nấu chín vào nước sốt và khuấy đều. Bôi một ít bơ lên ​​đĩa nướng cỡ vừa rồi đổ nhân gà và nấm vào.', NULL, '2026-05-15 14:32:07', '2026-05-15 14:32:07'),
(717, 98, 4, 'Cẩn thận đặt khoai tây lên trên lớp nhân nóng, hơi chồng lên nhau, gần giống như mặt bánh nướng.', NULL, '2026-05-15 14:32:07', '2026-05-15 14:32:07'),
(718, 98, 5, 'Quét khoai tây với một ít bơ tan chảy và nướng trong lò khoảng 35 phút. Lẩu đã sẵn sàng khi khoai tây đã chín và có màu vàng nâu.', NULL, '2026-05-15 14:32:07', '2026-05-15 14:32:07'),
(719, 99, 1, 'Đun nóng 1 thìa bơ và 2 thìa dầu ô liu trong chảo lớn trên lửa vừa cao', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(720, 99, 2, 'Nêm cả hai mặt của mỗi ức gà với muối và một chút hạt tiêu', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(721, 99, 3, 'Cho gà vào chảo và nấu khoảng 5-7 phút mỗi mặt hoặc cho đến khi chín đều', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(722, 99, 4, 'Trong khi luộc gà, hãy đun sôi một nồi nước lớn', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(723, 99, 5, 'Đổ nước sôi với một ít muối kosher', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(724, 99, 6, 'Thêm mì ống và khuấy đều', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(725, 99, 7, 'Nấu, thỉnh thoảng khuấy cho đến khi chín, khoảng 12 phút', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(726, 99, 8, 'Dự trữ 1/2 cốc nước mì ống trước khi xả mì ống', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(727, 99, 9, 'Lấy gà ra khỏi chảo và chuyển sang thớt; cho phép nó nghỉ ngơi', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(728, 99, 10, 'Giảm lửa xuống mức trung bình và cho 1 thìa bơ và dầu ô liu còn lại vào chảo bạn dùng để nấu gà', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(729, 99, 11, 'Cho rau (trừ tỏi) và ớt đỏ vào chảo rồi đảo đều cho dầu và bơ phủ đều (không nêm muối cho đến khi rau chín vàng)', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(730, 99, 12, 'Nấu, khuấy thường xuyên cho đến khi rau mềm, khoảng 5 phút', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(731, 99, 13, 'Thêm tỏi và một chút muối và hạt tiêu vào chảo và nấu trong 1 phút', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(732, 99, 14, 'Khử men chảo bằng rượu trắng', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(733, 99, 15, 'Tiếp tục nấu cho đến khi rượu cạn một nửa, khoảng 3 phút', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(734, 99, 16, 'Khuấy sữa, kem béo và nước mì ống dành riêng', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(735, 99, 17, 'Đun sôi hỗn hợp nhẹ nhàng và để nhỏ lửa và giảm trong 2-3 phút', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(736, 99, 18, 'Tắt lửa và thêm phô mai Parmesan và mì ống nấu chín', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(737, 99, 19, 'Nêm muối và hạt tiêu cho vừa ăn', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(738, 99, 20, 'Trang trí với phô mai Parmesan và rau mùi tây cắt nhỏ nếu muốn', NULL, '2026-05-15 14:32:09', '2026-05-15 14:32:09'),
(739, 100, 1, 'Làm nóng lò ở 180°C/Mốc gas 4. Chuẩn bị sẵn các miếng thịt gà để nấu. Đun nóng bơ và 3 muỗng canh dầu ô liu trong nồi chống cháy hoặc chảo rán lớn. Chiên từng miếng gà thành từng mẻ ở cả hai mặt, nêm muối và tiêu khi ăn. Đừng dồn chảo - chiên gà theo từng mẻ nhỏ, vớt từng miếng ra giấy ăn khi đã xong.', NULL, '2026-05-15 14:32:18', '2026-05-15 14:32:18'),
(740, 100, 2, 'Thêm một ít dầu ô liu vào nồi và xào hành tây trên lửa vừa trong 10 phút, khuấy thường xuyên cho đến khi mềm nhưng không chuyển sang màu nâu. Thêm phần dầu còn lại, sau đó là ớt và nấu thêm 5 phút nữa.', NULL, '2026-05-15 14:32:18', '2026-05-15 14:32:18'),
(741, 100, 3, 'Thêm chorizo, cà chua phơi nắng và tỏi vào nấu trong 2-3 phút. Thêm gạo vào, khuấy đều để đảm bảo cơm được ngấm đều trong dầu. Khuấy bột cà chua, ớt bột, lá nguyệt quế và húng tây cắt nhỏ. Đổ nước kho và rượu vào. Khi chất lỏng bắt đầu nổi bong bóng, hãy giảm nhiệt xuống mức sôi nhẹ. Nhấn cơm xuống nước nếu cơm chưa ngập rồi đặt gà lên trên. Thêm chanh và ô liu xung quanh gà.', NULL, '2026-05-15 14:32:18', '2026-05-15 14:32:18'),
(742, 100, 4, 'Đậy nắp và nấu trong lò trong 50 phút. Cơm phải chín nhưng vẫn còn vết cắn, thịt gà phải có nước chảy trong khi dùng dao đâm vào phần dày nhất. Nếu chưa, hãy nấu thêm 5 phút nữa và kiểm tra lại.', NULL, '2026-05-15 14:32:18', '2026-05-15 14:32:18'),
(743, 101, 1, 'BƯỚC 1 – Ướp GÀ', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(744, 101, 2, 'Cho thịt gà, muối, tiêu trắng, nước gừng vào tô rồi trộn đều.', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(745, 101, 3, 'Đặt gà sang một bên.', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(746, 101, 4, 'BƯỚC 2 – RỬA GẠO TRẮNG', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(747, 101, 5, 'Vo gạo trong tô hoặc nồi kim loại vài lần rồi để ráo nước.', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(748, 101, 6, 'BƯỚC 2 - Luộc gạo trắng', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(749, 101, 7, 'Tiếp theo cho 8 cốc nước vào rồi đặt bếp ở lửa lớn cho đến khi sôi. Khi cháo bắt đầu sôi, đặt bếp ở lửa nhỏ rồi khuấy đều 8-10 phút một lần trong khoảng 20-25 phút.', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(750, 101, 8, 'Sau 25 phút, điều này là tùy chọn nhưng bạn có thể thêm một chút nước để nấu cháo cho bớt đặc hoặc tùy theo sở thích của bạn.', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(751, 101, 9, 'Tiếp theo cho thịt gà đã ướp vào nồi cháo rồi để lửa nhỏ đun thêm 10 phút nữa.', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(752, 101, 10, 'Sau 10 phút thêm hành lá, gừng thái lát, 1 nhúm muối, 1 nhúm tiêu trắng vào đảo đều trong 10 giây.', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(753, 101, 11, 'Đổ cháo vào tô', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(754, 101, 12, 'Tùy chọn: thêm rau mùi lên trên cháo.', NULL, '2026-05-15 14:32:23', '2026-05-15 14:32:23'),
(755, 102, 1, 'Đun nóng dầu ô liu trong chảo lớn và xào hành tây trong 1-2 phút cho đến khi mềm. Thêm thịt gà và chiên trong 7-10 phút cho đến khi chín và hành tây chuyển sang màu vàng. Bào gừng, khuấy qua sợi harissa để phủ đều mọi thứ và nấu thêm 1 phút nữa.', NULL, '2026-05-15 14:32:25', '2026-05-15 14:32:25'),
(756, 102, 2, 'Cho mơ, đậu xanh và couscous vào, sau đó rưới nước kho lên và khuấy đều một lần. Đậy nắp hoặc đậy kín chảo bằng giấy bạc và để khoảng 5 phút cho đến khi couscous ngấm hết nước và mềm. Dùng nĩa xới đều món couscous và rắc lên rau mùi để thưởng thức. Ăn kèm thêm harissa nếu bạn thích.', NULL, '2026-05-15 14:32:25', '2026-05-15 14:32:25'),
(757, 103, 1, 'Cắt mỗi ức gà làm khoảng 3 miếng để chín nhanh hơn rồi cho vào nồi nhỏ. Đổ nước sốt Enchilada lên trên và nấu ở lửa vừa đến thấp cho đến khi gà chín, khoảng 20 phút. Không cần nước, gà sẽ được nấu với sốt Enchilada. Nhớ thỉnh thoảng khuấy đều để không bị dính đáy.', NULL, '2026-05-15 14:32:28', '2026-05-15 14:32:28'),
(758, 103, 2, 'Lấy gà ra khỏi nồi và xé nhỏ bằng hai nĩa.', NULL, '2026-05-15 14:32:28', '2026-05-15 14:32:28'),
(759, 103, 3, 'Làm nóng lò ở nhiệt độ 375 F.', NULL, '2026-05-15 14:32:28', '2026-05-15 14:32:28'),
(760, 103, 4, 'Bắt đầu xếp lớp thịt hầm. Bắt đầu với khoảng ¼ cốc nước sốt Enchilada còn sót lại trên đáy đĩa nướng. Tôi dùng một đĩa nướng dài hơn để có thể đặt 2 chiếc bánh ngô ngang nhau. Đặt 2 chiếc bánh ngô ở dưới cùng, đặt ⅓ thịt gà và ⅓ phần nước sốt còn lại lên trên. Rắc ⅓ phô mai và lặp lại bắt đầu với 2 chiếc bánh ngô nữa, sau đó là thịt gà, nước sốt, phô mai. Lặp lại với lớp cuối cùng với các nguyên liệu còn lại, bánh ngô, thịt gà, nước sốt và phô mai.', NULL, '2026-05-15 14:32:28', '2026-05-15 14:32:28'),
(761, 103, 5, 'Nướng trong 20 đến 30 phút không đậy nắp, cho đến khi sủi bọt và phô mai tan chảy và bắt đầu có màu nâu ở trên.', NULL, '2026-05-15 14:32:28', '2026-05-15 14:32:28'),
(762, 103, 6, 'Phục vụ ấm áp.', NULL, '2026-05-15 14:32:28', '2026-05-15 14:32:28'),
(763, 104, 1, 'Chiên hành, ớt và tỏi trong dầu ô liu cho đến khi trong mờ đẹp mắt. Tạo một cái giếng trong rau và thêm thịt gà của bạn vào. Thêm gia vị và muối của bạn. Cho phép tô màu một chút.', NULL, '2026-05-15 14:32:30', '2026-05-15 14:32:30'),
(764, 104, 2, 'Thêm kem, nước kho và mì ống của bạn.', NULL, '2026-05-15 14:32:30', '2026-05-15 14:32:30'),
(765, 104, 3, 'Nấu ở mức thấp trong 20 phút. Thêm phô mai của bạn, khuấy đều để kết hợp.', NULL, '2026-05-15 14:32:30', '2026-05-15 14:32:30'),
(766, 104, 4, 'Top với ớt nướng và rau mùi tây.', NULL, '2026-05-15 14:32:30', '2026-05-15 14:32:30'),
(767, 105, 1, 'Cơm chiên ngon nhất được làm từ cơm thừa để được ít nhất một ngày. Nếu không nó sẽ trở nên dẻo trong chảo.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(768, 105, 2, 'Nếu bạn không còn cơm thừa từ tối hôm trước, hãy nấu một mẻ gạo và trải lên khay nướng lớn hoặc vài đĩa lớn. Để cơm khô khoảng 1 đến 2 tiếng trước khi dùng làm cơm chiên.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(769, 105, 3, 'Cơm rất dễ dính vào chảo nên hãy đảm bảo sử dụng chảo hoặc chảo không có bề mặt dính. Tôi thường nấu các món xào trong chảo thép carbon dày dặn của mình, nhưng chảo gang hoặc chảo chống dính cũng hoạt động tốt. Bạn có thể cần thêm một chút dầu nếu mọi thứ không dễ dàng bong ra.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(770, 105, 4, 'Chuẩn bị gà:', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(771, 105, 5, 'Cắt thịt gà thành các khối nhỏ từ 1/4 inch đến 1/2 inch. Rắc 1/2 thìa muối lên gà rồi trộn đều. Đặt gà sang một bên trong khoảng 10 phút (tôi thường dùng thời gian này để cắt nhỏ tất cả các loại rau).', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(772, 105, 6, 'Đánh trứng:', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(773, 105, 7, 'Đun nóng chảo hoặc chảo xào lớn trên lửa vừa cao. Khuấy một thìa dầu và thêm trứng đã đánh bông vào. Dùng thìa để đánh trứng nhanh chóng, bẻ sữa đông thành những miếng nhỏ hơn khi chúng quyện lại với nhau. Chuyển trứng ra đĩa.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(774, 105, 8, 'Nấu gà:', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(775, 105, 9, 'Thêm một muỗng canh dầu khác vào chảo hoặc chảo. Thêm gà và nấu trong 4 đến 5 phút, thỉnh thoảng khuấy. Tắt lửa và chuyển gà đã luộc ra đĩa.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(776, 105, 10, 'Dùng thìa cạo sạch những miếng thịt gà còn dính vào chảo để chúng không bị cháy trong bước tiếp theo. Bạn cũng có thể dùng khăn giấy để lau chảo hoặc chảo.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(777, 105, 11, 'Nấu rau:', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(778, 105, 12, 'Khuấy 1 muỗng canh dầu vào chảo trên lửa vừa cao. Thêm hành tây thái hạt lựu và nấu trong 1 phút cho đến khi chúng bắt đầu mềm. Trộn tỏi và gừng băm vào và nấu cho đến khi có mùi thơm, khoảng 30 giây. Thêm cà rốt thái hạt lựu và nấu trong 2 phút, khuấy thường xuyên. Thêm 1/2 thìa cà phê muối và đậu Hà Lan vào rồi khuấy đều.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(779, 105, 13, 'Nấu cơm:', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(780, 105, 14, 'Cho gạo vào chảo hoặc chảo đặt trên rau và khuấy đều. Dùng mặt sau của thìa đập vỡ những khối gạo lớn để chúng vỡ ra. Thêm phần trắng và xanh của hành lá cắt lát (để lại phần xanh đậm) và bột ngũ vị hương. Khuấy để kết hợp. Nếu cơm bắt đầu dính vào chảo, hãy cho thêm một ít dầu vào.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(781, 105, 15, 'Rưới nước tương và dầu mè lên cơm rồi khuấy đều. Cho thịt gà đã nấu chín, trứng bác và phần sẫm màu của hành lá vào trộn đều. Khuấy nhanh để hòa quyện và nấu thêm 1 đến 2 phút nữa.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(782, 105, 16, 'Phục vụ:', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(783, 105, 17, 'Hương vị và thêm nước tương nếu cần thiết. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:32:32', '2026-05-15 14:32:32'),
(784, 106, 1, 'Đun nóng nước luộc gà trong chảo có nắp đậy. Thêm ức gà và đun nhỏ lửa. Đậy nắp và nấu trong 10 phút. Dùng kẹp lấy ức gà ra khỏi nước và đặt lên đĩa. Đổ rượu nấu vào một cái bình lớn.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(785, 106, 2, 'Đun chảy 25g/1oz bơ trong chảo lớn có đế nặng ở lửa nhỏ. Khuấy tỏi tây và chiên nhẹ nhàng trong hai phút, thỉnh thoảng khuấy cho đến khi mềm. Thêm tỏi và nấu thêm một phút nữa. Thêm bơ còn lại và khuấy bột ngay khi bơ tan chảy. Nấu trong 30 giây, khuấy liên tục.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(786, 106, 3, 'Từ từ đổ sữa vào chảo, mỗi lần một ít, khuấy đều giữa mỗi lần thêm. Dần dần thêm 250ml/10fl oz nước kho dự trữ và rượu, nếu dùng thì khuấy đều cho đến khi nước sốt mịn và hơi đặc. Đun nhỏ lửa và nấu trong 3 phút.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(787, 106, 4, 'Nêm hỗn hợp vừa ăn với muối và hạt tiêu đen mới xay. Tắt bếp và cho kem vào khuấy đều. Đổ vào một tô lớn và dùng màng dính phủ lên bề mặt nước sốt để tránh hình thành vỏ. Đặt sang một bên để nguội.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(788, 106, 5, 'Làm nóng lò ở nhiệt độ 200C/400F/Gas 6. Đặt khay nướng vào lò để làm nóng.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(789, 106, 6, 'Đối với bánh ngọt, cho bột mì và bơ vào máy xay thực phẩm và xay ở chế độ xung cho đến khi hỗn hợp giống như vụn bánh mì mịn. Khi động cơ đang chạy, thêm trứng đã đánh và nước vào rồi trộn cho đến khi hỗn hợp tạo thành một khối. Chia bớt 250g/10oz bánh ngọt cho nắp.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(790, 106, 7, 'Lăn phần bánh ngọt còn lại trên bề mặt có phủ bột mì nhẹ, đảo bánh thường xuyên cho đến khi dày khoảng 5 mm/¼ inch và lớn hơn đĩa bánh 4 cm/1½ inch. Nhấc bánh qua cán cán và nhẹ nhàng đặt bánh vào đĩa bánh. Nhấn mạnh bánh ngọt lên các cạnh, đảm bảo không có bọt khí. Để phần bánh thừa nhô ra hai bên.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(791, 106, 8, 'Cắt ức gà thành từng miếng 3cm/1¼in. Khuấy thịt gà, giăm bông và tỏi tây vào nước sốt đã nguội. Đổ nhân gà vào đĩa bánh. Quét trứng đã đánh lên mép đĩa. Tung ra phần bánh ngọt dành riêng cho nắp.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(792, 106, 9, 'Đậy nắp bánh bằng nắp bánh và ấn chặt các mép lại với nhau để bịt kín. Cắt bớt phần bánh thừa.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(793, 106, 10, 'Tạo một lỗ nhỏ ở giữa bánh bằng đầu dao. Phủ mặt trên của chiếc bánh với trứng đã đánh. Nướng trên khay đã làm nóng trước ở giữa lò trong 35-40 phút hoặc cho đến khi toàn bộ bánh có màu nâu vàng và phần nhân nóng hổi.', NULL, '2026-05-15 14:32:35', '2026-05-15 14:32:35'),
(794, 107, 1, 'Lấy một cái nồi hoặc chảo lớn, đủ lớn để nấu chín hết thịt gà và đun nóng dầu trong đó. Khi dầu nóng, cho hành tây thái lát vào chiên cho đến khi có màu vàng đậm. Sau đó lấy chúng ra đĩa và đặt sang một bên.', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(795, 107, 2, 'Cũng trong nồi đó, thêm tỏi băm nhỏ và xào trong một phút. Sau đó thêm cà chua xắt nhỏ vào nấu cho đến khi cà chua mềm. Việc này sẽ mất khoảng 5 phút.', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(796, 107, 3, 'Sau đó cho hành tây đã xào vào nồi và đảo đều. Thêm bột gừng và xào đều.', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(797, 107, 4, 'Bây giờ thêm hạt thì là, một nửa số hạt rau mùi và ớt xanh xắt nhỏ. Hãy khuấy động nhanh chóng.', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(798, 107, 5, 'Tiếp theo là các loại gia vị – bột nghệ và bột ớt đỏ. Xào đều gia vị trong vài phút.', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(799, 107, 6, 'Cho các miếng thịt gà vào chảo, nêm muối vừa ăn rồi đậy nắp gà trên lửa vừa-thấp cho đến khi gà gần chín. Việc này sẽ mất khoảng 15 phút. Xào gà từ từ sẽ làm tăng hương vị, vì vậy đừng đẩy nhanh bước này bằng cách đun lửa lớn.', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(800, 107, 7, 'Khi dầu tách ra khỏi gia vị, cho sữa chua đã đánh vào, giữ lửa ở mức thấp nhất để sữa chua không bị tách nước. Rắc hạt rau mùi còn lại và thêm một nửa lá cỏ cà ri khô. Trộn đều.', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(801, 107, 8, 'Cuối cùng thêm kem và trộn đều để mọi thứ kết hợp tốt.', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(802, 107, 9, 'Rắc kasuri methi và garam masala còn lại rồi phục vụ món gà handi nóng với naan hoặc rotis. Thưởng thức!', NULL, '2026-05-15 14:32:38', '2026-05-15 14:32:38'),
(803, 108, 1, 'Cho gừng, tỏi, nước tương, rượu sake và đường vào tô rồi đánh đều. Thêm thịt gà vào, sau đó khuấy đều cho ngấm đều. Đậy nắp và để lạnh ít nhất 1 giờ.', NULL, '2026-05-15 14:32:43', '2026-05-15 14:32:43'),
(804, 108, 2, 'Thêm 1 inch dầu thực vật vào nồi có đáy nặng và đun nóng cho đến khi dầu đạt 360 độ F. Lót 2 tờ khăn giấy vào giá đỡ rồi lấy kẹp ra. Cho tinh bột khoai tây vào tô', NULL, '2026-05-15 14:32:43', '2026-05-15 14:32:43'),
(805, 108, 3, 'Thêm một nắm thịt gà vào tinh bột khoai tây và đảo đều để bột phủ đều từng miếng.', NULL, '2026-05-15 14:32:43', '2026-05-15 14:32:43'),
(806, 108, 4, 'Chiên karaage theo từng mẻ cho đến khi bên ngoài có màu nâu vừa và gà chín đều. Chuyển gà rán vào giá có lót khăn giấy. Nếu muốn karaage giòn lâu hơn, bạn có thể chiên gà lần thứ hai, cho đến khi gà có màu đậm hơn sau khi nguội một lần. Ăn kèm với chanh.', NULL, '2026-05-15 14:32:43', '2026-05-15 14:32:43'),
(807, 109, 1, '1. Làm sạch và cắt thịt gà; ướp sơ với muối, bột nghệ và một ít dầu.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48'),
(808, 109, 2, '2. Rửa sạch và ngâm gạo basmati trong 20–30 phút.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48'),
(809, 109, 3, '3. Đun nóng bơ/dầu trong một nồi lớn. Chiên hành tây xắt nhỏ cho đến khi vàng. Thêm tỏi băm và ớt xanh vào xào trong 1–2 phút.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48'),
(810, 109, 4, '4. Thêm toàn bộ gia vị (bạch đậu khấu, đinh hương, quế, lá nguyệt quế) và gia vị xay (rau mùi, thì là). Khuấy cho đến khi có mùi thơm.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(811, 109, 5, '5. Thêm miếng thịt gà vào, chiên vàng nhạt và thêm đủ nước/nước luộc gà vào cho ngập. Đun nhỏ lửa cho đến khi thịt gà gần chín.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48'),
(812, 109, 6, '6. Lấy thịt gà ra; đo chất lỏng còn lại và thêm gạo ngâm. Đun sôi, sau đó giảm nhiệt, đậy nắp và nấu cơm cho đến khi gần chín.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48'),
(813, 109, 7, '7. Cho gà trở lại nồi cơm trên, đậy kín và hấp ở lửa nhỏ trong 10–15 phút để hương vị hòa quyện.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48'),
(814, 109, 8, '8. (Tùy chọn) Để có mùi thơm khói đích thực: đun một cục than nhỏ cho đến khi nóng đỏ, đặt than lên cốc giấy bạc nhỏ ở giữa nồi, thêm một thìa cà phê bơ/dầu lên than rồi đậy nắp ngay để bẫy khói trong 5–10 phút. Loại bỏ than.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48'),
(815, 109, 9, '9. Trang trí với hành tây chiên, rau mùi xắt nhỏ và dùng kèm tương ớt hoặc raita.', NULL, '2026-05-15 14:32:48', '2026-05-15 14:32:48'),
(816, 110, 1, 'Đun nóng dầu trong chảo lớn chống cháy và xào nấm cho đến khi chúng bắt đầu mềm. Thêm chân gà và nấu nhanh mỗi bên để tạo màu cho chúng một chút.', NULL, '2026-05-15 14:32:51', '2026-05-15 14:32:51'),
(817, 110, 2, 'Đổ passata vào, nghiền nát viên nước kho và cho ô liu vào khuấy đều. Nêm hạt tiêu đen – bạn không cần muối. Đậy nắp và đun nhỏ lửa trong 40 phút cho đến khi gà mềm. Rắc rau mùi tây và dùng kèm với mì ống và salad, hoặc khoai tây nghiền và rau xanh, nếu bạn thích.', NULL, '2026-05-15 14:32:51', '2026-05-15 14:32:51'),
(818, 111, 1, 'Đối với phần trên, luộc khoai tây trong nước muối cho đến khi mềm. Để ráo nước và đẩy qua máy nghiền khoai tây hoặc nghiền kỹ. Khuấy bơ, kem và lòng đỏ trứng. Nêm và đặt sang một bên.', NULL, '2026-05-15 14:32:57', '2026-05-15 14:32:57'),
(819, 111, 2, 'Để làm nhân, làm tan bơ trong chảo lớn. Thêm hẹ tây, cà rốt và cần tây vào xào nhẹ cho đến khi mềm, sau đó thêm tỏi. Đổ rượu vào và nấu trong 1 phút. Khuấy cà chua xay nhuyễn, cà chua cắt nhỏ rồi kho và nấu trong 10–15 phút cho đến khi đặc lại. Thêm thịt gà xé nhỏ, ô liu và rau mùi tây. Nêm muối và tiêu cho vừa ăn.', NULL, '2026-05-15 14:32:57', '2026-05-15 14:32:57'),
(820, 111, 3, 'Làm nóng lò ở mức 180C/160C Quạt/Gas 4.', NULL, '2026-05-15 14:32:57', '2026-05-15 14:32:57'),
(821, 111, 4, 'Cho nhân vào đĩa chịu nhiệt 20x30cm/8x12in và đặt khoai tây nghiền lên trên. Hãy ghi nhớ Gruyère. Nướng trong vòng 30–35 phút cho đến khi nóng và khoai tây có màu nâu vàng.', NULL, '2026-05-15 14:32:57', '2026-05-15 14:32:57'),
(822, 112, 1, 'Nấu quinoa theo hướng dẫn trên bao bì, sau đó rửa sạch bằng nước lạnh và để ráo nước.', NULL, '2026-05-15 14:33:02', '2026-05-15 14:33:02'),
(823, 112, 2, 'Trong khi đó, trộn bơ, ớt và tỏi thành hỗn hợp sệt. Cho phi lê gà vào 2 muỗng cà phê dầu ô liu cùng một ít gia vị. Đặt vào chảo nướng nóng và nướng trong 3-4 phút mỗi mặt hoặc cho đến khi chín đều. Chuyển ra đĩa, chấm bơ cay rồi đặt sang một bên cho tan chảy.', NULL, '2026-05-15 14:33:02', '2026-05-15 14:33:02'),
(824, 112, 3, 'Tiếp theo, cho cà chua, ô liu, hành tây, feta và bạc hà vào tô. Cho quinoa đã nấu chín vào. Khuấy đều dầu ô liu, nước chanh và vỏ còn lại rồi nêm gia vị. Ăn kèm với phi lê gà ở trên, rưới nước sốt gà bơ.', NULL, '2026-05-15 14:33:02', '2026-05-15 14:33:02'),
(825, 113, 1, 'Bắt đầu bằng cách cắt thịt gà của bạn thành những lát nhỏ vừa phải. Lấy túi ziplock của bạn và đổ thịt gà mới thái lát vào trong.', NULL, '2026-05-15 14:33:05', '2026-05-15 14:33:05'),
(826, 113, 2, 'Thêm tỏi, rau mùi, thì là, bạch đậu khấu, ớt cayenne, ớt bột, muối, hạt tiêu, nước cốt chanh và dầu ô liu vào túi. Đóng túi lại và trộn kỹ. Đặt trong tủ lạnh trong 10-12 giờ (ngắn hơn cũng được nhưng lâu hơn thì tốt hơn).', NULL, '2026-05-15 14:33:05', '2026-05-15 14:33:05'),
(827, 113, 3, 'Sau khi đã sẵn sàng nấu, hãy làm nóng chảo rán của bạn ở mức trung bình cao và thêm một chút dầu ô liu. Chiên một mặt của tất cả các loại bánh mì dẹt của bạn cho đến khi hơi chín. Lấy chảo ra, cho lượng dầu vừa đủ vào chảo. Cho khoai tây chiên vụn vào nồi chiên không khí ở mức 180 trong 15 phút, thỉnh thoảng lắc.', NULL, '2026-05-15 14:33:05', '2026-05-15 14:33:05'),
(828, 113, 4, 'Lúc này chảo đã khá nóng, hãy cho gà làm 2 mẻ (trừ khi bạn có chảo rán lớn) để tránh tình trạng quá đông. Con gà sẽ có màu da đẹp và đậm hơn là hoàn hảo. Nấu thêm 5-8 phút nữa hoặc cho đến khi chín. Lặp lại với mẻ gà tiếp theo.', NULL, '2026-05-15 14:33:05', '2026-05-15 14:33:05'),
(829, 113, 5, 'Trong khi nấu gà, hãy cho sữa chua Hy Lạp vào tô. Kết hợp tỏi, bạc hà thái nhỏ và rau mùi tây, vắt chanh và thì là. Trộn và thêm muối cho vừa ăn. Trong một bát nhỏ, trộn 1 thìa cà phê bột tỏi, ớt bột, thì là, bột hành tây, lá oregano, rau mùi tây khô, ớt cayenne (tùy chọn) và để sang một bên cho khoai tây chiên.', NULL, '2026-05-15 14:33:05', '2026-05-15 14:33:05'),
(830, 113, 6, 'Nêm khoai tây chiên ngay sau khi nấu chín và thêm muối cho vừa ăn. Sau khi gà đã hoàn thành, hãy dùng ngay bằng cách bày bánh mì dẹt ra, phết đều nước sốt lên bánh mì, thêm rau diếp, hành tây, cà chua, khoai tây chiên, thịt gà, feta và thêm nước sốt lên trên. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:33:05', '2026-05-15 14:33:05'),
(832, 114, 1, 'Dùng một chiếc kéo nhà bếp sắc bén, cắt mỗi cánh ở đốt ngón tay thành hai mảnh. Trộn tỏi, vỏ chanh và nước ép, thì là và dầu với nhiều gia vị, sau đó cho vào đĩa có cánh gà và trộn đều. Đậy kín và cho vào tủ lạnh để ướp ít nhất 1 tiếng hoặc qua đêm nếu có thời gian.', NULL, '2026-05-15 14:33:09', '2026-05-16 12:35:33'),
(834, 114, 2, 'Làm nóng lò nướng ở nhiệt độ 200C/180C quạt/gas 6 hoặc hâm nóng món nướng ngoài trời. Nướng cánh gà trên khay nướng trong 45-50 phút cho đến khi giòn hoặc nướng trong 20 phút, rưới mật ong trong 10 phút cuối cùng của mỗi phương pháp. Bày ra đĩa có nhiều khăn giấy. Đổ đầy các bát nhỏ với ô liu, quả hồ trăn hoặc hạnh nhân, chà là, ớt ngâm và bánh mì dẹt để phục vụ cùng với các món ăn dưới đây.', NULL, '2026-05-15 14:33:09', '2026-05-16 12:35:33'),
(836, 115, 1, 'Đun nóng chảo lớn trên lửa cao và nêm thịt gà. Thêm dầu ô liu vào chảo, sau đó cho thịt gà vào. Chiên khoảng 5 phút mỗi mặt, gắp ra đĩa rồi đặt sang một bên.', NULL, '2026-05-15 14:33:12', '2026-05-16 12:35:33'),
(838, 115, 2, 'Giảm nhiệt xuống mức trung bình. Với lượng mỡ còn lại, xào hành tây trong 3 phút, sau đó thêm tỏi và nghệ tây. Nấu thêm 3-4 phút nữa. Thêm rượu sherry vào, sau đó đun nhỏ lửa trong 3-5 phút cho đến khi có dạng siro.', NULL, '2026-05-15 14:33:12', '2026-05-16 12:35:33'),
(840, 115, 3, 'Cho các miếng chân gà trở lại chảo, cho nước luộc, húng tây và nho khô vào, đậy nắp rồi nấu nhẹ ở lửa nhỏ trong 20 phút. Thêm thịt ức và bất kỳ nước trái cây nào còn lại trên đĩa. Đun nhỏ lửa thêm 10 phút cho đến khi chín và nước sốt trong chảo giảm bớt.', NULL, '2026-05-15 14:33:12', '2026-05-16 12:35:33'),
(842, 115, 4, 'Trong khi gà đang nấu, làm nóng lò ở mức quạt/gas 200C/180C 6. Rải hạt thông lên khay nướng, sau đó nướng trong 10 phút cho đến khi chín vàng. Khi gà đã chín, nêm nếm vừa ăn, rắc hạt thông và rau mùi tây rồi dùng với cơm.', NULL, '2026-05-15 14:33:12', '2026-05-16 12:35:33'),
(843, 116, 1, 'Làm nước sốt cam:', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(844, 116, 2, 'Đánh đều các thành phần nước sốt trong một bát vừa. Đặt sang một bên.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(845, 116, 3, 'Chuẩn bị gà:', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(846, 116, 4, 'Cắt thịt gà thành khối khoảng 1 inch. Đánh trứng với muối và hạt tiêu đen vào tô rồi thêm thịt gà vào. Khuấy đều.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(847, 116, 5, 'Trong một bát riêng, trộn đều bột mì và bột bắp. Dùng thìa hoặc kẹp có rãnh vớt gà ra khỏi trứng, để trứng thừa ráo nước rồi chuyển sang hỗn hợp bột bắp và tráng đều.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(848, 116, 6, 'Chiên gà:', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(849, 116, 7, 'Thêm dầu vào chảo lớn 10 đến 12 inch. Đun trên lửa vừa cao cho đến khi đạt nhiệt độ 350°F. Nếu không có nhiệt kế, bạn cũng có thể kiểm tra nhiệt độ bằng cách rắc một ít bột mì vào. Nếu dầu đủ nóng, dầu sẽ xì hơi ngay lập tức.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(850, 116, 8, 'Khi dầu nóng, chiên gà làm hai mẻ. Dầu có thể không bao phủ hoàn toàn con gà—điều đó không sao cả. Nấu trong 3 đến 4 phút. Lật miếng thịt gà và nấu cho đến khi gà chín, khoảng 3 đến 4 phút nữa. Tổng thời gian nấu khoảng 6 đến 8 phút.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(851, 116, 9, 'Gắp gà rán thành từng khối rồi chuyển ra đĩa có lót sẵn khăn giấy để gà ráo nước. Lặp lại cho đến khi tất cả thịt gà được nấu chín.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(852, 116, 10, 'Ướp gà trong nước sốt:', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(853, 116, 11, 'Sau khi gà chín, đổ dầu nóng ra và lau sạch chảo. Thêm một thìa dầu tươi cùng với tỏi và hẹ tây xắt nhỏ. Nấu trong một phút rồi thêm nước sốt. Đun nhỏ nước sốt cho đến khi nó bắt đầu đặc lại.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(854, 116, 12, 'Khi nước sốt sủi bọt nhẹ, thêm gà rán vào và trộn đều. Nước sốt sẽ tiếp tục đặc lại và dính vào thịt gà. Để lửa nhỏ thêm một hoặc hai phút nữa. Dùng gà cam với cơm trắng nấu chín, trang trí với hạt vừng và hành lá tươi.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(855, 116, 13, 'Bạn có thích công thức này không? Hãy cho chúng tôi biết bằng cách đánh giá và đánh giá!', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(856, 116, 14, 'THỪA CÒN! Gà màu cam bảo quản tốt trong tủ lạnh trong 5 ngày. Đun nóng trong chảo với một chút nước trên lửa nhỏ. Làm đông lạnh gà màu cam trong tối đa 3 tháng, nhưng hãy nhớ rã đông trước khi hâm nóng để gà không bị vón cục lại với nhau.', NULL, '2026-05-15 14:33:16', '2026-05-15 14:33:16'),
(857, 117, 1, 'Đun nóng 1 muỗng canh dầu trong chảo lớn, đế nặng hoặc đĩa chống cháy. Cho thịt xông khói vào và chiên cho đến khi giòn. Lấy ra và để ráo trên giấy ăn. Thêm hẹ vào chảo và chiên, khuấy hoặc lắc chảo thường xuyên trong 5-8 phút cho đến khi chín vàng đều. Hủy bỏ và đặt sang một bên với thịt xông khói.', NULL, '2026-05-15 14:33:19', '2026-05-15 14:33:19'),
(858, 117, 2, 'Lau khô miếng gà bằng giấy ăn. Đổ lượng dầu còn lại vào chảo, sau đó chiên nửa miếng gà, đảo đều trong 5-8 phút cho đến khi chín vàng. Hủy bỏ, sau đó lặp lại với con gà còn lại. Loại bỏ và đặt sang một bên.', NULL, '2026-05-15 14:33:19', '2026-05-15 14:33:19'),
(859, 117, 3, 'Rắc tỏi vào và chiên nhanh, sau đó, ở lửa vừa cao, đổ rượu mạnh hoặc Cognac vào, khuấy đáy chảo để khử men. Rượu sẽ kêu xèo xèo và bắt đầu bay hơi nên không còn nhiều.', NULL, '2026-05-15 14:33:19', '2026-05-15 14:33:19'),
(860, 117, 4, 'Cho chân và đùi gà vào chảo cùng với nước cốt, sau đó đổ một ít rượu vào, khuấy đều đáy chảo một lần nữa. Khuấy phần rượu còn lại, nước kho và bột cà chua xay nhuyễn, thả bó hoa trang trí vào, nêm hạt tiêu và một chút muối, sau đó cho thịt xông khói và hẹ tây vào chảo. Đậy nắp, giảm lửa cho sôi nhẹ, cho ức gà vào nấu trong 50 phút-1 giờ.', NULL, '2026-05-15 14:33:19', '2026-05-15 14:33:19'),
(861, 117, 5, 'Ngay trước khi sẵn sàng phục vụ, hãy đun nóng dầu cho nấm trong chảo chống dính lớn. Thêm nấm và chiên trên lửa cao trong vài phút cho đến khi vàng. Loại bỏ và giữ ấm.', NULL, '2026-05-15 14:33:19', '2026-05-15 14:33:19'),
(862, 117, 6, 'Nhấc gà, hẹ tây và thịt xông khói ra khỏi chảo và chuyển sang đĩa ăn đã hâm nóng. Loại bỏ bó hoa trang trí. Để làm chất làm đặc, trộn bột mì, dầu ô liu và bơ vào một chiếc bát nhỏ bằng cách sử dụng mặt sau của một thìa cà phê. Đun sôi nhẹ hỗn hợp rượu, sau đó thả từng miếng nhỏ chất làm đặc vào, dùng máy đánh trứng đánh từng miếng. Đun nhỏ lửa trong 1-2 phút. Rắc nấm lên gà, sau đó rưới sốt rượu vang lên. Trang trí với rau mùi tây xắt nhỏ.', NULL, '2026-05-15 14:33:19', '2026-05-15 14:33:19'),
(863, 118, 1, 'Cho ức gà chưa nấu chín vào nồi sành. Đổ đầy chai nước sốt salad lên gà. Rắc phần nguyên liệu còn lại lên trên và dùng thìa trộn một chút.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(864, 118, 2, 'Đậy nắp nồi sành và nấu ở nhiệt độ cao trong 4 giờ.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(865, 118, 3, 'Lấy tất cả ức gà ra khỏi nồi sành và để nguội.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(866, 118, 4, 'Cắt nhỏ ức gà và chuyển vào tô thủy tinh.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(867, 118, 5, 'Đổ hầu hết chất lỏng lên gà xé.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(868, 118, 6, 'ĐỐI VỚI TACOS:', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(869, 118, 7, 'Làm nước sốt guacamole bằng cách trộn bơ và salsa xanh với nhau. Đổ hỗn hợp guacamole qua lưới lọc cho đến khi mịn và chuyển vào chai bóp. Cắt phần đầu của nắp chai bóp để mở rộng hơn nếu cần.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(870, 118, 8, 'Làm sốt kem chua bằng cách trộn kem chua và sữa với nhau cho đến khi bạn có được sốt kem chua lỏng hơn. Chuyển sang một chai bóp.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(871, 118, 9, 'Trong đĩa nướng thủy tinh 9x13, đổ đầy tất cả hơn 12 chiếc bánh taco với một lớp đậu chiên, thịt gà nấu chín và phô mai cắt nhỏ.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(872, 118, 10, 'Nướng ở nhiệt độ 450 trong 10-15 phút cho đến khi phô mai tan chảy và sủi bọt.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(873, 118, 11, 'Lấy tất cả các bánh taco ra khỏi lò với cà chua nho thái lát, ớt jalapeno và ngò.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(874, 118, 12, 'Kết thúc với một chút guacamole và kem chua.', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(875, 118, 13, 'Thưởng thức!', NULL, '2026-05-15 14:33:22', '2026-05-15 14:33:22'),
(877, 119, 1, 'Làm nóng lò nướng ở nhiệt độ 200C/180C quạt/gas 6. Đun nóng dầu ô liu trong chảo rán lớn chịu nhiệt trên lửa vừa và xào hành tây, chorizo và ớt cùng với một chút muối và hạt tiêu trong 15 phút cho đến khi rau mềm và chorizo tiết ra dầu. Thêm ớt bột và tỏi vào, nấu thêm vài phút nữa cho đến khi có mùi thơm.', NULL, '2026-05-15 14:33:26', '2026-05-16 12:35:33'),
(879, 119, 2, 'Cho cà chua cắt nhỏ, ô liu và đậu bơ vào, khuấy đều và nêm gia vị. Nhúng đùi gà vào và nêm nếm vừa ăn. Chuyển vào lò nướng và nướng trong 40 phút cho đến khi da gà giòn và thịt chín và mềm. Rắc rau mùi tây và phục vụ.', NULL, '2026-05-15 14:33:26', '2026-05-16 12:35:33'),
(880, 119, 3, 'Xem sau quảng cáo (0,04):', NULL, '2026-05-15 14:33:26', '2026-05-16 12:35:33'),
(881, 119, 4, '3 ý tưởng trứng ngân sách', NULL, '2026-05-15 14:33:26', '2026-05-16 12:35:33'),
(882, 120, 1, 'Làm nóng lò ở 425 độ. Rửa và lau khô tất cả sản phẩm. Cắt, gọt vỏ và cắt cà rốt theo đường chéo thành từng miếng dày ¼ inch. Cắt khoai tây thành miếng ½ inch. Cắt đôi, gọt vỏ và cắt lát mỏng hành tây.', NULL, '2026-05-15 14:33:28', '2026-05-15 14:33:28'),
(883, 120, 2, 'Cho cà rốt lên khay nướng với một ít dầu, muối và tiêu. Nướng cho đến khi chín vàng và mềm, khoảng 15-20 phút.', NULL, '2026-05-15 14:33:28', '2026-05-15 14:33:28'),
(884, 120, 3, 'Trong khi đó, đặt khoai tây vào nồi vừa với lượng nước muối vừa đủ ngập 2 inch. Đun sôi và nấu cho đến khi mềm, 12-15 phút. Để ráo nước và cho khoai tây vào nồi; đậy lại để giữ ấm.', NULL, '2026-05-15 14:33:28', '2026-05-15 14:33:28'),
(885, 120, 4, 'Trong khi nấu khoai tây, đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm hành tây và nấu, thỉnh thoảng khuấy cho đến khi hành tây chuyển sang màu nâu nhạt và mềm, khoảng 8-10 phút. Rắc 1 thìa cà phê đường (2 thìa cà phê cho 4 phần ăn). Khuấy nước cô đặc và 2 muỗng canh nước (¼ cốc cho 4 người); nêm muối và hạt tiêu. Nấu cho đến khi mứt, thêm 2-3 phút nữa. Tắt nhiệt; chuyển sang một cái bát nhỏ. Rửa sạch chảo.', NULL, '2026-05-15 14:33:29', '2026-05-15 14:33:29'),
(886, 120, 5, 'Lau khô gà bằng khăn giấy; nêm đều muối và hạt tiêu. Đun nóng một ít dầu trong chảo dùng cho hành tây trên lửa vừa cao. Thêm thịt gà vào và nấu cho đến khi chín vàng, khoảng 5-6 phút mỗi mặt. Trong 1-2 phút nấu cuối cùng, phủ hành tây và phô mai caramen lên trên. Đậy chảo cho đến khi phô mai tan chảy. (Nếu chảo của bạn không có nắp, hãy phủ một tấm nướng bánh!)', NULL, '2026-05-15 14:33:29', '2026-05-15 14:33:29'),
(887, 120, 6, 'Đun nóng nồi khoai tây đã ráo nước trên lửa nhỏ; nghiền với kem chua, 2 muỗng canh bơ (4 muỗng canh cho 4 phần ăn), muối, tiêu và một chút nước (hoặc sữa, để thêm đậm đà) cho đến khi mịn. Chia thịt gà, cà rốt nướng và khoai tây nghiền vào các đĩa.', NULL, '2026-05-15 14:33:29', '2026-05-15 14:33:29'),
(888, 121, 1, 'HƯỚNG DẪN:', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(889, 121, 2, 'BƯỚC 1 - SỐT', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(890, 121, 3, 'Trong một cái bát, thêm 2 cốc nước, 2 thìa canh nước tương, 2 thìa canh giấm trắng, rượu nấu sherry, 1/4 thìa cà phê tiêu trắng, gừng băm, tỏi băm, ớt cay, sốt cà chua, sốt tương đen và đường.', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(891, 121, 4, 'Trộn đều và đặt sang một bên.', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(892, 121, 5, 'BƯỚC 2 – Ướp GÀ', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(893, 121, 6, 'Cho thịt gà, 1 nhúm muối, 1 nhúm tiêu trắng, 2 lòng trắng trứng và 3 thìa tinh bột ngô vào tô', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(894, 121, 7, 'BƯỚC 3 - CHIÊN GÀ', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(895, 121, 8, 'Chiên gà ở nhiệt độ 350 độ trong 3-4 phút hoặc cho đến khi vàng nâu rồi thả gà ra để chúng không dính vào nhau.', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(896, 121, 9, 'Đặt gà sang một bên.', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(897, 121, 10, 'BƯỚC 4 - Xào', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(898, 121, 11, 'Thêm nước sốt vào chảo rồi cho bông cải xanh vào và đợi cho đến khi sôi.', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(899, 121, 12, 'Để làm đặc nước sốt, trộn 2 muỗng canh bột ngô và 4 muỗng canh nước vào tô rồi từ từ thêm vào món xào cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(900, 121, 13, 'Tiếp theo cho thịt gà vào xào khoảng một phút rồi bày ra đĩa', NULL, '2026-05-15 14:33:32', '2026-05-15 14:33:32'),
(901, 122, 1, '2 phần ăn', NULL, '2026-05-15 14:33:35', '2026-05-15 14:33:35'),
(902, 122, 2, '1. Làm nóng lò ở nhiệt độ 425 độ. Rửa và lau khô tất cả sản phẩm. Cắt khoai tây thành miếng dày 1/2 inch. Rưới một ít dầu, muối và tiêu lên một mặt của khay nướng. (Đối với 4 phần ăn, trải khoai tây ra toàn bộ tờ giấy.) Nướng trên giá trên cùng trong 5 phút (sau đó chúng ta sẽ thêm bông cải xanh).', NULL, '2026-05-15 14:33:35', '2026-05-15 14:33:35'),
(903, 122, 3, '2. Trong khi đó, cắt bông cải xanh thành miếng vừa ăn, nếu cần. Bóc vỏ và băm nhuyễn tỏi. Trong một bát nhỏ an toàn với lò vi sóng, trộn 1 muỗng canh dầu ô liu (2 muỗng canh cho 4 phần ăn) và một nửa số tỏi. Cho vào lò vi sóng cho đến khi tỏi kêu xèo xèo, 30 giây.', NULL, '2026-05-15 14:33:35', '2026-05-15 14:33:35'),
(904, 122, 4, '3. Sau khi khoai tây đã nướng được 5 phút, lấy khay ra khỏi lò và thêm bông cải xanh vào mặt trống; cẩn thận trộn với dầu tỏi, muối và hạt tiêu. (Đối với 4 phần ăn, thêm bông cải xanh vào tờ thứ hai.) Tiếp tục rang cho đến khi khoai tây và bông cải xanh có màu nâu vàng và giòn, thêm 15-20 phút nữa.', NULL, '2026-05-15 14:33:35', '2026-05-15 14:33:35'),
(905, 122, 5, '4. Trong khi nướng rau, dùng khăn giấy thấm khô gà; nêm đều muối và hạt tiêu. Đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm thịt gà vào và nấu cho đến khi chín vàng, khoảng 5-6 phút mỗi mặt. (Nếu gà chín quá nhanh thì giảm lửa vừa.) Tắt lửa; đặt gà sang một bên để nghỉ ngơi. Rửa sạch chảo.', NULL, '2026-05-15 14:33:35', '2026-05-15 14:33:35'),
(906, 122, 6, '5. Đun nóng chảo gà trên lửa vừa cao. Thêm một chút dầu và số tỏi còn lại; nấu cho đến khi có mùi thơm, 30 giây. Khuấy giấm, mật ong, nước kho cô đặc và 1/4 cốc nước (1/3 cốc cho 4 phần ăn). Đun nhỏ lửa cho đến khi đặc và bóng, khoảng 2-3 phút. Tắt bếp và cho 1 muỗng canh bơ vào khuấy (2 muỗng canh cho 4 người). Nêm muối và hạt tiêu.', NULL, '2026-05-15 14:33:35', '2026-05-15 14:33:35'),
(907, 122, 7, '6. Cho gà trở lại chảo và tráng men. Chia thịt gà, bông cải xanh và khoai tây vào các đĩa. Rưới phần men còn lại lên thịt gà và thưởng thức.', NULL, '2026-05-15 14:33:35', '2026-05-15 14:33:35'),
(908, 123, 1, 'Thiết bị', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(909, 123, 2, 'Lò Hà Lan', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(910, 123, 3, 'Hướng dẫn', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(911, 123, 4, 'Cho đùi gà, gia vị đa năng, 1 thìa bột cà ri, hành tây, hành lá, tiêu xanh, tép tỏi, hạt tiêu scotch (nếu dùng) và húng tây vào tô lớn rồi trộn đều, đảm bảo tất cả các miếng gà đều được phủ đều gia vị. Đậy nắp và để lạnh ít nhất 1 giờ hoặc qua đêm.', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(912, 123, 5, 'Một con gà đã ướp xong, bỏ hành, ớt và tép tỏi ra khỏi thịt gà rồi để sang một bên.', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(913, 123, 6, 'Đun nóng dầu ô liu trong nồi lớn có đáy nặng trên lửa vừa. Thêm bột cà ri còn lại vào và khuấy đều, nấu trong khoảng 20-30 giây. Cho hành tây, ớt xanh, tép tỏi, húng tây và ớt scotch (nếu dùng) vào nồi và khuấy đều cho đến khi hành mềm, khoảng 3-5 phút. Nếu hành và ớt của bạn trông khô, hãy thêm khoảng 1 thìa nước.', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(914, 123, 7, 'Cho gà và ¼ cốc nước vào nồi. Đậy nắp và giảm nhiệt xuống mức trung bình thấp. Nấu, thỉnh thoảng khuấy trong 30-35 phút.', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(915, 123, 8, 'Khi còn khoảng 15 phút, cho khoai tây vào đảo đều và đậy nắp tiếp tục nấu.', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(916, 123, 9, 'Sau khi gà chín và khoai tây mềm thì tắt bếp. Muối và hạt tiêu cho vừa ăn.', NULL, '2026-05-15 14:33:40', '2026-05-15 14:33:40'),
(917, 124, 1, 'Để làm nước xốt giật, cho tất cả nguyên liệu vào máy xay thực phẩm cùng với 1 thìa cà phê muối và xay thành hỗn hợp nhuyễn. Nếu bạn gặp khó khăn khi xay, chỉ cần tắt máy xay, khuấy hỗn hợp và thử lại. Cuối cùng, nó sẽ bắt đầu hòa quyện - đừng cố thêm nước vì bạn muốn có một hỗn hợp sệt.', NULL, '2026-05-15 14:33:44', '2026-05-15 14:33:44'),
(918, 124, 2, 'Nếm thử hỗn hợp gia vị đã trộn – nó sẽ có vị khá mặn nhưng không khó chịu, mặn chát. Bây giờ bạn có thể cho thêm ớt vào nếu thấy chưa đủ cay. Nếu nó có vị quá mặn và chua, hãy thử thêm một chút đường nâu cho đến khi hỗn hợp có vị cân bằng.', NULL, '2026-05-15 14:33:44', '2026-05-15 14:33:44'),
(919, 124, 3, 'Rạch một vài đường trên đùi gà rồi rưới nước xốt lên thịt, chà xát vào tất cả các kẽ hở. Đậy nắp và để ướp qua đêm trong tủ lạnh.', NULL, '2026-05-15 14:33:44', '2026-05-15 14:33:44'),
(920, 124, 4, 'Nếu bạn muốn nướng thịt gà, hãy để than cháy khoảng 1 giờ trước khi sẵn sàng nấu. Thịt giật đích thực không phải là nướng chính xác như chúng ta nghĩ về nướng mà là kiểu nướng khói. Để có được trải nghiệm chân thực hơn, hãy thêm một ít dăm gỗ vào món thịt nướng của bạn và nấu gà ở nhiệt độ chậm, gián tiếp trong 30 phút. Để nấu trong lò, làm nóng quạt/khí ở nhiệt độ 180C/160C 4. Cho các miếng thịt gà vào hộp nướng cùng với hai nửa quả chanh và nấu trong 45 phút cho đến khi mềm và chín.', NULL, '2026-05-15 14:33:44', '2026-05-15 14:33:44'),
(921, 124, 5, 'Trong khi luộc gà, chuẩn bị cơm và đậu Hà Lan. Xả gạo với nhiều nước lạnh, sau đó cho gạo vào nồi lớn cùng tất cả nguyên liệu còn lại trừ đậu thận. Nêm muối, thêm 300ml nước lạnh rồi đun trên lửa lớn. Khi cơm bắt đầu sôi, vặn lửa vừa, đậy nắp và nấu trong 10 phút.', NULL, '2026-05-15 14:33:44', '2026-05-15 14:33:44'),
(922, 124, 6, 'Cho đậu vào cơm, sau đó đậy nắp lại. Tắt lửa trong 5 phút cho đến khi hấp thụ hết chất lỏng. Vắt chanh rang lên gà và dùng kèm cơm, đậu Hà Lan và một ít nước sốt nóng nếu bạn thích cay.', NULL, '2026-05-15 14:33:44', '2026-05-15 14:33:44'),
(923, 125, 1, 'Caramel gà với dầu ô liu sau đó thêm một viên maggi và đun sôi trong khoảng 30 phút.', NULL, '2026-05-15 14:33:47', '2026-05-15 14:33:47'),
(924, 125, 2, 'Trong một nồi khác, thêm tất cả các loại rau và caramen cho đến khi chúng mềm.', NULL, '2026-05-15 14:33:47', '2026-05-15 14:33:47'),
(925, 125, 3, 'Sau khi mọi thứ đã xong, cho gạo, nho khô và gia vị vào rau rồi thêm 2 cốc rưỡi nước để nấu cơm.', NULL, '2026-05-15 14:33:47', '2026-05-15 14:33:47'),
(926, 125, 4, 'Sau khi cơm chín, cho mọi thứ vào lò nướng.', NULL, '2026-05-15 14:33:47', '2026-05-15 14:33:47'),
(927, 126, 1, 'Chuẩn bị:15 phút > Nấu: 30 phút > Sẵn sàng: 45 phút', NULL, '2026-05-15 14:33:53', '2026-05-15 14:33:53'),
(928, 126, 2, 'Đối với nước sốt cà ri: Đun nóng dầu trong chảo chống dính vừa, thêm hành tây và tỏi vào nấu cho đến khi mềm. Khuấy cà rốt và nấu trên lửa nhỏ trong 10 đến 12 phút.', NULL, '2026-05-15 14:33:53', '2026-05-15 14:33:53'),
(929, 126, 3, 'Thêm bột mì và bột cà ri; nấu trong 1 phút. Từ từ khuấy đều cho đến khi hòa quyện; thêm mật ong, nước tương và lá nguyệt quế. Từ từ đun sôi.', NULL, '2026-05-15 14:33:53', '2026-05-15 14:33:53'),
(930, 126, 4, 'Giảm nhiệt và đun nhỏ lửa trong 20 phút hoặc cho đến khi nước sốt đặc lại nhưng vẫn có độ sệt. Khuấy garam masala. Đổ nước sốt cà ri qua rây; trở lại chảo và giữ ở lửa nhỏ cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:33:53', '2026-05-15 14:33:53'),
(931, 126, 5, 'Đối với thịt gà: Nêm muối và hạt tiêu vào cả hai mặt ức gà. Cho bột mì, trứng và vụn bánh mì vào các bát riêng rồi xếp thành một hàng. Lăn ức gà qua bột mì, sau đó nhúng vào trứng, sau đó lăn qua vụn bánh mì, đảm bảo phủ kín cả hai mặt.', NULL, '2026-05-15 14:33:53', '2026-05-15 14:33:53'),
(932, 126, 6, 'Đun nóng dầu trong chảo lớn trên lửa vừa cao. Cho gà vào dầu nóng và chiên cho đến khi vàng nâu, khoảng 3 hoặc 4 phút mỗi mặt. Sau khi chín, đặt lên giấy ăn để thấm bớt dầu thừa.', NULL, '2026-05-15 14:33:53', '2026-05-15 14:33:53'),
(933, 126, 7, 'Rưới nước sốt cà ri lên gà, dùng kèm cơm trắng và thưởng thức!', NULL, '2026-05-15 14:33:53', '2026-05-15 14:33:53'),
(934, 127, 1, 'Làm nóng lò chiên ở nhiệt độ 350°F. Trộn thật đều tất cả các nguyên liệu làm hỗn hợp gia vị.', NULL, '2026-05-15 14:33:55', '2026-05-15 14:33:55'),
(935, 127, 2, 'Trộn hỗn hợp gia vị với bột mì, đường nâu và muối.', NULL, '2026-05-15 14:33:55', '2026-05-15 14:33:55'),
(936, 127, 3, 'Nhúng miếng gà vào lòng trắng trứng để tráng nhẹ rồi chuyển sang hỗn hợp bột. Lật vài lần và đảm bảo hỗn hợp bột thực sự dính vào gà. Lặp lại với tất cả các miếng thịt gà.', NULL, '2026-05-15 14:33:55', '2026-05-15 14:33:55'),
(937, 127, 4, 'Để miếng gà nghỉ trong 5 phút để lớp vỏ có cơ hội khô một chút.', NULL, '2026-05-15 14:33:55', '2026-05-15 14:33:55'),
(938, 127, 5, 'Chiên gà theo mẻ. Vú và cánh sẽ mất 12-14 phút, còn chân và đùi sẽ cần thêm vài phút. Miếng thịt gà chín khi nhiệt kế thịt được đưa vào phần dày nhất cho thấy nhiệt độ là 165°F.', NULL, '2026-05-15 14:33:55', '2026-05-15 14:33:55'),
(939, 127, 6, 'Để gà ráo nước trên một ít khăn giấy khi lấy ra khỏi nồi chiên. Ăn nóng.', NULL, '2026-05-15 14:33:55', '2026-05-15 14:33:55'),
(940, 128, 1, 'Kết hợp rượu sake hoặc rượu gạo, nước tương, dầu mè và bột ngô hòa tan trong nước. Chia hỗn hợp làm đôi.', NULL, '2026-05-15 14:33:59', '2026-05-15 14:33:59'),
(941, 128, 2, 'Trong một đĩa thủy tinh hoặc bát, trộn một nửa hỗn hợp rượu sake với các miếng thịt gà và trộn đều. Đậy đĩa và để trong tủ lạnh khoảng 30 phút.', NULL, '2026-05-15 14:33:59', '2026-05-15 14:33:59'),
(942, 128, 3, 'Trong một chảo vừa, trộn hỗn hợp rượu sake còn lại, ớt, giấm và đường. Trộn đều rồi thêm hành lá, tỏi, hạt dẻ nước và đậu phộng vào. Đun nóng nước sốt từ từ trên lửa vừa cho đến khi có mùi thơm.', NULL, '2026-05-15 14:33:59', '2026-05-15 14:33:59'),
(943, 128, 4, 'Trong khi đó, lấy thịt gà ra khỏi nước xốt và xào trong chảo lớn cho đến khi nước trong. Khi nước sốt có mùi thơm thì cho gà đã xào vào đun nhỏ lửa cho đến khi nước sốt đặc lại.', NULL, '2026-05-15 14:33:59', '2026-05-15 14:33:59'),
(944, 129, 1, 'Cắt nhuyễn 1/4 quả ớt, sau đó cho phần còn lại vào máy xay thực phẩm cùng với gừng, tỏi, cọng rau mùi và 1/3 số lá. Đánh thành hỗn hợp sệt với một chút nước nếu cần.', NULL, '2026-05-15 14:34:02', '2026-05-15 14:34:02'),
(945, 129, 2, 'Đun nóng dầu trong chảo, sau đó chiên nhanh miếng gà trong 1 phút. Khuấy hỗn hợp thêm một phút nữa, sau đó thêm bơ đậu phộng, nước kho và sữa chua. Khi nước sốt sủi bọt nhẹ, nấu trong 10 phút cho đến khi gà vừa chín và nước sốt đặc lại. Khuấy hầu hết số rau mùi còn lại, sau đó rải phần còn lại lên trên cùng với ớt nếu dùng. Ăn với cơm hoặc khoai lang nghiền.', NULL, '2026-05-15 14:34:02', '2026-05-15 14:34:02'),
(946, 130, 1, 'Trộn nước sốt vào tô nhỏ.', NULL, '2026-05-15 14:34:04', '2026-05-15 14:34:04'),
(947, 130, 2, 'Băm tỏi vào chảo dầu. Đặt trên lửa lớn, khi nóng thì cho thịt gà và cọng bông cải xanh vào nấu đến khi gà có màu vàng nhạt.', NULL, '2026-05-15 14:34:04', '2026-05-15 14:34:04'),
(948, 130, 3, 'Đẩy sang một bên chảo, đập trứng vào và tráng. Đừng lo lắng nếu nó dính vào đáy chảo - nó sẽ cháy thành than và làm tăng thêm hương vị đích thực.', NULL, '2026-05-15 14:34:04', '2026-05-15 14:34:04'),
(949, 130, 4, 'Thêm mì, lá bông cải xanh và nước sốt. Trộn nhẹ nhàng cho đến khi sợi mì có màu sẫm và lá héo. Phục vụ ngay lập tức!', NULL, '2026-05-15 14:34:04', '2026-05-15 14:34:04'),
(951, 131, 1, 'Đầu tiên, làm bột cà ri. Dùng chày và cối giã nhuyễn ớt khô và ớt tươi, mắm tôm, tỏi, riềng, sả, vỏ chanh, tiêu trắng, rau mùi, thì là, nhục đậu khấu và đậu phộng, cộng thêm 1 thìa cà phê muối. Bạn nên có một dán thô. Ngoài ra, bạn có thể cho tất cả nguyên liệu vào máy xay thực phẩm cùng với 2-3 thìa nước cốt dừa và xay cho đến khi thu được hỗn hợp sệt. Bảo quản trong lọ có nắp đậy trong tủ lạnh. Sẽ giữ được tối đa hai tuần.', NULL, '2026-05-15 14:34:08', '2026-05-16 12:35:33'),
(953, 131, 2, 'Thêm 2-3 muỗng canh phần nước cốt dừa đặc vào nồi trên lửa vừa cao. Khi nước cốt dừa bắt đầu sủi bọt, thêm 1-2 thìa canh bột cà ri vào và khuấy đều khoảng 1 phút cho đến khi có mùi thơm.', NULL, '2026-05-15 14:34:08', '2026-05-16 12:35:33'),
(955, 131, 3, 'Cho gà vào đun khoảng 3-4 phút cho đến khi gà chuyển sang màu nâu vàng. Tiếp theo với đậu Pháp và khuấy đều.', NULL, '2026-05-15 14:34:08', '2026-05-16 12:35:33'),
(957, 131, 4, 'Nêm nước mắm và đường rồi cho phần nước cốt dừa còn lại vào. Trộn đều, thêm nửa lá chanh makrut vào đun nhỏ lửa trong 3-5 phút cho đến khi gà chín. Nếm thử và thêm đường hoặc nước mắm nếu cần - nước mắm phải có vị mặn, bùi và vị ngọt. Thêm lá húng quế Thái vào, trộn nhanh và tắt lửa. Ăn kèm cơm hoa nhài hấp, trang trí với ớt thái lát và phần còn lại của lá chanh makrut.', NULL, '2026-05-15 14:34:08', '2026-05-16 12:35:33'),
(958, 132, 1, 'BƯỚC 1', NULL, '2026-05-15 14:34:10', '2026-05-15 14:34:10'),
(959, 132, 2, 'Trộn đều tất cả nguyên liệu làm nước xốt trong máy xay thực phẩm nhỏ. Xoa nước xốt lên gà và để trong 1 giờ ở nhiệt độ phòng.', NULL, '2026-05-15 14:34:10', '2026-05-15 14:34:10'),
(960, 132, 3, 'BƯỚC 2', NULL, '2026-05-15 14:34:10', '2026-05-15 14:34:10'),
(961, 132, 4, 'Làm nóng lò nướng ở 190C/quạt 170C/gas 5. Cho gà vào khay nướng và nướng trong 1 giờ 20 phút. Nghỉ ngơi dưới giấy bạc trong 20 phút. Trong khi gà đang nghỉ ngơi, trộn đều các nguyên liệu và nêm gia vị. Phục vụ gà với khoai tây chiên, khoai tây chiên và gia vị.', NULL, '2026-05-15 14:34:10', '2026-05-15 14:34:10'),
(963, 133, 1, 'Cho nghệ tây vào tô nhỏ cùng 75ml nước vừa đun sôi. Khuấy và đặt sang một bên. Đun nóng 2 muỗng canh dầu trong một đĩa thịt hầm rộng, nông. Nấu tỏi cho đến khi có màu vàng nhạt, sau đó cho hạnh nhân đã chần và bánh mì vào, tiếp tục chiên cho đến khi mọi thứ đều vàng. Cho vào máy xay thực phẩm với một ít muối, hạt tiêu và rau mùi tây rồi xay nhuyễn với nhau.', NULL, '2026-05-15 14:34:13', '2026-05-16 12:35:33'),
(965, 133, 2, 'Đun nóng thêm 2 muỗng canh dầu trong chảo rồi cho gà vào chiên vàng đều, nêm gia vị khi nấu. Cho vào tô và đặt sang một bên.', NULL, '2026-05-15 14:34:13', '2026-05-16 12:35:33'),
(967, 133, 3, 'Lấy tất cả trừ khoảng 2 muỗng canh mỡ gà ra khỏi chảo và nấu hành tây, cà rốt và cần tây cho đến khi vàng. Thêm rượu sherry vào, khuấy đều để đánh bật các mảng màu nâu dính vào chảo. Đổ nước kho và nghệ tây (cùng với nước vào), đun sôi, sau đó vặn lửa nhỏ để đun nhỏ lửa. Thêm gia vị và lá nguyệt quế, rồi cho gà trở lại chảo cùng với nước trái cây. Nêm và nấu gà nhẹ nhàng trong khoảng 40 phút với nắp đậy.', NULL, '2026-05-15 14:34:13', '2026-05-16 12:35:33'),
(969, 133, 4, 'Chuyển gà vào tô một lần nữa, để nước sốt trong chảo và bọc lại bằng giấy bạc để giữ ấm. Trứng loại bỏ lòng đỏ và cắt nhỏ lòng trắng. Nghiền lòng đỏ trứng trong một cái bát nhỏ và trộn dần với một vài muỗng canh nước sốt. Đun sôi phần nước sốt còn lại cho bớt bớt một chút (bạn muốn nước sốt chỉ phủ đều lên gà), sau đó vặn lửa nhỏ. Loại bỏ vịnh và thanh quế. Thêm lòng đỏ trứng và nấu trong vài phút cho đến khi hỗn hợp đặc lại. Khuấy hỗn hợp hạnh nhân mà bạn đã làm trước đó (điều này cũng sẽ làm nước sốt đặc lại). Cho gà trở lại chảo và đun nóng trong khoảng 3 phút, rưới nước sốt lên trên. Nêm nếm vừa miệng.', NULL, '2026-05-15 14:34:13', '2026-05-16 12:35:33'),
(971, 133, 5, 'Rắc thêm rau mùi tây, các miếng hạnh nhân và lòng trắng trứng cắt nhỏ (nếu bạn định sử dụng chúng). Bạn có thể phục vụ món này ngay từ món ăn với một ít cơm nếu thích.', NULL, '2026-05-15 14:34:13', '2026-05-16 12:35:33'),
(972, 134, 1, 'Gratin khoai tây 15 phút với thịt gà và rau xanh thịt xông khói: món gratin luôn có vẻ tốn nhiều công sức và ngon miệng hơn so với món luộc hoặc nướng thông thường, nhưng không nhất thiết phải mất 45 phút, thật tuyệt khi thay đổi và bạn có thể kiểm soát hàm lượng calo bằng cách ăn đầy đủ chất béo đến kem ít béo', NULL, '2026-05-15 14:34:16', '2026-05-15 14:34:16'),
(973, 134, 2, '(Rõ ràng là nó luôn có vị béo tốt hơn!) Phần 4: dùng 800g khoai tây, thái lát mỏng và đun sôi trong chảo khoảng 5-8 phút cho đến khi cứng, không mềm', NULL, '2026-05-15 14:34:16', '2026-05-15 14:34:16'),
(974, 134, 3, 'Cắt nhuyễn 3 củ hành tây rồi cho vào khay nướng cùng với 2 thìa dầu ô liu và 100ml nước luộc gà', NULL, '2026-05-15 14:34:16', '2026-05-15 14:34:16'),
(975, 134, 4, 'Nấu cho đến khi hành tây mềm thì vớt khoai tây ra và đổ lên hành tây', NULL, '2026-05-15 14:34:16', '2026-05-15 14:34:16'),
(976, 134, 5, 'Nêm và dùng thìa phủ lên kem hoặc creme fraiche cho đến khi phủ đều nhưng không nổi', NULL, '2026-05-15 14:34:16', '2026-05-15 14:34:16'),
(977, 134, 6, 'Bào Parmesan lên trên rồi nướng dưới vỉ nướng cho đến khi chín vàng đẹp mắt', NULL, '2026-05-15 14:34:16', '2026-05-15 14:34:16'),
(978, 134, 7, 'ăn kèm với thịt gà và thịt xông khói, đậu Hà Lan và rau bina', NULL, '2026-05-15 14:34:16', '2026-05-15 14:34:16'),
(979, 135, 1, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C).', NULL, '2026-05-15 14:34:19', '2026-05-15 14:34:19'),
(980, 135, 2, 'Trộn nước, hành tây, dầu ô liu, giấm balsamic, mù tạt Dijon, tỏi, tiêu đen, ớt cayenne và muối với nhau trong đĩa rang. Thêm thịt gà; xoay cho đến khi được phủ đều hỗn hợp.', NULL, '2026-05-15 14:34:19', '2026-05-15 14:34:19'),
(981, 135, 3, 'Nướng trong lò làm nóng trước cho đến khi nhiệt kế đọc tức thời được đưa vào phần dày nhất của đùi, gần xương, đọc 165 độ F (74 độ C), khoảng 1 giờ 30 phút.', NULL, '2026-05-15 14:34:19', '2026-05-15 14:34:19'),
(982, 136, 1, 'Làm nóng lò ở nhiệt độ 400 độ F (200 độ C). Bôi mỡ vào chảo nướng 10x14x2 inch.', NULL, '2026-05-15 14:34:22', '2026-05-15 14:34:22'),
(983, 136, 2, 'Đun nóng bơ thực vật trong chảo trên lửa vừa; khuấy hành tây. Nấu và khuấy cho đến khi hành tây mềm và chuyển sang màu trong, khoảng 5 phút. Giảm nhiệt xuống thấp và tiếp tục nấu và khuấy cho đến khi hành tây rất mềm và có màu nâu sẫm, khoảng 40 phút nữa.', NULL, '2026-05-15 14:34:22', '2026-05-15 14:34:22'),
(984, 136, 3, 'Đun sôi nước luộc gà trong nồi lớn; cho ức gà vào, giảm nhiệt và đun nhỏ lửa cho đến khi gà không còn màu hồng ở giữa, khoảng 20 phút. Loại bỏ khỏi nhiệt. Dùng thìa có rãnh vớt ức gà ra đĩa; nước dùng dự trữ.', NULL, '2026-05-15 14:34:22', '2026-05-15 14:34:22'),
(985, 136, 4, 'Ép khoai tây bằng máy ép trái cây điện; cho thịt khoai tây khô vào tô và đổ nước đi. Khuấy muối và hạt tiêu vào khoai tây; khuấy đủ nước dùng dành riêng để tạo thành hỗn hợp có độ đặc của bột yến mạch. Đặt nước dùng còn lại sang một bên.', NULL, '2026-05-15 14:34:22', '2026-05-15 14:34:22'),
(986, 136, 5, 'Trải đều một nửa hỗn hợp khoai tây vào chảo đã chuẩn bị. Xếp đều ức gà đã nấu chín lên trên khoai tây; rải đều hành tây caramen lên thịt gà. Rải hỗn hợp khoai tây còn lại lên trên hành và thịt gà.', NULL, '2026-05-15 14:34:22', '2026-05-15 14:34:22'),
(987, 136, 6, 'Nướng trong lò làm nóng trước cho đến khi có màu vàng nâu, khoảng 1 giờ. Đun nóng lại nước luộc gà; đổ từng phần riêng lẻ theo ý muốn.', NULL, '2026-05-15 14:34:22', '2026-05-15 14:34:22'),
(989, 137, 1, 'Bật lửa nướng hoặc làm nóng chảo nướng ở nhiệt độ cao. Cho gà, bột cà ri và nước cốt dừa vào tô, sau đó trộn đều cho đến khi gà được phủ đều. Xiên rau và thịt gà vào xiên. Nướng xiên trên vỉ nướng hoặc vỉ nướng trong 5-8 phút, thỉnh thoảng lật thịt cho đến khi thịt gà chín đều và cháy thành than. Ăn kèm cơm, salad và nửa quả chanh để vắt.', NULL, '2026-05-15 14:34:24', '2026-05-16 12:35:33'),
(991, 138, 1, 'Làm nóng lò nướng ở mức quạt/khí 200C/180C 6. Cho thịt gà, thì là, ớt bột, 1 muỗng canh dầu ô liu và gia vị vào hộp rang. Nấu trong 40 phút cho đến khi gà giòn và chín đều.', NULL, '2026-05-15 14:34:27', '2026-05-16 12:35:33'),
(993, 138, 2, 'Trong khi đó, xé 1 chiếc bánh mì pitta và cho vào một cái bát nhỏ. Đổ một vài muỗng canh nước luộc gà và để ngâm. Chiên khô quả óc chó trong chảo khoảng 3 phút cho đến khi vàng và nướng. Đặt sang một bên. Đun nóng lượng dầu còn lại trong chảo rồi cho hành, tỏi vào xào chín mềm. Cho bánh mì pitta đã làm mềm, hỗn hợp hành tây và hầu hết các loại hạt vào máy xay. Đổ phần nước luộc gà còn lại lên và trộn đều cho đến khi tạo thành hỗn hợp sệt. Cho hỗn hợp trở lại chảo. Thêm kem và nước cốt chanh, nêm gia vị và giữ ấm.', NULL, '2026-05-15 14:34:27', '2026-05-16 12:35:33'),
(995, 138, 3, 'Khi gà chín, xếp ra đĩa. Khuấy rau mùi qua nước sốt và cho thìa vào tô. Cắt nhỏ những quả óc chó còn lại và rắc lên gà. Nướng bánh pittas, cắt thành miếng vừa ăn và dùng kèm', NULL, '2026-05-15 14:34:27', '2026-05-16 12:35:33'),
(996, 139, 1, 'Cho gà vào lò nướng kiểu Hà Lan lớn hoặc nồi kho', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(997, 139, 2, 'Phủ nước', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(998, 139, 3, 'Đun sôi và đun nhỏ lửa trong 2 đến 2 tiếng rưỡi, loại bỏ tạp chất bên trên để đảm bảo nước dùng trong', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(999, 139, 4, 'Nếu nồi của bạn đủ lớn, hãy thêm rau và gia vị vào giờ nấu cuối cùng.', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(1000, 139, 5, 'Lò nướng kiểu Hà Lan của tôi không đủ lớn để đựng mọi thứ, chỉ có thịt gà và các loại xương khác lấp đầy nồi nên tôi nấu chín thịt/xương rồi lấy ra và nấu riêng rau và gia vị.', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(1001, 139, 6, 'Lọc mọi thứ ra khỏi nước dùng', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(1002, 139, 7, 'Rút xương gà, xé thịt thành khối lớn', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(1003, 139, 8, 'Cắt lát cà rốt', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(1004, 139, 9, 'Cho gà và cà rốt vào nước dùng', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(1005, 139, 10, 'Nấu mì theo hướng dẫn trên bao bì nếu bạn đang sử dụng chúng', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(1006, 139, 11, 'Cho mì vào tô rồi rưới nước súp nóng lên trên', NULL, '2026-05-15 14:34:30', '2026-05-15 14:34:30'),
(1007, 140, 1, 'Kết hợp các thành phần xốt trong một túi ziplock lớn (hoặc bát).', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1008, 140, 2, 'Thêm gà vào và dùng tay để đảm bảo từng miếng đều được phủ đều. Nếu dùng túi ziplock, mình thấy đóng túi lại tiện rồi massage túi cho phân tán đều khắp từng miếng gà.', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1009, 140, 3, 'Ướp qua đêm hoặc tối đa 24 giờ.', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1010, 140, 4, 'Cho các nguyên liệu nước sốt sữa chua vào tô và trộn đều. Đậy nắp và cho vào tủ lạnh cho đến khi cần thiết (có thể để trong tủ lạnh trong 3 ngày).', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1011, 140, 5, 'Nướng nhiệt/BBQ (hoặc chảo nặng lớn trên bếp) ở mức cao vừa phải. Bạn không cần phải bôi dầu vì nước xốt có dầu và phi lê đùi cũng có mỡ. Nhưng nếu bạn lo lắng thì hãy tra dầu vào đĩa hâm/vỉ nướng của bạn. (Xem ghi chú khi làm bánh)', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1012, 140, 6, 'Đặt gà lên vỉ nướng và nướng mặt đầu tiên trong 4 đến 5 phút cho đến khi chín vàng, sau đó lật mặt còn lại trong 3 đến 4 phút (mặt thứ 2 mất ít thời gian hơn).', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1013, 140, 7, 'Lấy gà ra khỏi vỉ nướng và bọc lỏng bằng giấy bạc. Đặt sang một bên để nghỉ ngơi trong 5 phút.', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1014, 140, 8, 'ĐỂ PHỤC VỤ', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1015, 140, 9, 'Cắt lát thịt gà và xếp lên đĩa cùng với bánh mì dẹt, Salad và Nước sốt sữa chua.', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1016, 140, 10, 'Để làm lớp bọc, hãy lấy một miếng bánh mì dẹt và phết sốt sữa chua. Phủ một ít rau diếp, cà chua và thịt gà Shawarma lên trên. Cuộn lại và thưởng thức!', NULL, '2026-05-15 14:34:35', '2026-05-15 14:34:35'),
(1018, 141, 1, 'Bạn cần 15 xiên: nếu bằng gỗ thì ngâm trong nước 10 phút. Cắt gà thành miếng 3 cm và cho vào tô. Thêm 1 muỗng canh dầu ô liu, gia vị, tỏi và giấm, trộn đều và nêm gia vị. Bạn có thể làm điều này trước một ngày và để trong tủ lạnh.', NULL, '2026-05-15 14:34:38', '2026-05-16 12:35:33'),
(1020, 141, 2, 'Xiên 2-3 miếng vào mỗi xiên. Đổ lượng dầu còn lại vào chảo rán hoặc chà lên chảo nướng. Bắt chảo nóng và nướng gà trong 3-4 phút mỗi mặt - bạn có thể phải làm theo từng đợt, giữ ấm xiên đã nấu chín trong lò nướng nhỏ. Ăn kèm với aïoli khói nếu bạn thích.', NULL, '2026-05-15 14:34:38', '2026-05-16 12:35:33'),
(1022, 142, 1, 'Ngâm đậu ít nhất 4 giờ hoặc qua đêm trong tô lớn với nhiều nước ngập. Ngày hôm sau, rửa sạch và để ráo nước, sau đó cho vào chảo lớn có nền dày cùng hành tây, ớt bột, bó rau thơm và thịt gà. Đổ đủ nước hoặc nước kho vào, đun sôi rồi giảm lửa, đậy nắp và đun nhỏ lửa trong 45 phút.', NULL, '2026-05-15 14:34:41', '2026-05-16 12:35:33'),
(1024, 142, 2, 'Lấy thịt gà ra đĩa, sau đó cho khoai tây và chorizo vào chảo. Tiếp tục nấu trong 30 phút cho đến khi đậu và khoai tây mềm.', NULL, '2026-05-15 14:34:41', '2026-05-16 12:35:33'),
(1026, 142, 3, 'Loại bỏ da và xương gà rồi xé thành từng miếng lớn. Cho gà vào chảo cùng với rau bina và đun nhỏ lửa trong 5 phút.', NULL, '2026-05-15 14:34:41', '2026-05-16 12:35:33'),
(1028, 143, 1, 'Làm nóng lò ở mức quạt/gas 190C/170C 5. Cho tất cả nguyên liệu vào một đĩa chịu nhiệt rộng, rộng. Trộn tất cả mọi thứ lại với nhau bằng tay và nêm gia vị.', NULL, '2026-05-15 14:34:44', '2026-05-16 12:35:33'),
(1030, 143, 2, 'Nướng trong 45 phút, đảo hành sau 20 phút cho đến khi gà vàng và hành mềm. Ăn kèm cơm.', NULL, '2026-05-15 14:34:44', '2026-05-16 12:35:33'),
(1032, 144, 1, 'Làm nóng lò ở 200C/quạt 180C/gas 6. Luộc khoai tây trong 15-20 phút cho đến khi mềm. Để ráo nước, cho trở lại chảo, sau đó nghiền với một ít gia vị và 2 thìa cà phê ớt bột.', NULL, '2026-05-15 14:34:47', '2026-05-16 12:35:33'),
(1034, 144, 2, 'Trong khi đó, đun nóng dầu trong chảo lớn, sau đó xào hành và tỏi trong vài phút cho đến khi mềm. Khuấy phần ớt bột còn lại trong 1 phút, thêm cà chua vào, sau đó đun nhỏ lửa. Đổ thịt vào một đĩa chịu nhiệt lớn, sau đó cho thịt gà, ớt, ô liu và một ít gia vị vào trộn đều.', NULL, '2026-05-15 14:34:47', '2026-05-16 12:35:33'),
(1036, 144, 3, 'Đổ hỗn hợp nghiền lên trên, sau đó nướng trong 15 phút cho đến khi hỗn hợp có màu vàng ở trên và nước sốt sủi bọt.', NULL, '2026-05-15 14:34:47', '2026-05-16 12:35:33'),
(1038, 145, 1, 'Làm nước xốt. Dùng chày và cối đập tỏi với một ít muối. Thêm vỏ chanh và nước ép, hỗn hợp gia vị, ớt, dầu và một ít hạt tiêu đen xay. Trộn thành bột nhão. Điều này có thể được thực hiện trong một máy chế biến thực phẩm mini.', NULL, '2026-05-15 14:34:49', '2026-05-16 12:35:33'),
(1040, 145, 2, 'Cho gà vào nước xốt và đặt sang một bên trong khi bạn đốt thịt nướng. Khi thịt nướng đã nóng, xếp các bó rau thơm lên vỉ và đặt thịt gà, mặt da úp lên trên. Đậy nắp nếu thịt nướng của bạn có nắp và nấu gà trên các loại thảo mộc đang cháy âm ỉ trong khoảng 10 phút cho đến khi thịt bắt đầu có màu. Lật gà và tiếp tục nấu thêm 20-30 phút nữa, đảo khi cần thiết, cho đến khi các loại thảo mộc bị cháy hơi cháy và chín đến tận xương.', NULL, '2026-05-15 14:34:49', '2026-05-16 12:35:33'),
(1042, 146, 1, 'Thực hiện 3 dấu gạch chéo trên mỗi dùi trống. Trộn đậu nành, mật ong, dầu, cà chua xay nhuyễn và mù tạt. Đổ hỗn hợp này lên gà và phủ kỹ. Để ướp trong 30 phút ở nhiệt độ phòng hoặc qua đêm trong tủ lạnh. Làm nóng lò ở 200C/quạt 180C/gas 6.', NULL, '2026-05-15 14:34:52', '2026-05-16 12:35:33'),
(1044, 146, 2, 'Cho gà vào khay nướng nông và nấu trong 35 phút, thỉnh thoảng lật gà cho đến khi gà mềm và lấp lánh với nước xốt.', NULL, '2026-05-15 14:34:52', '2026-05-16 12:35:33'),
(1045, 147, 1, 'Đun nóng chảo hoặc chảo lớn cho đến khi thật nóng, sau đó thêm 1 muỗng canh dầu. Khi trời rất nóng, cho gà vào xào trên lửa cao trong 8-10 phút cho đến khi chín vàng đều. Dùng thìa có rãnh, lấy gà ra khỏi chảo và đặt sang một bên.', NULL, '2026-05-15 14:34:54', '2026-05-15 14:34:54'),
(1047, 147, 2, 'Làm nóng chảo và thêm lượng dầu còn lại. Cho tỏi và hẹ tây vào xào trong 3 phút cho đến khi có màu vàng nâu.', NULL, '2026-05-15 14:34:54', '2026-05-16 12:35:33'),
(1049, 147, 3, 'Cho gà vào chảo rồi thêm ớt, nước mắm, nước tương đen và đường. Xào trên lửa cao thêm 8-10 phút nữa hoặc cho đến khi gà chín. Khuấy lá húng quế và dùng ngay.', NULL, '2026-05-15 14:34:54', '2026-05-16 12:35:33'),
(1050, 148, 1, 'Phủ gà với lòng trắng trứng:', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1051, 148, 2, 'Trong một cái bát, trộn thịt gà với lòng trắng trứng, 1/2 thìa cà phê muối kosher và bột ngô. Đảo đều để gà ngấm đều. Để yên trong 15 phút ở nhiệt độ phòng hoặc để qua đêm trong tủ lạnh.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1052, 148, 3, 'Làm nước sốt chua ngọt:', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1053, 148, 4, 'Đánh đều nước ép dứa, giấm, sốt cà chua, 1/2 muỗng cà phê muối kosher và đường nâu.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1054, 148, 5, 'Xào gà ở lửa lớn:', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1055, 148, 6, 'Đun nóng chảo rán lớn hoặc chảo trên lửa cao cho đến khi một hạt nước ngay lập tức sủi bọt và bay hơi. Đổ 1 thìa dầu ăn vào và khuấy đều. Điều quan trọng là chảo rất nóng.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1056, 148, 7, 'Thêm thịt gà và trải các miếng thành một lớp. Để gà chiên nguyên trong 1 phút, cho đến khi phần đáy có màu nâu.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1057, 148, 8, 'Lật và chiên mặt còn lại trong 1 phút. Con gà vẫn còn hơi hồng ở giữa. Gắp gà ra đĩa sạch, để lại càng nhiều dầu trong chảo càng tốt.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1058, 148, 9, 'Xào ớt chuông và gừng:', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1059, 148, 10, 'Giảm lửa vừa và thêm 1 muỗng cà phê dầu ăn còn lại. Để dầu nóng lên trước khi cho ớt chuông và gừng vào. Chiên trong 1 phút.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1060, 148, 11, 'Thêm dứa, nước sốt và sau đó là thịt gà:', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1061, 148, 12, 'Thêm miếng dứa và nước sốt chua ngọt. Tăng nhiệt lên cao. Khi nước sốt sôi thì cho các miếng thịt gà vào lại.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1062, 148, 13, 'Để nhỏ lửa trong 1 đến 2 phút, cho đến khi gà chín. Thời gian phụ thuộc vào độ dày bạn cắt thịt gà. Cách tốt nhất để biết gà đã chín hay chưa là lấy một miếng ra và cắt thành từng miếng. Nếu nó có màu hồng, hãy nấu thêm một phút nữa.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1063, 148, 14, 'Điều chỉnh gia vị và thưởng thức:', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1064, 148, 15, 'Nếm thử nước sốt và thêm đường nâu hoặc giấm cho phù hợp với khẩu vị của bạn nếu muốn.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1065, 148, 16, 'Ăn nóng với cơm trắng hoặc gạo lứt.', NULL, '2026-05-15 14:34:58', '2026-05-15 14:34:58'),
(1066, 149, 1, 'Kết hợp hành tây, cần tây, ngò và rau mùi tây trong một nồi lớn. Khuấy nghệ, thì là, ớt bột, gừng, ớt cayenne, muối và tiêu. Đặt đùi gà lên trên. Rưới dầu ô liu lên thịt gà. Đậy nắp và đun nhỏ lửa cho đến khi gà mềm, khoảng 40 phút.', NULL, '2026-05-15 14:35:01', '2026-05-15 14:35:01'),
(1067, 149, 2, 'Đặt nho khô vào một cái bát nhỏ và đổ nước nóng vào; để ngâm trong 10 phút. Làm khô hạn.', NULL, '2026-05-15 14:35:01', '2026-05-15 14:35:01'),
(1068, 149, 3, 'Làm nóng lò ở nhiệt độ 400 độ F (200 độ C).', NULL, '2026-05-15 14:35:01', '2026-05-15 14:35:01'),
(1069, 149, 4, 'Chuyển hỗn hợp gà vào đĩa tagine hoặc món thịt hầm an toàn với lò nướng. Thêm khoai lang và cà rốt. Đậy nắp hoặc giấy nhôm.', NULL, '2026-05-15 14:35:01', '2026-05-15 14:35:01'),
(1070, 149, 5, 'Nướng trong lò làm nóng trước cho đến khi khoai lang mềm, khoảng 40 phút. Thêm nho khô và mận khô. Tiếp tục nướng, đậy nắp cho đến khi nho khô và mận chín đều, khoảng 10 phút.', NULL, '2026-05-15 14:35:01', '2026-05-15 14:35:01'),
(1071, 150, 1, 'Trộn nước cốt chanh với ớt bột và hành đỏ trong một đĩa nông lớn. Chém mỗi đùi gà ba lần, sau đó cho vào nước cốt và để trong 10 phút.', NULL, '2026-05-15 14:35:02', '2026-05-15 14:35:02');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(1072, 150, 2, 'Trộn tất cả nguyên liệu làm nước xốt với nhau và rưới lên gà. Trộn đều mọi thứ, sau đó đậy nắp và để lạnh ít nhất 1 giờ. Điều này có thể được thực hiện trước một ngày.', NULL, '2026-05-15 14:35:02', '2026-05-15 14:35:02'),
(1073, 150, 3, 'Làm nóng vỉ nướng. Nhấc miếng gà lên giá trên khay nướng. Phết một ít dầu lên và nướng trong 8 phút mỗi mặt hoặc cho đến khi cháy thành than nhẹ và chín hoàn toàn.', NULL, '2026-05-15 14:35:02', '2026-05-15 14:35:02'),
(1074, 151, 1, 'Làm nóng lò nướng ở nhiệt độ 350° F. Xịt dung dịch chống dính lên chảo nướng 9x13 inch.', NULL, '2026-05-15 14:35:05', '2026-05-15 14:35:05'),
(1075, 151, 2, 'Cho nước tương, ½ cốc nước, đường nâu, gừng và tỏi vào nồi nhỏ rồi đậy nắp. Đun sôi trên lửa vừa. Mở nắp và nấu trong một phút sau khi sôi.', NULL, '2026-05-15 14:35:05', '2026-05-15 14:35:05'),
(1076, 151, 3, 'Trong khi đó, khuấy đều tinh bột ngô và 2 thìa nước trong một đĩa riêng cho đến khi mịn. Sau khi nước sốt sôi, cho hỗn hợp vào nồi và khuấy đều. Nấu cho đến khi nước sốt bắt đầu đặc lại thì tắt bếp.', NULL, '2026-05-15 14:35:05', '2026-05-15 14:35:05'),
(1077, 151, 4, 'Đặt ức gà vào chảo đã chuẩn bị. Đổ một chén nước sốt lên trên thịt gà. Đặt gà vào lò nướng và nướng trong 35 phút hoặc cho đến khi chín. Lấy gà ra khỏi lò và xé thịt gà bằng hai chiếc nĩa.', NULL, '2026-05-15 14:35:05', '2026-05-15 14:35:05'),
(1078, 151, 5, '*Trong khi đó, hấp hoặc nấu rau theo hướng dẫn trên bao bì.', NULL, '2026-05-15 14:35:05', '2026-05-15 14:35:05'),
(1079, 151, 6, 'Cho rau và cơm đã nấu chín vào món thịt hầm cùng với thịt gà. Thêm phần lớn nước sốt còn lại, chừa lại một ít để rưới lên trên khi dùng. Nhẹ nhàng trộn tất cả mọi thứ vào đĩa thịt hầm cho đến khi hòa quyện. Quay trở lại lò nướng và nấu 15 phút. Lấy ra khỏi lò và để yên 5 phút trước khi dùng. Rắc từng khẩu phần với nước sốt còn lại. Thưởng thức!', NULL, '2026-05-15 14:35:05', '2026-05-15 14:35:05'),
(1081, 152, 1, 'Cho thịt gà, tỏi, gừng, hành tây, rau mùi và ớt vào máy xay thực phẩm và nêm đều. Đảo nhanh cho đến khi thịt gà được nghiền mịn và mọi thứ được trộn đều. Dùng tay tạo hình sáu chiếc bánh nhỏ.', NULL, '2026-05-15 14:35:10', '2026-05-16 12:35:33'),
(1083, 152, 2, 'Đun nóng dầu trong chảo, sau đó chiên bánh trên lửa vừa trong khoảng 6-8 phút, quay một lần. Ăn nóng với tương ớt ngọt, chanh, rau mùi, hành lá cắt nhỏ và ớt đỏ.', NULL, '2026-05-15 14:35:10', '2026-05-16 12:35:33'),
(1085, 153, 1, 'Làm nóng lò nướng ở mức quạt/khí 200C/180C 6 và lót giấy bạc vào khay nướng. Trộn nước sốt ớt với vỏ cam và nước ép, tỏi, bột cà ri và ¼ muỗng cà phê muối. Thêm thịt gà và áo thật kỹ.', NULL, '2026-05-15 14:35:12', '2026-05-16 12:35:33'),
(1087, 153, 2, 'Xếp các dùi trống lên giấy bạc, cách đều nhau. Phủ gà với phần nước xốt còn lại trong tô, sau đó nướng trong 35-40 phút cho đến khi mềm. Bọc trong giấy bạc hoặc đóng gói vào hộp đựng thực phẩm.', NULL, '2026-05-15 14:35:12', '2026-05-16 12:35:33'),
(1089, 154, 1, 'Đun nóng dầu trong chảo lớn nhất, cho hành tây vào xào trong 3 phút cho mềm. Thêm thịt gà và tỏi vào nấu cho đến khi gà đổi màu.', NULL, '2026-05-15 14:35:17', '2026-05-16 12:35:33'),
(1091, 154, 2, 'Thêm bột cà ri, nước cốt dừa, nước kho, lá chanh và nước mắm vào rồi đun nhỏ lửa trong 12 phút. Thêm hành tây xắt nhỏ, đậu xanh và măng vào nấu trong 4-6 phút cho đến khi đậu mềm.', NULL, '2026-05-15 14:35:17', '2026-05-16 12:35:33'),
(1093, 154, 3, 'Trong khi đó, cho nước cốt chanh và húng quế vào một cái bình hẹp và xay nhuyễn bằng máy xay cầm tay để tạo thành hỗn hợp sệt màu xanh mịn. Đổ súp với hành lá thái lát vào và đun nóng. Ăn kèm với chanh cho bữa trưa hoặc bữa tối nhẹ hoặc như một món khai vị chuẩn bị trước.', NULL, '2026-05-15 14:35:17', '2026-05-16 12:35:33'),
(1099, 156, 1, 'Đổ nước luộc gà và nước cốt dừa vào nồi lớn đặt trên lửa vừa. Cho riềng, sả và lá chanh vào rồi đun nhỏ lửa khoảng 6-8 phút. Giữ lửa nhỏ, thêm thịt gà vào. Nấu trong 8-10 phút cho đến khi mềm và chín.', NULL, '2026-05-15 14:35:24', '2026-05-16 12:35:33'),
(1101, 156, 2, 'Khuấy nấm và ớt rồi đun nhỏ lửa thêm 3-5 phút nữa cho đến khi mọi thứ chín đều. Rắc đường và 3 muỗng canh nước mắm và nước cốt chanh vào. Hương vị và thêm phần còn lại nếu cần.', NULL, '2026-05-15 14:35:24', '2026-05-16 12:35:33'),
(1103, 156, 3, 'Dùng thìa có rãnh loại bỏ riềng, sả và lá chanh trước khi dùng. Múc ra bát và dùng kèm với lá ngò rắc lên trên và cơm hấp đặt bên cạnh. Sẽ giữ lạnh lên đến ba ngày. Để nguội trước.', NULL, '2026-05-15 14:35:24', '2026-05-16 12:35:33'),
(1104, 157, 1, 'Cắt gà thành từng miếng vừa ăn. Gọt vỏ và cắt hành tây, băm tỏi.', NULL, '2026-05-15 14:35:26', '2026-05-15 14:35:26'),
(1105, 157, 2, 'Tập hợp các nguyên liệu còn lại và bạn đã sẵn sàng bắt đầu nấu ăn.', NULL, '2026-05-15 14:35:26', '2026-05-15 14:35:26'),
(1106, 157, 3, 'Làm món ăn', NULL, '2026-05-15 14:35:26', '2026-05-15 14:35:26'),
(1107, 157, 4, 'Làm nóng chảo rán trên lửa vừa. Thêm dầu vào và khi nóng, xào hành tây cho đến khi trong suốt. Lấy ra khỏi chảo và chuyển vào máy xay hoặc máy chế biến thực phẩm.', NULL, '2026-05-15 14:35:26', '2026-05-15 14:35:26'),
(1108, 157, 5, 'Thêm cà chua, tỏi, nghệ, thì là, đường, bột gừng, nước cốt dừa, nước và trộn đều.', NULL, '2026-05-15 14:35:26', '2026-05-15 14:35:26'),
(1109, 157, 6, 'Trong cùng một chảo bạn nấu hành tây, thêm thịt gà và chiên vàng tất cả các mặt. Quá trình này sẽ mất khoảng 3 phút.', NULL, '2026-05-15 14:35:26', '2026-05-15 14:35:26'),
(1110, 157, 7, 'Cho nguyên liệu máy xay và lá nguyệt quế vào chảo, đun nhỏ lửa và nấu cho đến khi thịt gà có màu trắng bên trong và nước sánh như kem. (15 đến 20 phút)', NULL, '2026-05-15 14:35:26', '2026-05-15 14:35:26'),
(1111, 157, 8, 'Loại bỏ lá nguyệt quế và dùng với cơm trắng.', NULL, '2026-05-15 14:35:26', '2026-05-15 14:35:26'),
(1113, 158, 1, 'Để làm nước sốt, trộn tất cả nguyên liệu lại với nhau trong một tô lớn. Luộc mì theo hướng dẫn trên bao bì, sau đó để ráo nước và cho vào tô cùng với nước sốt.', NULL, '2026-05-15 14:35:28', '2026-05-16 12:35:33'),
(1115, 158, 2, 'Gọt vỏ cà rốt thành dải dài bằng dụng cụ gọt rau. Làm tương tự với dưa chuột cho đến khi lấy được hạt (bỏ hạt). Thêm cà rốt và dưa chuột vào hỗn hợp mì cùng với thịt gà xé nhỏ, củ cải, hành tím và bạc hà. Trộn đều để phủ đều nước sốt, rắc lên đậu phộng và thưởng thức.', NULL, '2026-05-15 14:35:28', '2026-05-16 12:35:33'),
(1117, 159, 1, 'Gọt vỏ và bỏ phần lớn tôm (người bán cá có thể làm việc này cho bạn), giữ lại một ít nguyên con để trang trí, nếu bạn thích. Đun nóng dầu ô liu trong chảo rán lớn hoặc nồi chống cháy nông trên lửa vừa và nhỏ và xào hành tây trong 5 phút cho đến khi mềm. Thêm lá nguyệt quế, nghệ tây, gạo và cà chua xay nhuyễn vào nấu thêm 1-2 phút nữa, khuấy đều.', NULL, '2026-05-15 14:35:33', '2026-05-16 12:35:33'),
(1119, 159, 2, 'Đổ rượu và bong bóng vào trong 1-2 phút, sau đó đổ nước luộc hải sản và 150ml nước vào. Nấu trong 5 phút, sau đó thêm mực, nêm đều và khuấy đều. Đun sôi, sau đó đậy nắp và giảm nhiệt cho sôi nhẹ. Nấu thêm 12 phút nữa, thêm một chút nước nếu hỗn hợp bắt đầu khô.', NULL, '2026-05-15 14:35:33', '2026-05-16 12:35:33'),
(1121, 159, 3, 'Mở chảo và đảo đều tôm đã bóc vỏ, sau đó xếp tôm nguyên con lên trên hỗn hợp cơm. Đậy nắp lại và đun nhỏ lửa thêm 5-6 phút cho đến khi tôm có màu hồng và chín. Để yên trong vài phút trước khi phục vụ từ chảo.', NULL, '2026-05-15 14:35:33', '2026-05-16 12:35:33'),
(1122, 160, 1, 'Làm nóng lò ở 180C/quạt 160C/gas 4. Cắt bỏ lá thì là và đặt sang một bên. Cắt củ thì là làm đôi, sau đó cắt mỗi nửa thành 3 miếng. Luộc trong nước muối sôi khoảng 10 phút rồi vớt ra để ráo nước. Cắt nhỏ lá thì là, sau đó trộn với rau mùi tây và vỏ chanh.', NULL, '2026-05-15 14:35:35', '2026-05-15 14:35:35'),
(1123, 160, 2, 'Trải cây thì là đã ráo nước lên một đĩa nông chịu nhiệt, sau đó cho cà chua vào. Rưới dầu ô liu lên, sau đó nướng trong 10 phút. Nhúng cá hồi vào trong rau, rắc nước cốt chanh, sau đó nướng thêm 15 phút nữa cho đến khi cá vừa chín. Rắc lên rau mùi tây và thưởng thức.', NULL, '2026-05-15 14:35:35', '2026-05-15 14:35:35'),
(1125, 161, 1, 'Luộc mì theo hướng dẫn trên bao bì, sau đó rửa sạch dưới nước lạnh và để ráo nước. Trong một cái chảo nhỏ, đun chảy bơ đậu phộng, nước cốt dừa, tương ớt ngọt và một nửa số hành lá, thêm 1-2 muỗng canh nước để hỗn hợp được sệt lại.', NULL, '2026-05-15 14:35:38', '2026-05-16 12:35:33'),
(1127, 161, 2, 'Trộn mì, dưa chuột và giá đỗ vào đĩa phục vụ. Xếp tôm lên trên, rưới nước sốt đậu phộng và rải lên số hành lá còn lại.', NULL, '2026-05-15 14:35:38', '2026-05-16 12:35:33'),
(1129, 162, 1, 'Cho tất cả các nguyên liệu làm nước sốt vào máy xay thực phẩm với một chút muối và xay nhuyễn để làm nước sốt. Cắt cá ba lần mỗi mặt, phủ một nửa nước sốt rồi để ướp trong khoảng 30 phút.', NULL, '2026-05-15 14:35:41', '2026-05-16 12:35:33'),
(1131, 162, 2, 'Làm nóng lò ở 220C/quạt 200C/gas 7. Đặt cá lên khay nướng rồi cho vào lò nướng khoảng 20 phút cho đến khi thịt săn chắc và mắt cá chuyển sang màu trắng. Ăn cá với phần nước sốt còn lại và couscous hấp hoặc cơm.', NULL, '2026-05-15 14:35:41', '2026-05-16 12:35:33'),
(1133, 162, 3, 'BIẾT CÁCH: CÁCH NẤU: Nấu cá chẽm nguyên xương, như chúng tôi đã làm ở đây, có những ưu điểm – nó sẽ giữ ẩm hơn trong khi nấu và một số người sẽ nói rằng hương vị cũng được tăng cường. Nếu bạn muốn lấy xương ra, chúng sẽ dễ dàng tìm thấy và ít có khả năng mắc vào phi lê nếu cá được nấu chín nguyên con. Phi lê có thể được chiên hoặc nướng đơn giản. Nếu bạn thích cá hồi, bạn sẽ thực sự thích hương vị của cá chẽm, vốn có nguyên liệu và phương pháp nấu tương tự – hương vị cam quýt đặc biệt ngon, cũng như tỏi và nấm dại. Đơn giản chỉ cần nướng cá với một số loại thảo mộc tươi, dầu ô liu và gia vị là ngon, và trong những tháng hè, bạn cũng có thể nướng cá. Một thứ mà bạn không thể bỏ qua là má hoặc \'ngọc trai\' của cá, chúng đơn giản là đáng yêu, ẩm ướt và thực sự ngọt ngào - rất đáng để bạn chú ý tới!', NULL, '2026-05-15 14:35:41', '2026-05-16 12:35:33'),
(1134, 163, 1, 'Nấu với gia vị cajun và nước xốt ớt cayenne làm cho món cá này trở nên siêu mọng nước và thơm ngon. Phủ lên trên một lớp nước sốt thơm ngon và dùng kèm bánh tortilla để có món chính nhanh chóng, không cầu kỳ, mang đến một mùa hè thú vị.', NULL, '2026-05-15 14:35:45', '2026-05-15 14:35:45'),
(1135, 163, 2, 'Trên một đĩa lớn, trộn gia vị cajun và ớt cayenne với một ít gia vị rồi phết đều khắp cá.', NULL, '2026-05-15 14:35:45', '2026-05-15 14:35:45'),
(1136, 163, 3, 'Đun nóng một ít dầu trong chảo, cho cá vào chiên ở lửa vừa cho đến khi chín vàng. Giảm nhiệt và tiếp tục chiên cho đến khi cá chín, khoảng 10 phút. Nấu theo mẻ nếu bạn không có đủ chỗ trong chảo.', NULL, '2026-05-15 14:35:45', '2026-05-15 14:35:45'),
(1137, 163, 4, 'Trong khi đó, chuẩn bị nước sốt bằng cách kết hợp tất cả nguyên liệu với một ít gia vị.', NULL, '2026-05-15 14:35:45', '2026-05-15 14:35:45'),
(1138, 163, 5, 'Làm mềm bánh ngô bằng cách hâm nóng trong lò vi sóng trong 5-10 giây. Xếp cao bơ, rau diếp và hành lá, thêm một thìa salsa, phủ những miếng cá lớn lên trên và rưới lên nước sốt.', NULL, '2026-05-15 14:35:45', '2026-05-15 14:35:45'),
(1140, 164, 1, 'Chiên chorizo ​​trong chảo lớn có nắp, trên lửa vừa cho đến khi nó bắt đầu giòn và tiết ra dầu. Thêm hành tây và nấu trong 5 phút cho đến khi bắt đầu mềm. Sau đó thêm tỏi và rau mùi tây thái nhỏ vào xào thêm 1 phút nữa.', NULL, '2026-05-15 14:35:48', '2026-05-16 12:35:33'),
(1142, 164, 2, 'Đổ nước kho và cà chua vào. Đun sôi, giảm nhiệt, sau đó thêm đậu và giấm sherry. Đun nhỏ lửa trong 10 phút cho đến khi chất lỏng giảm nhẹ.', NULL, '2026-05-15 14:35:48', '2026-05-16 12:35:33'),
(1144, 164, 3, 'Rải đều lên nghêu, đậy nắp và hấp trong 2-4 phút, thỉnh thoảng lắc chảo cho đến khi nghêu mở miệng. Hãy nếm thử một chút trước khi nêm gia vị vì nghêu có thể khá mặn. Sau đó rắc lên rau mùi tây cắt nhỏ. Ăn với nhiều bánh mì giòn.', NULL, '2026-05-15 14:35:48', '2026-05-16 12:35:33'),
(1145, 165, 1, 'Làm nước xốt:', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1146, 165, 2, 'Trong một chảo nhỏ, cho nước luộc thịt bò, nước tương, rượu Thiệu Hưng, dầu hào và bột tiêu trắng vào chảo trên lửa vừa. Đánh đều và đun sôi.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1147, 165, 3, 'Cho bột ngô và nước vào tô nhỏ rồi khuấy đều cho tan. Thêm vào chảo và đánh cho đến khi nước sốt đặc lại và phủ lên mặt sau của thìa, từ 2 đến 3 phút. Đậy nắp chảo và giữ ấm ở nhiệt độ thấp nhất có thể.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1148, 165, 4, 'Làm bột bánh non trứng foo:', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1149, 165, 5, 'Trong một tô vừa, trộn bột ngô và nước cho đến khi hòa tan. Thêm trứng, muối và đường. Đánh đều cho đến khi hòa quyện và không còn vón cục lòng trắng trứng.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1150, 165, 6, 'Thêm hành lá, giá đỗ và tôm. Khuấy đều cho đến khi mọi thứ được phủ đều.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1151, 165, 7, 'Chiên trứng foo non:', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1152, 165, 8, 'Cho dầu thực vật vào chảo lớn; nó sẽ cao khoảng 2 inch ở hai bên. Đun nóng dầu trên lửa vừa cao đến 350°F hoặc cho đến khi hình thành bong bóng mạnh xung quanh chiếc đũa gỗ được nhét vào.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1153, 165, 9, 'Dùng một cái muôi, nhẹ nhàng và từ từ thêm 1/4 lượng bột trứng ốp la. Trứng foo non sẽ lập tức sủi bọt và phồng lên như có phép thuật. Chiên cho đến khi có màu vàng nâu và giòn ở mỗi mặt, khoảng 2 phút mỗi mặt. Nếu có đốm nhạt thì dùng muôi phết nhẹ với dầu nóng.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1154, 165, 10, 'Trứng foo non có thể hơi khó lật. Phương pháp đơn giản nhất là đặt một dụng cụ vào mỗi tay (một con nhện, thìa có rãnh, kẹp và đũa lớn đều là những ứng cử viên phù hợp) và nhẹ nhàng dỗ món trứng tráng qua, kéo lên một bên và đẩy xuống xung quanh mặt kia.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1155, 165, 11, 'Lấy trứng tráng ra và đặt nó lên khay nướng có lót khăn giấy. Để nguội trong 5 phút. Trong khi đó, lặp lại với phần bột còn lại để làm 4 món trứng tráng. Nếu cần, hãy thêm dầu vào chảo giữa các mẻ.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1156, 165, 12, 'Phục vụ và thưởng thức:', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1157, 165, 13, 'Xếp từng quả trứng non lên trên một lớp cơm. Rưới nước sốt ấm lên trên và dùng ngay.', NULL, '2026-05-15 14:35:50', '2026-05-15 14:35:50'),
(1158, 166, 1, 'Rửa sạch cá; chà xát với chanh hoặc chanh, nêm muối và hạt tiêu hoặc sử dụng gia vị yêu thích của bạn. Tôi đã sử dụng gia vị creole. Đặt sang một bên hoặc cho vào lò nướng để giữ ấm cho đến khi nước sốt sẵn sàng.', NULL, '2026-05-15 14:35:54', '2026-05-15 14:35:54'),
(1159, 166, 2, 'Trong chảo lớn, đun nóng dầu trên lửa vừa, cho đến khi nóng, cho cá vào chiên mỗi mặt trong khoảng 5-7 phút cho đến khi chín và giòn cả hai mặt. Lấy cá ra và đặt sang một bên. Xả dầu và để lại khoảng 2-3 muỗng canh dầu', NULL, '2026-05-15 14:35:54', '2026-05-15 14:35:54'),
(1160, 166, 3, 'Thêm lá nguyệt quế, tỏi và gừng vào xào khoảng một phút để đảm bảo tỏi không bị cháy', NULL, '2026-05-15 14:35:54', '2026-05-15 14:35:54'),
(1161, 166, 4, 'Sau đó thêm hành tây, ớt chuông, húng tây, rượu Scotch, đường, tất cả gia vị - tiếp tục khuấy trong khoảng 2-3 phút. Thêm giấm, trộn muối và tiêu điều chỉnh theo sở thích. Để lửa nhỏ thêm khoảng 2 phút nữa.', NULL, '2026-05-15 14:35:54', '2026-05-15 14:35:54'),
(1162, 166, 5, 'Bỏ lá nguyệt quế, lá húng tây và dùng kèm với cá với một bên của miếng thịt bammy này. Bạn có thể làm nước sốt trước khoảng 2 ngày.', NULL, '2026-05-15 14:35:54', '2026-05-15 14:35:54'),
(1163, 167, 1, 'BƯỚC 1', NULL, '2026-05-15 14:35:57', '2026-05-15 14:35:57'),
(1164, 167, 2, 'Cho cá vào chảo có nắp đậy và đổ lượng nước vừa đủ. Đun sôi và đun nhẹ trong 10 phút ở lửa nhỏ và đậy nắp. Xả và vẩy cá.', NULL, '2026-05-15 14:35:57', '2026-05-15 14:35:57'),
(1165, 167, 3, 'BƯỚC 2', NULL, '2026-05-15 14:35:57', '2026-05-15 14:35:57'),
(1166, 167, 4, 'Cho cá, khoai tây, ớt xanh, rau mùi, thì là, tiêu đen, tỏi và gừng vào tô lớn. Nêm gia vị, thêm bột gạo vào, trộn đều và đập 1 quả trứng vào. Khuấy hỗn hợp và chia thành 15, sau đó vo thành từng khúc nhỏ. Đập những quả trứng còn lại vào tô và đánh nhẹ. Cho vụn bánh mì vào một cái bát khác. Nhúng từng fofo vào trứng đã đánh, sau đó là hỗn hợp vụn bánh mì. Thư giãn trong 20 phút.', NULL, '2026-05-15 14:35:57', '2026-05-15 14:35:57'),
(1167, 167, 5, 'BƯỚC 3', NULL, '2026-05-15 14:35:57', '2026-05-15 14:35:57'),
(1168, 167, 6, 'Đun nóng 1cm dầu trong chảo lớn trên lửa vừa. Chiên fofos theo từng mẻ trong 2 phút mỗi mặt, lật nhẹ để có màu nâu vàng đều. Xả trên giấy ăn và lặp lại với fofos còn lại.', NULL, '2026-05-15 14:35:57', '2026-05-15 14:35:57'),
(1169, 167, 7, 'BƯỚC 4', NULL, '2026-05-15 14:35:57', '2026-05-15 14:35:57'),
(1170, 167, 8, 'Đối với món salad hành tây, trộn hành tây, rau mùi và nước cốt chanh với một chút muối. Ăn kèm với fofos và tương ớt xoài.', NULL, '2026-05-15 14:35:57', '2026-05-15 14:35:57'),
(1171, 168, 1, '01. Cho khoai tây vào chảo nước muối lạnh lớn và đun sôi. Giảm nhiệt, đậy nắp, sau đó đun nhỏ lửa trong 15 phút cho đến khi mềm. Xả sạch, sau đó cho trở lại chảo ở lửa nhỏ trong 30 giây để loại bỏ lượng nước dư thừa. Nghiền với 1 muỗng canh dầu ô liu, sau đó nêm gia vị.', NULL, '2026-05-15 14:36:02', '2026-05-15 14:36:02'),
(1172, 168, 2, '02.Trong lúc đó, cho sữa vào chảo xào lớn, cho cá vào và đun sôi. Tắt bếp, đậy nắp và để yên trong 3 phút. Lấy cá ra (dành riêng sữa) và lau khô bằng giấy ăn, sau đó nhẹ nhàng cho vào đĩa chịu nhiệt, loại bỏ da và xương.', NULL, '2026-05-15 14:36:02', '2026-05-15 14:36:02'),
(1173, 168, 3, '03. Đun nóng lượng dầu còn lại trong chảo, cho bột mì vào khuấy đều và nấu trong 30 giây. Khuấy dần dần 200-250ml sữa dự trữ (bỏ phần còn lại). Nghiền hạt nhục đậu khấu, nêm gia vị, sau đó sủi bọt cho đến khi đặc lại. Khuấy kem.', NULL, '2026-05-15 14:36:02', '2026-05-15 14:36:02'),
(1174, 168, 4, '04. Làm nóng lò ở 190°C/quạt170°C/gas 5. Bào atisô và thêm vào món ăn cùng tỏi tây, tôm và rau thơm. Khuấy vỏ chanh và nước cốt vào nước sốt, sau đó rưới lên. Trộn nhẹ nhàng bằng thìa gỗ.', NULL, '2026-05-15 14:36:02', '2026-05-15 14:36:02'),
(1175, 168, 5, '05. Đổ hỗn hợp nhuyễn lên hỗn hợp cá, sau đó dùng nĩa tạo thành các đỉnh, sẽ giòn và có màu nâu khi nấu. Rắc phô mai lên, sau đó nướng trong 35-40 phút cho đến khi vàng và sủi bọt. Ăn kèm với rau xanh héo.', NULL, '2026-05-15 14:36:02', '2026-05-15 14:36:02'),
(1176, 169, 1, 'Trong nồi vừa, đun nóng dầu ô liu trên lửa vừa cao. Thêm hành vào và nấu, thỉnh thoảng khuấy cho đến khi hành bắt đầu chuyển sang màu caramen. Thêm cà rốt và nấu cho đến khi cà rốt bắt đầu mềm, khoảng 4 phút nữa.', NULL, '2026-05-15 14:36:04', '2026-05-15 14:36:04'),
(1177, 169, 2, 'Thêm nước kho, nước, khoai tây, lá nguyệt quế và hạt tiêu đen. Nêm muối và đun sôi. Giảm nhiệt, đậy nắp và nấu trong 10 phút. Thêm kê và nấu thêm 15 phút nữa cho đến khi kê và khoai tây chín.', NULL, '2026-05-15 14:36:04', '2026-05-15 14:36:04'),
(1178, 169, 3, 'Nhẹ nhàng thêm các khối cá vào. Khuấy và đun sôi súp. Cá sẽ chín rất nhanh nên đừng để cá chín quá. Chúng được thực hiện khi thịt có màu đục và dễ bong ra.', NULL, '2026-05-15 14:36:04', '2026-05-15 14:36:04'),
(1179, 169, 4, 'Trang trí súp với thì là tươi hoặc rau mùi tây cắt nhỏ trước khi dùng.', NULL, '2026-05-15 14:36:04', '2026-05-15 14:36:04'),
(1180, 170, 1, 'Xoay đầu tôm, sau đó bóc bỏ phần chân và vỏ nhưng giữ nguyên phần đuôi. Lọc bỏ từng con tôm. Chiên vỏ trong 1 muỗng canh dầu trong 5 phút cho đến khi có màu hồng đậm và vàng từng mảng. Thêm rượu vào, đun sôi khoảng 2/3 rồi đổ nước kho vào. Lọc vào bình, loại bỏ vỏ.', NULL, '2026-05-15 14:36:08', '2026-05-15 14:36:08'),
(1181, 170, 2, 'Đun nóng phần dầu còn lại trong chảo hoặc chảo sâu lòng. Thêm thì là, hành tây và tỏi vào, nêm gia vị rồi đậy nắp và nấu nhẹ trong 10 phút cho đến khi mềm. Trong khi đó, gọt vỏ khoai tây và cắt thành khối khoảng 2cm. Cho vào chảo nước lạnh, đun sôi và nấu trong 5 phút cho đến khi gần mềm. Xả trong một cái chao.', NULL, '2026-05-15 14:36:08', '2026-05-15 14:36:08'),
(1182, 170, 3, 'Gọt một dải vỏ từ quả cam. Cho vỏ, hoa hồi, nguyệt quế và ½ thìa cà phê harissa vào chảo. Chiên nhẹ nhàng, không đậy nắp trong 5-10 phút cho đến khi rau mềm, ngọt và vàng.', NULL, '2026-05-15 14:36:08', '2026-05-15 14:36:08'),
(1183, 170, 4, 'Khuấy nhuyễn cà chua, nấu trong 2 phút, sau đó thêm cà chua và kho. Đun nhỏ lửa trong 10 phút cho đến khi nước sốt đặc lại một chút. Nêm nếm vừa miệng. Nước sốt có thể được làm trước và hâm nóng lại sau đó trong ngày. Trong khi đó, hãy chà sạch trai hoặc nghêu và nhổ bỏ những sợi râu xơ xác. Bất kỳ cái gì đang mở phải được gõ mạnh lên mặt bàn - nếu chúng không đóng lại sau vài giây, hãy loại bỏ chúng.', NULL, '2026-05-15 14:36:08', '2026-05-15 14:36:08'),
(1184, 170, 5, 'Đun lại nước sốt nếu cần, sau đó khuấy nhẹ nhàng khoai tây, từng miếng cá và tôm vào hầm. Đun sôi trở lại, sau đó đậy nắp và đun nhỏ lửa trong 3 phút. Rải trai hoặc nghêu lên trên món hầm, sau đó đậy nắp và nấu thêm 2 phút hoặc cho đến khi vỏ mở rộng. Loại bỏ bất kỳ cái gì vẫn đóng. Các miếng cá sẽ bong ra dễ dàng và tôm sẽ có màu hồng. Rắc lá húng tây.', NULL, '2026-05-15 14:36:08', '2026-05-15 14:36:08'),
(1185, 170, 6, 'Để làm món cuộn nhanh, hãy khuấy phần còn lại của món harissa qua sốt mayonnaise. Dọn món hầm ra bát, phủ lên trên một thìa bột rouille sẽ tan vào nước sốt và làm đậm đà nước sốt. Chuẩn bị sẵn một ít bánh mì ngon vì bạn chắc chắn sẽ muốn lau sạch nước trái cây.', NULL, '2026-05-15 14:36:08', '2026-05-15 14:36:08'),
(1186, 171, 1, 'Cắt phi lê cá thành khối hoặc dải. Nghiền hoặc băm tỏi. Rửa sạch rau và cắt thành dải mỏng.', NULL, '2026-05-15 14:36:10', '2026-05-15 14:36:10'),
(1187, 171, 2, 'Đun nóng bơ trong nồi và thêm tỏi. Khi tỏi bắt đầu chuyển sang màu vàng, thêm bột mì vào, đánh đều.', NULL, '2026-05-15 14:36:10', '2026-05-15 14:36:10'),
(1188, 171, 3, 'Thêm nước luộc cá vào và tiếp tục đánh cho đến khi không còn vón cục.', NULL, '2026-05-15 14:36:10', '2026-05-15 14:36:10'),
(1189, 171, 4, 'Thêm rau và sữa vào rồi đun sôi. Nấu trong khoảng 10 phút.', NULL, '2026-05-15 14:36:10', '2026-05-15 14:36:10'),
(1190, 171, 5, 'Thêm crème fraîche (hoặc kem chua). Đun sôi súp trở lại và khi súp bắt đầu sủi bọt trở lại thì tắt lửa. Giữ súp trên bếp và thêm cá. Để cá nấu trong súp nóng trong 5 phút. Nếu sử dụng tôm, hãy thêm ngay trước khi dùng.', NULL, '2026-05-15 14:36:10', '2026-05-15 14:36:10'),
(1191, 171, 6, 'Rắc hẹ (hoặc thì là hoặc mùi tây) trước khi dùng.', NULL, '2026-05-15 14:36:10', '2026-05-15 14:36:10'),
(1193, 172, 1, 'Cắt mực thành từng khoanh dày khoảng ½cm. Đổ bột vào túi đông lạnh và nêm đều. Thêm nụ bạch hoa, sau đó lắc đều để trộn đều. Đổ mực vào túi, sau đó lắc lại cho đến khi tất cả các vòng đều được phủ đều. Trộn tỏi và sốt mayonnaise với nhau, sau đó cho vào tô phục vụ.', NULL, '2026-05-15 14:36:12', '2026-05-16 12:35:33'),
(1195, 172, 2, 'Đổ một ít dầu vào chảo lớn cho đến khi ngập các cạnh khoảng 7cm, nhưng chảo không đầy quá một phần ba. Đặt trên lửa vừa và để dầu nóng lên. Để kiểm tra xem dầu đã sẵn sàng hay chưa, hãy đặt một miếng bánh mì nhỏ vào chảo – nó sẽ kêu xèo xèo khi chạm vào dầu.', NULL, '2026-05-15 14:36:12', '2026-05-16 12:35:33'),
(1197, 172, 3, 'Lấy một nắm mực ra khỏi bột và rũ bỏ phần thừa. Nhẹ nhàng thả vào dầu rồi chiên khoảng 3 phút cho đến khi giòn. Lấy thìa có rãnh ra và đặt lên giấy ăn. Lặp lại với con mực còn lại. Ăn ngay với sốt mayonnaise và chanh.', NULL, '2026-05-15 14:36:12', '2026-05-16 12:35:33'),
(1199, 173, 1, 'Lột vỏ tôm, để nguyên đuôi và dùng que cocktail loại bỏ đường tiêu hóa. Hoặc, nếu bạn sử dụng chảo rán thay vì nồi đất nung, bạn có thể nấu tôm trong vỏ. Nêm với một ít muối biển.', NULL, '2026-05-15 14:36:15', '2026-05-16 12:35:33'),
(1201, 173, 2, 'Cho tỏi, dầu ô liu và ớt vào nồi đất nung hoặc chảo rán chống cháy và đun trên lửa cao. Khi tỏi bắt đầu chuyển sang màu vàng, cho tôm vào xào khoảng 1-2 phút mỗi mặt cho đến khi có màu hồng. Rắc lên rau mùi tây cắt nhỏ và một ít hạt tiêu đen tươi nứt, rồi dùng ngay. Nếu dùng nồi đất nung, bạn có thể đặt thẳng lên bàn, nhưng hãy cẩn thận vì dầu và đất nung sẽ vẫn nóng trong vài phút.', NULL, '2026-05-15 14:36:15', '2026-05-16 12:35:33'),
(1202, 174, 1, 'Đặt tôm vào nồi và thêm nước vừa đủ. Đun sôi trong 5 phút. Xả, dự trữ chất lỏng và đặt sang một bên.', NULL, '2026-05-15 14:36:18', '2026-05-15 14:36:18'),
(1203, 174, 2, 'Đun nóng 2 thìa dầu trong chảo. Thêm hành tây; nấu và khuấy cho đến khi mềm. Trộn mùi tây, rượu vang, cà chua, tỏi và dầu ô liu còn lại. Đun nhỏ lửa, thỉnh thoảng khuấy trong khoảng 30 phút hoặc cho đến khi nước sốt đặc lại.', NULL, '2026-05-15 14:36:18', '2026-05-15 14:36:18'),
(1204, 174, 3, 'Trong khi nước sốt đang sôi, tôm phải đủ nguội để có thể xử lý được. Đầu tiên, loại bỏ các chân bằng cách kẹp chúng, sau đó kéo vỏ ra, để lại đầu và đuôi.', NULL, '2026-05-15 14:36:18', '2026-05-15 14:36:18'),
(1205, 174, 4, 'Khi nước sốt đặc lại thì cho tôm vào trộn đều. Đun sôi lại nếu nước sốt cùng với tôm đã nguội và nấu trong khoảng 5 phút. Thêm feta và loại bỏ nhiệt. Hãy đứng cho đến khi phô mai bắt đầu tan chảy. Ăn nóng với những lát bánh mì giòn.', NULL, '2026-05-15 14:36:18', '2026-05-15 14:36:18'),
(1206, 174, 5, 'Mặc dù hoàn toàn không theo truyền thống, nhưng bạn có thể thêm một vài thìa nước kho hoặc passata vào công thức này để tạo ra nước sốt mì ống thơm ngon. Trộn với mì ống sau khi thêm feta và thưởng thức.', NULL, '2026-05-15 14:36:18', '2026-05-15 14:36:18'),
(1208, 175, 1, 'Đun nóng dầu ô liu trong chảo rán lớn. Cho các lát tỏi vào và nấu trong vài giây. Sau đó đảo tôm và nấu trong vài phút cho đến khi chúng bắt đầu chuyển sang màu hồng.', NULL, '2026-05-15 14:36:21', '2026-05-16 12:35:33'),
(1210, 175, 2, 'Đổ rượu sherry lên và nấu thêm vài phút nữa cho đến khi tôm chín. Rắc rau mùi tây trước khi phục vụ.', NULL, '2026-05-15 14:36:21', '2026-05-16 12:35:33'),
(1211, 176, 1, 'BƯỚC 1', NULL, '2026-05-15 14:36:24', '2026-05-15 14:36:24'),
(1212, 176, 2, 'Cho tất cả nguyên liệu trừ cá mòi vào tô và trộn cùng với một ít gia vị. Đổ vào đĩa nướng, thêm cá mòi và đảo thật đều. Che và thư giãn trong vài giờ.', NULL, '2026-05-15 14:36:24', '2026-05-15 14:36:24'),
(1213, 176, 3, 'BƯỚC 2', NULL, '2026-05-15 14:36:24', '2026-05-15 14:36:24'),
(1214, 176, 4, 'Đun nóng chảo BBQ hoặc vỉ nướng cho đến khi nóng. Nấu cá mòi trong 4-5 phút mỗi bên hoặc cho đến khi thực sự có màu caramen và cháy thành than. Cho ra đĩa, rưới dầu, rắc thêm một ít ớt bột và vắt lên chanh.', NULL, '2026-05-15 14:36:24', '2026-05-15 14:36:24'),
(1218, 178, 1, 'Nêm tôm với 1 thìa canh bột cà ri và gia vị đa năng rồi để riêng trong khoảng 10 phút trong khi chuẩn bị các nguyên liệu khác như cắt hành, ớt và tỏi.', NULL, '2026-05-15 14:36:35', '2026-05-15 14:36:35'),
(1219, 178, 2, 'Đun nóng 2 muỗng canh dầu ô liu trong chảo lớn trên lửa vừa. Thêm hành tây vàng thái lát, ớt chuông đỏ, ớt chuông xanh, ớt chuông Scotch, nếu dùng, tỏi băm nhỏ và khuấy trong 5 phút cho đến khi ớt hơi mềm.', NULL, '2026-05-15 14:36:35', '2026-05-15 14:36:35'),
(1220, 178, 3, 'Thêm 1,5 muỗng canh bột cà ri vào chảo và khuấy thêm một phút.', NULL, '2026-05-15 14:36:35', '2026-05-15 14:36:35'),
(1221, 178, 4, 'Sau đó thêm nước cốt dừa, tôm tẩm gia vị, sốt cà chua và húng tây vào, đảm bảo tôm được bao phủ trong nước sốt.', NULL, '2026-05-15 14:36:35', '2026-05-15 14:36:35'),
(1222, 178, 5, 'Để nước sốt sôi liu riu và tiếp tục nấu ở lửa vừa, thỉnh thoảng khuấy đều và lật tôm nửa chừng cho đến khi tôm chín hoàn toàn cả hai mặt. Quá trình này sẽ mất khoảng 5-6 phút. Muối và hạt tiêu cho vừa ăn.', NULL, '2026-05-15 14:36:35', '2026-05-15 14:36:35'),
(1223, 179, 1, 'Trong một bát vừa, kết hợp tôm với ớt Scotch Bonnet băm nhỏ, gia vị đa năng, điều màu xay và hạt tiêu xay. Đảo đều để thịt thấm đều và để ướp trong 10 phút.', NULL, '2026-05-15 14:36:39', '2026-05-15 14:36:39'),
(1224, 179, 2, 'Đun nóng chảo lớn trên lửa vừa. Thêm nước luộc tôm vào và đun nhỏ lửa. Cho hành và tỏi thái hạt lựu vào, nấu cho đến khi mềm và có mùi thơm, khoảng 2 phút.', NULL, '2026-05-15 14:36:39', '2026-05-15 14:36:39'),
(1225, 179, 3, 'Thêm tôm đã nêm gia vị và nhánh húng tây vào, phết tôm vào chảo. Đậy nắp và nấu trong khoảng 5–7 phút, thỉnh thoảng khuấy đều cho đến khi tôm chuyển sang màu cam sáng và chín đều.', NULL, '2026-05-15 14:36:39', '2026-05-15 14:36:39'),
(1226, 179, 4, 'Thêm giấm trắng, khuấy đều và nấu thêm một phút nữa. Nếm; thêm muối cho vừa ăn. Dùng thìa có rãnh chuyển tôm vào đĩa. Dùng nóng với một ít nước nấu rưới lên trên.', NULL, '2026-05-15 14:36:39', '2026-05-15 14:36:39'),
(1227, 180, 1, 'Đối với cơm, đun nóng dầu trong chảo lớn có nắp đậy, cho hành tây vào, sau đó xào nhẹ trong 5 phút cho đến khi mềm nhưng không có màu. Thêm gia vị, nêm muối rồi tiếp tục xào cho đến khi hỗn hợp bắt đầu chuyển sang màu nâu và có mùi thơm; khoảng 3 phút.', NULL, '2026-05-15 14:36:43', '2026-05-15 14:36:43'),
(1228, 180, 2, 'Thêm gạo và khuấy đều. Thêm 600ml nước vào, khuấy đều rồi đun sôi. Giảm nhỏ lửa, sau đó đậy nắp trong 10 phút. Tắt lửa và để yên, đậy nắp thêm 10-15 phút nữa. Cơm sẽ chín hoàn toàn nếu bạn không mở nắp trước khi nấu xong.', NULL, '2026-05-15 14:36:43', '2026-05-15 14:36:43'),
(1229, 180, 3, 'Trong khi đó, cho cá tuyết chấm đen và lá nguyệt quế vào chảo rán, phủ sữa lên rồi chần trong 10 phút cho đến khi thịt bong ra. Lấy sữa ra, gọt bỏ vỏ, sau đó thái thịt thành từng miếng cỡ ngón tay cái. Cho trứng vào chảo, đổ nước vào, đun sôi rồi giảm nhỏ lửa. Để khoảng 4½-5 phút, ngâm vào nước lạnh, sau đó bóc vỏ và cắt trứng thành từng phần tư. Nhẹ nhàng trộn cá, trứng, rau mùi tây, rau mùi và gạo với nhau trong chảo. Dùng nóng, rắc thêm ít rau thơm.', NULL, '2026-05-15 14:36:43', '2026-05-15 14:36:43'),
(1230, 181, 1, 'Trộn bột ngô và 1 muỗng canh nước tương, cho tôm vào và để yên trong 10 phút. Khuấy giấm, nước tương còn lại, cà chua xay nhuyễn, đường và 2 muỗng canh nước với nhau để làm nước sốt.', NULL, '2026-05-15 14:36:45', '2026-05-15 14:36:45'),
(1231, 181, 2, 'Khi bạn đã sẵn sàng nấu, hãy làm nóng chảo rán hoặc chảo lớn cho đến khi thật nóng, sau đó thêm 1 muỗng canh dầu. Chiên tôm cho đến khi chúng vàng vài chỗ và nở ra – sau đó vớt tôm ra khỏi chảo.', NULL, '2026-05-15 14:36:45', '2026-05-15 14:36:45'),
(1232, 181, 3, 'Đun nóng phần dầu còn lại rồi cho đậu phộng, ớt và hạt dẻ nước vào. Xào trong 2 phút hoặc cho đến khi đậu phộng bắt đầu chuyển màu, sau đó thêm gừng và tỏi vào xào thêm 1 phút nữa. Cho tôm và nước sốt vào đun nhỏ lửa trong 2 phút cho đến khi hơi đặc lại. Ăn kèm cơm.', NULL, '2026-05-15 14:36:45', '2026-05-15 14:36:45'),
(1233, 182, 1, 'Đun nóng dầu trong chảo vừa và thêm ớt. Nấu trong 1 phút, sau đó thêm bột cà ri vào, khuấy đều và nấu thêm 1 phút nữa. Hòa tan viên nước kho trong bình lớn với 700ml nước sôi, sau đó đổ vào chảo và khuấy đều. Đổ nước cốt dừa vào và đun sôi.', NULL, '2026-05-15 14:36:50', '2026-05-15 14:36:50'),
(1234, 182, 2, 'Thêm nước mắm và một ít gia vị. Cho mì vào nấu thêm 3-4 phút cho mì mềm. Vắt nước cốt chanh vào, thêm tôm vào và nấu cho đến khi ấm, khoảng 2-3 phút. Rắc một ít rau mùi lên trên.', NULL, '2026-05-15 14:36:50', '2026-05-15 14:36:50'),
(1235, 182, 3, 'Bày ra bát với phần rau mùi và chanh còn lại ở trên để ép.', NULL, '2026-05-15 14:36:50', '2026-05-15 14:36:50'),
(1236, 183, 1, 'Đun sôi một nồi nước muối lớn', NULL, '2026-05-15 14:36:56', '2026-05-15 14:36:56'),
(1237, 183, 2, 'Thêm mì ống, khuấy một lần và nấu trong khoảng 10 phút hoặc theo hướng dẫn trên gói.', NULL, '2026-05-15 14:36:56', '2026-05-15 14:36:56'),
(1238, 183, 3, 'Trong khi đó, rửa cà chua và cắt làm tư. Cắt ô liu. Rửa húng quế.', NULL, '2026-05-15 14:36:56', '2026-05-15 14:36:56'),
(1239, 183, 4, 'Cho cà chua vào bát salad và rắc lá húng quế lên trên. Thêm một muỗng canh dầu ô liu và trộn.', NULL, '2026-05-15 14:36:56', '2026-05-15 14:36:56'),
(1240, 183, 5, 'Khi mì đã sẵn sàng, đổ mì vào một cái chao và cho nước lạnh chảy qua để mì nguội nhanh.', NULL, '2026-05-15 14:36:56', '2026-05-15 14:36:56'),
(1241, 183, 6, 'Cho mì ống vào bát salad cùng với cà chua và húng quế.', NULL, '2026-05-15 14:36:56', '2026-05-15 14:36:56'),
(1242, 183, 7, 'Thêm ô liu thái lát, quả mozzarella đã ráo nước và khối cá ngừ. Trộn đều và để salad nghỉ ít nhất nửa giờ để hương vị hòa quyện.', NULL, '2026-05-15 14:36:56', '2026-05-15 14:36:56'),
(1243, 183, 8, 'Rắc mì ống với nhiều hạt tiêu đen xay và rưới thêm dầu ô liu còn lại ngay trước khi dùng.', NULL, '2026-05-15 14:36:56', '2026-05-15 14:36:56'),
(1244, 184, 1, 'Đun nóng dầu trong chảo ở lửa vừa. Sau đó cho đậu phộng, ớt khô, tôm khô và dhal vào. Chiên các chất thơm cho đến khi có mùi thơm. Lấy ra khỏi chảo và để sang một bên.', NULL, '2026-05-15 14:36:59', '2026-05-15 14:36:59'),
(1245, 184, 2, 'Trộn các nguyên liệu đã chiên với bột me và nước cho đến khi mịn. Sau đó, xào các nguyên liệu đã trộn trong dầu đun nóng ở lửa nhỏ. Tiếp tục nấu cho đến khi dầu tách ra khỏi hỗn hợp và chuyển sang màu sẫm hơn.', NULL, '2026-05-15 14:36:59', '2026-05-15 14:36:59'),
(1246, 184, 3, 'Gọt vỏ và cắt khoai tây thành từng miếng nhỏ rồi đun sôi trong nồi nước cho đến khi mềm như dao. Sau khi đã sẵn sàng, lấy chúng ra khỏi nồi và để sang một bên. Đổ bỏ nước.', NULL, '2026-05-15 14:36:59', '2026-05-15 14:36:59'),
(1247, 184, 4, 'Hành tây và đậu phụ xào, tỏi băm nhỏ, cắt một ít bắp cải và cải thảo (choi sam). Chuẩn bị tôm chiên và cắt chúng. Luộc mì cho mềm nếu mua khô. Cũng trộn nước tương đen với nước.', NULL, '2026-05-15 14:36:59', '2026-05-15 14:36:59'),
(1248, 184, 5, 'Để chiên một phần mee goreng mamak, đun nóng dầu và thêm 1/4 nguyên liệu sau theo thứ tự sau: tỏi, hành, bột nhão. Xào cho đến khi có mùi thơm. Tùy chọn, thêm tôm.', NULL, '2026-05-15 14:36:59', '2026-05-15 14:36:59'),
(1249, 184, 6, 'Thêm vào 1/4 lượng đậu phụ, khoai tây luộc, bắp cải, bắp cải hoa và tôm chiên. Xào thêm 30 giây nữa.', NULL, '2026-05-15 14:36:59', '2026-05-15 14:36:59'),
(1250, 184, 7, 'Thêm mì vào chảo. Thêm 3 muỗng canh hỗn hợp nước tương đen. Trộn đều trong 1 phút tiếp theo. Sau đó, chuyển mì sang một bên chảo. Khuấy một quả trứng. Trang trí với một lát chanh và vài lát ớt xanh. Để nấu một đĩa mì khác, lặp lại từ bước 5 trở đi.', NULL, '2026-05-15 14:36:59', '2026-05-15 14:36:59'),
(1268, 186, 1, 'Trong một chảo vừa trên lửa vừa, khuấy đều nước cốt dừa, nước, gừng xay, củ gừng, muối, lá nguyệt quế và gạo. Đậy nắp và đun sôi. Giảm nhiệt và đun nhỏ lửa trong 20 đến 30 phút hoặc cho đến khi hoàn thành.', NULL, '2026-05-15 14:37:08', '2026-05-15 14:37:08'),
(1270, 186, 2, 'Cho trứng vào nồi, đổ ngập nước lạnh. Đun sôi nước và tắt bếp ngay lập tức. Đậy nắp và để trứng ngâm trong nước nóng trong 10 đến 12 phút. Lấy trứng ra khỏi nước nóng, để nguội, bóc vỏ và cắt làm đôi. Cắt dưa chuột.', NULL, '2026-05-15 14:37:08', '2026-05-16 12:35:33'),
(1272, 186, 3, 'Trong khi đó, trong chảo hoặc chảo lớn, đun nóng 1 cốc dầu thực vật trên lửa vừa cao. Khuấy đậu phộng và nấu nhanh cho đến khi có màu nâu nhạt. Dùng thìa có rãnh loại bỏ đậu phộng và đặt lên khăn giấy để thấm bớt dầu mỡ thừa. Bắc chảo lên bếp. Khuấy nội dung của một gói cá cơm; nấu nhanh, đảo đều cho đến khi giòn. Lấy thìa có rãnh ra và đặt lên khăn giấy. Loại bỏ dầu. Lau sạch chảo.', NULL, '2026-05-15 14:37:08', '2026-05-16 12:35:33'),
(1274, 186, 4, 'Đun nóng 2 muỗng canh dầu trong chảo. Khuấy hành, tỏi và hẹ tây; nấu cho đến khi có mùi thơm, khoảng 1 hoặc 2 phút. Trộn tương ớt vào và nấu trong 10 phút, thỉnh thoảng khuấy. Nếu tương ớt quá khô, hãy thêm một lượng nhỏ nước. Khuấy cá cơm còn lại; nấu trong 5 phút. Khuấy muối, đường và nước me; đun nhỏ lửa cho đến khi nước sốt đặc lại, khoảng 5 phút.', NULL, '2026-05-15 14:37:08', '2026-05-16 12:35:33'),
(1276, 186, 5, 'Dọn nước sốt hành tỏi lên cơm ấm, trên cùng là đậu phộng, cá cơm chiên, dưa chuột và trứng.', NULL, '2026-05-15 14:37:08', '2026-05-16 12:35:33'),
(1278, 187, 1, 'Thả mì vào tô lớn, sau đó đổ nước sôi vừa đủ ngập mì. Đổ đường cắt lát vào và để trong 4 phút. Xả vào một cái chao, đặt dưới vòi nước lạnh để nguội, sau đó để ráo nước lại. Đổ vào tô và đổ dầu mè vào.', NULL, '2026-05-15 14:37:12', '2026-05-16 12:35:33'),
(1280, 187, 2, 'Trộn các nguyên liệu làm nước sốt. Đổ hành lá, rau mùi và cá hồi lên mì, rưới nước sốt lên và trộn mọi thứ lại với nhau. Ăn kèm với bánh quy xoắn hoặc bánh mì cuộn.', NULL, '2026-05-15 14:37:12', '2026-05-16 12:35:33'),
(1282, 188, 1, 'Cho mì vào một tô chịu nhiệt lớn, đổ nước sôi vào và để trong 4 phút, sau đó vớt ra để ráo nước và ngâm dưới vòi nước lạnh.', NULL, '2026-05-15 14:37:13', '2026-05-16 12:35:33'),
(1284, 188, 2, 'Cho nước cốt chanh, ớt cayenne, đường và nước mắm vào tô rồi trộn đều. Chuẩn bị sẵn tất cả các nguyên liệu khác trên bếp.', NULL, '2026-05-15 14:37:13', '2026-05-16 12:35:33'),
(1286, 188, 3, 'Đun nóng dầu rồi chiên tôm cho đến khi chín. Thêm hành lá và mì vào rồi đảo đều. Đổ hỗn hợp nước cốt chanh vào, sau đó cho giá đỗ, một nửa đậu phộng và rau mùi vào khuấy đều. Nấu trong 1 phút cho đến khi mọi thứ đều nóng.', NULL, '2026-05-15 14:37:13', '2026-05-16 12:35:33'),
(1288, 188, 4, 'Đổ đậu phộng và rau mùi còn lại vào đĩa lớn, rải đều với đậu phộng và rau mùi còn lại, dùng kèm với chanh và tương ớt ngọt.', NULL, '2026-05-15 14:37:13', '2026-05-16 12:35:33'),
(1290, 189, 1, 'Đun nóng 1 muỗng canh dầu trong chảo rộng, nông. Thêm đầu tôm và cọng mùi tây vào xào cho đến khi đầu tôm chuyển sang màu hồng, sau đó nghiền bằng máy nghiền khoai tây. Đổ rượu sherry hoặc rượu vang và 300ml nước, nêm muối và đun nhỏ lửa trong 10 phút để làm nước dùng, nghiền nát đầu tôm khi nấu.', NULL, '2026-05-15 14:37:17', '2026-05-16 12:35:33'),
(1292, 189, 2, 'Rải trai vào chảo, đậy nắp hoặc khăn trà lại, sau đó đặt trên lửa lớn trong 3-4 phút cho đến khi trai vừa mở miệng. Khuấy đều để nước hến chảy ra, sau đó đổ lượng chứa trong chảo vào một cái chao đặt trên một tô lớn chứa nghệ tây. Để nghệ tây ngâm trong nước dùng - bạn sẽ cần tổng cộng 700ml, vì vậy hãy đổ thêm nước nếu cần và khuấy đều mọi thứ. Chọn trai ra khỏi rây, sau đó đặt sang một bên.', NULL, '2026-05-15 14:37:17', '2026-05-16 12:35:33'),
(1294, 189, 3, 'Lau sạch chảo và thêm phần dầu ô liu còn lại vào. Xào chorizo ​​cho đến khi tiết ra dầu, sau đó thêm hành và tỏi vào nấu cho đến khi mềm. Thêm mực và lật lại cho đến khi nó chuyển sang màu trắng. Thêm cà chua và nấu trong một phút, sau đó đổ phần lớn nước kho vào, khuấy đều mọi thứ và đun sôi. Rải gạo lên trên, khuấy đều một lần rồi đun sôi mạnh trong 5 phút. Giảm nhiệt xuống mức thấp nhất và đun nhỏ lửa từ từ trong 10 phút mà không khuấy cho đến khi gạo hấp thụ hầu hết chất lỏng.', NULL, '2026-05-15 14:37:17', '2026-05-16 12:35:33'),
(1296, 189, 4, 'Nhét đuôi tôm vào cơm và đun nhỏ lửa trong 5 phút, lật lại cho đến khi chín. Khuấy qua trai và đậu tằm hoặc đậu Hà Lan. Nếm thử cơm – nếu cơm vẫn còn hơi sống nhưng chảo đã khô, hãy thêm một chút nước luộc và tiếp tục nấu; nếu nước quá loãng thì hãy tăng lửa để nấu hết nước kho cuối cùng.', NULL, '2026-05-15 14:37:17', '2026-05-16 12:35:33'),
(1298, 189, 5, 'Khi cơm vừa chín, tắt lửa và đậy khăn lại trong vài phút. Rắc lá mùi tây và vỏ chanh lên trên, sau đó nêm muối hun khói nếu bạn thích. Khuấy mọi thứ một lần, sau đó dùng ngay từ chảo, với lát chanh ở bên cạnh.', NULL, '2026-05-15 14:37:17', '2026-05-16 12:35:33'),
(1300, 190, 1, 'Xả sạch đậu rồi cho vào chảo lớn với 2 lít nước. Đun nhỏ lửa với toàn bộ tép tỏi, lá nguyệt quế và húng tây trong 30 phút hoặc cho đến khi chín và mềm. Hủy bỏ nhiệt và đặt sang một bên.', NULL, '2026-05-15 14:37:19', '2026-05-16 12:35:33'),
(1302, 190, 2, 'Trong khi đó, đun nóng 2 muỗng canh dầu trong chảo rán. Chiên bánh mì với tép tỏi còn lại. Khi bánh vàng và giòn thì vớt ra để ráo trên giấy ăn. Cho chorizo ​​vào chảo, chiên cho đến khi giòn, vớt ra và giữ ấm cùng với bánh mì.', NULL, '2026-05-15 14:37:19', '2026-05-16 12:35:33'),
(1304, 190, 3, 'Thêm 2 muỗng canh dầu và hành tây vào chảo, nấu trong 5 phút cho đến khi mềm. Khuấy ớt bột. Để ráo đậu rồi cho hành tây cùng nước luộc gà và 2 thìa cà phê muối vào. Nấu trong 5-10 phút. Khuấy qua mùi tây và giữ ấm.', NULL, '2026-05-15 14:37:19', '2026-05-16 12:35:33'),
(1306, 190, 4, 'Nêm cá tuyết và đun nóng 2 muỗng canh dầu còn lại trong chảo rán. Đặt cá tuyết, mặt da úp xuống, vào chảo và nấu trong 3-5 phút trên lửa vừa cao để da giòn. Lật cá lại và nấu thêm 3-5 phút nữa cho đến khi chín. Múc hỗn hợp đậu trắng vào bát, đặt cá tuyết lên trên và kết thúc với bánh mì chiên, chorizo ​​và thêm một ít húng tây.', NULL, '2026-05-15 14:37:19', '2026-05-16 12:35:33'),
(1307, 191, 1, 'BƯỚC 1', NULL, '2026-05-15 14:37:22', '2026-05-15 14:37:22'),
(1308, 191, 2, 'Đun nóng một chút dầu trong chảo rán sâu lòng, lớn rồi xào hành tây và hạt tiêu trên lửa vừa cho đến khi mềm nhưng không chuyển sang màu nâu. Cắt nhỏ cọng rau mùi (giữ lại lá sau) rồi cho vào chảo cùng với ớt và tỏi băm nhỏ. Chiên thêm vài phút nữa. Thêm rượu vang, nghệ tây và lá nguyệt quế vào đun nhỏ lửa cho đến khi còn một nửa.', NULL, '2026-05-15 14:37:22', '2026-05-15 14:37:22'),
(1309, 191, 3, 'BƯỚC 2', NULL, '2026-05-15 14:37:22', '2026-05-15 14:37:22'),
(1310, 191, 4, 'Cho khoai tây, cà chua và 300ml nước vào đun sôi nhẹ. Dùng thìa đặt cạnh chảo bẻ nhỏ cà chua và đun nhỏ lửa trong 20-25 phút cho đến khi khoai tây vừa mềm và cà chua đã nát.', NULL, '2026-05-15 14:37:22', '2026-05-15 14:37:22'),
(1311, 191, 5, 'BƯỚC 3', NULL, '2026-05-15 14:37:22', '2026-05-15 14:37:22'),
(1312, 191, 6, 'Nêm vừa ăn rồi nhẹ nhàng cho cá vào nước sốt rồi xếp mực, tôm, nghêu, hến lên trên mặt nước. Đậy nắp và nấu khoảng 6-8 phút cho đến khi vỏ trai và nghêu mở ra, tôm chín và cá bong tróc. Nướng bánh mì, chà nhẹ với một nửa tép tỏi và rưới dầu ô liu. Phục vụ món hầm với lá rau mùi cắt nhỏ và bánh mì nướng để nhúng.', NULL, '2026-05-15 14:37:22', '2026-05-15 14:37:22'),
(1314, 192, 1, 'Để hành tím giòn, cho dầu vào chảo đun nóng khoảng 5 cm. Bạn sẽ biết dầu đã đủ nóng khi một miếng hẹ vừa thả vào sẽ kêu xèo xèo. Trộn các lát hẹ với bột mì, giũ sạch phần thừa rồi chiên trong dầu cho đến khi vàng. Họ chiên nhanh, khoảng 1 phút. Xả trên giấy ăn, rắc muối và đặt sang một bên.', NULL, '2026-05-15 14:37:25', '2026-05-16 12:35:33'),
(1316, 192, 2, 'Để làm nước sốt, trộn nước cốt chanh, đường, nước mắm và tỏi rồi để sang một bên. Trong một tô trộn lớn, đổ nước sôi lên mì. Để chúng trong 2 phút hoặc cho đến khi chúng vừa chín, sau đó rửa sạch dưới nước lạnh. Để ráo nước, lắc rây nhiều lần để thoát hết nước rồi đặt lại vào tô. Thêm tôm, hành tây, ớt, dưa chuột và rau thơm. Đổ nước sốt lên trên, trộn đều rồi rắc hẹ tây và đậu phộng.', NULL, '2026-05-15 14:37:25', '2026-05-16 12:35:33'),
(1318, 193, 1, 'Cho tôm vào tô. Cho ớt, tỏi, cọng rau mùi (cắt chúng bằng kéo trước) và đường xay vào máy xay gia vị hoặc máy xay thực phẩm nhỏ rồi xay nhuyễn. Thêm một nửa nước cốt chanh và nước mắm, sau đó rưới lên tôm.', NULL, '2026-05-15 14:37:28', '2026-05-16 12:35:33'),
(1320, 193, 2, 'Đun nóng 1 muỗng canh dầu trong chảo, cho gừng và hành lá vào xào trong 1 phút. Thêm ớt đỏ và xào trong 1 phút cho đến khi ớt bắt đầu mềm. Thêm hạt dẻ nước và giá đỗ vào, trộn đều cho đến khi giá đỗ bắt đầu héo. Thêm nước tương và hạt tiêu đen xay thật nhuyễn, sau đó cho rất nhiều vào đĩa phục vụ.', NULL, '2026-05-15 14:37:28', '2026-05-16 12:35:33'),
(1322, 193, 3, 'Đun nóng lượng dầu còn lại trong chảo rồi cho tôm vào, vớt tôm ra khỏi nước. Đảo khoảng 1-2 phút cho đến khi chúng chuyển sang màu hồng, thêm nước xốt vào và đảo nhanh chảo, sau đó đổ hỗn hợp lên rau. Cắt lá rau mùi và rắc phần chanh còn lại. Dùng với mì có thêm chanh để vắt.', NULL, '2026-05-15 14:37:28', '2026-05-16 12:35:33'),
(1324, 194, 1, 'Chuẩn bị trước - cắt đôi quả ớt theo chiều dọc và loại bỏ hạt và cuống. Lót giấy bạc vào chảo nướng và đặt hai nửa hạt tiêu, mặt da hướng lên trên, lên chảo nướng cùng với cả tép tỏi, ớt và cà chua. Nướng trong 2 phút, lật cà chua rồi nướng thêm 2 phút nữa. Dùng thìa lớn loại bỏ cà chua, sau đó gọt vỏ, làm tư và bỏ hạt. Sau đó cắt nhỏ cà chua.', NULL, '2026-05-15 14:37:29', '2026-05-16 12:35:33'),
(1326, 194, 2, 'Tiếp tục nướng tiêu, ớt và tỏi trong 4-5 phút, cho đến khi vỏ ớt và ớt chuyển sang màu đen và tỏi bắt đầu mềm (vỏ tỏi sẽ bắt đầu tách ra khi chín). Khi đủ nguội để cầm, hãy gọt vỏ và cắt đôi quả ớt, cạo bỏ hạt. Gọt vỏ hạt tiêu và cắt nhỏ cả hạt tiêu và ớt.', NULL, '2026-05-15 14:37:29', '2026-05-16 12:35:33'),
(1328, 194, 3, 'Trải các loại hạt lên giấy bạc và nướng cho đến khi nướng. Cắt nhỏ các loại hạt và mùi tây trong máy xay thực phẩm. Đổ vào một cái bát nhỏ.', NULL, '2026-05-15 14:37:29', '2026-05-16 12:35:33'),
(1330, 194, 4, 'Đun nóng 3 thìa dầu ăn trong chảo, cho tiêu, tỏi, ớt vào xào trong 3 phút. Xé bánh mì và cho vào chảo, cho vào chảo dầu cho đến khi chín vàng nhẹ. Cho cà chua, muối, giấm và dầu vào máy xay thực phẩm cho đến khi cắt nhỏ. Đổ tiền vào một cái bát. Để nguội và bảo quản trong tủ lạnh tối đa 3 ngày.', NULL, '2026-05-15 14:37:29', '2026-05-16 12:35:33'),
(1332, 194, 5, 'Trong ngày, thêm các loại hạt và mùi tây vào nước sốt và trộn. Bày ra một chiếc bát nhỏ cùng với tôm đã bóc vỏ. Cung cấp que cocktail để xiên tôm.', NULL, '2026-05-15 14:37:29', '2026-05-16 12:35:33'),
(1334, 195, 1, 'Yêu cầu người bán cá làm sạch mực; những cái nhỏ thường được làm sạch sẵn. Dùng kéo nhà bếp cắt phần thân và mở ra. Rửa sạch, sau đó lau khô. Nếu bạn có một con mực lớn, hãy cắt thân thành bốn phần, gần như hình vuông. Mực nhỏ chỉ có thể được mở ra.', NULL, '2026-05-15 14:37:33', '2026-05-16 12:35:33'),
(1336, 195, 2, 'Sử dụng đầu của một con dao thật sắc, rạch phần trên theo đường chéo gọn gàng. Quét một lớp dầu lên và đặt sang một bên trong khi hâm nóng vỉ nướng hoặc vỉ nướng cho đến khi sẵn sàng nấu.', NULL, '2026-05-15 14:37:33', '2026-05-16 12:35:33'),
(1338, 195, 3, 'Trộn 2 thìa cà phê muối biển, ngũ vị hương Trung Quốc và 1 thìa cà phê tiêu đen mới xay. Rắc đều lên cả hai mặt của mực ngay trước khi nấu, tùy theo khẩu vị. Bạn có thể không cần tất cả. Làm nóng chảo nướng cho nóng và nướng khoảng 1 phút mỗi mặt cho đến khi chảo bắt đầu cong lại. Dùng kẹp gắp ra đĩa và rưới một ít dầu mè. Khi ăn, trang trí với lá rau mùi và dùng kèm với bát nước sốt ớt ngọt nhỏ để chấm.', NULL, '2026-05-15 14:37:33', '2026-05-16 12:35:33'),
(1339, 196, 1, 'Ngâm tất cả các loại gia vị, gừng, tỏi, cùi me và ớt kashmiri trừ dầu trong giấm.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1340, 196, 2, 'Thêm đường và muối.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1341, 196, 3, 'Ngoài ra còn thêm bột nghệ.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1342, 196, 4, 'Trộn đều tất cả và ướp trong 35-40 phút.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1343, 196, 5, 'Xay hỗn hợp cho đến khi mềm và mịn. Thêm giấm nếu cần nhưng đảm bảo hỗn hợp phải đặc, nên thêm giấm cho phù hợp. Nếu bột masala mỏng thì nó sẽ không dính vào cá.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1344, 196, 6, 'Rửa sạch phần cá ở giữa và rạch một đường từ trên xuống. Bạn có thể nhìn thấy con cá bên dưới để hiểu rõ hơn.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1345, 196, 7, 'Bây giờ hãy nhét miếng dán vào giữa và vào vết mổ. Phủ toàn bộ cá bằng hỗn hợp này. Ướp cá trong 30 phút.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1346, 196, 8, 'Cho dầu vào chảo nông, khi dầu khá nóng, hãy chiên cá thu nhồi bông.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1347, 196, 9, 'Chiên cho đến khi vàng đều hai mặt', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1348, 196, 10, 'Ăn nóng cá thu recheado với salad, chanh, cơm và cà ri.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1349, 196, 11, 'Ghi chú', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1350, 196, 12, '1. Đảm bảo bột masala đặc, nếu không kết quả sẽ không tốt.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1351, 196, 13, '2. Nếu bạn không tìm được ớt kashmiri thì hãy dùng ớt bedgi hoặc bột ớt đỏ kashmiri.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1352, 196, 14, '3. Bạn có thể dùng giấm trắng hoặc giấm dừa.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1353, 196, 15, '4. Phần dán còn sót lại có thể được bảo quản trong tủ lạnh để sử dụng sau.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1354, 196, 16, '5. Có thể tránh dùng quế vì nó là một loại gia vị mạnh thường được sử dụng cho thịt hoặc thịt gà.', NULL, '2026-05-15 14:37:35', '2026-05-15 14:37:35'),
(1355, 197, 1, 'Nêm cá hồi, sau đó chà xát với dầu. Trộn các nguyên liệu làm nước sốt với nhau. Cắt đôi, gọt vỏ và cắt lát quả bơ. Cắt đôi và làm tư quả dưa chuột theo chiều dọc, sau đó cắt thành từng lát. Chia salad, bơ và dưa chuột vào bốn đĩa, sau đó rưới một nửa nước sốt lên.', NULL, '2026-05-15 14:37:38', '2026-05-15 14:37:38'),
(1356, 197, 2, 'Làm nóng chảo chống dính. Thêm cá hồi và chiên trong 3-4 phút mỗi mặt cho đến khi giòn nhưng vẫn ẩm bên trong. Đặt phi lê cá hồi lên trên mỗi món salad và rưới lên phần nước sốt còn lại. Phục vụ ấm áp.', NULL, '2026-05-15 14:37:38', '2026-05-15 14:37:38'),
(1358, 198, 1, 'Đổ nước kho vào chảo lớn, đun sôi rồi cho bột cà ri vào khuấy đều. Thêm mì và nấu trong 8 phút. Cho nấm và ngô vào nấu thêm 2 phút nữa.', NULL, '2026-05-15 14:37:40', '2026-05-16 12:35:33'),
(1360, 198, 2, 'Thêm cá hồi vào chảo và nấu trong 3 phút hoặc cho đến khi chín. Tắt bếp và cho nước cốt chanh, nước tương và một chút đường vào khuấy đều. Múc vào 4 bát và rắc rau mùi lên ngay trước khi dùng.', NULL, '2026-05-15 14:37:40', '2026-05-16 12:35:33'),
(1362, 199, 1, 'Làm nóng lò ở 200C/quạt 180C/gas 6. Cho mì vào tô và đổ nước sôi vừa đủ ngập mì. Để trong 2 phút, cho đến khi chúng có thể uốn cong nhưng không quá mềm thì để ráo nước. Cho hành lá, petit pois, muối, tiêu và một phần ba bơ vào bát. Trộn đều cho đến khi bơ tan chảy.', NULL, '2026-05-15 14:37:43', '2026-05-16 12:35:33');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(1364, 199, 2, 'Xếp mì và rau lên hai miếng giấy nướng hình vuông lớn, sau đó đặt cá hồi lên trên. Cắt lát bơ còn lại và xếp lên trên cá hồi. Úp hai đầu tờ giấy lên trên con cá, gấp lại cho kín rồi nhét hai đầu tờ giấy vào bên dưới để không còn khoảng trống. Đặt các gói lên khay nướng và nướng trong 15-20 phút. Chuyển sang đĩa ăn tối và phục vụ ngay lập tức.', NULL, '2026-05-15 14:37:44', '2026-05-16 12:35:33'),
(1365, 200, 1, 'Đun chảy bơ trong chảo có đáy dày và nhẹ nhàng nấu hành tây không màu cho đến khi mềm.', NULL, '2026-05-15 14:37:47', '2026-05-15 14:37:47'),
(1366, 200, 2, 'Thêm gạo và khuấy đều để phủ tất cả các hạt trong bơ', NULL, '2026-05-15 14:37:47', '2026-05-15 14:37:47'),
(1367, 200, 3, 'Thêm rượu và nấu khuấy nhẹ nhàng cho đến khi nó được hấp thụ', NULL, '2026-05-15 14:37:47', '2026-05-15 14:37:47'),
(1368, 200, 4, 'Dần dần thêm nước nóng vào, khuấy đều cho đến khi từng chất bổ sung được hấp thụ. Tiếp tục khuấy cho đến khi gạo mềm', NULL, '2026-05-15 14:37:47', '2026-05-15 14:37:47'),
(1369, 200, 5, 'Nêm nước cốt chanh, vỏ và hạt tiêu cho vừa ăn. (chắc cá hồi đã đủ độ mặn nên không cần cho muối) Khuấy nhẹ cho nóng đều', NULL, '2026-05-15 14:37:47', '2026-05-15 14:37:47'),
(1370, 200, 6, 'Ăn kèm với Parmesan và rau theo mùa.', NULL, '2026-05-15 14:37:47', '2026-05-15 14:37:47'),
(1371, 200, 7, 'Nướng cá hồi và nhẹ nhàng đặt tôm và măng tây lên cơm risotto', NULL, '2026-05-15 14:37:47', '2026-05-15 14:37:47'),
(1373, 201, 1, 'Để làm nước chấm, trộn tất cả nguyên liệu vào một chiếc bát nhỏ cho đến khi đường tan hết rồi để riêng. Trộn bột ngô và bột mì với ớt và 2 thìa muối biển vào tô lớn, sau đó đặt sang một bên. Lót giấy ăn vào khay và đảm bảo bạn có nhiều muối để rắc.', NULL, '2026-05-15 14:37:48', '2026-05-16 12:35:33'),
(1375, 201, 2, 'Đun nóng khoảng 7cm dầu đến 180C trong nồi chiên sâu, chảo hoặc chảo sâu lòng. Nếu không có nhiệt kế, bạn có thể kiểm tra bằng một khối bánh mì – nó sẽ chuyển sang màu nâu sau 20 giây. Phủ đều mực với hỗn hợp bột và chiên theo mẻ trong khoảng 2 phút mỗi mẻ hoặc cho đến khi giòn. Dùng thìa có rãnh vớt mực ra, để ráo nước trên giấy bếp và rắc thêm chút muối. Dọn mực với hành lá và ớt, kèm nước chấm bên cạnh.', NULL, '2026-05-15 14:37:48', '2026-05-16 12:35:33'),
(1377, 202, 1, 'Đun nóng một nửa lượng dầu trong chảo rồi xào hành tây trên lửa vừa cho đến khi mềm và có màu vàng nhạt - quá trình này sẽ mất khoảng 8 phút. Lấy ra khỏi chảo, đặt sang một bên và thêm khoai tây vào chảo. Nấu cho đến khi chúng mềm nhưng không bị nát, thỉnh thoảng lật cẩn thận. Đậy chảo một lúc để giúp các lát chín đều. Cho hành tây trở lại chảo cùng với tỏi và nấu thêm 4 phút nữa. Cho trứng, rau mùi tây và một ít gia vị vào tô rồi trộn đều. Để yên trong nửa giờ.', NULL, '2026-05-15 14:37:51', '2026-05-16 12:35:33'),
(1379, 202, 2, 'Trong khi đó, cho cá tuyết vào nồi và đổ ngập nước. Đun nhỏ lửa. Tắt bếp, đậy nắp và để trong 10 phút. Để ráo nước, để nguội và loại bỏ da và xương. Chia thành từng mảnh lớn và thêm vào hỗn hợp khoai tây và trứng.', NULL, '2026-05-15 14:37:51', '2026-05-16 12:35:33'),
(1381, 202, 3, 'Đun nóng phần dầu còn lại trong chảo chống dính. Đổ hỗn hợp bánh tortilla vào và nấu ở lửa vừa-thấp cho đến khi bánh vừa chín và tách ra khỏi thành chảo. Bạn có thể cần phải che nó lại để giúp phần giữa cố định. Hãy cẩn thận để không nấu quá chín. Thỉnh thoảng đặt một chiếc thìa bên dưới bánh tortilla để đảm bảo bánh không bị dính. Đặt bánh tortilla lên đĩa, sau đó đặt chảo lên trên và lật mặt bánh chưa chín vào đó. Nấu trên lửa nhỏ cho đến khi chín vàng hoặc nướng cho đến khi chín. Để nguội một chút trước khi dùng.', NULL, '2026-05-15 14:37:51', '2026-05-16 12:35:33'),
(1382, 203, 1, 'Đối với cá muối, ngâm muối qua đêm, thay nước vài lần.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1383, 203, 2, 'Xả sạch, sau đó cho cá tuyết vào chảo nước sạch lớn và đun sôi. Xả lại, thêm nước sạch và đun sôi lại.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1384, 203, 3, 'Đun nhỏ lửa trong khoảng năm phút hoặc cho đến khi chín, sau đó để ráo nước và vẩy cá thành từng miếng lớn. Loại bỏ da hoặc xương.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1385, 203, 4, 'Đối với bánh bao, trộn bột mì và mỡ với một chút muối và 250ml/9fl oz nước để tạo thành bột nhào.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1386, 203, 5, 'Bọc hỗn hợp trong màng bám và để trong tủ lạnh để nghỉ.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1387, 203, 6, 'Mở hộp ackee, để ráo nước và rửa sạch, sau đó đặt sang một bên.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1388, 203, 7, 'Đun nóng một thìa dầu ô liu trong chảo và xào hành tây cho đến khi mềm nhưng không có màu nâu.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1389, 203, 8, 'Thêm gia vị, hạt nêm, sốt tiêu và ớt thái lát vào rồi tiếp tục xào cho đến khi ớt mềm.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1390, 203, 9, 'Thêm cà chua xắt nhỏ, sau đó thêm muối vào và trộn đều. Cuối cùng khuấy ackee thật nhẹ nhàng và đun nhỏ lửa cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1391, 203, 10, 'Khi bạn gần chuẩn bị ăn, hãy đun nóng dầu thực vật khoảng 1cm/½ inch trong chảo rán và đun nóng cho đến khi bốc khói.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1392, 203, 11, 'Nặn hỗn hợp bánh bao thành những viên tròn cỡ quả mận và chiên nông cho đến khi có màu vàng nâu. (THẬN TRỌNG: dầu nóng có thể nguy hiểm. Không được để chảo không có người trông coi.)', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1393, 203, 12, 'Xả bánh bao trên giấy ăn và dùng kèm với cá muối và ackee.', NULL, '2026-05-15 14:37:54', '2026-05-15 14:37:54'),
(1395, 204, 1, 'Ướp 6 phi lê cá chẽm với muối và hạt tiêu, sau đó rạch da 3 lần.', NULL, '2026-05-15 14:37:57', '2026-05-16 12:35:33'),
(1397, 204, 2, 'Làm nóng chảo rán nặng và thêm 1 muỗng canh dầu hướng dương.', NULL, '2026-05-15 14:37:57', '2026-05-16 12:35:33'),
(1399, 204, 3, 'Sau khi nóng, chiên phi lê cá chẽm, úp mặt xuống trong 5 phút hoặc cho đến khi da rất giòn và vàng. Cá sẽ gần chín hẳn.', NULL, '2026-05-15 14:37:57', '2026-05-16 12:35:33'),
(1401, 204, 4, 'Lật lại, nấu thêm 30 giây - 1 phút nữa thì bày ra đĩa và dùng nóng. Bạn sẽ cần chiên phi lê cá chẽm thành 2 mẻ.', NULL, '2026-05-15 14:37:57', '2026-05-16 12:35:33'),
(1403, 204, 5, 'Đun nóng 2 thìa dầu hướng dương, sau đó cho gừng đã gọt vỏ cắt thành que diêm vào phi thơm, 3 tép tỏi thái mỏng và 3 quả ớt đỏ thái mỏng khoảng 2 phút cho đến khi chín vàng.', NULL, '2026-05-15 14:37:57', '2026-05-16 12:35:33'),
(1405, 204, 6, 'Tắt lửa và cho bó hành lá cắt nhỏ vào. Rắc cá với 1 muỗng canh nước tương và rưới lên cá trong chảo.', NULL, '2026-05-15 14:37:57', '2026-05-16 12:35:33'),
(1406, 205, 1, 'Đun sôi ấm đun nước. Đổ vẹm vào một cái chao và để dưới vòi nước lạnh. Vứt bỏ bất kỳ vỏ nào bị vỡ. Nhặt từng vỏ, gõ nhẹ vào từng vỏ ở thành bồn rửa - chúng nên đóng lại hoặc nên đóng từ từ khi gõ - nếu chúng vẫn mở, hãy vứt chúng đi. Nếu bất kỳ vỏ nào vẫn còn bám hà hoặc râu xơ xác, hãy dùng dao kéo tách chúng ra và rửa sạch vỏ. Giữ trong một cái chao, phủ một miếng vải ẩm và lạnh cho đến khi bạn sẵn sàng nấu ăn. Tôm chỉ bóc vỏ ở phần thân – giữ nguyên đầu và đuôi. Hãy rạch phần lưng và lôi hết phần ruột có sạn ra. Thư giãn cho đến khi bạn sẵn sàng nấu ăn.', NULL, '2026-05-15 14:37:59', '2026-05-15 14:37:59'),
(1407, 205, 2, 'Cho nghệ tây vào cốc nhỏ, đổ 50ml nước nóng vào ấm và để yên trong 10 phút. Nếu dùng bún thì cho vào tô và dùng tay vò nát thành từng miếng nhỏ (dài khoảng 1cm).', NULL, '2026-05-15 14:37:59', '2026-05-15 14:37:59'),
(1408, 205, 3, 'Đun nóng dầu trong chảo rán lớn có mép chảo ít nhất 3cm hoặc chảo paella 40cm. Thêm hành tây vào và đảo đều chảo trong 5 phút cho đến khi mềm. Thêm tỏi và nấu thêm 1 phút nữa, sau đó cho bún vào nấu trong 5 phút, thỉnh thoảng khuấy cho đến khi bún có màu nâu. Khuấy ớt bột.', NULL, '2026-05-15 14:37:59', '2026-05-15 14:37:59'),
(1409, 205, 4, 'Để lửa vừa phải, khuấy đều cá chày, mực và nghệ tây với nước, nêm gia vị vừa đủ. Dàn đều các nguyên liệu, sau đó rưới nước dùng còn nóng lên và rải cà chua lên trên. Đun sôi, sau đó đậy kín toàn bộ món ăn bằng nắp đậy kín (hoặc giấy bạc). Vặn lửa vừa và nấu trong 6 phút.', NULL, '2026-05-15 14:37:59', '2026-05-15 14:37:59'),
(1410, 205, 5, 'Khám phá và khuấy đều để kết hợp lớp mì ống khô trên cùng. Đẩy hến vào trong mì sao cho bản lề chìm vào đáy đĩa và chúng đứng thẳng lên. Xếp tôm lên trên, đậy kín và nấu thêm 6 phút nữa hoặc cho đến khi trai mở miệng, tôm có màu hồng và mì chín. Để lửa nhỏ thêm 2-3 phút nữa để nấu gần hết chất lỏng còn lại (để lại một ít trong chảo để tránh mì ống dính vào nhau). Để yên trong 2-3 phút, sau đó vắt thêm nước cốt chanh và xếp các miếng nêm lên trên. Rắc rau mùi tây trước khi dùng.', NULL, '2026-05-15 14:37:59', '2026-05-15 14:37:59'),
(1412, 206, 1, 'Đun nóng dầu trong chảo sâu lòng, sau đó cho tỏi tây vào xào mềm trong 5 phút mà không bị chuyển sang màu nâu. Thêm chorizo ​​và chiên cho đến khi nó tiết ra dầu. Khuấy nghệ và gạo cho đến khi được dầu bao phủ, sau đó đổ nước kho vào. Đun sôi, sau đó đun nhỏ lửa trong 15 phút, thỉnh thoảng khuấy.', NULL, '2026-05-15 14:38:01', '2026-05-16 12:35:33'),
(1414, 206, 2, 'Cho đậu Hà Lan vào và nấu trong 5 phút, sau đó cho hải sản vào đun nóng trong 1-2 phút cuối cùng hoặc cho đến khi cơm chín. Kiểm tra gia vị và dùng ngay với chanh.', NULL, '2026-05-15 14:38:01', '2026-05-16 12:35:33'),
(1415, 207, 1, 'BƯỚC 1 – NGÂM MÌ', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1416, 207, 2, 'Ngâm bún qua đêm cho mềm', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1417, 207, 3, 'BƯỚC 2 - LUÔN MÌ', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1418, 207, 4, 'Luộc mì trong vòng 10-15 phút rồi xả lại bằng nước lạnh để dừng quá trình nấu mì.', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1419, 207, 5, 'BƯỚC 3 - Ướp TÔM', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1420, 207, 6, 'Cho tôm, trứng, 1 nhúm tiêu trắng, 1 thìa dầu mè, 1 thìa bột ngô và 1 thìa dầu vào tô.', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1421, 207, 7, 'Trộn đều với nhau', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1422, 207, 8, 'BƯỚC 4 - Xào', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1423, 207, 9, 'Cho 2 thìa dầu vào chảo, cho tôm vào xào cho đến khi có màu vàng nâu', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1424, 207, 10, 'Đặt tôm sang một bên', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1425, 207, 11, 'Thêm 1 muỗng canh dầu vào rồi cho tỏi băm, gừng và tất cả các loại rau vào.', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1426, 207, 12, 'Thêm mì vào chảo', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1427, 207, 13, 'Tiếp theo thêm rượu nấu sherry, dầu hào, đường, giấm, dầu mè, 1 nhúm tiêu trắng và nước tương.', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1428, 207, 14, 'Thêm tôm vào lại', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1429, 207, 15, 'Để làm đặc nước sốt, trộn 1 muỗng canh tinh bột ngô và 2 muỗng canh nước vào tô rồi từ từ thêm vào món xào cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:38:05', '2026-05-15 14:38:05'),
(1430, 208, 1, 'Bạn cũng có thể sử dụng đậu Hà Lan có đường cho công thức này. Tiết kiệm thời gian chuẩn bị bằng cách chuẩn bị đậu Hà Lan, gừng và tỏi trong khi ướp tôm.', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1431, 208, 2, 'Ướp tôm:', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1432, 208, 3, 'Trộn tất cả nguyên liệu làm nước xốt vào tô lớn, sau đó cho tôm vào. Quẳng vào áo khoác. Hãy ngồi trong 15 đến 20 phút trong khi chuẩn bị đậu Hà Lan, gừng và tỏi.', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1433, 208, 4, 'Xào gừng và tỏi:', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1434, 208, 5, 'Đun nóng chảo hoặc chảo xào lớn trên lửa cao trong 1 phút. Thêm dầu đậu phộng và để nóng, khoảng 30 giây. Thêm gừng và tỏi và trộn đều. Xào trong khoảng 30 giây.', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1435, 208, 6, 'Thêm tôm, đậu Hà Lan, nước tương, nước dùng:', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1436, 208, 7, 'Cho tôm và toàn bộ nước xốt vào chảo (dùng thìa cao su cạo hết nước xốt). Thêm đậu tuyết, nước tương và nước luộc gà. Xào cho đến khi tôm chuyển sang màu hồng, khoảng 2 phút.', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1437, 208, 8, 'Thêm hành lá và hoàn thiện với dầu mè:', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1438, 208, 9, 'Thêm hành lá và xào thêm 1 phút nữa. Tắt lửa và thêm dầu mè. Trộn đều một lần nữa và dùng kèm cơm trắng.', NULL, '2026-05-15 14:38:08', '2026-05-15 14:38:08'),
(1439, 209, 1, 'Để có hành ngọt, hãy tìm Vidalia, OSO Sweet hoặc Walla Walla. Những loại hành tây siêu ngọt thích hợp với món xào này hơn vì khi nấu xong, hành tây vẫn còn hơi giòn.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1440, 209, 2, 'Làm nước sốt:', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1441, 209, 3, 'Trong một cái bát, trộn dầu mè, nước tương và giấm gạo.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1442, 209, 4, 'Nấu mì gạo:', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1443, 209, 5, 'Đun sôi một nồi nước lớn, cho mì vào rồi dùng kẹp đảo mì cho ngập nước. Nấu trong 2 phút hoặc cho đến khi chúng mềm nhưng vẫn còn vết cắn (chúng sẽ chín hơn một chút khi bạn thêm chúng vào chảo).', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1444, 209, 6, 'Để ráo nước, xả lại bằng nước lạnh rồi dùng kéo cắt mì nhiều lần để bẻ sợi mì thành những đoạn ngắn hơn.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1445, 209, 7, 'Đánh trứng:', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1446, 209, 8, 'Trong một cái bát nhỏ đánh đều trứng. Đun nóng chảo hoặc lò Hà Lan trên lửa vừa. Thêm 1 muỗng canh dầu đậu phộng hoặc dầu hạt cải. Thêm trứng vào và đánh trong 2 phút hoặc cho đến khi chúng tạo thành khối sữa đông lớn và mềm. Chuyển chúng từ chảo sang đĩa hoặc bát.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1447, 209, 9, 'Nấu rau:', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1448, 209, 10, 'Thêm 1 muỗng canh dầu còn lại vào chảo. Khi trời nóng, thêm gừng, tỏi, cà rốt, ớt jalapeño, hành tây và muối. Nấu, khuấy liên tục trong 2 phút hoặc cho đến khi rau bắt đầu mềm.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1449, 209, 11, 'Thêm các thành phần còn lại:', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1450, 209, 12, 'Rắc hỗn hợp rau với 1 muỗng canh dầu đậu phộng hoặc dầu hạt cải còn lại. Khi dầu nóng, cho giăm bông, bắp cải, hành lá, ớt đỏ và bột cà ri vào chảo. Nấu, khuấy liên tục trong 1 phút.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1451, 209, 13, 'Thêm tôm vào và nấu, khuấy đều thêm 3 phút nữa hoặc cho đến khi tôm có màu hồng tươi và chín.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1452, 209, 14, 'Thêm mì theo mẻ:', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1453, 209, 15, 'Thêm trứng, hỗn hợp nước sốt và một nửa sợi mì vào chảo. Quăng trong 1 phút.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1454, 209, 16, 'Thêm phần mì còn lại vào và tiếp tục đảo thêm 1 phút nữa cho đến khi chúng hòa quyện hoàn toàn và hỗn hợp được đun nóng.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1455, 209, 17, 'Phục vụ:', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1456, 209, 18, 'Nêm nếm gia vị và thêm muối hoặc nước tương nếu bạn thích. Rắc lá ngò và dùng.', NULL, '2026-05-15 14:38:10', '2026-05-15 14:38:10'),
(1457, 210, 1, 'Ngâm cá trích trong nước lạnh ít nhất 1 giờ. Nếu mặn quá thì lặp lại, thay nước mỗi lần.', NULL, '2026-05-15 14:38:13', '2026-05-15 14:38:13'),
(1458, 210, 2, 'Xả thật sạch và cắt cá trích thành từng miếng vừa ăn.', NULL, '2026-05-15 14:38:13', '2026-05-15 14:38:13'),
(1459, 210, 3, 'Cho vào một cái lọ đủ lớn để chứa các miếng và phủ dầu, hạt tiêu, hạt tiêu và lá nguyệt quế. Đóng bình lại.', NULL, '2026-05-15 14:38:13', '2026-05-15 14:38:13'),
(1460, 210, 4, 'Để trong tủ lạnh từ 2 đến 3 ngày trước khi ăn. Điều này sẽ giữ lạnh lên đến 2 tuần.', NULL, '2026-05-15 14:38:13', '2026-05-15 14:38:13'),
(1461, 210, 5, 'Ăn kèm với hành tây thái nhỏ hoặc lát hành tây, chanh và rau mùi tây hoặc thì là.', NULL, '2026-05-15 14:38:13', '2026-05-15 14:38:13'),
(1463, 211, 1, 'Đun sôi ấm đun nước. Trong chảo chống dính hoặc chảo nông có nắp, xào hành tây, ớt, chorizo ​​và tỏi trong dầu trên lửa cao trong 3 phút. Cho gạo và cà chua cắt nhỏ vào với 500ml nước sôi, đậy nắp rồi đun trên lửa lớn trong 12 phút.', NULL, '2026-05-15 14:38:17', '2026-05-16 12:35:33'),
(1465, 211, 2, 'Mở nắp rồi khuấy đều - cơm sẽ gần mềm. Khuấy tôm, rưới thêm nước nếu gạo trông khô, sau đó nấu thêm một phút nữa cho đến khi tôm có màu hồng và gạo mềm.', NULL, '2026-05-15 14:38:17', '2026-05-16 12:35:33'),
(1467, 212, 1, 'Đun nóng dầu trong chảo lớn và cho hành tây vào xào mềm trong 6-7 phút. Thêm hạt tiêu và tỏi, nấu thêm 2 phút nữa, sau đó cho cơm paella vào và nấu trong 1 phút, khuấy đều.', NULL, '2026-05-15 14:38:20', '2026-05-16 12:35:33'),
(1469, 212, 2, 'Đổ nước kho vào, thêm nghệ tây và đun sôi. Nấu, không đậy nắp, ở mức bong bóng nhẹ trong 20 phút, thỉnh thoảng khuấy cho đến khi gạo mềm.', NULL, '2026-05-15 14:38:20', '2026-05-16 12:35:33'),
(1471, 212, 3, 'Khuấy hải sản và nước cốt chanh rồi nấu trong 2 phút hoặc cho đến khi nóng và chín hoàn toàn. Phục vụ trong bát ấm rải rác với rau mùi tây.', NULL, '2026-05-15 14:38:20', '2026-05-16 12:35:33'),
(1473, 213, 1, 'Nấu mì theo hướng dẫn trên bao bì, để ráo nước và để riêng cho lần sau. Đun nóng dầu trong chảo lớn rồi đổ trứng đã đánh vào. Xoay quanh chảo để làm món trứng tráng mỏng, nấu trong 1-2 phút, sau đó lật lại và chiên mặt còn lại trong 1 phút. Mẹo ra và cắt thành dải mỏng.', NULL, '2026-05-15 14:38:23', '2026-05-16 12:35:33'),
(1475, 213, 2, 'Cho ớt và gừng vào chảo, xào khoảng 1-2 phút rồi cho mì, tôm và trứng vào. Rưới nước tương vào và xào thêm 1 phút nữa. Cho các loại thảo mộc đã cắt nhỏ vào và rưới nước cốt chanh và vỏ, sau đó rắc lên đậu phộng đã cắt nhỏ và thưởng thức.', NULL, '2026-05-15 14:38:23', '2026-05-16 12:35:33'),
(1476, 214, 1, 'BƯỚC 1', NULL, '2026-05-15 14:38:25', '2026-05-15 14:38:25'),
(1477, 214, 2, 'Để làm bột, bạn chà bơ vào bột mì rồi cho lòng trắng trứng và một nửa lòng đỏ (giữ lại), giấm, một chút muối và nước lạnh vừa đủ để tạo thành khối bột mềm. Nhào trên bề mặt đã rắc bột mì cho đến khi mịn rồi bọc lại và để yên trong 30 phút.', NULL, '2026-05-15 14:38:25', '2026-05-15 14:38:25'),
(1478, 214, 3, 'BƯỚC 2', NULL, '2026-05-15 14:38:25', '2026-05-15 14:38:25'),
(1479, 214, 4, 'Làm nóng lò ở 180c/quạt 160c/gas 4. Cắt bỏ phần đầu còn xanh của hành lá rồi thái nhuyễn phần còn lại. Đun nóng một ít dầu trong chảo và chiên nhẹ nhàng cho đến khi mềm nhưng không bị chín vàng. Thêm ớt và tỏi vào, khuấy đều rồi cho tôm vào nấu cho đến khi có màu đục. Mùa tốt. Múc tôm ra và đun sôi nước cho đến khi đặc lại, sau đó cho tôm vào.', NULL, '2026-05-15 14:38:26', '2026-05-15 14:38:26'),
(1480, 214, 5, 'BƯỚC 3', NULL, '2026-05-15 14:38:26', '2026-05-15 14:38:26'),
(1481, 214, 6, 'Chia bột empanada thành tám quả bóng và cán thành những vòng tròn mỏng trên bề mặt đã rắc bột mì. Cho một ít nhân vào một nửa miếng bột, rắc feta lên trên và gấp nửa còn lại lại. Cắt bớt mép rồi gấp và gấp bột lại với nhau sao cho empanada được đậy kín, đặt lên khay nướng đã phết dầu ở một bên hoặc đặt trên mép không bị gấp nếp giống như một chiếc bánh bột ngô. Lặp lại với bột và hỗn hợp còn lại. Trộn lòng đỏ trứng còn sót lại với một chút nước và phết lên mặt bánh empanadas.', NULL, '2026-05-15 14:38:26', '2026-05-15 14:38:26'),
(1482, 214, 7, 'BƯỚC 4', NULL, '2026-05-15 14:38:26', '2026-05-15 14:38:26'),
(1483, 214, 8, 'Nướng trong 30 phút hoặc cho đến khi vàng và hơi giòn xung quanh các cạnh.', NULL, '2026-05-15 14:38:26', '2026-05-15 14:38:26'),
(1485, 215, 1, 'Nấu toàn bộ ớt dưới vỉ nướng, trên vỉ nướng hoặc vỉ nướng, cho đến khi cháy hoàn toàn. Cho ớt vào tô, đậy bằng đĩa cho đến khi nguội vừa tay rồi gọt vỏ, bỏ hạt và thái lát mỏng. Trong một tô lớn, trộn ớt và bất kỳ loại nước ép nào với đậu xanh, rau mùi tây, ớt và tỏi. Đặt sang một bên.', NULL, '2026-05-15 14:38:29', '2026-05-16 12:35:33'),
(1487, 215, 2, 'Đun nóng chảo lớn cho đến khi bốc khói. Làm việc nhanh chóng và cẩn thận, thêm một chút dầu vào chảo, sau đó là mực. Xào trong khoảng 30 giây. Rắc chorizo ​​lên mực, tiếp tục nấu thêm 30 giây nữa rồi cho ớt vào tô. Nêm mọi thứ với muối và hạt tiêu, sau đó trộn với lượng dầu còn lại, nước cốt chanh và vỏ chanh. Trộn đều, bày ra đĩa và để mọi người tự lấy.', NULL, '2026-05-15 14:38:29', '2026-05-16 12:35:33'),
(1488, 216, 1, 'BƯỚC 1', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1489, 216, 2, 'ĐỂ LÀM SUSHI CUỘN: Đổ một ít cơm ra. Trải tấm nori lên tấm thảm, mặt bóng úp xuống. Nhúng tay vào nước giấm, sau đó vỗ từng nắm gạo lên trên thành một lớp dày 1cm, chừa lại mép xa nhất.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1490, 216, 3, 'BƯỚC 2', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1491, 216, 4, 'Rưới lên một ít sốt mayonnaise Nhật Bản. Dùng thìa phết một lớp sốt mayonnaise mỏng xuống giữa cơm.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1492, 216, 5, 'BƯỚC 3', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1493, 216, 6, 'Thêm nhân vào. Cho con bạn phủ sốt mayonnaise với một số loại nhân yêu thích của chúng – ở đây chúng tôi sử dụng cá ngừ và dưa chuột.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1494, 216, 7, 'BƯỚC 4', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1495, 216, 8, 'Cuộn nó lại. Nhấc mép tấm thảm lên trên cơm, ấn nhẹ để giữ mọi thứ cuộn chặt.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1496, 216, 9, 'BƯỚC 5', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1497, 216, 10, 'Dán các cạnh xuống như một con tem. Khi đến mép mà không còn cơm thì phết một ít nước và tiếp tục cuộn thành cuộn thật chặt.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1498, 216, 11, 'BƯỚC 6', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1499, 216, 12, 'Bọc trong màng bám. Lấy tấm lót ra và cuộn thật chặt trong màng bám trước khi người lớn cắt sushi thành những lát dày, sau đó gỡ lớp màng bám ra.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1500, 216, 13, 'BƯỚC 7', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1501, 216, 14, 'ĐỂ LÀM SUSHI ÁP LỰC: Phủ lên một ít cá hồi hun khói. Phủ màng dính lên hộp bánh mì, sau đó đặt một lớp mỏng cá hồi hun khói bên trong lên trên màng bọc thực phẩm.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1502, 216, 15, 'BƯỚC 8', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1503, 216, 16, 'Đậy cơm và ấn xuống. Ấn cơm khoảng 3cm lên cá, gấp màng dính lại và ấn xuống hết mức có thể, dùng hộp thiếc khác nếu có.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1504, 216, 17, 'BƯỚC 9', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1505, 216, 18, 'Mẹo nó ra giống như một lâu đài cát. Xếp khối sushi lên thớt. Nhờ người lớn cắt thành từng ngón tay, sau đó gỡ màng bám ra.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1506, 216, 19, 'BƯỚC 10', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1507, 216, 20, 'ĐỂ LÀM BÓNG SUSHI: Chọn phần topping của bạn. Lấy một miếng màng dính hình vuông nhỏ và đặt lớp trên cùng, chẳng hạn như nửa con tôm hoặc một miếng cá hồi hun khói nhỏ lên trên. Dùng tay ẩm để cuộn những viên cơm cỡ quả óc chó và đặt lên trên.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1508, 216, 21, 'BƯỚC 11', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1509, 216, 22, 'Tạo thành những quả bóng chặt chẽ. Chụm các góc của màng bám lại với nhau và siết chặt thành từng quả bóng bằng cách xoắn nó lại, sau đó mở gói ra và thưởng thức.', NULL, '2026-05-15 14:38:31', '2026-05-15 14:38:31'),
(1511, 217, 1, 'Đun nóng dầu trong chảo trên lửa vừa và nấu bột cà ri trong 1 phút trước khi thêm rau xào và tôm vào. Nấu trong 3 phút cho đến khi tôm có màu hồng, sau đó thêm nước cốt dừa, nước luộc rau và mì.', NULL, '2026-05-15 14:38:34', '2026-05-16 12:35:33'),
(1513, 217, 2, 'Đun sôi, sau đó giảm nhiệt cho sôi và nấu trong 5 phút cho đến khi mì chín và rau mềm nhưng vẫn còn vị. Chia thành hai bát và rắc rau thơm, ớt và hành lá lên trên.', NULL, '2026-05-15 14:38:34', '2026-05-16 12:35:33'),
(1515, 218, 1, 'Đun nóng 1 thìa dầu ăn trong chảo, cho hành, tỏi, ớt vào xào khoảng 2-3 phút cho đến khi chín vàng. Thêm tôm và nấu trong 1 phút. Cho gạo và đậu Hà Lan vào, tiếp tục đảo cho đến khi thật nóng. Thêm nước tương và nước mắm vào, sau đó đảo đều với rau mùi cắt nhỏ. Giữ ấm khi chiên trứng.', NULL, '2026-05-15 14:38:36', '2026-05-16 12:35:33'),
(1517, 218, 2, 'Đun nóng lượng dầu còn lại trong chảo rồi chiên trứng với một ít gia vị. Chia hỗn hợp cơm chiên vào 4 bát và phủ một quả trứng chiên lên trên mỗi bát. Ăn kèm rau mùi, tương ớt nếu thích.', NULL, '2026-05-15 14:38:36', '2026-05-16 12:35:33'),
(1519, 219, 1, 'Đun nóng dầu trong chảo vừa. Cho hành tây và gừng vào, sau đó nấu trong vài phút cho đến khi mềm. Khuấy bột cà ri, sau đó nấu thêm 1 phút nữa. Đổ cà chua xắt nhỏ và nước cốt dừa lên trên. Đun sôi, sau đó để nhỏ lửa trong 5 phút, thêm một chút nước sôi nếu hỗn hợp quá đặc.', NULL, '2026-05-15 14:38:40', '2026-05-16 12:35:33'),
(1521, 219, 2, 'Cho tôm vào, sau đó nấu thêm 5-10 phút nữa, tùy thuộc vào kích thước của chúng. Ăn kèm với một ít cơm trắng và rắc một ít rau mùi xắt nhỏ nếu bạn thích.', NULL, '2026-05-15 14:38:40', '2026-05-16 12:35:33'),
(1523, 220, 1, 'Nấu mì theo hướng dẫn đóng gói. Làm mới trong nước lạnh và thoát nước tốt.', NULL, '2026-05-15 14:38:43', '2026-05-16 12:35:33'),
(1525, 220, 2, 'Cho nước luộc vào nồi lớn rồi cho bột cà ri, lá chanh, nước mắm và 250ml nước lạnh vào khuấy đều. Đun nhỏ lửa và nấu trong 5 phút.', NULL, '2026-05-15 14:38:43', '2026-05-16 12:35:33'),
(1527, 220, 3, 'Cắt cá thành khối khoảng 3cm và cho vào chảo. Đun sôi trở lại, sau đó nấu trong 2 phút không đậy nắp.', NULL, '2026-05-15 14:38:43', '2026-05-16 12:35:33'),
(1529, 220, 4, 'Khuấy mì, tôm và pak choi rồi đun nhỏ lửa trong 2-3 phút hoặc cho đến khi cá và tôm vừa chín. Phục vụ trong bát rải rác với rau mùi.', NULL, '2026-05-15 14:38:43', '2026-05-16 12:35:33'),
(1531, 221, 1, 'Đặt các phi lê cá cạnh nhau trên một tờ giấy bạc hình vuông lớn và rải gừng, tỏi, ớt và vỏ chanh lên trên chúng. Rưới nước cốt chanh lên trên rồi rải các miếng pak choi xung quanh và phía trên con cá. Đổ nước tương lên pak choi và dán giấy bạc lại để tạo thành một gói, đảm bảo bạn chừa khoảng trống ở phía trên để hơi nước lưu thông khi cá chín.', NULL, '2026-05-15 14:38:46', '2026-05-16 12:35:33'),
(1533, 221, 2, 'Hấp trong 15 phút. (Nếu bạn không có nồi hấp, hãy đặt gói hàng lên đĩa cách nhiệt trên chảo nước sôi nhẹ, đậy nắp lại và hấp.)', NULL, '2026-05-15 14:38:46', '2026-05-16 12:35:33'),
(1534, 222, 1, 'Làm nóng lò ở mức 200C/400F/Gas 6 (quạt 180C).', NULL, '2026-05-15 14:38:49', '2026-05-15 14:38:49'),
(1535, 222, 2, 'Cho khoai tây vào nồi nước muối lạnh. Đun sôi và đun nhỏ lửa cho đến khi mềm hoàn toàn. Để ráo nước rồi nghiền với bơ và sữa. Thêm hạt tiêu và nếm thử để kiểm tra gia vị. Thêm muối và thêm hạt tiêu nếu cần thiết.', NULL, '2026-05-15 14:38:49', '2026-05-15 14:38:49'),
(1536, 222, 3, 'Để làm nhân cá, làm tan chảy bơ trong chảo, thêm tỏi tây vào và khuấy đều trên lửa. Đậy nắp và đun nhỏ lửa trong 10 phút hoặc cho đến khi mềm. Đong bột vào một cái bát nhỏ. Thêm rượu vào và đánh đều cho đến khi mịn.', NULL, '2026-05-15 14:38:49', '2026-05-15 14:38:49'),
(1537, 222, 4, 'Thêm sữa vào tỏi tây, đun sôi rồi thêm hỗn hợp rượu vào. Khuấy nhanh cho đến khi đặc lại. Nêm và thêm rau mùi tây và cá. Khuấy trên lửa trong hai phút, sau đó cho vào nồi chịu nhiệt. Rắc đều lên trứng. Để nguội cho đến khi cứng lại.', NULL, '2026-05-15 14:38:49', '2026-05-15 14:38:49'),
(1538, 222, 5, 'Đổ khoai tây nghiền lên hỗn hợp cá và đánh dấu bằng nĩa. Rắc phô mai.', NULL, '2026-05-15 14:38:49', '2026-05-15 14:38:49'),
(1539, 222, 6, 'Nướng trong 30-40 phút hoặc cho đến khi mặt trên có màu nâu vàng nhạt và sủi bọt xung quanh các cạnh.', NULL, '2026-05-15 14:38:49', '2026-05-15 14:38:49'),
(1541, 223, 1, 'Đun sôi nước kho trong nồi cỡ vừa. Thêm sả, riềng, rễ ngò và lá chanh vào đun nhỏ lửa trong 2 phút.', NULL, '2026-05-15 14:38:52', '2026-05-16 12:35:33'),
(1543, 223, 2, 'Thêm tôm, nước mắm, ớt và nước cốt chanh vào, sau đó đun sôi lại. Nêm nếm và điều chỉnh gia vị với thêm nước cốt chanh hoặc nước mắm, sau đó trang trí với lá ngò và dùng.', NULL, '2026-05-15 14:38:52', '2026-05-16 12:35:33'),
(1545, 224, 1, 'Đổ 1,3 lít nước vào nồi lớn trên lửa lớn. Thêm hành tây, cà chua, ớt, riềng, sả, đầu tôm và viên nước luộc gà vào. Khuấy và đun sôi, sau đó giảm nhiệt xuống mức trung bình và đun nhỏ lửa trong 20 phút cho đến khi chất lỏng giảm bớt.', NULL, '2026-05-15 14:38:55', '2026-05-16 12:35:33'),
(1547, 224, 2, 'Cẩn thận lọc nước dùng nóng vào tô hoặc bình chịu nhiệt lớn, sau đó loại bỏ đầu tôm. Cho hỗn hợp rau và thảo mộc đã lọc vào nồi và rưới nước dùng lên. Khuấy nấm và lá chanh rồi nấu trong 3 phút cho đến khi nấm mềm.', NULL, '2026-05-15 14:38:55', '2026-05-16 12:35:33'),
(1549, 224, 3, 'Thêm 1 muỗng canh đường, nước mắm, nước cốt chanh, nước cốt dừa và tôm. Đun sôi và nấu cho đến khi tôm chín, khoảng 1-2 phút. Hủy bỏ khỏi nhiệt. Vớt sả ra, sau đó cho mứt ớt Thái vào trộn đều nếu dùng. Rắc lên rau mùi để hoàn thành nếu bạn thích và thưởng thức.', NULL, '2026-05-15 14:38:55', '2026-05-16 12:35:33'),
(1550, 225, 1, 'Đun nóng 2 muỗng cà phê dầu trong chảo lớn và nấu hành lá trên lửa nhỏ trong 3 phút hoặc cho đến khi bắt đầu mềm. Thêm rau bina vào, đậy nắp kín và nấu thêm 2–3 phút hoặc cho đến khi mềm và héo, khuấy một hoặc hai lần. Đổ hỗn hợp vào rây hoặc chao rồi để ráo nước và nguội.', NULL, '2026-05-15 14:38:58', '2026-05-15 14:38:58'),
(1551, 225, 2, 'Sử dụng một chiếc đĩa làm hướng dẫn, cắt ra 24 vòng có đường kính khoảng 12,5 cm (5 in) từ bánh ngọt filo, cắt 6 vòng từ mỗi tờ. Xếp các cuộn filo thành một đống, sau đó dùng màng bọc thực phẩm bọc lại để chúng không bị khô.', NULL, '2026-05-15 14:38:58', '2026-05-15 14:38:58'),
(1552, 225, 3, 'Khi hỗn hợp rau bina nguội, vắt càng nhiều chất lỏng dư thừa càng tốt, sau đó chuyển vào tô. Thêm cá ngừ, trứng, sốt ớt cay, muối và hạt tiêu cho vừa ăn. Trộn đều.', NULL, '2026-05-15 14:38:58', '2026-05-15 14:38:58'),
(1553, 225, 4, 'Làm nóng lò ở nhiệt độ 200°C (400°F, vạch khí 6). Lấy một vòng filo và chải thật nhẹ với một ít dầu còn lại. Phủ vòng thứ hai lên trên và chải với một ít dầu, sau đó đặt vòng thứ ba lên trên và chải bằng dầu.', NULL, '2026-05-15 14:38:58', '2026-05-15 14:38:58'),
(1554, 225, 5, 'Đặt một muỗng canh nhân vào giữa viên tròn, sau đó gấp bánh lại để tạo thành hình bán nguyệt. Gấp các cạnh, xoắn chúng lại để bịt kín và đặt lên khay nướng chống dính. Lặp lại với phần bánh ngọt và nhân còn lại để tạo thành 8 chiếc bánh tất cả.', NULL, '2026-05-15 14:38:58', '2026-05-15 14:38:58'),
(1555, 225, 6, 'Nhẹ nhàng chải các sợi tóc bằng lượng dầu còn lại. Nướng trong 12–15 phút hoặc cho đến khi bánh giòn và có màu vàng nâu.', NULL, '2026-05-15 14:38:58', '2026-05-15 14:38:58'),
(1556, 225, 7, 'Trong khi đó, trộn cà chua và dưa chuột vào tô rồi rưới nước cốt chanh và gia vị cho vừa ăn. Ăn nóng bánh mì với món salad này và tương ớt.', NULL, '2026-05-15 14:38:58', '2026-05-15 14:38:58'),
(1557, 226, 1, 'Làm nóng lò ở 200C/quạt 180C/gas 6. Trộn khoai tây với 2 thìa cà phê dầu và một ít gia vị. Đặt lên một khay nướng lớn, sau đó nướng trong 20 phút, khuấy nửa chừng cho đến khi giòn, vàng và chín đều.', NULL, '2026-05-15 14:39:01', '2026-05-15 14:39:01'),
(1558, 226, 2, 'Trong khi đó, cho trứng vào chảo nước nhỏ, đun sôi rồi đun nhỏ lửa trong 8-10 phút, tùy thuộc vào cách bạn muốn trứng chín. Ngâm vào tô nước lạnh để nguội trong vài phút. Bóc vỏ, sau đó cắt làm đôi.', NULL, '2026-05-15 14:39:01', '2026-05-15 14:39:01'),
(1559, 226, 3, 'Trong một bát salad lớn, trộn đều dầu còn lại, giấm rượu vang đỏ, nụ bạch hoa và cà chua cắt nhỏ. Nêm, cho hành tây, rau bina, cá ngừ và khoai tây vào, sau đó nhẹ nhàng trộn đều. Phủ trứng lên trên, sau đó dùng ngay.', NULL, '2026-05-15 14:39:01', '2026-05-15 14:39:01'),
(1561, 227, 1, 'Cho đường vào một cái chảo nông lớn cùng với một chút nước. Đun nóng nhẹ, xoay chảo cho đến khi đường tan. Tăng nhiệt và đun sôi xi-rô cho đến khi nó chuyển sang màu hổ phách đậm. Cho nước mắm, phần lớn ớt và gừng vào, sau đó cho vào 1 thìa canh nước cho loãng. Đun sôi lại cho đến khi có nước siro, sau đó thêm phi lê cá, có da úp xuống, và cải chíp, cắt úp xuống.', NULL, '2026-05-15 14:39:03', '2026-05-16 12:35:33'),
(1563, 227, 2, 'Đậy nắp chảo và đun nhỏ lửa trong 4-5 phút cho đến khi cá chín và cải chíp héo. Tắt bếp, vắt chanh lên rồi rải đều ớt, gừng và nhánh ngò còn lại. Ăn kèm cơm.', NULL, '2026-05-15 14:39:03', '2026-05-16 12:35:33'),
(1565, 228, 1, 'Trộn tất cả các nguyên liệu làm nước chấm cùng với 50ml nước vào tô và đặt sang một bên để đường tan và hương vị ngấm.', NULL, '2026-05-15 14:39:06', '2026-05-16 12:35:33'),
(1567, 228, 2, 'Để gói các cuộn bánh, hãy đổ đầy nước ấm vào một chiếc bát rộng và lấy một chiếc khăn trà ẩm sạch để thực hiện. Nhúng giấy gói bánh tráng vào nước trong vài giây cho đến khi mềm rồi cẩn thận đặt lên khăn.', NULL, '2026-05-15 14:39:06', '2026-05-16 12:35:33'),
(1569, 228, 3, 'Đặt một ít lá bạc hà và rau mùi vào giữa giấy gói, sau đó đặt hai con tôm và một ít rau xoắn ốc lên trên, có thể cần phải cắt nhỏ nếu xoắn ốc quá dài.', NULL, '2026-05-15 14:39:06', '2026-05-16 12:35:33'),
(1571, 228, 4, 'Gấp các cạnh của giấy gói vào giữa, phủ lên trên phần nhân, sau đó gấp các cạnh sao cho phần nhân được bọc hoàn toàn, sau đó cuộn thật chặt. Lặp lại cho đến khi sử dụng hết giấy gói và phần nhân. Khi dùng, cắt chéo và ăn cùng nước chấm.', NULL, '2026-05-15 14:39:06', '2026-05-16 12:35:33'),
(1573, 229, 1, 'Cắt nhỏ ớt trong máy xay thực phẩm, sau đó cho ớt vào rây và ấn vào rây để ớt tiết ra hết nước. Cho thịt băm, tương ớt đỏ, bột biber, 1½ thìa cà phê muối biển và 2 thìa dầu vào tô. Trộn đều, nhào kỹ ít nhất 2-3 phút. Nếu cần, hãy làm ướt tay bằng nước lạnh để hỗn hợp không bị dính. Hỗn hợp phải dính khi đã sẵn sàng. Đậy nắp và để lạnh ít nhất 2 giờ hoặc tối đa 12 giờ.', NULL, '2026-05-15 14:39:10', '2026-05-16 12:35:33'),
(1575, 229, 2, 'Khi đã sẵn sàng nấu, làm nóng vỉ nướng ở mức cao hoặc cho vào lò nướng ở nhiệt độ 220C/200C quạt/gas 6. Chia hỗn hợp thành 12 phần bằng nhau, mỗi phần khoảng 85g. Nếu bạn muốn xiên chúng, hãy chia thành 8 phần bằng nhau và vo thành từng viên tròn. Dùng tay ướt, xâu các viên bi vào đầu xiên, xoa hỗn hợp xuống xiên ở giữa lòng bàn tay cho đến khi phân bố đều. Đảm bảo hỗn hợp được quấn chặt quanh xiên mà không để lộ phần kim loại nào. Ngoài ra, hãy đặt chúng lên một khay nướng lớn có lót giấy da nếu nấu trong lò hoặc giấy bạc nếu nấu dưới vỉ nướng. Tạo hình thành köfte dài 20cm. Làm ướt ngón tay của bạn bằng một ít nước lạnh và tạo các vết lõm dọc theo köfte để có hình dạng truyền thống.', NULL, '2026-05-15 14:39:10', '2026-05-16 12:35:33'),
(1577, 229, 3, 'Nhẹ nhàng phết từng köfte với 1 muỗng canh dầu còn lại và nấu dưới vỉ nướng, đặt trên kệ trên cùng trong 10-12 phút, đảo đều hoặc nấu trong lò trong 16-18 phút, cho đến khi giòn bên ngoài và ngon ngọt ở giữa', NULL, '2026-05-15 14:39:10', '2026-05-16 12:35:33'),
(1579, 230, 1, 'Cho tỏi vào tô cùng với gừng, nước cốt chanh, dầu, gia vị và hạt nêm. Dùng máy xay cầm tay xay nhuyễn cho đến khi mịn, sau đó dùng để phết sườn cừu lên cả hai mặt. Để ướp trong tủ lạnh vài giờ hoặc qua đêm.', NULL, '2026-05-15 14:39:13', '2026-05-16 12:35:33'),
(1581, 230, 2, 'Đun nóng thịt nướng cho đến khi nóng. Nướng sườn trên than khoảng 3 phút mỗi mặt cho đến khi chín nhưng vẫn còn màu hồng và mọng nước ở giữa.', NULL, '2026-05-15 14:39:13', '2026-05-16 12:35:33'),
(1582, 231, 1, 'Đặt freekeh vào một cái bát nhỏ và đậy lại bằng nước lạnh. Đặt sang một bên.', NULL, '2026-05-15 14:39:14', '2026-05-15 14:39:14'),
(1583, 231, 2, 'Cho thịt cừu, hành tây, tiêu đen, ớt bột, quế và muối vào nồi. Khuấy dầu, 1/2 củ ngò, 1/2 lá bạc hà và cọng cần tây cho đến khi hòa quyện. Đun nhỏ lửa ở nhiệt độ thấp trong 15 phút. Khuấy đậu xanh; đổ nước vừa đủ ngập rồi đun nhỏ lửa. Khuấy bí xanh, cà rốt và bột cà chua.', NULL, '2026-05-15 14:39:14', '2026-05-15 14:39:14'),
(1584, 231, 3, 'Đặt nồi hấp lên trên nồi; thêm cà chua. Đậy nắp và hấp cà chua cho đến khi mềm, khoảng 5 phút. Nghiền cà chua bằng thìa gỗ để bã cà chua nhỏ vào súp. Lấy nồi hấp ra và loại bỏ vỏ cà chua còn sót lại.', NULL, '2026-05-15 14:39:14', '2026-05-15 14:39:14'),
(1585, 231, 4, 'Thêm khoai tây vào súp và lượng nước vừa đủ. Đun nhỏ lửa cho đến khi khoai tây mềm, khoảng 10 phút.', NULL, '2026-05-15 14:39:14', '2026-05-15 14:39:14'),
(1586, 231, 5, 'Xả freekeh và thêm vào súp. Đun nhỏ lửa cho đến khi mềm, khoảng 15 phút. Loại bỏ cuống cần tây và loại bỏ. Rắc súp với 1/2 ngò còn lại và 1/2 lá bạc hà còn lại trước khi dùng.', NULL, '2026-05-15 14:39:14', '2026-05-15 14:39:14'),
(1587, 232, 1, 'Cắt thịt cừu thành miếng lớn.', NULL, '2026-05-15 14:39:16', '2026-05-15 14:39:16'),
(1588, 232, 2, 'Cắt bắp cải thành từng miếng lớn, giữ nguyên phần lõi.', NULL, '2026-05-15 14:39:16', '2026-05-15 14:39:16'),
(1589, 232, 3, 'Xếp một lớp miếng thịt cừu vào đáy nồi lớn, úp mặt mỡ xuống. Rắc hạt tiêu và muối. Thêm một lớp bắp cải nêm lên trên. Lặp lại với nhiều lớp thịt cừu, hạt tiêu và bắp cải hơn, kết thúc bằng bắp cải ở trên.', NULL, '2026-05-15 14:39:16', '2026-05-15 14:39:16'),
(1590, 232, 4, 'Tùy chọn: Rắc một vài thìa lên trên miếng thịt cừu để có món hầm đặc hơn.', NULL, '2026-05-15 14:39:16', '2026-05-15 14:39:16'),
(1591, 232, 5, 'Thêm nước vào nồi và đun sôi. Che và giảm nhiệt. Nấu trên lửa nhỏ trong 2 – 3 giờ, cho đến khi thịt cừu nhẹ nhàng rời khỏi xương.', NULL, '2026-05-15 14:39:16', '2026-05-15 14:39:16'),
(1592, 232, 6, 'Ăn kèm với khoai tây luộc và rau mùi tây tươi, phủ đều nước dùng fårikål.', NULL, '2026-05-15 14:39:16', '2026-05-15 14:39:16'),
(1594, 233, 1, 'Làm nóng chảo nướng. Xoa thịt cừu bít tết với dầu, thì là và một ít gia vị. Nướng khoảng 3-4 phút mỗi mặt hoặc cho đến khi chín theo ý thích của bạn. Đặt sang một bên trên đĩa để nghỉ ngơi.', NULL, '2026-05-15 14:39:20', '2026-05-16 12:35:33'),
(1596, 233, 2, 'Trong một tô lớn, khuấy đường vào giấm cho đến khi hòa tan. Thêm cà rốt, hành lá, bắp cải và một ít gia vị vào rồi trộn đều.', NULL, '2026-05-15 14:39:20', '2026-05-16 12:35:33'),
(1598, 233, 3, 'Nghiền toàn bộ ớt và mayo trong máy xay thực phẩm. Thêm một đống salad vào mỗi chiếc bánh mì dẹt. Cắt lát thịt cừu, cắt bỏ phần mỡ thừa và đặt lên trên món salad, rưới nước trái cây còn lại. Rưới sốt mayo lên và rắc một ít ớt cắt lát. Cuộn lại và ăn. Nếu sử dụng pitta, chia nhỏ và nhồi. Phục vụ thêm bất kỳ món salad nào ở bên cạnh.', NULL, '2026-05-15 14:39:20', '2026-05-16 12:35:33'),
(1600, 234, 1, 'Làm nóng lò nướng ở mức quạt/khí 190C/170C 5. Cắt đôi quả cà tím theo chiều dọc và khía sâu vào mặt thịt, phết một lớp dầu ô liu vừa phải rồi đặt lên khay nướng. Nướng trong 20 phút hoặc cho đến khi thịt đủ mềm để múc ra.', NULL, '2026-05-15 14:39:23', '2026-05-16 12:35:33'),
(1602, 234, 2, 'Chiên hành tây với một ít dầu cho đến khi mềm, thêm tỏi và quế vào xào trong 1 phút. Sau khi cà tím đủ nguội để cầm, hãy múc phần giữa của cà tím. Cắt nhỏ thịt và thêm vào hành tây. Cắt đôi quả cà chua, múc hạt và nước ép vào rây đặt trên bát, sau đó cắt nhỏ thịt. Thêm cà chua xắt nhỏ vào chảo và nấu mọi thứ trong 10 phút cho đến khi mềm và ngon. Thêm một chút dầu nếu bạn cần. Khuấy mùi tây, để lại một ít để rải ở cuối.', NULL, '2026-05-15 14:39:23', '2026-05-16 12:35:33'),
(1604, 234, 3, 'Đặt hai nửa cà tím vào đĩa nướng và chia hỗn hợp cà chua vào giữa chúng. Đổ nước ép từ cà chua lên, rưới thêm dầu ô liu và nướng trong 30 phút cho đến khi cà tím xẹp xuống.', NULL, '2026-05-15 14:39:23', '2026-05-16 12:35:33'),
(1606, 234, 4, 'Trong khi đó, trộn các nguyên liệu tzatziki với nhau và cho vào tô nhỏ.', NULL, '2026-05-15 14:39:23', '2026-05-16 12:35:33'),
(1608, 234, 5, 'Nêm thịt cừu với muối, hạt tiêu đen và một chút ớt bột. Nướng, nướng hoặc nướng thịt trong 3 phút mỗi mặt hoặc cho đến khi mỡ có màu nâu vàng đẹp mắt, sau đó đặt vào đĩa phục vụ và vắt lên nửa quả chanh. Rắc cà tím với rau mùi tây, sau đó dùng kèm với thịt cừu và tzatziki.', NULL, '2026-05-15 14:39:23', '2026-05-16 12:35:33'),
(1609, 235, 1, 'Cắt thịt thành dải. Đun nóng dầu trong chảo và chiên các dải trong 6 phút cho đến khi chín.', NULL, '2026-05-15 14:39:27', '2026-05-15 14:39:27'),
(1610, 235, 2, 'Nướng khoai tây chiên cho đến khi vàng nâu trong nồi chiên sâu. Khi đã sẵn sàng chuyển sang đĩa lót. Hãy chắc chắn rằng khoai tây chiên được trải đều trên toàn bộ món ăn.', NULL, '2026-05-15 14:39:27', '2026-05-15 14:39:27'),
(1611, 235, 3, 'Phủ một lớp thịt mới lên khoai tây chiên và trải đều.', NULL, '2026-05-15 14:39:27', '2026-05-15 14:39:27'),
(1612, 235, 4, 'Thêm một lớp phô mai lên trên thịt. Bạn cũng có thể sử dụng phô mai bào. Khi hoàn tất, cho vào lò nướng vài phút cho đến khi phô mai tan chảy.', NULL, '2026-05-15 14:39:27', '2026-05-15 14:39:27'),
(1613, 235, 5, 'Cắt nhỏ rau diếp, cà chua và dưa chuột rồi trộn đều. cho món salad cơ bản. Ngoài ra, bạn có thể thêm ô liu jalapenos và hỗn hợp màu đỏ.', NULL, '2026-05-15 14:39:27', '2026-05-15 14:39:27'),
(1614, 235, 6, 'Bày salad lên trên đĩa và ăn kèm với nước sốt tỏi và nước sốt nóng', NULL, '2026-05-15 14:39:27', '2026-05-15 14:39:27'),
(1615, 236, 1, 'Đun nóng dầu thực vật trong chảo lớn trên lửa vừa cao. Thêm thịt cừu vào và nấu cho đến khi chín vàng các mặt, khoảng 5 phút. Nêm nghệ tây, muối và hạt tiêu cho vừa ăn; khuấy đều trừ 4 thìa hành tây và đổ nước vào. Đun sôi, sau đó đậy nắp, giảm nhiệt xuống mức trung bình thấp và đun nhỏ lửa cho đến khi thịt cừu mềm, khoảng 15 phút.', NULL, '2026-05-15 14:39:29', '2026-05-15 14:39:29'),
(1616, 236, 2, 'Mở chảo, cho bơ vào khuấy đều và để nước sốt giảm từ 5 đến 10 phút để đạt độ đặc mong muốn. Nêm muối và tiêu cho vừa ăn rồi đổ ra đĩa phục vụ. Rắc hành tây và rau mùi tây cắt nhỏ còn lại. Trang trí với chanh để phục vụ.', NULL, '2026-05-15 14:39:29', '2026-05-15 14:39:29'),
(1618, 237, 1, 'Cho thịt băm vào một cái tô lớn (dùng bát rửa sạch nếu bạn không có thứ gì đủ lớn) cùng với tất cả các nguyên liệu làm bánh mì kẹp thịt khác và một chút muối. Xắn tay áo lên, nhúng tay vào hỗn hợp và trộn mọi thứ lại với nhau bằng ngón tay cho đến khi trộn hoàn toàn. Đổ hỗn hợp vào 16 chiếc bánh mì kẹp thịt nhỏ. Bây giờ chúng có thể được đông lạnh trong tối đa 1 tháng hoặc làm lạnh trước một ngày.', NULL, '2026-05-15 14:39:32', '2026-05-16 12:35:33'),
(1620, 237, 2, 'Để nấu, hãy làm nóng vỉ nướng ở mức cao nhất và xếp bánh mì kẹp thịt thành một lớp trên khay nướng (bạn có thể cần thực hiện việc này theo từng mẻ, tùy thuộc vào kích thước khay của bạn). Nướng trên kệ cao nhất trong 5-6 phút mỗi mặt cho đến khi chín vàng và chín đều. Xếp bánh mì kẹp thịt lên đĩa và phục vụ cùng với tất cả các món ăn kèm để mọi người có thể tự làm bánh sandwich cho mình.', NULL, '2026-05-15 14:39:32', '2026-05-16 12:35:33'),
(1622, 238, 1, 'Đun nóng 2 muỗng cà phê dầu trong chảo và cho hành tây vào xào mềm trong 5 phút. Thêm tỏi và gia vị và nấu thêm vài phút nữa. Múc một nửa hỗn hợp hành tây vào tô và để nguội. Thêm cà chua, đường và gia vị vào số hành còn lại trong chảo và đun nhỏ lửa trong khoảng 10 phút cho đến khi chín.', NULL, '2026-05-15 14:39:35', '2026-05-16 12:35:33'),
(1624, 238, 2, 'Trong khi đó, thêm bạc hà, thịt cừu, quả mơ và vụn bánh mì vào hành đã nguội, nêm gia vị và dùng tay trộn đều. Tạo hình thành những viên thịt nhỏ.', NULL, '2026-05-15 14:39:35', '2026-05-16 12:35:33'),
(1626, 238, 3, 'Đun nóng phần dầu còn lại trong chảo chống dính và chiên thịt viên cho đến khi vàng (theo từng mẻ nếu bạn cần). Khuấy nước sốt với một chút nước và nấu nhẹ mọi thứ trong vài phút cho đến khi thịt viên chín. Ăn kèm bánh mì pitta và salad.', NULL, '2026-05-15 14:39:35', '2026-05-16 12:35:33'),
(1627, 239, 1, 'Nghiền tỏi với muối biển bằng chày và cối (hoặc dùng máy xay thực phẩm nhỏ) cho đến khi tỏi tạo thành hỗn hợp sệt. Trộn đều dầu, nước cốt chanh, vỏ, thì là và tỏi. Trộn thịt cừu vào và trộn đều. Đậy nắp và ướp ít nhất 2 tiếng hoặc qua đêm trong tủ lạnh. Nếu bạn định sử dụng xiên tre, hãy ngâm chúng trong nước lạnh.', NULL, '2026-05-15 14:39:39', '2026-05-15 14:39:39'),
(1628, 239, 2, 'Nếu bạn đã chuẩn bị thịt cừu vào ngày hôm trước, hãy lấy thịt ra khỏi tủ lạnh 30 phút trước khi nấu. Xiên thịt vào xiên đã ngâm nước hoặc kim loại. Làm nóng lò nướng ở mức cao hoặc chuẩn bị sẵn chảo nướng nóng hoặc món nướng. Nướng xiên trong 2-3 phút mỗi mặt, phết phần nước xốt còn lại. Đun nóng bánh pitta hoặc bánh mì dẹt trong thời gian ngắn, sau đó nhồi souvlaki vào. Thêm salad Hy Lạp (xem \'Rất hợp\', bên phải) và Tzatziki (bên dưới), nếu bạn thích.', NULL, '2026-05-15 14:39:39', '2026-05-15 14:39:39'),
(1629, 240, 1, 'Rắc thịt bằng bột mì để phủ nhẹ.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1630, 240, 2, 'Đun nóng lượng dầu thực vật vừa đủ trong một cái chảo lớn để đổ đầy đế rồi xào hành tây và thịt cho đến khi chín vàng nhạt. Nêm muối và hạt tiêu.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1631, 240, 3, 'Thêm cà rốt, nước luộc và thêm gia vị cho vừa ăn.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1632, 240, 4, 'Đun sôi, đậy nắp và giảm nhiệt cho sôi. Đun nhỏ lửa ít nhất một giờ hoặc cho đến khi thịt mềm. Hãy dành thời gian nấu thịt, để càng lâu thì hương vị sẽ càng ngon.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1633, 240, 5, 'Làm nóng lò ở 180C/350F/Gas 4.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1634, 240, 6, 'Thêm khối khoai tây đã ráo nước vào thịt cừu.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1635, 240, 7, 'Biến hỗn hợp thành đĩa bánh hoặc món thịt hầm và phủ một lớp vỏ bánh ngọt lên trên. Tạo ba khe ở mặt trên của bánh ngọt để thoát hơi nước trong khi nấu.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1636, 240, 8, 'Quét một lớp trứng đã đánh lên và nướng trong khoảng 40 phút cho đến khi bánh có màu vàng nâu.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1637, 240, 9, 'Phục vụ.', NULL, '2026-05-15 14:39:44', '2026-05-15 14:39:44'),
(1638, 241, 1, 'Nghiền hạt điều, hạt anh túc và hạt thì là thành bột nhão mịn, sử dụng càng ít nước càng tốt. Đặt sang một bên.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1639, 241, 2, 'Chiên hành tây thái lát khi còn nóng. Đừng đổ quá nhiều dầu. Khi hành tây chuyển sang màu nâu nhạt, vớt ra để ráo dầu trên khăn giấy. Hành tây chiên sẽ giòn khi để ráo nước. Cũng chiên hạt điều cho đến khi vàng nâu. Đặt sang một bên.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1640, 241, 3, 'Vo gạo và ngâm trong nước trong hai mươi phút.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1641, 241, 4, 'Trong khi đó, lấy một chiếc chảo lớn, cho dầu vào lửa vừa, cho hành tây thái lát, thêm hỗn hợp đã trộn vào, thêm ớt xanh, gừng, tỏi và tỏi vào xào trong một phút.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1642, 241, 5, 'Sau đó cho cà chua vào xào chín và không bị nhão.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1643, 241, 6, 'Sau đó, thêm bột ớt đỏ, bột biryani, bạc hà, lá rau mùi và xào đều.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1644, 241, 7, 'Thêm sữa chua và trộn đều. Tôi luôn di chuyển chảo ra xa nguồn nhiệt khi thêm sữa chua để tránh sữa đông lại.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1645, 241, 8, 'Bây giờ sau khi đặt chảo trở lại bếp, cho thịt cừu đã rửa sạch, muối và ½ cốc nước vào trộn đều. Nấu trong 1 giờ và đun ở lửa vừa thấp hoặc cho vào nồi áp suất trong 6 tiếng còi. Nếu nước chưa thoát hết, hãy làm nóng nó bằng cách mở nắp.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1646, 241, 9, 'Lấy một cái chảo lớn khác, cho gấp ba chén gạo bạn dùng vào rồi đun sôi. Khi nước sôi cao, cho gạo, muối và jeera vào rồi trộn đều. Chính xác là sau 7 phút hoặc khi cơm chín được 80%. Tắt và xả gạo.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1647, 241, 10, 'Bây giờ, việc phân lớp bắt đầu. Để thịt cừu, vỗ nhẹ và san bằng nó. Thêm cơm nóng đã ráo nước lên trên. Trang trí với hành tây chiên, bơ sữa trâu, bạc hà, lá rau mùi và nghệ tây hòa tan trong sữa.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1648, 241, 11, 'Đậy đĩa và nướng trong lò 350f trong 15 phút hoặc cho đến khi chín nhưng không nhão. Hoặc nấu trên bếp lửa vừa trong 12 phút và lửa nhỏ nhất trong 5 phút. Và tắt đi. Trộn và dùng nóng!', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1649, 241, 12, 'Ghi chú', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1650, 241, 13, '1. Nếu bạn nấu trong lò nướng, hãy đảm bảo nấu trong chảo lớn an toàn cho lò nướng và đậy nắp kín rồi cho vào lò nướng cho bước cuối cùng.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1651, 241, 14, '2. Bạn có thể bỏ qua biryani masala nếu không có và chỉ thêm garam masala (1 thìa cà phê và bột ớt đỏ – 3 thìa cà phê thay vì 1 thìa cà phê)', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1652, 241, 15, '3. Nếu cuối cùng nó cay, hãy vắt một ít chanh, nó sẽ làm giảm nhiệt và tăng hương vị.', NULL, '2026-05-15 14:39:49', '2026-05-15 14:39:49'),
(1653, 242, 1, 'Đặt nho khô và mận vào một cái bát nhỏ và đổ lượng nước vừa đủ. Thêm nước cốt chanh và ngâm ít nhất 1 giờ. Làm khô hạn. Cắt nhỏ mận.', NULL, '2026-05-15 14:39:52', '2026-05-15 14:39:52'),
(1654, 242, 2, 'Trong khi đó, đun nóng bơ trong chảo lớn, thêm hành tây và nấu trong 5 phút. Thêm thịt cừu thái miếng, thịt cừu xay và tép tỏi nghiền. Chiên trong 5 phút, khuấy liên tục cho đến khi chín vàng.', NULL, '2026-05-15 14:39:52', '2026-05-15 14:39:52'),
(1655, 242, 3, 'Đổ 2/3 cốc (150 ml) nước dùng vào chảo. Đun sôi, sau đó giảm nhiệt, đậy nắp và đun nhỏ lửa trong 1 giờ hoặc cho đến khi thịt cừu mềm.', NULL, '2026-05-15 14:39:52', '2026-05-15 14:39:52');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(1656, 242, 4, 'Thêm lượng nước còn lại vào và đun sôi. Thêm gạo trắng hạt dài đã vo sạch và một nhúm nghệ tây lớn. Khuấy đều, sau đó đậy nắp và đun nhỏ lửa trong 15 phút hoặc cho đến khi gạo mềm.', NULL, '2026-05-15 14:39:52', '2026-05-15 14:39:52'),
(1657, 242, 5, 'Thêm nho khô đã ráo nước, mận cắt nhỏ để ráo nước, muối và hạt tiêu cho vừa ăn. Đun nóng trong vài phút, sau đó bày ra đĩa đã hâm nóng và trang trí với những nhánh mùi tây lá dẹt.', NULL, '2026-05-15 14:39:52', '2026-05-15 14:39:52'),
(1658, 243, 1, 'Cho hành tây vào máy xay thực phẩm và xay cho đến khi thái nhỏ. Đun nóng dầu trong chảo lớn có đế dày, sau đó đậy nắp lại cho hành tây vào chiên, thỉnh thoảng đảo đều cho đến khi hành tây thật vàng và mềm. Thêm tỏi và gừng, sau đó chiên thêm 5 phút nữa.', NULL, '2026-05-15 14:39:54', '2026-05-15 14:39:54'),
(1659, 243, 2, 'Cho bột cà ri, tất cả gia vị và lá nguyệt quế vào chảo cùng với cà chua xay nhuyễn. Khuấy đều trên lửa khoảng 30 giây rồi cho thịt và 300ml nước vào. Khuấy đều, giảm lửa, sau đó thêm sữa chua.', NULL, '2026-05-15 14:39:54', '2026-05-15 14:39:54'),
(1660, 243, 3, 'Đậy nắp chảo, sau đó đun nhỏ lửa trong 40-60 phút cho đến khi thịt mềm và nước sốt đặc và đẹp mắt. Ăn kèm với rau mùi, cơm basmati hoặc cơm pilau.', NULL, '2026-05-15 14:39:54', '2026-05-15 14:39:54'),
(1661, 244, 1, 'Đun nóng dầu ô liu trong chảo có đáy dày rồi cho hành tây và cà rốt vào. Nấu trong 3-4 phút cho đến khi mềm.', NULL, '2026-05-15 14:39:57', '2026-05-15 14:39:57'),
(1662, 244, 2, 'Thêm thịt cừu thái hạt lựu và nâu khắp mặt. Khuấy tỏi và tất cả các loại gia vị và nấu thêm vài phút nữa hoặc cho đến khi mùi thơm tỏa ra.', NULL, '2026-05-15 14:39:57', '2026-05-15 14:39:57'),
(1663, 244, 3, 'Thêm mật ong và quả mơ, nghiền nát thành viên và đổ khoảng 500ml nước sôi hoặc đủ ngập thịt. Khuấy đều và đun sôi. Vặn lửa nhỏ, đậy nắp và nấu trong 1 giờ.', NULL, '2026-05-15 14:39:57', '2026-05-15 14:39:57'),
(1664, 244, 4, 'Đậy nắp và nấu thêm 30 phút nữa thì cho bí vào khuấy đều. Nấu thêm 20 – 30 phút nữa cho đến khi bí mềm và thịt cừu mềm. Ăn kèm với cơm hoặc couscous và rắc rau mùi tây và hạt thông, nếu dùng.', NULL, '2026-05-15 14:39:57', '2026-05-15 14:39:57'),
(1665, 245, 1, 'Ở đây dùng lá nho ngâm chua, bảo quản trong nước muối. Những chiếc lá nhỏ mỏng manh sẽ tốt hơn những chiếc lá lớn có nhiều lông, tuy nhiên, nếu chỉ dùng những chiếc lá lớn thì hãy cắt chúng thành khoảng 12 x 12 cm để không có quá nhiều lớp lá xung quanh nhân bánh. Và loại bỏ bất kỳ thân cây nào. Xả sạch lá đã bảo quản, ngâm trong nước sôi trong 10 phút rồi để khô trên khăn trước khi sử dụng.', NULL, '2026-05-15 14:40:01', '2026-05-15 14:40:01'),
(1666, 245, 2, 'Cơm basmati với bơ và hạt thông là món ăn kèm lý tưởng. Couscous cũng tuyệt vời. Phục vụ bốn.', NULL, '2026-05-15 14:40:01', '2026-05-15 14:40:01'),
(1667, 245, 3, 'Đầu tiên làm nhân. Cho tất cả nguyên liệu, trừ cà chua, vào tô. Cắt cà chua làm đôi, xay thô cho vào bát và bỏ vỏ. Thêm nửa muỗng cà phê muối và một ít hạt tiêu đen vào rồi khuấy đều. Để sang một bên hoặc trong tủ lạnh tối đa một ngày. Trước khi sử dụng, dùng tay bóp nhẹ và chắt hết nước chảy ra.', NULL, '2026-05-15 14:40:01', '2026-05-15 14:40:01'),
(1668, 245, 4, 'Để làm nước sốt, đun nóng dầu trong chảo vừa. Thêm gừng và tỏi, nấu trong một hoặc hai phút, chú ý không làm cháy chúng, sau đó thêm cà chua, nước cốt chanh và đường. Nêm, đun nhỏ lửa trong 20 phút.', NULL, '2026-05-15 14:40:01', '2026-05-15 14:40:01'),
(1669, 245, 5, 'Trong khi nước sốt đang sủi bọt, chuẩn bị lá nho. Dùng những chiếc lá rách hoặc gãy để lót đáy một cái chảo rộng và nặng. Cắt bỏ hết lá thì là, cắt dọc thành từng lát dày 0,5cm rồi trải lên đáy chảo cho kín.', NULL, '2026-05-15 14:40:01', '2026-05-15 14:40:01'),
(1670, 245, 6, 'Đặt một chiếc lá nho đã chuẩn bị sẵn (xem phần giới thiệu) lên bề mặt làm việc, mặt có gân hướng lên trên. Đặt hai thìa cà phê nhân ở gốc lá thành một dải dài 2cm x rộng 1cm. Gấp các cạnh của chiếc lá lên trên phần nhân, sau đó cuộn chặt từ dưới lên trên theo hình điếu xì gà. Đặt vào chảo, khâu lại và lặp lại với những chiếc lá còn lại, đặt chúng sát cạnh nhau theo đường thẳng hoặc hình tròn (thành hai lớp nếu cần).', NULL, '2026-05-15 14:40:01', '2026-05-15 14:40:01'),
(1671, 245, 7, 'Đổ nước sốt lên lá (và nếu cần, thêm nước vừa đủ). Đặt một cái đĩa lên trên, để cân lá xuống rồi đậy nắp lại. Đun sôi, giảm nhiệt và nấu trên lửa nhỏ trong 70 phút. Hầu hết chất lỏng sẽ bay hơi. Tắt bếp và để nguội một chút - tốt nhất nên dùng khi còn ấm. Khi phục vụ, hãy mang ra bàn trong chảo - trông rất tuyệt. Ăn một ít lá nho và lát thì là với cơm ấm. Múc nước cốt om lên trên và trang trí với rau mùi.', NULL, '2026-05-15 14:40:01', '2026-05-15 14:40:01'),
(1672, 246, 1, 'Đổ bulghar vào chảo, đổ nước vào và đun sôi trong 10 phút. Xả thật kỹ trong một cái rây, ép hết nước thừa.', NULL, '2026-05-15 14:40:03', '2026-05-15 14:40:03'),
(1673, 246, 2, 'Để làm món tzatziki, hãy ép và ép lấy nước từ dưa chuột, sau đó trộn vào sữa chua cùng với lá bạc hà cắt nhỏ và một chút muối.', NULL, '2026-05-15 14:40:03', '2026-05-15 14:40:03'),
(1674, 246, 3, 'Trộn bulghar vào thịt cừu với gia vị, tỏi (nếu dùng) và gia vị, sau đó tạo hình thành 4 chiếc bánh mì kẹp thịt. Quét một ít dầu rồi chiên hoặc nướng mỗi mặt khoảng 5 phút cho đến khi chín hẳn. Ăn kèm với bánh mì (nướng nếu bạn thích) với tzatziki, cà chua, hành tây và một ít lá bạc hà.', NULL, '2026-05-15 14:40:03', '2026-05-15 14:40:03'),
(1675, 247, 1, 'Làm nóng lò nướng ở 160C/quạt 140C/gas 3. Đun nóng một ít bơ hoặc bơ trong một đĩa thịt hầm lớn, nông, làm chín thịt cừu theo từng mẻ, gắp ra đĩa, sau đó lặp lại với thận.', NULL, '2026-05-15 14:40:06', '2026-05-15 14:40:06'),
(1676, 247, 2, 'Chiên hành tây và cà rốt trong chảo với độ nhỏ giọt nhỏ hơn một chút cho đến khi vàng. Rắc bột lên trên, để chín trong vài phút, rưới nước sốt Worcestershire lên, đổ nước kho vào, sau đó đun sôi. Cho thịt và lá nguyệt quế vào trộn đều rồi tắt bếp. Xếp khoai tây thái lát lên trên miếng thịt, sau đó rưới thêm một ít nước nhỏ giọt. Đậy nắp lại rồi cho vào lò nướng khoảng 1 tiếng rưỡi cho đến khi khoai tây chín.', NULL, '2026-05-15 14:40:06', '2026-05-15 14:40:06'),
(1677, 247, 3, 'Mở nắp, quét khoai tây với một chút nước nhỏ giọt, sau đó bật lò nướng để khoai tây chín vàng hoặc nướng chín trong 5-8 phút cho đến khi chín vàng.', NULL, '2026-05-15 14:40:06', '2026-05-15 14:40:06'),
(1678, 248, 1, 'Làm nóng chảo lớn và nướng hạt thì là trong vài phút, sau đó đặt sang một bên. Đun nóng dầu trong cùng một chảo rồi xào hành, tỏi, ớt, tiêu và một chút muối trong khoảng 8 phút cho đến khi không còn độ ẩm. Tắt bếp, cho hạt thì là đã nướng, hạt nhục đậu khấu (hoặc nhục đậu khấu) và rau mùi xay vào trộn đều. Để nguội.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1679, 248, 2, 'Trong một tô lớn, trộn thịt cừu băm, tiêu trắng, rau mùi tươi và hỗn hợp hành tây đã nguội với gia vị cho đến khi hòa quyện. Đặt sang một bên, đậy kín, cho vào tủ lạnh.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1680, 248, 3, 'Làm nóng lò nướng ở nhiệt độ 200C/400F/Gas 6 và bôi mỡ mỡ vào khuôn bánh hình tròn có đáy rời hoặc dạng lò xo có đường kính 20cm/8in.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1681, 248, 4, 'Để làm bánh ngọt, rây bột mì và muối vào tô lớn rồi tạo một cái giếng ở giữa.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1682, 248, 5, 'Cho sữa, mỡ lợn và 90ml/3fl oz nước vào nồi và đun nóng nhẹ. Khi mỡ lợn đã tan chảy, tăng lửa và đun sôi.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1683, 248, 6, 'Đổ nước sôi vào bột, dùng thìa gỗ trộn đều cho đến khi đủ nguội để cầm. Tập hợp lại thành một quả bóng.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1684, 248, 7, 'Phủi bột mì lên bề mặt làm việc và nhào bột nhanh chóng - bột sẽ mềm và ẩm. Dành một phần ba số bánh ngọt và lăn phần còn lại trên bề mặt đã rắc bột mì. Lót đĩa bánh với bánh ngọt, ấn thẳng vào các cạnh cho đến khi nó nhô lên trên mặt hộp thiếc.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1685, 248, 8, 'Thêm từng chút nhân vào khuôn đã lót bánh ngọt. Khi bạn đạt đến đỉnh, hãy tạo thành một đỉnh nhẹ. Cán mỏng phần bánh ngọt đã dành riêng và phủ lên trên chiếc bánh. Chụm các cạnh để bịt kín và cắt bớt phần thừa. Đục một lỗ trên mặt bánh rồi nhét một ống nhỏ làm từ lá nhôm vào để hơi nước thoát ra ngoài.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1686, 248, 9, 'Quét một ít lòng đỏ trứng đã đánh bông lên mặt bánh rồi nướng trong lò đã làm nóng trước trong 30 phút (đặt một cái khay lên kệ bên dưới để hứng những giọt nước nhỏ xuống). Sau đó giảm nhiệt độ xuống 160C/325F/Gas 3 và nấu thêm 1¼ giờ cho đến khi có màu vàng nâu. Để nguội hoàn toàn trước khi cho vào tủ lạnh trong hai giờ hoặc qua đêm.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1687, 248, 10, 'Dùng dao chạy quanh mép bánh, lấy ra khỏi khuôn và dùng kèm tương ớt, salad hoặc dưa chua.', NULL, '2026-05-15 14:40:10', '2026-05-15 14:40:10'),
(1688, 249, 1, 'Đun nóng một thìa dầu trong chảo xào lớn có nắp đậy. Thêm các miếng xúc xích vào và chiên trên lửa vừa cao trong 10 phút, khuấy đều cho đến khi có màu vàng nâu. Chuyển xúc xích ra đĩa, sau đó cho hành tây và thì là vào chảo nóng xào trong 15 phút, thỉnh thoảng đảo đều cho đến khi mềm và có màu caramen; nếu chảo hơi khô, hãy thêm một thìa cà phê dầu. Khuấy ớt bột, tỏi và một nửa hạt thì là, chiên thêm hai phút, sau đó đổ rượu vào và đun sôi trong 30 giây, giảm còn một nửa. Cho cà chua, đường, 100ml nước, xúc xích xào và nửa thìa muối vào, đậy nắp đun nhỏ lửa trong 30 phút; mở nắp sau 10 phút và nấu cho đến khi nước sốt đặc và đậm đà. Tắt bếp, khuấy đều ô liu và hạt thì là còn lại rồi đặt sang một bên cho đến khi bạn sẵn sàng dùng.', NULL, '2026-05-15 14:40:12', '2026-05-15 14:40:12'),
(1689, 249, 2, 'Đun sôi một nồi nước muối lớn, cho mì ống vào và nấu trong 12-14 phút (hoặc theo hướng dẫn trên gói) cho đến khi chín. Trong khi đó, hâm nóng lại nước sốt. Xả sạch mì ống, cho vào nồi, cho một thìa dầu vào đảo đều rồi chia ra các bát.', NULL, '2026-05-15 14:40:12', '2026-05-15 14:40:12'),
(1690, 249, 3, 'Cho tất cả nguyên liệu pesto trừ húng quế vào tô nhỏ của máy xay thực phẩm. Thêm một thìa nước và blitz để tạo thành hỗn hợp sệt. Thêm húng quế vào, sau đó xay nhuyễn cho đến khi hòa quyện (món pesto có kết cấu ngon hơn nhiều nếu húng quế không được trộn quá kỹ).', NULL, '2026-05-15 14:40:12', '2026-05-15 14:40:12'),
(1691, 249, 4, 'Rưới lên miếng ragù và phủ một thìa pesto lên trên. Kết thúc bằng việc rắc lá thì là xắt nhỏ, nếu có, và dùng ngay.', NULL, '2026-05-15 14:40:12', '2026-05-15 14:40:12'),
(1693, 250, 1, 'Cho thịt cừu vào túi đựng thức ăn lớn cùng với toàn bộ nước cốt và ướp qua đêm.', NULL, '2026-05-15 14:40:17', '2026-05-16 12:35:33'),
(1695, 250, 2, 'Ngày hôm sau, lấy thịt cừu ra khỏi tủ lạnh 1 giờ trước khi bạn muốn nấu. Làm nóng lò ở mức quạt/gas 220C/200C 7. Lấy thịt cừu ra khỏi nước ướp (dự trữ nước ướp còn lại) và lau khô. Xoa với một nửa lượng dầu và nướng trong 15-20 phút cho đến khi chín vàng. Lấy thịt cừu ra và giảm nhiệt độ lò xuống 160C/140C quạt/gas 3.', NULL, '2026-05-15 14:40:17', '2026-05-16 12:35:33'),
(1697, 250, 3, 'Trộn vỏ, dầu còn lại, mật ong, gia vị và tỏi với nhiều gia vị. Đặt một tờ giấy nướng lớn lên một tờ giấy bạc lớn. Đặt chân cừu lên trên, thoa hỗn hợp lên khắp người và kéo các cạnh của giấy bạc lên. Rưới nước xốt vào đế và vò giấy bạc để bịt kín.', NULL, '2026-05-15 14:40:17', '2026-05-16 12:35:33'),
(1699, 250, 4, 'Nướng trong 4 giờ, cho đến khi rất mềm. Nghỉ ngơi, vẫn quấn trong 30 phút. Mở gói và phục vụ với nước trái cây.', NULL, '2026-05-15 14:40:17', '2026-05-16 12:35:33'),
(1701, 251, 1, 'Để làm hỗn hợp gia vị, trộn tất cả nguyên liệu lại với nhau với một nhúm muối lớn. Dùng dao sắc chém khắp vai cừu và chà xát. Nếu có thời gian, hãy ướp trong tối đa 24 giờ, nhưng điều này không cần thiết.', NULL, '2026-05-15 14:40:20', '2026-05-16 12:35:33'),
(1703, 251, 2, 'Làm nóng lò nướng ở mức quạt/khí 150C/130C 2. Đun nóng dầu trong đĩa thịt hầm lớn chống cháy hoặc hộp nướng trên lửa vừa cao, thêm hành tây, cà rốt và tỏi vào rồi đun nhỏ lửa trong 5 phút cho đến khi hành tây và cà rốt mềm. Đổ nước kho vào, sau đó đun sôi. Nhúng thịt cừu vào chảo và đậy nắp, sau đó chuyển vào lò nướng và nướng trong 2 giờ.', NULL, '2026-05-15 14:40:20', '2026-05-16 12:35:33'),
(1705, 251, 3, 'Khám phá và chuyển thịt cừu vào đĩa bằng kẹp. Khuấy đậu, ớt và ô liu với nước luộc trong chảo, đặt thịt cừu lên trên rồi cho vào lò nướng, không đậy nắp, trong 1 giờ 30 phút cho đến khi thịt cừu chín. Chuyển thịt cừu sang thớt và dùng hai chiếc nĩa xé nhỏ. Khuấy mùi tây qua đậu om trước khi dùng.', NULL, '2026-05-15 14:40:20', '2026-05-16 12:35:33'),
(1706, 252, 1, 'Làm nóng lò ở mức quạt/khí 180C/160C 4. Cắt bỏ phần ngọn của cà chua và để dành. Dùng thìa cà phê múc phần lớn cùi, cẩn thận để không làm rách vỏ. Cắt nhỏ bã và giữ lại nước trái cây. Rắc một ít đường vào bên trong cà chua để khử bớt axit rồi đặt cà chua lên khay nướng.', NULL, '2026-05-15 14:40:23', '2026-05-15 14:40:23'),
(1707, 252, 2, 'Đun nóng 2 muỗng canh dầu ô liu trong chảo lớn, cho hành tây và tỏi vào, sau đó xào nhẹ khoảng 10 phút cho đến khi mềm nhưng không có màu. Thêm thịt cừu, quế và cà chua xay nhuyễn vào, vặn lửa lớn rồi chiên cho đến khi thịt chín vàng. Thêm bột cà chua và nước ép, gạo và nước kho. Mùa một cách hào phóng. Đun sôi, sau đó đun nhỏ lửa trong 15 phút hoặc cho đến khi gạo mềm và chất lỏng đã được hấp thụ. Đặt sang một bên để nguội một chút, sau đó khuấy đều các loại thảo mộc.', NULL, '2026-05-15 14:40:23', '2026-05-15 14:40:23'),
(1708, 252, 3, 'Nhồi cà chua đến miệng, đậy nắp cà chua lại, rưới thêm 2 thìa dầu ô liu, rưới 3 thìa nước vào khay rồi nướng trong 35 phút. Ăn kèm salad và bánh mì giòn, nóng hoặc lạnh.', NULL, '2026-05-15 14:40:23', '2026-05-15 14:40:23'),
(1709, 253, 1, 'Cho thịt cừu vào nồi và nấu trên lửa cao. Khi chín vàng, tắt bếp và đặt sang một bên.', NULL, '2026-05-15 14:40:27', '2026-05-15 14:40:27'),
(1710, 253, 2, 'Giữ một thìa mỡ trong nồi và loại bỏ phần còn lại. Giảm lửa vừa rồi cho tỏi, hành tây và rau bina vào nấu cho đến khi hành tây trong và rau bina héo hoặc khoảng 5 phút.', NULL, '2026-05-15 14:40:27', '2026-05-15 14:40:27'),
(1711, 253, 3, 'Cho thịt cừu trở lại hầm với hỗn hợp hành tây-rau bina, thêm cà chua xay nhuyễn, thì là, harissa, thịt gà, đậu xanh, nước cốt chanh, muối và hạt tiêu vào chảo. Đun sôi trên lửa nhỏ trong khoảng 20 phút.', NULL, '2026-05-15 14:40:27', '2026-05-15 14:40:27'),
(1712, 253, 4, 'Thêm mì ống và nấu trong 15 phút hoặc cho đến khi mì ống chín.', NULL, '2026-05-15 14:40:27', '2026-05-15 14:40:27'),
(1714, 254, 1, 'Chiên khô hạt thông hoặc hạnh nhân trong chảo lớn cho đến khi nướng nhẹ, sau đó cho ra đĩa. Thêm dầu vào chảo, sau đó xào hành tây và quế với nhau cho đến khi bắt đầu chuyển sang màu vàng. Tăng lửa, cho thịt cừu vào xào cho đến khi thịt đổi màu thì cho cơm vào nấu trong 1 phút, khuấy đều.', NULL, '2026-05-15 14:40:29', '2026-05-16 12:35:33'),
(1716, 254, 2, 'Đổ 500ml nước sôi vào, vo viên, cho mơ vào, nêm gia vị cho vừa ăn. Giảm nhiệt, đậy nắp và đun nhỏ lửa trong 12 phút cho đến khi gạo mềm và nước luộc đã ngấm. Cho hạt thông và bạc hà vào rồi thưởng thức.', NULL, '2026-05-15 14:40:29', '2026-05-16 12:35:33'),
(1718, 255, 1, 'Làm nóng vỉ nướng ở mức cao. Nêm thịt cừu, sau đó nướng mỗi mặt trong 2 phút cho đến khi chín vàng nhưng vẫn rất tái. Trong khi đó, trộn gia vị, lá oregano và một nửa lá bạc hà vào một trong các hộp sữa chua, phết hỗn hợp này lên thịt cừu, sau đó quay lại nướng thêm 2-3 phút nữa hoặc cho đến khi sữa chua phồng rộp và thịt chín theo ý thích của bạn.', NULL, '2026-05-15 14:40:31', '2026-05-16 12:35:33'),
(1720, 255, 2, 'Để thịt nằm trên thớt trong vài phút trong khi nướng bánh pittas, cắt nhỏ rau diếp và cắt mỏng hành tím. Khuấy phần bạc hà còn lại vào bồn sữa chua thứ hai. Cắt lát dày thịt và nhồi vào bánh mì pitta cùng với salad và sữa chua bạc hà. Vắt thêm nước cốt chanh trước khi nhét vào, nếu bạn thích.', NULL, '2026-05-15 14:40:31', '2026-05-16 12:35:33'),
(1722, 256, 1, 'Làm nóng lò nướng ở nhiệt độ quạt/khí 160C/140C 3. Đun nóng 1 muỗng canh dầu trong nồi có đáy dày, nêm gia vị cho các chân gà, sau đó chiên vàng 2 mặt mỗi lần, thêm lượng dầu còn lại cho mẻ thứ hai. Lấy thịt cừu ra và thêm hành tây. Chiên chúng khá nhanh, khoảng 30 giây, thêm gừng, tỏi và ớt băm nhỏ, sau đó giảm lửa và nấu trong 1 phút. Thêm 1 thìa đường vào, khuấy đều rồi cho hoa hồi, sả, nước kho, xay nhuyễn và gia vị vào. Đun sôi.', NULL, '2026-05-15 14:40:33', '2026-05-16 12:35:33'),
(1724, 256, 2, 'Đậy nắp và cho vào lò nướng khoảng 1 tiếng rưỡi, sau đó cho khoai lang vào nấu thêm 1 giờ nữa. Thịt cừu phải mềm hoàn toàn và gần như rơi ra khỏi xương. Khuấy nước mắm, nước cốt chanh và 1 thìa đường để tăng hương vị, sau đó rắc bạc hà, húng quế và ớt thái lát vào để thưởng thức.', NULL, '2026-05-15 14:40:33', '2026-05-16 12:35:33'),
(1725, 257, 1, 'Đun chảy mỡ trong chảo chống dính, để mỡ nóng và đẹp, sau đó cho thịt xông khói vào. Khi nó bắt đầu chuyển sang màu nâu, thêm hành và tỏi. Tiếp theo, thêm mầm hoặc bắp cải thái lát vào và để hơi màu. Tất cả điều này sẽ mất 5-6 phút.', NULL, '2026-05-15 14:40:36', '2026-05-15 14:40:36'),
(1726, 257, 2, 'Tiếp theo, thêm khoai tây. Trộn mọi thứ lại với nhau trong chảo và ấn xuống để hỗn hợp phủ kín đáy chảo - để hỗn hợp bám nhẹ vào đáy chảo trước khi lật lại và làm lại như vậy. Chính những miếng khoai tây dính vào chảo sẽ xác định thuật ngữ \'bong bóng và tiếng kêu\', vì vậy hãy dũng cảm và để hỗn hợp có màu. Cắt thành nêm và phục vụ.', NULL, '2026-05-15 14:40:36', '2026-05-15 14:40:36'),
(1728, 258, 1, 'Làm nóng lò ở nhiệt độ 200C/180C/gas 6. Đun nóng một nửa dầu trong chảo sâu lòng hoặc chảo xào (hoặc đĩa hầm nông) có đường kính khoảng 30cm. Ở nhiệt độ cao, nhuộm các lát thịt ba chỉ ở mỗi bên thành nhiều mẻ, sau đó chuyển sang tô. Thêm lượng dầu còn lại vào chảo và giảm lửa ở mức vừa, sau đó cho bánh pudding đen và thịt xông khói vào chiên trong vài phút. Loại bỏ bằng một cái muỗng có rãnh. Chiên hành tây và ớt trong khoảng 10 phút cho đến khi mềm và có màu vàng nhạt, sau đó cho cà chua vào nấu cho đến khi mềm. Thêm tỏi, ớt bột hun khói và ớt bột vào nấu thêm 2 phút nữa, sau đó cho thịt lợn, bánh pudding đen và thịt xông khói vào chảo. Thêm đậu, nước luộc và bất kỳ loại thảo mộc nào bạn đang sử dụng vào rồi đun sôi mọi thứ.', NULL, '2026-05-15 14:40:40', '2026-05-16 12:35:33'),
(1730, 258, 2, 'Rắc cơm xung quanh bụng lợn, đẩy nó xuống bên dưới nước luộc. Đun sôi lại nước kho, nêm gia vị vừa đủ rồi chuyển vào lò nướng (không đậy nắp). Nấu trong 20 phút mà không khuấy, sau đó kiểm tra xem cơm chín như thế nào. Gạo phải mềm và nước ngấm. Nếu chưa chín, hãy cho bánh vào lò nướng thêm 5 phút nữa rồi kiểm tra lại. Nêm nếm gia vị.', NULL, '2026-05-15 14:40:40', '2026-05-16 12:35:33'),
(1732, 258, 3, 'Vắt nước cốt chanh lên trên và rưới lên một ít dầu ô liu nguyên chất ngay trước khi dùng, nếu bạn thích.', NULL, '2026-05-15 14:40:40', '2026-05-16 12:35:33'),
(1734, 259, 1, 'Làm nóng lò ở 200C/quạt 180C/gas. Trộn đường vào hỗn hợp bánh mì trong tô lớn, sau đó thêm nước theo hướng dẫn trên bao bì. Dùng thìa gỗ trộn bột lại, sau đó nhào trên bề mặt đã rắc chút bột mì trong 5 phút cho đến khi mịn. Cho vào tô lớn, phủ màng dính dầu rồi để ở nơi ấm áp cho đến khi nở gấp đôi.', NULL, '2026-05-15 14:40:42', '2026-05-16 12:35:33'),
(1736, 259, 2, 'Trong khi đó, làm nóng dầu trong chảo, sau đó chiên thịt xông khói cho đến khi giòn, khoảng 5 phút. Thêm gừng và tỏi vào xào trong 1 phút cho đến khi mềm, sau đó cho đậu nành, mật ong và cà chua xay nhuyễn vào khuấy đều. Có thể thực hiện trước 3 ngày.', NULL, '2026-05-15 14:40:42', '2026-05-16 12:35:33'),
(1738, 259, 3, 'Đổ bột ra và nhào nhẹ, sau đó vo thành 12 viên có kích thước đều nhau. Dùng tay ấn dẹt, sau đó cho một viên nhân có kích thước bằng thìa cà phê vào giữa. Kéo bột lên và kẹp lại như một cái ví, sau đó lật bánh lại và đặt lên khay nướng lớn. Dùng màng bọc dầu bọc lại và để bột nở khoảng 30 phút cho đến khi bột có cảm giác dẻo. Quét trứng lên và nướng trong 20 phút cho đến khi vàng. Ăn nóng với nước chấm. Có thể đông lạnh sau lần ủ thứ hai trong tối đa 1 tháng hoặc nướng trước một ngày và hâm nóng lại.', NULL, '2026-05-15 14:40:42', '2026-05-16 12:35:33'),
(1739, 260, 1, 'Làm nóng lò ở 450 độ. Rửa và lau khô tất cả sản phẩm. Cắt khoai lang thành miếng dày ½ inch. Đổ một ít dầu, muối và hạt tiêu lên khay nướng. Nướng cho đến khi chín vàng và mềm, khoảng 20-25 phút.', NULL, '2026-05-15 14:40:45', '2026-05-15 14:40:45'),
(1740, 260, 2, 'Trong khi đó, cắt đôi và gọt vỏ hành tây. Cắt càng mỏng càng tốt cho đến khi bạn còn ¼ cốc (½ cốc cho 4 phần ăn); thái nhỏ hành tây còn lại. Bóc vỏ và băm nhuyễn tỏi. Vôi giảm một nửa; vắt nước trái cây vào một cái bát nhỏ. Bánh mì cắt đôi. Thêm 1 muỗng canh bơ (2 muỗng canh cho 4 người) vào một bát nhỏ riêng biệt dùng được cho lò vi sóng; lò vi sóng cho đến khi tan chảy, 30 giây. Chải lên các mặt đã cắt của bánh.', NULL, '2026-05-15 14:40:45', '2026-05-15 14:40:45'),
(1741, 260, 3, 'Để tô với nước cốt chanh, thêm hành tây thái lát, ¼ thìa cà phê đường (½ thìa cho 4 phần ăn) và một chút muối. Khuấy để kết hợp; dành riêng để ngâm nhanh.', NULL, '2026-05-15 14:40:45', '2026-05-15 14:40:45'),
(1742, 260, 4, 'Đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm hành tây xắt nhỏ và nêm muối và hạt tiêu. Nấu, khuấy đều cho đến khi mềm, 4-5 phút. Thêm tỏi và nấu cho đến khi có mùi thơm, thêm 30 giây nữa. Thêm thịt lợn và nêm muối và hạt tiêu. Nấu, chia thịt thành từng miếng cho đến khi chín vàng, khoảng 4-6 phút.', NULL, '2026-05-15 14:40:45', '2026-05-15 14:40:45'),
(1743, 260, 5, 'Trong khi nấu thịt lợn, trong tô nhỏ thứ ba, trộn nước sốt BBQ, nước ngâm từ hành tây, 3 muỗng canh tương cà (6 muỗng canh cho 4 phần ăn), ½ muỗng cà phê đường (1 muỗng cà phê cho 4 người) và ¼ cốc nước (⅓ cốc cho 4 người). Sau khi thịt lợn chín, thêm hỗn hợp sốt BBQ vào chảo. Nấu, khuấy đều cho đến khi nước sốt đặc lại, 2-3 phút. Hương vị và nêm muối và hạt tiêu.', NULL, '2026-05-15 14:40:45', '2026-05-15 14:40:45'),
(1744, 260, 6, 'Trong khi đó, nướng bánh trong lò nướng hoặc lò nướng bánh mì cho đến khi vàng, khoảng 3-5 phút. Chia bánh mì nướng vào các đĩa và đổ đầy thịt lợn BBQ tùy thích. Đổ hành ngâm và nước sốt nóng lên trên. Ăn kèm với khoai lang nêm ở bên cạnh.', NULL, '2026-05-15 14:40:45', '2026-05-15 14:40:45'),
(1745, 261, 1, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C).', NULL, '2026-05-15 14:40:47', '2026-05-15 14:40:47'),
(1746, 261, 2, 'Đun nóng nồi lớn trên lửa vừa. Thêm thịt xông khói và kielbasa; nấu và khuấy cho đến khi thịt xông khói chuyển sang màu mỡ và xúc xích có màu nâu nhạt. Dùng thìa có rãnh để lấy thịt và chuyển sang nồi lớn hoặc lò nướng kiểu Hà Lan.', NULL, '2026-05-15 14:40:47', '2026-05-15 14:40:47'),
(1747, 261, 3, 'Phủ nhẹ các khối thịt lợn bằng bột mì và chiên chúng trong nước sốt thịt xông khói trên lửa vừa cao cho đến khi có màu vàng nâu. Dùng thìa có rãnh để chuyển thịt lợn vào nồi. Thêm tỏi, hành tây, cà rốt, nấm tươi, bắp cải và dưa cải bắp. Giảm nhiệt xuống mức trung bình; nấu và khuấy cho đến khi cà rốt mềm, khoảng 10 phút. Đừng để rau có màu nâu.', NULL, '2026-05-15 14:40:47', '2026-05-15 14:40:47'),
(1748, 261, 4, 'Khử men chảo bằng cách đổ rượu vang đỏ vào và khuấy đều để loại bỏ hết thức ăn và bột mì dính dưới đáy. Nêm lá nguyệt quế, húng quế, kinh giới, ớt bột, muối, tiêu, hạt caraway và ớt cayenne; nấu trong 1 phút.', NULL, '2026-05-15 14:40:47', '2026-05-15 14:40:47'),
(1749, 261, 5, 'Trộn nấm khô, sốt ớt cay, sốt Worcestershire, thịt bò kho, bột cà chua và cà chua. Đun nóng cho đến khi sôi. Đổ rau và tất cả chất lỏng vào đĩa thịt hầm cùng với thịt. Đậy nắp.', NULL, '2026-05-15 14:40:47', '2026-05-15 14:40:47'),
(1750, 261, 6, 'Nướng trong lò làm nóng trước từ 2 tiếng rưỡi đến 3 giờ, cho đến khi thịt rất mềm.', NULL, '2026-05-15 14:40:47', '2026-05-15 14:40:47'),
(1751, 262, 1, 'BƯỚC 1', NULL, '2026-05-15 14:40:52', '2026-05-15 14:40:52'),
(1752, 262, 2, 'Trước khi bắt đầu, hãy đặt lò nướng ở mức thấp nhất để sẵn sàng giữ ấm mọi thứ. Gọt vỏ khoai tây, xay 2 củ rồi đặt sang một bên. Cắt 2 cái còn lại thành từng miếng lớn, sau đó đun sôi trong 10-15 phút hoặc cho đến khi mềm. Trong khi đó, dùng khăn sạch vắt càng nhiều chất lỏng từ khoai tây nghiền càng tốt. Nghiền nhuyễn khoai tây luộc rồi trộn với khoai tây bào sợi, hành lá và bột mì.', NULL, '2026-05-15 14:40:52', '2026-05-15 14:40:52'),
(1753, 262, 3, 'BƯỚC 2', NULL, '2026-05-15 14:40:52', '2026-05-15 14:40:52'),
(1754, 262, 4, 'Đánh lòng trắng trứng trong một tô lớn cho đến khi có chóp mềm. Cho bơ sữa vào, sau đó thêm bicarbonate soda. Gấp vào hỗn hợp khoai tây.', NULL, '2026-05-15 14:40:52', '2026-05-15 14:40:52'),
(1755, 262, 5, 'BƯỚC 3', NULL, '2026-05-15 14:40:52', '2026-05-15 14:40:52'),
(1756, 262, 6, 'Đun nóng chảo chống dính lớn trên lửa vừa, sau đó thêm 1 muỗng canh bơ và một ít dầu. Thả 3-4 thìa hỗn hợp khoai tây vào chảo, sau đó nấu nhẹ mỗi mặt trong 3-5 phút cho đến khi vàng và giòn. Giữ ấm trên đĩa trong lò trong khi nấu mẻ tiếp theo, cho thêm bơ và dầu vào chảo trước khi làm. Bạn sẽ nhận được 16 chiếc hộp cỡ nhỏ từ hỗn hợp. Có thể làm vào ngày hôm trước, để ráo nước trên giấy ăn, sau đó hâm nóng trong lò ở nhiệt độ thấp trong 20 phút.', NULL, '2026-05-15 14:40:52', '2026-05-15 14:40:52'),
(1757, 262, 7, 'BƯỚC 4', NULL, '2026-05-15 14:40:52', '2026-05-15 14:40:52'),
(1758, 262, 8, 'Làm nóng lò nướng ở mức vừa và cho cà chua vào chảo có đáy dày. Thêm một ít bơ và một ít dầu vào, sau đó chiên khoảng 5 phút cho đến khi chín mềm. Nướng thịt xông khói rồi bày ra đĩa, dùng nóng. Xếp hộp, thịt xông khói và trứng lên rồi dọn kèm cà chua lên một bên.', NULL, '2026-05-15 14:40:52', '2026-05-15 14:40:52'),
(1759, 263, 1, '1. Chuẩn bị bột', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1760, 263, 2, 'Nghiền mịn khoai tây bằng dụng cụ xay cầm tay hoặc máy xay thực phẩm. Đặt khoai tây nghiền vào tô và trộn chúng với bột mì, trứng và muối cho đến khi tạo thành một khối bột dính. Độ đặc phải dày nhưng dẻo.', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1761, 263, 3, '2. Nấu bánh bao', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1762, 263, 4, 'Đun sôi một nồi nước muối lớn. Sử dụng máy làm halušky (tương tự như máy làm spaetzle), ấn bột trực tiếp vào nước sôi. Nếu không có, bạn có thể dùng thớt nghiêng và dao cạo từng miếng bột nhỏ xuống nước.', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1763, 263, 5, 'Nấu bánh bao cho đến khi nổi lên mặt nước, thường trong vòng 2-3 phút. Dùng thìa có rãnh múc chúng ra và đặt vào một cái tô lớn.', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1764, 263, 6, '3. Chuẩn bị lớp phủ bên trên', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1765, 263, 7, 'Cắt thịt xông khói thành từng miếng nhỏ và chiên trong chảo trên lửa vừa cho đến khi giòn. Nếu sử dụng sản phẩm thay thế bryndza, hãy trộn feta vụn với một ít kem chua để mô phỏng hương vị thơm của phô mai cừu truyền thống của Slovakia.', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1766, 263, 8, '4. Lắp ráp món ăn', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1767, 263, 9, 'Trộn bánh bao đã nấu chín với phô mai bryndza (hoặc phô mai thay thế) cho đến khi chúng phủ đều và mịn như kem. Phủ thịt xông khói giòn và nước xốt lên trên. Trang trí với hẹ hoặc rau mùi tây cắt nhỏ để tăng thêm màu sắc và hương vị.', NULL, '2026-05-15 14:40:55', '2026-05-15 14:40:55'),
(1768, 264, 1, 'Làm nóng lò ở nhiệt độ 200 độ C.', NULL, '2026-05-15 14:40:58', '2026-05-15 14:40:58'),
(1769, 264, 2, 'Cắt thịt xông khói hoặc chorizo ​​thành miếng vừa và ớt bột thành dải.', NULL, '2026-05-15 14:40:58', '2026-05-15 14:40:58'),
(1770, 264, 3, 'Rưới một ít nước sốt cà chua và phô mai mozzarella lên từng phần sắn.', NULL, '2026-05-15 14:40:58', '2026-05-15 14:40:58'),
(1771, 264, 4, 'Thêm thịt xông khói hoặc chorizo, ngô, giăm bông gà tây, một ít ô liu và ớt bột.', NULL, '2026-05-15 14:40:58', '2026-05-15 14:40:58'),
(1772, 264, 5, 'Nướng trong 7 đến 10 phút.', NULL, '2026-05-15 14:40:58', '2026-05-15 14:40:58'),
(1773, 264, 6, 'Lấy ra khỏi lò và thưởng thức.', NULL, '2026-05-15 14:40:58', '2026-05-15 14:40:58'),
(1775, 265, 1, 'Đun nóng dầu trong chảo lớn, sau đó nhẹ nhàng xào hành tây trong 3-4 phút cho đến khi hành mềm. Khuấy cà rốt, cần tây, húng tây và lá nguyệt quế. Nêm gia vị, sau đó nấu trong 2-3 phút, thỉnh thoảng khuấy. Thêm tỏi, chorizo, quế và ớt bột hun khói. Nhẹ nhàng chiên cho đến khi rau mềm và chorizo ​​bắt đầu tiết ra dầu và giòn.', NULL, '2026-05-15 14:41:01', '2026-05-16 12:35:33'),
(1777, 265, 2, 'Khuấy đậu xanh, giấm và 150ml nước, sau đó đun nhỏ lửa trong 1-2 phút cho đến khi đậu xanh nóng lên. Thêm rau chân vịt vào, sau đó đảo đều đậu xanh cho đến khi đậu hơi héo. Tắt bếp, nêm nếm vừa ăn rồi dùng nóng với bánh mì giòn.', NULL, '2026-05-15 14:41:01', '2026-05-16 12:35:33'),
(1786, 267, 1, 'Đặt một chiếc chảo vừa lên lửa và cho cà chua vào, tiếp theo là một lon nước. Trong khi cà chua đang nóng, nhanh chóng cắt chorizo ​​thành từng miếng nhỏ (bỏ hết vỏ) và cắt nhỏ bắp cải.', NULL, '2026-05-15 14:41:05', '2026-05-16 12:35:33'),
(1788, 267, 2, 'Cho xúc xích và bắp cải vào chảo cùng với ớt và đậu xanh, sau đó nghiền thành khối nước dùng. Khuấy đều, đậy nắp và để sôi ở lửa lớn trong 6 phút hoặc cho đến khi bắp cải mềm. Múc ra bát ăn với bánh mì giòn hoặc bánh mì tỏi.', NULL, '2026-05-15 14:41:05', '2026-05-16 12:35:33'),
(1790, 268, 1, 'Nấu khoai tây trong chảo lớn có nước muối sôi trong 12 phút, thêm trứng sau 6 phút và đậu vào trong 2 phút cuối cùng. Xả hết mọi thứ và làm nguội trứng dưới vòi nước lạnh.', NULL, '2026-05-15 14:41:08', '2026-05-16 12:35:33'),
(1792, 268, 2, 'Trong khi đó, chiên các lát chorizo ​​trong 1-2 phút cho đến khi bắt đầu giòn. Dùng thìa có rãnh lấy ra khỏi chảo và đặt sang một bên, để lại dầu từ chorizo ​​trong chảo. Thêm tỏi vào chảo và nấu nhẹ trong 1 phút.', NULL, '2026-05-15 14:41:08', '2026-05-16 12:35:33'),
(1794, 268, 3, 'Nhấc chảo ra khỏi bếp, cho giấm và mùi tây vào khuấy đều, sau đó trộn khoai tây, đậu, chorizo và gia vị. Trứng bóc vỏ, cắt làm tư và thêm vào món salad.', NULL, '2026-05-15 14:41:08', '2026-05-16 12:35:33'),
(1796, 269, 1, 'Cho cà chua vào tô cùng với hành tây và húng tây. Nêm, sau đó rưới giấm và dầu lên. Hãy để hương vị hòa quyện trong khi bạn nấu chorizo.', NULL, '2026-05-15 14:41:10', '2026-05-16 12:35:33'),
(1798, 269, 2, 'Trong chảo khô, nóng, chiên các lát chorizo cho đến khi chín vàng cả hai mặt. Phục vụ cà chua với chorizo ​​​​chiên, rưới một ít dầu từ chảo.', NULL, '2026-05-15 14:41:10', '2026-05-16 12:35:33'),
(1800, 270, 1, 'Luộc khoai tây trong nước sôi khoảng 8-10 phút hoặc cho đến khi mềm. Xả và để khô bằng hơi nước. Đun nóng dầu trong chảo trứng tráng, thêm chorizo ​​và nấu trong 2 phút. Thêm khoai tây và nấu thêm 5 phút nữa cho đến khi khoai tây bắt đầu giòn. Múc hết nội dung trong chảo ra, lau chảo và nấu món trứng tráng 2 hoặc 3 quả trong cùng một chảo. Khi gần chín, rải đều với chorizo ​​và khoai tây, rau mùi tây và phô mai. Gấp món trứng tráng vào chảo và nấu thêm 1 phút nữa để làm tan chảy phô mai.', NULL, '2026-05-15 14:41:13', '2026-05-16 12:35:34'),
(1801, 271, 1, 'BƯỚC 1', NULL, '2026-05-15 14:41:16', '2026-05-15 14:41:16'),
(1802, 271, 2, 'Đun nóng bơ trong chảo cho đến khi nóng hổi, sau đó chiên thịt lợn trong 2-3 phút mỗi mặt cho đến khi chín vàng. Lấy ra khỏi chảo.', NULL, '2026-05-15 14:41:16', '2026-05-15 14:41:16'),
(1803, 271, 3, 'BƯỚC 2', NULL, '2026-05-15 14:41:16', '2026-05-15 14:41:16'),
(1804, 271, 4, 'Cho thịt xông khói, cà rốt, khoai tây và thịt Thụy Điển vào chảo, sau đó chiên nhẹ cho đến khi có màu hơi nhạt. Khuấy bắp cải, đặt miếng sườn lên trên, thêm lá nguyệt quế, sau đó rưới rượu táo lên và kho. Đậy nắp chảo, sau đó để mọi thứ sôi nhẹ trong 20 phút cho đến khi thịt lợn chín và rau mềm.', NULL, '2026-05-15 14:41:16', '2026-05-15 14:41:16'),
(1805, 271, 5, 'BƯỚC 3', NULL, '2026-05-15 14:41:16', '2026-05-15 14:41:16'),
(1806, 271, 6, 'Phục vụ tại bàn được múc thẳng từ đĩa.', NULL, '2026-05-15 14:41:16', '2026-05-15 14:41:16'),
(1807, 272, 1, 'Làm nóng lò ở nhiệt độ 350°. Loại bỏ phần cuống của một bó cải xoăn Tuscan và xé lá thành từng miếng 1 inch (mù tạt xanh, cải rổ, rau bina và củ cải cũng rất tuyệt). Cắt thô nửa đầu bắp cải xanh. Cho các loại rau xanh vào một đĩa nướng lớn và thêm 4 tép tỏi thái lát mỏng. Thêm một ít hành tây thái lát và nấm đông cô vào thời điểm này là tùy chọn, nhưng rất khuyến khích (Tôi sẽ xào hành và nấm trong đĩa nướng gang ngay trên bếp trước khi thêm vào phủ rau xanh với một ít dầu ô liu và đổ ½ cốc nước luộc gà hoặc nước dùng lên trên mọi thứ. Dùng giấy bạc đậy đĩa lại và nướng cho đến khi rau héo, khoảng 15 phút. Lấy giấy bạc ra và nêm muối và hạt tiêu.', NULL, '2026-05-15 14:41:20', '2026-05-15 14:41:20'),
(1808, 272, 2, 'Trong khi đó, đun nóng một ít dầu ô liu trong chảo lớn trên lửa vừa cao. Dùng nĩa đâm bốn chiếc xúc xích Ý ngọt và nấu cho đến khi chín vàng các mặt và chín đều trong vòng 10 đến 12 phút. Khi rau đã chín, hãy cắt xúc xích và trộn vào rau với một chút giấm yêu thích của bạn (tôi thích rượu sherry hoặc rượu vang đỏ).', NULL, '2026-05-15 14:41:20', '2026-05-15 14:41:20'),
(1809, 273, 1, '1. Chuẩn bị hỗn hợp bánh mì', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1810, 273, 2, 'Ngâm các lát bánh mì trong sữa hoặc nước cho đến khi mềm.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1811, 273, 3, 'Bóp chất lỏng dư thừa và nghiền thành những mảnh vụn nhỏ.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1812, 273, 4, '2. Trộn nguyên liệu', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1813, 273, 5, 'Trong một tô lớn, trộn thịt xay, hành tây xắt nhỏ, tỏi, bánh mì ngâm, trứng và gia vị.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1814, 273, 6, 'Trộn đều cho đến khi kết hợp đồng đều.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1815, 273, 7, '3. Tạo hình miếng chả', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1816, 273, 8, 'Lấy các phần hỗn hợp và nặn chúng thành những miếng chả cỡ lòng bàn tay.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1817, 273, 9, 'Làm phẳng một chút để giúp nấu ăn đều.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1818, 273, 10, '4. Bọc miếng chả', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1819, 273, 11, 'Rắc nhẹ từng miếng bánh bằng bột mì.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1820, 273, 12, 'Nhúng vào trứng đã đánh, sau đó phủ một lớp vụn bánh mì để có lớp vỏ giòn.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1821, 273, 13, '5. Chiên Fašírky', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1822, 273, 14, 'Đun nóng dầu thực vật trong chảo trên lửa vừa.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1823, 273, 15, 'Chiên các miếng chả trong 4-5 phút mỗi mặt cho đến khi có màu vàng nâu và chín hoàn toàn.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1824, 273, 16, 'Chuyển sang đĩa có lót khăn giấy để xả bớt dầu thừa.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1825, 273, 17, '6. Phục vụ và thưởng thức', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1826, 273, 18, 'Ăn nóng Fašírky với khoai tây nghiền, salad bắp cải hoặc bánh mì tươi.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1827, 273, 19, 'Thưởng thức cùng mù tạt, dưa chua hoặc sốt tỏi để tăng thêm hương vị.', NULL, '2026-05-15 14:41:23', '2026-05-15 14:41:23'),
(1829, 274, 1, 'Để làm nhân, đun nóng dầu ô liu trong chảo cho đến khi dầu bắt đầu sủi bọt. Thêm tỏi tây và xào cho đến khi mềm nhưng không có màu. Dùng thìa gỗ khuấy thịt giăm bông, chiên trong 1 phút, sau đó cho bột mì vào và chiên trên lửa vừa, thỉnh thoảng khuấy cho đến khi hỗn hợp vàng nhưng không bị cháy - quá trình này sẽ mất khoảng 5 phút.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1831, 274, 2, 'Trong khi đó, cho nước kho và sữa vào chảo nhỏ và đun nóng cho đến khi hấp nhưng không sôi. Nêm với một ít hạt nhục đậu khấu. Dần dần thêm chất lỏng, mỗi lần một vài muỗng canh, khuấy liên tục.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1833, 274, 3, 'Sau khi bạn đã trộn hết nước kho sữa, hãy tiếp tục nấu phần nhân ở lửa vừa trong khoảng 10 phút hoặc cho đến khi nhân đặc lại và rời khỏi thành chảo khi bạn khuấy.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1835, 274, 4, 'Nêm hạt tiêu đen, nếm và điều chỉnh muối nếu cần - lúc đầu giăm bông có thể rất mặn. Phần nhân bây giờ đã xong: nó phải thật dày vì bạn không muốn bánh croquetas biến thành bánh kếp.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1837, 274, 5, 'Dàn đều hỗn hợp lên khay nướng (30 x 20cm là được). Khi bánh đã ngừng hấp, hãy dùng màng bọc thực phẩm bọc lại để bánh không bị khô. Để nguội trước khi cho vào tủ lạnh khoảng 1h.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1839, 274, 6, 'Khi bạn đã sẵn sàng cho giai đoạn tiếp theo, hãy xếp ba cái bát: cái thứ nhất chứa đầy bột mì, cái thứ hai chứa trứng đánh và cái thứ ba chứa vụn bánh mì. Lấy hỗn hợp giăm bông ra khỏi tủ lạnh. Thoa một ít dầu ô liu lên tay để cuộn bánh croquetas dễ dàng hơn.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1841, 274, 7, 'Lăn một thìa hỗn hợp giữa lòng bàn tay của bạn. Kích thước và hình dạng của croquetas tùy thuộc vào bạn, nhưng dễ nhất là một quả bóng có kích thước bằng quả óc chó. Sau đó bắt đầu phủ như sau.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1843, 274, 8, 'Nhúng bánh croquetas vào bột mì - bạn muốn có một lớp bột - tiếp theo là trứng, sau đó là vụn bánh mì. Đặt chúng lên khay và khi bạn đã sử dụng hết hỗn hợp, hãy đặt chúng vào tủ lạnh trong 30 phút.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1845, 274, 9, 'Nếu bạn có nồi chiên ngập dầu, hãy đun nóng dầu đến 180C và chiên trong vài phút. Nếu không, hãy đun nóng dầu trong chảo sâu lòng, có đáy nặng cho đến khi dầu bắt đầu sủi bọt. Sau đó thêm 5-6 croquetas cùng một lúc và chiên cho đến khi vàng đều. Sau khi chín, để ráo trên giấy ăn và ăn ngay.', NULL, '2026-05-15 14:41:27', '2026-05-16 12:35:34'),
(1846, 275, 1, 'BƯỚC 1', NULL, '2026-05-15 14:41:32', '2026-05-15 14:41:32'),
(1847, 275, 2, 'Gọt vỏ và cắt khoai tây thành những khối đều nhau, cỡ vừa. Cho vào một cái chảo lớn chứa đầy nước muối lạnh, đun sôi và nấu trong vòng 10 - 15 phút cho đến khi có thể đâm dao vào khoai tây dễ dàng.', NULL, '2026-05-15 14:41:32', '2026-05-15 14:41:32'),
(1848, 275, 3, 'BƯỚC 2', NULL, '2026-05-15 14:41:32', '2026-05-15 14:41:32'),
(1849, 275, 4, 'Trong khi đó, làm tan bơ trong chảo xào lớn trên lửa vừa. Thêm tỏi, bắp cải, hành lá và một ít gia vị. Thỉnh thoảng đảo đều cho đến khi bắp cải héo nhưng vẫn còn dính một ít thì để sang một bên.', NULL, '2026-05-15 14:41:32', '2026-05-15 14:41:32'),
(1850, 275, 5, 'BƯỚC 3', NULL, '2026-05-15 14:41:32', '2026-05-15 14:41:32'),
(1851, 275, 6, 'Để ráo khoai tây, để khô trong vài phút, sau đó nghiền với kem, mù tạt và gia vị trong cùng một chảo. Khuấy bắp cải và giăm bông. Giữ ấm ở nhiệt độ thấp.', NULL, '2026-05-15 14:41:32', '2026-05-15 14:41:32'),
(1852, 275, 7, 'BƯỚC 4', NULL, '2026-05-15 14:41:32', '2026-05-15 14:41:32'),
(1853, 275, 8, 'Làm nóng lại chảo bạn dùng để nấu bắp cải (không cần rửa trước), thêm một chút dầu, đập trứng vào và chiên theo ý thích của bạn. Để phục vụ, hãy chia colcannon vào các bát và phủ một quả trứng chiên lên trên mỗi bát.', NULL, '2026-05-15 14:41:32', '2026-05-15 14:41:32'),
(1854, 276, 1, 'BƯỚC 1 - LÀM Súp', NULL, '2026-05-15 14:41:34', '2026-05-15 14:41:34'),
(1855, 276, 2, 'Cho nước luộc gà vào chảo và đợi sôi.', NULL, '2026-05-15 14:41:34', '2026-05-15 14:41:34'),
(1856, 276, 3, 'Tiếp theo thêm muối, đường, dầu hạt mè, tiêu trắng, sốt ớt cay, giấm và nước tương vào rồi khuấy đều trong vài giây.', NULL, '2026-05-15 14:41:34', '2026-05-15 14:41:34'),
(1857, 276, 4, 'Cho Đậu phụ, nấm hương, mộc nhĩ đen vào chảo.', NULL, '2026-05-15 14:41:34', '2026-05-15 14:41:34'),
(1858, 276, 5, 'Để làm đặc nước sốt, trộn 1 thìa bột ngô và 2 thìa nước vào tô rồi từ từ thêm vào súp cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:41:34', '2026-05-15 14:41:34'),
(1859, 276, 6, 'Tiếp theo, thêm 1 quả trứng đánh nhẹ bằng dao hoặc nĩa rồi thêm vào súp và khuấy trong 8 giây', NULL, '2026-05-15 14:41:34', '2026-05-15 14:41:34'),
(1860, 276, 7, 'Múc súp ra bát rồi thêm thịt lợn bbq và hành lá thái lát lên trên.', NULL, '2026-05-15 14:41:34', '2026-05-15 14:41:34'),
(1862, 277, 1, 'Rửa sạch lá tỏi dại trong một cái chao, sau đó đổ nước sôi từ ấm vào cho đến khi héo. Rửa sạch ngay dưới vòi nước lạnh, sau đó vắt bớt nước và thái nhỏ.', NULL, '2026-05-15 14:41:38', '2026-05-16 12:35:34'),
(1864, 277, 2, 'Đun nóng sữa trong chảo ở lửa nhỏ cho đến khi sôi. Đun nóng dầu hoặc bơ trong chảo thứ hai và sau khi ấm hoặc tan chảy, cho bột vào khuấy trong vài phút cho đến khi bột bắt đầu chuyển sang màu nâu một chút. Dần dần thêm sữa ấm, từng chút một, cho đến khi bạn có được nước sốt đặc và mượt. Tạo bọt trong một hoặc hai phút, khuấy đều để đảm bảo bột đã chín hết. Mùa.', NULL, '2026-05-15 14:41:38', '2026-05-16 12:35:34'),
(1866, 277, 3, 'Thêm manchego, jamón và tỏi rừng vào chảo rồi đánh đều. Đổ ra khay hoặc đĩa nướng đã phết một ít dầu, dàn đều rồi đậy nắp và để nguội ít nhất 1 giờ. Sẽ giữ lạnh lên đến 24 giờ.', NULL, '2026-05-15 14:41:38', '2026-05-16 12:35:34'),
(1868, 277, 4, 'Thoa nhẹ dầu lên tay và nặn hỗn hợp thành 18-20 quả bóng có kích thước đều nhau. Xếp lên khay nướng và để đông trong 30 phút cho cứng lại.', NULL, '2026-05-15 14:41:38', '2026-05-16 12:35:34'),
(1870, 277, 5, 'Đánh trứng vào đĩa nông với một ít gia vị. Đổ panko vào món thứ hai. Nhúng từng chiếc croquetas vào trứng, sau đó lăn qua bột chiên xù. Tại thời điểm này, croquetas thô có thể được đông lạnh đến ba tháng. Đổ dầu vào chảo lớn, sâu lòng, đảm bảo ngập không quá 1/3 dầu và đun nóng ở nhiệt độ 170C hoặc cho đến khi một khối bánh mì chín vàng nhẹ trong 30 giây. Chiên croquetas theo mẻ trong 2-3 phút cho đến khi vàng đậm. Để nấu từ món đông lạnh, hãy chiên ở nhiệt độ 160C thêm vài phút nữa cho đến khi chúng nóng bên trong. Dùng thìa có rãnh vớt ra một tờ giấy ăn và để ráo nước. Ăn ấm với một ly rượu sherry.', NULL, '2026-05-15 14:41:38', '2026-05-16 12:35:34'),
(1871, 278, 1, 'BƯỚC 1', NULL, '2026-05-15 14:41:41', '2026-05-15 14:41:41'),
(1872, 278, 2, 'Đun nóng dầu trong chảo, xào hành tây thái lát cho đến khi vàng nâu, sau đó thêm tonkatsu (xem công thức ở đây), đặt vào giữa chảo. Trộn dashi, đậu nành, mirin và đường với nhau rồi đổ 3/4 hỗn hợp xung quanh tonkatsu. Đun sôi trong vài phút để nước sốt đặc lại một chút và tonkatsu sẽ nóng lại.', NULL, '2026-05-15 14:41:41', '2026-05-15 14:41:41'),
(1873, 278, 3, 'BƯỚC 2', NULL, '2026-05-15 14:41:41', '2026-05-15 14:41:41'),
(1874, 278, 4, 'Đổ trứng đã đánh xung quanh tonkatsu và nấu trong 2-3 phút cho đến khi trứng chín nhưng vẫn còn hơi chảy nước. Chia cơm vào hai bát, sau đó phủ một nửa quả trứng và hỗn hợp tonkatsu lên trên, rắc hẹ lên và dùng ngay, rưới thêm một chút đậu nành nếu bạn muốn thêm vị umami.', NULL, '2026-05-15 14:41:41', '2026-05-15 14:41:41'),
(1876, 279, 1, 'Đun nóng mỡ lợn trong chảo trên lửa vừa và xào hành tây thái nhỏ cho đến khi vàng, khoảng 5-8 phút. Cho thìa là và thịt lợn vào, chiên đều trong 10 phút cho đến khi chín vàng. Thêm tỏi, nêm đều và rải lên bột. Nấu khoảng một phút, sau đó thêm ớt bột vào và nấu thêm 1 phút nữa.', NULL, '2026-05-15 14:41:44', '2026-05-16 12:35:34'),
(1878, 279, 2, 'Đổ một nửa nước kho vào, thêm lá nguyệt quế và đậy nắp đun nhỏ lửa ở lửa nhỏ trong 30 phút.', NULL, '2026-05-15 14:41:44', '2026-05-16 12:35:34'),
(1880, 279, 3, 'Thêm dưa cải bắp, nước còn lại và một ít nước ngâm dưa cải bắp. Đậy nắp đun nhỏ lửa trong 30 phút, thỉnh thoảng khuấy đều cho đến khi thịt mềm. Khuấy kem và đun nhỏ lửa trong 5 phút để kết hợp hương vị. Nêm nếm vừa ăn, trang trí bằng một thìa kem chua là xong.', NULL, '2026-05-15 14:41:44', '2026-05-16 12:35:34'),
(1881, 279, 4, 'Công thức này đã được Apetit Online cung cấp và chưa được chúng tôi kiểm tra lại.', NULL, '2026-05-15 14:41:44', '2026-05-16 12:35:34'),
(1882, 280, 1, 'Làm nóng lò ở mức quạt/khí 140C/120C 1. Đặt một chiếc chảo chịu nhiệt lớn (có nắp đậy kín) lên lửa cao. Cho mỡ và thịt thái hạt lựu vào, nấu trong vài phút cho kín các mép, đảo nhanh để chín đều. Giảm nhiệt xuống thấp, thêm hành tây thái lát, cả tép tỏi, cà rốt và hạt thì là vào nấu nhẹ để rau mềm trong vài phút.', NULL, '2026-05-15 14:41:49', '2026-05-15 14:41:49'),
(1883, 280, 2, 'Đổ giấm rượu vang đỏ lên trên, cạo hết phần thịt còn sót lại dưới đáy chảo. Thêm nước luộc, cà chua xay nhuyễn, một nửa lá hương thảo và rau mùi tây. Đun sôi và đun nhỏ lửa trong 10 phút, sau đó nêm gia vị, đậy nắp và cho vào lò nướng trong 2 giờ, tháo nắp trong giờ nấu cuối cùng. Thỉnh thoảng khuấy đều và thêm đậu vào sau 30 phút.', NULL, '2026-05-15 14:41:49', '2026-05-15 14:41:49'),
(1884, 280, 3, 'Lấy chảo ra khỏi lò và làm nóng vỉ nướng. Rắc các loại thảo mộc và vụn bánh mì còn lại lên trên, rưới một ít dầu lên trên rồi cho vào lò nướng trong 5-10 phút cho đến khi vụn bánh mì vàng. Ăn kèm bánh mì giòn và rau xanh.', NULL, '2026-05-15 14:41:49', '2026-05-15 14:41:49'),
(1886, 281, 1, 'Cắt thịt thành từng miếng lớn, cho vào nồi lớn nhất và đổ 5 lít nước vào. Đun sôi ở nhiệt độ cao, hớt hết bọt nổi lên bề mặt. Thêm lá nguyệt quế. Mùa. Giảm nhiệt xuống đun nhỏ lửa và nấu trong 1 giờ hoặc cho đến khi thịt mềm và rơi ra khỏi xương. Thêm đậu nếu sử dụng khô.', NULL, '2026-05-15 14:41:54', '2026-05-16 12:35:34'),
(1888, 281, 2, 'Tăng nhiệt lên. Đun sôi trở lại, sau đó giảm nhiệt và đun thêm 20 phút nữa – đậu vẫn còn hơi thô. Thêm cà rốt, hành tây, tỏi và hạt tiêu. Khuấy đều, sau đó thêm ớt nếu dùng. Nấu thêm 15 phút nữa.', NULL, '2026-05-15 14:41:54', '2026-05-16 12:35:34'),
(1890, 281, 3, 'Khuấy củ cải đường và nấu trong 10 phút trước khi thêm khoai tây. Sau 15 phút, thêm cà chua xay nhuyễn cho vừa ăn và đậu, nếu dùng đóng hộp, rồi đun sôi. Nấu trong 5 phút, thêm bắp cải và nấu thêm 5 phút nữa. Nêm gia vị, sau đó trang trí với rau mùi tây và thì là. Tắt lửa và để yên trong 5 phút. Ăn kèm với kem chua ở bên cạnh.', NULL, '2026-05-15 14:41:54', '2026-05-16 12:35:34'),
(1891, 282, 1, 'BƯỚC 1', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1892, 282, 2, 'Cắt thăn thành 5 miếng có kích thước bằng nhau, để phần đuôi dài hơn một chút. Lấy một túi nhựa trong và nhét một trong các mảnh vào. Dùng cán lăn đập nó vào một cái thang có kích thước bằng tấm bên và lặp lại với các mảnh còn lại.', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1893, 282, 3, 'BƯỚC 2', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1894, 282, 4, 'Cho rượu vang, ớt bột, một ít muối, tiêu và nước cốt của ½ quả chanh vào tô rồi thêm thịt lợn vào. Để ướp trong 20-30 phút, trong khi bạn nướng thịt nướng đến giai đoạn than đỏ rực nhưng không có ngọn lửa.', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1895, 282, 5, 'BƯỚC 3', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1896, 282, 6, 'Để làm khoai tây chiên, hãy đổ đầy nước mát vào chậu và cắt khoai tây thành những miếng khoai tây chiên dày 3 cm. Ngâm chúng trong nước khoảng 5 phút rồi thay nước. Để thêm 5 phút nữa. Để ráo nước rồi lau khô trên khăn hoặc giấy ăn.', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1897, 282, 7, 'BƯỚC 4', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1898, 282, 8, 'Đun nóng dầu trong nồi chiên ngập dầu hoặc chảo sâu lòng có nắp đậy ở nhiệt độ 130C rồi thả khoai tây chiên vào dầu (theo mẻ). Chần trong 8-10 phút. Lấy ra khỏi dầu và để ráo nước. Đặt lên khay để nguội. Đun nóng dầu đến 180C (đảm bảo dầu nóng, nếu không khoai tây chiên của bạn sẽ bị sũng nước) và thả giỏ khoai tây chiên vào dầu (một lần nữa, hãy làm theo từng mẻ). Để nấu trong 2 phút rồi lắc nhẹ. Nấu thêm khoảng một phút nữa cho đến khi chúng có màu sắc đẹp và giòn khi chạm vào. Để ráo nước trong vài phút, đổ vào tô và rắc muối biển.', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1899, 282, 9, 'BƯỚC 5', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1900, 282, 10, 'Thịt lợn sẽ chín nhanh nên làm thành 2 mẻ. Lấy các miếng ra khỏi nước xốt, thoa dầu rồi thả chúng vào vỉ nướng (bạn cũng có thể sử dụng vỉ nướng). Nấu mỗi mặt trong 1 phút - chúng có thể bùng lên khi bạn làm như vậy. Khoảng thời gian này thực sự là đủ vì họ sẽ tiếp tục nấu ăn. Lấy chúng ra khỏi vỉ nướng và xếp lên đĩa. Lặp lại với lô còn lại.', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1901, 282, 11, 'BƯỚC 6', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1902, 282, 12, 'Phục vụ bằng cách xếp khoai tây chiên lên đĩa, thả thịt lợn lên trên mỗi chồng và đổ nước ép từ đĩa lên trên để khoai tây chiên thấm hết hương vị. Phủ một thìa sốt mayonnaise và một lát chanh lên trên.', NULL, '2026-05-15 14:41:58', '2026-05-15 14:41:58'),
(1903, 283, 1, 'Raspeballer & Thịt Muối (Tùy Chọn)', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1904, 283, 2, 'Nếu bạn làm món thịt lợn, hãy luộc trong nước sôi khoảng 3 giờ cho đến khi thịt rời khỏi xương. Lấy thịt lợn ra và để dành nước dùng để nấu món raspeballer.', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1905, 283, 3, 'Luộc khoai tây luộc và gọt vỏ sau khi nguội. Ngoài ra, hãy gọt vỏ khoai tây sống, sau đó xay hoặc cho vào máy xay thực phẩm. Dùng khăn giấy để loại bỏ bớt hơi ẩm trên khoai tây nghiền.', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1906, 283, 4, 'Nghiền khoai tây luộc trong máy nghiền khoai tây hoặc bằng máy nghiền. Hãy chắc chắn rằng không có cục u. Cho khoai tây sống đã bào vào một tô trộn lớn và trộn đều với khoai tây nghiền. Thêm bột lúa mạch, bột mì đa dụng và muối vào rồi trộn đều bằng tay cho đến khi hỗn hợp hòa quyện hoàn toàn.', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1907, 283, 5, 'Bạn có thể nấu bánh raspeballer trong nước luộc rau hoặc thịt bò, hoặc nếu bạn đang làm món thịt lợn, hãy nấu chúng trong nước dùng từ thịt lợn. Đun sôi nước dùng thật nhẹ - bạn không muốn nước luộc sôi hoàn toàn vì khi đó bánh raspeballer có thể bị vỡ.', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(1908, 283, 6, 'Dùng một thìa canh nhúng vào nước lạnh để tạo hình từng quả raspeball trong tay. Cố gắng làm sao cho chúng mịn nhất có thể rồi nhẹ nhàng thả vào nồi nước dùng đang sôi. Nhúng thìa vào bát nước lạnh giữa mỗi quả raspeball.', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1909, 283, 7, 'Để raspeballer sôi trong khoảng 30 phút. Nếu bạn làm xúc xích hun khói, bạn có thể hâm nóng xúc xích trong cùng một nồi với dụng cụ nướng xúc xích. Rắc mùi tây tươi xắt nhỏ lên trên.', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1910, 283, 8, 'Rutabaga nghiền', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1911, 283, 9, 'Gọt vỏ rutabaga và cà rốt rồi cắt thành từng miếng nhỏ. Đun sôi trong nước khoảng 30 phút hoặc cho đến khi mềm. Sau đó để ráo nước, thêm kem/sữa, bơ và hạt nhục đậu khấu vào rồi xay cho đến khi mịn.', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1912, 283, 10, 'Phục vụ cùng với raspeballer và thịt.', NULL, '2026-05-15 14:42:03', '2026-05-15 14:42:03'),
(1914, 284, 1, 'Cho bắp cải vào máy xay thực phẩm và xay cho đến khi thái nhỏ. Nêm ½ thìa muối, đảo đều và để yên trong 15 phút. Đổ vào một chiếc khăn trà sạch và vắt càng nhiều nước càng tốt. Cho cà rốt, nấm, thịt lợn băm, tỏi, gừng, nước tương, dầu mè và hành lá vào tô. Nêm hạt tiêu đen. Dùng tay trộn đều mọi thứ lại với nhau, trộn đều cho đến khi mọi thứ hòa quyện.', NULL, '2026-05-15 14:42:05', '2026-05-16 12:35:34'),
(1916, 284, 2, 'Ngâm các miếng chả giò trong vài giây trong một đĩa nước ấm, sau đó chuyển sang thớt đã phết dầu. Làm từng tờ một, múc 1 muỗng canh nhân vào giữa, sau đó gấp phần dưới lên và phủ lên trên. Gấp phần trên của tờ giấy xuống, sau đó gấp các cạnh lại và tạo thành một hình vuông gọn gàng. Nếu bánh bao có cảm giác hơi giòn, hãy ngâm một tờ giấy khác và bọc lại. Lặp lại với các tờ giấy và phần nhân còn lại, chuyển bánh bao vào đĩa đã phết dầu trong khi thực hiện.', NULL, '2026-05-15 14:42:05', '2026-05-16 12:35:34'),
(1918, 284, 3, 'Đun nóng dầu trong chảo chống dính lớn (đảm bảo không đầy quá một phần ba) trên lửa vừa cao và chiên bánh bao trong 3-5 phút cho đến khi có màu vàng nâu. Dùng thìa có rãnh hoặc con nhện để lật chúng, sau đó đậy nắp lại và nấu thêm 3-4 phút nữa cho đến khi chín vàng. Mở nắp và nấu trong 1-2 phút.', NULL, '2026-05-15 14:42:05', '2026-05-16 12:35:34'),
(1920, 284, 4, 'Trong khi đó, trộn tất cả nguyên liệu làm nước chấm vào tô nhỏ. Dọn bánh bao với nước chấm ở bên cạnh.', NULL, '2026-05-15 14:42:05', '2026-05-16 12:35:34'),
(1922, 285, 1, 'Cắt đôi bắp cải, loại bỏ phần cuống cứng và thái lát mỏng. Cho vào chảo lớn cùng tất cả các nguyên liệu khác trừ xúc xích, sau đó trộn với 300ml nước và một ít muối, tiêu.', NULL, '2026-05-15 14:42:08', '2026-05-16 12:35:34'),
(1924, 285, 2, 'Đun sôi, sau đó giảm nhiệt, đậy nắp vừa vặn và nấu nhẹ trong 1 tiếng rưỡi, khuấy thường xuyên. Nếu khô quá có thể cho thêm chút nước.', NULL, '2026-05-15 14:42:08', '2026-05-16 12:35:34'),
(1926, 285, 3, 'Thêm kabanos vào hỗn hợp bắp cải, đậy nắp chảo và đun nhỏ lửa trong 20 phút. Mở nắp và nấu thêm 10 phút nữa. Ăn kèm với khoai tây nghiền hoặc luộc đơn giản.', NULL, '2026-05-15 14:42:08', '2026-05-16 12:35:34'),
(1927, 286, 1, 'Phục vụ 2', NULL, '2026-05-15 14:42:12', '2026-05-15 14:42:12'),
(1928, 286, 2, 'Điều chỉnh giá đỡ ở vị trí trên cùng và giữa và làm nóng lò trước ở nhiệt độ 450 độ. Rửa và lau khô tất cả sản phẩm. Cắt khoai lang thành từng miếng 1/2 inch. Đổ một ít dầu, muối và hạt tiêu lên khay nướng. Nướng trên giá trên cùng trong 12 phút (sau đó chúng ta sẽ nướng bí xanh).', NULL, '2026-05-15 14:42:12', '2026-05-15 14:42:12'),
(1929, 286, 3, 'Trong khi đó, nửa quả táo và lõi; thái mỏng thành hình bán nguyệt. Bóc vỏ và băm nhuyễn tỏi. Quả chanh quý. Cắt và cắt đôi bí xanh theo chiều dọc; cắt ngang thành hình bán nguyệt dày 1/2 inch. Đổ một ít dầu và một chút muối và hạt tiêu lên khay nướng thứ hai. Đặt sang một bên.', NULL, '2026-05-15 14:42:12', '2026-05-15 14:42:12'),
(1930, 286, 4, 'Lau khô thịt lợn bằng khăn giấy và rắc muối và hạt tiêu lên trên. Đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm thịt lợn vào và nấu cho đến khi chín vàng, khoảng 4-5 phút mỗi mặt. Tắt nhiệt; chuyển sang đĩa.', NULL, '2026-05-15 14:42:12', '2026-05-15 14:42:12'),
(1931, 286, 5, 'Sau khi nướng khoai lang được 12 phút, chuyển khay nướng có bí xanh sang giá giữa và tiếp tục nướng cho đến khi cả hai loại rau đều chín vàng và mềm, thêm 12-15 phút nữa.', NULL, '2026-05-15 14:42:12', '2026-05-15 14:42:12'),
(1932, 286, 6, 'Trong khi đó, làm tan chảy 1 muỗng canh bơ (2 muỗng canh cho 4 phần ăn) trong chảo dùng cho thịt lợn ở lửa vừa cao. Thêm táo và nêm muối và hạt tiêu. Nấu, cạo hết những phần có màu nâu dưới đáy chảo cho đến khi táo hơi mềm, khoảng 2-3 phút. Thêm tỏi; nấu cho đến khi có mùi thơm, 30 giây. Thêm 1/z cốc nước (3/4 cốc cho 4 người), nước cô đặc và 11/2 thìa cà phê đường (3 thìa cà phê cho 4 người). Nấu, khuấy đều cho đến khi nước sốt đặc lại và táo rất mềm, khoảng 3-5 phút. Nêm muối và hạt tiêu.', NULL, '2026-05-15 14:42:12', '2026-05-15 14:42:12'),
(1933, 286, 7, 'Lấy chảo có táo ra khỏi bếp; khuấy 1 muỗng canh bơ (2 muỗng canh cho 4 phần ăn) và vắt nước cốt chanh. Chia thịt lợn, bí xanh và khoai lang vào các đĩa. Thịt lợn phủ sốt táo. Top zucchini với một vắt nước chanh.', NULL, '2026-05-15 14:42:12', '2026-05-15 14:42:12'),
(1935, 287, 1, 'Làm nóng lò nướng ở nhiệt độ quạt/khí 200C/180C 6. Dùng chày và cối giã tỏi, lá xô thơm, vỏ chanh, muối và tiêu với nhau cho đến khi hỗn hợp trở thành hỗn hợp sệt. Khuấy dầu, sau đó phết hỗn hợp lên vai lợn, tránh phần da bên trên. Dùng dao sắc rạch da, sau đó chà một nhúm muối lớn vào da. Buộc thịt lợn lại với nhau bằng dây bếp.', NULL, '2026-05-15 14:42:14', '2026-05-16 12:35:34'),
(1937, 287, 2, 'Lót một khay nướng lớn với một lớp giấy bạc hai lớp và đặt thịt lợn lên trên, mặt da hướng lên trên. Dùng giấy bạc bọc các cạnh của miếng thịt lại để tạo thành một gói, sau đó đổ rượu vào khay xung quanh các cạnh. Chuyển vào lò nướng và giảm nhiệt độ xuống 140C/120C quạt/gas 1. Nướng trong 4-5 giờ hoặc cho đến khi nhiệt kế thịt đưa vào phần dày nhất của thịt lợn ghi 70C.', NULL, '2026-05-15 14:42:14', '2026-05-16 12:35:34'),
(1939, 287, 3, 'Vặn lò nướng lên đến 240C/220C quạt/khí 9. Cẩn thận múc nước nướng thịt lợn từ chảo vào nồi và nấu trên lửa vừa trong 10-15 phút hoặc cho đến khi giảm một phần ba. Nêm nếm vừa miệng.', NULL, '2026-05-15 14:42:14', '2026-05-16 12:35:34'),
(1941, 287, 4, 'Trong khi đó, xếp giấy bạc xung quanh miếng thịt sao cho chỉ lộ ra phần da, sau đó cho vào lò nướng khoảng 10 - 15 phút cho đến khi phần da phồng lên và chín vàng toàn bộ. Để yên khoảng 20 phút trước khi cắt. Ăn kèm với nước sốt rưới lên.', NULL, '2026-05-15 14:42:14', '2026-05-16 12:35:34'),
(1943, 288, 1, 'Bắc một chảo nước lên bếp đun sôi với lửa lớn. Trong khi đó, dùng kéo cắt chorizo ​​thành từng dải rồi cắt nhỏ mùi tây và ớt (trước tiên hãy kiểm tra xem có hạt lạc không).', NULL, '2026-05-15 14:42:18', '2026-05-16 12:35:34'),
(1945, 288, 2, 'Khi nước sôi mạnh, cho mì spaghetti cùng một lượng muối vừa đủ vào, khuấy đều và đun sôi trở lại. Nấu trong 3 phút.', NULL, '2026-05-15 14:42:18', '2026-05-16 12:35:34'),
(1947, 288, 3, 'Trong một chảo lớn, đun nóng dầu, cho chorizo, ớt và nhiều tiêu đen vào. Nấu trong khoảng một phút cho đến khi nóng hoàn toàn và nước ép có màu đỏ từ ớt bột trong chorizo. Múc nửa cốc nước mì ống ra khỏi chảo, chắt phần còn lại và cho mì spaghetti vào chảo rán.', NULL, '2026-05-15 14:42:18', '2026-05-16 12:35:34'),
(1949, 288, 4, 'Thêm rau mùi tây và parmesan, trộn đều và vẩy nước mì ống vào để làm ẩm. Đưa thêm parmesan lên bàn.', NULL, '2026-05-15 14:42:18', '2026-05-16 12:35:34'),
(1954, 290, 1, 'Rửa và gọt vỏ khoai tây rồi cắt thành từng miếng có kích thước tương tự để chín đều.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1955, 290, 2, 'Trong một nồi súp lớn, luộc khoai tây và lá nguyệt quế trong nước muối trong 20 phút. Bỏ lá nguyệt quế đi.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1956, 290, 3, 'Nếu bạn không sử dụng túi cải xoăn xoăn cắt sẵn, hãy rửa kỹ các bó dưới vòi nước mát để loại bỏ hết đất - bạn sẽ không muốn có kết cấu sạn trong món ăn đã hoàn thành của mình. Cắt bỏ những cành thô và loại bỏ những lá màu nâu. Dùng một con dao sắc, cắt cải xoăn thành những dải mỏng.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1957, 290, 4, 'Gọt vỏ và cắt nhỏ hẹ.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1958, 290, 5, 'Trong chảo rán hoặc chảo, làm tan chảy 1 muỗng canh. bơ và xào hẹ trong vài phút trước khi thêm cải xoăn xoăn và 2 muỗng canh. của nước. Nêm và nấu trong khoảng 10 phút hoặc cho đến khi mềm.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1959, 290, 6, 'Đun nóng sữa trên bếp hoặc trong lò vi sóng.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1960, 290, 7, 'Để ráo nước, lắc và lau khô khoai tây bằng khăn bếp trước khi nghiền bằng máy nghiền hoặc máy xay khoai tây. Thao tác nhanh chóng, thêm sữa ấm và phần bơ còn lại vào. Nêm nếm với hạt nhục đậu khấu, muối và hạt tiêu.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1961, 290, 8, 'Trộn cải xoăn đã nấu chín với hỗn hợp khoai tây nghiền đã nấu chín.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1962, 290, 9, 'Xếp các lát xúc xích hun khói lên trên và dùng nóng với mù tạt hoặc nước thịt yêu thích của bạn.', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1963, 290, 10, 'Phục vụ và thưởng thức!', NULL, '2026-05-15 14:42:24', '2026-05-15 14:42:24'),
(1964, 291, 1, 'Chuẩn bị', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1965, 291, 2, '1. Đập trứng vào tô. Tách lòng trắng và lòng đỏ trứng.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1966, 291, 3, 'Thịt lợn chua ngọt', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1967, 291, 4, '2. Cắt thăn lợn thành từng dải.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1968, 291, 5, '3. Chuẩn bị nước xốt bằng cách sử dụng một chút muối, một thìa cà phê tinh bột, hai thìa cà phê nước tương nhạt và một lòng trắng trứng.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1969, 291, 6, '4. Ướp các dải thịt lợn trong khoảng 20 phút.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1970, 291, 7, '5. Cho phần tinh bột còn lại vào tô. Thêm một ít nước và giấm để tạo thành nước sốt có tinh bột.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1971, 291, 8, 'Thịt lợn chua ngọt', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1972, 291, 9, 'Hướng dẫn nấu ăn', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1973, 291, 10, '1. Đổ dầu ăn vào chảo và đun nóng đến 190°C (375°F). Thêm các dải thịt lợn đã ướp vào và chiên cho đến khi chúng chuyển sang màu nâu. Lấy thịt lợn đã nấu chín ra khỏi chảo và đặt lên đĩa.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1974, 291, 11, '2. Để lại một ít dầu trong chảo. Cho nước sốt cà chua và đường trắng vào chảo, đun nóng cho đến khi dầu và nước sốt hòa quyện hoàn toàn.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1975, 291, 12, '3. Thêm một ít nước vào chảo và đun nóng kỹ nước sốt chua ngọt trước khi thêm thịt lợn vào.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1976, 291, 13, '4. Đổ nước sốt tinh bột vào. Xào tất cả các nguyên liệu cho đến khi thịt lợn và nước sốt được trộn đều với nhau.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1977, 291, 14, '5. Bày ra đĩa và thêm một ít rau mùi để trang trí.', NULL, '2026-05-15 14:42:25', '2026-05-15 14:42:25'),
(1979, 292, 1, 'Đun nóng dầu trong chảo lớn hoặc nồi chống cháy. Thêm hành lá và cọng rau mùi vào nấu trong 1 phút. Thêm các lát thịt lợn và nấu trong 5 phút cho đến khi bắt đầu có màu nâu.', NULL, '2026-05-15 14:42:29', '2026-05-16 12:35:34'),
(1981, 292, 2, 'Khuấy bột cà ri và bơ đậu phộng. Sau 30 giây, thêm đường, đậu nành và nước cốt dừa cùng ½ lon nước. Trộn đều, đậy nắp và đun nhỏ lửa trong 15 phút, thỉnh thoảng khuấy.', NULL, '2026-05-15 14:42:29', '2026-05-16 12:35:34'),
(1983, 292, 3, 'Mở nắp, thêm bắp non vào và tăng lửa. Đánh bong bóng trong 3 phút cho đến khi ngô chín và nước sốt hơi đặc lại. Khuấy nước cốt chanh và kiểm tra gia vị. Bây giờ có thể được đông lạnh lên đến 2 tháng. Để nấu từ món đông lạnh: rã đông kỹ, sau đó đun trên chảo trên bếp cho đến khi cà ri nóng hoàn toàn. Ăn rải rác với lá rau mùi và cơm.', NULL, '2026-05-15 14:42:29', '2026-05-16 12:35:34'),
(1984, 293, 1, 'Làm nóng lò ở 200°C/quạt180°C/gas 6. Chiên xúc xích trong chảo chống dính cho đến khi chín vàng.', NULL, '2026-05-15 14:42:31', '2026-05-15 14:42:31'),
(1985, 293, 2, 'Rưới dầu thực vật vào khay nướng sâu 30 cm x 25 cm x 6 cm rồi cho vào lò nướng khoảng 5 phút.', NULL, '2026-05-15 14:42:31', '2026-05-15 14:42:31'),
(1986, 293, 3, 'Cho bột mì vào tô, đập trứng cỡ vừa vào, sau đó cho cải ngựa bào vào trộn đều. Dần dần đánh vào sữa bán gầy. Mùa.', NULL, '2026-05-15 14:42:31', '2026-05-15 14:42:31'),
(1987, 293, 4, 'Đặt xúc xích vào khay nướng nóng và đổ bột lên trên. Phủ cà chua bi lên trên và nấu trong 30 phút cho đến khi phồng lên và vàng.', NULL, '2026-05-15 14:42:31', '2026-05-15 14:42:31'),
(1988, 294, 1, 'BƯỚC 1', NULL, '2026-05-15 14:42:34', '2026-05-15 14:42:34'),
(1989, 294, 2, 'Loại bỏ miếng mỡ lớn ở mép mỗi miếng thăn lợn, sau đó đập từng miếng thăn vào giữa hai miếng giấy nướng cho đến khi dày khoảng 1 cm – bạn có thể làm điều này bằng cách sử dụng dụng cụ làm mềm thịt hoặc cây cán bột. Sau khi đập, dùng tay nắn lại hình dạng và độ dày ban đầu của thịt – bước này sẽ đảm bảo thịt mọng nước nhất có thể.', NULL, '2026-05-15 14:42:34', '2026-05-15 14:42:34'),
(1990, 294, 3, 'BƯỚC 2', NULL, '2026-05-15 14:42:34', '2026-05-15 14:42:34'),
(1991, 294, 4, 'Cho bột mì, trứng và vụn bánh mì panko vào ba tô có viền rộng riêng biệt. Nêm thịt, sau đó nhúng vào bột mì, sau đó là trứng, sau đó là vụn bánh mì.', NULL, '2026-05-15 14:42:34', '2026-05-15 14:42:34'),
(1992, 294, 5, 'BƯỚC 3', NULL, '2026-05-15 14:42:34', '2026-05-15 14:42:34'),
(1993, 294, 6, 'Trong chảo rán hoặc chảo xào lớn, cho lượng dầu vừa đủ sao cho ngập thành chảo 2cm. Đun nóng dầu đến 180C – nếu không có nhiệt kế, bạn cho một ít panko vào dầu, nếu thấy hơi chìm xuống thì bắt đầu chiên là dầu đã chín. Thêm hai miếng sườn heo và nấu trong 1 phút 30 giây mỗi mặt, sau đó lấy ra và để trên giá lưới trong 5 phút. Lặp lại với phần sườn heo còn lại.', NULL, '2026-05-15 14:42:34', '2026-05-15 14:42:34'),
(1994, 294, 7, 'BƯỚC 4', NULL, '2026-05-15 14:42:34', '2026-05-15 14:42:34'),
(1995, 294, 8, 'Trong khi thịt lợn đang nghỉ, hãy làm nước sốt bằng cách trộn các nguyên liệu lại với nhau, thêm một chút nước nếu nước sốt đặc biệt đặc. Cắt tonkatsu và dùng kèm với nước sốt.', NULL, '2026-05-15 14:42:34', '2026-05-15 14:42:34'),
(1996, 295, 1, 'Lót giấy da vào đáy khuôn lò xo dài 20-2 cm (8-9 inch), tôi thường để lại một ít phần nhô ra vì bột rất lỏng và có thể tràn ra một chút. Làm nóng lò trước ở nhiệt độ 220 độ C.', NULL, '2026-05-15 14:42:37', '2026-05-15 14:42:37'),
(1997, 295, 2, 'Nướng phô mai và lấy giăm bông ra.', NULL, '2026-05-15 14:42:37', '2026-05-15 14:42:37'),
(1998, 295, 3, 'Trộn tất cả nguyên liệu còn lại vào tô lớn trong khoảng một đến hai phút.', NULL, '2026-05-15 14:42:37', '2026-05-15 14:42:37'),
(1999, 295, 4, 'Đổ một nửa bột vào chảo đã chuẩn bị sẵn, nó sẽ rất lỏng. Sau đó đặt giăm bông và phô mai lên trên rồi đổ phần bột còn lại lên trên.', NULL, '2026-05-15 14:42:37', '2026-05-15 14:42:37'),
(2000, 295, 5, 'Nướng khoảng 20-25 phút hoặc cho đến khi mặt trên vàng. Đợi vài phút trước khi lấy ra khỏi chảo và thưởng thức nóng hoặc lạnh với một số loại thảo mộc tươi.', NULL, '2026-05-15 14:42:37', '2026-05-15 14:42:37'),
(2001, 296, 1, 'Làm nóng lò ở mức quạt/khí 200C/180C 6. Luộc khoai tây cho đến khi mềm, để ráo nước và nghiền nát, sau đó để nguội. Đun nóng dầu trong chảo chống dính, cho thịt băm và hành tây vào xào nhanh cho đến khi chín vàng. Thêm tỏi, gia vị, nước kho, nhiều hạt tiêu và một chút muối vào trộn đều. Tắt bếp, khuấy đều khoai tây và để nguội.', NULL, '2026-05-15 14:42:39', '2026-05-15 14:42:39'),
(2002, 296, 2, 'Cán mỏng một nửa chiếc bánh và lót vào đế đĩa bánh nướng hoặc hộp bánh flan có đường kính 20-23 cm. Đổ hỗn hợp thịt lợn vào và phết nước lên các cạnh của bánh ngọt. Cán phần bột còn lại và bọc bánh lại. Nhấn các cạnh của bánh ngọt để bịt kín, cắt bỏ phần thừa. Chích phần trên của vỏ bánh ngọt để hơi nước thoát ra ngoài và phủ trứng đã đánh lên trên.', NULL, '2026-05-15 14:42:39', '2026-05-15 14:42:39'),
(2003, 296, 3, 'Nướng trong 30 phút cho đến khi bánh giòn và vàng đều. Phục vụ cắt thành miếng nêm với món salad xanh giòn. Thức ăn thừa dùng nguội sẽ rất ngon cho bữa trưa ngày hôm sau, dùng kèm với nhiều loại dưa chua.', NULL, '2026-05-15 14:42:39', '2026-05-15 14:42:39'),
(2004, 297, 1, 'Cắt lát mỏng thịt lợn chưa nấu chín, khoảng ⅛\". Nó giúp đông lạnh thịt một chút (tùy chọn).', NULL, '2026-05-15 14:42:42', '2026-05-15 14:42:42'),
(2005, 297, 2, 'Băm tỏi và hẹ. Trộn trong tô với đường, nước mắm, nước tương đặc, hạt tiêu và dầu cho đến khi đường tan.', NULL, '2026-05-15 14:42:42', '2026-05-15 14:42:42'),
(2006, 297, 3, 'Ướp thịt trong 1 giờ hoặc qua đêm để có kết quả tốt hơn.', NULL, '2026-05-15 14:42:42', '2026-05-15 14:42:42'),
(2007, 297, 4, 'Nướng thịt lợn ở nhiệt độ 375F trong 10-15 phút hoặc cho đến khi chín khoảng 80%. Kết thúc quá trình nấu bằng cách nướng trong lò cho đến khi có màu nâu vàng đẹp mắt, lật các miếng giữa chừng.', NULL, '2026-05-15 14:42:42', '2026-05-15 14:42:42'),
(2008, 297, 5, 'Lắp bát của bạn với rau, mì và trang trí. Nhiều người thích trộn cả tô lên và rưới nước mắm lên trên nhưng mình thích làm từng miếng nhỏ và rưới nước mắm từ từ.', NULL, '2026-05-15 14:42:42', '2026-05-15 14:42:42'),
(2010, 298, 1, 'Ngày hôm trước: làm băng. Cho đường và nước cốt chanh vào chảo cùng 1 muỗng canh nước rồi đun sôi để hòa tan đường. Thêm ớt và rau mùi vào rồi khuấy đều, sau đó cho vào máy xay cho đến khi mịn. Đổ vào tô, sau đó cho dầu mè, nước mắm, nước tương và hạt mè vào trộn đều để làm nước sốt. Đậy nắp và làm lạnh cho đến khi cần thiết.', NULL, '2026-05-15 14:42:46', '2026-05-16 12:35:34'),
(2012, 298, 2, 'Hai giờ trước khi ăn: làm nóng chảo nướng. Làm nóng lò ở mức 200C/gas 6/quạt 180C. Quét dầu lên thịt lợn và nướng đều các mặt trong vài phút cho đến khi chín. Chuyển sang khay nướng và cho vào lò nướng khoảng 10-12 phút cho đến khi chín. Để nguội, thái lát mỏng theo thớ thịt. Đổ vào một cái bát và đổ lên một nửa nước sốt.', NULL, '2026-05-15 14:42:46', '2026-05-16 12:35:34'),
(2014, 298, 3, 'Cách dùng: cho các nguyên liệu salad còn lại vào tô cùng với nước sốt còn lại. Xếp ra đĩa, đặt các lát thịt lợn lên trên và rưới lên bất kỳ loại nước trái cây nào.', NULL, '2026-05-15 14:42:46', '2026-05-16 12:35:34'),
(2016, 299, 1, 'Đun nóng 1 muỗng canh dầu trong chảo trên lửa lớn rồi xào từng mẻ thịt lợn cho đến khi chín vàng đều. Loại bỏ bằng một cái muỗng có rãnh và đặt sang một bên.', NULL, '2026-05-15 14:42:48', '2026-05-16 12:35:34'),
(2018, 299, 2, 'Giảm lửa xuống và thêm lượng dầu còn lại vào, sau đó cho hẹ, gừng và ớt vào đảo đều. Nấu trên lửa nhỏ trong vài phút cho đến khi bắt đầu mềm. Cho đường, nước mắm và 200ml nước vào chảo rồi khuấy đều. Đun sôi, khuấy đều cho đường tan hết rồi cho thịt lợn vào chảo. Đánh bong bóng mạnh trong 8-10 phút cho đến khi nước sốt đặc lại, phủ lên thịt và trở nên bóng. Hương vị và khuấy thêm một chút nước mắm, nếu cần, cùng với tương ớt. Rắc hành lá và ăn kèm cơm trắng và pak choi.', NULL, '2026-05-15 14:42:48', '2026-05-16 12:35:34'),
(2020, 300, 1, 'Làm nóng lò ở 200C/Gas 6/quạt 180C. Cắt bỏ phần đầu gỗ của măng tây và bỏ đi. Xếp măng tây thành một lớp trong khay nướng có các cạnh. Cắt cà chua làm đôi theo chiều ngang, trộn chúng với măng tây, nêm muối biển và hạt tiêu rồi rưới dầu ô liu. Cuộn từng miếng thịt xông khói thành một cuộn chặt (nếu lớn, trước tiên hãy cắt làm đôi theo chiều ngang) và xếp vào khay. Rưới mật ong lên cuộn thịt xông khói và nướng trong 20 phút cho đến khi cà chua mềm và thịt xông khói giòn.', NULL, '2026-05-15 14:42:52', '2026-05-16 12:35:34'),
(2022, 300, 2, 'Trong lúc đó, luộc khoai tây cho đến khi mềm. Đánh đều giấm, dầu ô liu, mù tạt, một ít muối biển và hạt tiêu vào tô lớn cho đến khi hòa quyện. Cho lá tên lửa hoặc rau bina vào một nửa nước sốt và bày lên đĩa phục vụ lớn.', NULL, '2026-05-15 14:42:52', '2026-05-16 12:35:34'),
(2024, 300, 3, 'Xả khoai tây và cắt làm đôi. Nhẹ nhàng trộn chúng với phần nước sốt còn lại và xếp lên đĩa cùng với măng tây. Nhét cà chua và thịt xông khói vào.', NULL, '2026-05-15 14:42:52', '2026-05-16 12:35:34'),
(2025, 301, 1, 'Kết hợp thịt lợn, tỏi, gừng, nước tương, dầu mè và rau vào tô.', NULL, '2026-05-15 14:42:54', '2026-05-15 14:42:54'),
(2026, 301, 2, 'Tách vỏ hoành thánh.', NULL, '2026-05-15 14:42:54', '2026-05-15 14:42:54'),
(2027, 301, 3, 'Đặt một thìa cà phê nhân vào giữa hoành thánh.', NULL, '2026-05-15 14:42:54', '2026-05-15 14:42:54'),
(2028, 301, 4, 'Quét nước lên 2 viền da, cách mép 1/4 inch.', NULL, '2026-05-15 14:42:54', '2026-05-15 14:42:54'),
(2029, 301, 5, 'Gấp da lại để tạo thành hình tam giác, dán kín các cạnh.', NULL, '2026-05-15 14:42:54', '2026-05-15 14:42:54'),
(2030, 301, 6, 'Chụm hai điểm dài bên ngoài lại với nhau.', NULL, '2026-05-15 14:42:54', '2026-05-15 14:42:54'),
(2031, 301, 7, 'Đun nóng dầu đến 450 độ và chiên lần lượt 4 đến 5 miếng cho đến khi vàng.', NULL, '2026-05-15 14:42:54', '2026-05-15 14:42:54'),
(2032, 301, 8, 'Xả và phục vụ với nước sốt.', NULL, '2026-05-15 14:42:54', '2026-05-15 14:42:54'),
(2034, 302, 1, 'Làm nóng lò ở nhiệt độ 200C/180C quạt/gas 6. Nướng bánh mì baguette trên khay nướng trong 8-10 phút, sau đó để nguội.', NULL, '2026-05-15 14:42:56', '2026-05-16 12:35:34'),
(2036, 302, 2, 'Đun nóng 2 thìa bơ và 1 thìa dầu trong chảo trên lửa nhỏ rồi xào hành tây xắt nhỏ trong 5 phút cho đến khi mềm. Cho nấm vào, vặn lửa vừa và nấu thêm 5-10 phút nữa cho đến khi rau mềm và nước nấm bay hơi hết. Khuấy tỏi và nấu trong 1-2 phút cho đến khi mềm. Nêm gia vị, sau đó cho sốt mayonnaise vào khuấy đều và tắt bếp.', NULL, '2026-05-15 14:42:56', '2026-05-16 12:35:34'),
(2038, 302, 3, 'Cắt đôi bánh mì baguette theo chiều dọc, sau đó đặt trở lại khay nướng, cắt thành từng mặt và phết lên hỗn hợp nấm, sau đó rắc lên phô mai cheddar, giăm bông, kabanos và mozzarella. Nướng trong 8-10 phút hoặc cho đến khi phô mai tan chảy và chuyển sang màu vàng.', NULL, '2026-05-15 14:42:56', '2026-05-16 12:35:34'),
(2040, 302, 4, 'Trong khi đó, đun nóng phần bơ và dầu còn lại trong chảo trên lửa vừa và xào hành tây thái lát trong 5 phút cho đến khi vàng và mềm. Hủy bỏ nhiệt và đặt sang một bên. Sau khi pizza đã chín, phủ hành tây caramen, dưa chua thì là (nếu dùng), hẹ và một chút sốt cà chua theo hình zig-zag lên trên.', NULL, '2026-05-15 14:42:56', '2026-05-16 12:35:34'),
(2041, 303, 1, 'Trộn các nguyên liệu làm nước sốt vào một bát nhỏ và nêm muối và hạt tiêu. Đặt sang một bên.', NULL, '2026-05-15 14:43:02', '2026-05-15 14:43:02'),
(2042, 303, 2, 'Nấu mì ống theo hướng dẫn trên gói. Thêm đậu Hà Lan có đường vào phút cuối cùng của thời gian nấu.', NULL, '2026-05-15 14:43:02', '2026-05-15 14:43:02'),
(2043, 303, 3, 'Trong khi đó, làm nóng dầu trong chảo hoặc chảo rán lớn, cho tỏi và ớt vào nấu trên lửa khá nhẹ trong khoảng 30 giây mà không để tỏi chuyển sang màu nâu. Cho tôm vào nấu trên lửa lớn, khuấy thường xuyên trong khoảng 3 phút cho đến khi tôm chuyển sang màu hồng.', NULL, '2026-05-15 14:43:02', '2026-05-15 14:43:02'),
(2044, 303, 4, 'Thêm cà chua vào và nấu, thỉnh thoảng khuấy trong 3 phút cho đến khi chúng bắt đầu mềm. Xả sạch mì và đường rồi trộn vào hỗn hợp tôm. Xé lá húng quế, khuấy đều và nêm muối và hạt tiêu.', NULL, '2026-05-15 14:43:02', '2026-05-15 14:43:02'),
(2045, 303, 5, 'Ăn kèm lá salad rưới nước sốt chanh và bánh mì giòn nóng.', NULL, '2026-05-15 14:43:02', '2026-05-15 14:43:02'),
(2046, 304, 1, 'Nấu mì ống theo hướng dẫn trên bao bì trong một nồi lớn có nước sôi và muối', NULL, '2026-05-15 14:43:05', '2026-05-15 14:43:05'),
(2047, 304, 2, 'Thêm kem đặc và bơ vào chảo lớn trên lửa vừa cho đến khi kem sủi bọt và bơ tan chảy', NULL, '2026-05-15 14:43:05', '2026-05-15 14:43:05'),
(2048, 304, 3, 'Đánh đều parmesan và thêm gia vị (muối và tiêu đen)', NULL, '2026-05-15 14:43:05', '2026-05-15 14:43:05'),
(2049, 304, 4, 'Để nước sốt đặc lại một chút rồi thêm mì ống vào đảo đều cho đến khi phủ đầy nước sốt', NULL, '2026-05-15 14:43:05', '2026-05-15 14:43:05'),
(2050, 304, 5, 'Trang trí với rau mùi tây và thế là xong', NULL, '2026-05-15 14:43:05', '2026-05-15 14:43:05'),
(2051, 305, 1, 'Trong một cái chảo vừa, khuấy kem đông, bơ và bột ngô trên lửa nhỏ và đun nhỏ lửa. Tắt lửa và giữ ấm.', NULL, '2026-05-15 14:43:08', '2026-05-15 14:43:08'),
(2052, 305, 2, 'Trong khi đó, cho phô mai và hạt nhục đậu khấu vào một cái bát nhỏ rồi thêm một ít tiêu đen xay nhuyễn, sau đó khuấy đều mọi thứ lại với nhau (không thêm muối ở giai đoạn này).', NULL, '2026-05-15 14:43:08', '2026-05-15 14:43:08'),
(2053, 305, 3, 'Cho mì ống vào một chảo khác với 2 thìa cà phê muối, đổ một ít nước sôi và nấu theo hướng dẫn trên bao bì (thường là 3-4 phút). Khi nấu chín, múc một ít nước nấu vào bình hoặc ca chịu nhiệt rồi để ráo mì nhưng không quá kỹ.', NULL, '2026-05-15 14:43:08', '2026-05-15 14:43:08'),
(2054, 305, 4, 'Thêm mì ống vào chảo với hỗn hợp kem đông, sau đó rắc phô mai lên và nhẹ nhàng gấp mọi thứ lại với nhau trên lửa nhỏ bằng thìa cao su. Khi kết hợp, cho 3 muỗng canh nước nấu vào. Lúc đầu, mì sẽ trông ướt và luộm thuộm: tiếp tục khuấy cho đến khi nước ngấm và nước sốt sánh bóng. Kiểm tra gia vị trước khi chuyển sang bát đã đun nóng. Rắc lên một ít hẹ hoặc rau mùi tây, sau đó dùng ngay.', NULL, '2026-05-15 14:43:08', '2026-05-15 14:43:08'),
(2055, 306, 1, 'Làm mac và phô mai', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2056, 306, 2, '1. Đun sôi một nồi nước vừa có nhiều muối (bạn muốn nước có vị như nước biển). Thêm mì ống vào và nấu, thỉnh thoảng khuấy cho đến khi chín tới, từ 8 đến 10 phút hoặc theo hướng dẫn trên bao bì. Sợi mì phải mềm nhưng vẫn dai.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2057, 306, 3, '2. Trong khi nấu mì ống, trong một tô nhỏ, trộn đều bột mì, bột mù tạt, bột tỏi, muối, tiêu đen và ớt cayenne.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2058, 306, 4, '3. Xả mì ống vào một cái chao. Đặt chảo mì ống rỗng (không cần rửa) trên lửa nhỏ và thêm bơ vào. Khi bơ tan chảy, cho hỗn hợp bột vào tiếp tục nấu, đánh đều cho đến khi hỗn hợp bắt đầu chuyển sang màu nâu và có mùi thơm hấp dẫn dễ chịu, khoảng 1 phút. Chú ý canh cẩn thận để không bị cháy sém dưới đáy chảo.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2059, 306, 5, '4. Từ từ đánh sữa và kem vào hỗn hợp bột cho đến khi mọi thứ thật sự hòa quyện. Nấu, khuấy liên tục cho đến khi nước sốt nóng lên và bắt đầu đặc lại, khoảng 2 phút. Hủy bỏ khỏi nhiệt. Dần dần thêm phô mai vào trong khi khuấy liên tục bằng thìa gỗ hoặc thìa silicone và tiếp tục khuấy cho đến khi phô mai tan chảy vào nước sốt. Sau đó cho mì đã luộc chín vào trộn đều.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2060, 306, 6, '5. Lót giấy nến hoặc giấy nhôm vào khay nướng có viền kích thước 9 x 13 inch (23 x 33 cm). Phủ giấy hoặc giấy bạc bằng bình xịt nấu ăn không dính hoặc bôi bơ. Đổ mac và phô mai ấm lên khay nướng đã chuẩn bị sẵn và dùng thìa trải đều. Phủ một miếng giấy da khác bằng bình xịt nấu ăn hoặc bơ rồi đặt mặt đã phết dầu hoặc bơ xuống dưới, trực tiếp lên bề mặt của mac và pho mát. Làm lạnh cho đến khi nguội và chắc, khoảng 1 giờ.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2061, 306, 7, 'Làm phô mai nướng', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2062, 306, 8, '6. Đun nóng chảo gang lớn hoặc chảo chống dính trên lửa vừa và nhỏ.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2063, 306, 9, '7. Trong một tô nhỏ, khuấy đều 4 thìa canh (55 gam) bơ và bột tỏi cho đến khi hòa quyện.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2064, 306, 10, '8. Lấy mac và phô mai ra khỏi tủ lạnh và bóc lớp giấy da trên cùng. Cẩn thận cắt thành 8 miếng bằng nhau. Mỗi miếng sẽ làm được 1 chiếc bánh mì mac nướng và phô mai. (Bạn có thể bảo quản từng phần riêng lẻ trong túi nhựa hai lớp có thể khóa lại và để trong tủ lạnh tối đa 3 ngày hoặc đông lạnh tối đa 1 tháng.)', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2065, 306, 11, '9. Phết 3/4 thìa cà phê bơ tỏi lên một mặt của mỗi lát bánh mì. Đặt một nửa số lát đã phết bơ úp xuống trên thớt sạch. Trên mỗi miếng có một lát Cheddar, sau đó là 1 miếng mac và pho mát. (Chuyển từ khay nướng bằng cách quét tay hoặc thìa dưới từng miếng mac và phô mai, sau đó lật nó lên trên một chiếc bánh sandwich.) Đặt 1 lát Jack lên trên mỗi miếng. Kết thúc với những lát bánh mì còn lại, phết bơ lên ​​trên.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2066, 306, 12, '10. Dùng một chiếc thìa rộng, đặt càng nhiều bánh sandwich vào chảo càng tốt mà không làm bánh bị dồn. Đậy nắp và nấu cho đến khi mặt dưới có màu nâu đẹp mắt, khoảng 4 phút. Lật và nấu cho đến khi các mặt thứ hai chuyển sang màu nâu, phô mai tan chảy, mac và phô mai được đun nóng trong khoảng 4 phút nữa.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2067, 306, 13, '11. Lặp lại với các nguyên liệu còn lại. Cắt đôi bánh sandwich nếu muốn và thưởng thức.', NULL, '2026-05-15 14:43:11', '2026-05-15 14:43:11'),
(2068, 307, 1, '1. Trong một bát nhỏ, trộn bốn nguyên liệu đầu tiên; phết lên bốn lát bánh mì. Lớp với thịt xông khói, cà chua và phô mai; phủ bánh mì còn lại lên trên.', NULL, '2026-05-15 14:43:14', '2026-05-15 14:43:14'),
(2069, 307, 2, '2. Làm tan chảy 2 thìa bơ trong chảo hoặc vỉ nướng lớn. Nướng bánh mì sandwich cho đến khi vàng nhạt cả hai mặt và phô mai tan chảy, thêm bơ nếu cần.', NULL, '2026-05-15 14:43:14', '2026-05-15 14:43:14'),
(2070, 307, 3, 'Thành phần dinh dưỡng', NULL, '2026-05-15 14:43:14', '2026-05-15 14:43:14'),
(2071, 307, 4, '1 bánh sandwich: 445 calo, 24g chất béo (12g chất béo bão hòa), 66mg cholesterol, 1094mg natri, 35g carbohydrate (3g đường, 2g chất xơ), 21g protein.', NULL, '2026-05-15 14:43:14', '2026-05-15 14:43:14'),
(2072, 308, 1, 'Đun nóng dầu trong chảo lớn. Dùng kéo nhà bếp để cắt thịt xông khói thành từng miếng nhỏ hoặc dùng dao sắc để cắt thịt trên thớt. Thêm thịt xông khói vào chảo và nấu chỉ trong vài phút cho đến khi bắt đầu chuyển sang màu vàng. Thêm hành tây, cần tây và cà rốt vào nấu trên lửa vừa trong 5 phút, thỉnh thoảng khuấy đều cho đến khi mềm.', NULL, '2026-05-15 14:43:17', '2026-05-15 14:43:17'),
(2073, 308, 2, 'Thêm tỏi và nấu trong 1 phút, sau đó cho thịt băm vào nấu, khuấy đều và bẻ nhỏ bằng thìa gỗ trong khoảng 6 phút cho đến khi tỏi chín vàng.', NULL, '2026-05-15 14:43:17', '2026-05-15 14:43:17'),
(2074, 308, 3, 'Khuấy nhuyễn cà chua và nấu trong 1 phút, trộn đều với thịt bò và rau. Mẹo trong cà chua xắt nhỏ. Đổ đầy nước vào từng lon một nửa để rửa sạch cà chua còn sót lại trong lon rồi cho vào chảo. Thêm mật ong và nêm nếm cho vừa ăn. Đun nhỏ lửa trong 20 phút.', NULL, '2026-05-15 14:43:17', '2026-05-15 14:43:17'),
(2075, 308, 4, 'Làm nóng lò nướng ở mức quạt/gas 200C/180C 6. Để làm món lasagne, múc một ít nước sốt ragu vào đáy hộp thiếc nướng hoặc đĩa thịt hầm, phết nước sốt lên khắp đế. Đặt 2 tấm lasagne lên trên lớp nước sốt chồng lên nhau cho vừa miệng, sau đó lặp lại với nhiều nước sốt hơn và một lớp mì ống khác. Lặp lại với 2 lớp nước sốt và mì ống nữa, kết thúc bằng một lớp mì ống.', NULL, '2026-05-15 14:43:17', '2026-05-15 14:43:17'),
(2076, 308, 5, 'Cho kem tươi vào tô và trộn với 2 muỗng canh nước để tạo thành nước sốt mịn có thể rót được. Đổ thứ này lên trên mì ống, sau đó phủ mozzarella lên trên. Rắc Parmesan lên trên và nướng trong 25–30 phút cho đến khi vàng và sủi bọt. Ăn kèm với húng quế nếu bạn thích.', NULL, '2026-05-15 14:43:17', '2026-05-15 14:43:17'),
(2077, 309, 1, 'Nấu mì ống theo hướng dẫn gói. Đun nóng dầu trong chảo chống dính rồi cho hành, tỏi, ớt vào xào khoảng 3-4 phút cho mềm. Khuấy nhuyễn cà chua và nấu trong 1 phút, sau đó thêm hành tây với nước sốt của chúng. Nấu chín, dùng thìa gỗ bẻ cá, sau đó thêm ô liu vào và tiếp tục nấu thêm vài phút nữa.', NULL, '2026-05-15 14:43:22', '2026-05-15 14:43:22'),
(2078, 309, 2, 'Xả mì ống và cho vào chảo cùng với 2-3 muỗng canh nước nấu. Trộn đều mọi thứ lại với nhau, sau đó chia ra các đĩa và thưởng thức, rải đều với Parmesan.', NULL, '2026-05-15 14:43:22', '2026-05-15 14:43:22'),
(2079, 310, 1, 'BƯỚC 1', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2080, 310, 2, 'Đặt một nồi nước lớn vào đun sôi.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2081, 310, 3, 'BƯỚC 2', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2082, 310, 4, 'Cắt nhỏ 100g pancetta, trước tiên đã loại bỏ vỏ. Nghiền mịn 50g phô mai pecorino và 50g parmesan rồi trộn đều.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2083, 310, 5, 'BƯỚC 3', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2084, 310, 6, 'Đánh 3 quả trứng lớn vào tô vừa và nêm một ít hạt tiêu đen mới xay. Đặt mọi thứ sang một bên.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2085, 310, 7, 'BƯỚC 4', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2086, 310, 8, 'Cho 1 thìa cà phê muối vào nước sôi, thêm 350g mì spaghetti vào và khi nước sôi trở lại thì đun nhỏ lửa, đậy nắp trong 10 phút hoặc cho đến khi chín vừa.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2087, 310, 9, 'BƯỚC 5', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2088, 310, 10, 'Dùng dao gọt vỏ 2 tép tỏi mọng nước chỉ để bầm dập.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2089, 310, 11, 'BƯỚC 6', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2090, 310, 12, 'Trong khi mì spaghetti đang nấu, hãy chiên pancetta với tỏi. Thả 50g bơ không muối vào chảo hoặc chảo lớn và ngay khi bơ tan chảy, cho pancetta và tỏi vào.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2091, 310, 13, 'BƯỚC 7', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2092, 310, 14, 'Để nấu trên lửa vừa trong khoảng 5 phút, khuấy thường xuyên cho đến khi pancetta vàng và giòn. Tỏi lúc này đã có mùi thơm, vì vậy hãy dùng thìa có rãnh vớt tỏi ra và vứt đi.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2093, 310, 15, 'BƯỚC 8', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2094, 310, 16, 'Giữ nhiệt dưới pancetta ở mức thấp. Khi mì ống đã sẵn sàng, hãy nhấc mì ống lên khỏi mặt nước bằng nĩa hoặc kẹp mì ống và cho vào chảo rán cùng với pancetta. Đừng lo lắng nếu có một ít nước rơi vào chảo (bạn muốn điều này xảy ra) và đừng vội vứt nước mì ống đi.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2095, 310, 17, 'BƯỚC 9', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2096, 310, 18, 'Trộn hầu hết phô mai với trứng, giữ lại một ít để rắc lên sau.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2097, 310, 19, 'BƯỚC 10', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2098, 310, 20, 'Nhấc chảo spaghetti và pancetta ra khỏi bếp. Bây giờ nhanh chóng đổ trứng và phô mai vào. Dùng kẹp hoặc nĩa dài nhấc mì spaghetti lên để dễ dàng trộn với hỗn hợp trứng, hỗn hợp này đặc lại nhưng không bị vón cục và mọi thứ đều được phủ đều.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2099, 310, 21, 'BƯỚC 11', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2100, 310, 22, 'Thêm thêm nước nấu mì ống để giữ độ xốt (nên dùng vài thìa canh). Bạn không muốn nó ướt, chỉ ẩm thôi. Nêm một chút muối nếu cần.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2101, 310, 23, 'BƯỚC 12', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2102, 310, 24, 'Dùng một chiếc nĩa có ngạnh dài để vặn mì vào đĩa hoặc bát phục vụ. Ăn ngay với một ít phô mai còn lại và rắc một ít hạt tiêu đen. Nếu món ăn hơi khô trước khi dùng, hãy rưới thêm một ít nước mì nóng vào và nước sốt bóng loáng sẽ được hồi sinh.', NULL, '2026-05-15 14:43:25', '2026-05-15 14:43:25'),
(2103, 311, 1, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C). Bôi mỡ vào đĩa nướng 9x13 inch.', NULL, '2026-05-15 14:43:28', '2026-05-15 14:43:28'),
(2104, 311, 2, 'Đun sôi một nồi lớn nước muối nhẹ. Thêm spaghetti và nấu trong 8 đến 10 phút hoặc cho đến khi chín; để ráo nước và khuấy đều với nước sốt cà chua, bột cà chua, quế, dầu, muối và hạt tiêu. Chuyển sang món ăn đã chuẩn bị.', NULL, '2026-05-15 14:43:28', '2026-05-15 14:43:28'),
(2105, 311, 3, 'Nướng trong lò làm nóng trước trong 1 giờ hoặc cho đến khi mặt trên giòn.', NULL, '2026-05-15 14:43:28', '2026-05-15 14:43:28'),
(2106, 312, 1, 'Đun nóng dầu trong chảo lớn. Thêm chân vịt vào và chiên chín vàng các mặt trong khoảng 10 phút. Đổ ra đĩa và đặt sang một bên. Thêm hành tây vào chảo và nấu trong 5 phút cho đến khi mềm. Thêm tỏi và nấu thêm 1 phút nữa, sau đó cho quế và bột mì vào đảo đều và nấu thêm một phút nữa. Cho vịt trở lại chảo, thêm rượu, cà chua, nước kho, rau thơm, đường và gia vị. Đun sôi, sau đó giảm nhiệt, đậy nắp và nấu trong 2 giờ, thỉnh thoảng khuấy.', NULL, '2026-05-15 14:43:30', '2026-05-15 14:43:30'),
(2107, 312, 2, 'Cẩn thận nhấc chân vịt ra khỏi nước sốt và đặt vào đĩa - chúng sẽ rất mềm nên cố gắng không để mất miếng thịt nào. Gọt vỏ và loại bỏ mỡ, sau đó dùng 2 nĩa xé thịt và bỏ xương. Cho thịt trở lại nước sốt với sữa và đun nhỏ lửa, không đậy nắp, thêm 10-15 phút nữa trong khi nấu mì ống.', NULL, '2026-05-15 14:43:30', '2026-05-15 14:43:30'),
(2108, 312, 3, 'Nấu mì ống theo hướng dẫn trên bao bì, sau đó để ráo nước, chừa lại một cốc nước mì ống và thêm mì ống vào ragu. Khuấy để phủ tất cả mì ống vào nước sốt và nấu thêm 1 phút nữa, thêm một chút nước nấu nếu thấy khô. Ăn kèm với Parmesan bào, nếu bạn thích.', NULL, '2026-05-15 14:43:30', '2026-05-15 14:43:30'),
(2109, 313, 1, 'Trộn bột mì, muối, đường, baking soda và bạch đậu khấu với nhau trong một tô lớn.', NULL, '2026-05-15 14:43:34', '2026-05-15 14:43:34'),
(2110, 313, 2, 'Tách trứng và thêm lòng đỏ trứng vào hỗn hợp bột. Đổ buttermilk (hoặc sữa nuôi cấy) vào và đánh bột cho đến khi mịn. Đậy nắp và để lạnh trong khoảng 30 phút.', NULL, '2026-05-15 14:43:34', '2026-05-15 14:43:34'),
(2111, 313, 3, 'Dùng máy trộn cầm tay (hoặc đứng) để đánh lòng trắng trứng cho đến khi bông cứng. Cẩn thận gấp vào bột æbleskiver.', NULL, '2026-05-15 14:43:34', '2026-05-15 14:43:34'),
(2112, 313, 4, 'Đun nóng chảo ở lửa vừa. Sau khi nóng, phết bơ vào chảo và đổ bột vào gần đầy từng lỗ æbleskive.', NULL, '2026-05-15 14:43:34', '2026-05-15 14:43:34'),
(2113, 313, 5, 'Khi các cạnh đã cứng lại, hãy dùng kim đan hoặc xiên gỗ để xoay æbleskiver khoảng 1/4. Tiếp tục xoay cho đến khi bạn có được những quả cầu bánh pancake tròn. Chúng phải có màu nâu vàng.', NULL, '2026-05-15 14:43:34', '2026-05-15 14:43:34'),
(2114, 313, 6, 'Lấy æbleskiver ra khỏi chảo và dùng kèm với đường bột và mứt.', NULL, '2026-05-15 14:43:34', '2026-05-15 14:43:34'),
(2115, 314, 1, 'Làm bột: Kem bơ và đường. Thêm lòng đỏ trứng và vỏ chanh. Dần dần trộn bột mì và bột bắp để tạo thành một khối bột. Thư giãn trong 1 giờ.', NULL, '2026-05-15 14:43:37', '2026-05-15 14:43:37'),
(2116, 314, 2, 'Nướng bánh quy: Cán bột, cắt thành hình tròn và nướng ở nhiệt độ 180°C (350°F) trong 12-15 phút. Để nguội.', NULL, '2026-05-15 14:43:37', '2026-05-15 14:43:37'),
(2117, 314, 3, 'Lắp ráp: Trải dulce de leche lên một chiếc bánh quy, sau đó kẹp với một chiếc bánh quy khác. Cuộn các cạnh trong mảnh dừa.', NULL, '2026-05-15 14:43:37', '2026-05-15 14:43:37'),
(2118, 314, 4, 'Lời khuyên chuyên nghiệp:', NULL, '2026-05-15 14:43:37', '2026-05-15 14:43:37'),
(2119, 314, 5, 'Làm lạnh bột trước khi cán mỏng để dễ xử lý hơn và tránh bánh bị nở quá nhiều trong khi nướng.', NULL, '2026-05-15 14:43:37', '2026-05-15 14:43:37'),
(2120, 314, 6, 'Nhúng alfajores vào sô cô la tan chảy và đặt chúng trên giá lưới để có một món ăn ngon hơn.', NULL, '2026-05-15 14:43:37', '2026-05-15 14:43:37'),
(2122, 315, 1, 'Làm nóng lò ở 180C/quạt 160C/gas 4. Cho yến mạch, dừa, bột mì và đường vào tô. Đun chảy bơ trong chảo nhỏ và cho xi-rô vàng vào khuấy đều. Thêm bicarbonate soda vào 2 muỗng canh nước sôi, sau đó khuấy đều vào hỗn hợp xi-rô vàng và bơ.', NULL, '2026-05-15 14:43:39', '2026-05-16 12:35:34'),
(2124, 315, 2, 'Tạo một cái giếng ở giữa nguyên liệu khô và đổ hỗn hợp bơ và xi-rô vàng vào. Khuấy nhẹ nhàng để kết hợp các thành phần khô.', NULL, '2026-05-15 14:43:39', '2026-05-16 12:35:34'),
(2126, 315, 3, 'Đặt các thìa hỗn hợp tráng miệng lên khay nướng đã phết bơ, cách nhau khoảng 2,5cm/1in để có chỗ trải đều. Nướng từng mẻ trong 8-10 phút cho đến khi vàng. Chuyển sang giá dây để nguội.', NULL, '2026-05-15 14:43:39', '2026-05-16 12:35:34'),
(2127, 316, 1, 'Trộn sữa, dầu và trứng với nhau. Rây bột mì, bột nở và muối vào hỗn hợp. Khuấy đều cho đến khi tất cả các thành phần được kết hợp đồng đều.', NULL, '2026-05-15 14:43:42', '2026-05-15 14:43:42'),
(2128, 316, 2, 'Trải một ít bột lên chảo. Trải một lớp bột mỏng lên thành chảo. Đậy chảo trong 30-60 giây cho đến khi xuất hiện bọt khí nhỏ.', NULL, '2026-05-15 14:43:42', '2026-05-15 14:43:42'),
(2129, 316, 3, 'Thêm bơ, bắp kem, đậu phộng giã nhuyễn và đường vào bánh pancake. Gấp bánh pancake làm đôi khi mặt dưới đã chín vàng.', NULL, '2026-05-15 14:43:42', '2026-05-15 14:43:42'),
(2130, 316, 4, 'Cắt thành từng miếng vừa ăn và ăn ngon nhất khi còn ấm.', NULL, '2026-05-15 14:43:42', '2026-05-15 14:43:42'),
(2131, 317, 1, 'Làm nóng lò ở nhiệt độ 190C/170C quạt/gas 5. Cho bột mì và đường vào tô lớn. Thêm bơ, sau đó dùng đầu ngón tay chà xát vào bột để tạo kết cấu vụn bánh mì nhẹ. Đừng làm việc quá sức nếu không mảnh vụn sẽ trở nên nặng nề. Rắc đều hỗn hợp lên khay nướng và nướng trong 15 phút hoặc cho đến khi có màu nhạt.', NULL, '2026-05-15 14:43:46', '2026-05-15 14:43:46'),
(2132, 317, 2, 'Trong khi đó, đối với món compote, gọt vỏ, bỏ lõi và cắt táo thành xúc xắc 2cm. Cho bơ và đường vào nồi vừa và đun chảy với lửa vừa. Nấu trong 3 phút cho đến khi hỗn hợp chuyển sang màu caramel nhẹ. Cho táo vào và nấu trong 3 phút. Thêm quả mâm xôi và quế vào nấu thêm 3 phút nữa. Đậy nắp, tắt bếp, sau đó để khoảng 2-3 phút để tiếp tục nấu trên chảo ấm.', NULL, '2026-05-15 14:43:46', '2026-05-15 14:43:46'),
(2133, 317, 3, 'Để phục vụ, hãy múc trái cây còn ấm vào đĩa gratin chịu nhiệt, phủ hỗn hợp vụn lên trên, sau đó hâm nóng trong lò trong 5-10 phút. Ăn kèm với kem vani.', NULL, '2026-05-15 14:43:46', '2026-05-15 14:43:46'),
(2134, 318, 1, 'Làm nóng lò ở nhiệt độ 180°C. (350˚F) Bôi mỡ vào chảo bánh và lót giấy nướng.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2135, 318, 2, 'Trong một tô lớn, đập bốn quả trứng với đường và đánh cho đến khi chúng nở gấp ba lần và trở nên bông xốp.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2136, 318, 3, 'Rây bột nở tự nổi và thêm vào hỗn hợp trứng của bạn. Gấp cái này lại, bảo quản càng nhiều không khí càng tốt. Thêm bơ tan chảy (và hơi nguội) vào và trộn cho đến khi hòa quyện.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2137, 318, 4, 'Thêm quế, một chút muối và chiết xuất vani.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2138, 318, 5, 'Thêm táo thái hạt lựu vào bột và nhẹ nhàng gấp chúng vào bột để các miếng táo được phân bố đều. Bạn có thể lăn những miếng táo qua một ít quế.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2139, 318, 6, 'Đổ bột vào chảo bánh đã chuẩn bị sẵn và dùng thìa làm mịn phần trên.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2140, 318, 7, 'Đặt các lát táo lên trên mặt bột và ấn nhẹ. Tùy ý rắc một ít vỏ hạnh nhân.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2141, 318, 8, 'Nướng bánh táo trong lò làm nóng trước khoảng 45-50 phút, hoặc cho đến khi xiên que gỗ vào giữa bánh thấy tăm sạch sẽ.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2142, 318, 9, 'Lấy bánh ra khỏi lò và để nguội trong khuôn vài phút. Sau đó cẩn thận lấy bánh ra khỏi khuôn và để nguội hoàn toàn trên giá lưới.', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2143, 318, 10, 'Rắc đường bột lên bánh táo đã nguội', NULL, '2026-05-15 14:43:50', '2026-05-15 14:43:50'),
(2144, 319, 1, 'Làm nóng lò ở mức quạt/gas 200C/180C 6.', NULL, '2026-05-15 14:43:54', '2026-05-15 14:43:54'),
(2145, 319, 2, 'Đặt bánh quy vào một túi đông lạnh lớn có thể bịt kín lại và dùng cán cán thành từng miếng vụn mịn. Đun chảy bơ trong chảo nhỏ, sau đó cho vụn bánh quy vào và khuấy đều cho đến khi bơ phủ đều. Đổ bánh tart vào khuôn và dùng mặt sau của thìa ấn lên đáy và các cạnh của khuôn để tạo thành một lớp đều. Làm lạnh trong tủ lạnh trong khi bạn làm nhân.', NULL, '2026-05-15 14:43:54', '2026-05-15 14:43:54'),
(2146, 319, 3, 'Đánh bơ và đường cùng nhau cho đến khi mịn và nhạt màu. Bạn có thể làm điều này trong máy xay thực phẩm nếu có. Quá trình trong 2-3 phút. Trộn trứng vào, sau đó thêm hạnh nhân xay và chiết xuất hạnh nhân vào, trộn đều cho đến khi hòa quyện.', NULL, '2026-05-15 14:43:54', '2026-05-15 14:43:54'),
(2147, 319, 4, 'Gọt vỏ táo, cắt thành từng lát mỏng. Làm điều này vào phút cuối để táo không bị chuyển sang màu nâu. Xếp các lát bánh lên trên đế bánh quy. Trải đều nhân frangipane lên trên. Làm phẳng bề mặt và rắc hạnh nhân vụn.', NULL, '2026-05-15 14:43:54', '2026-05-15 14:43:54'),
(2148, 319, 5, 'Nướng trong 20-25 phút cho đến khi có màu vàng nâu và chín.', NULL, '2026-05-15 14:43:54', '2026-05-15 14:43:54'),
(2149, 319, 6, 'Lấy ra khỏi lò và để nguội trong 15 phút. Loại bỏ các cạnh của thiếc. Một cách dễ dàng để làm điều này là đặt hộp thiếc lên trên một lon đậu và ấn nhẹ xuống các cạnh của hộp thiếc.', NULL, '2026-05-15 14:43:54', '2026-05-15 14:43:54'),
(2150, 319, 7, 'Chuyển bánh tart đã gắn đế thiếc vào đĩa phục vụ. Ăn nóng với kem, crème fraiche hoặc kem.', NULL, '2026-05-15 14:43:54', '2026-05-15 14:43:54'),
(2152, 320, 1, 'Cho mascarpone, sữa chua, đường và nước hoa cam vào tô lớn và đánh đều cho đến khi đặc lại. Gấp các nguyên liệu còn lại lại, sau đó chia hỗn hợp vào 2 ly hoặc bát tráng miệng và trang trí thêm bạc hà nếu bạn thích.', NULL, '2026-05-15 14:43:57', '2026-05-16 12:35:34'),
(2153, 321, 1, 'Lấy bánh phồng của bạn ra khỏi tủ đông và rã đông.', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2154, 321, 2, 'Rắc một ít bột mì lên quầy bếp. Xếp các tấm bánh phồng lên nhau và dùng cán lăn chúng ra. Bạn muốn năm tờ giấy đó mỏng như một tờ giấy.', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2155, 321, 3, 'Dùng khuôn tròn hoặc hình bầu dục ấn vào bánh phồng và cố gắng làm điều đó một cách tiết kiệm nhất có thể. Bạn muốn có càng nhiều cookie càng tốt.', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2156, 321, 4, 'Trộn đường vani với quế, bạch đậu khấu và vỏ chanh trong một cái bát nhỏ', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2157, 321, 5, 'Lấy bột ra khỏi quầy và rắc một chút hỗn hợp đường.', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2158, 321, 6, 'Quét một ít nước rửa trứng lên bánh bông lan rồi nhúng vào hỗn hợp đường rồi lăn nhẹ để đường vào.', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2159, 321, 7, 'Đặt bánh phồng có đường của bạn lên khay nướng (đã phết dầu mỡ hoặc lót giấy nướng) và để bột nghỉ trong khoảng 20 đến 25 phút. điều này sẽ làm cho bánh quy giòn hơn.', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2160, 321, 8, 'Trong lúc đó làm nóng lò ở nhiệt độ 180 độ C rồi cho khay nướng vào lò nướng.', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2161, 321, 9, 'nướng bánh quy có màu nâu vàng trong khoảng 25 phút và đảm bảo đường được caramen đẹp mắt', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2162, 321, 10, 'Và thì đấy, Những cô gái đến từ Arnhem với phong cách Almeerse', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2163, 321, 11, 'Thì đấy, Arnhemse Meisjes đã gặp een Almeerse.', NULL, '2026-05-15 14:43:59', '2026-05-15 14:43:59'),
(2164, 322, 1, 'Nghiền hạnh nhân trong máy xay hạnh nhân hoặc máy chế biến thực phẩm.', NULL, '2026-05-15 14:44:03', '2026-05-15 14:44:03'),
(2165, 322, 2, 'Trộn hạnh nhân và đường bột với nhau trong một tô trộn lớn. Thêm ba lòng trắng trứng vào và dùng tay nhào bột cho đến khi bột thành một khối. Bọc trong màng bám và để trong tủ lạnh ít nhất một giờ, tốt nhất là đến ngày hôm sau.', NULL, '2026-05-15 14:44:03', '2026-05-15 14:44:03'),
(2166, 322, 3, 'Bôi mỡ kỹ vào các khuôn kransekake và phủ một lớp bột báng, bột mì hoặc vụn bánh mì.', NULL, '2026-05-15 14:44:03', '2026-05-15 14:44:03'),
(2167, 322, 4, 'Làm nóng lò ở nhiệt độ trên và dưới là 210°C (410°F). Chia bột thành sáu phần.', NULL, '2026-05-15 14:44:03', '2026-05-15 14:44:03'),
(2168, 322, 5, 'Từ từ thêm lòng trắng trứng còn lại vào bột và nhào cho đến khi bạn có thể cuộn thành những chiếc xúc xích dài dày bằng ngón trỏ. Đổ xúc xích bột vào khuôn, ghim các đầu lại với nhau để tạo thành các vòng.', NULL, '2026-05-15 14:44:03', '2026-05-15 14:44:03'),
(2169, 322, 6, 'Đặt các khuôn lên khay nướng và đặt lại vào giữa lò trong khoảng 10 - 12 phút, cho đến khi mặt trên có màu nâu vàng.', NULL, '2026-05-15 14:44:03', '2026-05-15 14:44:03'),
(2170, 323, 1, 'Để làm bánh ngọt, hãy đo lượng bột mì cho vào tô và dùng đầu ngón tay xoa bơ cho đến khi hỗn hợp giống như vụn bánh mì mịn. Thêm nước vào, trộn đều để tạo thành bột mềm.', NULL, '2026-05-15 14:44:05', '2026-05-15 14:44:05'),
(2171, 323, 2, 'Cán bột trên bề mặt đã rắc chút bột mì và dùng để lót khuôn bánh flan 20 cm/8 inch. Để trong tủ lạnh để ướp trong 30 phút.', NULL, '2026-05-15 14:44:05', '2026-05-15 14:44:05'),
(2172, 323, 3, 'Làm nóng lò ở mức 200C/400F/Gas 6 (quạt 180C).', NULL, '2026-05-15 14:44:05', '2026-05-15 14:44:05'),
(2173, 323, 4, 'Lót giấy bạc vào vỏ bánh ngọt và đổ đậu nướng vào. Nướng mù khoảng 15 phút, sau đó lấy đậu và giấy bạc ra rồi nấu thêm 5 phút nữa để đế khô.', NULL, '2026-05-15 14:44:05', '2026-05-15 14:44:05'),
(2174, 323, 5, 'Để dũa, phết một lớp mứt mâm xôi lên phần đế của chiếc bánh flan.', NULL, '2026-05-15 14:44:05', '2026-05-15 14:44:05'),
(2175, 323, 6, 'Đun chảy bơ trong chảo, tắt bếp rồi cho đường vào khuấy đều. Thêm hạnh nhân xay, trứng và chiết xuất hạnh nhân. Đổ vào khuôn bánh flan và rắc hạnh nhân đã vỡ vụn lên trên.', NULL, '2026-05-15 14:44:05', '2026-05-15 14:44:05');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(2176, 323, 7, 'Nướng trong khoảng 35 phút. Nếu hạnh nhân có vẻ chín vàng quá nhanh, hãy dùng giấy bạc bọc nhẹ bánh tart để tránh bị cháy.', NULL, '2026-05-15 14:44:05', '2026-05-15 14:44:05'),
(2178, 324, 1, 'Đầu tiên, làm xi-rô. Cho đường vào nồi lớn cùng 650ml nước. Khuấy trên lửa nhỏ cho đến khi đường tan hết thì vặn lửa lớn và đun sôi. Giảm nhiệt để đun nhỏ lửa và nấu trong 15 phút, sau đó vắt vào vài giọt nước cốt chanh và đun nhỏ lửa thêm 5 phút nữa. Hủy bỏ nhiệt và để nguội. Trong khi đó, để làm baklava sau này, hãy đun chảy bơ trong chảo nhỏ trên lửa nhỏ trong 5 phút, hớt bọt và loại bỏ bọt nổi lên trên bề mặt.', NULL, '2026-05-15 14:44:08', '2026-05-16 12:35:34'),
(2180, 324, 2, 'Để làm nhân, hãy nghiền nát tất cả các loại hạt bằng chày và cối, hoặc xay nhuyễn trong máy chế biến thực phẩm - bạn muốn có một hỗn hợp các loại hạt xay mịn với một vài miếng vụn. Đổ vào tô, trộn đều gia vị và đặt sang một bên.', NULL, '2026-05-15 14:44:08', '2026-05-16 12:35:34'),
(2182, 324, 3, 'Trong một bát riêng, trộn ricotta với vỏ chanh, vỏ cam và vani. Làm nóng lò nướng ở nhiệt độ 180C/160C quạt/gas 4. Quét một ít bơ tan chảy vào đáy khay nướng lớn (khoảng 35 x 47cm). Mỗi lần xử lý từng tờ filo (che phần còn lại bằng khăn trà ẩm để tránh bị khô), trải tờ giấy lên bảng sao cho một trong các đầu ngắn hướng về phía bạn. Rắc đều 30g hỗn hợp hạt lên toàn bộ tờ giấy, sau đó múc 1 muỗng canh hỗn hợp ricotta ở đầu gần bạn nhất. Gấp đầu này lại để bọc nhân, sau đó đặt một xiên dài và mỏng cạnh mép gấp rồi cuộn bánh ngọt xung quanh để tạo thành một cuộn dài. Khi cuộn lại hoàn toàn, nó sẽ có độ dày gần bằng xúc xích chipolata. Trong khi giữ một đầu của que cán hoặc xiên, nhẹ nhàng bóp cuộn filo như đàn xếp và cẩn thận đẩy nó ra khỏi xiên và lên khay đã chuẩn bị sẵn. Lặp lại với phần filo và phần nhân còn lại - bạn sẽ có được khoảng 12 cuộn. Cắt mỗi cuộn thành bốn để tạo thành 48 chiếc baklava lớn hoặc tám để tạo thành 96 chiếc bánh nhỏ.', NULL, '2026-05-15 14:44:08', '2026-05-16 12:35:34'),
(2184, 324, 4, 'Chải với bơ tan chảy còn lại. Nướng trong 20-25 phút cho đến khi vàng đều, lật khay lại nửa chừng. Khi còn nóng, đổ ngay 5-6 muôi si-rô vào. Bạn sẽ nghe thấy tiếng xi-rô xèo xèo khi chạm vào bánh baklava nóng. Đặt sang một bên để nguội và hấp thụ.', NULL, '2026-05-15 14:44:08', '2026-05-16 12:35:34'),
(2186, 324, 5, 'Đun chảy sô cô la đen trong một chiếc bát chịu nhiệt đặt trên chảo nước sôi, đảm bảo bát không chạm vào nước hoặc cho vào lò vi sóng trong thời gian ngắn. Rưới thứ này lên baklava đã nguội và rắc quả hồ trăn đã xay.', NULL, '2026-05-15 14:44:08', '2026-05-16 12:35:34'),
(2187, 325, 1, 'Trong một cái bát, nghiền chuối bằng nĩa cho đến khi nó giống như một hỗn hợp nhuyễn. Khuấy trứng, bột nở và vani.', NULL, '2026-05-15 14:44:12', '2026-05-15 14:44:12'),
(2188, 325, 2, 'Đun nóng chảo chống dính lớn hoặc chảo pancake trên lửa vừa và phết một nửa lượng dầu. Dùng một nửa lượng bột, múc hai chiếc bánh vào chảo, nướng mỗi mặt khoảng 1-2 phút rồi úp ra đĩa. Lặp lại quá trình với dầu và bột còn lại. Phủ hồ đào và quả mâm xôi lên trên bánh kếp.', NULL, '2026-05-15 14:44:12', '2026-05-15 14:44:12'),
(2189, 326, 1, 'Làm nóng lò nướng ở mức quạt/khí 4 180C/160C rồi lót giấy nến vào đáy và các cạnh của hộp thiếc vuông 20 cm (cách dễ nhất là đặt các dải dài 2 x 20 cm lên trên đế). Để làm bánh bông lan hạnh nhân, hãy cho bơ, đường, bột mì, hạnh nhân xay, bột nở, trứng, vani và chiết xuất hạnh nhân vào tô lớn. Đánh bằng máy đánh trứng điện cho đến khi hỗn hợp hòa quyện với nhau mịn màng. Cạo vào khuôn, dàn đều ra các góc và nướng trong 25-30 phút - khi bạn chọc xiên vào, xiên sẽ sạch. Làm nguội trong hộp thiếc trong 10 phút, sau đó chuyển sang giá lưới để nguội hoàn tất trong khi bạn làm miếng bọt biển thứ hai.', NULL, '2026-05-15 14:44:14', '2026-05-15 14:44:14'),
(2190, 326, 2, 'Đối với miếng bọt biển màu hồng, hãy lót hộp thiếc như trên. Trộn tất cả các thành phần với nhau như trên, nhưng không thêm chiết xuất hạnh nhân. Gấp một ít màu thực phẩm màu hồng vào. Sau đó cạo tất cả vào khuôn và nướng như trước. Mát mẻ.', NULL, '2026-05-15 14:44:14', '2026-05-15 14:44:14'),
(2191, 326, 3, 'Để lắp ráp, đun nóng mứt trong chảo nhỏ cho đến khi chảy nước, sau đó rây. Chỉ cần cắt tỉa hai cạnh đối diện của miếng bọt biển hạnh nhân, sau đó tỉa kỹ cạnh thứ ba. Đo đại khái chiều cao của miếng bọt biển, sau đó cắt từ mép đã được cắt tỉa cẩn thận, dùng thước giúp bạn cắt 4 lát, mỗi lát có chiều rộng bằng chiều cao của miếng bọt biển. Vứt bỏ hoặc gặm miếng bọt biển còn sót lại. Lặp lại với bánh màu hồng.', NULL, '2026-05-15 14:44:14', '2026-05-15 14:44:14'),
(2192, 326, 4, 'Lấy 2 x lát hạnh nhân và 2 x lát màu hồng và cắt sao cho chúng có cùng chiều dài. Cán một khối bánh hạnh nhân trên bề mặt có phủ một ít đường bột với chiều rộng chỉ hơn 20 cm, sau đó tiếp tục lăn theo chiều dọc cho đến khi bánh hạnh nhân dày khoảng 0,5 cm. Quét một lớp mứt mơ, sau đó đặt một lát bánh hạnh nhân và một lát màu hồng cạnh nhau ở một đầu của bánh hạnh nhân, phết mứt vào giữa để dính bọt biển và chừa lại phần bánh hạnh nhân trong suốt 4cm ở cuối. Quét thêm mứt lên trên miếng bọt biển, sau đó kẹp 2 lát còn lại lên trên, xen kẽ các màu để tạo hiệu ứng bàn cờ. Cắt bánh hạnh nhân theo chiều dài của bánh.', NULL, '2026-05-15 14:44:14', '2026-05-15 14:44:14'),
(2193, 326, 5, 'Cẩn thận nhấc bánh hạnh nhân lên và dùng tay dàn đều trên mặt bánh, nhưng để lại một nếp bánh hạnh nhân nhỏ dọc theo mép dưới trước khi dán vào mặt đầu tiên. Cắt cạnh đối diện để phù hợp với kích thước của nếp gấp, sau đó dùng ngón tay cái và ngón cái bấm các cạnh (hoặc đơn giản hơn là ấn bằng ngạnh nĩa). Nếu bạn thích, hãy đánh dấu 10 lát bằng cách sử dụng nĩa.', NULL, '2026-05-15 14:44:14', '2026-05-15 14:44:14'),
(2194, 326, 6, 'Lắp ráp Battenberg thứ hai và giữ trong hộp kín hoặc bọc kỹ trong màng bám trong tối đa 3 ngày. Có thể đông lạnh đến một tháng.', NULL, '2026-05-15 14:44:14', '2026-05-15 14:44:14'),
(2195, 327, 1, 'Trong tô của máy trộn đứng, thêm nước ấm, một chút đường và men. Để yên cho đến khi nổi bọt.', NULL, '2026-05-15 14:44:16', '2026-05-15 14:44:16'),
(2196, 327, 2, 'Trong cùng một bát, thêm 1/2 cốc đường, sữa ấm, bơ tan chảy, trứng và muối vào rồi đánh đều cho đến khi hòa quyện.', NULL, '2026-05-15 14:44:16', '2026-05-15 14:44:16'),
(2197, 327, 3, 'Đặt một cái móc bột vào máy trộn, thêm bột mì vào máy, cho đến khi tạo thành một khối bột mịn nhưng hơi dính.', NULL, '2026-05-15 14:44:16', '2026-05-15 14:44:16'),
(2198, 327, 4, 'Đặt bột vào tô, bọc bằng màng bọc thực phẩm và để bột ủ trong 1 tiếng rưỡi.', NULL, '2026-05-15 14:44:16', '2026-05-15 14:44:16'),
(2199, 327, 5, 'Cắt bột thành 12 miếng và cán thành những hình bầu dục dài dày khoảng 1/4 inch giống đuôi hải ly.', NULL, '2026-05-15 14:44:16', '2026-05-15 14:44:16'),
(2200, 327, 6, 'Trong một chiếc nồi lớn và sâu, đun nóng dầu ở nhiệt độ 350 độ. Nhẹ nhàng cho bột đuôi hải ly vào dầu nóng và chiên mỗi mặt từ 30 đến 45 giây cho đến khi có màu vàng nâu.', NULL, '2026-05-15 14:44:16', '2026-05-15 14:44:16'),
(2201, 327, 7, 'Xả trên khăn giấy và trang trí theo ý muốn. Thêm đường quế, đường trắng với một chút chanh hoặc với một ít Nutella và một ít hạnh nhân nướng. Thưởng thức!', NULL, '2026-05-15 14:44:16', '2026-05-15 14:44:16'),
(2203, 328, 1, 'Cho củ cải đường vào bình cùng với sữa và dùng máy xay sinh tố xay cho đến khi mịn. Đổ vào tô cùng với các nguyên liệu làm bánh pancake còn lại và đánh cho đến khi mịn và có màu tím rực rỡ.', NULL, '2026-05-15 14:44:19', '2026-05-16 12:35:34'),
(2205, 328, 2, 'Đặt một miếng bơ nhỏ vào chảo chống dính lớn và đun nóng ở lửa vừa-thấp cho đến khi tan chảy và nổi bọt. Bây giờ hãy tạo 3 hoặc 4 chiếc bánh kếp, mỗi chiếc được làm từ 2 muỗng canh bột. Nấu khoảng 2-3 phút rồi lật lại và nấu thêm một phút nữa cho đến khi chín. Lặp lại với bất kỳ bột còn lại. Làm nóng lò ở mức thấp nhất và giữ ấm bánh kếp trong đó cho đến khi cần.', NULL, '2026-05-15 14:44:19', '2026-05-16 12:35:34'),
(2207, 328, 3, 'Ăn kèm với lớp phủ bánh kếp yêu thích của bạn hoặc làm một món chế biến đơn giản bằng cách đun sôi quả mọng đông lạnh với 1 muỗng canh mứt lý chua đen cho đến khi sủi bọt và có dạng siro (khoảng 5-10 phút). Trong một bát nhỏ khuấy đều phần mứt còn lại và sữa chua. Xếp những chiếc bánh đã nấu chín với sữa chua và đổ hỗn hợp quả mọng ấm lên trên.', NULL, '2026-05-15 14:44:19', '2026-05-16 12:35:34'),
(2208, 329, 1, 'Đối với bánh quy, làm nóng lò nướng ở nhiệt độ 200C/180C (quạt)/Gas 6 và lót giấy nướng vào hai khay nướng lớn. Rải các loại hạt lên khay nướng và nướng trong lò khoảng 6-8 phút hoặc cho đến khi có màu vàng nâu. Hãy quan sát chúng cẩn thận để chúng không có cơ hội bị cháy. Lấy ra khỏi lò, đặt lên một tấm ván và để nguội.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2209, 329, 2, 'Cho bơ và đường vào tô lớn và đánh bằng thìa gỗ cho đến khi mịn và mịn như kem. Cắt nhỏ các loại hạt đã nguội rồi thêm vào bơ đánh kem và đường, cùng với vỏ chanh, bột mì và bột nở. Khuấy đều cho đến khi hỗn hợp hòa quyện và tạo thành một khối - bạn có thể phải dùng tay.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2210, 329, 3, 'Chia bột bánh quy thành 24 phần đều nhau và vo thành từng viên nhỏ. Đặt các viên bánh vào khay nướng đã chuẩn bị sẵn, cách đều nhau để có thể trải đều.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2211, 329, 4, 'Nhấn bánh quy để làm phẳng độ dày khoảng 1 cm/½ inch. Nướng bánh quy từng khay một trong 12 phút hoặc cho đến khi có màu nâu vàng nhạt. Để nguội trên khay. Chúng sẽ rất mềm khi bạn lấy chúng ra khỏi lò, nhưng sẽ giòn khi nguội.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2212, 329, 5, 'Bảo quản trong hộp kín và ăn trong vòng năm ngày.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2213, 329, 6, 'Đối với kẻ ngốc, hãy rửa quả mâm xôi trong một cái chao để rửa sạch bụi bẩn. Cho quả mâm xôi vào chảo chống dính và rắc đường lên trên.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2214, 329, 7, 'Khuấy nước cốt chanh và đun nóng nhẹ trong hai phút hoặc cho đến khi quả mâm xôi bắt đầu mềm và tiết ra nước. Lấy và để dành 12 quả mâm xôi để trang trí và tiếp tục nấu phần còn lại.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2215, 329, 8, 'Đun nhỏ quả mâm xôi thật nhẹ nhàng trong 15 phút, khuấy thường xuyên cho đến khi thật mềm và có độ sệt. Tắt bếp và ép quả mọng và nước ép qua rây trên một cái bát, sử dụng đáy muôi để giúp bạn chiết xuất được càng nhiều nước ép nhuyễn càng tốt. Để hỗn hợp nhuyễn nguội và loại bỏ hạt. Bạn sẽ thu được khoảng 325ml/11fl oz bột nhuyễn.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2216, 329, 9, 'Cho kem và sữa chua vào một tô lớn và dùng máy đánh trứng đánh cho đến khi lấy máy đánh trứng ra khỏi bát để tạo thành chóp mềm – tính axit của trái cây sẽ làm kem đặc hơn, vì vậy đừng đánh quá xa.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2217, 329, 10, 'Khi hỗn hợp đã nguội hoàn toàn, hãy điều chỉnh độ ngọt theo khẩu vị bằng cách thêm đường nếu cần. Đổ nó vào bát cùng với kem đánh bông và sữa chua rồi khuấy chỉ một hoặc hai lần cho đến khi hòa quyện rất nhẹ.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2218, 329, 11, 'Múc từng quả dâu đen vào các đĩa thủy tinh rộng, riêng lẻ - hoặc một bát lớn, đơn. Nó sẽ trông khá giống đá cẩm thạch, vì vậy đừng khuấy quá kỹ. Rắc một vài lá bạc hà nhỏ lên trên và trang trí với quả mâm xôi dành riêng. Rắc một chút đường nếu thích và dùng kèm với bánh quy hạt phỉ.', NULL, '2026-05-15 14:44:23', '2026-05-15 14:44:23'),
(2220, 330, 1, 'Làm nóng lò nướng ở mức quạt 180C/200C thông thường/khí 6. Bơ nhiều bơ vào sáu hộp bánh rán hoặc bánh nướng xốp chống dính. Đun chảy bơ và để nguội.', NULL, '2026-05-15 14:44:26', '2026-05-16 12:35:34'),
(2222, 330, 2, 'Rây đường bột và bột mì vào tô. Thêm hạnh nhân và trộn mọi thứ giữa các ngón tay của bạn.', NULL, '2026-05-15 14:44:26', '2026-05-16 12:35:34'),
(2224, 330, 3, 'Đánh lòng trắng trứng vào một cái bát khác cho đến khi tạo thành bọt mềm, nhẹ. Tạo một cái giếng ở giữa các nguyên liệu khô, cho lòng trắng trứng và vỏ chanh vào, sau đó khuấy nhẹ bơ để tạo thành hỗn hợp bột mềm.', NULL, '2026-05-15 14:44:26', '2026-05-16 12:35:34'),
(2226, 330, 4, 'Chia bột vào các hộp thiếc, một chiếc thìa lớn là hoàn hảo cho công việc này. Rắc một ít quả việt quất lên mỗi chiếc bánh và nướng trong 15-20 phút cho đến khi sờ vào thấy cứng và có màu vàng nâu.', NULL, '2026-05-15 14:44:26', '2026-05-16 12:35:34'),
(2228, 330, 5, 'Để nguội trong hộp thiếc trong 5 phút, sau đó lấy ra và để nguội trên giá lưới. Để phục vụ, rắc nhẹ với đường bột.', NULL, '2026-05-15 14:44:26', '2026-05-16 12:35:34'),
(2229, 331, 1, 'Làm nóng lò ở nhiệt độ 180°C/350˚F (lò nướng thông thường).', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2230, 331, 2, 'Cho bơ đã làm mềm và đường vào tô máy trộn đứng và đánh cho đến khi thành kem.', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2231, 331, 3, 'Thêm bột mì và muối vào rồi nhào bằng tay cho đến khi thu được khối bột mịn. Chia thành hai phần.', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2232, 331, 4, 'Lót giấy nến vào đế khuôn bánh hình vuông hoặc tròn (không phải khuôn dạng lò xo) và đặt nửa đầu của chiếc bánh lên trên. Làm phẳng bằng ngón tay và thìa.', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2233, 331, 5, 'Dùng một thìa cà phê, rắc một ít dulce de leche lên trên đế. Rắc sô cô la cắt nhỏ và phủ nửa sau của chiếc bánh ngọt lên.', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2234, 331, 6, 'Việc này phức tạp hơn một chút, nhưng nếu bạn làm không đúng thì cũng đừng lo lắng, sau khi nướng xong sẽ ổn thôi! Quét bánh ngọt bằng trứng đã đánh.', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2235, 331, 7, 'Nướng trong lò khoảng 30 phút hoặc cho đến khi có màu vàng nâu. Nó sẽ chao đảo. Đó là vì bánh bơ chỉ cứng lại khi nguội.', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2236, 331, 8, 'Cắt thành miếng nhỏ khi nó nguội hoàn toàn!', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2237, 331, 9, 'Ghi chú', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2238, 331, 10, 'Bảo quản: Bảo quản trong hộp kín, để ngoài tủ lạnh khoảng 2-3 ngày hoặc để trong tủ lạnh khoảng 5 ngày. Đóng băng lên đến ba tháng.', NULL, '2026-05-15 14:44:29', '2026-05-15 14:44:29'),
(2239, 332, 1, 'Bôi bơ vào đĩa bánh 1 lít/2 pint.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2240, 332, 2, 'Cắt vỏ bánh mì. Trải từng lát bơ lên ​​một mặt, sau đó cắt thành hình tam giác.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2241, 332, 3, 'Xếp một lớp bánh mì phết bơ lên ​​trên dưới đáy đĩa, sau đó thêm một lớp nho sultanas. Rắc một ít quế, sau đó lặp lại các lớp bánh mì và nho, rắc quế cho đến khi bạn dùng hết bánh mì. Kết thúc bằng một lớp bánh mì rồi đặt sang một bên.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2242, 332, 4, 'Nhẹ nhàng làm ấm sữa và kem trong chảo trên lửa nhỏ đến mức sôi. Đừng để nó sôi.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2243, 332, 5, 'Đập trứng vào tô, thêm 3/4 lượng đường vào rồi đánh nhẹ cho đến khi nhạt màu.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2244, 332, 6, 'Thêm hỗn hợp sữa và kem ấm vào rồi khuấy đều, sau đó lọc sữa trứng vào tô.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2245, 332, 7, 'Đổ sữa trứng lên các lớp bánh mì đã chuẩn bị sẵn và rắc hạt nhục đậu khấu và lượng đường còn lại rồi để yên trong 30 phút.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2246, 332, 8, 'Làm nóng lò ở 180C/355F/Gas 4.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2247, 332, 9, 'Đặt món ăn vào lò nướng và nướng trong 30-40 phút hoặc cho đến khi sữa trứng đông lại và mặt trên có màu nâu vàng.', NULL, '2026-05-15 14:44:33', '2026-05-15 14:44:33'),
(2248, 333, 1, 'Nghiền ricotta và đánh đều với lòng đỏ trứng, cho bột mì, đường, quế, vỏ chanh bào và rượu rum vào trộn đều. Bạn có thể làm điều này trong một bộ xử lý thực phẩm. Đánh lòng trắng trứng cho đến khi cứng, gấp lại và đổ vào khuôn bánh 25 cm đã phết bơ và bột mì. Nướng trong lò ở nhiệt độ 180°C/160°C quạt/gas 4 trong khoảng 40 phút hoặc cho đến khi bánh cứng lại.', NULL, '2026-05-15 14:44:39', '2026-05-15 14:44:39'),
(2249, 333, 2, 'Ăn nóng hoặc lạnh với đường bột.', NULL, '2026-05-15 14:44:39', '2026-05-15 14:44:39'),
(2250, 334, 1, 'Làm nóng lò nướng ở nhiệt độ quạt 170C/ thông thường 190C/gas 5. Cán bột bánh trên bề mặt đã rắc chút bột mì sao cho mỏng hơn một chút so với khi lấy bánh ra khỏi gói. Sau đó cắt 18-20 vòng bằng dao cắt rãnh 7,5cm, cuộn lại các phần trang trí. Sử dụng các vòng tròn để lót hai hộp bánh tart 12 lỗ sâu (không phải hộp bánh nướng xốp). Nếu chỉ có khuôn bánh tart 12 lỗ cỡ thông thường, bạn có thể làm một số loại bánh tart nông hơn một chút.', NULL, '2026-05-15 14:44:42', '2026-05-15 14:44:42'),
(2251, 334, 2, 'Đánh trứng vào tô lớn và kết hợp với các nguyên liệu còn lại trừ quả óc chó. Đổ hỗn hợp này vào chảo và khuấy liên tục trong 3-4 phút cho đến khi bơ tan chảy, hỗn hợp sủi bọt và bắt đầu đặc lại. Nó phải đủ dày để phủ mặt sau của một chiếc thìa gỗ. Đừng nấu quá chín và nhớ khuấy liên tục vì hỗn hợp có thể dễ bị cháy. Tắt bếp và cho các loại hạt vào khuấy đều.', NULL, '2026-05-15 14:44:42', '2026-05-15 14:44:42'),
(2252, 334, 3, 'Múc nhân vào vỏ bánh tart chưa nướng sao cho ngang bằng với bánh ngọt. Nướng trong 15-18 phút cho đến khi chín và có màu vàng nhạt. Để trong hộp thiếc nguội vài phút trước khi nhấc lên giá lưới. Phục vụ ấm hoặc lạnh.', NULL, '2026-05-15 14:44:42', '2026-05-15 14:44:42'),
(2253, 335, 1, 'Cho bã me và 1 cốc đường vào tô rồi dùng thìa hoặc nĩa nghiền nhuyễn. Lấy một lượng nhỏ hỗn hợp me và đường rồi vo thành những quả bóng nhỏ bằng cách lăn chúng trong tay. Làm cho chúng có kích thước bằng một viên bi hoặc lớn hơn một chút, tùy thích.', NULL, '2026-05-15 14:44:44', '2026-05-15 14:44:44'),
(2254, 335, 2, 'Thêm lượng đường còn lại vào một bề mặt phẳng, chẳng hạn như đĩa hoặc chảo. Lăn những quả me trong đường cát cho đến khi chúng được phủ đều.', NULL, '2026-05-15 14:44:44', '2026-05-15 14:44:44'),
(2255, 335, 3, 'Bạn có thể ăn me viên ngay hoặc có thể để vài giờ hoặc qua đêm. Để chúng đông lại sẽ mang lại cho chúng kết cấu chắc chắn hơn và lớp phủ đường kết tinh hơn. Thưởng thức.', NULL, '2026-05-15 14:44:44', '2026-05-15 14:44:44'),
(2256, 336, 1, 'Đối với bánh cà rốt, làm nóng lò nướng ở nhiệt độ 160C/325F/Gas 3. Bôi mỡ và lót khuôn bánh dạng lò xo 26cm/10in.', NULL, '2026-05-15 14:44:46', '2026-05-15 14:44:46'),
(2257, 336, 2, 'Trộn tất cả nguyên liệu làm bánh cà rốt, trừ cà rốt và quả óc chó, vào tô cho đến khi hòa quyện. Khuấy cà rốt và quả óc chó.', NULL, '2026-05-15 14:44:46', '2026-05-15 14:44:46'),
(2258, 336, 3, 'Múc hỗn hợp vào khuôn bánh và nướng trong 1 giờ 15 phút, hoặc cho đến khi xiên que vào giữa thấy tăm sạch sẽ. Lấy bánh ra khỏi lò và để nguội trong 10 phút, sau đó cẩn thận lấy bánh ra khỏi khuôn và để nguội hoàn toàn trên giá làm mát.', NULL, '2026-05-15 14:44:46', '2026-05-15 14:44:46'),
(2259, 336, 4, 'Trong khi đó, để làm kem, đánh kem phô mai, đường bột và bơ với nhau trong tô cho đến khi mịn. Dùng dao tạo lớp kem phủ lên mặt bánh.', NULL, '2026-05-15 14:44:46', '2026-05-15 14:44:46'),
(2260, 337, 1, 'Làm nóng lò ở 180 C / Gas 4. Lót khay nướng bằng giấy thấm mỡ.', NULL, '2026-05-15 14:44:48', '2026-05-15 14:44:48'),
(2261, 337, 2, 'Trong một cái bát, trộn hạt điều và đường bột. Thêm lòng đỏ trứng và nước hoa cam vào rồi trộn đều thành hỗn hợp đồng nhất mịn.', NULL, '2026-05-15 14:44:48', '2026-05-15 14:44:48'),
(2262, 337, 3, 'Lấy từng cục bột điều và vo thành những quả bóng nhỏ. Lăn các quả bóng trong đường bột và chuyển vào khay nướng. Đẩy một quả hạnh nhân vào giữa mỗi chiếc ghribia.', NULL, '2026-05-15 14:44:48', '2026-05-15 14:44:48'),
(2263, 337, 4, 'Nướng cho đến khi bánh quy có màu vàng nhẹ, khoảng 20 phút. Hãy để mắt tới chúng, chúng sẽ cháy rất nhanh.', NULL, '2026-05-15 14:44:48', '2026-05-15 14:44:48'),
(2264, 338, 1, 'Rây bột mì và muối vào tô lớn. Tạo một cái giếng ở giữa và thêm men vào.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2265, 338, 2, 'Trong khi đó, làm ấm sữa và bơ trong chảo cho đến khi bơ tan chảy và hỗn hợp còn âm ấm.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2266, 338, 3, 'Thêm hỗn hợp sữa và trứng vào hỗn hợp bột và khuấy cho đến khi các thành phần trong bát hòa quyện với nhau thành một khối bột mềm. (Bạn có thể cần thêm một ít bột mì.)', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2267, 338, 4, 'Đổ bột lên một bề mặt làm việc đã được rải đầy bột mì. Nhào trong năm phút, thêm bột mì nếu cần, cho đến khi bột mịn, đàn hồi và không còn cảm giác dính.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2268, 338, 5, 'Thoa nhẹ một ít dầu thực vật vào bát. Đặt bột vào tô và đảo cho đến khi phủ đầy dầu. Đậy bát bằng màng dính và để ở nơi ấm áp trong một giờ hoặc cho đến khi bột nở gấp đôi.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2269, 338, 6, 'Bôi nhẹ một lớp mỡ lên khay nướng.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2270, 338, 7, 'Để làm nhân, đập bột trở lại kích thước ban đầu và đặt lên bề mặt đã rắc một lớp bột mì nhẹ. Cán bột thành hình chữ nhật dày 0,5 cm/¼ inch. Quét bơ tan chảy lên khắp mặt, sau đó rắc đường nâu, quế và trái cây khô lên trên.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2271, 338, 8, 'Cán bột thành hình trụ thật chặt, cắt mười lát 4 cm/1½ inch và đặt chúng lên khay nướng đã phết một ít dầu mỡ, chừa một khoảng trống nhỏ giữa mỗi lát. Che lại bằng một chiếc khăn trà và đặt sang một bên để ủ trong 30 phút.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2272, 338, 9, 'Làm nóng lò ở 190C/375F/Gas 5.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2273, 338, 10, 'Nướng bánh trong lò khoảng 20-25 phút hoặc cho đến khi bánh nở và có màu vàng nâu.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2274, 338, 11, 'Trong khi đó, đối với phần men, đun nóng sữa và đường trong nồi cho đến khi sôi. Giảm nhiệt và đun nhỏ lửa trong 2-3 phút.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2275, 338, 12, 'Lấy bánh ra khỏi lò và phết một lớp men, sau đó đặt sang một bên để nguội trên giá lưới.', NULL, '2026-05-15 14:44:51', '2026-05-15 14:44:51'),
(2276, 339, 1, 'Để làm thạch rượu vang đỏ, cho rượu vang đỏ, đường mứt, hoa hồi, đinh hương, thanh quế, hạt tiêu, vỏ vani tách đôi và hạt vào một cái chảo vừa. Khuấy đều, sau đó đun nóng nhẹ để hòa tan đường. Tăng nhiệt và đun sôi trong 20 phút cho đến khi giảm bớt và có dạng siro. Lọc vào lọ mứt nhỏ đã khử trùng và để nguội hoàn toàn. Sẽ giữ trong tủ lạnh lên đến 1 tháng.', NULL, '2026-05-15 14:44:55', '2026-05-15 14:44:55'),
(2277, 339, 2, 'Lấy bánh ra khỏi tủ lạnh và để ở nhiệt độ phòng trong 10 phút, sau đó mở ra. Làm nóng lò nướng ở mức cao và làm nóng lò ở mức quạt/gas 180C/160C 4. Cắt những miếng bánh ngọt hình tròn 2 x 13cm, dùng đĩa làm hướng dẫn và đặt lên khay nướng chống dính. Rắc từng khoanh tròn 1 thìa đường rồi nướng trong 5 phút cho caramen, quan sát cẩn thận để đường không bị cháy. Lấy ra khỏi vỉ nướng. Có thể làm trước vài giờ và để trong tủ lạnh, đậy kín.', NULL, '2026-05-15 14:44:55', '2026-05-15 14:44:55'),
(2278, 339, 3, 'Gọt vỏ, cắt đôi và bỏ lõi táo, cắt thành lát mỏng 2mm và xếp lên trên mặt bánh. Rắc lên lượng đường còn lại rồi cho vào lò nướng khoảng 20-25 phút cho đến khi bánh chín và vàng đều, táo mềm. Lấy ra và để nguội một chút. Đun nóng 3 thìa thạch rượu vang đỏ trong chảo nhỏ trên lửa nhỏ với 1 thìa cà phê nước để thạch chảy hơn một chút, sau đó quét lên trên mặt bánh tart.', NULL, '2026-05-15 14:44:55', '2026-05-15 14:44:55'),
(2279, 339, 4, 'Đổ kem tươi vào tô, rây đường bột và bạch đậu khấu rồi trộn đều. Cẩn thận nhấc những chiếc bánh tart còn ấm lên đĩa phục vụ và dùng kèm với kem bạch đậu khấu.', NULL, '2026-05-15 14:44:55', '2026-05-15 14:44:55'),
(2280, 340, 1, 'Đầu tiên, làm bánh ngọt. Cho nguyên liệu vào máy xay thực phẩm với 1/4 thìa cà phê muối. Trộn cho đến khi hỗn hợp giống như vụn bánh mì. Rưới 2-3 thìa cà phê nước lạnh vào phễu trong khi lưỡi dao đang chạy – hỗn hợp sẽ bắt đầu kết tụ lại với nhau. Đổ lên bề mặt làm việc và tập hợp lại với nhau, nhào nhanh thành một quả bóng. Đổ vào đĩa, bọc trong màng bám và để lạnh ít nhất 20 phút. Làm nóng lò ở mức quạt/gas 200C/180C 6.', NULL, '2026-05-15 14:44:57', '2026-05-15 14:44:57'),
(2281, 340, 2, 'Lấy bánh ra khỏi tủ lạnh và để ở nhiệt độ phòng trong 5 phút cho mềm. Phủ bột lên bề mặt làm việc, sau đó mở bánh ra và cuộn thành hình tròn có độ dày bằng đồng xu £ 1. Dùng bánh ngọt để lót một khuôn bánh có rãnh tròn, đường kính 23 cm – của tôi sâu khoảng 3 cm. Nhấn bánh ngọt vào các góc và hướng lên trên, đảm bảo không có khoảng trống. Để lại phần bánh ngọt nhô ra 1cm (để dành một số mẩu bánh ngọt cho lần sau). Lót giấy nến nướng (nhớ trước để dẻo hơn) và đổ đậu nướng vào. Nướng kín trong 15-20 phút cho đến khi các mặt chín hẳn, sau đó lấy giấy da và đậu ra rồi cho vào lò nướng trong 5 phút cho đến khi có màu vàng nâu. Cắt bánh sao cho phẳng với mặt trên của hộp thiếc - tốt nhất nên dùng một con dao có răng cưa nhỏ cho việc này. Nếu có bất kỳ vết nứt nào, hãy vá chúng bằng vụn bánh ngọt.', NULL, '2026-05-15 14:44:57', '2026-05-15 14:44:57'),
(2282, 340, 3, 'Trong khi đó, cân bơ, xi-rô và đường vào chảo, thêm 1/4 thìa cà phê muối. Đun nóng cho đến khi bơ tan chảy và đường tan, khuấy đều cho đến khi mịn. Tắt bếp và để nguội trong 10 phút. Giảm nhiệt độ lò/quạt xuống 160C/140C 3.', NULL, '2026-05-15 14:44:57', '2026-05-15 14:44:57'),
(2283, 340, 4, 'Đánh trứng vào tô. Thêm hỗn hợp xi-rô, vani và hồ đào vào và trộn cho đến khi kết hợp tốt. Đổ một nửa hỗn hợp vào hộp bánh tart, rải lên một nửa số sô cô la chip, sau đó phủ phần nhân còn lại và sô cô la chip lên. Nướng trên kệ giữa trong 50-55 phút cho đến khi chín. Lấy ra khỏi lò và để nguội, sau đó để lạnh ít nhất 2 giờ trước khi dùng.', NULL, '2026-05-15 14:44:57', '2026-05-15 14:44:57'),
(2284, 341, 1, 'Đối với bánh quy, đánh bơ với đường trong vài phút. Sau đó thêm trứng và mật ong vào và trộn đều. Thêm bột mì, bột ngô, ca cao, baking soda và bột nở vào rồi trộn cho đến khi thu được khối bột. Bọc trong màng bọc thực phẩm và để lạnh ít nhất nửa giờ hoặc qua đêm.', NULL, '2026-05-15 14:45:00', '2026-05-15 14:45:00'),
(2285, 341, 2, 'Lót giấy nến vào hai khay nướng, làm nóng lò ở nhiệt độ 200 độ C.', NULL, '2026-05-15 14:45:00', '2026-05-15 14:45:00'),
(2286, 341, 3, 'Chia bột thành hai phần, một phần để vào tủ lạnh trước khi dùng. Cán phần thứ hai khoảng 2 mm và cắt những chiếc bánh quy tròn có đường kính 5-6 cm. Điều này có thể được thực hiện bằng máy cắt bánh quy hoặc ly. Bạn sẽ nhận được tổng cộng 30 chiếc bánh quy hoặc thậm chí nhiều hơn, tôi nhận được khoảng 40 chiếc. Nướng một khay nướng mỗi lần trong khoảng 8-10 phút. Để bánh nguội.', NULL, '2026-05-15 14:45:00', '2026-05-15 14:45:00'),
(2287, 341, 4, 'Để làm nhân bánh, hãy tìm hai chiếc bánh quy có cùng kích thước và đặt khoảng một thìa cà phê dulce de leche lên chiếc bánh dưới cùng trước khi kẹp lại với nhau.', NULL, '2026-05-15 14:45:00', '2026-05-15 14:45:00'),
(2288, 341, 5, 'Cắt nhỏ sô cô la vừa ngọt và làm tan chảy với bơ và vỏ cam ở lửa nhỏ. Nhúng từng chiếc bánh sandwich vào sô cô la và để nguội trên giấy da trước khi dùng.', NULL, '2026-05-15 14:45:00', '2026-05-15 14:45:00'),
(2289, 342, 1, '1. Trộn tất cả nguyên liệu mousse lại với nhau trong máy xay thực phẩm cho đến khi mịn. Trước tiên hãy thêm bột cacao và khi trộn, bạn có sẵn tất cả các nguyên liệu để điều chỉnh tỷ lệ một chút vì kích thước của quả bơ và chuối rất khác nhau. Tỷ lệ hoàn hảo để tránh món ăn nếm quá nhiều một trong hai là sử dụng lượng bằng nhau của cả hai.', NULL, '2026-05-15 14:45:02', '2026-05-15 14:45:02'),
(2290, 342, 2, '2. Nếm thử và thêm vài giọt stevia nếu bạn cảm thấy cần thêm vị ngọt.', NULL, '2026-05-15 14:45:02', '2026-05-15 14:45:02'),
(2291, 342, 3, '3. Đổ mousse vào các cốc nhỏ hoặc ly nhỏ, rắc bột cacao hoặc ngòi cacao và thưởng thức.', NULL, '2026-05-15 14:45:02', '2026-05-15 14:45:02'),
(2292, 342, 4, 'Mẹo Nếu không có sẵn chuối đông lạnh, bạn có thể sử dụng chuối bình thường rồi làm lạnh mousse trước khi dùng làm món tráng miệng giải nhiệt.', NULL, '2026-05-15 14:45:02', '2026-05-15 14:45:02'),
(2293, 343, 1, 'Bôi mỡ và lót giấy nến vào khuôn nướng 20 x 20cm/8\" x 8\".', NULL, '2026-05-15 14:45:04', '2026-05-15 14:45:04'),
(2294, 343, 2, 'Đặt các thanh mars và bơ vào tô chịu nhiệt rồi đặt lên chảo nước vừa sôi. Trộn bằng máy đánh trứng, đun chảy cho đến khi hỗn hợp mịn.', NULL, '2026-05-15 14:45:04', '2026-05-15 14:45:04'),
(2295, 343, 3, 'Đổ bánh gạo vào tô trộn và trộn cho đến khi tất cả các nguyên liệu hòa quyện đều nhau. Nhấn đều vào khuôn nướng đã chuẩn bị và đặt sang một bên.', NULL, '2026-05-15 14:45:04', '2026-05-15 14:45:04'),
(2296, 343, 4, 'Làm tan chảy sô cô la sữa trong lò vi sóng hoặc trên chảo nước vừa sôi.', NULL, '2026-05-15 14:45:04', '2026-05-15 14:45:04'),
(2297, 343, 5, 'Rải sô cô la tan chảy lên hỗn hợp bánh gạo krispie và để ở nơi mát mẻ. Sau khi đặt lát thành hình vuông và phục vụ!', NULL, '2026-05-15 14:45:04', '2026-05-15 14:45:04'),
(2299, 344, 1, 'Để làm nước sốt, bạn cho đường và bơ vào nồi đun nhỏ lửa cho đến khi đường tan, sau đó cho kem vào khuấy đều và đun nhỏ lửa cho đến khi có nước sốt sánh mịn, khoảng 2-3 phút. Tắt bếp, khuấy đều với một chút muối biển và sô cô la, rồi tiếp tục khuấy trong 2-3 phút hoặc cho đến khi tan chảy hoàn toàn. Giữ ấm hoặc để nguội để hâm nóng sau. Đối với lớp phủ, trộn đường với quế và một chút muối biển mịn rồi để sang một bên.', NULL, '2026-05-15 14:45:07', '2026-05-16 12:35:34'),
(2301, 344, 2, 'Đối với bánh churros, cho bột mì, ca cao, bột nở và một chút muối vào tô. Thêm chiết xuất vani và bơ tan chảy, sau đó cẩn thận đổ 250-300ml nước sôi vào và đánh đều để tạo thành hỗn hợp bột mịn, rất đặc. Để nguội trong vài phút, sau đó cạo hỗn hợp vào túi bắt kem có gắn vòi hình sao cỡ trung bình.', NULL, '2026-05-15 14:45:07', '2026-05-16 12:35:34'),
(2303, 344, 3, 'Đổ dầu hướng dương vào nồi chiên ngập dầu theo hướng dẫn của nhà sản xuất hoặc chảo đế nặng, đảm bảo dầu không đầy quá một phần ba. Đun nóng đến 170C hoặc cho đến khi một khối bánh mì chuyển sang màu nâu trong 30 giây. Đổ những đoạn bột dài 12-15cm vào dầu, dùng kéo cắt bỏ phần cuối của mỗi cục bột. Cho bốn hoặc năm ống mỗi lần và nấu trong khoảng 4 phút, hoặc cho đến khi vàng và giòn, xoay chúng bằng kẹp hoặc thìa có rãnh khi nấu. Lấy ra khỏi dầu và đặt trên giá dây. Lặp lại với phần bột còn lại. Để nguội nếu hâm nóng sau, nếu không thì lăn churros trong đường quế và dùng ngay với sốt sô cô la ấm và kem. Để hâm nóng bánh churros, hãy đặt lên khay và nướng trong 5-8 phút, sau đó lăn trong lớp đường phủ. Trong khi đó, đun nóng nước sốt trong chảo và dùng kèm để chấm.', NULL, '2026-05-15 14:45:07', '2026-05-16 12:35:34'),
(2305, 345, 1, 'Làm nóng lò ở 180C/quạt 160C/gas 4. Bơ bơ và lót đáy khuôn nướng hình vuông 20cm. Đánh bơ và đường cho đến khi nhạt màu, sau đó cho trứng vào đánh đều. Thêm 1 muỗng canh bột mì nếu hỗn hợp bắt đầu đặc lại.', NULL, '2026-05-15 14:45:09', '2026-05-16 12:35:34'),
(2307, 345, 2, 'Rây bột mì, bột nở và ca cao vào rồi dùng thìa kim loại trộn đều. Khuấy sữa. Cạo hỗn hợp vào hộp thiếc và san bằng mặt trên. Nướng trong 18-20 phút hoặc cho đến khi ấn bánh lại. Để nguội trong hộp thiếc.', NULL, '2026-05-15 14:45:09', '2026-05-16 12:35:34'),
(2309, 345, 3, 'Để làm kem, cho sô cô la, bơ và 4 muỗng canh nước vào chảo và đun nóng nhẹ cho đến khi tan chảy. Để nguội một chút rồi cho đường bột vào đánh đều.', NULL, '2026-05-15 14:45:09', '2026-05-16 12:35:34'),
(2311, 345, 4, 'Lấy bánh ra khỏi khuôn và bóc giấy. Cắt thành 16 hình vuông. Nhúng các hình vuông vào kem, sau đó lăn vào dừa. Cho phép đặt trên giá làm mát.', NULL, '2026-05-15 14:45:09', '2026-05-16 12:35:34'),
(2312, 346, 1, 'Để làm đầy, đặt lon vào một cái nồi lớn và đổ đầy nước vào. Đun sôi trong hai tiếng rưỡi, thỉnh thoảng thêm nước. Để nguội trước khi mở. Để biết thêm lời khuyên, vui lòng kiểm tra ở đây.', NULL, '2026-05-15 14:45:12', '2026-05-15 14:45:12'),
(2313, 346, 2, 'Đối với bột, trộn bột mì, bột ca cao và muối vào tô lớn. Thêm bơ lạnh thành từng miếng nhỏ và dùng ngón tay chà thành từng mảnh vụn. Thêm trứng và nhào thành bột. Bạn có thể phải thêm sữa, mỗi lần một thìa sữa nếu sữa vẫn khô. Bọc và thư giãn ít nhất nửa giờ hoặc qua đêm.', NULL, '2026-05-15 14:45:12', '2026-05-15 14:45:12'),
(2314, 346, 3, 'Lót giấy nến vào khay nướng và làm nóng lò trước ở nhiệt độ 180 độ C.', NULL, '2026-05-15 14:45:12', '2026-05-15 14:45:12'),
(2315, 346, 4, 'Cán bột trên một bề mặt đã rắc chút bột mì, bột phải mỏng. Cắt các hình tròn có kích thước 12cm bằng khuôn cắt bánh quy hoặc bằng đĩa/đĩa nhỏ hơn. Đặt hai đến ba muỗng cà phê dulce de leche vào giữa mỗi vòng tròn. Quét sữa lên các cạnh, tôi làm điều này với ngón út của mình. Gấp mỗi vòng tròn làm đôi để có hình bán nguyệt và dùng nĩa ấn các cạnh xuống. Bạn cũng có thể xoay các cạnh khoảng nửa centimet vào trong mỗi centimet hoặc lâu hơn để tạo hoa văn.', NULL, '2026-05-15 14:45:12', '2026-05-15 14:45:12'),
(2316, 346, 5, 'Đặt bánh empanadas đã chuẩn bị lên khay nướng và phết nước rửa trứng lên. Nướng trong khoảng 20-25 phút.', NULL, '2026-05-15 14:45:12', '2026-05-15 14:45:12'),
(2317, 346, 6, 'Đến cuối thời gian nướng, làm tan chảy phần bơ còn lại rồi trộn đường và quế vào một cái bát nhỏ. Sau khi bạn lấy empanadas ra, ngay lập tức phết bơ lên ​​và rắc hỗn hợp đường. Empanadas có thể được thưởng thức khi còn ấm hoặc lạnh. Nếu ăn ấm, hãy cẩn thận đừng để bị bỏng với nhân nóng!', NULL, '2026-05-15 14:45:12', '2026-05-15 14:45:12'),
(2318, 347, 1, 'Làm nóng lò ở 180°C/350°F/Mã khí 4. Bôi mỡ và lót đế của khuôn bánh lò xo tròn 8 inch bằng giấy nướng', NULL, '2026-05-15 14:45:15', '2026-05-15 14:45:15'),
(2319, 347, 2, 'Đập sô-cô-la vào tô chịu nhiệt rồi đặt lên nồi nước sôi nhẹ và khuấy đều cho đến khi sô-cô-la tan chảy. (hoặc làm tan chảy trong lò vi sóng trong 2-3 phút thỉnh thoảng khuấy)', NULL, '2026-05-15 14:45:15', '2026-05-15 14:45:15'),
(2320, 347, 3, 'Cho bơ và đường vào tô trộn và dùng thìa gỗ trộn kem cho đến khi mềm và mịn. Từ từ đánh trứng vào, thêm một ít bột mì nếu hỗn hợp bắt đầu đặc lại. Trộn phần bột còn lại với sô-cô-la tan chảy đã nguội và sữa. Trộn cho đến khi mịn.', NULL, '2026-05-15 14:45:15', '2026-05-15 14:45:15'),
(2321, 347, 4, 'Trải hỗn hợp vào khuôn bánh và nướng trong 50-55 phút hoặc cho đến khi cứng ở giữa và xiên que ra sạch sẽ. Để nguội trong 10 phút, sau đó tắt và nguội hoàn toàn.', NULL, '2026-05-15 14:45:15', '2026-05-15 14:45:15'),
(2322, 348, 1, 'Làm nóng lò nướng ở mức quạt/khí 180C/160C 4. Lót giấy nướng vào khay nướng 20 x 30cm. Cho sô cô la, bơ và đường vào chảo và đun chảy nhẹ nhàng, thỉnh thoảng khuấy bằng thìa gỗ. Hủy bỏ khỏi nhiệt.', NULL, '2026-05-15 14:45:18', '2026-05-15 14:45:18'),
(2323, 348, 2, 'Khuấy từng quả trứng vào hỗn hợp sô cô la tan chảy. Rây bột mì và ca cao rồi khuấy đều. Khuấy một nửa quả mâm xôi, cạo vào khay, sau đó rải lên số quả mâm xôi còn lại. Nướng trên kệ giữa trong 30 phút hoặc nếu bạn thích kết cấu chắc hơn thì nướng thêm 5 phút. Làm nguội trước khi cắt thành hình vuông. Bảo quản trong hộp kín tối đa 3 ngày.', NULL, '2026-05-15 14:45:18', '2026-05-15 14:45:18'),
(2324, 349, 1, 'Làm nóng lò nướng ở mức 220C/quạt 200C/gas 7 và đặt khay nướng lên kệ trên cùng. Đối với nước sốt, đun nóng kem và đường cho đến khi sôi. Tắt bếp, cho sô cô la và bơ vào khuấy đều cho đến khi tan chảy rồi giữ ấm.', NULL, '2026-05-15 14:45:20', '2026-05-15 14:45:20'),
(2325, 349, 2, 'Quét 6 x 150ml ramekins bằng bơ tan chảy, rắc 2 muỗng canh đường bột, sau đó loại bỏ phần thừa. Đun chảy sô-cô-la và kem trong tô trên chảo nước sôi, để nguội rồi trộn với lòng đỏ trứng. Đánh lòng trắng trứng cho đến khi giữ được hình dạng, sau đó thêm đường, mỗi lần 1 muỗng canh, đánh lại để có độ đặc như cũ. Trộn một thìa vào sô-cô-la, sau đó nhẹ nhàng trộn phần còn lại vào.', NULL, '2026-05-15 14:45:20', '2026-05-15 14:45:20'),
(2326, 349, 3, 'Làm việc nhanh chóng, đổ đầy khuôn ramekins, lau sạch vành và chạy ngón tay cái quanh các cạnh. Giảm nhiệt độ lò xuống 200C/quạt 180C/gas 6, đặt ramekins lên khay nướng, sau đó nướng trong 8-10 phút cho đến khi bánh đứng dậy và hơi lắc lư. Không mở cửa lò quá sớm vì có thể làm cửa lò bị sập.', NULL, '2026-05-15 14:45:20', '2026-05-15 14:45:20'),
(2327, 349, 4, 'Sau khi bánh soufflé đã sẵn sàng, hãy rắc đường bột, khoét một lỗ nhỏ trên bề mặt bánh, sau đó đổ một ít nước sốt sô cô la nóng vào. Đậy nắp lại và dùng ngay.', NULL, '2026-05-15 14:45:20', '2026-05-15 14:45:20'),
(2328, 350, 1, 'Làm nóng lò ở 160C/quạt 140C/gas 3. Lót đáy và các cạnh của khuôn bánh tròn 20 cm, sâu 7,5 cm. Đánh bơ và đường bằng máy trộn cầm tay điện trong 1-2 phút cho đến khi có màu kem và nhạt, cạo dọc thành bát nửa chừng. Khuấy một thìa bột mì, sau đó lần lượt cho trứng đã đánh và phần bột còn lại vào, mỗi lần một phần tư, dùng thìa gỗ đánh đều. Khuấy hạnh nhân.', NULL, '2026-05-15 14:45:24', '2026-05-15 14:45:24'),
(2329, 350, 2, 'Trộn rượu sherry (hỗn hợp sẽ trông như vón cục), sau đó thêm vỏ, quả anh đào, nho khô, quả anh đào, các loại hạt, vỏ chanh, gia vị, nước hoa hồng và vani. Đánh đều cho hòa quyện rồi cho bột nở vào trộn đều.', NULL, '2026-05-15 14:45:24', '2026-05-15 14:45:24'),
(2330, 350, 3, 'Múc hỗn hợp vào khuôn và làm phẳng phần trên, tạo một vết lõm nhẹ ở giữa. Nướng trong 30 phút, sau đó giảm nhiệt độ xuống 150C/quạt 130C/gas 2 và nướng thêm 2-2¼ giờ, cho đến khi xiên que vào giữa xiên ra sạch sẽ. Để nguội trong hộp thiếc rồi lấy ra khỏi hộp, bóc lớp giấy lót. Khi nguội hoàn toàn, bọc kỹ trong màng bám và giấy bạc để bảo quản cho đến khi sẵn sàng trang trí. Bánh sẽ giữ được vài tháng.', NULL, '2026-05-15 14:45:24', '2026-05-15 14:45:24'),
(2331, 351, 1, 'Làm nóng lò ở 180°C/quạt 160°C/mã gas 4 rồi bôi mỡ và lót khuôn 25 cm x 20 cm. Đun chảy bơ, đường, xi-rô và vỏ cam trong chảo lớn trên lửa vừa. Mục đích là để hòa tan tất cả các thành phần sao cho chúng mịn, nhưng không bị mất thể tích khi đun sôi, vì vậy hãy cẩn thận không để quá nóng.', NULL, '2026-05-15 14:45:27', '2026-05-15 14:45:27'),
(2332, 351, 2, 'Thêm yến mạch và khuấy đều cho đến khi được phủ đều. Khuấy phần bánh pudding Giáng sinh còn sót lại và đổ vào hộp thiếc đã chuẩn bị sẵn. Dùng thìa cán phẳng mặt trên và nướng trong 40 phút cho đến khi các cạnh bắt đầu chuyển sang màu nâu. Trong khi vẫn còn ấm trong hộp thiếc, hãy chia thành 12 ô vuông. Để nguội hoàn toàn trước khi cắt dọc theo điểm số.', NULL, '2026-05-15 14:45:27', '2026-05-15 14:45:27'),
(2333, 351, 3, 'Bảo quản trong hộp kín 5 ngày hoặc để đông trong 1 tháng.', NULL, '2026-05-15 14:45:27', '2026-05-15 14:45:27'),
(2334, 352, 1, 'Dùng dao gọt vỏ cam, đảm bảo loại bỏ hết phần cùi. Cắt càng mỏng càng tốt và bày lên đĩa ăn tối. Rắc đường demerara, sau đó là Grand Marnier và đặt sang một bên.', NULL, '2026-05-15 14:45:30', '2026-05-15 14:45:30'),
(2335, 352, 2, 'Nghiền bánh pudding Giáng sinh thành từng miếng lớn và rải dưới đáy một chiếc bát nhỏ. Xếp từng lớp cam lên bánh pudding và đổ nước ép lên trên.', NULL, '2026-05-15 14:45:30', '2026-05-15 14:45:30'),
(2336, 352, 3, 'Đánh mascarpone cho đến khi mịn, sau đó cho sữa trứng vào khuấy đều. Đổ hỗn hợp lên trên những quả cam.', NULL, '2026-05-15 14:45:30', '2026-05-15 14:45:30'),
(2337, 352, 4, 'Đánh nhẹ kem và dùng thìa phủ lên sữa trứng. Rắc hạnh nhân và sô-cô-la bào lên trên. Bạn có thể làm món này trước một ngày nếu thích, thư giãn cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:45:30', '2026-05-15 14:45:30'),
(2339, 353, 1, 'Đun sôi ấm, sau đó đo 300ml nước sôi cho vào bình rồi cho bơ tan chảy và chiết xuất vani vào. Rây bột mì và bột nở vào tô trộn lớn cùng với một chút muối lớn. Tạo một cái giếng ở giữa, sau đó đổ lượng chứa trong bình vào và dùng thìa gỗ đánh thật nhanh vào bột cho đến khi không còn vón cục. Nghỉ khoảng 10-15 phút trong lúc làm nước sốt.', NULL, '2026-05-15 14:45:31', '2026-05-16 12:35:34'),
(2341, 353, 2, 'Cho tất cả nguyên liệu làm nước sốt vào chảo và đun chảy nhẹ nhàng với nhau, thỉnh thoảng khuấy đều cho đến khi có được nước sốt mịn bóng. Giữ ấm ở nhiệt độ thấp.', NULL, '2026-05-15 14:45:31', '2026-05-16 12:35:34'),
(2343, 353, 3, 'Đổ đầy một cái chảo sâu lòng lớn vào một phần ba dầu. Nấu bằng dầu nóng có thể nguy hiểm – trước khi bắt đầu, hãy đọc cách chiên ngập dầu an toàn để tránh tai nạn trong nhà bếp. Đun nóng cho đến khi một khối bánh mì có màu nâu trong vòng 45 giây đến 1 phút. Đậy khay bằng giấy ăn và trộn đường bột và quế với nhau.', NULL, '2026-05-15 14:45:31', '2026-05-16 12:35:34'),
(2345, 353, 4, 'Lắp đầu hút hình sao vào túi bắt kem – rộng 1,5-2cm là kích thước phù hợp. Đổ đầy bột đã nghỉ, sau đó đổ trực tiếp 2-3 dải bột vào chảo, dùng kéo nhà bếp cắt từng dải bột. Chiên cho đến khi vàng nâu và giòn. Hãy hết sức cẩn thận ở đây – nếu bọt khí hình thành trong bánh churros, chúng có thể nổ tung, đặc biệt nếu dầu quá nóng hoặc bạn sử dụng bột mì cũ. Nấu bằng dầu nóng có thể nguy hiểm – trước khi bắt đầu, hãy đọc cách chiên ngập dầu an toàn để tránh tai nạn trong nhà bếp. Giữ trẻ em không vào bếp và tự bảo vệ mình bằng cách mặc áo dài tay, đeo kính bảo vệ mắt và tránh để mặt bạn chạm vào chảo.', NULL, '2026-05-15 14:45:31', '2026-05-16 12:35:34'),
(2347, 353, 5, 'Khi bánh churros đã giòn và có màu nâu vàng, dùng thìa có rãnh vớt chúng ra khỏi dầu và để ráo trên khay có lót giấy nhà bếp. Tiếp tục nấu phần bột còn lại theo từng đợt, rắc một ít đường quế lên bánh churros đã nấu chín. Khi bạn đã nấu xong tất cả các món churros, trộn với lượng đường quế còn lại và dùng kèm với sốt sô cô la để chấm.', NULL, '2026-05-15 14:45:31', '2026-05-16 12:35:34'),
(2348, 353, 6, 'Để xem video về cách chuẩn bị bánh churros, hãy xem công thức làm bánh mì kẹp kem churros của chúng tôi.', NULL, '2026-05-15 14:45:31', '2026-05-16 12:35:34'),
(2349, 354, 1, 'Trong một cái chảo nhỏ, đun nóng bơ, sữa và muối cho đến khi bơ tan chảy. Để hỗn hợp nguội cho đến khi còn âm ấm.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2350, 354, 2, 'Trong một tô lớn, khuấy đều bột mì, men, bạch đậu khấu và đường cho đến khi hòa quyện.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2351, 354, 3, 'Tạo một cái giếng ở giữa và đập trứng vào. Đổ hỗn hợp sữa ấm vào và khuấy đều mọi thứ lại với nhau để tạo thành một khối bột dính. Bạn có thể phải dùng tay khi bột trở nên cứng hơn.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2352, 354, 4, 'Bôi dầu lên bề mặt làm việc bằng một thìa cà phê dầu ô liu. Lật bột lên bề mặt đã phết dầu và nhào mạnh trong 5–8 phút, dùng nạo nhựa nếu cần để gạt bột ra khỏi bề mặt làm việc. Đừng cố thêm bột mì vì điều này sẽ làm cho bánh bị khô và dai. Tiếp tục nhào cho đến khi bột bớt dính, mịn và đàn hồi hơn đáng kể.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2353, 354, 5, 'Tạo thành một quả bóng và cho vào một cái tô lớn đã bôi mỡ. Đậy bát bằng một chiếc khăn trà sạch và đặt ở nơi ấm áp để ủ trong một giờ hoặc cho đến khi kích thước tăng gấp đôi.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2354, 354, 6, 'Trong khi đó, để làm nhân và phủ, trộn bơ đã làm mềm vào tô với một nửa lượng đường và 1 thìa quế. Dùng nĩa trộn đường và gia vị vào bơ cho đến khi hòa quyện hoàn toàn.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2355, 354, 7, 'Trộn phần đường và quế còn lại vào một bát riêng rồi đặt sang một bên.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2356, 354, 8, 'Khi bột đã nổi lên, đặt lên bề mặt đã rắc bột mì và nhẹ nhàng cán thành hình chữ nhật có kích thước 36x24cm/14x9½in. Trải đều quế-đường-bơ lên ​​bột bằng bàn hoặc dao pha màu.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2357, 354, 9, 'Với cạnh dài nhất gần bạn nhất, cuộn bột thành hình trụ. Cắt thành 12 lát đều nhau.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2358, 354, 10, 'Đặt từng lát lên hộp đựng bánh cupcake bằng giấy dẹt trên khay nướng hoặc vào khuôn làm bánh nướng xốp đã phết mỡ. (Nướng trong khuôn làm bánh nướng xốp sẽ làm cho bánh quế của bạn cao hơn và có hình vòm.)', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2359, 354, 11, 'Che lại bằng một chiếc khăn trà sạch và đặt sang một bên để ủ lại trong 30–45 phút hoặc cho đến khi nổi lên.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2360, 354, 12, 'Làm nóng lò ở mức quạt/gas 200C/180C 6.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2361, 354, 13, 'Quét trứng đánh lên mặt bánh và rắc đường quế lên mặt bánh. Nướng trong 12 phút cho đến khi bánh có màu nâu vàng đậm. Thưởng thức ấm áp với một tách cà phê.', NULL, '2026-05-15 14:45:34', '2026-05-15 14:45:34'),
(2362, 355, 1, 'Chuẩn bị mọi thứ cho món bánh pudding. Hạnh nhân cắt nhỏ. Gọt vỏ, bỏ lõi và cắt nhỏ táo nấu ăn. Làm sắc nét con dao của bạn và cắt vỏ kẹo. (Bạn có thể cắt hạnh nhân và táo trong máy xay thực phẩm, nhưng vỏ phải được thực hiện bằng tay.) Nghiền 3/4 số hạt nhục đậu khấu (nghe có vẻ nhiều nhưng chính xác là như vậy).', NULL, '2026-05-15 14:45:37', '2026-05-15 14:45:37'),
(2363, 355, 2, 'Trộn hạnh nhân, táo, vỏ kẹo, nhục đậu khấu, nho khô, bột mì, vụn bánh mì, đường muscovado nhẹ, trứng và 2 muỗng canh rượu mạnh hoặc rượu cognac trong một tô lớn.', NULL, '2026-05-15 14:45:37', '2026-05-15 14:45:37'),
(2364, 355, 3, 'Giữ bơ trong vỏ bọc, bào một phần tư bơ vào tô, sau đó khuấy mọi thứ lại với nhau. Lặp lại cho đến khi tất cả bơ được nghiền mịn, sau đó khuấy trong 3-4 phút – hỗn hợp đã sẵn sàng khi nó lắng xuống một chút sau mỗi lần khuấy. Yêu cầu cả nhà khuấy đều và kêu gọi mọi người cùng ước.', NULL, '2026-05-15 14:45:37', '2026-05-15 14:45:37'),
(2365, 355, 4, 'Thoa đều bơ vào hai tô 1,2 lít và lót một vòng giấy nướng bánh vào đáy mỗi tô. Gói trong hỗn hợp bánh pudding. Phủ hai lớp giấy nướng, xếp nếp để giãn nở, sau đó buộc bằng dây (giữ tờ giấy cố định bằng dây chun trong khi buộc). Cắt bỏ phần giấy thừa.', NULL, '2026-05-15 14:45:37', '2026-05-15 14:45:37'),
(2366, 355, 5, 'Bây giờ, đặt mỗi chiếc bát lên một tờ giấy bạc lớn và úp các cạnh lên trên, sau đó đặt một tờ giấy bạc khác lên trên và úp xuống bên dưới để tạo thành một gói đôi (điều này làm cho bánh pudding không bị thấm nước). Buộc thêm dây và làm tay cầm để dễ dàng nhấc vào và lấy ra khỏi chảo. Hãy xem video của chúng tôi để biết cách buộc bánh pudding đúng cách.', NULL, '2026-05-15 14:45:37', '2026-05-15 14:45:37'),
(2367, 355, 6, 'Đun sôi hoặc hấp bánh pudding trong 8 giờ, thêm nước nếu cần. Lấy ra khỏi chảo và để nguội qua đêm. Khi nguội, loại bỏ lớp giấy gói lộn xộn và bọc lại bằng giấy nướng, giấy bạc và dây mới. Bảo quản ở nơi khô ráo, thoáng mát cho đến Giáng sinh.', NULL, '2026-05-15 14:45:37', '2026-05-15 14:45:37'),
(2368, 355, 7, 'Để làm bơ brandy, đánh bơ với vỏ cam và đường bột. Đổ dần dần rượu mạnh hoặc rượu cognac và gừng cắt nhỏ vào. Cho vào tô nhỏ, nĩa đẹp mắt rồi cho vào tủ lạnh để định hình. Bơ sẽ giữ được một tuần trong tủ lạnh hoặc có thể đông lạnh đến sáu tuần.', NULL, '2026-05-15 14:45:37', '2026-05-15 14:45:37'),
(2369, 355, 8, 'Vào ngày Giáng sinh, đun sôi hoặc hấp trong lò trong 1 giờ. Mở gói và bật ra. Để đốt lửa, làm ấm 3-4 muỗng canh rượu mạnh trong chảo nhỏ, đổ lên bánh pudding và đốt lửa.', NULL, '2026-05-15 14:45:37', '2026-05-15 14:45:37'),
(2370, 356, 1, 'Làm nóng lò ở nhiệt độ 300 độ F (150 độ C). Lót một tấm nướng bằng giấy da. Trải hạnh nhân lên khay nướng.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2371, 356, 2, 'Nướng trong lò làm nóng trước cho đến khi hạnh nhân thơm và rang, khoảng 20 đến 25 phút.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2372, 356, 3, 'Chuẩn bị bột làm bánh ngọt trong khi rang hạnh nhân. Trộn bột mì, 1/2 cốc cộng với 1 thìa bơ và muối vào tô rồi chà xát với nhau cho đến khi hỗn hợp giống như vụn bánh mì. Thêm trứng, dầu và 1 1/2 thìa nước hoa cam; nhào tất cả mọi thứ thành một khối bột bánh ngọt mịn. Thêm một ít nước, mỗi lần 1 thìa cà phê, nếu bột quá khô. Nặn bột bánh ngọt thành một quả bóng, bọc trong màng bọc thực phẩm và để yên trong 30 phút.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2373, 356, 4, 'Lấy hạnh nhân ra khỏi lò và để nguội một chút, khoảng 5 phút. Cho hạnh nhân vào tô của máy xay thực phẩm; xử lý cho đến khi được nghiền mịn và đồng đều. Thêm 3/4 cốc cộng với 1 thìa đường, quế, trứng và 1 thìa nước hoa cam vào máy xay thực phẩm, xay sau mỗi lần thêm cho đến khi hỗn hợp được kết hợp đồng đều và giống như một hỗn hợp sệt.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2374, 356, 5, 'Loại bỏ những phần nhân nhỏ cỡ quả óc chó bằng tay đã bôi mỡ. Cuộn chúng thành những khúc gỗ nhỏ có đầu mỏng. Đặt sang một bên.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2375, 356, 6, 'Làm nóng lò ở nhiệt độ 325 độ F (165 độ C). Lót một tấm nướng bằng giấy da.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2376, 356, 7, 'Cán một nửa số bột bánh ngọt trên bề mặt đã rắc chút bột mì cho đến khi thật mỏng. Đặt một trong những miếng bột hạnh nhân lên mép bánh ngọt, gấp bánh ngọt lên trên phần nhân, phủ kín hoàn toàn và bịt kín các mép. Dùng ngón tay nặn thành hình lưỡi liềm. Dùng dao cắt bánh ngọt, cắt xung quanh hình lưỡi liềm và chuyển sang khay nướng đã chuẩn bị sẵn. Lặp lại với phần bột và nhân còn lại.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2377, 356, 8, 'Nướng trong lò làm nóng trước cho đến khi sừng linh dương có màu vàng nhạt và nướng trong khoảng 20 phút. Chúng không nên quá tối. Để nguội một chút, khoảng 3 phút.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2378, 356, 9, 'Đun nóng mật ong trong chảo nhỏ trên lửa vừa và nhỏ. Tắt bếp và khuấy đều với 1 thìa nước hoa cam. Nhúng sừng linh dương vào mật ong và đặt lên đĩa phục vụ. Rắc quả hồ trăn nghiền nát.', NULL, '2026-05-15 14:45:42', '2026-05-15 14:45:42'),
(2380, 357, 1, 'Cho sữa, kem, thanh quế và tất cả vỏ cam quýt vào nồi đặt trên lửa vừa. Nấu và khuấy thường xuyên cho đến khi sữa vừa bốc hơi chứ không sôi, khoảng 3-5 phút. Tắt bếp, đậy bằng đĩa và để ngấm trong ít nhất 30 phút.', NULL, '2026-05-15 14:45:44', '2026-05-16 12:35:34');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(2382, 357, 2, 'Khi hỗn hợp kem đã ngấm, đánh lòng đỏ trứng, đường và bột ngô vào một bát riêng trong 3-5 phút hoặc cho đến khi có màu nhạt và nhạt. Đổ sữa đã lọc qua rây vào hỗn hợp trứng, đánh liên tục. Cho hỗn hợp trở lại nồi.', NULL, '2026-05-15 14:45:44', '2026-05-16 12:35:34'),
(2384, 357, 3, 'Đặt chảo lên lửa vừa cao và đánh đều trong khoảng 10-12 phút. Hỗn hợp sẽ bắt đầu đặc lại đến độ đặc giống như sữa trứng - bạn có thể nhận biết hỗn hợp đã sẵn sàng bằng cách nhúng thìa gỗ vào hỗn hợp, sau đó dùng ngón tay lướt qua hỗn hợp ở mặt sau của thìa. Nếu dòng giữ, nó đã sẵn sàng. Rây hỗn hợp vào bình để loại bỏ hết bọt.', NULL, '2026-05-15 14:45:44', '2026-05-16 12:35:34'),
(2386, 357, 4, 'Chia sữa trứng vào sáu đĩa ramekin 150ml hoặc đĩa đất nung nhỏ, sau đó để nguội trong 1 giờ ở nhiệt độ phòng cho đến khi đông lại với độ rung nhẹ. Thư giãn qua đêm.', NULL, '2026-05-15 14:45:44', '2026-05-16 12:35:34'),
(2388, 357, 5, 'Ngay trước khi dùng, rắc 1 muỗng canh đường bột lên trên mỗi chiếc ramekin và caramen bằng đèn khò nhà bếp. Ngoài ra, hãy đặt các ramekins dưới vỉ nướng nóng cho đến khi đường chuyển sang màu vàng và bắt đầu sủi bọt. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:45:44', '2026-05-16 12:35:34'),
(2389, 358, 1, 'Làm nóng lò ở nhiệt độ 350°F (180°C). Bôi mỡ vào chảo nướng hình vuông 8 inch (20 cm).', NULL, '2026-05-15 14:45:47', '2026-05-15 14:45:47'),
(2390, 358, 2, 'Để làm ngày tháng: Cho chà là và nước vào nồi vừa trên lửa cao và đun sôi. Giảm nhiệt xuống thấp và đun nhỏ lửa, thỉnh thoảng khuấy cho đến khi hỗn hợp đặc lại, khoảng 6 đến 8 phút. Tắt bếp, cho vani vào khuấy đều và để nguội. Đặt sang một bên.', NULL, '2026-05-15 14:45:47', '2026-05-15 14:45:47'),
(2391, 358, 3, 'Kết hợp yến mạch cán, bột mì, đường, baking soda và muối trong máy xay thực phẩm. Xung 3 lần (cẩn thận không trộn quá kỹ, không muốn hỗn hợp bị nhão mà chỉ hòa quyện thôi). Thêm bơ và xay lại cho đến khi hỗn hợp vụn thành từng cục cỡ hạt đậu. Chuyển sang tô trộn để trộn đều bơ.', NULL, '2026-05-15 14:45:47', '2026-05-15 14:45:47'),
(2392, 358, 4, 'Rải một nửa hỗn hợp yến mạch xuống đáy chảo nướng đã chuẩn bị sẵn, sau đó ấn xuống để tạo thành đáy phẳng, bằng phẳng. Thêm hỗn hợp chà là lên trên lớp vỏ và sau đó trải đều. Phủ hỗn hợp yến mạch còn lại lên và ấn xuống để làm phẳng lớp trên cùng.', NULL, '2026-05-15 14:45:47', '2026-05-15 14:45:47'),
(2393, 358, 5, 'Nướng ở giữa lò cho đến khi mặt trên có màu vàng nâu, từ 30 đến 35 phút. Để nguội hoàn toàn trong chảo trước khi cắt và phục vụ. Hình vuông chà là được bảo quản tốt, đậy kín trong tủ lạnh tối đa một tuần và đông lạnh từ 2 đến 3 tháng.', NULL, '2026-05-15 14:45:47', '2026-05-15 14:45:47'),
(2394, 359, 1, 'Kết hợp các thành phần: Trong một cái nồi lớn, có đáy nặng, trộn sữa, đường và baking soda. Nấu trên lửa nhỏ, khuấy liên tục để tránh bị cháy.', NULL, '2026-05-15 14:45:49', '2026-05-15 14:45:49'),
(2395, 359, 2, 'Làm đặc: Tiếp tục nấu, khuấy thường xuyên cho đến khi hỗn hợp trở nên đặc và có màu caramel, khoảng 1-2 giờ.', NULL, '2026-05-15 14:45:49', '2026-05-15 14:45:49'),
(2396, 359, 3, 'Hương vị: Khuấy chiết xuất vani.', NULL, '2026-05-15 14:45:49', '2026-05-15 14:45:49'),
(2397, 359, 4, 'Làm mát: Để dulce de leche nguội, sau đó chuyển vào lọ. Nó sẽ dày hơn nữa khi nó nguội đi.', NULL, '2026-05-15 14:45:50', '2026-05-15 14:45:50'),
(2398, 359, 5, 'Lời khuyên chuyên nghiệp:', NULL, '2026-05-15 14:45:50', '2026-05-15 14:45:50'),
(2399, 359, 6, 'Khuấy liên tục và để lửa nhỏ để sữa không bị cháy và dính đáy chảo.', NULL, '2026-05-15 14:45:50', '2026-05-15 14:45:50'),
(2400, 359, 7, 'Một giọt chiết xuất vani được thêm vào cuối quá trình nấu sẽ làm tăng hương vị.', NULL, '2026-05-15 14:45:50', '2026-05-15 14:45:50'),
(2401, 360, 1, 'Cho hạnh nhân vào một cái bát nhỏ và đổ nước sôi vừa đủ. Để trong 5 phút rồi lọc qua rây và để khô.', NULL, '2026-05-15 14:45:52', '2026-05-15 14:45:52'),
(2402, 360, 2, 'Làm nóng lò nướng ở nhiệt độ 180C/160 C quạt/Mã gas 4. Lót giấy nướng vào khuôn bánh có đáy rộng 20cm có đáy sâu.', NULL, '2026-05-15 14:45:52', '2026-05-15 14:45:52'),
(2403, 360, 3, 'Cho bơ vào tô lớn và đánh đều cho đến khi mềm. Thêm đường và đánh cho đến khi nhẹ và mịn. Khuấy vỏ cam và mứt mơ.', NULL, '2026-05-15 14:45:52', '2026-05-15 14:45:52'),
(2404, 360, 4, 'Rây bột mì và bột nở lại với nhau. Thêm từng quả trứng vào bơ kem và đường, đánh đều sau mỗi lần thêm. Nếu hỗn hợp bắt đầu đông lại, hãy thêm một ít bột mì vào.', NULL, '2026-05-15 14:45:52', '2026-05-15 14:45:52'),
(2405, 360, 5, 'Thêm bột mì còn lại và hạnh nhân xay vào, trộn đều. Trộn sữa vào sau đó cho hoa quả khô và quả anh đào vào trộn nhẹ nhàng.', NULL, '2026-05-15 14:45:52', '2026-05-15 14:45:52'),
(2406, 360, 6, 'Múc hỗn hợp vào khuôn đã chuẩn bị sẵn và dàn đều bằng mặt sau của thìa. Xếp các quả hạnh nhân gần nhau thành vòng tròn gọn gàng trên mặt bánh. Nướng trong lò trong 45 phút.', NULL, '2026-05-15 14:45:52', '2026-05-15 14:45:52'),
(2407, 360, 7, 'Hạ nhiệt độ lò xuống 160C/140 C quạt/Gas Mark 3 và nấu thêm 60–80 phút nữa. Kiểm tra bánh sau 50 phút bằng cách dùng que xiên bằng gỗ hoặc kim loại đâm vào bánh. Khi hoàn thành, nó chỉ còn lại một vài mẩu vụn. Kiểm tra 10 phút một lần - điều quan trọng là không nên nấu quá chín chiếc bánh này vì phần giữa sẽ hơi mềm.', NULL, '2026-05-15 14:45:52', '2026-05-15 14:45:52'),
(2408, 360, 8, 'Khi bánh chín, lấy bánh ra khỏi lò một thời gian ngắn, cho sữa và đường vào chảo nhỏ, đun nóng nhẹ cho đến khi đường tan. Quét lên mặt bánh và cho bánh vào lò nướng trong 2-3 phút. Lấy ra và để bánh nguội trong khuôn. Khi bánh khá nguội, lấy ra khỏi hộp thiếc, bọc trong giấy bạc và để ít nhất 2 ngày trước khi cắt.', NULL, '2026-05-15 14:45:52', '2026-05-15 14:45:52'),
(2409, 361, 1, 'Cho bột mì, 150 g đường, chút muối và 1 lòng đỏ trứng vào tô máy xay thực phẩm. Cắt bơ thành khối nhỏ và thêm vào bát. Biến nó thành một khối bột cứng. Đừng chế biến quá kỹ, bạn sẽ không muốn bột bị nóng. Kiểm tra xem nó có dính hay không bằng cách kẹp nó giữa các ngón tay của bạn.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2410, 361, 2, 'Biến thành một miếng bọc nhựa. Dùng tay tạo thành một quả bóng tròn và cuộn nó vào trong nhựa. Cho vào tủ lạnh nửa tiếng cho nguội.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2411, 361, 3, 'Lấy một khuôn nướng tròn có đường kính 22 cm và phủ giấy nướng lên trên. Chải các mặt bằng bơ.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2412, 361, 4, 'Làm nóng lò ở nhiệt độ 170˚C (340˚F)', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2413, 361, 5, 'Cắt táo thành khối vuông và trộn với nho khô, lượng đường còn sót lại và quế.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2414, 361, 6, 'Đặt khối bột đã nguội lên một mặt phẳng có rắc bột mì rồi cán thành tấm mỏng. Đặt cái này vào khay nướng và đậy kín đáy và các mặt. Tôi thường chỉ ấn nó vào hộp thiếc mà không lăn nó ra. Mình thấy đó là cách dễ nhất nhưng nó kém mượt mà hơn. Chỉ cần làm bất cứ điều gì có ích cho bạn.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2415, 361, 7, 'Hãy chắc chắn rằng bạn giữ riêng 1/4 khối bột để tạo thành các dải ở trên.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2416, 361, 8, 'Khi phần dưới và các mặt đã được phủ bột, hãy lấy những chiếc bánh quy và vò nát chúng ở phía dưới. Bạn cũng có thể sử dụng breadcrumbs cho việc này. Lắc nó một chút để nó được chia đều ở phía dưới.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2417, 361, 9, 'Thêm hỗn hợp táo và chia đều trên hộp thiếc. Cán phần bột còn lại và cắt thành dải. Đặt nó lên trên mặt bánh theo hình kim cương. Quét các đường và các mặt bằng lòng đỏ trứng còn lại rồi cho vào lò nướng đã làm nóng trước.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2418, 361, 10, 'Nướng bánh táo trong khoảng 1 giờ hoặc cho đến khi chín vàng. Để nguội trong hộp thiếc và đảm bảo các cạnh được lỏng ra trước khi mở hộp thiếc.', NULL, '2026-05-15 14:45:54', '2026-05-15 14:45:54'),
(2419, 362, 1, 'Cho bột vào tô lớn rồi thêm men và đường. Nếu sữa lạnh, hãy đảm bảo đun nóng đến mức ấm. Trộn từng chút hỗn hợp bột với sữa cho đến khi thu được hỗn hợp bột mịn. Thêm muối và trộn bằng thìa gỗ cho đến khi bột mịn và lỏng.', NULL, '2026-05-15 14:45:58', '2026-05-15 14:45:58'),
(2420, 362, 2, 'Đậy lại bằng một chiếc khăn trà sạch và để ở nơi ấm áp trong khoảng một giờ cho bột nở.', NULL, '2026-05-15 14:45:58', '2026-05-15 14:45:58'),
(2421, 362, 3, 'Đun nóng nồi chiên sâu hoặc thêm dầu vào nồi lớn. Dầu phải ở nhiệt độ 180˚C (350˚F) để có kết quả tốt nhất.', NULL, '2026-05-15 14:45:58', '2026-05-15 14:45:58'),
(2422, 362, 4, 'Trước khi bắt đầu khuấy đều bột và múc bột bằng hai thìa hoặc thìa kem. Hãy để nó thả vào dầu một cách cẩn thận. Cách dễ nhất để làm điều này là bạn nhúng thìa hoặc múc vào dầu trước khi nhúng vào bột. Bằng cách đó nó sẽ trượt thìa dễ dàng. Đừng để chảo chiên quá đông để tránh dầu nguội quá nhanh và mọi thứ dính vào nhau. Khi một mặt có màu nâu vàng, nó thường tự động quay sang mặt còn lại. Nếu không giúp nó cùng với hai nĩa.', NULL, '2026-05-15 14:45:58', '2026-05-15 14:45:58'),
(2423, 362, 5, 'Lấy những quả bóng ra khi đã có màu vàng nâu và để ráo nước trên một tờ giấy ăn.', NULL, '2026-05-15 14:45:58', '2026-05-15 14:45:58'),
(2424, 363, 1, 'Làm nóng lò ở 160˚C (320˚F) Lót giấy nến vào khay bánh và đặt sang một bên.', NULL, '2026-05-15 14:46:01', '2026-05-15 14:46:01'),
(2425, 363, 2, 'Trộn tất cả nguyên liệu khô với nhau trong một tô lớn. Cho sữa vào nồi nhỏ và đun nóng cho đến khi gần sôi nhưng chưa sôi hẳn.', NULL, '2026-05-15 14:46:01', '2026-05-15 14:46:01'),
(2426, 363, 3, 'Đổ sữa từ từ vào nguyên liệu khô trong khi đánh. Đừng trộn quá nhiều! Ngay sau khi nó được kết hợp thành một khối bột mịn, bạn đổ nó vào chảo bánh. Rắc đường trân châu lên trên và nướng trong lò khoảng 1 giờ.', NULL, '2026-05-15 14:46:01', '2026-05-15 14:46:01'),
(2427, 363, 4, 'Kiểm tra sau khoảng 50 phút bánh đang tiến triển như thế nào. Nếu người thử bánh bước ra làm sạch bánh đã chín. Nếu không hãy để nó nấu lâu hơn một chút.', NULL, '2026-05-15 14:46:01', '2026-05-15 14:46:01'),
(2428, 364, 1, 'Kết hợp sữa và men trong một cái bát. Để yên một lúc cho men tan hết.', NULL, '2026-05-15 14:46:03', '2026-05-15 14:46:03'),
(2429, 364, 2, 'Trong một tô khác, trộn bột mì, bơ, đường, trứng và muối. Đổ hỗn hợp men vào và nhào cho đến khi mịn. Đậy bát và để bột nở trong một giờ.', NULL, '2026-05-15 14:46:03', '2026-05-15 14:46:03'),
(2430, 364, 3, 'Khi bột gần như đã sẵn sàng, hãy làm nhân bánh. Cho tất cả nguyên liệu vào nồi và khuấy đều cho đến khi bơ tan chảy và đường tan. Hãy để nó sôi một lúc. Chất Stroop sẽ tiếp tục dày lên khi nó nguội đi.', NULL, '2026-05-15 14:46:03', '2026-05-15 14:46:03'),
(2431, 364, 4, 'Nặn bột thành từng viên nặng khoảng 35g. Tổng cộng là 14. Bật bàn ủi Stroopwafel của bạn ở cài đặt cao nhất.', NULL, '2026-05-15 14:46:03', '2026-05-15 14:46:03'),
(2432, 364, 5, 'Đặt một viên bột vào bàn ủi và đóng bàn ủi lại. Đừng làm phẳng bánh quế quá nhiều; bạn vẫn có thể vượt qua nó. Nướng trong 1-2 phút cho đến khi bánh quế có màu vàng nâu đẹp mắt.', NULL, '2026-05-15 14:46:03', '2026-05-15 14:46:03'),
(2433, 364, 6, 'Khi bánh quế đã xong, hãy làm việc nhanh chóng. Lấy bánh quế ra khỏi bàn ủi và ngay lập tức dùng dao cắt tròn cắt ra một hình tròn đẹp có đường kính khoảng 8 đến 9 cm (3 đến 3,5 inch).', NULL, '2026-05-15 14:46:03', '2026-05-15 14:46:03'),
(2434, 364, 7, 'Đặt bánh quế nóng lên thớt và dùng dao sắc cắt theo chiều ngang. Stroopwafel rất nóng nên hãy dùng găng tay lò nướng để giữ cố định.', NULL, '2026-05-15 14:46:03', '2026-05-15 14:46:03'),
(2435, 364, 8, 'Lấy một nửa chiếc bánh quế và phết nước sốt (nóng!) lên đó. Đặt nửa còn lại lên trên, ấn nhẹ nếu cần và đặt bánh quế lên giá lưới để nguội. Lặp lại cho tất cả các quả bóng.', NULL, '2026-05-15 14:46:03', '2026-05-15 14:46:03'),
(2436, 365, 1, 'Chuẩn bị hạnh nhân vào ngày hôm trước. Đun sôi 6 cốc nước. Tắt bếp và thêm hạnh nhân vào. Hạnh nhân ngâm trong nước khoảng 5 phút rồi vớt ra để ráo nước. Trải hạnh nhân lên khay nướng và nướng ở nhiệt độ 200 độ F (95 độ C) cho đến khi khô hoàn toàn và nướng. Việc này mất vài giờ và cần được chuẩn bị trước. Hãy cẩn thận để không làm cháy các loại hạt vì điều này sẽ tạo ra vị đắng cho nhân.', NULL, '2026-05-15 14:46:05', '2026-05-15 14:46:05'),
(2437, 365, 2, 'Cho 1 cốc đường và 1 cốc nước vào nồi, đun sôi. Thêm 1 thìa cà phê nước cốt chanh, giảm nhiệt xuống thấp và đun nhỏ lửa cho đến khi có dạng siro, khoảng 30 đến 40 phút. Khuấy nước hoa cam và tắt bếp. Đặt xi-rô đường sang một bên.', NULL, '2026-05-15 14:46:05', '2026-05-15 14:46:05'),
(2438, 365, 3, 'Trộn bột mì và muối vào một tô trộn lớn. Tạo một lỗ ở giữa rồi đổ dầu, trứng, 1/2 thìa nước cốt chanh và 1 thìa nước hoa cam vào giữa. Trộn bằng ngón tay cho đến khi bột giống như vụn thô. Dần dần rắc nước ấm trong khi trộn cho đến khi bột trở nên mềm và dẻo. Chia thành 4 phần bằng nhau. Che bột bằng một miếng vải ướt và đặt sang một bên.', NULL, '2026-05-15 14:46:05', '2026-05-15 14:46:05'),
(2439, 365, 4, 'Trong máy xay thực phẩm, nghiền mịn hạnh nhân. Đong 3 cốc hạnh nhân nghiền mịn cho vào tô trộn, khuấy đều với 1 cốc đường, bột nở, bột vani, vỏ chanh và 2 thìa nước hoa cam. Trộn lần lượt ba quả trứng vào, khuấy liên tục; trộn cho đến khi bạn có được một hỗn hợp dính, giống như bột nhão.', NULL, '2026-05-15 14:46:05', '2026-05-15 14:46:05'),
(2440, 365, 5, 'Rắc bột ngô lên mặt cán để chống dính. Cán từng phần bột thật mỏng, từ 1 đến 2 mm (1/16 inch). Cắt bột đã cán thành các hình tròn có đường kính khoảng 10 cm (4 inch). Lau nhẹ bề mặt của từng hình tròn bằng bột ngô rồi cho vào khuôn bánh tart, úp mặt bột ngô xuống để chống dính. Nhẹ nhàng ấn bột vào các cạnh và đáy khuôn, đồng thời cắt bớt phần bột thừa ở xung quanh viền. Đổ nhân hạnh nhân vào 3/4 mỗi khuôn.', NULL, '2026-05-15 14:46:05', '2026-05-15 14:46:05'),
(2441, 365, 6, 'Nướng trên kệ trên cùng ở nhiệt độ 350 độ F (175 độ C) trong 20 đến 25 phút hoặc cho đến khi bề mặt bánh vàng và bột cứng. Lấy bánh tart ra khỏi khuôn ngay khi chúng ra khỏi lò. Nhúng từng chiếc bánh tart vào nước đường khi còn nóng. Dán một hạt thông vào giữa mỗi chiếc bánh để trang trí. Đặt trên giá lưới cho ráo nước.', NULL, '2026-05-15 14:46:05', '2026-05-15 14:46:05'),
(2442, 366, 1, 'Để làm bánh ngọt, hãy cắt bơ thành hạt lựu và cho vào ngăn đá tủ lạnh cho thật cứng. Đổ bột mì vào tô của máy xay thực phẩm cùng với một nửa bơ và xay theo kết cấu vụn bánh mì. Đổ nước cốt chanh và 100ml nước đá vào, trộn đều thành khối. Đổ phần bơ còn lại vào và đập vài lần cho đến khi bột dính nhiều bơ. Điều quan trọng là bạn không nên lạm dụng quá nhiều vì những hạt bơ chính là nguyên nhân khiến bánh bị bong tróc.', NULL, '2026-05-15 14:46:08', '2026-05-15 14:46:08'),
(2443, 366, 2, 'Trên bề mặt đã phủ bột mì, cán bánh thành hình chữ nhật gọn gàng có kích thước khoảng 20 x 30cm. Gấp 2 đầu bánh vào giữa (xem hình 1), sau đó gấp làm đôi (ảnh 2). Lăn bánh ra một lần nữa và gấp lại theo cách tương tự thêm 3 lần nữa, để bánh nghỉ ít nhất 15 phút, mỗi lần giữa cuộn và gấp, sau đó để bánh nghỉ trong tủ lạnh ít nhất 30 phút trước khi sử dụng.', NULL, '2026-05-15 14:46:08', '2026-05-15 14:46:08'),
(2444, 366, 3, 'Để làm nhân, làm tan chảy bơ trong một cái chảo lớn. Tắt lửa và khuấy tất cả các thành phần khác cho đến khi trộn hoàn toàn, sau đó đặt sang một bên.', NULL, '2026-05-15 14:46:08', '2026-05-15 14:46:08'),
(2445, 366, 4, 'Để làm bánh, hãy cán bánh ra cho đến khi nó dày hơn đồng xu 1 bảng một chút và cắt ra 8 vòng tròn có chiều ngang khoảng 12 cm. Cuộn lại phần cắt tỉa nếu cần. Đặt một thìa hỗn hợp đã trộn đều vào giữa mỗi viên tròn, phết nước lên các cạnh của viên tròn, sau đó gom bánh ngọt xung quanh phần nhân và ép lại với nhau (ảnh 3). Lật chúng lại để phần trên nhẵn hướng lên trên và vỗ chúng thành một vòng tròn mịn. Dùng cán cán dẹt từng vòng thành hình bầu dục cho đến khi quả vừa bắt đầu xuyên qua thì đặt lên khay nướng. Cắt 2 khe nhỏ trên mỗi chiếc bánh Eccles, phết một lớp lòng trắng trứng lên trên và rắc đường (ảnh 4).', NULL, '2026-05-15 14:46:08', '2026-05-15 14:46:08'),
(2446, 366, 5, 'Làm nóng lò ở nhiệt độ 220C/200C quạt/gas 8. Nướng bánh Eccles trong 15-20 phút cho đến khi vừa chuyển sang màu nâu vàng và dính. Để nguội trên giá và thưởng thức khi còn ấm hoặc lạnh với một tách trà. Nếu bạn thích, bánh Eccles cũng rất hợp ăn kèm với một miếng pho mát Anh cứng và thơm như Lancashire hoặc cheddar.', NULL, '2026-05-15 14:46:08', '2026-05-15 14:46:08'),
(2448, 367, 1, 'Đổ 230ml nước ấm vào tô và thêm men. Để yên trong 3 phút, sau đó thêm đường bột, trứng, bột mì và 1 muỗng cà phê muối biển vào. Trộn với nhau để tạo thành bột, sau đó nhào trong 10 phút trong máy trộn đứng bằng móc bột (hoặc 15 phút bằng tay) cho đến khi bột đủ đàn hồi để gần như nhìn xuyên qua khi kéo căng. Đậy nắp và để yên trong 30 phút, sau đó cắt thành bốn miếng bằng nhau. Chuyển sang khay nướng có lót giấy nướng. Để yên thêm 30 phút nữa.', NULL, '2026-05-15 14:46:12', '2026-05-16 12:35:34'),
(2450, 367, 2, 'Bôi dầu thực vật lên bề mặt làm việc và cán lăn. Mỗi lần làm từng phần bột, dùng lòng bàn tay ấn dẹt bột xuống bề mặt, sau đó cán bột thành hình chữ nhật mỏng, khoảng 30 x 50cm. Để yên trong 2 phút trong khi bạn phết một phần tư mỡ lợn lên trên. (Nếu bạn muốn lấp đầy bánh ngọt của mình bằng sobrasada de Mallorca, hãy trộn 50g mỡ lợn với sobrasada và phết phần này lên bột.) Kéo một góc của miếng bột dẹt và kéo căng nó ra xa nhất có thể mà không bị vỡ. Lặp lại khoảng 10 cm xung quanh hình chữ nhật bột theo mọi hướng cho đến khi đạt kích thước khoảng 50 x 70 cm.', NULL, '2026-05-15 14:46:12', '2026-05-16 12:35:34'),
(2452, 367, 3, 'Cắt một dải từ mỗi cạnh ngắn hơn và đặt chúng cạnh nhau dọc theo một trong các cạnh dài hơn của hình chữ nhật; đây là cái mà chúng tôi gọi là trái tim của ensaimada. Từ đó, bắt đầu cán bột cho đến khi bạn có được một chiếc bánh ngọt dài. Lặp lại với các phần bột còn lại.', NULL, '2026-05-15 14:46:12', '2026-05-16 12:35:34'),
(2454, 367, 4, 'Lấy cuộn bột đầu tiên và kéo căng cho đến khi dài hơn một mét. Sau đó, cuộn bột lại thành hình xoắn ốc, chừa khoảng cách 1cm giữa mỗi vòng xoắn ốc để bột có thể nở ra. Làm phẳng một chút và chuyển sang khay nướng có lót giấy nướng. Lặp lại với phần bột còn lại. Để ở nơi ấm áp ít nhất 12 giờ, hoặc lý tưởng nhất là 24 giờ.', NULL, '2026-05-15 14:46:12', '2026-05-16 12:35:34'),
(2456, 367, 5, 'Làm nóng lò ở mức quạt/gas 200C/180C 6. Đặt ensaimadas vào phần trên cùng của lò và giảm nhiệt độ ngay xuống 180C/160C quạt/gas 4. Nướng trong 18 phút cho đến khi vàng sẫm. Để nguội trên giá lưới. Để phủ kem tươi lên món ensaimada của bạn, hãy cắt lát và mở ra, sau đó phết kem lên và đóng lại. Rắc một lượng lớn đường bột nếu bạn thích và cắt thành từng miếng để thưởng thức.', NULL, '2026-05-15 14:46:12', '2026-05-16 12:35:34'),
(2457, 368, 1, 'Nghiền một nửa quả dâu tây trong máy xay sinh tố. Cắt nhỏ những quả dâu tây còn lại, để dành 4 quả để trang trí.', NULL, '2026-05-15 14:46:14', '2026-05-15 14:46:14'),
(2458, 368, 2, 'Đánh kem đôi cho đến khi tạo thành chóp cứng, sau đó cho dâu tây xay nhuyễn và bánh trứng đường nghiền vào. Cho dâu tây cắt nhỏ và nước gừng vào nếu dùng.', NULL, '2026-05-15 14:46:14', '2026-05-15 14:46:14'),
(2459, 368, 3, 'Múc một lượng hỗn hợp bằng nhau vào bốn ly rượu lạnh. Phục vụ trang trí với dâu tây còn lại và một nhánh bạc hà.', NULL, '2026-05-15 14:46:14', '2026-05-15 14:46:14'),
(2460, 369, 1, 'Trong một tô vừa, trộn đều bột mì, đường nâu, bột nở và gia vị.', NULL, '2026-05-15 14:46:17', '2026-05-15 14:46:17'),
(2461, 369, 2, 'Thêm nho khô vào và khuấy đều, đảm bảo phủ nho khô vào hỗn hợp bột.', NULL, '2026-05-15 14:46:17', '2026-05-15 14:46:17'),
(2462, 369, 3, 'Thêm bơ tan chảy, mật đường và nước vào rồi trộn bằng thìa gỗ. Tạo thành một quả bóng bằng thìa hoặc tay và cho viên bột vào túi đựng bánh pudding bằng vải bông. Buộc túi lại, chừa khoảng trống ít nhất 1 inch để bánh pudding nở ra trong khi nấu.', NULL, '2026-05-15 14:46:17', '2026-05-15 14:46:17'),
(2463, 369, 4, 'Đun sôi bánh pudding trong 1,5 giờ. (Ở NL, việc này thường được thực hiện trong nồi cùng với Bữa tối của Jiggs, nhưng nó có thể được thực hiện độc lập.)', NULL, '2026-05-15 14:46:17', '2026-05-15 14:46:17'),
(2464, 369, 5, 'Khi bánh đã cứng lại, vớt ra khỏi nước sôi và để nguội một chút trước khi lấy ra khỏi túi bánh pudding.', NULL, '2026-05-15 14:46:17', '2026-05-15 14:46:17'),
(2465, 369, 6, 'Cắt bánh pudding như một chiếc bánh ngọt và dùng kèm với nước sốt ấm mà bạn chọn: sốt bơ rượu rum, mật đường ấm hoặc sốt Mật đường Coady (1 cốc (250 mL) mật đường, 1/4 cốc (60 mL) bơ, 1/4 cốc (60 mL) nước) là loại phổ biến ở Newfoundland.', NULL, '2026-05-15 14:46:17', '2026-05-15 14:46:17'),
(2466, 370, 1, 'Đối với caramen, cho 100 gam đường vào chảo rán không có mỡ và đun chảy ở lửa vừa. Cố gắng không khuấy bằng thìa mà hãy xoay chảo. Để tan chảy cho đến khi bạn có màu hổ phách và đường tan chảy hoàn toàn. Đổ đầy vào đáy bốn hộp đựng bánh flan. Caramel sẽ cứng lại ngay nên bạn cần phải nhanh tay. Thùng chứa của tôi mang lại khoảng 120 ml mỗi thùng.', NULL, '2026-05-15 14:46:19', '2026-05-15 14:46:19'),
(2467, 370, 2, 'Làm nóng lò nướng ở nhiệt độ 150 độ C và tìm một cái nồi hoặc hộp đựng vừa đủ bốn hộp đựng bánh flan của bạn.', NULL, '2026-05-15 14:46:19', '2026-05-15 14:46:19'),
(2468, 370, 3, 'Đun nóng sữa với 45 gam đường rồi cắt vỏ vani. Sữa không cần đun sôi, chỉ cần đun nóng. Lấy vỏ vani ra sau vài phút. Trong khi đó, khuấy nhẹ lòng đỏ trứng và trứng, cố gắng không để lẫn không khí vào. Họ đổ hỗn hợp sữa vào hỗn hợp trứng và chỉ khuấy lại thật nhẹ nhàng. Đổ vào các hộp đựng bánh flan đã chuẩn bị sẵn và đặt chúng vào nồi hoặc hộp đựng của bạn. Đun sôi nước và đổ nước vào nồi lớn. Đảm bảo không chạm vào hỗn hợp bánh flan. Đặt trên giá giữa trong lò và nướng trong khoảng 35-40 phút. Một cây tăm được cắm vào sẽ sạch sẽ.', NULL, '2026-05-15 14:46:19', '2026-05-15 14:46:19'),
(2469, 370, 4, 'Để nguội bên trong hộp trong một giờ trước khi chuyển vào tủ lạnh. Thư giãn qua đêm. Ngày hôm sau nhẹ nhàng thả vành bánh ra rồi úp ngược ra đĩa. Ăn kèm với một ít dulce de leche bên cạnh.', NULL, '2026-05-15 14:46:19', '2026-05-15 14:46:19'),
(2470, 371, 1, 'Làm nóng lò ở nhiệt độ 350˚F.', NULL, '2026-05-15 14:46:22', '2026-05-15 14:46:22'),
(2471, 371, 2, 'Trộn tất cả nguyên liệu làm vỏ bánh (mụn bánh quy giòn graham, bơ tan chảy, đường cát và quế xay) trong tô vừa. Dành khoảng 2 muỗng canh (30 mL) cho lần sau và ấn hỗn hợp vào đĩa bánh sâu 9 inch ở dưới cùng và lên trên các mặt. Nướng vỏ bánh trong 10 phút, bánh sẽ chỉ hơi nâu.', NULL, '2026-05-15 14:46:22', '2026-05-15 14:46:22'),
(2472, 371, 3, 'Kết hợp các nguyên liệu làm nhân sữa trứng vani (sữa, đường cát, bột ngô, lòng đỏ trứng, chiết xuất vani và muối với nhau) và nấu trên lửa vừa, khuấy liên tục cho đến khi sủi bọt và đặc lại như kết cấu của bánh pudding. Đặt sang một bên để nguội trong khi bạn làm lớp phủ meringue.', NULL, '2026-05-15 14:46:22', '2026-05-15 14:46:22'),
(2473, 371, 4, 'Trong tô của máy trộn đứng có gắn phụ kiện máy đánh trứng hoặc trong tô lớn sử dụng máy trộn điện, đánh đều các nguyên liệu làm bánh trứng đường (lòng trắng trứng, đường cát, kem tartar) với nhau cho đến khi có chóp cứng và bóng.', NULL, '2026-05-15 14:46:22', '2026-05-15 14:46:22'),
(2474, 371, 5, 'Để gói bánh, đổ nhân vào vỏ bánh và phủ một lớp bánh trứng đường dày lên trên, tạo thành những chiếc gai nhỏ sẽ có màu nâu ở trên. Rắc phần vụn bánh đã để sẵn lên trên và cho vào lò nướng đã làm nóng trước.', NULL, '2026-05-15 14:46:22', '2026-05-15 14:46:22'),
(2475, 371, 6, 'Nướng cho đến khi bánh trứng đường có màu nâu, khoảng 10 phút, nhớ quan sát cẩn thận.', NULL, '2026-05-15 14:46:22', '2026-05-15 14:46:22'),
(2476, 371, 7, 'Làm lạnh trong tủ lạnh và ăn trong vòng vài giờ sau khi nướng. Bánh này ngon nhất nên ăn trong ngày vì bánh trứng đường sẽ mềm và lỏng.', NULL, '2026-05-15 14:46:22', '2026-05-15 14:46:22'),
(2477, 372, 1, 'vỏ bánh', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2478, 372, 2, 'Trộn đường, vani và bơ cho đến khi mịn và nhẹ. Trộn lòng đỏ trứng vào. Cho bột mì và bột nở vào, dùng tay nhào cho đến khi bột mịn.', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2479, 372, 3, 'Gói bột trong màng bọc thực phẩm và để lạnh trong tủ lạnh ít nhất 30 phút.', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2480, 372, 4, 'nhân hạnh nhân', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2481, 372, 5, 'Cho hạnh nhân và đường vào máy xay thực phẩm cho đến khi hạnh nhân được nghiền mịn (bạn có thể tự quyết định độ thô hay mịn mà mình muốn).', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2482, 372, 6, 'Khuấy bơ, trứng, rượu cognac và/hoặc chiết xuất hạnh nhân (nếu sử dụng).', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2483, 372, 7, 'Lót giấy nướng vào đáy khuôn bánh và bôi mỡ vào các cạnh của khuôn.', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2484, 372, 8, 'Làm nóng lò ở nhiệt độ 350°F (175°C).', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2485, 372, 9, 'Cắt 2/3 phần bột vỏ bánh thành từng lát rồi ấn xuống thành dạng bánh. Phủ bột vào phần dưới của khuôn bánh và đưa bột lên 2-3 cm (1 inch) lên các cạnh của khuôn, ấn cho đến khi đều.', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2486, 372, 10, 'Múc nhân hạnh nhân lên trên vỏ bánh, dàn đều khắp khuôn bánh.', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2487, 372, 11, 'Cán phần bột còn lại và cắt thành dải dài. Xếp các dải bột lên bánh theo dạng lưới. Đừng lo lắng về việc các dải giấy bị đứt - chỉ cần ấn chúng lại với nhau trên bánh.', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2488, 372, 12, 'Nhẹ nhàng chải bột bằng nước rửa trứng.', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2489, 372, 13, 'Nướng trong khoảng 45 phút. Mặt trên của bánh phải có màu nâu vàng trong khi nhân hạnh nhân vẫn mềm.', NULL, '2026-05-15 14:46:26', '2026-05-15 14:46:26'),
(2490, 373, 1, 'Trộn bột mì tự nổi, đường, hỗn hợp gia vị speculaas và muối. Thêm bơ và sữa vào rồi nhào thành một khối bột cứng. Bắt đầu với 6 thìa sữa, nếu bột quá cứng bạn có thể cho thêm sữa.', NULL, '2026-05-15 14:46:31', '2026-05-15 14:46:31'),
(2491, 373, 2, 'Bọc bột trong màng bọc thực phẩm và để lạnh qua đêm. Bạn có thể chế biến và nướng ngay nhưng hương vị sẽ ngon hơn rất nhiều nếu bạn để yên.', NULL, '2026-05-15 14:46:31', '2026-05-15 14:46:31'),
(2492, 373, 3, 'Trộn bột hạnh nhân với một nửa quả trứng đã đánh và nhào đều. Điều này làm cho nó dễ dàng hơn để làm việc và mang lại cho nó một kết cấu tốt hơn và ngon hơn.', NULL, '2026-05-15 14:46:31', '2026-05-15 14:46:31'),
(2493, 373, 4, 'Lấy một nửa khối bột và cán thành kích thước 20 x 20 cm. Đặt vào khay nướng có lót giấy da. Trải đều hỗn hợp bột hạnh nhân. Cán mỏng phần bột còn lại và đặt lên trên lớp bột hạnh nhân.', NULL, '2026-05-15 14:46:31', '2026-05-15 14:46:31'),
(2494, 373, 5, 'Phủ phần trứng đã đánh còn lại lên trên. Trang trí với hạnh nhân và phủ một lớp trứng khác lên trên.', NULL, '2026-05-15 14:46:31', '2026-05-15 14:46:31'),
(2495, 373, 6, 'Nướng những chiếc bánh đã làm đầy trong 40 phút ở 180°C/350℉ (lò nướng thông thường) hoặc cho đến khi chín.', NULL, '2026-05-15 14:46:31', '2026-05-15 14:46:31'),
(2496, 374, 1, 'Trong một tô lớn, sử dụng máy trộn điện để đánh kem đặc lạnh cho đến khi tạo thành chóp cứng. Nhẹ nhàng trộn sữa đặc có đường và chiết xuất vani vào cho đến khi hòa quyện.', NULL, '2026-05-15 14:46:33', '2026-05-15 14:46:33'),
(2497, 374, 2, 'Cho ngũ cốc vào và khuấy đều cho đến khi phân bố đều khắp hỗn hợp.', NULL, '2026-05-15 14:46:33', '2026-05-15 14:46:33'),
(2498, 374, 3, 'Đổ hỗn hợp vào hộp đựng an toàn trong tủ đông (chẳng hạn như khuôn làm bánh mì). Đặt màng bọc thực phẩm lên trên kem để tránh bị cháy tủ đông. Đậy nắp hộp và để đông ít nhất 6 giờ hoặc cho đến khi cứng lại.', NULL, '2026-05-15 14:46:33', '2026-05-15 14:46:33'),
(2499, 374, 4, 'Sau khi đông lạnh, hãy để kem ở nhiệt độ phòng trong vài phút để hơi mềm trước khi múc và dùng.', NULL, '2026-05-15 14:46:33', '2026-05-15 14:46:33'),
(2500, 375, 1, 'Làm nóng lò ở nhiệt độ quạt/khí 160C/140C 3. Dùng cán cán nghiền nát bánh quy và hầu hết hạnh nhân bên trong túi nhựa đựng thực phẩm. Trộn với bơ, sau đó ấn vào đáy đĩa sâu, hình bầu dục, đường kính 23cm (hoặc vật gì đó có kích thước tương tự - khuôn nướng, khuôn nướng hoặc khuôn làm bánh đều phù hợp). Nướng trong 10 phút cho đến khi giòn.', NULL, '2026-05-15 14:46:36', '2026-05-15 14:46:36'),
(2501, 375, 2, 'Khuấy hoặc nghiền nhuyễn sữa chua và mascarpone, sau đó cho từng quả trứng vào đánh đều. Khuấy vỏ chanh và cam, sau đó cho phần lớn mật ong vào, chừa lại khoảng 3 muỗng canh. Trải đều trên đế bánh quy, phủ nhẹ bằng giấy bạc và nấu trong 1 giờ. Lấy giấy bạc ra và nấu thêm 15 phút cho đến khi vàng nhạt và mặt trên cứng lại, chỉ hơi rung nhẹ ở giữa. Để nguội. Có thể bảo quản trong tủ lạnh tối đa 2 ngày.', NULL, '2026-05-15 14:46:36', '2026-05-15 14:46:36'),
(2502, 375, 3, 'Để phục vụ, hãy rắc hạnh nhân, rưới lên lượng mật ong còn lại và đưa trái cây tươi đi kèm.', NULL, '2026-05-15 14:46:36', '2026-05-15 14:46:36'),
(2503, 376, 1, 'Lót một khay nướng hình vuông 8 inch bằng giấy sáp hoặc giấy bạc và phủ một lớp xịt chống dính.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2504, 376, 2, 'Trong một chiếc bát an toàn với lò vi sóng, trộn sô cô la đen, kem béo và một nửa sữa đặc có đường. Cho hỗn hợp sô cô la đen vào lò vi sóng trong khoảng thời gian 20 giây, khuấy đều giữa mỗi khoảng thời gian cho đến khi sô cô la tan chảy.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2505, 376, 3, 'Thêm chiết xuất vani vào hỗn hợp sô cô la đen và khuấy đều cho đến khi mịn.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2506, 376, 4, 'Chuyển hỗn hợp sô cô la đen vào chảo đã chuẩn bị sẵn và dàn đều thành một lớp.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2507, 376, 5, 'Trong một bát riêng, trộn sô cô la trắng với nửa sữa đặc có đường còn lại. Cho hỗn hợp sô cô la trắng vào lò vi sóng trong khoảng thời gian 20 giây, khuấy đều giữa mỗi khoảng thời gian cho đến khi sô cô la tan chảy.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2508, 376, 6, 'Trải đều hỗn hợp sô cô la trắng lên trên lớp sô cô la đen.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2509, 376, 7, 'Phủ Mallow Bits hoặc kẹo dẻo thu nhỏ lên trên các lớp sô cô la và nhẹ nhàng ấn chúng xuống.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2510, 376, 8, 'Làm lạnh trong 4 giờ hoặc cho đến khi đông lại.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2511, 376, 9, 'Lấy giấy nến và giấy sáp ra khỏi chảo. Cẩn thận bóc toàn bộ giấy sáp ra khỏi kẹo mềm.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2512, 376, 10, 'Cắt kẹo mềm thành từng miếng vừa ăn và thưởng thức.', NULL, '2026-05-15 14:46:39', '2026-05-15 14:46:39'),
(2513, 377, 1, 'Làm nóng lò ở nhiệt độ 350°F (180°C) và lót giấy nến vào khay nướng lớn.', NULL, '2026-05-15 14:46:42', '2026-05-15 14:46:42'),
(2514, 377, 2, 'Trong máy trộn đứng có gắn cánh khuấy, đánh bơ, đường trắng và trứng cho đến khi hòa quyện, sau đó thêm mật đường và vani vào và trộn cho đến khi mịn.', NULL, '2026-05-15 14:46:42', '2026-05-15 14:46:42'),
(2515, 377, 3, 'Sau khi kết hợp, thêm hỗn hợp nước baking soda và trộn thêm một phút nữa để kết hợp.', NULL, '2026-05-15 14:46:42', '2026-05-15 14:46:42'),
(2516, 377, 4, 'Kết hợp các thành phần khô; trộn bột nở, quế, bột mì và muối trong một bát riêng, sau đó thêm từng chút một vào nguyên liệu ướt, trộn ở mức thấp cho đến khi hòa quyện hoàn toàn và cạo các mặt để đảm bảo mọi thứ được hòa quyện. Bột phải dễ tạo hình.', NULL, '2026-05-15 14:46:42', '2026-05-15 14:46:42'),
(2517, 377, 5, 'Chia bột bằng một chiếc thìa nhỏ, vo thành từng quả bóng và đặt chúng lên khay bánh quy đã lót giấy, dùng cốc thủy tinh có bột mì hoặc lòng bàn tay ẩm ấn chúng thành những đĩa phẳng.', NULL, '2026-05-15 14:46:42', '2026-05-15 14:46:42'),
(2518, 377, 6, 'Đặt bánh lên khay nướng có lót giấy nến và nướng trong vòng 10-12 phút. Lấy ra khỏi lò và để chúng nguội trong ít nhất 10 phút.', NULL, '2026-05-15 14:46:42', '2026-05-15 14:46:42'),
(2519, 377, 7, 'Sau khi làm nguội bánh quy bằng cách phết ít nhất hai thìa cà phê mứt yêu thích của bạn vào giữa hai chiếc bánh quy. Lặp lại và thưởng thức với một tách trà.', NULL, '2026-05-15 14:46:42', '2026-05-15 14:46:42'),
(2520, 378, 1, 'Đặt một khay nướng sâu lòng vào kệ dưới cùng của lò và đảm bảo có một kệ khác ngay phía trên nó. Kéo khay nướng ra trên kệ, đổ nước sôi vào 2/3 ấm rồi cẩn thận trượt khay trở lại. Làm nóng lò ở mức quạt/khí 180C/160C 4. Xé một tờ giấy bạc và giấy thấm dầu lớn (khoảng 30 x 40cm). Đặt lớp chống thấm dầu lên trên giấy bạc và phết bơ lên ​​trên.', NULL, '2026-05-15 14:46:45', '2026-05-15 14:46:45'),
(2521, 378, 2, 'Cho bơ, bột mì và hạt vani vào máy xay thực phẩm; đập cho đến khi bơ biến mất. Đổ vào tô trộn. Khuấy đều mỡ, đổ sữa vào và dùng dao nĩa nhào cho đến khi thu được khối bột dính. Bạn có thể cần thêm một giọt sữa, tùy thuộc vào loại bột của bạn.', NULL, '2026-05-15 14:46:45', '2026-05-15 14:46:45'),
(2522, 378, 3, 'Đổ bột ra bề mặt đã rắc bột mì, vỗ nhanh cho bột mịn rồi cán thành hình vuông khoảng 25 x 25 cm. Trải mứt khắp nơi, để lại một khoảng trống dọc theo một cạnh, sau đó cuộn lên từ cạnh đối diện. Chụm phần mép không bị kẹt vào miếng bột nơi nó tiếp xúc và cũng kẹp thật mạnh phần cuối. Cẩn thận nhấc tờ giấy đã phết dầu lên, úp mặt xuống (bạn có thể thấy một tấm nướng phẳng hữu ích cho việc này), nhẹ nhàng đưa giấy và giấy bạc xung quanh nó lên, sau đó kẹp lại dọc theo các cạnh và đầu để bịt kín. Roly-poly sẽ phồng lên khá nhiều trong khi nấu nên đừng quấn chặt. Nhấc gói trực tiếp lên giá phía trên hộp thiếc và nấu trong 1 giờ.', NULL, '2026-05-15 14:46:45', '2026-05-15 14:46:45'),
(2523, 378, 4, 'Để bánh pudding trong 5 phút trước khi mở gói, sau đó cẩn thận mở giấy bạc và giấy bạc rồi cắt thành lát dày để thưởng thức.', NULL, '2026-05-15 14:46:45', '2026-05-15 14:46:45'),
(2524, 379, 1, 'Nghiền chuối bằng nĩa trong bát.', NULL, '2026-05-15 14:46:51', '2026-05-15 14:46:51'),
(2525, 379, 2, 'Thêm đường nâu, vani, chiết xuất, quế, nhục đậu khấu và một chút muối. Rây bột vào và dùng thìa khuấy đều cho đến khi hòa quyện hoàn toàn.', NULL, '2026-05-15 14:46:51', '2026-05-15 14:46:51'),
(2526, 379, 3, 'Thêm dầu vào chảo 10 inch trên lửa vừa cao. Khi dầu nóng, thả từng thìa bột chiên chuối vào dầu. Khi một mặt đã vàng và xuất hiện bong bóng ở trên, hãy lật bánh rán và nấu cho đến khi mặt còn lại cũng chuyển sang màu nâu.', NULL, '2026-05-15 14:46:51', '2026-05-15 14:46:51'),
(2527, 379, 4, 'Loại bỏ rán và để ráo trên khăn giấy. Thưởng thức', NULL, '2026-05-15 14:46:51', '2026-05-15 14:46:51'),
(2528, 380, 1, 'Ngâm nho khô, nho khô và anh đào vào 1 cốc bia. Đặt sang một bên và để ngâm trong 30 phút.', NULL, '2026-05-15 14:46:54', '2026-05-15 14:46:54'),
(2529, 380, 2, 'Làm nóng lò ở nhiệt độ 325 độ F. Bôi mỡ vào chảo ổ bánh mì 8x4. Đặt sang một bên.', NULL, '2026-05-15 14:46:54', '2026-05-15 14:46:54'),
(2530, 380, 3, 'Trộn bột mì đa dụng, bột nở, quế xay, muối vào tô lớn và đặt sang một bên.', NULL, '2026-05-15 14:46:54', '2026-05-15 14:46:54'),
(2531, 380, 4, 'Trong một bát khác, trộn đường nâu, trứng, sữa, mật ong, bơ tan chảy, mật đường, đường nâu, chiết xuất vani và bia ngâm trái cây. Đừng đổ trái cây vào lúc này, chỉ đổ bia thôi. Trộn để kết hợp.', NULL, '2026-05-15 14:46:54', '2026-05-15 14:46:54'),
(2532, 380, 5, 'Lấy 2 thìa bột mì ra khỏi hỗn hợp bột và cho trái cây vào đó. Đặt sang một bên.', NULL, '2026-05-15 14:46:54', '2026-05-15 14:46:54'),
(2533, 380, 6, 'Tạo một cái giếng ở giữa bát nguyên liệu khô rồi đổ hỗn hợp ướt vào, khuấy đều cho đến khi hòa quyện hoàn toàn. Và các loại trái cây cho vào hỗn hợp và khuấy đều cho đến khi hòa quyện.', NULL, '2026-05-15 14:46:54', '2026-05-15 14:46:54'),
(2534, 380, 7, 'Đổ hỗn hợp vào khuôn ổ bánh đã chuẩn bị sẵn và nướng trong lò đã làm nóng trước trong 50-60 phút hoặc cho đến khi tăm rút ra sạch sẽ.', NULL, '2026-05-15 14:46:54', '2026-05-15 14:46:54'),
(2535, 380, 8, 'Làm nguội trong chảo trong 5 phút rồi chuyển sang giá làm mát để làm mát xong. Ăn kèm với lát phô mai cheddar.', NULL, '2026-05-15 14:46:54', '2026-05-15 14:46:54'),
(2536, 381, 1, 'Làm nóng lò ở nhiệt độ 350°F (175°C). Bôi mỡ và lót một chiếc chảo tròn 9 inch hoặc chảo ổ bánh mì bằng giấy da.', NULL, '2026-05-15 14:46:57', '2026-05-15 14:46:57'),
(2537, 381, 2, 'Đặt khoai lang đã cắt vào tô của máy xay thực phẩm và chế biến cho đến khi nghiền mịn. Trong một bát nhỏ, trộn nho khô với 2 thìa cà phê bột mì từ ½ cốc. Đặt sang một bên.', NULL, '2026-05-15 14:46:57', '2026-05-15 14:46:57'),
(2538, 381, 3, 'Trong một tô lớn, trộn khoai lang bào, đường nâu nhạt, bột mì đa dụng, chiết xuất vani, hạt tiêu, quế, nhục đậu khấu, gừng và muối. Khuấy 1½ cốc nước cốt dừa cho đến khi tạo thành bột. Gấp nho khô đã được trộn vào bột mì.', NULL, '2026-05-15 14:46:57', '2026-05-15 14:46:57'),
(2539, 381, 4, 'Đổ bột vào chảo đã chuẩn bị sẵn và làm phẳng phần trên. Nướng không đậy nắp trong 1 giờ 30 phút, cho đến khi gần chín nhưng vẫn hơi mềm ở giữa', NULL, '2026-05-15 14:46:57', '2026-05-15 14:46:57'),
(2540, 382, 1, 'Làm nóng lò nướng ở nhiệt độ 160C/quạt 140C/gas 3. Đánh bánh quy thành vụn trong máy xay thực phẩm (hoặc cho vào túi nhựa chắc chắn và dùng chày cán bột đập vụn bánh quy). Trộn với bơ tan chảy và ấn vào đế và các cạnh của khuôn bánh tart có đế rời 22cm. Nướng trong lò trong 10 phút. Hủy bỏ và làm mát.', NULL, '2026-05-15 14:47:00', '2026-05-15 14:47:00'),
(2541, 382, 2, 'Cho lòng đỏ trứng vào tô lớn và đánh đều trong một phút bằng máy đánh trứng. Thêm sữa đặc và đánh trong 3 phút, sau đó thêm vỏ và nước trái cây vào và đánh lại trong 3 phút. Đổ nhân vào đế đã nguội rồi cho vào lò nướng trong 15 phút. Để nguội rồi để lạnh ít nhất 3 tiếng hoặc qua đêm nếu thích.', NULL, '2026-05-15 14:47:00', '2026-05-15 14:47:00'),
(2542, 382, 3, 'Khi bạn đã sẵn sàng phục vụ, hãy cẩn thận lấy bánh ra khỏi hộp thiếc và đặt lên đĩa phục vụ. Để trang trí, đánh nhẹ kem và đường bột với nhau. Đổ hoặc phết kem lên mặt bánh và phủ thêm vỏ chanh.', NULL, '2026-05-15 14:47:00', '2026-05-15 14:47:00'),
(2543, 383, 1, 'Lấy kanfhe cho vào tô và cắt thô. Đổ bơ tan chảy, màu thực phẩm màu vàng vào rồi trộn đều bằng tay.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2544, 383, 2, 'Trong một bát riêng trộn đều sữa, kem phô mai, đường, bột bắp.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2545, 383, 3, 'Bật lửa và đun sôi chất lỏng, khi nó đặc lại thì tắt lửa để nguội một chút.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2546, 383, 4, 'Thêm mozzarella vào đó và trộn đều.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2547, 383, 5, 'Bây giờ làm phần đế bằng một nửa chiếc kanfhe trong đĩa, ấn nhẹ để bột phẳng đều.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2548, 383, 6, 'Đổ hỗn hợp phô mai lên trên và san bằng bằng thìa.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2549, 383, 7, 'Che nó bằng nửa còn lại của kanfhe.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2550, 383, 8, 'Đặt món ăn vào lò nướng đã làm nóng trước ở nhiệt độ 200 độ trong khoảng 20-25 phút.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2551, 383, 9, 'Nó đã sẵn sàng khi kunafa có bề mặt vàng và giòn.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2552, 383, 10, 'Đun sôi nước trong chảo và hòa tan đường trong đó trong 4–5 phút. HOẶC nấu cho đến khi hơi đặc lại và tiếp tục khuấy. Thêm nước cốt chanh với nước hoa hồng, trộn đều.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2553, 383, 11, 'Đổ đều xi-rô lên kunafa ngay khi nó lấy ra khỏi lò.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2554, 383, 12, 'Kunafa của bạn đã sẵn sàng phục vụ.', NULL, '2026-05-15 14:47:02', '2026-05-15 14:47:02'),
(2555, 384, 1, 'Hòa tan men trong nước ấm trong bát 2 1/2 lít. Thêm sữa, đường, muối, trứng, mỡ và 2 chén bột mì. Đánh ở tốc độ thấp trong 30 giây, cạo bát liên tục. Đánh ở tốc độ trung bình trong 2 phút, thỉnh thoảng cạo bát. Khuấy bột còn lại cho đến khi mịn. Đậy nắp và để tăng gấp đôi, 50-60 phút. (Bột đã sẵn sàng khi chạm vào vẫn còn vết lõm.) Lật bột lên bề mặt đã rắc bột mì; cuộn nhẹ xung quanh để phủ bột. Nhẹ nhàng cán bột dày 1/2 inch bằng cán bột. Cắt bằng máy cắt bánh rán bột. Đậy nắp và để tăng gấp đôi, 30-40 phút.', NULL, '2026-05-15 14:47:04', '2026-05-15 14:47:04'),
(2556, 384, 2, 'Đun nóng dầu thực vật trong nồi chiên sâu đến 350°. Trượt bánh rán vào dầu nóng bằng thìa rộng. Xoay bánh rán khi chúng nổi lên trên bề mặt. Chiên cho đến khi có màu vàng nâu, khoảng 1 phút mỗi mặt. Cẩn thận loại bỏ dầu (không chích vào bề mặt); làm khô hạn. Nhúng bánh rán vào lớp men kem đặt trên giá.', NULL, '2026-05-15 14:47:04', '2026-05-15 14:47:04'),
(2557, 384, 3, 'Đun nóng bơ cho đến khi tan chảy. Loại bỏ khỏi nhiệt. Khuấy đường bột và vani cho đến khi mịn. Khuấy trong nước, mỗi lần 1 muỗng canh, cho đến khi có độ đặc mong muốn.', NULL, '2026-05-15 14:47:04', '2026-05-15 14:47:04'),
(2558, 385, 1, 'sữa trứng vani', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2559, 385, 2, 'Tách lòng đỏ trứng và để riêng lòng trắng để dùng làm bánh trứng đường.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2560, 385, 3, 'Đánh đều lòng đỏ trứng, bột ngô và đường trong tô.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2561, 385, 4, 'Đun nóng kem và sữa trong chảo. Tách vỏ vani và thêm đậu vào nồi. Khi sữa bắt đầu sủi bọt, đổ khoảng một nửa vào bát cùng với hỗn hợp trứng, đánh liên tục. Sau đó bắc chảo lên bếp rồi đổ hỗn hợp trứng vào nồi cùng với phần sữa còn lại, khuấy liên tục. Khi hỗn hợp đặc lại thì giảm nhiệt và tiếp tục đánh trong khoảng 30 giây.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2562, 385, 5, 'Đổ sữa trứng vào tô sạch và dùng màng bọc thực phẩm bọc lại, đặt màng nhựa trực tiếp lên lớp trên cùng của sữa trứng. Thư giãn trong tủ lạnh.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2563, 385, 6, 'bánh ngọt', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2564, 385, 7, 'Trộn đều bơ và đường cho đến khi mịn và nhẹ. Thêm từng lòng đỏ trứng vào, để riêng lòng trắng trứng để làm bánh trứng đường. Thêm bột mì trộn với bột nở. Khuấy sữa, đánh cho đến khi mịn (bạn có thể sử dụng máy trộn điện nếu thích).', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2565, 385, 8, 'Làm nóng lò ở nhiệt độ 320°F (160°C). Phủ giấy nướng bánh lên khay nướng và dàn bột thành hình chữ nhật lớn, đều.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2566, 385, 9, 'topping meringue', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2567, 385, 10, 'Đánh đều lòng trắng trứng và đường cho đến khi thu được chóp cứng và bóng. Bánh trứng đường phải giữ nguyên hình dạng – nếu nó vẫn tan thì tiếp tục đánh.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2568, 385, 11, 'Trải meringue lên trên mặt bột bánh. Dùng thìa tạo sóng ánh sáng với bánh trứng đường. Rắc hạnh nhân lên trên meringue. Nướng trong khoảng 30 phút, cho đến khi bánh trứng đường và hạnh nhân chuyển sang màu vàng.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2569, 385, 12, 'Nhân kem', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2570, 385, 13, 'Đánh kem thành chóp cứng. Cẩn thận gấp sữa trứng vani vào.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2571, 385, 14, 'Khi bánh đã nguội, cắt làm đôi. Bạn có thể dùng kéo hoặc dao đặt trên thớt để cắt giấy nướng bánh.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2572, 385, 15, 'Đặt một nửa chiếc bánh lên đĩa phục vụ với mặt meringue úp xuống và bóc giấy nướng.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2573, 385, 16, 'Trải phần nhân kem lên khắp mặt bánh. Sau đó cẩn thận lấy nửa còn lại của chiếc bánh ra khỏi giấy nướng và đặt nó lên trên phần nhân kem, mặt meringue hướng lên trên.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2574, 385, 17, 'Ăn kèm với quả mọng tươi.', NULL, '2026-05-15 14:47:10', '2026-05-15 14:47:10'),
(2576, 386, 1, 'Làm nóng lò nướng ở nhiệt độ 200C/180C quạt/khí 6. Bơ bơ và lót khuôn hình chữ nhật 20 x 30cm.', NULL, '2026-05-15 14:47:14', '2026-05-16 12:35:34'),
(2578, 386, 2, 'Đánh bơ và đường trong máy trộn đứng cho đến khi nhạt và mịn. Thêm từng quả trứng vào và đánh đều. Đánh đều bột mì, sữa và muối cho đến khi hòa quyện hoàn toàn rồi cho vào khuôn. Nướng trong lò trong 25 phút hoặc cho đến khi vàng và chắc khi chạm vào. Đặt sang một bên để nguội hoàn toàn.', NULL, '2026-05-15 14:47:14', '2026-05-16 12:35:34'),
(2580, 386, 3, 'Cắt miếng bọt biển theo chiều ngang để tạo thành hai nửa. Cắt các cạnh để tạo thành các góc hoàn hảo. Cắt miếng bọt biển thành 18 hình vuông. Đánh nhẹ kem với đường bột cho đến khi đạt chóp mềm. Phết một ít mứt lên một nửa miếng bọt biển hình vuông sau đó phết hoặc phết lên một ít kem. Kẹp từng miếng với một miếng bọt biển hình vuông thứ hai sau đó để vào tủ lạnh để làm lạnh.', NULL, '2026-05-15 14:47:14', '2026-05-16 12:35:34'),
(2582, 386, 4, 'Để làm kem, trộn bơ tan chảy và sữa vào tô. Rây bột cacao và đường bột vào một bát riêng. Từ từ thêm cacao và đường vào hỗn hợp bơ và sữa, đánh liên tục để đảm bảo không bị vón cục. Nếu nó bị vón cục, hãy xay bằng máy xay cầm tay cho đến khi mịn.', NULL, '2026-05-15 14:47:14', '2026-05-16 12:35:34'),
(2584, 386, 5, 'Chia dừa vào ba chiếc bát nông (điều này giúp dừa không bị phủ quá nhiều sô cô la khi bạn nhúng).', NULL, '2026-05-15 14:47:14', '2026-05-16 12:35:34'),
(2586, 386, 6, 'Nhúng từng lamington vào kem cho đến khi phủ kín hoàn toàn. Cuộn dừa và đặt trên giá lưới. Lặp lại với miếng bọt biển còn lại. Thư giãn tối thiểu 1 giờ.', NULL, '2026-05-15 14:47:14', '2026-05-16 12:35:34'),
(2587, 387, 1, 'Làm nóng lò trước ở nhiệt độ 180C/350F/Gas 4. Bôi mỡ vào khuôn bánh tròn 18cm/7in, lót giấy thấm mỡ vào đế và phết giấy.', NULL, '2026-05-15 14:47:17', '2026-05-15 14:47:17'),
(2588, 387, 2, 'Đánh bơ và đường vào tô cho đến khi mịn và nhạt màu. Đánh từng quả trứng vào, đánh đều hỗn hợp giữa từng quả và thêm một thìa bột mì với quả trứng cuối cùng để tránh hỗn hợp bị vón cục.', NULL, '2026-05-15 14:47:17', '2026-05-15 14:47:17'),
(2589, 387, 3, 'Rây bột và trộn nhẹ nhàng, cho lượng sữa vừa đủ để tạo thành hỗn hợp rơi từ từ ra khỏi thìa. Gấp vỏ chanh vào.', NULL, '2026-05-15 14:47:17', '2026-05-15 14:47:17'),
(2590, 387, 4, 'Múc hỗn hợp vào khuôn đã chuẩn bị sẵn và san nhẹ mặt trên. Nướng trên kệ giữa của lò trong 30-40 phút, hoặc cho đến khi mặt trên có màu nâu vàng và cắm xiên vào giữa thấy tăm sạch sẽ.', NULL, '2026-05-15 14:47:17', '2026-05-15 14:47:17'),
(2591, 387, 5, 'Lấy ra khỏi lò và để nguội trong hộp thiếc trong 10 phút, sau đó đặt nó lên giá lưới và để nguội hoàn toàn.', NULL, '2026-05-15 14:47:17', '2026-05-15 14:47:17'),
(2592, 387, 6, 'Để phục vụ, trang trí bánh với vỏ kẹo.', NULL, '2026-05-15 14:47:17', '2026-05-15 14:47:17'),
(2593, 388, 1, 'Cho thịt bò xay với 1/2 củ tỏi băm và 1 thìa hành tây băm nhỏ vào tô lớn. Trộn bằng tay cho đến khi hòa quyện hoàn toàn. Nặn hỗn hợp thịt thành từng miếng hình thuôn dài 1/2 inch; bạn nên có 12 đến 14 viên thịt.', NULL, '2026-05-15 14:47:50', '2026-05-15 14:47:50'),
(2594, 388, 2, 'Đun nóng chảo lớn trên lửa vừa cao. Từng miếng chả màu nâu được cho vào chảo nóng cho đến khi giòn cả hai mặt và không còn màu hồng ở giữa, khoảng 10 phút. Đặt thịt viên sang một bên trong đĩa phục vụ có viền.', NULL, '2026-05-15 14:47:50', '2026-05-15 14:47:50'),
(2595, 388, 3, 'Giảm nhiệt ở mức trung bình và khuấy hành tây xắt nhỏ còn lại vào chảo. Nêm muối và hạt tiêu. Nấu, khuấy liên tục cho đến khi hành tây mềm và chuyển sang màu trong, khoảng 5 phút. Khuấy tỏi còn lại và nấu trong 30 giây. Khuấy cà chua Roma, rau mùi tây khô và ras el hanout. Đổ nước vào. Nấu cho đến khi cà chua mềm, khoảng 5 phút.', NULL, '2026-05-15 14:47:50', '2026-05-15 14:47:50'),
(2596, 388, 4, 'Đổ nước sốt cà chua lên thịt viên để thưởng thức.', NULL, '2026-05-15 14:47:50', '2026-05-15 14:47:50'),
(2597, 389, 1, 'Nấu thịt: Cho sườn vào nồi cùng nước dùng hoặc nước và muối. Nấu trên lửa nhỏ trong khoảng 2 giờ cho đến khi mềm và dễ cắt nhỏ.', NULL, '2026-05-15 14:47:52', '2026-05-15 14:47:52'),
(2598, 389, 2, 'Xé thịt: Sau khi chín, để ráo nước và xé thịt bằng hai chiếc nĩa.', NULL, '2026-05-15 14:47:52', '2026-05-15 14:47:52'),
(2599, 389, 3, 'Sơ chế rau củ: Phi thơm hành tây, ớt chuông, tỏi băm nhỏ với một ít dầu. Thêm thì là, lá oregano, ớt bột và muối. Khuấy thịt và nấu trong vài phút cho đến khi hương vị được kết hợp tốt.', NULL, '2026-05-15 14:47:52', '2026-05-15 14:47:52'),
(2600, 389, 4, 'Làm bột: Trong một cái bát, trộn bột ngô với nước ấm và muối cho đến khi tạo thành một khối bột mềm. Hãy để nó nghỉ ngơi trong 5 phút.', NULL, '2026-05-15 14:47:52', '2026-05-15 14:47:52'),
(2601, 389, 5, 'Tạo hình bánh arepas: Chia bột thành 6 phần, vo thành những quả bóng và dẹt thành những đĩa dày.', NULL, '2026-05-15 14:47:52', '2026-05-15 14:47:52'),
(2602, 389, 6, 'Nấu: Nấu bánh arepas trên vỉ nướng hoặc chảo trên lửa vừa trong 2–3 phút mỗi mặt cho đến khi chín vàng. Sau đó, bạn có thể nướng chúng trong vài phút nếu bạn thích chúng giòn hơn.', NULL, '2026-05-15 14:47:52', '2026-05-15 14:47:52'),
(2603, 389, 7, 'Phần nhân: Cắt miếng arepas ở một bên, cho thịt bò băm nóng vào và phủ phô mai bào lên trên.', NULL, '2026-05-15 14:47:52', '2026-05-15 14:47:52'),
(2605, 390, 1, 'Làm bánh mì kẹp thịt: Cho thịt vào tô và rắc lên trên 1 thìa cà phê muối và một ít tiêu đen xay. Dùng tay ướt để trộn gia vị. Dùng tay chia làm bốn phần và tạo hình bánh mì kẹp thịt. (Nó có thể được đông lạnh ở giai đoạn này.)', NULL, '2026-05-15 14:47:54', '2026-05-16 12:35:34'),
(2607, 390, 2, 'Phân loại nguyên liệu: Cắt củ cải đường và chia bánh mì naan.', NULL, '2026-05-15 14:47:54', '2026-05-16 12:35:34'),
(2609, 390, 3, 'Nướng bánh naan: Làm nóng chảo nướng hoặc vỉ nướng. Nướng naan ở cả hai mặt cho đến khi nướng nhẹ và đặt sang một bên. Cho bánh mì kẹp thịt vào vỉ nướng hoặc thịt nướng và nướng trong 2-3 phút, sau đó lật mặt và nướng mặt còn lại thêm 2-3 phút.', NULL, '2026-05-15 14:47:54', '2026-05-16 12:35:34');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(2611, 390, 4, 'Bày biện món ăn: Đặt nửa miếng naan nướng lên mỗi đĩa phục vụ và đặt một đống tên lửa lên mỗi đĩa. Phủ lên trên một chiếc bánh mì kẹp thịt, sau đó là vài lát củ cải đường và một ít kem chua. Rắc muối và hạt tiêu đen mới xay và dùng ngay với món salad xanh lớn và khoai tây chiên. Một ly rượu vang đỏ cũng không sao cả.', NULL, '2026-05-15 14:47:54', '2026-05-16 12:35:34'),
(2612, 391, 1, 'Ướp thịt bò:', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2613, 391, 2, 'Khuấy đều các nguyên liệu ướp thịt bò (1 thìa cà phê nước tương, 1 thìa cà phê rượu gạo Trung Quốc, 1/2 thìa cà phê bột bắp, 1/8 thìa cà phê tiêu đen) trong tô vừa.', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2614, 391, 3, 'Thêm các lát thịt bò và khuấy cho đến khi phủ đều. Để yên trong 10 phút.', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2615, 391, 4, 'Chuẩn bị nước sốt:', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2616, 391, 5, 'Khuấy đều các nguyên liệu làm nước sốt (2 thìa dầu hào, 1 thìa cà phê rượu gạo Trung Quốc, 1 thìa cà phê nước tương, 1/4 chén nước luộc gà) trong một tô nhỏ. Đặt sang một bên.', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2617, 391, 6, 'Chần hoặc hấp bông cải xanh:', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2618, 391, 7, 'Đun sôi một nồi nước. Thêm bông cải xanh và nấu cho đến khi mềm giòn, khoảng 2 phút. Xả thật kỹ.', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2619, 391, 8, 'Xào thịt bò:', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2620, 391, 9, 'Đun nóng chảo rán lớn hoặc chảo trên lửa cao cho đến khi một hạt nước sủi bọt và bay hơi ngay lập tức khi tiếp xúc. Thêm dầu ăn và xoáy đều.', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2621, 391, 10, 'Thêm thịt bò vào và ngay lập tức dàn đều khắp bề mặt chảo hoặc chảo thành một lớp (tốt nhất là không chạm vào).', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2622, 391, 11, 'Để thịt bò chiên yên trong 1 phút. Lật các lát thịt bò lên, cho tỏi vào chảo rồi chiên thêm 30 giây đến 1 phút cho đến khi không còn màu hồng.', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2623, 391, 12, 'Thêm nước sốt, bột bắp và bông cải xanh:', NULL, '2026-05-15 14:47:55', '2026-05-15 14:47:55'),
(2624, 391, 13, 'Đổ nước sốt và hỗn hợp bột bắp vào (1 thìa cà phê bột bắp hòa tan trong 1 thìa nước). Khuấy cho đến khi nước sốt sôi và đặc lại, khoảng 30 giây. Khuấy bông cải xanh.', NULL, '2026-05-15 14:47:56', '2026-05-15 14:47:56'),
(2625, 391, 14, 'Ăn ngay, với cơm trắng hoặc ăn riêng.', NULL, '2026-05-15 14:47:56', '2026-05-15 14:47:56'),
(2626, 392, 1, 'Làm nóng lò ở mức 150C/300F/Gas 2.', NULL, '2026-05-15 14:47:57', '2026-05-15 14:47:57'),
(2627, 392, 2, 'Cho thịt bò và bột mì vào tô cùng với một ít muối và tiêu đen.', NULL, '2026-05-15 14:47:57', '2026-05-15 14:47:57'),
(2628, 392, 3, 'Đun một nồi lớn cho đến khi nóng, cho một nửa dầu hạt cải và lượng thịt bò vừa đủ ngập đáy nồi.', NULL, '2026-05-15 14:47:57', '2026-05-15 14:47:57'),
(2629, 392, 4, 'Chiên cho đến khi chín vàng ở mỗi mặt, sau đó lấy ra và đặt sang một bên. Lặp lại với dầu và thịt bò còn lại.', NULL, '2026-05-15 14:47:57', '2026-05-15 14:47:57'),
(2630, 392, 5, 'Cho thịt bò vào chảo, thêm rượu và nấu cho đến khi lượng chất lỏng giảm đi một nửa, sau đó thêm nước kho, hành tây, cà rốt, húng tây và mù tạt, nêm muối và hạt tiêu.', NULL, '2026-05-15 14:47:57', '2026-05-15 14:47:57'),
(2631, 392, 6, 'Đậy nắp và cho vào lò nướng trong hai giờ.', NULL, '2026-05-15 14:47:58', '2026-05-15 14:47:58'),
(2632, 392, 7, 'Lấy ra khỏi lò, kiểm tra gia vị và để nguội. Loại bỏ húng tây.', NULL, '2026-05-15 14:47:58', '2026-05-15 14:47:58'),
(2633, 392, 8, 'Khi thịt bò nguội và bạn đã sẵn sàng gói bánh, hãy làm nóng lò nướng ở nhiệt độ 200C/400F/Gas 6.', NULL, '2026-05-15 14:47:58', '2026-05-15 14:47:58'),
(2634, 392, 9, 'Chuyển thịt bò sang đĩa bánh nướng, phết lòng đỏ trứng đã đánh bông lên vành và phủ bánh ngọt lên trên. Quét thêm trứng đã đánh lên trên mặt bánh.', NULL, '2026-05-15 14:47:58', '2026-05-15 14:47:58'),
(2635, 392, 10, 'Cắt bớt phần bánh sao cho phần thừa vừa đủ để gấp mép, sau đó cho vào lò nướng và nướng trong 30 phút hoặc cho đến khi bánh có màu nâu vàng và chín đều.', NULL, '2026-05-15 14:47:58', '2026-05-15 14:47:58'),
(2636, 392, 11, 'Đối với đậu xanh, đun sôi một nồi nước muối, cho đậu vào nấu khoảng 4-5 phút hoặc cho đến khi đậu mềm.', NULL, '2026-05-15 14:47:58', '2026-05-15 14:47:58'),
(2637, 392, 12, 'Để ráo nước và trộn với bơ, sau đó nêm hạt tiêu đen.', NULL, '2026-05-15 14:47:58', '2026-05-15 14:47:58'),
(2638, 392, 13, 'Để phục vụ, đặt một thìa bánh lớn lên mỗi đĩa cùng với một ít đậu xanh bên cạnh.', NULL, '2026-05-15 14:47:58', '2026-05-15 14:47:58'),
(2639, 393, 1, 'Nêm các khối thịt bò với muối và hạt tiêu đen. Đun nóng một thìa dầu trong chảo rồi cho thịt vào chiên ở lửa lớn. Thực hiện việc này thành ba mẻ để chảo không bị quá đông, chuyển thịt sang đĩa thịt hầm lớn chống cháy sau khi thịt đã chín vàng toàn bộ. Thêm dầu nếu chảo có vẻ khô.', NULL, '2026-05-15 14:47:59', '2026-05-15 14:47:59'),
(2640, 393, 2, 'Trong cùng một chảo, thêm một thìa dầu khác và nấu hẹ trong 4-5 phút, sau đó thêm tỏi và chiên trong 30 giây. Thêm thịt xông khói và chiên cho đến khi hơi chín. Chuyển hỗn hợp hành tây và thịt xông khói vào đĩa thịt hầm và thêm các loại thảo mộc.', NULL, '2026-05-15 14:47:59', '2026-05-15 14:47:59'),
(2641, 393, 3, 'Làm nóng lò ở 180C/350F/Gas 4.', NULL, '2026-05-15 14:47:59', '2026-05-15 14:47:59'),
(2642, 393, 4, 'Đổ bia đen vào chảo rán và đun sôi, khuấy đều để nhấc những phần màu nâu còn dính ra khỏi đáy chảo. Đổ bia đen lên thịt bò trong đĩa thịt hầm và thêm nước kho. Đậy nắp nồi và cho vào lò nướng trong 1½-2 giờ hoặc cho đến khi thịt bò mềm và nước sốt giảm bớt.', NULL, '2026-05-15 14:47:59', '2026-05-15 14:47:59'),
(2643, 393, 5, 'Hớt bỏ lớp mỡ trên bề mặt, nếm thử và thêm muối, tiêu nếu cần, sau đó cho bột ngô vào khuấy đều. Đặt đĩa thịt hầm lên bếp - đừng quên đĩa còn nóng - và đun nhỏ lửa trong 1-2 phút, khuấy đều cho đến khi đặc lại. Để nguội.', NULL, '2026-05-15 14:47:59', '2026-05-15 14:47:59'),
(2644, 393, 6, 'Tăng lò nướng lên 200C/400F/Gas 6. Để làm bánh ngọt, cho bột mì và muối vào một cái tô thật lớn. Nghiền bơ và trộn vào bột thành ba mẻ. Dần dần thêm 325ml/11fl oz nước lạnh – bạn có thể không cần hết – và khuấy bằng dao có lưỡi tròn cho đến khi hỗn hợp vừa quyện lại với nhau. Nhào nhẹ bánh ngọt thành một quả bóng trên bề mặt đã phủ bột mì nhẹ và dành 250g/9oz cho nắp bánh.', NULL, '2026-05-15 14:47:59', '2026-05-15 14:47:59'),
(2645, 393, 7, 'Cán phần còn lại của chiếc bánh ngọt cho đến khi lớn hơn đĩa bạn đang dùng khoảng 2 cm/¾ inch. Xếp bánh ngọt lên đĩa rồi xếp nhân vào, nhét hàu vào. Quét mép bánh bằng trứng đã đánh bông.', NULL, '2026-05-15 14:47:59', '2026-05-15 14:47:59'),
(2646, 393, 8, 'Cuộn phần bánh ngọt còn lại cho đến khi lớn hơn đĩa của bạn một chút và nhẹ nhàng nhấc phần nhân lên, ấn chặt các mép để bịt kín, sau đó dùng dao sắc cắt bớt. Quét một lớp trứng đánh lên để tráng men. Đặt đĩa lên khay nướng và nướng trong 25-30 phút hoặc cho đến khi bánh có màu nâu vàng và phần nhân sủi bọt.', NULL, '2026-05-15 14:47:59', '2026-05-15 14:47:59'),
(2647, 394, 1, '0. Trộn thịt bò, hạt tiêu xay, nước tương, giấm, lá nguyệt quế khô, chanh và sốt cà chua. Trộn đều. Ướp thịt bò ít nhất 30 phút.', NULL, '2026-05-15 14:48:00', '2026-05-15 14:48:00'),
(2648, 394, 2, '1. Cho thịt bò đã ướp vào nồi nấu cùng với phần nước xốt còn lại. Thêm nước. Hãy đun sôi.', NULL, '2026-05-15 14:48:00', '2026-05-15 14:48:00'),
(2649, 394, 3, '2. Thêm viên bò Knorr vào. Khuấy. Đậy nắp nồi và nấu trong 40 phút ở nhiệt độ thấp.', NULL, '2026-05-15 14:48:00', '2026-05-15 14:48:00'),
(2650, 394, 4, '3. Lật thịt bò lại. Thêm bột cà chua. Tiếp tục nấu cho đến khi thịt bò mềm. Đặt sang một bên.', NULL, '2026-05-15 14:48:00', '2026-05-15 14:48:00'),
(2651, 394, 5, '4. Đun nóng dầu trong chảo. Chiên khoai tây cho đến khi có màu nâu. Lật lại và tiếp tục chiên mặt đối diện. Lấy ra khỏi chảo và đặt lên đĩa sạch. Làm tương tự với cà rốt.', NULL, '2026-05-15 14:48:00', '2026-05-15 14:48:00'),
(2652, 394, 6, '5. Tiết kiệm 3 thìa dầu ăn trong chảo chiên khoai tây. Xào hành và tỏi cho đến khi hành mềm.', NULL, '2026-05-15 14:48:00', '2026-05-15 14:48:00'),
(2653, 394, 7, '6. Đổ nước sốt từ thịt bò hầm vào. Hãy đun sôi. Thêm thịt bò. Nấu trong 2 phút.', NULL, '2026-05-15 14:48:00', '2026-05-15 14:48:00'),
(2654, 394, 8, '7. Thêm bơ vào và đun chảy. Tiếp tục nấu cho đến khi nước sốt giảm còn một nửa.', NULL, '2026-05-15 14:48:00', '2026-05-15 14:48:00'),
(2655, 395, 1, 'Thành phần bổ sung: mayonnaise, siracha', NULL, '2026-05-15 14:48:02', '2026-05-15 14:48:02'),
(2656, 395, 2, 'Đặt gạo vào một cái rây mịn và rửa sạch cho đến khi nước trong. Cho vào nồi nhỏ cùng 1 cốc nước (2 cốc cho 4 phần ăn) và một chút muối. Đun sôi, sau đó đậy nắp và giảm nhiệt xuống thấp. Nấu cho đến khi gạo mềm, 15 phút. Đậy kín lửa trong ít nhất 10 phút hoặc cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:48:02', '2026-05-15 14:48:02'),
(2657, 395, 3, 'Trong khi đó, rửa sạch và lau khô tất cả sản phẩm. Bóc vỏ và băm nhuyễn tỏi. Vỏ và quý chanh (cho 4 phần ăn, vỏ 1 quả chanh và cả hai phần tư). Cắt và cắt đôi quả dưa chuột theo chiều dọc; thái mỏng theo chiều ngang thành hình bán nguyệt. Cắt đôi, gọt vỏ và thái hạt lựu vừa. Cắt nhỏ, gọt vỏ và xay cà rốt.', NULL, '2026-05-15 14:48:02', '2026-05-15 14:48:02'),
(2658, 395, 4, 'Trong một tô vừa, trộn dưa chuột, nước ép từ nửa quả chanh, ¼ thìa cà phê đường (½ thìa cho 4 phần ăn) và một chút muối. Trong một bát nhỏ, trộn sốt mayonnaise, một nhúm tỏi, vắt nước cốt chanh và bao nhiêu sriracha tùy thích. Nêm muối và hạt tiêu.', NULL, '2026-05-15 14:48:02', '2026-05-15 14:48:02'),
(2659, 395, 5, 'Đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm hành tây và nấu, khuấy đều cho đến khi mềm trong 4-5 phút. Thêm thịt bò, tỏi còn lại và 2 muỗng cà phê đường (4 muỗng cà phê cho 4 phần ăn). Nấu, chia thịt thành từng miếng cho đến khi thịt bò chín vàng, khoảng 4-5 phút. Khuấy nước tương. Tắt nhiệt; nếm và nêm muối và hạt tiêu.', NULL, '2026-05-15 14:48:02', '2026-05-15 14:48:02'),
(2660, 395, 6, 'Xới cơm bằng nĩa; khuấy vỏ chanh và 1 muỗng canh bơ. Chia cơm vào các bát. Xếp thịt bò, cà rốt bào sợi và dưa chuột muối lên trên. Top với một vắt nước cốt chanh. Rưới thêm sriracha mayo.', NULL, '2026-05-15 14:48:02', '2026-05-15 14:48:02'),
(2661, 396, 1, 'Làm nóng chảo lớn và thêm 1 muỗng canh mỡ ngỗng. Nêm thịt bò và chiên cho đến khi vàng nâu, khoảng 3-5 phút, sau đó lật mặt lại và chiên mặt còn lại cho đến khi thịt chín vàng đều, thêm mỡ nếu cần. Làm điều này thành 2-3 mẻ, chuyển thịt vào một cái rây đặt trên bát khi đã chín vàng.', NULL, '2026-05-15 14:48:04', '2026-05-15 14:48:04'),
(2662, 396, 2, 'Trong cùng một chảo, chiên thịt xông khói, hẹ tây hoặc hành tây trân châu, nấm, tỏi và bó hoa trang trí cho đến khi có màu nâu nhạt. Cho cà chua xay nhuyễn vào và nấu trong vài phút, khuấy đều hỗn hợp. Điều này làm phong phú thêm rượu bourguignon và tạo thành nền tảng tuyệt vời cho món hầm. Sau đó cho thịt bò và phần nước đã ráo nước vào chảo và đảo đều.', NULL, '2026-05-15 14:48:04', '2026-05-15 14:48:04'),
(2663, 396, 3, 'Đổ rượu và khoảng 100ml nước vào để thịt nổi lên nhưng không bị ngập hoàn toàn. Đun sôi và dùng thìa cạo phần nước nấu caramen khỏi đáy chảo - điều này sẽ giúp món hầm có thêm hương vị.', NULL, '2026-05-15 14:48:04', '2026-05-15 14:48:04'),
(2664, 396, 4, 'Làm nóng lò nướng ở nhiệt độ 150C/quạt 130C/gas 2. Làm vỏ bánh: xé một tờ giấy bạc hình vuông lớn hơn soong một chút, xếp vào chảo sao cho phủ kín mặt trên của món hầm và cắt bỏ phần giấy bạc thừa. Sau đó nấu trong 3 giờ. Nếu nước sốt có vẻ chảy nước, hãy dùng thìa có rãnh loại bỏ thịt bò và rau rồi đặt sang một bên. Nấu nước sốt trên lửa lớn trong vài phút cho đến khi nước sốt đặc lại một chút, sau đó cho thịt bò và rau vào chảo.', NULL, '2026-05-15 14:48:04', '2026-05-15 14:48:04'),
(2665, 396, 5, 'Để làm món củ cải nghiền, hãy gọt vỏ củ cải và cắt thành khối vuông. Đun nóng dầu ô liu trong chảo rán lớn. Cho củ cải vào và chiên trong 5 phút cho đến khi chuyển sang màu vàng. Nêm kỹ với muối và hạt tiêu. Khuấy vỏ hương thảo, húng tây, nguyệt quế và bạch đậu khấu, sau đó đổ hơn 200ml nước, đủ gần ngập củ cải. Vặn lửa nhỏ, đậy nắp một phần chảo và để sôi trong 25-30 phút.', NULL, '2026-05-15 14:48:04', '2026-05-15 14:48:04'),
(2666, 396, 6, 'Sau 25-30 phút, củ cải sẽ mềm và phần lớn nước sẽ bay hơi hết. Xả hết nước còn lại, sau đó loại bỏ các nhánh thảo mộc, vỏ nguyệt quế và bạch đậu khấu. Nghiền nhẹ bằng máy nghiền khoai tây, sau đó kết thúc với một chút dầu ô liu và nêm nếm cho vừa ăn. Múc thịt bò bourguignon vào bát phục vụ và đặt một thìa lớn củ cải nghiền lên trên. Trang trí bằng một trong những chiếc lá nguyệt quế nếu bạn thích.', NULL, '2026-05-15 14:48:04', '2026-05-15 14:48:04'),
(2667, 397, 1, '1 Chuẩn bị miếng ức để nấu: Ở một bên của miếng ức phải có một lớp mỡ tùy thích. Nếu có bất kỳ khối mỡ lớn nào, hãy cắt chúng ra và loại bỏ chúng. Những miếng mỡ lớn sẽ không thể thoát ra ngoài hoàn toàn.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2668, 397, 2, 'Dùng dao sắc vạch mỡ thành các đường song song, cách nhau khoảng 3/4 inch. Cắt qua mỡ chứ không phải thịt bò. Lặp lại theo hướng ngược lại để tạo thành một đường chéo.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2669, 397, 3, 'Muối kỹ và để yên ở nhiệt độ phòng trong 30 phút.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2670, 397, 4, '2 Áp chảo thịt ức: Bạn sẽ cần một chiếc nồi có đáy dày, chịu nhiệt bằng lò nướng có nắp đậy hoặc lò nướng kiểu Hà Lan, vừa đủ rộng để nướng thịt ức với một khoảng trống nhỏ cho hành tây.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2671, 397, 5, 'Vỗ nhẹ cho ức ức khô rồi đặt mặt có mỡ xuống dưới vào nồi rồi đặt trên lửa vừa cao. Nấu trong 5-8 phút, đun nhỏ lửa cho đến khi mặt mỡ có màu nâu đẹp mắt. (Nếu món nướng có vẻ chín quá nhanh, hãy giảm nhiệt xuống mức trung bình. Bạn muốn có tiếng xèo xèo đều đặn chứ không phải tiếng cháy dữ dội.)', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2672, 397, 6, 'Lật miếng ức lại và nấu thêm vài phút nữa cho mặt còn lại chín vàng.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2673, 397, 7, '3 Xào hành và tỏi: Khi ức đã chín vàng thì vớt ra khỏi nồi và đặt sang một bên. Trong nồi nên có vài thìa mỡ, nếu không thì thêm một ít dầu ô liu.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2674, 397, 8, 'Thêm hành tây xắt nhỏ và tăng nhiệt lên cao. Rắc một ít muối lên hành tây. Xào, khuấy thường xuyên cho đến khi hành tây có màu nâu nhạt, khoảng 5-8 phút. Khuấy tỏi và nấu thêm 1-2 phút nữa.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2675, 397, 9, '4 Cho ức vào nồi, thêm rau thơm, kho, đun nhỏ lửa, đậy nắp, nấu trong lò: Làm nóng lò ở nhiệt độ 300°F. Dùng dây nhà bếp buộc lá nguyệt quế, hương thảo và húng tây lại với nhau.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2676, 397, 10, 'Chuyển hành và tỏi sang các cạnh của nồi và nhét thịt ức vào bên trong. Thêm nước luộc thịt bò và các loại rau thơm buộc lại. Đun sôi nước kho trên bếp.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2677, 397, 11, 'Đậy nắp nồi, đặt nồi vào lò nướng ở nhiệt độ 300°F và nấu trong 3 giờ. Cẩn thận lật miếng ức mỗi giờ để nó chín đều.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2678, 397, 12, '5 Thêm cà rốt, tiếp tục nấu: Sau 3 giờ, thêm cà rốt. Đậy nắp nồi và nấu thêm 1 giờ nữa hoặc cho đến khi cà rốt chín và thịt ức mềm ra.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2679, 397, 13, '6 Lấy ức ra thớt, lều có lót giấy bạc: Khi ức đã mềm, lấy nồi ra khỏi lò và lấy ức lên thớt. Che nó bằng giấy bạc. Kéo ra và loại bỏ các loại thảo mộc.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2680, 397, 14, '7 Làm nước sốt (tùy chọn): Lúc này bạn có hai lựa chọn. Bạn có thể dùng nguyên hoặc có thể làm nước sốt với nước xốt và một ít hành tây. Nếu bạn phục vụ như cũ, hãy bỏ qua bước này.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2681, 397, 15, 'Để làm nước sốt, loại bỏ cà rốt và một nửa số hành tây, đặt sang một bên và bọc chúng bằng giấy bạc. Đổ các nguyên liệu còn lại vào nồi vào máy xay sinh tố, xay nhuyễn cho đến khi mịn. Nếu muốn, hãy thêm 1 thìa mù tạt vào hỗn hợp. Cho vào nồi nhỏ và giữ ấm.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2682, 397, 16, '8 Cắt thịt theo thớ: Chú ý các đường thớ thịt của miếng thịt quay. Đây là \"hạt\" của thịt. Cắt thịt vuông góc với những đường này hoặc ngang thớ (cắt theo cách này giúp thịt mềm hơn), thành các lát từ 1/4 inch đến 1/2 inch.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2683, 397, 17, 'Ăn kèm hành tây, cà rốt và nước sốt. Ăn kèm với khoai tây nghiền, nướng hoặc luộc, mì trứng hoặc polenta.', NULL, '2026-05-15 14:48:05', '2026-05-15 14:48:05'),
(2684, 398, 1, '0. Đun nóng dầu trong nồi nấu. Xào hành và tỏi cho đến khi hành mềm', NULL, '2026-05-15 14:48:06', '2026-05-15 14:48:06'),
(2685, 398, 2, '1. Thêm thịt bò. Xào cho đến khi phần bên ngoài chuyển sang màu nâu nhạt.', NULL, '2026-05-15 14:48:06', '2026-05-15 14:48:06'),
(2686, 398, 3, '2. Thêm nước tương. Đổ nước sốt cà chua và nước. Hãy đun sôi.', NULL, '2026-05-15 14:48:06', '2026-05-15 14:48:06'),
(2687, 398, 4, '3. Thêm viên bò Knorr vào. Đậy nắp nồi áp suất. Nấu trong 30 phút.', NULL, '2026-05-15 14:48:06', '2026-05-15 14:48:06'),
(2688, 398, 5, '4. Chiên cà rốt và khoai tây cho đến khi chín vàng. Đặt sang một bên.', NULL, '2026-05-15 14:48:06', '2026-05-15 14:48:06'),
(2689, 398, 6, '5. Thêm ớt, phết gan và bơ đậu phộng. Khuấy.', NULL, '2026-05-15 14:48:06', '2026-05-15 14:48:06'),
(2690, 398, 7, '6. Thêm ớt chuông, khoai tây chiên và cà rốt. Đậy nắp nồi. Tiếp tục nấu trong 5 đến 7 phút.', NULL, '2026-05-15 14:48:06', '2026-05-15 14:48:06'),
(2691, 398, 8, '7. Nêm muối và tiêu đen xay. Phục vụ.', NULL, '2026-05-15 14:48:06', '2026-05-15 14:48:06'),
(2692, 399, 1, 'Làm nóng lò ở 180C/350F/Gas 4.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2693, 399, 2, 'Đối với món thịt bò hầm, đun nóng dầu và bơ trong nồi chịu nhiệt rồi chiên thịt bò cho đến khi chín vàng đều các mặt.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2694, 399, 3, 'Rắc bột lên và nấu thêm 2-3 phút nữa.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2695, 399, 4, 'Thêm tỏi và tất cả các loại rau vào xào trong 1-2 phút.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2696, 399, 5, 'Khuấy rượu, nước kho và các loại thảo mộc, sau đó thêm sốt Worcestershire và giấm balsamic để nếm thử. Nêm muối và hạt tiêu đen mới xay.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2697, 399, 6, 'Đậy nắp, chuyển vào lò nướng và nấu trong khoảng hai giờ hoặc cho đến khi thịt mềm.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2698, 399, 7, 'Đối với phần bánh bao, rây bột mì, bột nở và muối vào tô.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2699, 399, 8, 'Thêm mỡ và đủ nước để tạo thành một khối bột dày.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2700, 399, 9, 'Dùng bàn tay tẩm bột mì vo từng thìa bột thành những viên tròn nhỏ.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2701, 399, 10, 'Sau hai giờ, mở nắp ra khỏi món hầm và đặt các viên bi lên trên món hầm. Đậy nắp lại, cho vào lò nướng thêm 20 phút nữa hoặc cho đến khi bánh bao phồng lên và mềm. (Nếu bạn thích bánh bao có mặt vàng ở trên, hãy mở nắp khi cho vào lò nướng.)', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2702, 399, 11, 'Để phục vụ, đặt một thìa khoai tây nghiền lên mỗi đĩa trong số bốn đĩa phục vụ và đặt món hầm và bánh bao lên trên. Rắc rau mùi tây cắt nhỏ.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2703, 400, 1, 'Đối với bột, đặt mỡ lợn, nước ấm và muối vào tô nhào lớn và khuấy đều. Thêm bột mì và lá oregano rồi nhào trong 5 phút bằng tay hoặc bằng chức năng nhào của máy. Để yên trong ít nhất nửa giờ hoặc qua đêm trong tủ lạnh.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2704, 400, 2, 'Để làm nhân, cho cà chua vào nước sôi khoảng 30 giây, sau đó làm nguội bằng nước lạnh, gọt vỏ rồi cắt thành khối vuông. Nhấn tỏi qua máy ép tỏi, cắt hành tây thành khối. Đun nhỏ tỏi và hành tây trong một ít dầu ô liu cho đến khi trong suốt. Vớt hành, tỏi ra rồi đun chín thịt ở nhiệt độ cao từ mọi phía. Nêm tất cả các loại thảo mộc và thêm hành, tỏi và cà chua. Để sôi trong vài phút, thêm muối, hạt tiêu và gia vị bổ sung cho vừa ăn. Bạn có thể chuẩn bị thịt từ tối hôm trước, bảo quản trong tủ lạnh nếu làm như vậy. Luộc trứng rồi cắt thành khối vuông rồi trộn với thịt đã chuẩn bị.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2705, 400, 3, 'Cắt bột làm đôi và cán mỏng một nửa trên bề mặt đã rắc bột mì. Cắt các hình tròn có đường kính khoảng 12-15 cm. Của tôi có đường kính 12,5 cm. Đặt khoảng 2-4 muỗng cà phê nhân vào một hình tròn, cho một chút nước xung quanh các cạnh và gấp nửa còn lại lại để bạn có được một nửa mặt trăng. Hãy chắc chắn để bịt kín các cạnh bằng một cái nĩa. Lặp lại cho đến khi không còn bột và nhân.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2706, 400, 4, 'Trong khi đó làm nóng lò trước ở nhiệt độ 200 độ C. Quét nước rửa trứng lên bánh empanadas và nướng khoảng 8 chiếc bánh empanadas trên khay nướng có lót giấy da trong khoảng 25 phút hoặc cho đến khi vàng. Ăn ấm với sốt chimichurri.', NULL, '2026-05-15 14:48:08', '2026-05-15 14:48:08'),
(2718, 402, 1, '1. Thịt bò rửa sạch và cắt thành từng miếng lớn. Nêm nhẹ với muối và bột nghệ.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2719, 402, 2, '2. Đun nóng ghee/dầu trong nồi lớn. Thêm hành tây thái lát và xào cho đến khi vàng nhạt.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2720, 402, 3, '3. Thêm tỏi, ớt xanh và cà chua; nấu cho đến khi mềm.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2721, 402, 4, '4. Thêm hỗn hợp gia vị mandi: rau mùi, thì là, tiêu đen, quế, bạch đậu khấu, đinh hương và lá nguyệt quế.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2722, 402, 5, '5. Thêm miếng thịt bò vào và đảo đều trên lửa vừa cho đến khi thịt thấm đều gia vị.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2723, 402, 6, '6. Đổ nước hoặc nước luộc thịt bò vào. Đậy nắp và đun nhỏ lửa cho đến khi thịt bò mềm (khoảng 1,5–2 giờ tùy theo vết cắt).', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2724, 402, 7, '7. Cẩn thận lấy thịt bò ra và đặt sang một bên. Lọc và đo nước dùng.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2725, 402, 8, '8. Thêm gạo basmati đã vo sạch, ngâm vào nước dùng (thường 1 chén gạo = 1,5–2 chén chất lỏng). Điều chỉnh gia vị và đun sôi.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2726, 402, 9, '9. Giảm nhiệt, đậy nắp và nấu cơm cho đến khi mềm.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2727, 402, 10, '10. Đặt các miếng thịt bò lên cơm và hấp ở lửa nhỏ trong 10 phút để hương vị hòa quyện.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2728, 402, 11, '11. Tùy chọn: Để có vị khói, đặt một cục than nóng nhỏ lên giấy bạc trong nồi, thêm 1 thìa cà phê bơ/dầu, đậy nắp ngay trong 5 phút. Loại bỏ than trước khi phục vụ.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2729, 402, 12, '12. Xới cơm và dùng mandi thịt bò với salad hoặc tương ớt.', NULL, '2026-05-15 14:48:11', '2026-05-15 14:48:11'),
(2730, 403, 1, '0. Làm nước sốt thăn bò bằng cách trộn nước tương, giấm, gừng, tỏi, dầu mè, dầu ô liu, đường, muối và tiêu đen xay trong một tô lớn. Trộn đều.', NULL, '2026-05-15 14:48:13', '2026-05-15 14:48:13'),
(2731, 403, 2, '1. Cho thăn bò thái miếng vào tô cùng với nước xốt thăn bò. Đảo nhẹ để thịt bò ngấm đều. Hãy để nó ở lại trong 1 giờ.', NULL, '2026-05-15 14:48:13', '2026-05-15 14:48:13'),
(2732, 403, 3, '2. Dùng xiên tre hoặc kim loại để xiên thịt bò kebob bằng cách xiên rau và thăn bò đã ướp.', NULL, '2026-05-15 14:48:13', '2026-05-15 14:48:13'),
(2733, 403, 4, '3. Làm nóng lò nướng và bắt đầu nướng thịt bò kebob trong 3 phút mỗi mặt. Điều này sẽ mang lại cho bạn một miếng thịt bò vừa, ngon ngọt và mềm ở bên trong. Hãy thêm thời gian nếu bạn muốn thịt bò chín kỹ nhưng sẽ kém mềm hơn.', NULL, '2026-05-15 14:48:13', '2026-05-15 14:48:13'),
(2734, 403, 5, '4. Chuyển sang đĩa phục vụ. Ăn kèm cơm Saffron.', NULL, '2026-05-15 14:48:13', '2026-05-15 14:48:13'),
(2735, 403, 6, '5. Chia sẻ và tận hưởng!', NULL, '2026-05-15 14:48:13', '2026-05-15 14:48:13'),
(2737, 404, 1, 'Đổ nước luộc thịt bò cùng 500ml nước vào nồi lớn. Cho hành tây và gừng vào chảo rán ở nhiệt độ cao và nướng chín đều các mặt trong khoảng 3-5 phút (bạn cũng có thể làm điều này dưới vỉ nướng). Sau khi cháy, thêm vào thịt bò. Trong cùng một chảo, nướng các loại gia vị trong 2-3 phút và khi chúng bắt đầu có mùi thơm, hãy thêm chúng vào nước luộc thịt bò. Đun sôi nước kho, sau đó vặn nhỏ lửa và nấu trong 30 phút trước khi lọc.', NULL, '2026-05-15 14:48:14', '2026-05-16 12:35:34'),
(2739, 404, 2, 'Trong khi đó, cắt mỡ từ miếng bít tết và bọc trong màng dính, sau đó cho vào tủ đá trong 15 phút - điều này sẽ giúp miếng bít tết của bạn thực sự dễ cắt! Cắt mỏng rồi dùng màng bọc thực phẩm bọc lại và cho vào tủ lạnh.', NULL, '2026-05-15 14:48:14', '2026-05-16 12:35:34'),
(2741, 404, 3, 'Nếm thử nước luộc bò rồi dùng đường thốt nốt, nước mắm và đậu nành để nêm nếm. Nấu mì theo hướng dẫn trên bao bì và chia thành hai bát, đặt thịt bò thái lát lên trên mỗi bát. Đun sôi nước kho rồi đổ vào bát (nhiệt sẽ làm chín thịt bò). Xếp hành lá, lát ớt và rau thơm lên trên. Ăn kèm với chanh để vắt.', NULL, '2026-05-15 14:48:14', '2026-05-16 12:35:34'),
(2742, 405, 1, 'Cắt nhỏ các thành phần gia vị rồi cho vào máy xay thực phẩm xay cho đến khi mịn.', NULL, '2026-05-15 14:48:15', '2026-05-15 14:48:15'),
(2743, 405, 2, 'Đun nóng dầu trong nồi hầm, thêm bột gia vị, quế, đinh hương, hoa hồi, bạch đậu khấu vào xào cho đến khi có mùi thơm. Thêm thịt bò và sả giã nhuyễn vào đảo đều trong 1 phút. Thêm nước cốt dừa, nước me, nước vào đun trên lửa vừa, khuấy thường xuyên cho đến khi thịt gần chín. Thêm lá chanh kaffir, kerisik (dừa nướng), đường hoặc đường cọ vào, khuấy đều để hòa quyện với thịt.', NULL, '2026-05-15 14:48:15', '2026-05-15 14:48:15'),
(2744, 405, 3, 'Hạ nhiệt xuống thấp, đậy nắp và đun nhỏ lửa trong 1 đến 1 tiếng rưỡi hoặc cho đến khi thịt thực sự mềm và nước sốt đã khô. Thêm nhiều muối và đường cho vừa ăn. Ăn ngay với cơm trắng và để dành một ít để qua đêm.', NULL, '2026-05-15 14:48:15', '2026-05-15 14:48:15'),
(2745, 406, 1, 'Đun nóng dầu ô liu trong chảo chống dính, sau đó cho hành tây thái lát vào nấu trên lửa vừa cho đến khi mềm hoàn toàn, khoảng 15 phút, thêm một ít nước nếu chúng bắt đầu dính. Nghiền tỏi và nấu thêm 2-3 phút nữa, sau đó thêm bơ. Khi bơ nổi bọt một chút, thêm nấm vào và nấu khoảng 5 phút cho đến khi mềm hoàn toàn. Nêm kỹ mọi thứ rồi bày ra đĩa.', NULL, '2026-05-15 14:48:16', '2026-05-15 14:48:16'),
(2746, 406, 2, 'Đổ bột mì vào tô với một chút muối và hạt tiêu, sau đó lăn miếng bít tết vào bột mì đã nêm. Cho các miếng bít tết vào chảo, rưới một ít dầu nếu chảo trông đặc biệt khô và chiên trong 3-4 phút cho đến khi có màu vàng đẹp. Cho hành và nấm trở lại chảo. Đánh đều kem tươi, mù tạt và nước kho thịt bò với nhau rồi đổ vào chảo. Nấu trên lửa vừa trong khoảng 5 phút. Rắc thêm rau mùi tây, sau đó dùng kèm với pappardelle hoặc cơm.', NULL, '2026-05-15 14:48:16', '2026-05-15 14:48:16'),
(2747, 407, 1, 'Nấu bông cải xanh và cà rốt trong chảo nước sôi cho đến khi mềm.', NULL, '2026-05-15 14:48:19', '2026-05-15 14:48:19'),
(2748, 407, 2, 'Nướng Thịt bò và Khoai tây trong lò trong 45 phút, khoai tây có thể cần được kiểm tra thường xuyên để không bị chín quá.', NULL, '2026-05-15 14:48:19', '2026-05-15 14:48:19'),
(2749, 407, 3, 'Cách làm bánh pudding Yorkshire:', NULL, '2026-05-15 14:48:19', '2026-05-15 14:48:19'),
(2750, 407, 4, 'Làm nóng lò ở 230C/quạt 210C/gas 8. Rưới đều một ít dầu hướng dương vào 2 hộp thiếc làm bánh pudding Yorkshire 4 lỗ hoặc khuôn làm bánh nướng xốp chống dính 12 lỗ rồi cho vào lò nướng để hâm nóng.', NULL, '2026-05-15 14:48:19', '2026-05-15 14:48:19'),
(2751, 407, 5, 'Để làm bột, cho 140g bột mì vào tô và đánh 4 quả trứng cho đến khi mịn. Thêm từ từ 200ml sữa vào và tiếp tục đánh cho đến khi hỗn hợp không bị vón cục. Nêm muối và hạt tiêu. Đổ bột vào bình, sau đó lấy khuôn nóng ra khỏi lò. Đổ bột vào các lỗ một cách cẩn thận và đều. Đặt các hộp thiếc trở lại lò và để yên trong 20-25 phút cho đến khi bánh pudding phồng lên và chuyển sang màu nâu. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:48:19', '2026-05-15 14:48:19'),
(2752, 407, 6, 'Bày ra đĩa và thêm nước sốt theo ý muốn.', NULL, '2026-05-15 14:48:19', '2026-05-15 14:48:19'),
(2753, 408, 1, 'Cho nấm vào máy xay thực phẩm với một ít gia vị rồi xay thành hỗn hợp sệt. Cạo hỗn hợp này vào chảo và nấu trên lửa cao trong khoảng 10 phút, đảo thường xuyên để loại bỏ hơi ẩm trong nấm. Bày ra đĩa cho nguội.', NULL, '2026-05-15 14:48:20', '2026-05-15 14:48:20'),
(2754, 408, 2, 'Đun nóng chảo và thêm một ít dầu ô liu. Nêm thịt bò và nướng trên chảo nóng chỉ trong 30 giây mỗi mặt. (Bạn không muốn nấu nó ở giai đoạn này, chỉ cần tô màu thôi). Lấy thịt bò ra khỏi chảo và để nguội rồi phết mù tạt lên khắp mặt.', NULL, '2026-05-15 14:48:20', '2026-05-15 14:48:20'),
(2755, 408, 3, 'Đặt một tấm màng bám lên bề mặt làm việc và sắp xếp các lát giăm bông Parma trên đó thành các hàng hơi chồng lên nhau. Dùng dao trộn phết hỗn hợp nấm lên giăm bông, sau đó đặt phi lê thịt bò xào vào giữa. Giữ chặt màng bám ở mép, cuộn gọn giăm bông Parma và nấm xung quanh miếng thịt bò để tạo thành hình thùng chặt. Vặn các đầu của màng bám để cố định. Làm lạnh trong 15-20 phút để thịt bò đông lại và giữ được hình dạng.', NULL, '2026-05-15 14:48:20', '2026-05-15 14:48:20'),
(2756, 408, 4, 'Cán miếng bánh phồng trên bề mặt đã phủ bột mì thành một hình chữ nhật lớn, có độ dày bằng đồng xu 1 bảng Anh. Loại bỏ lớp màng bám trên thịt bò rồi đặt vào giữa. Quét lòng đỏ trứng xung quanh bánh ngọt. Gấp các đầu lại, bọc bánh ngọt quanh thịt bò, cắt bỏ phần thừa. Lật lại sao cho đường may nằm bên dưới và đặt lên khay nướng. Quét trứng lên toàn bộ bánh và để lạnh trong khoảng 15 phút để bánh nghỉ.', NULL, '2026-05-15 14:48:20', '2026-05-15 14:48:20'),
(2757, 408, 5, 'Làm nóng lò ở nhiệt độ 200C, 400F, gas 6.', NULL, '2026-05-15 14:48:20', '2026-05-15 14:48:20'),
(2758, 408, 6, 'Chấm nhẹ lên bánh cách nhau 1cm và tráng lại bằng lòng đỏ trứng đã đánh bông. Nướng trong 20 phút, sau đó hạ nhiệt độ lò xuống 180C, 350F, gas 4 và nấu thêm 15 phút nữa. Để yên khoảng 10-15 phút trước khi cắt lát và dùng với các món ăn phụ mà bạn chọn. Thịt bò vẫn còn màu hồng ở giữa khi bạn phục vụ.', NULL, '2026-05-15 14:48:20', '2026-05-15 14:48:20'),
(2760, 409, 1, 'Cho bắp cải vào đĩa hầm dày, thêm nước luộc và nấu trên lửa nhỏ trong khoảng 50 phút cho đến khi bắp cải mềm.', NULL, '2026-05-15 14:48:21', '2026-05-16 12:35:34'),
(2762, 409, 2, 'Cắt nấm ngâm thành dải và tiết kiệm nước ngâm. Đun nóng mỡ rồi cho xúc xích và thịt xông khói vào xào chín rồi múc ra, để lại mỡ trong chảo. Chiên hành tây trong cùng một chảo trong 5-8 phút cho đến khi có màu nâu nhạt.', NULL, '2026-05-15 14:48:21', '2026-05-16 12:35:34'),
(2764, 409, 3, 'Thêm nấm và chất lỏng của chúng cùng với tất cả thịt, hành tây và mận đã nấu chín, sau đó đậy nắp và nấu trong 20 phút. Thêm gia vị, rượu vang đỏ và cà chua xay nhuyễn rồi đun nhỏ lửa, sau đó đậy nắp và nấu trong 1 giờ. Nêm kỹ và để nguội. Sẽ được đậy kín và ướp lạnh trong tối đa hai ngày. Bigos cải thiện hương vị trong vài ngày. Để nguội trước. Đun nóng lại cho đến khi nóng trước khi dùng.', NULL, '2026-05-15 14:48:21', '2026-05-16 12:35:34'),
(2765, 410, 1, 'Đun chảy bơ trong chảo hoặc chảo. Khi tan chảy, thêm từng chút bột vào và khuấy thành hỗn hợp sệt. Từ từ khuấy nước kho để đảm bảo roux hấp thụ chất lỏng. Đun nhỏ lửa trong vài phút ở lửa nhỏ trong khi cho hành tây, rau mùi tây và thịt xé nhỏ vào xào. Hỗn hợp sẽ đặc lại và chuyển thành nước sốt đặc, đặc.', NULL, '2026-05-15 14:48:23', '2026-05-15 14:48:23'),
(2766, 410, 2, 'Đổ hỗn hợp vào hộp nông, đậy nắp và để lạnh trong vài giờ hoặc cho đến khi nước sốt đông lại.', NULL, '2026-05-15 14:48:23', '2026-05-15 14:48:23'),
(2767, 410, 3, 'Lấy một thìa đầy nước sốt đặc, lạnh và nhanh chóng vo tròn thành một quả bóng nhỏ. Lăn nhẹ qua bột mì, trứng và cuối cùng là vụn bánh mì. Hãy chắc chắn rằng trứng bao phủ toàn bộ bề mặt của quả đắng. Khi hoàn tất, hãy để đồ ăn nhẹ vào tủ lạnh trong khi dầu trong nồi chiên của bạn nóng lên tới 190C (375F). Chiên bốn quả đắng cùng một lúc cho đến khi vàng.', NULL, '2026-05-15 14:48:23', '2026-05-15 14:48:23'),
(2768, 410, 4, 'Bày ra đĩa với mù tạt dạng hạt hoặc cay.', NULL, '2026-05-15 14:48:23', '2026-05-15 14:48:23'),
(2774, 412, 1, 'Đun nóng dầu ô liu trong nồi lớn. Cắt thịt bò thành khối vuông 1 inch (2,5 cm) và chiên vàng trong dầu.', NULL, '2026-05-15 14:48:26', '2026-05-15 14:48:26'),
(2775, 412, 2, 'Cắt nhỏ hành tây và thêm vào thịt bò đang xào. Thêm nước kho vào và đun sôi, sau đó giảm nhiệt, đậy nắp và đun nhỏ lửa trong khoảng 30 phút.', NULL, '2026-05-15 14:48:26', '2026-05-15 14:48:26'),
(2776, 412, 3, 'Gọt vỏ và cắt củ rutabaga và rễ cần tây thành khối 1 inch (2,5 cm). Cho vào nồi, đậy nắp và tiếp tục đun nhỏ lửa thêm 30 phút nữa.', NULL, '2026-05-15 14:48:26', '2026-05-15 14:48:26'),
(2777, 412, 4, 'Gọt vỏ và cắt phần rau còn lại thành khối 1 inch (2,5 cm) rồi cho vào nồi. Cắt tỏi tây thành từng khoanh. Đậy nắp và tiếp tục đun nhỏ lửa trong khoảng 20 phút. Khuấy càng ít càng tốt.', NULL, '2026-05-15 14:48:26', '2026-05-15 14:48:26'),
(2778, 412, 5, 'Rắc mùi tây tươi lên trên.', NULL, '2026-05-15 14:48:26', '2026-05-15 14:48:26'),
(2779, 413, 1, 'Nâu thịt bò: Trong một cái nồi lớn, nâu các khối thịt bò. Loại bỏ và đặt sang một bên.', NULL, '2026-05-15 14:48:27', '2026-05-15 14:48:27'),
(2780, 413, 2, 'Xào rau: Trong cùng một nồi, nấu hành tây cho đến khi chín trong. Thêm cà rốt, khoai tây và bí ngô vào nấu trong vài phút.', NULL, '2026-05-15 14:48:27', '2026-05-15 14:48:27'),
(2781, 413, 3, 'Đun nhỏ lửa: Cho thịt bò vào nồi. Thêm nước dùng và mơ khô. Nêm muối và hạt tiêu. Đun nhỏ lửa trong 1-2 giờ cho đến khi thịt bò mềm.', NULL, '2026-05-15 14:48:27', '2026-05-15 14:48:27'),
(2782, 413, 4, 'Cách dùng: Thưởng thức nóng với một miếng bánh mì giòn.', NULL, '2026-05-15 14:48:27', '2026-05-15 14:48:27'),
(2783, 413, 5, 'Lời khuyên chuyên nghiệp:', NULL, '2026-05-15 14:48:27', '2026-05-15 14:48:27'),
(2784, 413, 6, 'Nướng thịt bò theo từng mẻ để đảm bảo thịt có độ chín vừa phải, giúp tăng thêm hương vị cho món hầm.', NULL, '2026-05-15 14:48:27', '2026-05-15 14:48:27'),
(2785, 413, 7, 'Thêm trái cây vào cuối quá trình nấu sẽ giữ nguyên kết cấu của chúng và tăng thêm vị ngọt tinh tế cho món ăn.', NULL, '2026-05-15 14:48:27', '2026-05-15 14:48:27'),
(2786, 414, 1, 'Đặt thịt xay vào tô. Băm hành thật nhuyễn và băm nhuyễn tép tỏi. Thêm vào bát. Thêm rau mùi tây cắt nhỏ, các loại ớt bột, baking soda, vụn bánh mì khô, nước, rau củ, muối và hạt tiêu.', NULL, '2026-05-15 14:48:29', '2026-05-15 14:48:29'),
(2787, 414, 2, 'Trộn đều bằng máy trộn cầm tay có gắn móc bột. Đậy bát bằng màng dính/giấy nhựa và để yên trong tủ lạnh trong 1 hoặc 2 giờ.', NULL, '2026-05-15 14:48:29', '2026-05-15 14:48:29'),
(2788, 414, 3, 'Lấy các phần hỗn hợp thịt, khoảng 50-55 g/ 1,7-1,9 oz/ ¼ cốc và tạo thành cevapi. Các cuộn bánh phải dày bằng ngón tay cái của bạn và dài khoảng 7-10 cm/ 3-4 inch. Tôi có 18 cái xúc xích. Công thức có thể dễ dàng tăng gấp đôi.', NULL, '2026-05-15 14:48:29', '2026-05-15 14:48:29'),
(2789, 414, 4, 'Nướng cevapcici trên chảo nướng nóng hoặc trên vỉ nướng trong khoảng 12-14 phút, lật chúng vài lần giữa các lần hoặc cho đến khi có màu nâu và chín đều. Tôi kiểm tra bằng cách cắt một cái ở giữa rồi nướng các mẻ sau trong cùng một khoảng thời gian.', NULL, '2026-05-15 14:48:29', '2026-05-15 14:48:29'),
(2790, 414, 5, 'Dùng nóng như gợi ý ở trên. Cevapcici có thể được hâm nóng trong lò ở nhiệt độ 180 độ C/350 độ F trong khoảng 10 phút hoặc cho đến khi nóng hoàn toàn. Kiểm tra một cái, nếu chưa đủ nóng thì cho xúc xích thêm vài phút nữa.', NULL, '2026-05-15 14:48:29', '2026-05-15 14:48:29'),
(2796, 416, 1, 'Đun nóng dầu trên lửa vừa cao trong chảo hoặc chảo xào lớn, sau đó xào hành và tỏi cho đến khi mềm, khoảng 5 phút. Thêm thịt bò xay, thịt lợn và gia vị vào nấu cho đến khi thịt chín vàng.', NULL, '2026-05-15 14:48:33', '2026-05-15 14:48:33'),
(2797, 416, 2, 'Thêm nước dùng thịt bò và đun sôi rồi giảm nhiệt xuống mức trung bình thấp. Thêm khoai tây bào vào và khuấy đều. Nấu cho đến khi chất lỏng gần như hấp thụ, khoảng 15 phút. Loại bỏ lá nguyệt quế và thêm muối cho vừa ăn. Lấy chảo ra khỏi bếp và để hỗn hợp nguội hoàn toàn - bánh sẽ ngon nhất nếu nhân được làm lạnh.', NULL, '2026-05-15 14:48:33', '2026-05-15 14:48:33'),
(2798, 416, 3, 'Làm nóng lò ở nhiệt độ 375°F (190°C). Trên một bề mặt đã phủ bột nhẹ, cán mỏng một đĩa bột bánh có độ dày nhỏ hơn 1/4 inch và lót vào đĩa bánh 9 inch. Đổ đầy hỗn hợp tourtière đã nguội vào đây và trải đều. Cán khối bột còn lại có độ dày như nhau, khoét một lỗ ở giữa (để hơi thoát ra) và đặt lên trên phần nhân. Cắt bột còn 1/2 inch ngoài mép của đĩa bánh và kẹp các mép của vỏ bánh lại với nhau. Quét lớp vỏ bằng nước rửa trứng.', NULL, '2026-05-15 14:48:33', '2026-05-15 14:48:33'),
(2799, 416, 4, 'Nướng tourtière trong khoảng 45 phút hoặc cho đến khi bánh có màu nâu vàng đậm. Để nguội trong 15 phút trước khi cắt lát để phục vụ.', NULL, '2026-05-15 14:48:33', '2026-05-15 14:48:33'),
(2800, 416, 5, 'Phục vụ: 8-10 (làm 2 chiếc bánh 9 inch)', NULL, '2026-05-15 14:48:33', '2026-05-15 14:48:33'),
(2801, 417, 1, 'Đặt thịt bò bắp vào nồi lớn hoặc lò nướng kiểu Hà Lan và đậy nắp bằng nước. Thêm gói gia vị đi kèm với thịt bò bắp. Đậy nắp nồi và đun sôi, sau đó giảm nhỏ lửa. Đun nhỏ lửa khoảng 50 phút mỗi pound hoặc cho đến khi mềm.', NULL, '2026-05-15 14:48:34', '2026-05-15 14:48:34'),
(2802, 417, 2, 'Thêm toàn bộ khoai tây và cà rốt gọt vỏ và cắt nhỏ vào nấu cho đến khi rau gần như mềm. Thêm bắp cải và nấu thêm 15 phút nữa. Lấy thịt ra và để yên 15 phút.', NULL, '2026-05-15 14:48:34', '2026-05-15 14:48:34'),
(2803, 417, 3, 'Đặt rau vào tô và đậy nắp. Thêm bao nhiêu nước dùng (nước nấu dành riêng cho nồi Hà Lan hoặc nồi lớn) tùy thích. Cắt thịt theo thớ.', NULL, '2026-05-15 14:48:34', '2026-05-15 14:48:34'),
(2804, 418, 1, 'Đun nóng dầu ô liu trong chảo hoặc nồi Hà Lan trên lửa vừa cao. Thêm hành tây và ớt xanh vào xào khoảng 3-5 phút.', NULL, '2026-05-15 14:48:35', '2026-05-15 14:48:35'),
(2805, 418, 2, 'Thêm tỏi và khuấy trong khoảng 1 phút.', NULL, '2026-05-15 14:48:35', '2026-05-15 14:48:35'),
(2806, 418, 3, 'Thêm bắp cải cắt nhỏ vào và khuấy đều. Nấu khoảng 3-5 phút, khuấy thường xuyên cho đến khi mềm.', NULL, '2026-05-15 14:48:35', '2026-05-15 14:48:35'),
(2807, 418, 4, 'Thêm thịt bò bắp, cà chua Roma, húng tây và khuấy đều. Thêm sốt cà chua và sốt tiêu scotch nắp ca-pô vào rồi khuấy đều. Giảm nhiệt và nấu ở mức trung bình trong khoảng 3-5 phút, cho đến khi thịt bò bắp chín đều. Loại bỏ khỏi nhiệt.', NULL, '2026-05-15 14:48:35', '2026-05-15 14:48:35'),
(2808, 418, 5, 'Ăn kèm cơm trắng, bánh mì hoặc ăn riêng.', NULL, '2026-05-15 14:48:35', '2026-05-15 14:48:35'),
(2809, 419, 1, 'Xào hành tây:', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2810, 419, 2, 'Đun nóng bơ trong chảo lớn (tốt nhất là chảo gang) trên lửa vừa. Thêm hành tây và nấu vài phút cho đến khi trong suốt.', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2811, 419, 3, 'Thêm khoai tây và thịt bò bắp:', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2812, 419, 4, 'Trộn thịt bò và khoai tây cắt nhỏ vào. Trải đều trên chảo. Tăng nhiệt lên cao hoặc trung bình cao và ấn hỗn hợp xuống bằng thìa kim loại.', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2813, 419, 5, 'Nấu cho đến khi chín vàng rồi lật:', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2814, 419, 6, 'Đừng khuấy khoai tây và thịt bò bắp mà hãy để chúng có màu nâu. Nếu bạn nghe thấy chúng kêu xèo xèo thì điều này là tốt.', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2815, 419, 7, 'Dùng thìa kim loại để quan sát bên dưới và xem chúng có chuyển sang màu nâu không. Nếu bánh đã chín vàng đẹp mắt, hãy dùng thìa lật các phần trong chảo để chúng có màu nâu ở mặt còn lại. Nhấn xuống một lần nữa bằng thìa.', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2816, 419, 8, 'Nếu dính quá, bạn có thể cho thêm một ít bơ vào chảo. Tiếp tục nấu theo cách này cho đến khi khoai tây và thịt bò bắp có màu nâu đẹp mắt.', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2817, 419, 9, 'Khuấy rau mùi tây và nêm gia vị:', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2818, 419, 10, 'Tắt bếp, cho rau mùi tây cắt nhỏ vào khuấy đều. Thêm nhiều hạt tiêu đen mới xay và thêm muối cho vừa ăn.', NULL, '2026-05-15 14:48:36', '2026-05-15 14:48:36'),
(2819, 420, 1, 'Đun nóng dầu trong chảo', NULL, '2026-05-15 14:48:39', '2026-05-15 14:48:39'),
(2820, 420, 2, 'Thêm rau xắt nhỏ và xào cho đến khi mềm', NULL, '2026-05-15 14:48:39', '2026-05-15 14:48:39'),
(2821, 420, 3, 'Lấy một cái nồi, đổ đậu và rau vào nồi, cho xúc xích vào nấu thêm 20 phút ở lửa nhỏ', NULL, '2026-05-15 14:48:39', '2026-05-15 14:48:39'),
(2822, 420, 4, 'Hoặc cho vào lò nướng và nướng ở nhiệt độ 180°C/350°F trong 30 phút', NULL, '2026-05-15 14:48:39', '2026-05-15 14:48:39'),
(2823, 420, 5, 'Món ăn này thậm chí còn ngon hơn nếu được hâm nóng lại vào ngày hôm sau', NULL, '2026-05-15 14:48:39', '2026-05-15 14:48:39'),
(2824, 421, 1, 'Làm nóng lò ở mức quạt 200°C / 220°C / 425°F / Dấu gas 7', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2825, 421, 2, 'Nếu bạn chưa mua thịt cừu thái hạt lựu, hãy cắt vai hoặc chân cừu thành từng miếng lớn và đặt sang một bên.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2826, 421, 3, 'Những miếng thịt cừu băm nhỏ trên thớt đỏ', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2827, 421, 4, 'Làm dầu ướp -', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2828, 421, 5, 'Trộn 80ml dầu ô liu vào tô với tỏi xay nhuyễn, cà chua xay nhuyễn, hạt tiêu đen và muối.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2829, 421, 6, 'dầu ô liu, cà chua xay nhuyễn gia, tỏi gia nghiền nhuyễn và tiêu đen trộn với nhau trong một chiếc bát bạc để làm món peka Croatia', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2830, 421, 7, 'Cho khoai tây và rau vào một đĩa thịt hầm lớn có nắp đậy.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2831, 421, 8, 'Rau củ xắt nhỏ bao gồm hành tây đỏ xắt nhỏ, bí xanh, khoai tây ớt đỏ trong chảo gang', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2832, 421, 9, 'Đặt thịt cừu thái hạt lựu lên trên các loại rau, rưới nước xốt và rượu lên trên.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2833, 421, 10, 'Những miếng thịt cừu phủ sốt dầu cà chua khô đặt trên cùng với hành tây đỏ xắt nhỏ, cà tím, bí xanh và khoai tây trong chảo gang', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2834, 421, 11, 'Thêm hương thảo, húng tây và cây xô thơm, cố gắng giữ các loại thảo mộc ở trên.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2835, 421, 12, 'Vì vậy, bạn có thể dễ dàng loại bỏ cuống thảo mộc sau khi nấu chín.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2836, 421, 13, 'Những miếng thịt cừu phủ sốt dầu cà chua khô và phủ húng tây, hương thảo và cây xô thơm đặt trên cùng với hành tây đỏ xắt nhỏ, cà tím, bí xanh và khoai tây trong chảo gang', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2837, 421, 14, 'Đậy nắp lên đĩa thịt hầm và nấu trong 1 giờ 30 phút', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2838, 421, 15, 'Nếu bạn không có nắp đậy thật tốt bằng giấy bạc nhà bếp', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2839, 421, 16, 'Đĩa gang có nắp đậy trong lò', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2840, 421, 17, 'Mở nắp, loại bỏ những cọng thảo mộc dày. Khuấy 2 muỗng canh dầu ô liu.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2841, 421, 18, 'Nấu thêm 20-30 phút nữa.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2842, 421, 19, 'Thịt cừu Croatia Peka nấu chín trong chảo gang trong lò nướng', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2843, 421, 20, 'Ăn kèm với bánh mì tươi tự làm để nhúng vào nước ép.', NULL, '2026-05-15 14:48:40', '2026-05-15 14:48:40'),
(2845, 422, 1, 'Làm nóng lò nướng ở mức quạt/khí 160C/140C 3. Làm mềm cần tây, hành tây, cà rốt, nguyệt quế và 1 nhánh húng tây trong nồi với 1 muỗng canh dầu và bơ trong 10 phút. Khuấy bột mì, tiếp theo là bột nhuyễn, sốt Worcestershire và nước kho.', NULL, '2026-05-15 14:48:41', '2026-05-16 12:35:34'),
(2847, 422, 2, 'Khuấy dần dần với 600ml nước nóng, sau đó cho thịt bò vào đun sôi nhẹ. Đậy nắp và nướng trong lò khoảng 2 giờ 30 phút, sau đó mở nắp và nấu thêm 30 phút -1 giờ nữa cho đến khi thịt thực sự mềm và nước sốt đặc lại.', NULL, '2026-05-15 14:48:41', '2026-05-16 12:35:34'),
(2849, 422, 3, 'Trong khi đó, nấu khoai tây trong chảo nước sôi cho đến khi chưa chín nhưng còn khoảng ¾ chặng đường.', NULL, '2026-05-15 14:48:41', '2026-05-16 12:35:34'),
(2851, 422, 4, 'Chuyển thịt sang đĩa nướng. Cắt khoai tây thành những viên tròn dày 1cm và trộn nhẹ nhàng với gia vị, dầu còn lại và lá húng tây. Xếp lớp thịt bò lên trên, rải đều phô mai khi bạn xếp lớp. Bây giờ bạn có thể đậy nắp và làm lạnh chiếc bánh trong 1 ngày hoặc để đông lạnh tối đa 3 tháng.', NULL, '2026-05-15 14:48:41', '2026-05-16 12:35:34'),
(2853, 422, 5, 'Tăng lò nướng lên 200C/180C quạt/gas 6 và nướng trong 30-40 phút cho đến khi vàng và giòn, và nước sốt sủi bọt nếu món ăn để nguội. Ăn kèm với đậu Hà Lan.', NULL, '2026-05-15 14:48:41', '2026-05-16 12:35:34'),
(2855, 423, 1, 'Chuẩn bị mì theo hướng dẫn gói, sau đó để ráo nước và đặt sang một bên. Trộn tất cả các nguyên liệu làm nước sốt vào một cái bát hoặc bình nhỏ và đặt sang một bên.', NULL, '2026-05-15 14:48:43', '2026-05-16 12:35:34'),
(2857, 423, 2, 'Đun nóng dầu trong chảo lớn hoặc chảo rán trên lửa cao rồi xào tỏi và ớt trong 20 giây cho đến khi bắt đầu chuyển sang màu vàng. Thêm bít tết và xào trong 1 phút cho đến khi chín và bắt đầu có màu nâu. Thêm bông cải xanh và xào thêm một phút nữa, sau đó cho mì vào và thêm nước sốt. Xào thêm 1-2 phút nữa cho đến khi hòa quyện và nóng hổi.', NULL, '2026-05-15 14:48:43', '2026-05-16 12:35:34'),
(2859, 423, 3, 'Khuấy húng quế và tắt lửa. Phục vụ ngay lập tức để tránh nấu quá chín.', NULL, '2026-05-15 14:48:43', '2026-05-16 12:35:34'),
(2860, 424, 1, 'Chuẩn bị bánh mì cho phần dưới cùng của món ăn: Lấy bánh mì pita và xé thành từng miếng vừa ăn. Trong chảo rán, thêm khoảng 1/4 que bơ, thêm miếng bánh mì vào và chiên cho đến khi vàng nâu và giòn. Đặt những miếng này vào đĩa nướng thủy tinh, tốt nhất là đĩa có kích thước hình vuông. Đặt sang một bên.', NULL, '2026-05-15 14:48:44', '2026-05-15 14:48:44'),
(2861, 424, 2, 'Sau đó cho vào chảo, thêm một ít bơ, muối, khoảng 2 tép tỏi tươi giã nhuyễn, khoảng một thìa cà phê thì là khuấy đều cho đến khi ngửi thấy mùi thơm thì cho các miếng bánh mì đã chiên vào hỗn hợp này, đảo đều cho bánh mì phủ đều rồi cho vào khay nướng thủy tinh. Đặt sang một bên.', NULL, '2026-05-15 14:48:44', '2026-05-15 14:48:44'),
(2862, 424, 3, 'Chuẩn bị thịt: cho một ít bơ vào nồi, xào thịt cho đến khi chín vàng, thêm 1 củ hành tây cắt tư, muối tiêu, 1 viên nước luộc gà và nước cho ngập thịt. Đun sôi, vặn nhỏ lửa, đậy nắp và nấu cho đến khi mềm, khoảng 2 giờ. Sau khi thịt nguội, lấy từng miếng thịt ra cho vào tô, để riêng. Dự trữ súp từ thịt riêng biệt.', NULL, '2026-05-15 14:48:44', '2026-05-15 14:48:44'),
(2863, 424, 4, 'Chuẩn bị cơm: Cho một ít bơ vào nồi, thêm khoảng một nắm shareya (mì fideo), khuấy liên tục cho đến khi có màu vàng nâu, không quá đậm mà rất vàng. Sau đó cho hai chén gạo vào, khuấy một chút cho đến khi một ít gạo chuyển sang màu trắng đục. Thêm 2-1/4 cốc nước và muối cho vừa ăn. Đun sôi, đậy nắp và vặn nhỏ lửa, nấu cho đến khi mềm. Kiểm tra độ mềm của gạo sau khoảng 35 phút.', NULL, '2026-05-15 14:48:44', '2026-05-15 14:48:44'),
(2864, 424, 5, 'Bây giờ lấy một ít nước súp từ thịt và thêm lên trên các miếng bánh mì trong khay nướng để thấm đẫm. Thêm cơm đã nấu chín lên trên các miếng bánh mì. Từ từ múc phần súp còn lại lên cơm, nhìn vào mặt đĩa thủy tinh để biết mức súp, chỉ nên chạm tới mặt trên của cơm, đừng lo lắng, điều này không cần phải chính xác. Bây giờ bạn đã sẵn sàng làm nước sốt và chiên thịt để đặt lên trên.', NULL, '2026-05-15 14:48:44', '2026-05-15 14:48:44'),
(2865, 424, 6, 'Để chuẩn bị nước sốt đỏ: Cho một ít dầu hoặc bơ vào chảo, cà chua nghiền, nửa thìa cà phê bột cà chua, muối và tiêu, 2 tép tỏi tươi nghiền và thì là. Thêm khoảng 3 thìa giấm vào, khuấy đều cho đến khi ngửi thấy mùi thơm và hơi mịn. Nên đặc một chút, không bị chảy nước, nhưng nếu đặc quá bạn có thể thêm một chút nước. Dùng thìa gỗ trải cơm lên trên để phủ.', NULL, '2026-05-15 14:48:44', '2026-05-15 14:48:44'),
(2866, 424, 7, 'Chiên thịt: Cho một ít bơ hoặc dầu vào chảo, cho thịt vào một chút tương cà chua, khoảng một thìa tỏi tươi giã nhuyễn, muối tiêu, một thìa thì là. Nấu cho đến khi thịt chín vàng.', NULL, '2026-05-15 14:48:44', '2026-05-15 14:48:44'),
(2867, 424, 8, 'Múc thứ này lên trên cơm và thưởng thức. Thưởng thức!', NULL, '2026-05-15 14:48:44', '2026-05-15 14:48:44'),
(2868, 425, 1, 'Đun sôi một nồi lớn nước muối nhẹ. Cho đầu bắp cải vào nước, đậy nắp nồi và nấu cho đến khi lá bắp cải hơi mềm, có thể lấy ra khỏi đầu, trong 3 phút. Lấy bắp cải ra khỏi nồi và để bắp cải ngồi cho đến khi lá đủ nguội để cầm, khoảng 10 phút.', NULL, '2026-05-15 14:48:45', '2026-05-15 14:48:45'),
(2869, 425, 2, 'Cắt bỏ toàn bộ 18 lá ở đầu bắp cải, cắt bỏ những gân dày, cứng ở giữa. Đặt toàn bộ lá sang một bên. Cắt nhỏ phần đầu bắp cải còn lại và trải vào đáy đĩa thịt hầm.', NULL, '2026-05-15 14:48:45', '2026-05-15 14:48:45'),
(2870, 425, 3, 'Đun chảy bơ trong chảo lớn trên lửa vừa cao. Nấu và khuấy hành tây trong bơ nóng cho đến khi mềm, từ 5 đến 10 phút. Mát mẻ.', NULL, '2026-05-15 14:48:45', '2026-05-15 14:48:45');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(2871, 425, 4, 'Khuấy hành tây, thịt bò, thịt lợn, gạo, tỏi, 1 muỗng cà phê muối và 1/4 muỗng cà phê tiêu với nhau trong một tô lớn.', NULL, '2026-05-15 14:48:45', '2026-05-15 14:48:45'),
(2872, 425, 5, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C).', NULL, '2026-05-15 14:48:45', '2026-05-15 14:48:45'),
(2873, 425, 6, 'Đặt khoảng 1/2 chén hỗn hợp thịt bò lên lá bắp cải. Cuộn bắp cải quanh hỗn hợp thịt bò, nhét từng bên để tạo lớp bao quanh miếng thịt. Lặp lại với hỗn hợp lá và thịt còn lại. Xếp các cuộn bắp cải thành một lớp lên trên bắp cải đã cắt nhỏ trong đĩa thịt hầm; cuộn mùa với muối và hạt tiêu đen.', NULL, '2026-05-15 14:48:45', '2026-05-15 14:48:45'),
(2874, 425, 7, 'Đánh đều súp cà chua, nước ép cà chua và sốt cà chua trong một cái bát. Đổ hỗn hợp súp cà chua lên cuộn bắp cải và bọc đĩa bằng giấy nhôm.', NULL, '2026-05-15 14:48:45', '2026-05-15 14:48:45'),
(2875, 425, 8, 'Nướng trong lò làm nóng trước cho đến khi bắp cải mềm và thịt chín, khoảng 1 giờ.', NULL, '2026-05-15 14:48:45', '2026-05-15 14:48:45'),
(2876, 426, 1, 'Làm nóng lò nướng đến 180C/350F/mốc gas 4. Xả và rửa sạch lúa mì đã ngâm, cho vào chảo vừa với nhiều nước, đun sôi và đun nhỏ lửa trong một giờ cho đến khi chín. Xả và đặt sang một bên.', NULL, '2026-05-15 14:48:47', '2026-05-15 14:48:47'),
(2877, 426, 2, 'Nêm thịt cừu với một thìa cà phê muối và một ít hạt tiêu đen. Cho một thìa dầu vào chảo xào sâu, lớn có nắp đậy; đặt trên lửa vừa cao. Thêm một ít thịt cừu vào chảo - đừng đổ quá nhiều thịt vào chảo - và nướng trong bốn phút cho tất cả các mặt. Chuyển sang tô và lặp lại với miếng thịt cừu còn lại, thêm dầu nếu cần.', NULL, '2026-05-15 14:48:47', '2026-05-15 14:48:47'),
(2878, 426, 3, 'Giảm nhiệt xuống mức trung bình và thêm một muỗng dầu vào chảo. Thêm hẹ tây và chiên trong bốn phút cho đến khi có màu caramen. Đổ những thứ này vào bát thịt cừu, và lặp lại với các loại rau còn lại cho đến khi chúng đều có màu nâu đẹp mắt, thêm dầu nếu bạn cần.', NULL, '2026-05-15 14:48:47', '2026-05-15 14:48:47'),
(2879, 426, 4, 'Sau khi tất cả các loại rau đã chín và lấy ra khỏi chảo, hãy thêm rượu cùng với đường, rau thơm, một thìa cà phê muối và một hạt tiêu đen xay nhuyễn. Đun sôi ở nhiệt độ cao trong khoảng ba phút.', NULL, '2026-05-15 14:48:47', '2026-05-15 14:48:47'),
(2880, 426, 5, 'Đổ thịt cừu, rau và lúa mì nguyên hạt vào nồi rồi thêm nước kho vào. Đậy nắp và đun sôi trong năm phút, sau đó chuyển vào lò nướng trong một tiếng rưỡi.', NULL, '2026-05-15 14:48:47', '2026-05-15 14:48:47'),
(2881, 426, 6, 'Lấy món hầm ra khỏi lò và kiểm tra chất lỏng; nếu có nhiều thì đậy nắp và đun sôi trong vài phút.', NULL, '2026-05-15 14:48:47', '2026-05-15 14:48:47'),
(2882, 427, 1, 'Làm bột bánh ngọt', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2883, 427, 2, 'Cho một tô lớn, cho bột mì, 1 thìa cà phê muối, bột nghệ vào rồi trộn đều.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2884, 427, 3, 'Chà rút ngắn vào bột cho đến khi có những miếng rút ngắn nhỏ được bao phủ hoàn toàn bằng bột mì.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2885, 427, 4, 'Đổ 1/2 cốc nước đá vào và dùng tay trộn đều để bột quyện lại với nhau. Tiếp tục thêm nước đá 2 đến 3 muỗng canh mỗi lần cho đến khi hỗn hợp tạo thành bột.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2886, 427, 5, 'Ở giai đoạn này, bạn có thể cắt bột thành 2 miếng lớn, bọc nilon và để trong tủ lạnh 30 phút trước khi dùng.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2887, 427, 6, 'Ngoài ra, hãy cắt bột thành 10 đến 12 miếng bằng nhau, đặt lên đĩa hoặc khay nướng, bọc kín bằng màng bọc thực phẩm và để nguội trong 30 phút trong khi làm nhân.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2888, 427, 7, 'Làm nhân', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2889, 427, 8, 'Cho thịt bò xay vào tô lớn. Rắc hạt tiêu và hạt tiêu đen. Trộn đều và đặt sang một bên.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2890, 427, 9, 'Đun nóng dầu trong chảo cho đến khi nóng.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2891, 427, 10, 'Thêm hành tây và xào cho đến khi trong suốt. Thêm ớt cay, tỏi và húng tây và tiếp tục xào thêm một phút nữa. Thêm 1/4 muỗng cà phê muối.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2892, 427, 11, 'Thêm thịt bò xay đã tẩm gia vị vào rồi trộn đều, bẻ vụn và nấu cho đến khi thịt không còn màu hồng.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2893, 427, 12, 'Thêm sốt cà chua và thêm muối cho vừa ăn.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2894, 427, 13, 'Đổ vào 2 cốc nước và khuấy đều. Đun sôi hỗn hợp, sau đó giảm nhiệt và đun nhỏ lửa cho đến khi phần lớn chất lỏng bay hơi và phần còn lại chuyển thành nước sốt đặc.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2895, 427, 14, 'Gấp hành lá vào. Hủy bỏ nhiệt và để nguội hoàn toàn.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2896, 427, 15, 'Lắp ráp các miếng bánh', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2897, 427, 16, 'Đánh trứng và nước với nhau để tạo thành nước rửa trứng. Đặt sang một bên.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2898, 427, 17, 'Bây giờ bạn có thể chuẩn bị bột theo hai cách.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2899, 427, 18, 'Phương pháp đầu tiên: Phủ bột lên bề mặt làm việc và cán lăn. Nếu bạn cắt nó thành 2 miếng lớn, hãy lấy một trong những miếng lớn và cuộn nó thành một vòng tròn thật lớn. Lấy một cái bát có vành rộng (khoảng 5 inch) và cắt ra ba hình tròn.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2900, 427, 19, 'Đặt khoảng 3 thìa nhân vào 1/2 mỗi hình tròn. Nhúng một ngón tay vào nước và làm ẩm các cạnh của bánh ngọt. Gấp nửa còn lại và ấn để đóng dấu.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2901, 427, 20, 'Lấy một cái nĩa và uốn các cạnh. Cắt bỏ phần thừa để trông gọn gàng và đồng đều. Đặt lên khay nướng có lót giấy da và tiếp tục làm cho đến khi cán hết bột và lấp đầy các miếng chả.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2902, 427, 21, 'Phương pháp thứ hai: Nếu bạn đã cắt sẵn bột thành từng miếng riêng lẻ, hãy làm từng miếng bột một. Cán nó trên bề mặt có bột mì thành hình tròn 5 inch hoặc lớn hơn một chút. Đừng lo lắng nếu các cạnh không hoàn hảo.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2903, 427, 22, 'Đặt 3 thìa nhân vào một bên của hình tròn. Nhúng một ngón tay vào nước và làm ẩm các cạnh của bánh ngọt. Gấp nửa còn lại và ấn để đóng dấu.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2904, 427, 23, 'Lấy một cái nĩa và uốn các cạnh. Cắt bỏ phần thừa để trông gọn gàng và đồng đều. Đặt lên khay nướng có lót giấy da và tiếp tục làm cho đến khi bạn cán hết bột và lấp đầy các miếng chả.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2905, 427, 24, 'Chiên và phục vụ các miếng chả', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2906, 427, 25, 'Sau khi tạo thành các miếng chả, đặt chảo vào tủ lạnh trong khi làm nóng lò ở nhiệt độ 350 F.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2907, 427, 26, 'Ngay trước khi cho chảo có chả vào lò nướng, hãy phết nước rửa trứng lên bánh.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2908, 427, 27, 'Nướng miếng chả trong 30 phút hoặc cho đến khi có màu vàng nâu.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2909, 427, 28, 'Làm mát trên giá đỡ dây.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2910, 427, 29, 'Phục vụ ấm áp.', NULL, '2026-05-15 14:48:48', '2026-05-15 14:48:48'),
(2911, 428, 1, 'Tối hôm trước, bẻ thịt bò muối thành từng miếng lớn rồi ngâm nước qua đêm ít nhất 8-10 tiếng. Cho đậu đã tách đôi vào tô, đổ ngập nước để ngâm qua đêm.', NULL, '2026-05-15 14:48:49', '2026-05-15 14:48:49'),
(2912, 428, 2, 'Xả thịt bò muối và cho vào nồi kho lớn. Đổ đầy nước ngọt, ít nhất 6-7 lít. Đặt đậu Hà Lan đã tách đôi vào túi vải đựng bánh pudding đậu Hà Lan hoặc ba lớp vải thưa và buộc lại, đảm bảo chừa chỗ cho đậu Hà Lan nở ra bên trong túi.', NULL, '2026-05-15 14:48:49', '2026-05-15 14:48:49'),
(2913, 428, 3, 'Đặt túi vào trong nồi, buộc dây vào tay cầm bên ngoài để túi không bị dính vào đáy nồi cùng thịt bò muối. Đun sôi, sau đó giảm nhiệt và đun nhỏ lửa trong 2 giờ.', NULL, '2026-05-15 14:48:49', '2026-05-15 14:48:49'),
(2914, 428, 4, 'Lấy túi bánh pudding đậu Hà Lan và đổ hết vào tô, trộn với bơ và hạt tiêu cho vừa ăn. Đặt sang một bên.', NULL, '2026-05-15 14:48:49', '2026-05-15 14:48:49'),
(2915, 428, 5, 'Cho bắp cải vào nồi và đun thêm 20 phút nữa. Sau đó thêm củ cải, cà rốt và khoai tây rồi đun thêm 20 phút nữa hoặc cho đến khi rau mềm.', NULL, '2026-05-15 14:48:49', '2026-05-15 14:48:49'),
(2916, 428, 6, 'Lấy thịt bò muối và rau củ ra khỏi nồi rồi bày ra đĩa.', NULL, '2026-05-15 14:48:49', '2026-05-15 14:48:49'),
(2917, 428, 7, 'Sử dụng nước nấu theo hai cách; như một loại rượu nồi mà một số người thích uống hoặc giảm bớt nó để làm nước sốt hoặc nước xốt để rưới lên bữa ăn.', NULL, '2026-05-15 14:48:49', '2026-05-15 14:48:49'),
(2918, 429, 1, 'Nghiền nửa củ hành tây và đặt sang một bên. Cắt phần hành còn lại và chiên bơ ở nhiệt độ thấp/trung bình cho đến khi có màu caramen.', NULL, '2026-05-15 14:48:50', '2026-05-15 14:48:50'),
(2919, 429, 2, 'Trong một bát, trộn đều thịt bò xay, hành tây nghiền, muối, tiêu, nhục đậu khấu, tinh bột khoai tây/ngô và nước.', NULL, '2026-05-15 14:48:50', '2026-05-15 14:48:50'),
(2920, 429, 3, 'Tạo thành xúc xích và cắt 6 miếng. Dùng dao tạo hoa văn lưới nhẹ trên mỗi miếng bánh.', NULL, '2026-05-15 14:48:50', '2026-05-15 14:48:50'),
(2921, 429, 4, 'Nâu vàng cả hai mặt của karbonader trong bơ ở nhiệt độ cao, sau đó giảm nhiệt độ xuống và chiên thêm 2 – 3 phút nữa.', NULL, '2026-05-15 14:48:50', '2026-05-15 14:48:50'),
(2922, 429, 5, 'Phục vụ món karbonader và hành tây với khoai tây, đậu Hà Lan hầm và nước sốt nâu cho bữa tối hoặc trên một lát bánh mì cho bữa trưa hoặc bữa ăn nhẹ.', NULL, '2026-05-15 14:48:50', '2026-05-15 14:48:50'),
(2923, 430, 1, 'Đun sôi 4 cốc nước trong lò nướng hoặc nồi súp kiểu Hà Lan. Thêm thịt bò, tỏi và gừng vào rồi khuấy đều. Đun sôi nhẹ, đậy nắp và nấu, thỉnh thoảng khuấy trong 20 phút. Nếu bạn thấy có váng bọt ở trên, đừng lo lắng, bạn chỉ cần múc nó đi hoặc khuấy lại.', NULL, '2026-05-15 14:48:51', '2026-05-15 14:48:51'),
(2924, 430, 2, 'Tắt bếp và để ráo nước, nhưng để dành phần nước thừa để dùng sau.', NULL, '2026-05-15 14:48:51', '2026-05-15 14:48:51'),
(2925, 430, 3, 'Cho nồi hoặc lò nướng Hà Lan lên lửa vừa cùng với 2 thìa dầu ăn. Khi dầu đã sủi bọt, thêm hành vào và nấu, thỉnh thoảng khuấy cho đến khi mềm, từ 5 đến 7 phút.', NULL, '2026-05-15 14:48:51', '2026-05-15 14:48:51'),
(2926, 430, 4, 'Thêm cà chua vào hành tây và tiếp tục nấu, thỉnh thoảng khuấy cho đến khi cà chua rơi ra, từ 3 đến 5 phút.', NULL, '2026-05-15 14:48:51', '2026-05-15 14:48:51'),
(2927, 430, 5, 'Thêm thịt bò đã ráo nước vào hỗn hợp cà chua và hành tây rồi khuấy đều. Tiếp tục nấu trên lửa vừa trong 5 phút, thỉnh thoảng khuấy.', NULL, '2026-05-15 14:48:51', '2026-05-15 14:48:51'),
(2928, 430, 6, 'Thêm ớt bột, hạt tiêu, bột cà ri, bột cà chua và muối cho vừa ăn rồi khuấy đều.', NULL, '2026-05-15 14:48:51', '2026-05-15 14:48:51'),
(2929, 430, 7, 'Thêm lại lượng nước dư dùng để nấu thịt bò, cùng với lượng nước vừa đủ để ngập. Đun sôi, giảm nhiệt và đun nhỏ lửa, không đậy nắp, thỉnh thoảng khuấy trong khoảng 1 giờ hoặc cho đến khi thịt mềm và nước sốt đặc lại. Thêm nước bổ sung nếu cà ri thịt bò của bạn bắt đầu khô và dính, hoặc nếu bạn muốn cà ri của bạn có độ đặc sệt hơn.', NULL, '2026-05-15 14:48:51', '2026-05-15 14:48:51'),
(2930, 430, 8, 'Khi cà ri bò đã sẵn sàng, tắt bếp, nếm thử và điều chỉnh gia vị theo ý muốn. Trang trí với ớt tươi và ngò.', NULL, '2026-05-15 14:48:51', '2026-05-15 14:48:51'),
(2932, 431, 1, 'Cho gừng, tỏi, sả, rau mùi và 1 quả ớt vào máy xay thực phẩm rồi xay nhuyễn. Đun nóng dầu trong chảo ở lửa nhỏ. Thêm bột nhuyễn và nấu trong 5 phút. Cho thịt bò, đậu nành, ngũ vị hương, đường và nước kho vào trộn đều. Đậy nắp và đun sôi, sau đó giảm nhiệt và đun nhỏ lửa trong 1 giờ 15 phút. Đậy nắp và nấu thêm 15 phút nữa cho đến khi thịt bò mềm.', NULL, '2026-05-15 14:48:53', '2026-05-16 12:35:34'),
(2934, 431, 2, 'Ngay trước khi ăn, hãy chuẩn bị mì theo hướng dẫn trên bao bì. Để ráo nước rồi chia ra 2 tô và dùng thìa rưới lên thịt bò hầm. Ăn kèm với ớt và lá rau mùi còn lại, thêm chanh để ép.', NULL, '2026-05-15 14:48:53', '2026-05-16 12:35:34'),
(2935, 432, 1, 'Thêm một chút muối và dầu mè vào thịt bò băm. Trộn đều và đặt sang một bên.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2936, 432, 2, 'Trộn 1 thìa bột ngô với 2, ½ thìa nước vào tô nhỏ để tạo thành bột nước.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2937, 432, 3, 'Đậu phụ cắt thành khối vuông (khoảng 2cm). Đun sôi một lượng nước lớn rồi thêm một chút muối. Cho đậu phụ vào và nấu trong 1 phút. Di chuyển ra ngoài và thoát nước.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2938, 432, 4, 'Bắt chảo lên bếp đun nóng khoảng 2 thìa dầu, cho thịt băm vào chiên giòn. Gắp thịt bò ra và để lại dầu.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2939, 432, 5, 'Chiên doubanjiang trong 1 phút trên lửa nhỏ rồi cho tỏi, hành lá trắng, gừng và đậu đen lên men vào nấu trong 30 giây cho đến khi có mùi thơm. Sau đó trộn hạt tiêu vào.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2940, 432, 6, 'Thêm nước vào gia vị và đun sôi trên lửa lớn. Nhẹ nhàng trượt các khối đậu phụ. Thêm nước tương nhạt và thịt bò. Sau khi đun sôi, giảm lửa nhỏ rồi đun nhỏ lửa trong 6-8 phút. Sau đó thêm tỏi xanh xắt nhỏ.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2941, 432, 7, 'Khuấy đều tinh bột nước rồi đổ một nửa hỗn hợp vào nồi đun sôi. Đợi khoảng 30 giây rồi đổ nửa còn lại. Bạn có thể nêm nếm đậu phụ một chút và thêm chút muối nếu chưa đủ mặn. Nhân tiện, nếu bạn cảm thấy nó quá cay, hãy thêm một ít đường có thể làm dịu hương vị. Nhưng hãy cẩn thận vì nước dùng lúc này rất nóng.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2942, 432, 8, 'Chuyển ra ngoài khi gần như tất cả gia vị đã dính vào các viên đậu phụ. Rắc bột tiêu Tứ Xuyên (tùy khẩu vị) và tỏi băm nhỏ nếu dùng.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2943, 432, 9, 'Ăn ngay với cơm hấp.', NULL, '2026-05-15 14:48:54', '2026-05-15 14:48:54'),
(2944, 433, 1, 'Làm nóng lò ở nhiệt độ 200C/180C quạt/gas 6, sau đó rang đậu phộng trên khay nướng trong 5 phút cho đến khi có màu vàng nâu. Khi đủ nguội để xử lý, hãy cắt nhỏ. Giảm nhiệt độ lò/quạt xuống 180C/160C 4.', NULL, '2026-05-15 14:48:56', '2026-05-15 14:48:56'),
(2945, 433, 2, 'Đun nóng 2 muỗng canh nước cốt dừa trong một cái nồi lớn có nắp đậy. Thêm bột cà ri và chiên trong 1 phút, sau đó cho thịt bò vào xào cho đến khi được phủ đều và kín. Khuấy phần dừa còn lại với nửa lon nước, khoai tây, hành tây, lá chanh, quế, me, đường, nước mắm và hầu hết đậu phộng. Đun sôi, sau đó đậy nắp và nấu trong lò trong 2 giờ cho đến khi thịt bò mềm.', NULL, '2026-05-15 14:48:56', '2026-05-15 14:48:56'),
(2946, 433, 3, 'Rắc ớt thái lát và số đậu phộng còn lại, sau đó dùng ngay từ đĩa với cơm hoa nhài.', NULL, '2026-05-15 14:48:56', '2026-05-15 14:48:56'),
(2947, 434, 1, 'Làm nóng lò ở 200C/400F/Gas 6.', NULL, '2026-05-15 14:48:58', '2026-05-15 14:48:58'),
(2948, 434, 2, 'Đun nóng dầu trong chảo sâu lòng và chiên thịt bò băm trong 4-5 phút, dùng thìa gỗ bẻ nhỏ khi thịt có màu nâu.', NULL, '2026-05-15 14:48:58', '2026-05-15 14:48:58'),
(2949, 434, 3, 'Thêm hành tây và nấu trong 2-3 phút, sau đó cho cà chua xay nhuyễn vào và nấu thêm 2-3 phút nữa. Khuấy bột và nấu thêm một phút nữa, sau đó thêm nấm cắt nhỏ, thịt bò hoặc thịt bò kho và một chút sốt Worcestershire. Đun sôi, sau đó giảm nhiệt, đậy nắp chảo và đun nhỏ lửa trong 20 phút. Đặt sang một bên và để nguội, sau đó biến hỗn hợp thịt thành đĩa bánh một lít.', NULL, '2026-05-15 14:48:58', '2026-05-15 14:48:58'),
(2950, 434, 4, 'Lăn bánh ngọt trên bề mặt đã phủ bột mì cho đến khi nó lớn hơn đĩa bánh một chút. Nhẹ nhàng phủ bánh lên trên đĩa, ấn chặt vào các cạnh. Cắt tỉa, sau đó định hình các cạnh thành hình rãnh.', NULL, '2026-05-15 14:48:58', '2026-05-15 14:48:58'),
(2951, 434, 5, 'Cắt một số hình chiếc lá ra khỏi phần trang trí bánh ngọt và trang trí mặt trên của chiếc bánh, dán chúng lên bánh ngọt với lòng đỏ trứng đã đánh bông.', NULL, '2026-05-15 14:48:58', '2026-05-15 14:48:58'),
(2952, 434, 6, 'Tạo ba hoặc bốn khe trên bánh để hơi nước thoát ra ngoài, sau đó phết phần lòng đỏ trứng đã đánh còn lại lên bánh và nướng trong lò khoảng 20-25 phút hoặc cho đến khi có màu vàng nâu.', NULL, '2026-05-15 14:48:58', '2026-05-15 14:48:58'),
(2953, 434, 7, 'Để phục vụ, cắt thành nêm.', NULL, '2026-05-15 14:48:58', '2026-05-15 14:48:58'),
(2955, 435, 1, 'Để làm ớt, đun nóng dầu trong chảo và xào hành tây trong 5 phút cho đến khi mềm. Thêm gia vị; chiên trong 1 phút. Khuấy thịt bò và nấu trong vài phút. Thêm bột cà chua, nước kho và quế. Khuấy đều, đun sôi, sau đó đun nhỏ lửa trong 15-20 phút cho đến khi còn lại rất ít chất lỏng. Thêm đậu 5 phút trước khi kết thúc nấu. Kiểm tra gia vị và để nguội.', NULL, '2026-05-15 14:49:01', '2026-05-16 12:35:34'),
(2957, 435, 2, 'Làm nóng lò nướng ở 200C/quạt 180C/gas 6. Dùng dao cắt bánh ngọt 7cm, dập 12 hình tròn từ bánh ngọt. Dùng để lót khay bánh muffin nhỏ 12 lỗ, dùng nĩa chọc vào đế bánh và nướng trong 10 phút. Lấy ra khỏi lò và để nguội trên khay lưới. Lặp lại với bánh ngọt còn lại.', NULL, '2026-05-15 14:49:01', '2026-05-16 12:35:34'),
(2959, 435, 3, 'Trong khi đó, luộc khoai tây trong nước sôi cho đến khi mềm. Để ráo nước, nghiền nhuyễn với kem chua và gia vị rồi đảo qua hẹ. Múc 1-2 thìa ớt trộn vào vỏ bánh ngọt và phủ lên trên một thìa cà phê nghiền. Nghiền nhuyễn bằng nĩa; quay trở lại lò nướng trong 15 phút hoặc cho đến khi vàng.', NULL, '2026-05-15 14:49:01', '2026-05-16 12:35:34'),
(2960, 436, 1, 'Để làm thuốc, trộn đều muối, muối hồng, tiêu đen, rau mùi, đường, lá nguyệt quế và đinh hương trong một bát nhỏ. Phủ toàn bộ ức bằng thuốc chữa và cho vào một túi nhựa cực lớn có thể khóa lại. Đặt ở nơi lạnh nhất của tủ lạnh và để trong 4 ngày, lật ức hai lần một ngày.', NULL, '2026-05-15 14:49:03', '2026-05-15 14:49:03'),
(2961, 436, 2, 'Lấy thịt ức ra khỏi túi và rửa sạch càng nhiều càng tốt dưới vòi nước lạnh. Đặt thịt ức vào một thùng chứa lớn, đổ đầy nước và ngâm trong 2 giờ, thay nước sau mỗi 30 phút. Lấy ra khỏi nước và lau khô bằng khăn giấy.', NULL, '2026-05-15 14:49:03', '2026-05-15 14:49:03'),
(2962, 436, 3, 'Để làm hỗn hợp chà xát, trộn hạt tiêu đen, rau mùi, ớt bột, bột tỏi, bột hành tây, thì là, mù tạt, hạt cần tây và ớt đỏ nghiền vào một cái bát nhỏ. Phủ toàn bộ ức bằng chà xát.', NULL, '2026-05-15 14:49:03', '2026-05-15 14:49:03'),
(2963, 436, 4, 'Đốt lửa hoặc nướng ở nhiệt độ 225 độ, thêm các khối gỗ hút thuốc khi ở nhiệt độ. Khi gỗ bốc cháy và tạo ra khói, đặt miếng ức vào, mặt mỡ hướng lên trên và hun khói cho đến khi nhiệt kế đọc tức thời ghi 165 độ khi đưa vào phần dày nhất của miếng ức, khoảng 6 giờ.', NULL, '2026-05-15 14:49:03', '2026-05-15 14:49:03'),
(2964, 436, 5, 'Chuyển thịt ức vào chảo rang lớn có giá chữ V. Đặt chảo rang lên hai đầu đốt trên bếp và đổ đầy nước khoảng 1 inch. Đun sôi nước ở nhiệt độ cao, giảm nhiệt ở mức trung bình, đậy chảo rang bằng giấy nhôm và hấp ức cho đến khi nhiệt kế đọc tức thời ghi 180 độ khi đưa vào phần dày nhất của thịt, từ 1 đến 2 giờ, thêm nước nóng nếu cần.', NULL, '2026-05-15 14:49:03', '2026-05-15 14:49:03'),
(2965, 436, 6, 'Chuyển thịt ức vào thớt và để nguội một chút. Cắt lát và phục vụ, tốt nhất là trên lúa mạch đen với mù tạt.', NULL, '2026-05-15 14:49:03', '2026-05-15 14:49:03'),
(2966, 437, 1, 'Trộn đuôi bò với hành tây, hành lá, tỏi, gừng, ớt, nước tương, húng tây, muối và tiêu. Đun nóng dầu thực vật trong chảo lớn trên lửa vừa cao. Chiên đuôi bò trong chảo cho đến khi chín vàng toàn bộ, khoảng 10 phút. Cho vào nồi áp suất, đổ vào 375ml nước. Nấu ở áp suất trong 25 phút, sau đó tắt bếp và tháo nắp theo hướng dẫn của nhà sản xuất.', NULL, '2026-05-15 14:49:04', '2026-05-15 14:49:04'),
(2967, 437, 2, 'Thêm đậu tằm và quả pimento vào, đun sôi trên lửa vừa cao. Hòa tan bột ngô với 2 thìa nước rồi cho vào đuôi bò đang sôi lăn tăn. Nấu và khuấy vài phút cho đến khi nước sốt đặc lại và đậu mềm.', NULL, '2026-05-15 14:49:04', '2026-05-15 14:49:04'),
(2968, 438, 1, 'Rây bột mì và muối vào tô trộn lớn.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2969, 438, 2, 'Dùng thìa đẩy lòng đỏ trứng qua rây mịn vào bột.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2970, 438, 3, 'Thêm trứng sống và trộn đều.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2971, 438, 4, 'Đánh bơ 1 muỗng canh mỗi lần.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2972, 438, 5, 'Đặt bột lên bề mặt đã rắc bột mì và nhào cho đến khi mịn và đàn hồi, sau đó bọc trong giấy sáp và để trong tủ lạnh cho đến khi cứng lại (ít nhất 30 phút).', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2973, 438, 6, 'Trong một chiếc chảo nặng, làm tan chảy 2 thìa bơ trên lửa vừa; xào hành tây và rutabaga cho đến khi hành tây mềm và trong suốt (5 phút).', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2974, 438, 7, 'Cho hành tây, rutabaga và thịt bò vào máy xay thịt hai lần nếu có, nếu không chỉ cần cắt chúng càng mịn càng tốt.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2975, 438, 8, 'Đun chảy 4 thìa bơ còn lại trên lửa vừa và thêm hỗn hợp thịt vào.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2976, 438, 9, 'Nấu trên lửa nhỏ, thỉnh thoảng khuấy cho đến khi toàn bộ chất lỏng bay hơi và hỗn hợp đủ đặc để giữ được hình dạng.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2977, 438, 10, 'Tắt bếp và để nguội, sau đó cho 1 quả trứng vào khuấy đều, nêm muối và tiêu.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2978, 438, 11, 'Làm nóng lò ở nhiệt độ 350°F.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2979, 438, 12, 'Trên bề mặt đã phủ một ít bột mì, cán bột thành hình chữ nhật 13x8\" (dày 1/8\").', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2980, 438, 13, 'Đổ nhân vào giữa hình chữ nhật theo chiều dọc, chừa khoảng trống khoảng 1 inch ở mỗi đầu.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2981, 438, 14, 'Nhẹ nhàng chải các cạnh dài bằng nước lạnh, sau đó gấp một trong các cạnh dài lên phần nhân và mặt còn lại lên trên.', NULL, '2026-05-15 14:49:05', '2026-05-15 14:49:05'),
(2982, 438, 15, 'Chải các đầu ngắn bằng nước lạnh và gấp chúng lên trên, bao bọc phần nhân.', NULL, '2026-05-15 14:49:06', '2026-05-15 14:49:06'),
(2983, 438, 16, 'Đặt mặt bánh ngọt úp xuống khay nướng và phết đều phần trứng bác còn lại lên trên.', NULL, '2026-05-15 14:49:06', '2026-05-15 14:49:06'),
(2984, 438, 17, 'Nướng trong lò làm nóng trước cho đến khi có màu vàng nâu đậm (30 phút).', NULL, '2026-05-15 14:49:06', '2026-05-15 14:49:06'),
(2985, 438, 18, 'Cắt bánh ngọt theo đường chéo thành những miếng dài 1,5 inch và dùng làm món khai vị hoặc dùng kèm với súp.', NULL, '2026-05-15 14:49:06', '2026-05-15 14:49:06'),
(2986, 439, 1, 'BƯỚC 1', NULL, '2026-05-15 14:49:07', '2026-05-15 14:49:07'),
(2987, 439, 2, 'Chà tỏi lên miếng bít tết, sau đó cho vào túi đựng bánh sandwich và rắc dầu ô liu, giấm sherry và cọng mùi tây vào. Trộn đều mọi thứ lại với nhau, sau đó dùng cây lăn để đập miếng bít tết vài lần. Để trong 1-2 giờ.', NULL, '2026-05-15 14:49:07', '2026-05-15 14:49:07'),
(2988, 439, 3, 'BƯỚC 2', NULL, '2026-05-15 14:49:07', '2026-05-15 14:49:07'),
(2989, 439, 4, 'Để làm nước sốt, cho tất cả nguyên liệu vào máy xay sinh tố với 1 muỗng canh nước và xay cho đến khi mịn nhất có thể. Điều này sẽ tạo ra nhiều hơn mức bạn cần cho công thức nhưng sẽ giữ được trong một tuần trong lọ kín.', NULL, '2026-05-15 14:49:07', '2026-05-15 14:49:07'),
(2990, 439, 5, 'BƯỚC 3', NULL, '2026-05-15 14:49:07', '2026-05-15 14:49:07'),
(2991, 439, 6, 'Đun nóng vỉ nướng hoặc chảo rán ở mức cao. Loại bỏ cọng tỏi và mùi tây khỏi miếng bít tết và nêm gia vị thật kỹ. Áp chảo bít tết mỗi mặt trong 2 phút rồi đặt lên đĩa. Đặt nửa ciabatta lên đĩa, nướng úp mặt xuống để thấm hết nước.', NULL, '2026-05-15 14:49:07', '2026-05-15 14:49:07'),
(2992, 439, 7, 'BƯỚC 4', NULL, '2026-05-15 14:49:07', '2026-05-15 14:49:07'),
(2993, 439, 8, 'Cắt miếng bít tết sau đó nhồi vào cuộn với nước sốt xanh và tên lửa.', NULL, '2026-05-15 14:49:07', '2026-05-15 14:49:07'),
(2994, 440, 1, 'Đậu thận khô rửa sạch.. sau đó ngâm với nước trong một cái bát sâu lòng. Hãy nhớ rằng khi ngâm chúng sẽ nở ra ít nhất gấp ba lần kích thước ban đầu, vì vậy hãy thêm nhiều nước vào bát. Ngâm chúng qua đêm hoặc ít nhất 2 giờ để quá trình nấu diễn ra nhanh hơn. Tôi đổ nước mà chúng đã ngâm sau khi nó hoạt động.', NULL, '2026-05-15 14:49:09', '2026-05-15 14:49:09'),
(2995, 440, 2, 'Yêu cầu người bán thịt cắt bím tóc muối thành những miếng dài 2 inch vì sẽ rất khó cắt bằng dao làm bếp thông thường. Rửa sạch, sau đó đặt một nồi sâu với nước vào và đun sôi. Nấu trong 20 phút, sau đó vớt ra + rửa sạch và lặp lại (đun sôi lại trong nước). Mục đích là làm cho các miếng đuôi lợn mềm và loại bỏ hầu hết muối đã được ngâm trong đó.', NULL, '2026-05-15 14:49:09', '2026-05-15 14:49:09'),
(2996, 440, 3, 'Đã đến lúc bắt đầu món súp. Cho tất cả mọi thứ vào nồi (trừ bột mì và khoai tây), sau đó đổ nước vào và đặt trên lửa lớn để đun sôi. Khi nước sôi, hớt bỏ váng/bọt ở trên và bỏ đi. Giảm nhiệt đến mức sôi nhẹ và để nấu trong 1 giờ 15 phút.. về cơ bản cho đến khi đậu mềm và bắt đầu tách rời.', NULL, '2026-05-15 14:49:09', '2026-05-15 14:49:09'),
(2997, 440, 4, 'Bây giờ là lúc thêm khoai tây (và Yams, v.v. nếu bạn thêm nó) cũng như nước cốt dừa và tiếp tục nấu trong 15 phút.', NULL, '2026-05-15 14:49:09', '2026-05-15 14:49:09'),
(2998, 440, 5, 'Bây giờ là thời điểm thích hợp để bắt đầu làm loại bột cơ bản cho món bánh bao quay. Trộn bột mì và nước (thêm một chút muối nếu muốn) cho đến khi thu được khối bột mềm/mịn. Để yên trong 5 phút, sau đó múc từng muỗng canh và lăn giữa hai bàn tay để tạo thành hình điếu thuốc.', NULL, '2026-05-15 14:49:09', '2026-05-15 14:49:09'),
(2999, 440, 6, 'Thêm chúng vào nồi, khuấy đều và tiếp tục đun sôi thêm 15 phút nữa.', NULL, '2026-05-15 14:49:09', '2026-05-15 14:49:09'),
(3000, 440, 7, 'Bạn sẽ nhận thấy rằng tôi không thêm muối vào nồi vì lượng muối còn lại từ bím tóc muối sẽ đủ để nêm món ăn này. Tuy nhiên bạn có thể nếm thử và điều chỉnh cho phù hợp. Hãy tóm tắt lại phần thời gian của mọi thứ để bạn không bị nhầm lẫn. Nấu phần đáy súp trong 1 giờ 15 phút hoặc cho đến khi mềm, sau đó thêm khoai tây vào nấu trong 15 phút, sau đó thêm bánh bao vào nấu thêm 15 phút nữa. Hãy nhớ rằng món súp này sẽ đặc lại một chút khi nguội.', NULL, '2026-05-15 14:49:09', '2026-05-15 14:49:09'),
(3001, 440, 8, 'Mặc dù đây không phải là công thức nấu ăn truyền thống của bất kỳ hòn đảo cụ thể nào, nhưng các phiên bản của món súp này (đôi khi được gọi là đậu hầm) có thể được tìm thấy trên khắp vùng Caribe, Châu Mỹ Latinh và Châu Phi. Một bát canh thịnh soạn này chắc chắn sẽ khiến bạn buồn ngủ (có người gọi là mệt mỏi dân tộc). Bạn chắc chắn có thể đông lạnh thức ăn thừa và hâm nóng vào ngày khác.', NULL, '2026-05-15 14:49:09', '2026-05-15 14:49:09'),
(3002, 441, 1, 'Trong lò nướng kiểu Hà Lan hoặc nồi nấu chậm, thêm tất cả gia vị, nước luộc thịt bò và nước cốt chanh. Khuấy đều để hòa quyện..', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3003, 441, 2, 'Thêm thịt bò vào và đảo đều, rưới một ít nước sốt lên trên.', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3004, 441, 3, 'Đậy nắp và nấu ở nhiệt độ thấp trong 8-10 giờ.', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3005, 441, 4, 'Sau khi nấu chín, lấy thịt bò ra và dùng 2 chiếc nĩa để xé nhỏ. Loại bỏ bất kỳ chất béo dư thừa.', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3006, 441, 5, 'Hớt bỏ phần mỡ phía trên phần chất lỏng còn lại.', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3007, 441, 6, 'Trộn thịt bò thái nhỏ vào nước sốt. Giữ ấm cho đến khi bạn sẵn sàng phục vụ.', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3008, 441, 7, 'Tạo lớp bọc bằng cách phết nước sốt tỏi lên bánh pita. Phủ thịt bò lên trên và thêm đồ trang trí theo ý thích của bạn.', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3009, 441, 8, 'Gấp nó theo phong cách burrito.', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3010, 441, 9, 'Làm nóng chảo nướng và nướng bọc.', NULL, '2026-05-15 14:49:10', '2026-05-15 14:49:10'),
(3011, 442, 1, '1. Làm nóng lò ở nhiệt độ 425 độ. Rửa và lau khô tất cả sản phẩm. Cắt khoai tây thành miếng 1/2 inch. Cắt, gọt vỏ và cắt cà rốt theo đường chéo thành từng miếng dày 1/2 inch. Cắt và thái mỏng hành lá, tách lòng trắng khỏi rau xanh; thái nhỏ lòng trắng. Bóc vỏ và băm nhuyễn tỏi.', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3012, 442, 2, '2. Trong một tô vừa, ngâm bánh mì với 2 muỗng canh nước (4 muỗng canh cho 4 phần ăn); chia tay cho đến khi nhão. Khuấy thịt bò, sriracha, lòng trắng hành lá, một nửa số tỏi, muối (chúng tôi sử dụng 3/4 muỗng cà phê muối kosher; 11/2 muỗng cà phê cho 4) và hạt tiêu. Tạo thành hai ổ bánh cao 1 inch (bốn ổ cho 4 ổ). Đặt trên một mặt của một tấm nướng bánh. Đổ cà rốt lên mặt trống của tờ giấy với một chút dầu, muối và hạt tiêu. (Đối với 4 người, trải bánh mì thịt ra toàn bộ tấm và thêm cà rốt vào tấm thứ hai.) Nướng trong 20 phút (sau đó chúng ta sẽ tráng men bánh mì thịt).', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3013, 442, 3, '3. Trong khi đó, đặt khoai tây vào nồi vừa với lượng nước muối vừa đủ ngập 2 inch. Đun sôi và nấu cho đến khi thật', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3014, 442, 4, 'đấu thầu, 12-15 phút. Dự trữ 1/2 chén nước nấu khoai tây, sau đó để ráo nước. Trong khi nấu khoai tây, trong một bát nhỏ, trộn nước tương, bột tỏi, 1/4 cốc sốt cà chua (1/2 cốc cho 4 phần ăn) và 2 thìa cà phê đường (4 thìa cà phê cho 4 phần ăn).', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3015, 442, 5, '4. Sau khi bánh mì thịt và cà rốt đã nướng được 20 phút, hãy lấy ra khỏi lò. Múc một nửa lớp sốt cà chua lên bánh mì thịt (tiết kiệm', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3016, 442, 6, 'phần còn lại để phục vụ); quay trở lại lò nướng cho đến khi cà rốt chín vàng và mềm, bánh mì thịt chín và men dính lại, thêm 4-5 phút nữa.', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3017, 442, 7, '5. Trong khi đó, đun chảy 2 muỗng canh bơ (4 muỗng canh cho 4 phần ăn) trong nồi dùng cho khoai tây trên lửa vừa. Thêm tỏi còn lại và nấu', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3018, 442, 8, 'cho đến khi có mùi thơm, 30 giây. Thêm khoai tây và 1/4 muỗng cà phê wasabi. Nghiền, thêm một ít nước nấu khoai tây dành riêng nếu cần cho đến khi mịn. Nêm muối và hạt tiêu. (Nếu bạn thích ăn cay thì cho thêm wasabi vào nhé!)', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3019, 442, 9, '6. Chia bánh mì thịt, khoai tây nghiền và cà rốt nướng vào các đĩa. Rắc thêm hành lá và dùng kèm với sốt cà chua còn sót lại để chấm.', NULL, '2026-05-15 14:49:11', '2026-05-15 14:49:11'),
(3020, 443, 1, 'Cho hành tây và dầu vào chảo lớn rồi chiên trên lửa khá cao trong 3-4 phút. Thêm tỏi và thịt băm vào xào cho đến khi cả hai đều có màu nâu. Thêm nấm và thảo mộc vào nấu thêm vài phút nữa.', NULL, '2026-05-15 14:49:12', '2026-05-15 14:49:12'),
(3021, 443, 2, 'Khuấy cà chua, thịt bò kho, sốt cà chua hoặc bột nhuyễn, sốt Worcestershire và gia vị. Đun sôi, sau đó giảm nhiệt, đậy nắp và đun nhỏ lửa, thỉnh thoảng khuấy trong 30 phút.', NULL, '2026-05-15 14:49:12', '2026-05-15 14:49:12'),
(3022, 443, 3, 'Trong khi đó, nấu mì spaghetti trong một chảo lớn nước sôi có muối, theo hướng dẫn trên bao bì. Xả thật sạch, cho nước nóng chảy qua, cho lại vào chảo và thêm một chút dầu ô liu, nếu thích thì cho nước sốt thịt vào khuấy đều. Bày ra bát nóng và dùng phô mai Parmesan tròn để rắc lên trên.', NULL, '2026-05-15 14:49:12', '2026-05-15 14:49:12'),
(3024, 444, 1, 'Trộn tất cả các nguyên liệu làm nước sốt vào tô với 1 thìa canh nước cho đến khi đường tan.', NULL, '2026-05-15 14:49:14', '2026-05-16 12:35:34'),
(3026, 444, 2, 'Luộc mì theo hướng dẫn trên bao bì, sau đó ngâm vào tô nước lạnh cho mì nguội hoàn toàn. Để ráo mì, sau đó cho cà rốt, bắp cải, hành lá và nước sốt vào trộn đều.', NULL, '2026-05-15 14:49:14', '2026-05-16 12:35:34'),
(3028, 444, 3, 'Đun nóng dầu trong chảo trên lửa cao. Nêm bít tết, sau đó nấu theo ý thích của bạn; 2-3 phút mỗi mặt đối với loại vừa hiếm. Để yên trong 5 phút rồi cắt lát. Chia các lát salad và bít tết vào giữa các bát và rắc lên một ít rau mùi để thưởng thức.', NULL, '2026-05-15 14:49:14', '2026-05-16 12:35:34'),
(3029, 445, 1, 'Làm nóng lò ở 220C/425F/Gas 7', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3030, 445, 2, 'Đun nóng dầu thực vật trong chảo lớn, cho thịt bò vào chiên vàng đều. (Bạn có thể cần phải thực hiện việc này theo từng đợt.) Đặt sang một bên, sau đó làm chín thận ở cả hai mặt trong cùng một chảo. Thêm hành tây và nấu trong 3-4 phút.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3031, 445, 3, 'Cho thịt bò vào chảo, rắc bột mì lên rồi phủ thịt và hành tây lên', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3032, 445, 4, 'Thêm nước kho vào chảo, khuấy đều và đun sôi.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3033, 445, 5, 'Giảm nhiệt và đun nhỏ lửa trong 1 tiếng rưỡi mà không cần đậy nắp. Nếu chất lỏng bay hơi quá nhiều, hãy đổ thêm nước kho.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3034, 445, 6, 'Hủy bỏ khỏi nhiệt. Thêm muối, hạt tiêu và sốt Worcestershire và để nguội hoàn toàn. Đặt hỗn hợp thịt đã nấu chín vào đĩa bánh.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3035, 445, 7, 'Cán miếng bánh dày 5mm/¼in và lớn hơn 5cm/2in so với đĩa bạn đang dùng.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3036, 445, 8, 'Dùng cây cán bột, nhấc bánh lên và đặt lên trên đĩa bánh. Cắt và uốn các cạnh bằng ngón tay cái của bạn.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3037, 445, 9, 'Quét hỗn hợp trứng đã đánh lên bề mặt và nướng trong 30-40 phút cho đến khi có màu nâu vàng và phồng lên.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3038, 445, 10, 'Ăn kèm với kem nghiền và rau hấp để thấm nước sốt.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3039, 446, 1, 'Đun nóng dầu trong chảo 12 inch trên lửa vừa cao. Nêm bít tết với muối và hạt tiêu rồi cho vào chảo; nấu, lật một lần cho đến khi chín vàng cả hai mặt và chín đến độ chín mong muốn, khoảng 4 đến 5 phút đối với thịt vừa tái. Chuyển bít tết ra đĩa và đặt sang một bên.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3040, 446, 2, 'Cho chảo lên lửa cao và thêm nước kho vào; nấu cho đến khi giảm còn 1⁄2 cốc, khoảng 10 phút. Đổ vào tô, đặt sang một bên. Đun nóng chảo và thêm bơ; thêm tỏi và hẹ vào, nấu, khuấy đều cho đến khi mềm, khoảng 2 phút. Thêm nấm vào, nấu, khuấy đều cho đến khi nấm tiết ra chất lỏng và bay hơi và nấm bắt đầu chuyển sang màu nâu, khoảng 2 phút. Thêm rượu cognac và châm diêm vào flambée; nấu cho đến khi ngọn lửa tắt. Khuấy nước kho dự trữ, kem, Dijon, Worcestershire và nước sốt nóng, sau đó cho bít tết vào chảo; nấu, cho nước sốt vào, cho đến khi ấm và nước sốt đặc lại, khoảng 4 phút. Chuyển bít tết ra đĩa và trộn mùi tây và hẹ vào nước sốt; rưới nước sốt lên bít tết để phục vụ.', NULL, '2026-05-15 14:49:16', '2026-05-15 14:49:16'),
(3041, 447, 1, 'BƯỚC 1 – Ướp THỊT BÒ', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3042, 447, 2, 'Cho thịt bò, muối, dầu mè, tiêu trắng, lòng trắng trứng, 2 thìa tinh bột ngô và 1 thìa dầu vào tô.', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3043, 447, 3, 'BƯỚC 2 - Xào', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3044, 447, 4, 'Đầu tiên, nấu thịt bò bằng cách thêm 2 muỗng canh dầu cho đến khi thịt bò có màu vàng nâu.', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3045, 447, 5, 'Đặt thịt bò sang một bên', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3046, 447, 6, 'Trong chảo, thêm 1 muỗng canh dầu, gừng băm, tỏi băm và xào trong vài giây.', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3047, 447, 7, 'Tiếp theo cho tất cả các loại rau vào rồi thêm rượu nấu sherry và 1 cốc nước.', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3048, 447, 8, 'Để làm nước sốt, thêm dầu hào, sốt ớt cay và đường.', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3049, 447, 9, 'thêm thịt bò nấu chín và 1 thìa nước tương', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3050, 447, 10, 'Để làm đặc nước sốt, trộn 1 thìa bột ngô và 2 thìa nước vào tô rồi từ từ thêm vào món xào cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:49:17', '2026-05-15 14:49:17'),
(3052, 448, 1, 'Đun nóng chảo hoặc chảo lớn cho đến khi bốc khói. Đổ dầu vào và đảo quanh chảo, sau đó cho các dải thịt bò và ớt vào. Nấu, khuấy liên tục cho đến khi thịt có màu nâu nhạt, khoảng 3 phút thì rưới dầu hào lên trên. Nấu cho đến khi nóng và nước sốt thấm vào thịt. khuấy lá húng quế và dùng với cơm trắng.', NULL, '2026-05-15 14:49:19', '2026-05-16 12:35:34'),
(3053, 449, 1, 'Thịt rửa sạch nếu có gân và cắt thành từng miếng nhỏ hơn, kích thước 3 × 3 cm. Ướp thịt với mù tạt và gia vị rồi để trong tủ lạnh khoảng một giờ', NULL, '2026-05-15 14:49:21', '2026-05-15 14:49:21'),
(3054, 449, 2, 'Đun nóng một thìa mỡ lợn hoặc dầu thực vật trong nồi rồi chiên thịt các mặt cho đến khi chín vàng. Thịt chín thì múc ra đĩa rồi cho thêm 1 thìa mỡ vào nồi', NULL, '2026-05-15 14:49:21', '2026-05-15 14:49:21'),
(3055, 449, 3, 'Cắt hành thật nhuyễn, gọt vỏ cà rốt và dùng dụng cụ bào cắt nhỏ. Nấu hành tây và cà rốt trên lửa nhỏ trong 15 phút. Bạn có thể muối rau một chút để rau mềm nhanh hơn', NULL, '2026-05-15 14:49:21', '2026-05-15 14:49:21'),
(3056, 449, 4, 'Khi rau đã chín vàng và hơi nhão, hãy cho thịt, lá nguyệt quế và tỏi vào. Đổ rượu vào và đun nhỏ lửa trong vòng 10 - 15 phút để rượu bay hơi. Bây giờ là thời điểm thích hợp để thêm 2/3 lượng chất lỏng', NULL, '2026-05-15 14:49:21', '2026-05-15 14:49:21'),
(3057, 449, 5, 'Đậy nắp nồi và nấu trên lửa nhỏ trong một giờ, thỉnh thoảng khuấy đều. Sau giờ đầu tiên, đổ phần nước hoặc kho còn lại lên và nấu thêm 30-45 phút nữa.', NULL, '2026-05-15 14:49:21', '2026-05-15 14:49:21'),
(3058, 449, 6, 'Để món hầm nguội một chút và dùng kèm với rắc rau mùi tây cắt nhỏ và vài lát ớt tươi nếu bạn muốn thêm gia vị một chút.', NULL, '2026-05-15 14:49:21', '2026-05-15 14:49:21'),
(3059, 449, 7, 'Cắt một ít bánh mì tươi, nêm salad và đơn giản là thưởng thức những hương vị tuyệt vời này', NULL, '2026-05-15 14:49:21', '2026-05-15 14:49:21'),
(3061, 450, 1, 'Rây bột vào tô lớn, tạo một cái giếng ở giữa rồi rắc men vào. Đổ 125ml nước lên men, sau đó vẩy bột mì lên trên để tạo lớp. Đậy nắp và để ở nơi ấm áp trong 15 phút cho đến khi các vết nứt xuất hiện trên bề mặt của lớp đó.', NULL, '2026-05-15 14:49:23', '2026-05-16 12:35:34'),
(3063, 450, 2, 'Dùng tay trộn thêm 250ml nước cùng 1 thìa muối vào rồi nhào bột khoảng 10 phút cho đến khi bột dẻo và không còn dính tay. Thêm một chút bột mì nếu bạn cần. Đậy nắp và để bột nở lại ở nơi ấm áp trong 30 phút cho đến khi nở gấp đôi.', NULL, '2026-05-15 14:49:23', '2026-05-16 12:35:34'),
(3065, 450, 3, 'Làm nóng lò ở mức cao nhất có thể (khoảng 240C/220C quạt/gas 9) và rắc mỏng bột ngô lên một hoặc hai khay nướng.', NULL, '2026-05-15 14:49:23', '2026-05-16 12:35:34'),
(3067, 450, 4, 'Đổ nước sôi từ ấm lên cà chua, để yên một lúc rồi để ráo nước và lột vỏ. Cà chua cắt làm đôi, cắt bỏ cuống, bỏ hạt và bỏ đi, sau đó băm nhỏ lấy thịt.', NULL, '2026-05-15 14:49:23', '2026-05-16 12:35:34'),
(3069, 450, 5, 'Ớt bổ đôi theo chiều dọc, cắt bỏ cuống, hạt và lớp màng trắng bên trong rồi rửa sạch. Cắt theo chiều dọc thành dải mịn, sau đó cắt ngang thành xúc xắc mịn.', NULL, '2026-05-15 14:49:23', '2026-05-16 12:35:34'),
(3071, 450, 6, 'Cho cà chua, ớt, hành lá, rau mùi tây thái nhỏ, thịt bò bằm, gia vị, 1 thìa muối và ½ thìa tiêu đen mới xay vào tô rồi trộn đều.', NULL, '2026-05-15 14:49:23', '2026-05-16 12:35:34'),
(3073, 450, 7, 'Lấy bột và nhào thật nhanh, sau đó chia thành bốn phần và nặn từng phần thành một quả bóng. Lăn từng viên thành từng hình tròn mỏng, đặt lên khay nướng đã chuẩn bị sẵn. Trải một lớp mỏng hỗn hợp thịt.', NULL, '2026-05-15 14:49:23', '2026-05-16 12:35:34'),
(3075, 450, 8, 'Nướng từng chiếc bánh mỳ dẹt trong vòng 10-15 phút cho đến khi các cạnh bắt đầu sẫm màu. Sau khi lấy ra khỏi lò, rắc lahmacun với rau mùi tây cắt nhỏ và hành tây thái lát, sau đó vắt thêm vài giọt nước cốt chanh. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:49:23', '2026-05-16 12:35:34'),
(3076, 451, 1, 'Thêm thành phần:', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3077, 451, 2, '12 chén rau trộn xắt nhỏ', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3078, 451, 3, '1 chén nấm tươi xắt nhỏ', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3079, 451, 4, '1 chén hành ngọc trai', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3080, 451, 5, 'ĐỨNG ĐẦU:', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3081, 451, 6, 'Làm nóng lò ở nhiệt độ 450°. Nướng khoai tây trên khay nướng có lót giấy bạc cho đến khi mềm, khoảng 45 phút. Để nguội một chút rồi bóc vỏ. Nhấn khoai tây qua máy xay, máy xay thực phẩm hoặc rây vào tô lớn. Thêm bơ; khuấy cho đến khi trộn đều. Khuấy sữa. Nêm muối cho vừa ăn.', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3082, 451, 7, 'ĐIỀN:', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3083, 451, 8, 'Ngâm porcini khô trong 3 cốc nước nóng; đặt sang một bên. Kết hợp đậu lăng, 1 tép tỏi, 1 muỗng cà phê. muối và 4 cốc nước vào nồi vừa. Đun sôi; giảm nhiệt và đun nhỏ lửa, thỉnh thoảng khuấy cho đến khi đậu lăng mềm nhưng không nhão, trong 15–20 phút. Xả đậu lăng và loại bỏ tỏi.', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3084, 451, 9, 'Đun nóng 3 muỗng canh. dầu trong một nồi nặng lớn trên lửa vừa. Thêm hành tây và nấu, thỉnh thoảng khuấy cho đến khi mềm, khoảng 12 phút. Thêm tỏi băm nhỏ và nấu trong 1 phút. Khuấy bột cà chua. Nấu, khuấy liên tục cho đến khi bột cà chua có màu caramen, 2–3 phút.', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3085, 451, 10, 'Thêm lá nguyệt quế và rượu; khuấy đều, cạo sạch những phần màu nâu. Khuấy porcini, từ từ đổ chất lỏng ngâm porcini vào chảo nhưng để lại cặn. Đun nhỏ lửa và nấu cho đến khi chất lỏng giảm đi một nửa, khoảng 10 phút. Khuấy nước dùng và nấu, thỉnh thoảng khuấy cho đến khi giảm một nửa, khoảng 45 phút.', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3086, 451, 11, 'Lọc hỗn hợp vào nồi lớn và đun sôi; loại bỏ chất rắn trong bộ lọc. Khuấy bột ngô và 2 muỗng canh. nước vào một cái bát nhỏ để hòa tan. Thêm hỗn hợp bột ngô; đun nhỏ lửa cho đến khi đặc lại, khoảng 5 phút. Đánh đều trong miso. Nêm nước sốt với muối và hạt tiêu. Đặt sang một bên.', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3087, 451, 12, 'Làm nóng lò ở nhiệt độ 450°. Trộn rau và hành tây với 2 muỗng canh còn lại. dầu, 5 tép tỏi và nhánh hương thảo trong tô lớn; nêm muối và hạt tiêu. Chia giữa 2 tấm nướng có viền. Nướng, khuấy một lần cho đến khi mềm, khoảng 20–25 phút. Chuyển tép tỏi vào một cái bát nhỏ; nghiền nhuyễn bằng nĩa và khuấy thành nước sốt. Bỏ cây hương thảo. LÀM TRƯỚC: Đậu lăng, nước sốt và rau có thể được làm trước 1 ngày. Che riêng; sự ớn lạnh.', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3088, 451, 13, 'Sắp xếp đậu lăng thành một lớp chẵn trong 3-qt. món nướng; đặt đĩa lên khay nướng có viền lót giấy bạc. Trộn rau củ nướng với nấm tươi và rau thơm cắt nhỏ; lớp trên cùng của đậu lăng. Đổ nước sốt lên rau. Đổ đều hỗn hợp khoai tây lên trên.', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3089, 451, 14, 'Nướng cho đến khi chín vàng và sủi bọt, khoảng 30 phút. Hãy đứng trong 15 phút trước khi phục vụ.', NULL, '2026-05-15 14:49:25', '2026-05-15 14:49:25'),
(3090, 452, 1, 'Cho phần thân sau, 1 củ hành tây nhỏ cắt đôi, ớt chuông cắt đôi, 4 tép tỏi nguyên củ, lá tỏi tây màu xanh đậm rồi cho vào nồi kho lớn. Nấu khoảng 45-60 phút cho đến khi thịt mềm. LƯU Ý: thịt có thể mất nhiều thời gian hơn một chút để mềm; không sao cả, chỉ cần tăng thêm thời gian nấu nếu cần thiết.', NULL, '2026-05-15 14:49:26', '2026-05-15 14:49:26'),
(3091, 452, 2, 'Khi thịt mềm, vớt ra những miếng rau và xương lớn. Vứt bỏ.', NULL, '2026-05-15 14:49:26', '2026-05-15 14:49:26'),
(3092, 452, 3, 'Thêm hành tây thái hạt lựu, 2 củ tỏi băm, ớt ngọt nhỏ, tỏi tây thái lát (phần xanh nhạt), hành lá, yucca và ngô; Trộn và đun nhỏ lửa trên lửa vừa trong 5-8 phút cho đến khi yucca bắt đầu mềm. LƯU Ý: yuca có thể mất nhiều thời gian hơn để bắt đầu mềm; không sao cả, chỉ cần tăng thêm thời gian nấu nếu cần thiết.', NULL, '2026-05-15 14:49:26', '2026-05-15 14:49:26'),
(3093, 452, 4, 'Thêm yautia, khoai lang trắng và bí đỏ. Trộn để kết hợp. Đun nhỏ lửa ở lửa vừa trong 5 – 6 phút cho đến khi tất cả các loại rau củ đều mềm. LƯU Ý: Đừng nấu quá nhiều, nếu không chúng sẽ bị nát.', NULL, '2026-05-15 14:49:26', '2026-05-15 14:49:26'),
(3094, 452, 5, 'Hương vị và thêm muối theo khẩu vị của bạn, nếu cần thiết. Thêm ngò và 2 tép tỏi băm còn lại vào. Trộn và để sôi thêm 2 phút nữa.', NULL, '2026-05-15 14:49:26', '2026-05-15 14:49:26'),
(3095, 452, 6, 'Ăn nóng trong tô súp lớn, chia đều thịt và rau. Thêm một ít nước cốt chanh và/hoặc nước sốt nóng nếu muốn. Ăn kèm với arepas và casabe (bánh mì sắn).', NULL, '2026-05-15 14:49:26', '2026-05-15 14:49:26'),
(3096, 453, 1, 'Ướp thịt bò với muối, tiêu và tỏi băm', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3097, 453, 2, 'Cắt 1 củ hành tây thành 4 miếng lớn', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3098, 453, 3, 'Cho vào nồi áp suất thịt bò cùng 4 củ hành tây và nước luộc', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3099, 453, 4, 'Nấu áp suất trong 20 phút', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3100, 453, 5, 'Xả áp suất và mở nắp', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3101, 453, 6, 'Lấy thịt bò ra và TIẾT KIỆM 2 cốc nước dùng vào hộp đựng khác', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3102, 453, 7, 'Dùng 2 nĩa, xé thịt bò. Thịt bò phải đủ mềm để dễ dàng như vậy. Nếu chưa thì nấu thêm 10 phút nữa', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3103, 453, 8, 'Nhấn nút xào của nồi Instant pot. Thêm dầu ô liu', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3104, 453, 9, 'Khi máy phát ra tiếng bíp, cho hành tây, hạt tiêu và cà chua thái lát vào. Nấu cho đến khi mềm', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3105, 453, 10, 'Thêm thịt bò thái nhỏ vào nồi và trộn đều', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3106, 453, 11, 'Đổ 1 1/2 cốc nước dùng đã để sẵn, sốt Worcestershire, bột cà chua, sốt cà chua và thì là vào. Trộn', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3107, 453, 12, 'Nếu nước sốt có vẻ khô, hãy thêm một chút nước kho', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3108, 453, 13, 'Nêm muối và hạt tiêu', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3109, 453, 14, 'Phục vụ!', NULL, '2026-05-15 14:49:27', '2026-05-15 14:49:27'),
(3110, 454, 1, 'BƯỚC 1', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3111, 454, 2, 'Đặt ức gà vào giữa hai miếng giấy nến rồi dùng cây lăn cán nhẹ cho đến khi dày khoảng 1cm. Cắt mỗi ức gà thành hai miếng đều nhau.', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3112, 454, 3, 'BƯỚC 2', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3113, 454, 4, 'Nếu bạn đang sử dụng chảo rán, hãy làm nóng hai chảo rán trên lửa vừa cao, trong đó một chảo có chứa dầu. Chiên gà trong chảo dầu khoảng 3-4 phút mỗi mặt cho đến khi gà chín. Nêm gà, giảm lửa, rưới tương ớt và nửa nước cốt chanh vào, nấu thêm 1-2 phút cho đến khi nước sốt giảm bớt. Lấy gà ra khỏi lửa.', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3114, 454, 5, 'BƯỚC 3', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3115, 454, 6, 'Nếu bạn đang sử dụng nồi chiên không dầu, hãy làm nóng trước ở nhiệt độ 180C trong 4 phút. Cho gà vào nồi chiên không khí và nấu trong 12 phút. Rưới nước sốt ớt và nửa quả chanh lên rồi nấu thêm 1-2 phút cho đến khi gà chín và bớt nước sốt. Lấy gà ra và giữ ấm.', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3116, 454, 7, 'BƯỚC 4', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3117, 454, 8, 'Trong khi nướng gà, nướng bánh trong chảo rán khô trong 30 giây. Chuyển chúng vào đĩa. Nếu bạn sử dụng nồi chiên không dầu, hãy cho bánh vào nồi chiên không khí trong 1-2 phút cho đến khi bánh ấm. Tăng nhiệt độ nồi chiên không khí lên 200C. Thêm halloumi vào giỏ nồi chiên không dầu và nấu trong 10 phút, lật nửa chừng cho đến khi vàng. Trộn bắp cải với mayo và nước cốt chanh còn lại.', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3118, 454, 9, 'BƯỚC 5', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3119, 454, 10, 'Múc hummus (hoặc nhúng theo sở thích của bạn) vào bánh mì nướng, sau đó phủ rocket, gà ớt, halloumi và ớt lên trên. Rắc thêm một ít tương ớt, rưới lên bắp cải, nêm tiêu đen và đậy nắp bánh mì lên trên. Ăn kèm với bất kỳ bắp cải bổ sung nào ở bên cạnh hoặc salad xanh.', NULL, '2026-05-15 14:49:29', '2026-05-15 14:49:29'),
(3120, 455, 1, 'Vắt chanh lên gà và chà xát đều. Xả hết nước cốt chanh dư thừa.', NULL, '2026-05-15 14:49:32', '2026-05-15 14:49:32'),
(3121, 455, 2, 'Kết hợp cà chua, hành lá, hành tây, tỏi, hạt tiêu, húng tây, ớt và nước tương vào tô lớn cùng với các miếng thịt gà. Che và ướp ít nhất một giờ.', NULL, '2026-05-15 14:49:32', '2026-05-15 14:49:32'),
(3122, 455, 3, 'Đun nóng dầu trong nồi Hà Lan hoặc chảo lớn. Lắc bỏ gia vị khi lấy từng miếng thịt gà ra khỏi nước xốt. Dự trữ nước xốt cho nước sốt.', NULL, '2026-05-15 14:49:32', '2026-05-15 14:49:32'),
(3123, 455, 4, 'Chiên từng miếng gà một vài miếng trong dầu thật nóng. Đặt các miếng thịt gà đã chiên vàng lên đĩa để nghỉ trong khi chiên các miếng còn lại.', NULL, '2026-05-15 14:49:32', '2026-05-15 14:49:32'),
(3124, 455, 5, 'Xả bớt dầu thừa và cho gà trở lại chảo. Đổ nước xốt lên gà và thêm cà rốt. Khuấy và nấu trên lửa vừa trong 10 phút.', NULL, '2026-05-15 14:49:32', '2026-05-15 14:49:32');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(3125, 455, 6, 'Trộn bột mì và nước cốt dừa rồi cho vào hầm, khuấy liên tục. Giảm nhiệt xuống mức tối thiểu và nấu thêm 20 phút nữa hoặc cho đến khi mềm.', NULL, '2026-05-15 14:49:32', '2026-05-15 14:49:32'),
(3127, 456, 1, 'Đun nóng dầu trong một đĩa thịt hầm lớn chống cháy và làm chín các miếng thịt gà ở tất cả các mặt – bạn có thể phải làm việc này theo từng mẻ. Lấy ra khỏi đĩa và đặt sang một bên.', NULL, '2026-05-15 14:49:35', '2026-05-16 12:35:34'),
(3129, 456, 2, 'Giảm nhiệt, thêm hành tây và hạt tiêu vào nấu nhẹ trong 10 phút cho đến khi mềm. Thêm tỏi và chorizo ​​vào, nấu thêm 2 phút nữa cho đến khi chorizo ​​tiết ra một ít dầu vào đĩa. Khuấy nhuyễn cà chua và nấu thêm 1 phút nữa.', NULL, '2026-05-15 14:49:35', '2026-05-16 12:35:34'),
(3131, 456, 3, 'Cho các miếng thịt gà vào đĩa cùng với húng tây, rượu trắng và nước kho. Đun sôi chất lỏng, đậy nắp kín đĩa và giảm nhiệt. Nấu trong 30 phút.', NULL, '2026-05-15 14:49:35', '2026-05-16 12:35:34'),
(3133, 456, 4, 'Đổ cơm vào và khuấy đều mọi thứ lại với nhau. Đậy nắp, đặt ở lửa nhỏ và nấu thêm 15 phút nữa hoặc cho đến khi cơm chín và ngấm hầu hết nước nấu. Tắt bếp và để đĩa trong 10 phút để hấp thụ chất lỏng còn lại. Nêm nếm vừa ăn và rải với rau mùi tây để phục vụ.', NULL, '2026-05-15 14:49:35', '2026-05-16 12:35:34'),
(3134, 457, 1, 'Làm nóng lò ở nhiệt độ 200C/180C quạt/gas 6. Cho bơ vào nồi cỡ vừa và đặt trên lửa vừa. Thêm hành tây và để nấu trong 5 phút, thỉnh thoảng khuấy. Cho nấm vào nồi cùng hành tây.', NULL, '2026-05-15 14:49:36', '2026-05-15 14:49:36'),
(3135, 457, 2, 'Khi hành tây và nấm gần chín, cho bột mì vào khuấy đều - điều này sẽ tạo thành một hỗn hợp sệt gọi là roux. Nếu bạn đang sử dụng viên nước kho, hãy nghiền khối đó vào roux và khuấy đều. Đặt roux trên lửa nhỏ và khuấy liên tục trong 2 phút - điều này sẽ làm chín bột và ngăn nước sốt có vị bột.', NULL, '2026-05-15 14:49:36', '2026-05-15 14:49:36'),
(3136, 457, 3, 'Lấy roux ra khỏi lửa. Từ từ thêm nước kho tươi nếu sử dụng hoặc đổ vào 500ml nước nếu bạn dùng nước kho, khuấy liên tục. Khi tất cả chất lỏng đã được thêm vào, nêm hạt tiêu, một chút hạt nhục đậu khấu và bột mù tạt. Đặt chảo trở lại lửa vừa và từ từ đun sôi, khuấy đều. Khi nước sốt đã đặc lại, đặt ở nhiệt độ rất thấp. Thêm thịt gà và rau đã nấu chín vào nước sốt và khuấy đều. Bôi một ít bơ lên ​​đĩa nướng cỡ vừa rồi đổ nhân gà và nấm vào.', NULL, '2026-05-15 14:49:36', '2026-05-15 14:49:36'),
(3137, 457, 4, 'Cẩn thận đặt khoai tây lên trên lớp nhân nóng, hơi chồng lên nhau, gần giống như mặt bánh nướng.', NULL, '2026-05-15 14:49:36', '2026-05-15 14:49:36'),
(3138, 457, 5, 'Quét khoai tây với một ít bơ tan chảy và nướng trong lò khoảng 35 phút. Lẩu đã sẵn sàng khi khoai tây đã chín và có màu vàng nâu.', NULL, '2026-05-15 14:49:36', '2026-05-15 14:49:36'),
(3139, 458, 1, 'Đun nóng 1 thìa bơ và 2 thìa dầu ô liu trong chảo lớn trên lửa vừa cao', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3140, 458, 2, 'Nêm cả hai mặt của mỗi ức gà với muối và một chút hạt tiêu', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3141, 458, 3, 'Cho gà vào chảo và nấu khoảng 5-7 phút mỗi mặt hoặc cho đến khi chín đều', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3142, 458, 4, 'Trong khi luộc gà, hãy đun sôi một nồi nước lớn', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3143, 458, 5, 'Đổ nước sôi với một ít muối kosher', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3144, 458, 6, 'Thêm mì ống và khuấy đều', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3145, 458, 7, 'Nấu, thỉnh thoảng khuấy cho đến khi chín, khoảng 12 phút', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3146, 458, 8, 'Dự trữ 1/2 cốc nước mì ống trước khi xả mì ống', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3147, 458, 9, 'Lấy gà ra khỏi chảo và chuyển sang thớt; cho phép nó nghỉ ngơi', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3148, 458, 10, 'Giảm lửa xuống mức trung bình và cho 1 thìa bơ và dầu ô liu còn lại vào chảo bạn dùng để nấu gà', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3149, 458, 11, 'Cho rau (trừ tỏi) và ớt đỏ vào chảo rồi đảo đều cho dầu và bơ phủ đều (không nêm muối cho đến khi rau chín vàng)', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3150, 458, 12, 'Nấu, khuấy thường xuyên cho đến khi rau mềm, khoảng 5 phút', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3151, 458, 13, 'Thêm tỏi và một chút muối và hạt tiêu vào chảo và nấu trong 1 phút', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3152, 458, 14, 'Khử men chảo bằng rượu trắng', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3153, 458, 15, 'Tiếp tục nấu cho đến khi rượu cạn một nửa, khoảng 3 phút', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3154, 458, 16, 'Khuấy sữa, kem béo và nước mì ống dành riêng', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3155, 458, 17, 'Đun sôi hỗn hợp nhẹ nhàng và để nhỏ lửa và giảm trong 2-3 phút', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3156, 458, 18, 'Tắt lửa và thêm phô mai Parmesan và mì ống nấu chín', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3157, 458, 19, 'Nêm muối và hạt tiêu cho vừa ăn', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3158, 458, 20, 'Trang trí với phô mai Parmesan và rau mùi tây cắt nhỏ nếu muốn', NULL, '2026-05-15 14:49:37', '2026-05-15 14:49:37'),
(3159, 459, 1, 'Làm nóng lò ở 180°C/Mốc gas 4. Chuẩn bị sẵn các miếng thịt gà để nấu. Đun nóng bơ và 3 muỗng canh dầu ô liu trong nồi chống cháy hoặc chảo rán lớn. Chiên từng miếng gà thành từng mẻ ở cả hai mặt, nêm muối và tiêu khi ăn. Đừng dồn chảo - chiên gà theo từng mẻ nhỏ, vớt từng miếng ra giấy ăn khi đã xong.', NULL, '2026-05-15 14:49:38', '2026-05-15 14:49:38'),
(3160, 459, 2, 'Thêm một ít dầu ô liu vào nồi và xào hành tây trên lửa vừa trong 10 phút, khuấy thường xuyên cho đến khi mềm nhưng không chuyển sang màu nâu. Thêm phần dầu còn lại, sau đó là ớt và nấu thêm 5 phút nữa.', NULL, '2026-05-15 14:49:38', '2026-05-15 14:49:38'),
(3161, 459, 3, 'Thêm chorizo, cà chua phơi nắng và tỏi vào nấu trong 2-3 phút. Thêm gạo vào, khuấy đều để đảm bảo cơm được ngấm đều trong dầu. Khuấy bột cà chua, ớt bột, lá nguyệt quế và húng tây cắt nhỏ. Đổ nước kho và rượu vào. Khi chất lỏng bắt đầu nổi bong bóng, hãy giảm nhiệt xuống mức sôi nhẹ. Nhấn cơm xuống nước nếu cơm chưa ngập rồi đặt gà lên trên. Thêm chanh và ô liu xung quanh gà.', NULL, '2026-05-15 14:49:38', '2026-05-15 14:49:38'),
(3162, 459, 4, 'Đậy nắp và nấu trong lò trong 50 phút. Cơm phải chín nhưng vẫn còn vết cắn, thịt gà phải có nước chảy trong khi dùng dao đâm vào phần dày nhất. Nếu chưa, hãy nấu thêm 5 phút nữa và kiểm tra lại.', NULL, '2026-05-15 14:49:38', '2026-05-15 14:49:38'),
(3163, 460, 1, 'BƯỚC 1 – Ướp GÀ', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3164, 460, 2, 'Cho thịt gà, muối, tiêu trắng, nước gừng vào tô rồi trộn đều.', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3165, 460, 3, 'Đặt gà sang một bên.', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3166, 460, 4, 'BƯỚC 2 – RỬA GẠO TRẮNG', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3167, 460, 5, 'Vo gạo trong tô hoặc nồi kim loại vài lần rồi để ráo nước.', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3168, 460, 6, 'BƯỚC 2 - Luộc gạo trắng', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3169, 460, 7, 'Tiếp theo cho 8 cốc nước vào rồi đặt bếp ở lửa lớn cho đến khi sôi. Khi cháo bắt đầu sôi, đặt bếp ở lửa nhỏ rồi khuấy đều 8-10 phút một lần trong khoảng 20-25 phút.', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3170, 460, 8, 'Sau 25 phút, điều này là tùy chọn nhưng bạn có thể thêm một chút nước để nấu cháo cho bớt đặc hoặc tùy theo sở thích của bạn.', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3171, 460, 9, 'Tiếp theo cho thịt gà đã ướp vào nồi cháo rồi để lửa nhỏ đun thêm 10 phút nữa.', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3172, 460, 10, 'Sau 10 phút thêm hành lá, gừng thái lát, 1 nhúm muối, 1 nhúm tiêu trắng vào đảo đều trong 10 giây.', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3173, 460, 11, 'Đổ cháo vào tô', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3174, 460, 12, 'Tùy chọn: thêm rau mùi lên trên cháo.', NULL, '2026-05-15 14:49:39', '2026-05-15 14:49:39'),
(3175, 461, 1, 'Đun nóng dầu ô liu trong chảo lớn và xào hành tây trong 1-2 phút cho đến khi mềm. Thêm thịt gà và chiên trong 7-10 phút cho đến khi chín và hành tây chuyển sang màu vàng. Bào gừng, khuấy qua sợi harissa để phủ đều mọi thứ và nấu thêm 1 phút nữa.', NULL, '2026-05-15 14:49:40', '2026-05-15 14:49:40'),
(3176, 461, 2, 'Cho mơ, đậu xanh và couscous vào, sau đó rưới nước kho lên và khuấy đều một lần. Đậy nắp hoặc đậy kín chảo bằng giấy bạc và để khoảng 5 phút cho đến khi couscous ngấm hết nước và mềm. Dùng nĩa xới đều món couscous và rắc lên rau mùi để thưởng thức. Ăn kèm thêm harissa nếu bạn thích.', NULL, '2026-05-15 14:49:40', '2026-05-15 14:49:40'),
(3177, 462, 1, 'Cắt mỗi ức gà làm khoảng 3 miếng để chín nhanh hơn rồi cho vào nồi nhỏ. Đổ nước sốt Enchilada lên trên và nấu ở lửa vừa đến thấp cho đến khi gà chín, khoảng 20 phút. Không cần nước, gà sẽ được nấu với sốt Enchilada. Nhớ thỉnh thoảng khuấy đều để không bị dính đáy.', NULL, '2026-05-15 14:49:41', '2026-05-15 14:49:41'),
(3178, 462, 2, 'Lấy gà ra khỏi nồi và xé nhỏ bằng hai nĩa.', NULL, '2026-05-15 14:49:41', '2026-05-15 14:49:41'),
(3179, 462, 3, 'Làm nóng lò ở nhiệt độ 375 F.', NULL, '2026-05-15 14:49:41', '2026-05-15 14:49:41'),
(3180, 462, 4, 'Bắt đầu xếp lớp thịt hầm. Bắt đầu với khoảng ¼ cốc nước sốt Enchilada còn sót lại trên đáy đĩa nướng. Tôi dùng một đĩa nướng dài hơn để có thể đặt 2 chiếc bánh ngô ngang nhau. Đặt 2 chiếc bánh ngô ở dưới cùng, đặt ⅓ thịt gà và ⅓ phần nước sốt còn lại lên trên. Rắc ⅓ phô mai và lặp lại bắt đầu với 2 chiếc bánh ngô nữa, sau đó là thịt gà, nước sốt, phô mai. Lặp lại với lớp cuối cùng với các nguyên liệu còn lại, bánh ngô, thịt gà, nước sốt và phô mai.', NULL, '2026-05-15 14:49:41', '2026-05-15 14:49:41'),
(3181, 462, 5, 'Nướng trong 20 đến 30 phút không đậy nắp, cho đến khi sủi bọt và phô mai tan chảy và bắt đầu có màu nâu ở trên.', NULL, '2026-05-15 14:49:41', '2026-05-15 14:49:41'),
(3182, 462, 6, 'Phục vụ ấm áp.', NULL, '2026-05-15 14:49:41', '2026-05-15 14:49:41'),
(3183, 463, 1, 'Chiên hành, ớt và tỏi trong dầu ô liu cho đến khi trong mờ đẹp mắt. Tạo một cái giếng trong rau và thêm thịt gà của bạn vào. Thêm gia vị và muối của bạn. Cho phép tô màu một chút.', NULL, '2026-05-15 14:49:42', '2026-05-15 14:49:42'),
(3184, 463, 2, 'Thêm kem, nước kho và mì ống của bạn.', NULL, '2026-05-15 14:49:42', '2026-05-15 14:49:42'),
(3185, 463, 3, 'Nấu ở mức thấp trong 20 phút. Thêm phô mai của bạn, khuấy đều để kết hợp.', NULL, '2026-05-15 14:49:42', '2026-05-15 14:49:42'),
(3186, 463, 4, 'Top với ớt nướng và rau mùi tây.', NULL, '2026-05-15 14:49:42', '2026-05-15 14:49:42'),
(3187, 464, 1, 'Cơm chiên ngon nhất được làm từ cơm thừa để được ít nhất một ngày. Nếu không nó sẽ trở nên dẻo trong chảo.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3188, 464, 2, 'Nếu bạn không còn cơm thừa từ tối hôm trước, hãy nấu một mẻ gạo và trải lên khay nướng lớn hoặc vài đĩa lớn. Để cơm khô khoảng 1 đến 2 tiếng trước khi dùng làm cơm chiên.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3189, 464, 3, 'Cơm rất dễ dính vào chảo nên hãy đảm bảo sử dụng chảo hoặc chảo không có bề mặt dính. Tôi thường nấu các món xào trong chảo thép carbon dày dặn của mình, nhưng chảo gang hoặc chảo chống dính cũng hoạt động tốt. Bạn có thể cần thêm một chút dầu nếu mọi thứ không dễ dàng bong ra.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3190, 464, 4, 'Chuẩn bị gà:', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3191, 464, 5, 'Cắt thịt gà thành các khối nhỏ từ 1/4 inch đến 1/2 inch. Rắc 1/2 thìa muối lên gà rồi trộn đều. Đặt gà sang một bên trong khoảng 10 phút (tôi thường dùng thời gian này để cắt nhỏ tất cả các loại rau).', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3192, 464, 6, 'Đánh trứng:', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3193, 464, 7, 'Đun nóng chảo hoặc chảo xào lớn trên lửa vừa cao. Khuấy một thìa dầu và thêm trứng đã đánh bông vào. Dùng thìa để đánh trứng nhanh chóng, bẻ sữa đông thành những miếng nhỏ hơn khi chúng quyện lại với nhau. Chuyển trứng ra đĩa.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3194, 464, 8, 'Nấu gà:', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3195, 464, 9, 'Thêm một muỗng canh dầu khác vào chảo hoặc chảo. Thêm gà và nấu trong 4 đến 5 phút, thỉnh thoảng khuấy. Tắt lửa và chuyển gà đã luộc ra đĩa.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3196, 464, 10, 'Dùng thìa cạo sạch những miếng thịt gà còn dính vào chảo để chúng không bị cháy trong bước tiếp theo. Bạn cũng có thể dùng khăn giấy để lau chảo hoặc chảo.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3197, 464, 11, 'Nấu rau:', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3198, 464, 12, 'Khuấy 1 muỗng canh dầu vào chảo trên lửa vừa cao. Thêm hành tây thái hạt lựu và nấu trong 1 phút cho đến khi chúng bắt đầu mềm. Trộn tỏi và gừng băm vào và nấu cho đến khi có mùi thơm, khoảng 30 giây. Thêm cà rốt thái hạt lựu và nấu trong 2 phút, khuấy thường xuyên. Thêm 1/2 thìa cà phê muối và đậu Hà Lan vào rồi khuấy đều.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3199, 464, 13, 'Nấu cơm:', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3200, 464, 14, 'Cho gạo vào chảo hoặc chảo đặt trên rau và khuấy đều. Dùng mặt sau của thìa đập vỡ những khối gạo lớn để chúng vỡ ra. Thêm phần trắng và xanh của hành lá cắt lát (để lại phần xanh đậm) và bột ngũ vị hương. Khuấy để kết hợp. Nếu cơm bắt đầu dính vào chảo, hãy cho thêm một ít dầu vào.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3201, 464, 15, 'Rưới nước tương và dầu mè lên cơm rồi khuấy đều. Cho thịt gà đã nấu chín, trứng bác và phần sẫm màu của hành lá vào trộn đều. Khuấy nhanh để hòa quyện và nấu thêm 1 đến 2 phút nữa.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3202, 464, 16, 'Phục vụ:', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3203, 464, 17, 'Hương vị và thêm nước tương nếu cần thiết. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:49:43', '2026-05-15 14:49:43'),
(3204, 465, 1, 'Đun nóng nước luộc gà trong chảo có nắp đậy. Thêm ức gà và đun nhỏ lửa. Đậy nắp và nấu trong 10 phút. Dùng kẹp lấy ức gà ra khỏi nước và đặt lên đĩa. Đổ rượu nấu vào một cái bình lớn.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3205, 465, 2, 'Đun chảy 25g/1oz bơ trong chảo lớn có đế nặng ở lửa nhỏ. Khuấy tỏi tây và chiên nhẹ nhàng trong hai phút, thỉnh thoảng khuấy cho đến khi mềm. Thêm tỏi và nấu thêm một phút nữa. Thêm bơ còn lại và khuấy bột ngay khi bơ tan chảy. Nấu trong 30 giây, khuấy liên tục.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3206, 465, 3, 'Từ từ đổ sữa vào chảo, mỗi lần một ít, khuấy đều giữa mỗi lần thêm. Dần dần thêm 250ml/10fl oz nước kho dự trữ và rượu, nếu dùng thì khuấy đều cho đến khi nước sốt mịn và hơi đặc. Đun nhỏ lửa và nấu trong 3 phút.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3207, 465, 4, 'Nêm hỗn hợp vừa ăn với muối và hạt tiêu đen mới xay. Tắt bếp và cho kem vào khuấy đều. Đổ vào một tô lớn và dùng màng dính phủ lên bề mặt nước sốt để tránh hình thành vỏ. Đặt sang một bên để nguội.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3208, 465, 5, 'Làm nóng lò ở nhiệt độ 200C/400F/Gas 6. Đặt khay nướng vào lò để làm nóng.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3209, 465, 6, 'Đối với bánh ngọt, cho bột mì và bơ vào máy xay thực phẩm và xay ở chế độ xung cho đến khi hỗn hợp giống như vụn bánh mì mịn. Khi động cơ đang chạy, thêm trứng đã đánh và nước vào rồi trộn cho đến khi hỗn hợp tạo thành một khối. Chia bớt 250g/10oz bánh ngọt cho nắp.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3210, 465, 7, 'Lăn phần bánh ngọt còn lại trên bề mặt có phủ bột mì nhẹ, đảo bánh thường xuyên cho đến khi dày khoảng 5 mm/¼ inch và lớn hơn đĩa bánh 4 cm/1½ inch. Nhấc bánh qua cán cán và nhẹ nhàng đặt bánh vào đĩa bánh. Nhấn mạnh bánh ngọt lên các cạnh, đảm bảo không có bọt khí. Để phần bánh thừa nhô ra hai bên.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3211, 465, 8, 'Cắt ức gà thành từng miếng 3cm/1¼in. Khuấy thịt gà, giăm bông và tỏi tây vào nước sốt đã nguội. Đổ nhân gà vào đĩa bánh. Quét trứng đã đánh lên mép đĩa. Tung ra phần bánh ngọt dành riêng cho nắp.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3212, 465, 9, 'Đậy nắp bánh bằng nắp bánh và ấn chặt các mép lại với nhau để bịt kín. Cắt bớt phần bánh thừa.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3213, 465, 10, 'Tạo một lỗ nhỏ ở giữa bánh bằng đầu dao. Phủ mặt trên của chiếc bánh với trứng đã đánh. Nướng trên khay đã làm nóng trước ở giữa lò trong 35-40 phút hoặc cho đến khi toàn bộ bánh có màu nâu vàng và phần nhân nóng hổi.', NULL, '2026-05-15 14:49:45', '2026-05-15 14:49:45'),
(3214, 466, 1, 'Lấy một cái nồi hoặc chảo lớn, đủ lớn để nấu chín hết thịt gà và đun nóng dầu trong đó. Khi dầu nóng, cho hành tây thái lát vào chiên cho đến khi có màu vàng đậm. Sau đó lấy chúng ra đĩa và đặt sang một bên.', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3215, 466, 2, 'Cũng trong nồi đó, thêm tỏi băm nhỏ và xào trong một phút. Sau đó thêm cà chua xắt nhỏ vào nấu cho đến khi cà chua mềm. Việc này sẽ mất khoảng 5 phút.', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3216, 466, 3, 'Sau đó cho hành tây đã xào vào nồi và đảo đều. Thêm bột gừng và xào đều.', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3217, 466, 4, 'Bây giờ thêm hạt thì là, một nửa số hạt rau mùi và ớt xanh xắt nhỏ. Hãy khuấy động nhanh chóng.', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3218, 466, 5, 'Tiếp theo là các loại gia vị – bột nghệ và bột ớt đỏ. Xào đều gia vị trong vài phút.', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3219, 466, 6, 'Cho các miếng thịt gà vào chảo, nêm muối vừa ăn rồi đậy nắp gà trên lửa vừa-thấp cho đến khi gà gần chín. Việc này sẽ mất khoảng 15 phút. Xào gà từ từ sẽ làm tăng hương vị, vì vậy đừng đẩy nhanh bước này bằng cách đun lửa lớn.', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3220, 466, 7, 'Khi dầu tách ra khỏi gia vị, cho sữa chua đã đánh vào, giữ lửa ở mức thấp nhất để sữa chua không bị tách nước. Rắc hạt rau mùi còn lại và thêm một nửa lá cỏ cà ri khô. Trộn đều.', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3221, 466, 8, 'Cuối cùng thêm kem và trộn đều để mọi thứ kết hợp tốt.', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3222, 466, 9, 'Rắc kasuri methi và garam masala còn lại rồi phục vụ món gà handi nóng với naan hoặc rotis. Thưởng thức!', NULL, '2026-05-15 14:49:46', '2026-05-15 14:49:46'),
(3223, 467, 1, 'Cho gừng, tỏi, nước tương, rượu sake và đường vào tô rồi đánh đều. Thêm thịt gà vào, sau đó khuấy đều cho ngấm đều. Đậy nắp và để lạnh ít nhất 1 giờ.', NULL, '2026-05-15 14:49:47', '2026-05-15 14:49:47'),
(3224, 467, 2, 'Thêm 1 inch dầu thực vật vào nồi có đáy nặng và đun nóng cho đến khi dầu đạt 360 độ F. Lót 2 tờ khăn giấy vào giá đỡ rồi lấy kẹp ra. Cho tinh bột khoai tây vào tô', NULL, '2026-05-15 14:49:47', '2026-05-15 14:49:47'),
(3225, 467, 3, 'Thêm một nắm thịt gà vào tinh bột khoai tây và đảo đều để bột phủ đều từng miếng.', NULL, '2026-05-15 14:49:47', '2026-05-15 14:49:47'),
(3226, 467, 4, 'Chiên karaage theo từng mẻ cho đến khi bên ngoài có màu nâu vừa và gà chín đều. Chuyển gà rán vào giá có lót khăn giấy. Nếu muốn karaage giòn lâu hơn, bạn có thể chiên gà lần thứ hai, cho đến khi gà có màu đậm hơn sau khi nguội một lần. Ăn kèm với chanh.', NULL, '2026-05-15 14:49:47', '2026-05-15 14:49:47'),
(3227, 468, 1, '1. Làm sạch và cắt thịt gà; ướp sơ với muối, bột nghệ và một ít dầu.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3228, 468, 2, '2. Rửa sạch và ngâm gạo basmati trong 20–30 phút.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3229, 468, 3, '3. Đun nóng bơ/dầu trong một nồi lớn. Chiên hành tây xắt nhỏ cho đến khi vàng. Thêm tỏi băm và ớt xanh vào xào trong 1–2 phút.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3230, 468, 4, '4. Thêm toàn bộ gia vị (bạch đậu khấu, đinh hương, quế, lá nguyệt quế) và gia vị xay (rau mùi, thì là). Khuấy cho đến khi có mùi thơm.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3231, 468, 5, '5. Thêm miếng thịt gà vào, chiên vàng nhạt và thêm đủ nước/nước luộc gà vào cho ngập. Đun nhỏ lửa cho đến khi thịt gà gần chín.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3232, 468, 6, '6. Lấy thịt gà ra; đo chất lỏng còn lại và thêm gạo ngâm. Đun sôi, sau đó giảm nhiệt, đậy nắp và nấu cơm cho đến khi gần chín.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3233, 468, 7, '7. Cho gà trở lại nồi cơm trên, đậy kín và hấp ở lửa nhỏ trong 10–15 phút để hương vị hòa quyện.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3234, 468, 8, '8. (Tùy chọn) Để có mùi thơm khói đích thực: đun một cục than nhỏ cho đến khi nóng đỏ, đặt than lên cốc giấy bạc nhỏ ở giữa nồi, thêm một thìa cà phê bơ/dầu lên than rồi đậy nắp ngay để bẫy khói trong 5–10 phút. Loại bỏ than.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3235, 468, 9, '9. Trang trí với hành tây chiên, rau mùi xắt nhỏ và dùng kèm tương ớt hoặc raita.', NULL, '2026-05-15 14:49:49', '2026-05-15 14:49:49'),
(3236, 469, 1, 'Đun nóng dầu trong chảo lớn chống cháy và xào nấm cho đến khi chúng bắt đầu mềm. Thêm chân gà và nấu nhanh mỗi bên để tạo màu cho chúng một chút.', NULL, '2026-05-15 14:49:50', '2026-05-15 14:49:50'),
(3237, 469, 2, 'Đổ passata vào, nghiền nát viên nước kho và cho ô liu vào khuấy đều. Nêm hạt tiêu đen – bạn không cần muối. Đậy nắp và đun nhỏ lửa trong 40 phút cho đến khi gà mềm. Rắc rau mùi tây và dùng kèm với mì ống và salad, hoặc khoai tây nghiền và rau xanh, nếu bạn thích.', NULL, '2026-05-15 14:49:50', '2026-05-15 14:49:50'),
(3238, 470, 1, 'Đối với phần trên, luộc khoai tây trong nước muối cho đến khi mềm. Để ráo nước và đẩy qua máy nghiền khoai tây hoặc nghiền kỹ. Khuấy bơ, kem và lòng đỏ trứng. Nêm và đặt sang một bên.', NULL, '2026-05-15 14:49:51', '2026-05-15 14:49:51'),
(3239, 470, 2, 'Để làm nhân, làm tan bơ trong chảo lớn. Thêm hẹ tây, cà rốt và cần tây vào xào nhẹ cho đến khi mềm, sau đó thêm tỏi. Đổ rượu vào và nấu trong 1 phút. Khuấy cà chua xay nhuyễn, cà chua cắt nhỏ rồi kho và nấu trong 10–15 phút cho đến khi đặc lại. Thêm thịt gà xé nhỏ, ô liu và rau mùi tây. Nêm muối và tiêu cho vừa ăn.', NULL, '2026-05-15 14:49:51', '2026-05-15 14:49:51'),
(3240, 470, 3, 'Làm nóng lò ở mức 180C/160C Quạt/Gas 4.', NULL, '2026-05-15 14:49:51', '2026-05-15 14:49:51'),
(3241, 470, 4, 'Cho nhân vào đĩa chịu nhiệt 20x30cm/8x12in và đặt khoai tây nghiền lên trên. Hãy ghi nhớ Gruyère. Nướng trong vòng 30–35 phút cho đến khi nóng và khoai tây có màu nâu vàng.', NULL, '2026-05-15 14:49:51', '2026-05-15 14:49:51'),
(3242, 471, 1, 'Nấu quinoa theo hướng dẫn trên bao bì, sau đó rửa sạch bằng nước lạnh và để ráo nước.', NULL, '2026-05-15 14:49:53', '2026-05-15 14:49:53'),
(3243, 471, 2, 'Trong khi đó, trộn bơ, ớt và tỏi thành hỗn hợp sệt. Cho phi lê gà vào 2 muỗng cà phê dầu ô liu cùng một ít gia vị. Đặt vào chảo nướng nóng và nướng trong 3-4 phút mỗi mặt hoặc cho đến khi chín đều. Chuyển ra đĩa, chấm bơ cay rồi đặt sang một bên cho tan chảy.', NULL, '2026-05-15 14:49:53', '2026-05-15 14:49:53'),
(3244, 471, 3, 'Tiếp theo, cho cà chua, ô liu, hành tây, feta và bạc hà vào tô. Cho quinoa đã nấu chín vào. Khuấy đều dầu ô liu, nước chanh và vỏ còn lại rồi nêm gia vị. Ăn kèm với phi lê gà ở trên, rưới nước sốt gà bơ.', NULL, '2026-05-15 14:49:53', '2026-05-15 14:49:53'),
(3245, 472, 1, 'Bắt đầu bằng cách cắt thịt gà của bạn thành những lát nhỏ vừa phải. Lấy túi ziplock của bạn và đổ thịt gà mới thái lát vào trong.', NULL, '2026-05-15 14:49:54', '2026-05-15 14:49:54'),
(3246, 472, 2, 'Thêm tỏi, rau mùi, thì là, bạch đậu khấu, ớt cayenne, ớt bột, muối, hạt tiêu, nước cốt chanh và dầu ô liu vào túi. Đóng túi lại và trộn kỹ. Đặt trong tủ lạnh trong 10-12 giờ (ngắn hơn cũng được nhưng lâu hơn thì tốt hơn).', NULL, '2026-05-15 14:49:54', '2026-05-15 14:49:54'),
(3247, 472, 3, 'Sau khi đã sẵn sàng nấu, hãy làm nóng chảo rán của bạn ở mức trung bình cao và thêm một chút dầu ô liu. Chiên một mặt của tất cả các loại bánh mì dẹt của bạn cho đến khi hơi chín. Lấy chảo ra, cho lượng dầu vừa đủ vào chảo. Cho khoai tây chiên vụn vào nồi chiên không khí ở mức 180 trong 15 phút, thỉnh thoảng lắc.', NULL, '2026-05-15 14:49:54', '2026-05-15 14:49:54'),
(3248, 472, 4, 'Lúc này chảo đã khá nóng, hãy cho gà làm 2 mẻ (trừ khi bạn có chảo rán lớn) để tránh tình trạng quá đông. Con gà sẽ có màu da đẹp và đậm hơn là hoàn hảo. Nấu thêm 5-8 phút nữa hoặc cho đến khi chín. Lặp lại với mẻ gà tiếp theo.', NULL, '2026-05-15 14:49:54', '2026-05-15 14:49:54'),
(3249, 472, 5, 'Trong khi nấu gà, hãy cho sữa chua Hy Lạp vào tô. Kết hợp tỏi, bạc hà thái nhỏ và rau mùi tây, vắt chanh và thì là. Trộn và thêm muối cho vừa ăn. Trong một bát nhỏ, trộn 1 thìa cà phê bột tỏi, ớt bột, thì là, bột hành tây, lá oregano, rau mùi tây khô, ớt cayenne (tùy chọn) và để sang một bên cho khoai tây chiên.', NULL, '2026-05-15 14:49:54', '2026-05-15 14:49:54'),
(3250, 472, 6, 'Nêm khoai tây chiên ngay sau khi nấu chín và thêm muối cho vừa ăn. Sau khi gà đã hoàn thành, hãy dùng ngay bằng cách bày bánh mì dẹt ra, phết đều nước sốt lên bánh mì, thêm rau diếp, hành tây, cà chua, khoai tây chiên, thịt gà, feta và thêm nước sốt lên trên. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:49:54', '2026-05-15 14:49:54'),
(3252, 473, 1, 'Dùng một chiếc kéo nhà bếp sắc bén, cắt mỗi cánh ở đốt ngón tay thành hai mảnh. Trộn tỏi, vỏ chanh và nước ép, thì là và dầu với nhiều gia vị, sau đó cho vào đĩa có cánh gà và trộn đều. Đậy kín và cho vào tủ lạnh để ướp ít nhất 1 tiếng hoặc qua đêm nếu có thời gian.', NULL, '2026-05-15 14:49:55', '2026-05-16 12:35:34'),
(3254, 473, 2, 'Làm nóng lò nướng ở nhiệt độ 200C/180C quạt/gas 6 hoặc hâm nóng món nướng ngoài trời. Nướng cánh gà trên khay nướng trong 45-50 phút cho đến khi giòn hoặc nướng trong 20 phút, rưới mật ong trong 10 phút cuối cùng của mỗi phương pháp. Bày ra đĩa có nhiều khăn giấy. Đổ đầy các bát nhỏ với ô liu, quả hồ trăn hoặc hạnh nhân, chà là, ớt ngâm và bánh mì dẹt để phục vụ cùng với các món ăn dưới đây.', NULL, '2026-05-15 14:49:55', '2026-05-16 12:35:34'),
(3256, 474, 1, 'Đun nóng chảo lớn trên lửa cao và nêm thịt gà. Thêm dầu ô liu vào chảo, sau đó cho thịt gà vào. Chiên khoảng 5 phút mỗi mặt, gắp ra đĩa rồi đặt sang một bên.', NULL, '2026-05-15 14:49:56', '2026-05-16 12:35:34'),
(3258, 474, 2, 'Giảm nhiệt xuống mức trung bình. Với lượng mỡ còn lại, xào hành tây trong 3 phút, sau đó thêm tỏi và nghệ tây. Nấu thêm 3-4 phút nữa. Thêm rượu sherry vào, sau đó đun nhỏ lửa trong 3-5 phút cho đến khi có dạng siro.', NULL, '2026-05-15 14:49:56', '2026-05-16 12:35:34'),
(3260, 474, 3, 'Cho các miếng chân gà trở lại chảo, cho nước luộc, húng tây và nho khô vào, đậy nắp rồi nấu nhẹ ở lửa nhỏ trong 20 phút. Thêm thịt ức và bất kỳ nước trái cây nào còn lại trên đĩa. Đun nhỏ lửa thêm 10 phút cho đến khi chín và nước sốt trong chảo giảm bớt.', NULL, '2026-05-15 14:49:56', '2026-05-16 12:35:34'),
(3262, 474, 4, 'Trong khi gà đang nấu, làm nóng lò ở mức quạt/gas 200C/180C 6. Rải hạt thông lên khay nướng, sau đó nướng trong 10 phút cho đến khi chín vàng. Khi gà đã chín, nêm nếm vừa ăn, rắc hạt thông và rau mùi tây rồi dùng với cơm.', NULL, '2026-05-15 14:49:56', '2026-05-16 12:35:34'),
(3263, 475, 1, 'Làm nước sốt cam:', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3264, 475, 2, 'Đánh đều các thành phần nước sốt trong một bát vừa. Đặt sang một bên.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3265, 475, 3, 'Chuẩn bị gà:', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3266, 475, 4, 'Cắt thịt gà thành khối khoảng 1 inch. Đánh trứng với muối và hạt tiêu đen vào tô rồi thêm thịt gà vào. Khuấy đều.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3267, 475, 5, 'Trong một bát riêng, trộn đều bột mì và bột bắp. Dùng thìa hoặc kẹp có rãnh vớt gà ra khỏi trứng, để trứng thừa ráo nước rồi chuyển sang hỗn hợp bột bắp và tráng đều.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3268, 475, 6, 'Chiên gà:', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3269, 475, 7, 'Thêm dầu vào chảo lớn 10 đến 12 inch. Đun trên lửa vừa cao cho đến khi đạt nhiệt độ 350°F. Nếu không có nhiệt kế, bạn cũng có thể kiểm tra nhiệt độ bằng cách rắc một ít bột mì vào. Nếu dầu đủ nóng, dầu sẽ xì hơi ngay lập tức.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3270, 475, 8, 'Khi dầu nóng, chiên gà làm hai mẻ. Dầu có thể không bao phủ hoàn toàn con gà—điều đó không sao cả. Nấu trong 3 đến 4 phút. Lật miếng thịt gà và nấu cho đến khi gà chín, khoảng 3 đến 4 phút nữa. Tổng thời gian nấu khoảng 6 đến 8 phút.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3271, 475, 9, 'Gắp gà rán thành từng khối rồi chuyển ra đĩa có lót sẵn khăn giấy để gà ráo nước. Lặp lại cho đến khi tất cả thịt gà được nấu chín.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3272, 475, 10, 'Ướp gà trong nước sốt:', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3273, 475, 11, 'Sau khi gà chín, đổ dầu nóng ra và lau sạch chảo. Thêm một thìa dầu tươi cùng với tỏi và hẹ tây xắt nhỏ. Nấu trong một phút rồi thêm nước sốt. Đun nhỏ nước sốt cho đến khi nó bắt đầu đặc lại.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3274, 475, 12, 'Khi nước sốt sủi bọt nhẹ, thêm gà rán vào và trộn đều. Nước sốt sẽ tiếp tục đặc lại và dính vào thịt gà. Để lửa nhỏ thêm một hoặc hai phút nữa. Dùng gà cam với cơm trắng nấu chín, trang trí với hạt vừng và hành lá tươi.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3275, 475, 13, 'Bạn có thích công thức này không? Hãy cho chúng tôi biết bằng cách đánh giá và đánh giá!', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3276, 475, 14, 'THỪA CÒN! Gà màu cam bảo quản tốt trong tủ lạnh trong 5 ngày. Đun nóng trong chảo với một chút nước trên lửa nhỏ. Làm đông lạnh gà màu cam trong tối đa 3 tháng, nhưng hãy nhớ rã đông trước khi hâm nóng để gà không bị vón cục lại với nhau.', NULL, '2026-05-15 14:49:58', '2026-05-15 14:49:58'),
(3277, 476, 1, 'Cho ức gà chưa nấu chín vào nồi sành. Đổ đầy chai nước sốt salad lên gà. Rắc phần nguyên liệu còn lại lên trên và dùng thìa trộn một chút.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3278, 476, 2, 'Đậy nắp nồi sành và nấu ở nhiệt độ cao trong 4 giờ.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3279, 476, 3, 'Lấy tất cả ức gà ra khỏi nồi sành và để nguội.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3280, 476, 4, 'Cắt nhỏ ức gà và chuyển vào tô thủy tinh.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3281, 476, 5, 'Đổ hầu hết chất lỏng lên gà xé.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3282, 476, 6, 'ĐỐI VỚI TACOS:', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3283, 476, 7, 'Làm nước sốt guacamole bằng cách trộn bơ và salsa xanh với nhau. Đổ hỗn hợp guacamole qua lưới lọc cho đến khi mịn và chuyển vào chai bóp. Cắt phần đầu của nắp chai bóp để mở rộng hơn nếu cần.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3284, 476, 8, 'Làm sốt kem chua bằng cách trộn kem chua và sữa với nhau cho đến khi bạn có được sốt kem chua lỏng hơn. Chuyển sang một chai bóp.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3285, 476, 9, 'Trong đĩa nướng thủy tinh 9x13, đổ đầy tất cả hơn 12 chiếc bánh taco với một lớp đậu chiên, thịt gà nấu chín và phô mai cắt nhỏ.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3286, 476, 10, 'Nướng ở nhiệt độ 450 trong 10-15 phút cho đến khi phô mai tan chảy và sủi bọt.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3287, 476, 11, 'Lấy tất cả các bánh taco ra khỏi lò với cà chua nho thái lát, ớt jalapeno và ngò.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3288, 476, 12, 'Kết thúc với một chút guacamole và kem chua.', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3289, 476, 13, 'Thưởng thức!', NULL, '2026-05-15 14:50:00', '2026-05-15 14:50:00'),
(3291, 477, 1, 'Làm nóng lò nướng ở nhiệt độ 200C/180C quạt/gas 6. Đun nóng dầu ô liu trong chảo rán lớn chịu nhiệt trên lửa vừa và xào hành tây, chorizo và ớt cùng với một chút muối và hạt tiêu trong 15 phút cho đến khi rau mềm và chorizo tiết ra dầu. Thêm ớt bột và tỏi vào, nấu thêm vài phút nữa cho đến khi có mùi thơm.', NULL, '2026-05-15 14:50:01', '2026-05-16 12:35:34'),
(3293, 477, 2, 'Cho cà chua cắt nhỏ, ô liu và đậu bơ vào, khuấy đều và nêm gia vị. Nhúng đùi gà vào và nêm nếm vừa ăn. Chuyển vào lò nướng và nướng trong 40 phút cho đến khi da gà giòn và thịt chín và mềm. Rắc rau mùi tây và phục vụ.', NULL, '2026-05-15 14:50:01', '2026-05-16 12:35:34'),
(3294, 477, 3, 'Xem sau quảng cáo (0,04):', NULL, '2026-05-15 14:50:01', '2026-05-16 12:35:34'),
(3295, 477, 4, '3 ý tưởng trứng ngân sách', NULL, '2026-05-15 14:50:01', '2026-05-16 12:35:34'),
(3296, 478, 1, 'Làm nóng lò ở 425 độ. Rửa và lau khô tất cả sản phẩm. Cắt, gọt vỏ và cắt cà rốt theo đường chéo thành từng miếng dày ¼ inch. Cắt khoai tây thành miếng ½ inch. Cắt đôi, gọt vỏ và cắt lát mỏng hành tây.', NULL, '2026-05-15 14:50:03', '2026-05-15 14:50:03'),
(3297, 478, 2, 'Cho cà rốt lên khay nướng với một ít dầu, muối và tiêu. Nướng cho đến khi chín vàng và mềm, khoảng 15-20 phút.', NULL, '2026-05-15 14:50:03', '2026-05-15 14:50:03'),
(3298, 478, 3, 'Trong khi đó, đặt khoai tây vào nồi vừa với lượng nước muối vừa đủ ngập 2 inch. Đun sôi và nấu cho đến khi mềm, 12-15 phút. Để ráo nước và cho khoai tây vào nồi; đậy lại để giữ ấm.', NULL, '2026-05-15 14:50:03', '2026-05-15 14:50:03'),
(3299, 478, 4, 'Trong khi nấu khoai tây, đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm hành tây và nấu, thỉnh thoảng khuấy cho đến khi hành tây chuyển sang màu nâu nhạt và mềm, khoảng 8-10 phút. Rắc 1 thìa cà phê đường (2 thìa cà phê cho 4 phần ăn). Khuấy nước cô đặc và 2 muỗng canh nước (¼ cốc cho 4 người); nêm muối và hạt tiêu. Nấu cho đến khi mứt, thêm 2-3 phút nữa. Tắt nhiệt; chuyển sang một cái bát nhỏ. Rửa sạch chảo.', NULL, '2026-05-15 14:50:03', '2026-05-15 14:50:03'),
(3300, 478, 5, 'Lau khô gà bằng khăn giấy; nêm đều muối và hạt tiêu. Đun nóng một ít dầu trong chảo dùng cho hành tây trên lửa vừa cao. Thêm thịt gà vào và nấu cho đến khi chín vàng, khoảng 5-6 phút mỗi mặt. Trong 1-2 phút nấu cuối cùng, phủ hành tây và phô mai caramen lên trên. Đậy chảo cho đến khi phô mai tan chảy. (Nếu chảo của bạn không có nắp, hãy phủ một tấm nướng bánh!)', NULL, '2026-05-15 14:50:03', '2026-05-15 14:50:03'),
(3301, 478, 6, 'Đun nóng nồi khoai tây đã ráo nước trên lửa nhỏ; nghiền với kem chua, 2 muỗng canh bơ (4 muỗng canh cho 4 phần ăn), muối, tiêu và một chút nước (hoặc sữa, để thêm đậm đà) cho đến khi mịn. Chia thịt gà, cà rốt nướng và khoai tây nghiền vào các đĩa.', NULL, '2026-05-15 14:50:03', '2026-05-15 14:50:03'),
(3302, 479, 1, 'HƯỚNG DẪN:', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3303, 479, 2, 'BƯỚC 1 - SỐT', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3304, 479, 3, 'Trong một cái bát, thêm 2 cốc nước, 2 thìa canh nước tương, 2 thìa canh giấm trắng, rượu nấu sherry, 1/4 thìa cà phê tiêu trắng, gừng băm, tỏi băm, ớt cay, sốt cà chua, sốt tương đen và đường.', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3305, 479, 4, 'Trộn đều và đặt sang một bên.', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3306, 479, 5, 'BƯỚC 2 – Ướp GÀ', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3307, 479, 6, 'Cho thịt gà, 1 nhúm muối, 1 nhúm tiêu trắng, 2 lòng trắng trứng và 3 thìa tinh bột ngô vào tô', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3308, 479, 7, 'BƯỚC 3 - CHIÊN GÀ', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3309, 479, 8, 'Chiên gà ở nhiệt độ 350 độ trong 3-4 phút hoặc cho đến khi vàng nâu rồi thả gà ra để chúng không dính vào nhau.', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3310, 479, 9, 'Đặt gà sang một bên.', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3311, 479, 10, 'BƯỚC 4 - Xào', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3312, 479, 11, 'Thêm nước sốt vào chảo rồi cho bông cải xanh vào và đợi cho đến khi sôi.', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3313, 479, 12, 'Để làm đặc nước sốt, trộn 2 muỗng canh bột ngô và 4 muỗng canh nước vào tô rồi từ từ thêm vào món xào cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3314, 479, 13, 'Tiếp theo cho thịt gà vào xào khoảng một phút rồi bày ra đĩa', NULL, '2026-05-15 14:50:04', '2026-05-15 14:50:04'),
(3315, 480, 1, '2 phần ăn', NULL, '2026-05-15 14:50:06', '2026-05-15 14:50:06'),
(3316, 480, 2, '1. Làm nóng lò ở nhiệt độ 425 độ. Rửa và lau khô tất cả sản phẩm. Cắt khoai tây thành miếng dày 1/2 inch. Rưới một ít dầu, muối và tiêu lên một mặt của khay nướng. (Đối với 4 phần ăn, trải khoai tây ra toàn bộ tờ giấy.) Nướng trên giá trên cùng trong 5 phút (sau đó chúng ta sẽ thêm bông cải xanh).', NULL, '2026-05-15 14:50:06', '2026-05-15 14:50:06'),
(3317, 480, 3, '2. Trong khi đó, cắt bông cải xanh thành miếng vừa ăn, nếu cần. Bóc vỏ và băm nhuyễn tỏi. Trong một bát nhỏ an toàn với lò vi sóng, trộn 1 muỗng canh dầu ô liu (2 muỗng canh cho 4 phần ăn) và một nửa số tỏi. Cho vào lò vi sóng cho đến khi tỏi kêu xèo xèo, 30 giây.', NULL, '2026-05-15 14:50:06', '2026-05-15 14:50:06'),
(3318, 480, 4, '3. Sau khi khoai tây đã nướng được 5 phút, lấy khay ra khỏi lò và thêm bông cải xanh vào mặt trống; cẩn thận trộn với dầu tỏi, muối và hạt tiêu. (Đối với 4 phần ăn, thêm bông cải xanh vào tờ thứ hai.) Tiếp tục rang cho đến khi khoai tây và bông cải xanh có màu nâu vàng và giòn, thêm 15-20 phút nữa.', NULL, '2026-05-15 14:50:06', '2026-05-15 14:50:06'),
(3319, 480, 5, '4. Trong khi nướng rau, dùng khăn giấy thấm khô gà; nêm đều muối và hạt tiêu. Đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm thịt gà vào và nấu cho đến khi chín vàng, khoảng 5-6 phút mỗi mặt. (Nếu gà chín quá nhanh thì giảm lửa vừa.) Tắt lửa; đặt gà sang một bên để nghỉ ngơi. Rửa sạch chảo.', NULL, '2026-05-15 14:50:06', '2026-05-15 14:50:06'),
(3320, 480, 6, '5. Đun nóng chảo gà trên lửa vừa cao. Thêm một chút dầu và số tỏi còn lại; nấu cho đến khi có mùi thơm, 30 giây. Khuấy giấm, mật ong, nước kho cô đặc và 1/4 cốc nước (1/3 cốc cho 4 phần ăn). Đun nhỏ lửa cho đến khi đặc và bóng, khoảng 2-3 phút. Tắt bếp và cho 1 muỗng canh bơ vào khuấy (2 muỗng canh cho 4 người). Nêm muối và hạt tiêu.', NULL, '2026-05-15 14:50:06', '2026-05-15 14:50:06'),
(3321, 480, 7, '6. Cho gà trở lại chảo và tráng men. Chia thịt gà, bông cải xanh và khoai tây vào các đĩa. Rưới phần men còn lại lên thịt gà và thưởng thức.', NULL, '2026-05-15 14:50:06', '2026-05-15 14:50:06'),
(3322, 481, 1, 'Thiết bị', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3323, 481, 2, 'Lò Hà Lan', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3324, 481, 3, 'Hướng dẫn', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3325, 481, 4, 'Cho đùi gà, gia vị đa năng, 1 thìa bột cà ri, hành tây, hành lá, tiêu xanh, tép tỏi, hạt tiêu scotch (nếu dùng) và húng tây vào tô lớn rồi trộn đều, đảm bảo tất cả các miếng gà đều được phủ đều gia vị. Đậy nắp và để lạnh ít nhất 1 giờ hoặc qua đêm.', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3326, 481, 5, 'Một con gà đã ướp xong, bỏ hành, ớt và tép tỏi ra khỏi thịt gà rồi để sang một bên.', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3327, 481, 6, 'Đun nóng dầu ô liu trong nồi lớn có đáy nặng trên lửa vừa. Thêm bột cà ri còn lại vào và khuấy đều, nấu trong khoảng 20-30 giây. Cho hành tây, ớt xanh, tép tỏi, húng tây và ớt scotch (nếu dùng) vào nồi và khuấy đều cho đến khi hành mềm, khoảng 3-5 phút. Nếu hành và ớt của bạn trông khô, hãy thêm khoảng 1 thìa nước.', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3328, 481, 7, 'Cho gà và ¼ cốc nước vào nồi. Đậy nắp và giảm nhiệt xuống mức trung bình thấp. Nấu, thỉnh thoảng khuấy trong 30-35 phút.', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3329, 481, 8, 'Khi còn khoảng 15 phút, cho khoai tây vào đảo đều và đậy nắp tiếp tục nấu.', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3330, 481, 9, 'Sau khi gà chín và khoai tây mềm thì tắt bếp. Muối và hạt tiêu cho vừa ăn.', NULL, '2026-05-15 14:50:07', '2026-05-15 14:50:07'),
(3331, 482, 1, 'Để làm nước xốt giật, cho tất cả nguyên liệu vào máy xay thực phẩm cùng với 1 thìa cà phê muối và xay thành hỗn hợp nhuyễn. Nếu bạn gặp khó khăn khi xay, chỉ cần tắt máy xay, khuấy hỗn hợp và thử lại. Cuối cùng, nó sẽ bắt đầu hòa quyện - đừng cố thêm nước vì bạn muốn có một hỗn hợp sệt.', NULL, '2026-05-15 14:50:09', '2026-05-15 14:50:09'),
(3332, 482, 2, 'Nếm thử hỗn hợp gia vị đã trộn – nó sẽ có vị khá mặn nhưng không khó chịu, mặn chát. Bây giờ bạn có thể cho thêm ớt vào nếu thấy chưa đủ cay. Nếu nó có vị quá mặn và chua, hãy thử thêm một chút đường nâu cho đến khi hỗn hợp có vị cân bằng.', NULL, '2026-05-15 14:50:09', '2026-05-15 14:50:09'),
(3333, 482, 3, 'Rạch một vài đường trên đùi gà rồi rưới nước xốt lên thịt, chà xát vào tất cả các kẽ hở. Đậy nắp và để ướp qua đêm trong tủ lạnh.', NULL, '2026-05-15 14:50:09', '2026-05-15 14:50:09'),
(3334, 482, 4, 'Nếu bạn muốn nướng thịt gà, hãy để than cháy khoảng 1 giờ trước khi sẵn sàng nấu. Thịt giật đích thực không phải là nướng chính xác như chúng ta nghĩ về nướng mà là kiểu nướng khói. Để có được trải nghiệm chân thực hơn, hãy thêm một ít dăm gỗ vào món thịt nướng của bạn và nấu gà ở nhiệt độ chậm, gián tiếp trong 30 phút. Để nấu trong lò, làm nóng quạt/khí ở nhiệt độ 180C/160C 4. Cho các miếng thịt gà vào hộp nướng cùng với hai nửa quả chanh và nấu trong 45 phút cho đến khi mềm và chín.', NULL, '2026-05-15 14:50:09', '2026-05-15 14:50:09'),
(3335, 482, 5, 'Trong khi luộc gà, chuẩn bị cơm và đậu Hà Lan. Xả gạo với nhiều nước lạnh, sau đó cho gạo vào nồi lớn cùng tất cả nguyên liệu còn lại trừ đậu thận. Nêm muối, thêm 300ml nước lạnh rồi đun trên lửa lớn. Khi cơm bắt đầu sôi, vặn lửa vừa, đậy nắp và nấu trong 10 phút.', NULL, '2026-05-15 14:50:09', '2026-05-15 14:50:09'),
(3336, 482, 6, 'Cho đậu vào cơm, sau đó đậy nắp lại. Tắt lửa trong 5 phút cho đến khi hấp thụ hết chất lỏng. Vắt chanh rang lên gà và dùng kèm cơm, đậu Hà Lan và một ít nước sốt nóng nếu bạn thích cay.', NULL, '2026-05-15 14:50:09', '2026-05-15 14:50:09'),
(3337, 483, 1, 'Chuẩn bị:15 phút > Nấu: 30 phút > Sẵn sàng: 45 phút', NULL, '2026-05-15 14:50:10', '2026-05-15 14:50:10'),
(3338, 483, 2, 'Đối với nước sốt cà ri: Đun nóng dầu trong chảo chống dính vừa, thêm hành tây và tỏi vào nấu cho đến khi mềm. Khuấy cà rốt và nấu trên lửa nhỏ trong 10 đến 12 phút.', NULL, '2026-05-15 14:50:10', '2026-05-15 14:50:10'),
(3339, 483, 3, 'Thêm bột mì và bột cà ri; nấu trong 1 phút. Từ từ khuấy đều cho đến khi hòa quyện; thêm mật ong, nước tương và lá nguyệt quế. Từ từ đun sôi.', NULL, '2026-05-15 14:50:10', '2026-05-15 14:50:10'),
(3340, 483, 4, 'Giảm nhiệt và đun nhỏ lửa trong 20 phút hoặc cho đến khi nước sốt đặc lại nhưng vẫn có độ sệt. Khuấy garam masala. Đổ nước sốt cà ri qua rây; trở lại chảo và giữ ở lửa nhỏ cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:50:10', '2026-05-15 14:50:10'),
(3341, 483, 5, 'Đối với thịt gà: Nêm muối và hạt tiêu vào cả hai mặt ức gà. Cho bột mì, trứng và vụn bánh mì vào các bát riêng rồi xếp thành một hàng. Lăn ức gà qua bột mì, sau đó nhúng vào trứng, sau đó lăn qua vụn bánh mì, đảm bảo phủ kín cả hai mặt.', NULL, '2026-05-15 14:50:10', '2026-05-15 14:50:10'),
(3342, 483, 6, 'Đun nóng dầu trong chảo lớn trên lửa vừa cao. Cho gà vào dầu nóng và chiên cho đến khi vàng nâu, khoảng 3 hoặc 4 phút mỗi mặt. Sau khi chín, đặt lên giấy ăn để thấm bớt dầu thừa.', NULL, '2026-05-15 14:50:10', '2026-05-15 14:50:10'),
(3343, 483, 7, 'Rưới nước sốt cà ri lên gà, dùng kèm cơm trắng và thưởng thức!', NULL, '2026-05-15 14:50:10', '2026-05-15 14:50:10'),
(3344, 484, 1, 'Làm nóng lò chiên ở nhiệt độ 350°F. Trộn thật đều tất cả các nguyên liệu làm hỗn hợp gia vị.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3345, 484, 2, 'Trộn hỗn hợp gia vị với bột mì, đường nâu và muối.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3346, 484, 3, 'Nhúng miếng gà vào lòng trắng trứng để tráng nhẹ rồi chuyển sang hỗn hợp bột. Lật vài lần và đảm bảo hỗn hợp bột thực sự dính vào gà. Lặp lại với tất cả các miếng thịt gà.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3347, 484, 4, 'Để miếng gà nghỉ trong 5 phút để lớp vỏ có cơ hội khô một chút.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3348, 484, 5, 'Chiên gà theo mẻ. Vú và cánh sẽ mất 12-14 phút, còn chân và đùi sẽ cần thêm vài phút. Miếng thịt gà chín khi nhiệt kế thịt được đưa vào phần dày nhất cho thấy nhiệt độ là 165°F.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3349, 484, 6, 'Để gà ráo nước trên một ít khăn giấy khi lấy ra khỏi nồi chiên. Ăn nóng.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3350, 485, 1, 'Kết hợp rượu sake hoặc rượu gạo, nước tương, dầu mè và bột ngô hòa tan trong nước. Chia hỗn hợp làm đôi.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3351, 485, 2, 'Trong một đĩa thủy tinh hoặc bát, trộn một nửa hỗn hợp rượu sake với các miếng thịt gà và trộn đều. Đậy đĩa và để trong tủ lạnh khoảng 30 phút.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3352, 485, 3, 'Trong một chảo vừa, trộn hỗn hợp rượu sake còn lại, ớt, giấm và đường. Trộn đều rồi thêm hành lá, tỏi, hạt dẻ nước và đậu phộng vào. Đun nóng nước sốt từ từ trên lửa vừa cho đến khi có mùi thơm.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3353, 485, 4, 'Trong khi đó, lấy thịt gà ra khỏi nước xốt và xào trong chảo lớn cho đến khi nước trong. Khi nước sốt có mùi thơm thì cho gà đã xào vào đun nhỏ lửa cho đến khi nước sốt đặc lại.', NULL, '2026-05-15 14:50:12', '2026-05-15 14:50:12'),
(3354, 486, 1, 'Cắt nhuyễn 1/4 quả ớt, sau đó cho phần còn lại vào máy xay thực phẩm cùng với gừng, tỏi, cọng rau mùi và 1/3 số lá. Đánh thành hỗn hợp sệt với một chút nước nếu cần.', NULL, '2026-05-15 14:50:14', '2026-05-15 14:50:14'),
(3355, 486, 2, 'Đun nóng dầu trong chảo, sau đó chiên nhanh miếng gà trong 1 phút. Khuấy hỗn hợp thêm một phút nữa, sau đó thêm bơ đậu phộng, nước kho và sữa chua. Khi nước sốt sủi bọt nhẹ, nấu trong 10 phút cho đến khi gà vừa chín và nước sốt đặc lại. Khuấy hầu hết số rau mùi còn lại, sau đó rải phần còn lại lên trên cùng với ớt nếu dùng. Ăn với cơm hoặc khoai lang nghiền.', NULL, '2026-05-15 14:50:14', '2026-05-15 14:50:14'),
(3356, 487, 1, 'Trộn nước sốt vào tô nhỏ.', NULL, '2026-05-15 14:50:15', '2026-05-15 14:50:15'),
(3357, 487, 2, 'Băm tỏi vào chảo dầu. Đặt trên lửa lớn, khi nóng thì cho thịt gà và cọng bông cải xanh vào nấu đến khi gà có màu vàng nhạt.', NULL, '2026-05-15 14:50:15', '2026-05-15 14:50:15'),
(3358, 487, 3, 'Đẩy sang một bên chảo, đập trứng vào và tráng. Đừng lo lắng nếu nó dính vào đáy chảo - nó sẽ cháy thành than và làm tăng thêm hương vị đích thực.', NULL, '2026-05-15 14:50:15', '2026-05-15 14:50:15'),
(3359, 487, 4, 'Thêm mì, lá bông cải xanh và nước sốt. Trộn nhẹ nhàng cho đến khi sợi mì có màu sẫm và lá héo. Phục vụ ngay lập tức!', NULL, '2026-05-15 14:50:15', '2026-05-15 14:50:15'),
(3361, 488, 1, 'Đầu tiên, làm bột cà ri. Dùng chày và cối giã nhuyễn ớt khô và ớt tươi, mắm tôm, tỏi, riềng, sả, vỏ chanh, tiêu trắng, rau mùi, thì là, nhục đậu khấu và đậu phộng, cộng thêm 1 thìa cà phê muối. Bạn nên có một dán thô. Ngoài ra, bạn có thể cho tất cả nguyên liệu vào máy xay thực phẩm cùng với 2-3 thìa nước cốt dừa và xay cho đến khi thu được hỗn hợp sệt. Bảo quản trong lọ có nắp đậy trong tủ lạnh. Sẽ giữ được tối đa hai tuần.', NULL, '2026-05-15 14:50:16', '2026-05-16 12:35:34'),
(3363, 488, 2, 'Thêm 2-3 muỗng canh phần nước cốt dừa đặc vào nồi trên lửa vừa cao. Khi nước cốt dừa bắt đầu sủi bọt, thêm 1-2 thìa canh bột cà ri vào và khuấy đều khoảng 1 phút cho đến khi có mùi thơm.', NULL, '2026-05-15 14:50:16', '2026-05-16 12:35:34'),
(3365, 488, 3, 'Cho gà vào đun khoảng 3-4 phút cho đến khi gà chuyển sang màu nâu vàng. Tiếp theo với đậu Pháp và khuấy đều.', NULL, '2026-05-15 14:50:16', '2026-05-16 12:35:34'),
(3367, 488, 4, 'Nêm nước mắm và đường rồi cho phần nước cốt dừa còn lại vào. Trộn đều, thêm nửa lá chanh makrut vào đun nhỏ lửa trong 3-5 phút cho đến khi gà chín. Nếm thử và thêm đường hoặc nước mắm nếu cần - nước mắm phải có vị mặn, bùi và vị ngọt. Thêm lá húng quế Thái vào, trộn nhanh và tắt lửa. Ăn kèm cơm hoa nhài hấp, trang trí với ớt thái lát và phần còn lại của lá chanh makrut.', NULL, '2026-05-15 14:50:16', '2026-05-16 12:35:34'),
(3368, 489, 1, 'BƯỚC 1', NULL, '2026-05-15 14:50:17', '2026-05-15 14:50:17'),
(3369, 489, 2, 'Trộn đều tất cả nguyên liệu làm nước xốt trong máy xay thực phẩm nhỏ. Xoa nước xốt lên gà và để trong 1 giờ ở nhiệt độ phòng.', NULL, '2026-05-15 14:50:17', '2026-05-15 14:50:17'),
(3370, 489, 3, 'BƯỚC 2', NULL, '2026-05-15 14:50:17', '2026-05-15 14:50:17'),
(3371, 489, 4, 'Làm nóng lò nướng ở 190C/quạt 170C/gas 5. Cho gà vào khay nướng và nướng trong 1 giờ 20 phút. Nghỉ ngơi dưới giấy bạc trong 20 phút. Trong khi gà đang nghỉ ngơi, trộn đều các nguyên liệu và nêm gia vị. Phục vụ gà với khoai tây chiên, khoai tây chiên và gia vị.', NULL, '2026-05-15 14:50:17', '2026-05-15 14:50:17'),
(3372, 490, 1, 'Gratin khoai tây 15 phút với thịt gà và rau xanh thịt xông khói: món gratin luôn có vẻ tốn nhiều công sức và ngon miệng hơn so với món luộc hoặc nướng thông thường, nhưng không nhất thiết phải mất 45 phút, thật tuyệt khi thay đổi và bạn có thể kiểm soát hàm lượng calo bằng cách ăn đầy đủ chất béo đến kem ít béo', NULL, '2026-05-15 14:50:19', '2026-05-15 14:50:19'),
(3373, 490, 2, '(Rõ ràng là nó luôn có vị béo tốt hơn!) Phần 4: dùng 800g khoai tây, thái lát mỏng và đun sôi trong chảo khoảng 5-8 phút cho đến khi cứng, không mềm', NULL, '2026-05-15 14:50:19', '2026-05-15 14:50:19');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(3374, 490, 3, 'Cắt nhuyễn 3 củ hành tây rồi cho vào khay nướng cùng với 2 thìa dầu ô liu và 100ml nước luộc gà', NULL, '2026-05-15 14:50:19', '2026-05-15 14:50:19'),
(3375, 490, 4, 'Nấu cho đến khi hành tây mềm thì vớt khoai tây ra và đổ lên hành tây', NULL, '2026-05-15 14:50:19', '2026-05-15 14:50:19'),
(3376, 490, 5, 'Nêm và dùng thìa phủ lên kem hoặc creme fraiche cho đến khi phủ đều nhưng không nổi', NULL, '2026-05-15 14:50:19', '2026-05-15 14:50:19'),
(3377, 490, 6, 'Bào Parmesan lên trên rồi nướng dưới vỉ nướng cho đến khi chín vàng đẹp mắt', NULL, '2026-05-15 14:50:19', '2026-05-15 14:50:19'),
(3378, 490, 7, 'ăn kèm với thịt gà và thịt xông khói, đậu Hà Lan và rau bina', NULL, '2026-05-15 14:50:19', '2026-05-15 14:50:19'),
(3379, 491, 1, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C).', NULL, '2026-05-15 14:50:20', '2026-05-15 14:50:20'),
(3380, 491, 2, 'Trộn nước, hành tây, dầu ô liu, giấm balsamic, mù tạt Dijon, tỏi, tiêu đen, ớt cayenne và muối với nhau trong đĩa rang. Thêm thịt gà; xoay cho đến khi được phủ đều hỗn hợp.', NULL, '2026-05-15 14:50:20', '2026-05-15 14:50:20'),
(3381, 491, 3, 'Nướng trong lò làm nóng trước cho đến khi nhiệt kế đọc tức thời được đưa vào phần dày nhất của đùi, gần xương, đọc 165 độ F (74 độ C), khoảng 1 giờ 30 phút.', NULL, '2026-05-15 14:50:20', '2026-05-15 14:50:20'),
(3382, 492, 1, 'Làm nóng lò ở nhiệt độ 400 độ F (200 độ C). Bôi mỡ vào chảo nướng 10x14x2 inch.', NULL, '2026-05-15 14:50:21', '2026-05-15 14:50:21'),
(3383, 492, 2, 'Đun nóng bơ thực vật trong chảo trên lửa vừa; khuấy hành tây. Nấu và khuấy cho đến khi hành tây mềm và chuyển sang màu trong, khoảng 5 phút. Giảm nhiệt xuống thấp và tiếp tục nấu và khuấy cho đến khi hành tây rất mềm và có màu nâu sẫm, khoảng 40 phút nữa.', NULL, '2026-05-15 14:50:21', '2026-05-15 14:50:21'),
(3384, 492, 3, 'Đun sôi nước luộc gà trong nồi lớn; cho ức gà vào, giảm nhiệt và đun nhỏ lửa cho đến khi gà không còn màu hồng ở giữa, khoảng 20 phút. Loại bỏ khỏi nhiệt. Dùng thìa có rãnh vớt ức gà ra đĩa; nước dùng dự trữ.', NULL, '2026-05-15 14:50:21', '2026-05-15 14:50:21'),
(3385, 492, 4, 'Ép khoai tây bằng máy ép trái cây điện; cho thịt khoai tây khô vào tô và đổ nước đi. Khuấy muối và hạt tiêu vào khoai tây; khuấy đủ nước dùng dành riêng để tạo thành hỗn hợp có độ đặc của bột yến mạch. Đặt nước dùng còn lại sang một bên.', NULL, '2026-05-15 14:50:21', '2026-05-15 14:50:21'),
(3386, 492, 5, 'Trải đều một nửa hỗn hợp khoai tây vào chảo đã chuẩn bị. Xếp đều ức gà đã nấu chín lên trên khoai tây; rải đều hành tây caramen lên thịt gà. Rải hỗn hợp khoai tây còn lại lên trên hành và thịt gà.', NULL, '2026-05-15 14:50:21', '2026-05-15 14:50:21'),
(3387, 492, 6, 'Nướng trong lò làm nóng trước cho đến khi có màu vàng nâu, khoảng 1 giờ. Đun nóng lại nước luộc gà; đổ từng phần riêng lẻ theo ý muốn.', NULL, '2026-05-15 14:50:21', '2026-05-15 14:50:21'),
(3389, 493, 1, 'Bật lửa nướng hoặc làm nóng chảo nướng ở nhiệt độ cao. Cho gà, bột cà ri và nước cốt dừa vào tô, sau đó trộn đều cho đến khi gà được phủ đều. Xiên rau và thịt gà vào xiên. Nướng xiên trên vỉ nướng hoặc vỉ nướng trong 5-8 phút, thỉnh thoảng lật thịt cho đến khi thịt gà chín đều và cháy thành than. Ăn kèm cơm, salad và nửa quả chanh để vắt.', NULL, '2026-05-15 14:50:22', '2026-05-16 12:35:34'),
(3391, 494, 1, 'Làm nóng lò nướng ở mức quạt/khí 200C/180C 6. Cho thịt gà, thì là, ớt bột, 1 muỗng canh dầu ô liu và gia vị vào hộp rang. Nấu trong 40 phút cho đến khi gà giòn và chín đều.', NULL, '2026-05-15 14:50:23', '2026-05-16 12:35:34'),
(3393, 494, 2, 'Trong khi đó, xé 1 chiếc bánh mì pitta và cho vào một cái bát nhỏ. Đổ một vài muỗng canh nước luộc gà và để ngâm. Chiên khô quả óc chó trong chảo khoảng 3 phút cho đến khi vàng và nướng. Đặt sang một bên. Đun nóng lượng dầu còn lại trong chảo rồi cho hành, tỏi vào xào chín mềm. Cho bánh mì pitta đã làm mềm, hỗn hợp hành tây và hầu hết các loại hạt vào máy xay. Đổ phần nước luộc gà còn lại lên và trộn đều cho đến khi tạo thành hỗn hợp sệt. Cho hỗn hợp trở lại chảo. Thêm kem và nước cốt chanh, nêm gia vị và giữ ấm.', NULL, '2026-05-15 14:50:23', '2026-05-16 12:35:34'),
(3395, 494, 3, 'Khi gà chín, xếp ra đĩa. Khuấy rau mùi qua nước sốt và cho thìa vào tô. Cắt nhỏ những quả óc chó còn lại và rắc lên gà. Nướng bánh pittas, cắt thành miếng vừa ăn và dùng kèm', NULL, '2026-05-15 14:50:23', '2026-05-16 12:35:34'),
(3396, 495, 1, 'Cho gà vào lò nướng kiểu Hà Lan lớn hoặc nồi kho', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3397, 495, 2, 'Phủ nước', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3398, 495, 3, 'Đun sôi và đun nhỏ lửa trong 2 đến 2 tiếng rưỡi, loại bỏ tạp chất bên trên để đảm bảo nước dùng trong', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3399, 495, 4, 'Nếu nồi của bạn đủ lớn, hãy thêm rau và gia vị vào giờ nấu cuối cùng.', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3400, 495, 5, 'Lò nướng kiểu Hà Lan của tôi không đủ lớn để đựng mọi thứ, chỉ có thịt gà và các loại xương khác lấp đầy nồi nên tôi nấu chín thịt/xương rồi lấy ra và nấu riêng rau và gia vị.', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3401, 495, 6, 'Lọc mọi thứ ra khỏi nước dùng', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3402, 495, 7, 'Rút xương gà, xé thịt thành khối lớn', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3403, 495, 8, 'Cắt lát cà rốt', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3404, 495, 9, 'Cho gà và cà rốt vào nước dùng', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3405, 495, 10, 'Nấu mì theo hướng dẫn trên bao bì nếu bạn đang sử dụng chúng', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3406, 495, 11, 'Cho mì vào tô rồi rưới nước súp nóng lên trên', NULL, '2026-05-15 14:50:24', '2026-05-15 14:50:24'),
(3408, 496, 1, 'Bạn cần 15 xiên: nếu bằng gỗ thì ngâm trong nước 10 phút. Cắt gà thành miếng 3 cm và cho vào tô. Thêm 1 muỗng canh dầu ô liu, gia vị, tỏi và giấm, trộn đều và nêm gia vị. Bạn có thể làm điều này trước một ngày và để trong tủ lạnh.', NULL, '2026-05-15 14:50:26', '2026-05-16 12:35:34'),
(3410, 496, 2, 'Xiên 2-3 miếng vào mỗi xiên. Đổ lượng dầu còn lại vào chảo rán hoặc chà lên chảo nướng. Bắt chảo nóng và nướng gà trong 3-4 phút mỗi mặt - bạn có thể phải làm theo từng đợt, giữ ấm xiên đã nấu chín trong lò nướng nhỏ. Ăn kèm với aïoli khói nếu bạn thích.', NULL, '2026-05-15 14:50:26', '2026-05-16 12:35:34'),
(3412, 497, 1, 'Ngâm đậu ít nhất 4 giờ hoặc qua đêm trong tô lớn với nhiều nước ngập. Ngày hôm sau, rửa sạch và để ráo nước, sau đó cho vào chảo lớn có nền dày cùng hành tây, ớt bột, bó rau thơm và thịt gà. Đổ đủ nước hoặc nước kho vào, đun sôi rồi giảm lửa, đậy nắp và đun nhỏ lửa trong 45 phút.', NULL, '2026-05-15 14:50:27', '2026-05-16 12:35:34'),
(3414, 497, 2, 'Lấy thịt gà ra đĩa, sau đó cho khoai tây và chorizo vào chảo. Tiếp tục nấu trong 30 phút cho đến khi đậu và khoai tây mềm.', NULL, '2026-05-15 14:50:27', '2026-05-16 12:35:34'),
(3416, 497, 3, 'Loại bỏ da và xương gà rồi xé thành từng miếng lớn. Cho gà vào chảo cùng với rau bina và đun nhỏ lửa trong 5 phút.', NULL, '2026-05-15 14:50:27', '2026-05-16 12:35:34'),
(3418, 498, 1, 'Làm nóng lò ở mức quạt/gas 190C/170C 5. Cho tất cả nguyên liệu vào một đĩa chịu nhiệt rộng, rộng. Trộn tất cả mọi thứ lại với nhau bằng tay và nêm gia vị.', NULL, '2026-05-15 14:50:28', '2026-05-16 12:35:34'),
(3420, 498, 2, 'Nướng trong 45 phút, đảo hành sau 20 phút cho đến khi gà vàng và hành mềm. Ăn kèm cơm.', NULL, '2026-05-15 14:50:28', '2026-05-16 12:35:34'),
(3422, 499, 1, 'Làm nóng lò ở 200C/quạt 180C/gas 6. Luộc khoai tây trong 15-20 phút cho đến khi mềm. Để ráo nước, cho trở lại chảo, sau đó nghiền với một ít gia vị và 2 thìa cà phê ớt bột.', NULL, '2026-05-15 14:50:29', '2026-05-16 12:35:34'),
(3424, 499, 2, 'Trong khi đó, đun nóng dầu trong chảo lớn, sau đó xào hành và tỏi trong vài phút cho đến khi mềm. Khuấy phần ớt bột còn lại trong 1 phút, thêm cà chua vào, sau đó đun nhỏ lửa. Đổ thịt vào một đĩa chịu nhiệt lớn, sau đó cho thịt gà, ớt, ô liu và một ít gia vị vào trộn đều.', NULL, '2026-05-15 14:50:29', '2026-05-16 12:35:34'),
(3426, 499, 3, 'Đổ hỗn hợp nghiền lên trên, sau đó nướng trong 15 phút cho đến khi hỗn hợp có màu vàng ở trên và nước sốt sủi bọt.', NULL, '2026-05-15 14:50:29', '2026-05-16 12:35:34'),
(3428, 500, 1, 'Làm nước xốt. Dùng chày và cối đập tỏi với một ít muối. Thêm vỏ chanh và nước ép, hỗn hợp gia vị, ớt, dầu và một ít hạt tiêu đen xay. Trộn thành bột nhão. Điều này có thể được thực hiện trong một máy chế biến thực phẩm mini.', NULL, '2026-05-15 14:50:30', '2026-05-16 12:35:34'),
(3430, 500, 2, 'Cho gà vào nước xốt và đặt sang một bên trong khi bạn đốt thịt nướng. Khi thịt nướng đã nóng, xếp các bó rau thơm lên vỉ và đặt thịt gà, mặt da úp lên trên. Đậy nắp nếu thịt nướng của bạn có nắp và nấu gà trên các loại thảo mộc đang cháy âm ỉ trong khoảng 10 phút cho đến khi thịt bắt đầu có màu. Lật gà và tiếp tục nấu thêm 20-30 phút nữa, đảo khi cần thiết, cho đến khi các loại thảo mộc bị cháy hơi cháy và chín đến tận xương.', NULL, '2026-05-15 14:50:30', '2026-05-16 12:35:34'),
(3432, 501, 1, 'Thực hiện 3 dấu gạch chéo trên mỗi dùi trống. Trộn đậu nành, mật ong, dầu, cà chua xay nhuyễn và mù tạt. Đổ hỗn hợp này lên gà và phủ kỹ. Để ướp trong 30 phút ở nhiệt độ phòng hoặc qua đêm trong tủ lạnh. Làm nóng lò ở 200C/quạt 180C/gas 6.', NULL, '2026-05-15 14:50:31', '2026-05-16 12:35:34'),
(3434, 501, 2, 'Cho gà vào khay nướng nông và nấu trong 35 phút, thỉnh thoảng lật gà cho đến khi gà mềm và lấp lánh với nước xốt.', NULL, '2026-05-15 14:50:31', '2026-05-16 12:35:34'),
(3435, 502, 1, 'Đun nóng chảo hoặc chảo lớn cho đến khi thật nóng, sau đó thêm 1 muỗng canh dầu. Khi trời rất nóng, cho gà vào xào trên lửa cao trong 8-10 phút cho đến khi chín vàng đều. Dùng thìa có rãnh, lấy gà ra khỏi chảo và đặt sang một bên.', NULL, '2026-05-15 14:50:32', '2026-05-15 14:50:32'),
(3437, 502, 2, 'Làm nóng chảo và thêm lượng dầu còn lại. Cho tỏi và hẹ tây vào xào trong 3 phút cho đến khi có màu vàng nâu.', NULL, '2026-05-15 14:50:32', '2026-05-16 12:35:34'),
(3439, 502, 3, 'Cho gà vào chảo rồi thêm ớt, nước mắm, nước tương đen và đường. Xào trên lửa cao thêm 8-10 phút nữa hoặc cho đến khi gà chín. Khuấy lá húng quế và dùng ngay.', NULL, '2026-05-15 14:50:32', '2026-05-16 12:35:34'),
(3440, 503, 1, 'Phủ gà với lòng trắng trứng:', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3441, 503, 2, 'Trong một cái bát, trộn thịt gà với lòng trắng trứng, 1/2 thìa cà phê muối kosher và bột ngô. Đảo đều để gà ngấm đều. Để yên trong 15 phút ở nhiệt độ phòng hoặc để qua đêm trong tủ lạnh.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3442, 503, 3, 'Làm nước sốt chua ngọt:', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3443, 503, 4, 'Đánh đều nước ép dứa, giấm, sốt cà chua, 1/2 muỗng cà phê muối kosher và đường nâu.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3444, 503, 5, 'Xào gà ở lửa lớn:', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3445, 503, 6, 'Đun nóng chảo rán lớn hoặc chảo trên lửa cao cho đến khi một hạt nước ngay lập tức sủi bọt và bay hơi. Đổ 1 thìa dầu ăn vào và khuấy đều. Điều quan trọng là chảo rất nóng.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3446, 503, 7, 'Thêm thịt gà và trải các miếng thành một lớp. Để gà chiên nguyên trong 1 phút, cho đến khi phần đáy có màu nâu.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3447, 503, 8, 'Lật và chiên mặt còn lại trong 1 phút. Con gà vẫn còn hơi hồng ở giữa. Gắp gà ra đĩa sạch, để lại càng nhiều dầu trong chảo càng tốt.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3448, 503, 9, 'Xào ớt chuông và gừng:', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3449, 503, 10, 'Giảm lửa vừa và thêm 1 muỗng cà phê dầu ăn còn lại. Để dầu nóng lên trước khi cho ớt chuông và gừng vào. Chiên trong 1 phút.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3450, 503, 11, 'Thêm dứa, nước sốt và sau đó là thịt gà:', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3451, 503, 12, 'Thêm miếng dứa và nước sốt chua ngọt. Tăng nhiệt lên cao. Khi nước sốt sôi thì cho các miếng thịt gà vào lại.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3452, 503, 13, 'Để nhỏ lửa trong 1 đến 2 phút, cho đến khi gà chín. Thời gian phụ thuộc vào độ dày bạn cắt thịt gà. Cách tốt nhất để biết gà đã chín hay chưa là lấy một miếng ra và cắt thành từng miếng. Nếu nó có màu hồng, hãy nấu thêm một phút nữa.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3453, 503, 14, 'Điều chỉnh gia vị và thưởng thức:', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3454, 503, 15, 'Nếm thử nước sốt và thêm đường nâu hoặc giấm cho phù hợp với khẩu vị của bạn nếu muốn.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3455, 503, 16, 'Ăn nóng với cơm trắng hoặc gạo lứt.', NULL, '2026-05-15 14:50:34', '2026-05-15 14:50:34'),
(3456, 504, 1, 'Kết hợp hành tây, cần tây, ngò và rau mùi tây trong một nồi lớn. Khuấy nghệ, thì là, ớt bột, gừng, ớt cayenne, muối và tiêu. Đặt đùi gà lên trên. Rưới dầu ô liu lên thịt gà. Đậy nắp và đun nhỏ lửa cho đến khi gà mềm, khoảng 40 phút.', NULL, '2026-05-15 14:50:35', '2026-05-15 14:50:35'),
(3457, 504, 2, 'Đặt nho khô vào một cái bát nhỏ và đổ nước nóng vào; để ngâm trong 10 phút. Làm khô hạn.', NULL, '2026-05-15 14:50:35', '2026-05-15 14:50:35'),
(3458, 504, 3, 'Làm nóng lò ở nhiệt độ 400 độ F (200 độ C).', NULL, '2026-05-15 14:50:35', '2026-05-15 14:50:35'),
(3459, 504, 4, 'Chuyển hỗn hợp gà vào đĩa tagine hoặc món thịt hầm an toàn với lò nướng. Thêm khoai lang và cà rốt. Đậy nắp hoặc giấy nhôm.', NULL, '2026-05-15 14:50:35', '2026-05-15 14:50:35'),
(3460, 504, 5, 'Nướng trong lò làm nóng trước cho đến khi khoai lang mềm, khoảng 40 phút. Thêm nho khô và mận khô. Tiếp tục nướng, đậy nắp cho đến khi nho khô và mận chín đều, khoảng 10 phút.', NULL, '2026-05-15 14:50:35', '2026-05-15 14:50:35'),
(3461, 505, 1, 'Trộn nước cốt chanh với ớt bột và hành đỏ trong một đĩa nông lớn. Chém mỗi đùi gà ba lần, sau đó cho vào nước cốt và để trong 10 phút.', NULL, '2026-05-15 14:50:36', '2026-05-15 14:50:36'),
(3462, 505, 2, 'Trộn tất cả nguyên liệu làm nước xốt với nhau và rưới lên gà. Trộn đều mọi thứ, sau đó đậy nắp và để lạnh ít nhất 1 giờ. Điều này có thể được thực hiện trước một ngày.', NULL, '2026-05-15 14:50:36', '2026-05-15 14:50:36'),
(3463, 505, 3, 'Làm nóng vỉ nướng. Nhấc miếng gà lên giá trên khay nướng. Phết một ít dầu lên và nướng trong 8 phút mỗi mặt hoặc cho đến khi cháy thành than nhẹ và chín hoàn toàn.', NULL, '2026-05-15 14:50:36', '2026-05-15 14:50:36'),
(3464, 506, 1, 'Làm nóng lò nướng ở nhiệt độ 350° F. Xịt dung dịch chống dính lên chảo nướng 9x13 inch.', NULL, '2026-05-15 14:50:37', '2026-05-15 14:50:37'),
(3465, 506, 2, 'Cho nước tương, ½ cốc nước, đường nâu, gừng và tỏi vào nồi nhỏ rồi đậy nắp. Đun sôi trên lửa vừa. Mở nắp và nấu trong một phút sau khi sôi.', NULL, '2026-05-15 14:50:37', '2026-05-15 14:50:37'),
(3466, 506, 3, 'Trong khi đó, khuấy đều tinh bột ngô và 2 thìa nước trong một đĩa riêng cho đến khi mịn. Sau khi nước sốt sôi, cho hỗn hợp vào nồi và khuấy đều. Nấu cho đến khi nước sốt bắt đầu đặc lại thì tắt bếp.', NULL, '2026-05-15 14:50:37', '2026-05-15 14:50:37'),
(3467, 506, 4, 'Đặt ức gà vào chảo đã chuẩn bị. Đổ một chén nước sốt lên trên thịt gà. Đặt gà vào lò nướng và nướng trong 35 phút hoặc cho đến khi chín. Lấy gà ra khỏi lò và xé thịt gà bằng hai chiếc nĩa.', NULL, '2026-05-15 14:50:37', '2026-05-15 14:50:37'),
(3468, 506, 5, '*Trong khi đó, hấp hoặc nấu rau theo hướng dẫn trên bao bì.', NULL, '2026-05-15 14:50:37', '2026-05-15 14:50:37'),
(3469, 506, 6, 'Cho rau và cơm đã nấu chín vào món thịt hầm cùng với thịt gà. Thêm phần lớn nước sốt còn lại, chừa lại một ít để rưới lên trên khi dùng. Nhẹ nhàng trộn tất cả mọi thứ vào đĩa thịt hầm cho đến khi hòa quyện. Quay trở lại lò nướng và nấu 15 phút. Lấy ra khỏi lò và để yên 5 phút trước khi dùng. Rắc từng khẩu phần với nước sốt còn lại. Thưởng thức!', NULL, '2026-05-15 14:50:37', '2026-05-15 14:50:37'),
(3471, 507, 1, 'Cho thịt gà, tỏi, gừng, hành tây, rau mùi và ớt vào máy xay thực phẩm và nêm đều. Đảo nhanh cho đến khi thịt gà được nghiền mịn và mọi thứ được trộn đều. Dùng tay tạo hình sáu chiếc bánh nhỏ.', NULL, '2026-05-15 14:50:38', '2026-05-16 12:35:34'),
(3473, 507, 2, 'Đun nóng dầu trong chảo, sau đó chiên bánh trên lửa vừa trong khoảng 6-8 phút, quay một lần. Ăn nóng với tương ớt ngọt, chanh, rau mùi, hành lá cắt nhỏ và ớt đỏ.', NULL, '2026-05-15 14:50:38', '2026-05-16 12:35:34'),
(3475, 508, 1, 'Làm nóng lò nướng ở mức quạt/khí 200C/180C 6 và lót giấy bạc vào khay nướng. Trộn nước sốt ớt với vỏ cam và nước ép, tỏi, bột cà ri và ¼ muỗng cà phê muối. Thêm thịt gà và áo thật kỹ.', NULL, '2026-05-15 14:50:40', '2026-05-16 12:35:34'),
(3477, 508, 2, 'Xếp các dùi trống lên giấy bạc, cách đều nhau. Phủ gà với phần nước xốt còn lại trong tô, sau đó nướng trong 35-40 phút cho đến khi mềm. Bọc trong giấy bạc hoặc đóng gói vào hộp đựng thực phẩm.', NULL, '2026-05-15 14:50:40', '2026-05-16 12:35:34'),
(3479, 509, 1, 'Đun nóng dầu trong chảo lớn nhất, cho hành tây vào xào trong 3 phút cho mềm. Thêm thịt gà và tỏi vào nấu cho đến khi gà đổi màu.', NULL, '2026-05-15 14:50:42', '2026-05-16 12:35:34'),
(3481, 509, 2, 'Thêm bột cà ri, nước cốt dừa, nước kho, lá chanh và nước mắm vào rồi đun nhỏ lửa trong 12 phút. Thêm hành tây xắt nhỏ, đậu xanh và măng vào nấu trong 4-6 phút cho đến khi đậu mềm.', NULL, '2026-05-15 14:50:42', '2026-05-16 12:35:34'),
(3483, 509, 3, 'Trong khi đó, cho nước cốt chanh và húng quế vào một cái bình hẹp và xay nhuyễn bằng máy xay cầm tay để tạo thành hỗn hợp sệt màu xanh mịn. Đổ súp với hành lá thái lát vào và đun nóng. Ăn kèm với chanh cho bữa trưa hoặc bữa tối nhẹ hoặc như một món khai vị chuẩn bị trước.', NULL, '2026-05-15 14:50:42', '2026-05-16 12:35:34'),
(3484, 510, 1, 'Cho khoai tây vào chảo nước sôi và nấu trong 5 phút. Cho đậu vào và nấu thêm 3 phút nữa, lúc đó cả hai chỉ mềm nhưng không quá mềm. Xả và đặt sang một bên.', NULL, '2026-05-15 14:50:43', '2026-05-15 14:50:43'),
(3485, 510, 2, 'Trong chảo hoặc chảo rán lớn, đun nóng dầu cho đến khi thật nóng, sau đó thả tỏi vào và chiên cho đến khi vàng, quá trình này chỉ mất vài giây. Đừng để nó quá tối nếu không nó sẽ làm hỏng hương vị. Múc bột cà ri vào và khuấy đều trong vài giây để bắt đầu nấu gia vị và giải phóng hết hương vị. Tiếp theo, đổ nước cốt dừa vào và tạo bọt.', NULL, '2026-05-15 14:50:43', '2026-05-15 14:50:43'),
(3486, 510, 3, 'Khuấy nước mắm và đường, sau đó cho miếng thịt gà vào. Vặn lửa nhỏ xuống và nấu, đậy nắp trong khoảng 8 phút cho đến khi gà chín.', NULL, '2026-05-15 14:50:43', '2026-05-15 14:50:43'),
(3487, 510, 4, 'Cho khoai tây và đậu vào rồi để ấm trong nước cốt dừa nóng, sau đó thêm hương vị cam quýt đáng yêu bằng cách cho lá chanh cắt nhỏ (hoặc vỏ chanh) vào khuấy đều. Tiếp theo cho lá húng quế vào nhưng chỉ để trên lửa một thời gian ngắn nếu không chúng sẽ nhanh chóng mất đi độ tươi. Rắc chanh trang trí và dùng ngay với cơm luộc.', NULL, '2026-05-15 14:50:43', '2026-05-15 14:50:43'),
(3489, 511, 1, 'Đổ nước luộc gà và nước cốt dừa vào nồi lớn đặt trên lửa vừa. Cho riềng, sả và lá chanh vào rồi đun nhỏ lửa khoảng 6-8 phút. Giữ lửa nhỏ, thêm thịt gà vào. Nấu trong 8-10 phút cho đến khi mềm và chín.', NULL, '2026-05-15 14:50:44', '2026-05-16 12:35:34'),
(3491, 511, 2, 'Khuấy nấm và ớt rồi đun nhỏ lửa thêm 3-5 phút nữa cho đến khi mọi thứ chín đều. Rắc đường và 3 muỗng canh nước mắm và nước cốt chanh vào. Hương vị và thêm phần còn lại nếu cần.', NULL, '2026-05-15 14:50:44', '2026-05-16 12:35:34'),
(3493, 511, 3, 'Dùng thìa có rãnh loại bỏ riềng, sả và lá chanh trước khi dùng. Múc ra bát và dùng kèm với lá ngò rắc lên trên và cơm hấp đặt bên cạnh. Sẽ giữ lạnh lên đến ba ngày. Để nguội trước.', NULL, '2026-05-15 14:50:44', '2026-05-16 12:35:34'),
(3494, 512, 1, 'Cắt gà thành từng miếng vừa ăn. Gọt vỏ và cắt hành tây, băm tỏi.', NULL, '2026-05-15 14:50:46', '2026-05-15 14:50:46'),
(3495, 512, 2, 'Tập hợp các nguyên liệu còn lại và bạn đã sẵn sàng bắt đầu nấu ăn.', NULL, '2026-05-15 14:50:46', '2026-05-15 14:50:46'),
(3496, 512, 3, 'Làm món ăn', NULL, '2026-05-15 14:50:46', '2026-05-15 14:50:46'),
(3497, 512, 4, 'Làm nóng chảo rán trên lửa vừa. Thêm dầu vào và khi nóng, xào hành tây cho đến khi trong suốt. Lấy ra khỏi chảo và chuyển vào máy xay hoặc máy chế biến thực phẩm.', NULL, '2026-05-15 14:50:46', '2026-05-15 14:50:46'),
(3498, 512, 5, 'Thêm cà chua, tỏi, nghệ, thì là, đường, bột gừng, nước cốt dừa, nước và trộn đều.', NULL, '2026-05-15 14:50:46', '2026-05-15 14:50:46'),
(3499, 512, 6, 'Trong cùng một chảo bạn nấu hành tây, thêm thịt gà và chiên vàng tất cả các mặt. Quá trình này sẽ mất khoảng 3 phút.', NULL, '2026-05-15 14:50:46', '2026-05-15 14:50:46'),
(3500, 512, 7, 'Cho nguyên liệu máy xay và lá nguyệt quế vào chảo, đun nhỏ lửa và nấu cho đến khi thịt gà có màu trắng bên trong và nước sánh như kem. (15 đến 20 phút)', NULL, '2026-05-15 14:50:46', '2026-05-15 14:50:46'),
(3501, 512, 8, 'Loại bỏ lá nguyệt quế và dùng với cơm trắng.', NULL, '2026-05-15 14:50:46', '2026-05-15 14:50:46'),
(3503, 513, 1, 'Để làm nước sốt, trộn tất cả nguyên liệu lại với nhau trong một tô lớn. Luộc mì theo hướng dẫn trên bao bì, sau đó để ráo nước và cho vào tô cùng với nước sốt.', NULL, '2026-05-15 14:50:47', '2026-05-16 12:35:34'),
(3505, 513, 2, 'Gọt vỏ cà rốt thành dải dài bằng dụng cụ gọt rau. Làm tương tự với dưa chuột cho đến khi lấy được hạt (bỏ hạt). Thêm cà rốt và dưa chuột vào hỗn hợp mì cùng với thịt gà xé nhỏ, củ cải, hành tím và bạc hà. Trộn đều để phủ đều nước sốt, rắc lên đậu phộng và thưởng thức.', NULL, '2026-05-15 14:50:47', '2026-05-16 12:35:34'),
(3507, 514, 1, 'Gọt vỏ và bỏ phần lớn tôm (người bán cá có thể làm việc này cho bạn), giữ lại một ít nguyên con để trang trí, nếu bạn thích. Đun nóng dầu ô liu trong chảo rán lớn hoặc nồi chống cháy nông trên lửa vừa và nhỏ và xào hành tây trong 5 phút cho đến khi mềm. Thêm lá nguyệt quế, nghệ tây, gạo và cà chua xay nhuyễn vào nấu thêm 1-2 phút nữa, khuấy đều.', NULL, '2026-05-15 14:50:48', '2026-05-16 12:35:34'),
(3509, 514, 2, 'Đổ rượu và bong bóng vào trong 1-2 phút, sau đó đổ nước luộc hải sản và 150ml nước vào. Nấu trong 5 phút, sau đó thêm mực, nêm đều và khuấy đều. Đun sôi, sau đó đậy nắp và giảm nhiệt cho sôi nhẹ. Nấu thêm 12 phút nữa, thêm một chút nước nếu hỗn hợp bắt đầu khô.', NULL, '2026-05-15 14:50:48', '2026-05-16 12:35:34'),
(3511, 514, 3, 'Mở chảo và đảo đều tôm đã bóc vỏ, sau đó xếp tôm nguyên con lên trên hỗn hợp cơm. Đậy nắp lại và đun nhỏ lửa thêm 5-6 phút cho đến khi tôm có màu hồng và chín. Để yên trong vài phút trước khi phục vụ từ chảo.', NULL, '2026-05-15 14:50:48', '2026-05-16 12:35:34'),
(3512, 515, 1, 'Làm nóng lò ở 180C/quạt 160C/gas 4. Cắt bỏ lá thì là và đặt sang một bên. Cắt củ thì là làm đôi, sau đó cắt mỗi nửa thành 3 miếng. Luộc trong nước muối sôi khoảng 10 phút rồi vớt ra để ráo nước. Cắt nhỏ lá thì là, sau đó trộn với rau mùi tây và vỏ chanh.', NULL, '2026-05-15 14:50:50', '2026-05-15 14:50:50'),
(3513, 515, 2, 'Trải cây thì là đã ráo nước lên một đĩa nông chịu nhiệt, sau đó cho cà chua vào. Rưới dầu ô liu lên, sau đó nướng trong 10 phút. Nhúng cá hồi vào trong rau, rắc nước cốt chanh, sau đó nướng thêm 15 phút nữa cho đến khi cá vừa chín. Rắc lên rau mùi tây và thưởng thức.', NULL, '2026-05-15 14:50:50', '2026-05-15 14:50:50'),
(3515, 516, 1, 'Luộc mì theo hướng dẫn trên bao bì, sau đó rửa sạch dưới nước lạnh và để ráo nước. Trong một cái chảo nhỏ, đun chảy bơ đậu phộng, nước cốt dừa, tương ớt ngọt và một nửa số hành lá, thêm 1-2 muỗng canh nước để hỗn hợp được sệt lại.', NULL, '2026-05-15 14:50:51', '2026-05-16 12:35:34'),
(3517, 516, 2, 'Trộn mì, dưa chuột và giá đỗ vào đĩa phục vụ. Xếp tôm lên trên, rưới nước sốt đậu phộng và rải lên số hành lá còn lại.', NULL, '2026-05-15 14:50:51', '2026-05-16 12:35:34'),
(3519, 517, 1, 'Cho tất cả các nguyên liệu làm nước sốt vào máy xay thực phẩm với một chút muối và xay nhuyễn để làm nước sốt. Cắt cá ba lần mỗi mặt, phủ một nửa nước sốt rồi để ướp trong khoảng 30 phút.', NULL, '2026-05-15 14:50:52', '2026-05-16 12:35:34'),
(3521, 517, 2, 'Làm nóng lò ở 220C/quạt 200C/gas 7. Đặt cá lên khay nướng rồi cho vào lò nướng khoảng 20 phút cho đến khi thịt săn chắc và mắt cá chuyển sang màu trắng. Ăn cá với phần nước sốt còn lại và couscous hấp hoặc cơm.', NULL, '2026-05-15 14:50:52', '2026-05-16 12:35:34'),
(3523, 517, 3, 'BIẾT CÁCH: CÁCH NẤU: Nấu cá chẽm nguyên xương, như chúng tôi đã làm ở đây, có những ưu điểm – nó sẽ giữ ẩm hơn trong khi nấu và một số người sẽ nói rằng hương vị cũng được tăng cường. Nếu bạn muốn lấy xương ra, chúng sẽ dễ dàng tìm thấy và ít có khả năng mắc vào phi lê nếu cá được nấu chín nguyên con. Phi lê có thể được chiên hoặc nướng đơn giản. Nếu bạn thích cá hồi, bạn sẽ thực sự thích hương vị của cá chẽm, vốn có nguyên liệu và phương pháp nấu tương tự – hương vị cam quýt đặc biệt ngon, cũng như tỏi và nấm dại. Đơn giản chỉ cần nướng cá với một số loại thảo mộc tươi, dầu ô liu và gia vị là ngon, và trong những tháng hè, bạn cũng có thể nướng cá. Một thứ mà bạn không thể bỏ qua là má hoặc \'ngọc trai\' của cá, chúng đơn giản là đáng yêu, ẩm ướt và thực sự ngọt ngào - rất đáng để bạn chú ý tới!', NULL, '2026-05-15 14:50:52', '2026-05-16 12:35:34'),
(3524, 518, 1, 'Nấu với gia vị cajun và nước xốt ớt cayenne làm cho món cá này trở nên siêu mọng nước và thơm ngon. Phủ lên trên một lớp nước sốt thơm ngon và dùng kèm bánh tortilla để có món chính nhanh chóng, không cầu kỳ, mang đến một mùa hè thú vị.', NULL, '2026-05-15 14:50:53', '2026-05-15 14:50:53'),
(3525, 518, 2, 'Trên một đĩa lớn, trộn gia vị cajun và ớt cayenne với một ít gia vị rồi phết đều khắp cá.', NULL, '2026-05-15 14:50:53', '2026-05-15 14:50:53'),
(3526, 518, 3, 'Đun nóng một ít dầu trong chảo, cho cá vào chiên ở lửa vừa cho đến khi chín vàng. Giảm nhiệt và tiếp tục chiên cho đến khi cá chín, khoảng 10 phút. Nấu theo mẻ nếu bạn không có đủ chỗ trong chảo.', NULL, '2026-05-15 14:50:53', '2026-05-15 14:50:53'),
(3527, 518, 4, 'Trong khi đó, chuẩn bị nước sốt bằng cách kết hợp tất cả nguyên liệu với một ít gia vị.', NULL, '2026-05-15 14:50:53', '2026-05-15 14:50:53'),
(3528, 518, 5, 'Làm mềm bánh ngô bằng cách hâm nóng trong lò vi sóng trong 5-10 giây. Xếp cao bơ, rau diếp và hành lá, thêm một thìa salsa, phủ những miếng cá lớn lên trên và rưới lên nước sốt.', NULL, '2026-05-15 14:50:53', '2026-05-15 14:50:53'),
(3530, 519, 1, 'Chiên chorizo ​​trong chảo lớn có nắp, trên lửa vừa cho đến khi nó bắt đầu giòn và tiết ra dầu. Thêm hành tây và nấu trong 5 phút cho đến khi bắt đầu mềm. Sau đó thêm tỏi và rau mùi tây thái nhỏ vào xào thêm 1 phút nữa.', NULL, '2026-05-15 14:50:54', '2026-05-16 12:35:34'),
(3532, 519, 2, 'Đổ nước kho và cà chua vào. Đun sôi, giảm nhiệt, sau đó thêm đậu và giấm sherry. Đun nhỏ lửa trong 10 phút cho đến khi chất lỏng giảm nhẹ.', NULL, '2026-05-15 14:50:54', '2026-05-16 12:35:34'),
(3534, 519, 3, 'Rải đều lên nghêu, đậy nắp và hấp trong 2-4 phút, thỉnh thoảng lắc chảo cho đến khi nghêu mở miệng. Hãy nếm thử một chút trước khi nêm gia vị vì nghêu có thể khá mặn. Sau đó rắc lên rau mùi tây cắt nhỏ. Ăn với nhiều bánh mì giòn.', NULL, '2026-05-15 14:50:54', '2026-05-16 12:35:34'),
(3535, 520, 1, 'Làm nước xốt:', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3536, 520, 2, 'Trong một chảo nhỏ, cho nước luộc thịt bò, nước tương, rượu Thiệu Hưng, dầu hào và bột tiêu trắng vào chảo trên lửa vừa. Đánh đều và đun sôi.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3537, 520, 3, 'Cho bột ngô và nước vào tô nhỏ rồi khuấy đều cho tan. Thêm vào chảo và đánh cho đến khi nước sốt đặc lại và phủ lên mặt sau của thìa, từ 2 đến 3 phút. Đậy nắp chảo và giữ ấm ở nhiệt độ thấp nhất có thể.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3538, 520, 4, 'Làm bột bánh non trứng foo:', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3539, 520, 5, 'Trong một tô vừa, trộn bột ngô và nước cho đến khi hòa tan. Thêm trứng, muối và đường. Đánh đều cho đến khi hòa quyện và không còn vón cục lòng trắng trứng.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3540, 520, 6, 'Thêm hành lá, giá đỗ và tôm. Khuấy đều cho đến khi mọi thứ được phủ đều.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3541, 520, 7, 'Chiên trứng foo non:', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3542, 520, 8, 'Cho dầu thực vật vào chảo lớn; nó sẽ cao khoảng 2 inch ở hai bên. Đun nóng dầu trên lửa vừa cao đến 350°F hoặc cho đến khi hình thành bong bóng mạnh xung quanh chiếc đũa gỗ được nhét vào.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3543, 520, 9, 'Dùng một cái muôi, nhẹ nhàng và từ từ thêm 1/4 lượng bột trứng ốp la. Trứng foo non sẽ lập tức sủi bọt và phồng lên như có phép thuật. Chiên cho đến khi có màu vàng nâu và giòn ở mỗi mặt, khoảng 2 phút mỗi mặt. Nếu có đốm nhạt thì dùng muôi phết nhẹ với dầu nóng.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3544, 520, 10, 'Trứng foo non có thể hơi khó lật. Phương pháp đơn giản nhất là đặt một dụng cụ vào mỗi tay (một con nhện, thìa có rãnh, kẹp và đũa lớn đều là những ứng cử viên phù hợp) và nhẹ nhàng dỗ món trứng tráng qua, kéo lên một bên và đẩy xuống xung quanh mặt kia.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3545, 520, 11, 'Lấy trứng tráng ra và đặt nó lên khay nướng có lót khăn giấy. Để nguội trong 5 phút. Trong khi đó, lặp lại với phần bột còn lại để làm 4 món trứng tráng. Nếu cần, hãy thêm dầu vào chảo giữa các mẻ.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3546, 520, 12, 'Phục vụ và thưởng thức:', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3547, 520, 13, 'Xếp từng quả trứng non lên trên một lớp cơm. Rưới nước sốt ấm lên trên và dùng ngay.', NULL, '2026-05-15 14:50:55', '2026-05-15 14:50:55'),
(3548, 521, 1, 'Rửa sạch cá; chà xát với chanh hoặc chanh, nêm muối và hạt tiêu hoặc sử dụng gia vị yêu thích của bạn. Tôi đã sử dụng gia vị creole. Đặt sang một bên hoặc cho vào lò nướng để giữ ấm cho đến khi nước sốt sẵn sàng.', NULL, '2026-05-15 14:50:56', '2026-05-15 14:50:56'),
(3549, 521, 2, 'Trong chảo lớn, đun nóng dầu trên lửa vừa, cho đến khi nóng, cho cá vào chiên mỗi mặt trong khoảng 5-7 phút cho đến khi chín và giòn cả hai mặt. Lấy cá ra và đặt sang một bên. Xả dầu và để lại khoảng 2-3 muỗng canh dầu', NULL, '2026-05-15 14:50:56', '2026-05-15 14:50:56'),
(3550, 521, 3, 'Thêm lá nguyệt quế, tỏi và gừng vào xào khoảng một phút để đảm bảo tỏi không bị cháy', NULL, '2026-05-15 14:50:56', '2026-05-15 14:50:56'),
(3551, 521, 4, 'Sau đó thêm hành tây, ớt chuông, húng tây, rượu Scotch, đường, tất cả gia vị - tiếp tục khuấy trong khoảng 2-3 phút. Thêm giấm, trộn muối và tiêu điều chỉnh theo sở thích. Để lửa nhỏ thêm khoảng 2 phút nữa.', NULL, '2026-05-15 14:50:56', '2026-05-15 14:50:56'),
(3552, 521, 5, 'Bỏ lá nguyệt quế, lá húng tây và dùng kèm với cá với một bên của miếng thịt bammy này. Bạn có thể làm nước sốt trước khoảng 2 ngày.', NULL, '2026-05-15 14:50:56', '2026-05-15 14:50:56'),
(3553, 522, 1, 'BƯỚC 1', NULL, '2026-05-15 14:50:57', '2026-05-15 14:50:57'),
(3554, 522, 2, 'Cho cá vào chảo có nắp đậy và đổ lượng nước vừa đủ. Đun sôi và đun nhẹ trong 10 phút ở lửa nhỏ và đậy nắp. Xả và vẩy cá.', NULL, '2026-05-15 14:50:57', '2026-05-15 14:50:57'),
(3555, 522, 3, 'BƯỚC 2', NULL, '2026-05-15 14:50:57', '2026-05-15 14:50:57'),
(3556, 522, 4, 'Cho cá, khoai tây, ớt xanh, rau mùi, thì là, tiêu đen, tỏi và gừng vào tô lớn. Nêm gia vị, thêm bột gạo vào, trộn đều và đập 1 quả trứng vào. Khuấy hỗn hợp và chia thành 15, sau đó vo thành từng khúc nhỏ. Đập những quả trứng còn lại vào tô và đánh nhẹ. Cho vụn bánh mì vào một cái bát khác. Nhúng từng fofo vào trứng đã đánh, sau đó là hỗn hợp vụn bánh mì. Thư giãn trong 20 phút.', NULL, '2026-05-15 14:50:57', '2026-05-15 14:50:57'),
(3557, 522, 5, 'BƯỚC 3', NULL, '2026-05-15 14:50:57', '2026-05-15 14:50:57'),
(3558, 522, 6, 'Đun nóng 1cm dầu trong chảo lớn trên lửa vừa. Chiên fofos theo từng mẻ trong 2 phút mỗi mặt, lật nhẹ để có màu nâu vàng đều. Xả trên giấy ăn và lặp lại với fofos còn lại.', NULL, '2026-05-15 14:50:57', '2026-05-15 14:50:57'),
(3559, 522, 7, 'BƯỚC 4', NULL, '2026-05-15 14:50:57', '2026-05-15 14:50:57'),
(3560, 522, 8, 'Đối với món salad hành tây, trộn hành tây, rau mùi và nước cốt chanh với một chút muối. Ăn kèm với fofos và tương ớt xoài.', NULL, '2026-05-15 14:50:57', '2026-05-15 14:50:57'),
(3561, 523, 1, '01. Cho khoai tây vào chảo nước muối lạnh lớn và đun sôi. Giảm nhiệt, đậy nắp, sau đó đun nhỏ lửa trong 15 phút cho đến khi mềm. Xả sạch, sau đó cho trở lại chảo ở lửa nhỏ trong 30 giây để loại bỏ lượng nước dư thừa. Nghiền với 1 muỗng canh dầu ô liu, sau đó nêm gia vị.', NULL, '2026-05-15 14:50:58', '2026-05-15 14:50:58'),
(3562, 523, 2, '02.Trong lúc đó, cho sữa vào chảo xào lớn, cho cá vào và đun sôi. Tắt bếp, đậy nắp và để yên trong 3 phút. Lấy cá ra (dành riêng sữa) và lau khô bằng giấy ăn, sau đó nhẹ nhàng cho vào đĩa chịu nhiệt, loại bỏ da và xương.', NULL, '2026-05-15 14:50:58', '2026-05-15 14:50:58'),
(3563, 523, 3, '03. Đun nóng lượng dầu còn lại trong chảo, cho bột mì vào khuấy đều và nấu trong 30 giây. Khuấy dần dần 200-250ml sữa dự trữ (bỏ phần còn lại). Nghiền hạt nhục đậu khấu, nêm gia vị, sau đó sủi bọt cho đến khi đặc lại. Khuấy kem.', NULL, '2026-05-15 14:50:58', '2026-05-15 14:50:58'),
(3564, 523, 4, '04. Làm nóng lò ở 190°C/quạt170°C/gas 5. Bào atisô và thêm vào món ăn cùng tỏi tây, tôm và rau thơm. Khuấy vỏ chanh và nước cốt vào nước sốt, sau đó rưới lên. Trộn nhẹ nhàng bằng thìa gỗ.', NULL, '2026-05-15 14:50:58', '2026-05-15 14:50:58'),
(3565, 523, 5, '05. Đổ hỗn hợp nhuyễn lên hỗn hợp cá, sau đó dùng nĩa tạo thành các đỉnh, sẽ giòn và có màu nâu khi nấu. Rắc phô mai lên, sau đó nướng trong 35-40 phút cho đến khi vàng và sủi bọt. Ăn kèm với rau xanh héo.', NULL, '2026-05-15 14:50:58', '2026-05-15 14:50:58'),
(3566, 524, 1, 'Trong nồi vừa, đun nóng dầu ô liu trên lửa vừa cao. Thêm hành vào và nấu, thỉnh thoảng khuấy cho đến khi hành bắt đầu chuyển sang màu caramen. Thêm cà rốt và nấu cho đến khi cà rốt bắt đầu mềm, khoảng 4 phút nữa.', NULL, '2026-05-15 14:51:00', '2026-05-15 14:51:00'),
(3567, 524, 2, 'Thêm nước kho, nước, khoai tây, lá nguyệt quế và hạt tiêu đen. Nêm muối và đun sôi. Giảm nhiệt, đậy nắp và nấu trong 10 phút. Thêm kê và nấu thêm 15 phút nữa cho đến khi kê và khoai tây chín.', NULL, '2026-05-15 14:51:00', '2026-05-15 14:51:00'),
(3568, 524, 3, 'Nhẹ nhàng thêm các khối cá vào. Khuấy và đun sôi súp. Cá sẽ chín rất nhanh nên đừng để cá chín quá. Chúng được thực hiện khi thịt có màu đục và dễ bong ra.', NULL, '2026-05-15 14:51:00', '2026-05-15 14:51:00'),
(3569, 524, 4, 'Trang trí súp với thì là tươi hoặc rau mùi tây cắt nhỏ trước khi dùng.', NULL, '2026-05-15 14:51:00', '2026-05-15 14:51:00'),
(3570, 525, 1, 'Xoay đầu tôm, sau đó bóc bỏ phần chân và vỏ nhưng giữ nguyên phần đuôi. Lọc bỏ từng con tôm. Chiên vỏ trong 1 muỗng canh dầu trong 5 phút cho đến khi có màu hồng đậm và vàng từng mảng. Thêm rượu vào, đun sôi khoảng 2/3 rồi đổ nước kho vào. Lọc vào bình, loại bỏ vỏ.', NULL, '2026-05-15 14:51:01', '2026-05-15 14:51:01'),
(3571, 525, 2, 'Đun nóng phần dầu còn lại trong chảo hoặc chảo sâu lòng. Thêm thì là, hành tây và tỏi vào, nêm gia vị rồi đậy nắp và nấu nhẹ trong 10 phút cho đến khi mềm. Trong khi đó, gọt vỏ khoai tây và cắt thành khối khoảng 2cm. Cho vào chảo nước lạnh, đun sôi và nấu trong 5 phút cho đến khi gần mềm. Xả trong một cái chao.', NULL, '2026-05-15 14:51:01', '2026-05-15 14:51:01'),
(3572, 525, 3, 'Gọt một dải vỏ từ quả cam. Cho vỏ, hoa hồi, nguyệt quế và ½ thìa cà phê harissa vào chảo. Chiên nhẹ nhàng, không đậy nắp trong 5-10 phút cho đến khi rau mềm, ngọt và vàng.', NULL, '2026-05-15 14:51:01', '2026-05-15 14:51:01'),
(3573, 525, 4, 'Khuấy nhuyễn cà chua, nấu trong 2 phút, sau đó thêm cà chua và kho. Đun nhỏ lửa trong 10 phút cho đến khi nước sốt đặc lại một chút. Nêm nếm vừa miệng. Nước sốt có thể được làm trước và hâm nóng lại sau đó trong ngày. Trong khi đó, hãy chà sạch trai hoặc nghêu và nhổ bỏ những sợi râu xơ xác. Bất kỳ cái gì đang mở phải được gõ mạnh lên mặt bàn - nếu chúng không đóng lại sau vài giây, hãy loại bỏ chúng.', NULL, '2026-05-15 14:51:01', '2026-05-15 14:51:01'),
(3574, 525, 5, 'Đun lại nước sốt nếu cần, sau đó khuấy nhẹ nhàng khoai tây, từng miếng cá và tôm vào hầm. Đun sôi trở lại, sau đó đậy nắp và đun nhỏ lửa trong 3 phút. Rải trai hoặc nghêu lên trên món hầm, sau đó đậy nắp và nấu thêm 2 phút hoặc cho đến khi vỏ mở rộng. Loại bỏ bất kỳ cái gì vẫn đóng. Các miếng cá sẽ bong ra dễ dàng và tôm sẽ có màu hồng. Rắc lá húng tây.', NULL, '2026-05-15 14:51:01', '2026-05-15 14:51:01'),
(3575, 525, 6, 'Để làm món cuộn nhanh, hãy khuấy phần còn lại của món harissa qua sốt mayonnaise. Dọn món hầm ra bát, phủ lên trên một thìa bột rouille sẽ tan vào nước sốt và làm đậm đà nước sốt. Chuẩn bị sẵn một ít bánh mì ngon vì bạn chắc chắn sẽ muốn lau sạch nước trái cây.', NULL, '2026-05-15 14:51:01', '2026-05-15 14:51:01'),
(3576, 526, 1, 'Cắt phi lê cá thành khối hoặc dải. Nghiền hoặc băm tỏi. Rửa sạch rau và cắt thành dải mỏng.', NULL, '2026-05-15 14:51:03', '2026-05-15 14:51:03'),
(3577, 526, 2, 'Đun nóng bơ trong nồi và thêm tỏi. Khi tỏi bắt đầu chuyển sang màu vàng, thêm bột mì vào, đánh đều.', NULL, '2026-05-15 14:51:03', '2026-05-15 14:51:03'),
(3578, 526, 3, 'Thêm nước luộc cá vào và tiếp tục đánh cho đến khi không còn vón cục.', NULL, '2026-05-15 14:51:03', '2026-05-15 14:51:03'),
(3579, 526, 4, 'Thêm rau và sữa vào rồi đun sôi. Nấu trong khoảng 10 phút.', NULL, '2026-05-15 14:51:03', '2026-05-15 14:51:03'),
(3580, 526, 5, 'Thêm crème fraîche (hoặc kem chua). Đun sôi súp trở lại và khi súp bắt đầu sủi bọt trở lại thì tắt lửa. Giữ súp trên bếp và thêm cá. Để cá nấu trong súp nóng trong 5 phút. Nếu sử dụng tôm, hãy thêm ngay trước khi dùng.', NULL, '2026-05-15 14:51:03', '2026-05-15 14:51:03'),
(3581, 526, 6, 'Rắc hẹ (hoặc thì là hoặc mùi tây) trước khi dùng.', NULL, '2026-05-15 14:51:03', '2026-05-15 14:51:03'),
(3583, 527, 1, 'Cắt mực thành từng khoanh dày khoảng ½cm. Đổ bột vào túi đông lạnh và nêm đều. Thêm nụ bạch hoa, sau đó lắc đều để trộn đều. Đổ mực vào túi, sau đó lắc lại cho đến khi tất cả các vòng đều được phủ đều. Trộn tỏi và sốt mayonnaise với nhau, sau đó cho vào tô phục vụ.', NULL, '2026-05-15 14:51:04', '2026-05-16 12:35:34'),
(3585, 527, 2, 'Đổ một ít dầu vào chảo lớn cho đến khi ngập các cạnh khoảng 7cm, nhưng chảo không đầy quá một phần ba. Đặt trên lửa vừa và để dầu nóng lên. Để kiểm tra xem dầu đã sẵn sàng hay chưa, hãy đặt một miếng bánh mì nhỏ vào chảo – nó sẽ kêu xèo xèo khi chạm vào dầu.', NULL, '2026-05-15 14:51:04', '2026-05-16 12:35:34'),
(3587, 527, 3, 'Lấy một nắm mực ra khỏi bột và rũ bỏ phần thừa. Nhẹ nhàng thả vào dầu rồi chiên khoảng 3 phút cho đến khi giòn. Lấy thìa có rãnh ra và đặt lên giấy ăn. Lặp lại với con mực còn lại. Ăn ngay với sốt mayonnaise và chanh.', NULL, '2026-05-15 14:51:04', '2026-05-16 12:35:34'),
(3589, 528, 1, 'Đun nóng dầu ô liu trong chảo rán lớn. Cho các lát tỏi vào và nấu trong vài giây. Sau đó đảo tôm và nấu trong vài phút cho đến khi chúng bắt đầu chuyển sang màu hồng.', NULL, '2026-05-15 14:51:06', '2026-05-16 12:35:34'),
(3591, 528, 2, 'Đổ rượu sherry lên và nấu thêm vài phút nữa cho đến khi tôm chín. Rắc rau mùi tây trước khi phục vụ.', NULL, '2026-05-15 14:51:06', '2026-05-16 12:35:34'),
(3592, 529, 1, 'BƯỚC 1', NULL, '2026-05-15 14:51:07', '2026-05-15 14:51:07'),
(3593, 529, 2, 'Cho tất cả nguyên liệu trừ cá mòi vào tô và trộn cùng với một ít gia vị. Đổ vào đĩa nướng, thêm cá mòi và đảo thật đều. Che và thư giãn trong vài giờ.', NULL, '2026-05-15 14:51:07', '2026-05-15 14:51:07'),
(3594, 529, 3, 'BƯỚC 2', NULL, '2026-05-15 14:51:07', '2026-05-15 14:51:07'),
(3595, 529, 4, 'Đun nóng chảo BBQ hoặc vỉ nướng cho đến khi nóng. Nấu cá mòi trong 4-5 phút mỗi bên hoặc cho đến khi thực sự có màu caramen và cháy thành than. Cho ra đĩa, rưới dầu, rắc thêm một ít ớt bột và vắt lên chanh.', NULL, '2026-05-15 14:51:07', '2026-05-15 14:51:07'),
(3596, 530, 1, 'Trộn tất cả nguyên liệu trong Honey Teriyaki Glaze lại với nhau. Đánh đều để trộn đều. Kết hợp cá hồi và Glaze với nhau.', NULL, '2026-05-15 14:51:08', '2026-05-15 14:51:08'),
(3597, 530, 2, 'Đun nóng chảo ở lửa vừa và nhỏ. Thêm dầu vào, chiên cá hồi hai mặt cho đến khi chín hoàn toàn bên trong và lớp men dày lên.', NULL, '2026-05-15 14:51:08', '2026-05-15 14:51:08'),
(3598, 530, 3, 'Trang trí với vừng và dùng ngay.', NULL, '2026-05-15 14:51:08', '2026-05-15 14:51:08'),
(3599, 531, 1, 'Nêm tôm với 1 thìa canh bột cà ri và gia vị đa năng rồi để riêng trong khoảng 10 phút trong khi chuẩn bị các nguyên liệu khác như cắt hành, ớt và tỏi.', NULL, '2026-05-15 14:51:10', '2026-05-15 14:51:10'),
(3600, 531, 2, 'Đun nóng 2 muỗng canh dầu ô liu trong chảo lớn trên lửa vừa. Thêm hành tây vàng thái lát, ớt chuông đỏ, ớt chuông xanh, ớt chuông Scotch, nếu dùng, tỏi băm nhỏ và khuấy trong 5 phút cho đến khi ớt hơi mềm.', NULL, '2026-05-15 14:51:10', '2026-05-15 14:51:10'),
(3601, 531, 3, 'Thêm 1,5 muỗng canh bột cà ri vào chảo và khuấy thêm một phút.', NULL, '2026-05-15 14:51:10', '2026-05-15 14:51:10'),
(3602, 531, 4, 'Sau đó thêm nước cốt dừa, tôm tẩm gia vị, sốt cà chua và húng tây vào, đảm bảo tôm được bao phủ trong nước sốt.', NULL, '2026-05-15 14:51:10', '2026-05-15 14:51:10'),
(3603, 531, 5, 'Để nước sốt sôi liu riu và tiếp tục nấu ở lửa vừa, thỉnh thoảng khuấy đều và lật tôm nửa chừng cho đến khi tôm chín hoàn toàn cả hai mặt. Quá trình này sẽ mất khoảng 5-6 phút. Muối và hạt tiêu cho vừa ăn.', NULL, '2026-05-15 14:51:10', '2026-05-15 14:51:10'),
(3604, 532, 1, 'Trong một bát vừa, kết hợp tôm với ớt Scotch Bonnet băm nhỏ, gia vị đa năng, điều màu xay và hạt tiêu xay. Đảo đều để thịt thấm đều và để ướp trong 10 phút.', NULL, '2026-05-15 14:51:11', '2026-05-15 14:51:11'),
(3605, 532, 2, 'Đun nóng chảo lớn trên lửa vừa. Thêm nước luộc tôm vào và đun nhỏ lửa. Cho hành và tỏi thái hạt lựu vào, nấu cho đến khi mềm và có mùi thơm, khoảng 2 phút.', NULL, '2026-05-15 14:51:11', '2026-05-15 14:51:11'),
(3606, 532, 3, 'Thêm tôm đã nêm gia vị và nhánh húng tây vào, phết tôm vào chảo. Đậy nắp và nấu trong khoảng 5–7 phút, thỉnh thoảng khuấy đều cho đến khi tôm chuyển sang màu cam sáng và chín đều.', NULL, '2026-05-15 14:51:11', '2026-05-15 14:51:11'),
(3607, 532, 4, 'Thêm giấm trắng, khuấy đều và nấu thêm một phút nữa. Nếm; thêm muối cho vừa ăn. Dùng thìa có rãnh chuyển tôm vào đĩa. Dùng nóng với một ít nước nấu rưới lên trên.', NULL, '2026-05-15 14:51:11', '2026-05-15 14:51:11'),
(3608, 533, 1, 'Trộn bột ngô và 1 muỗng canh nước tương, cho tôm vào và để yên trong 10 phút. Khuấy giấm, nước tương còn lại, cà chua xay nhuyễn, đường và 2 muỗng canh nước với nhau để làm nước sốt.', NULL, '2026-05-15 14:51:12', '2026-05-15 14:51:12'),
(3609, 533, 2, 'Khi bạn đã sẵn sàng nấu, hãy làm nóng chảo rán hoặc chảo lớn cho đến khi thật nóng, sau đó thêm 1 muỗng canh dầu. Chiên tôm cho đến khi chúng vàng vài chỗ và nở ra – sau đó vớt tôm ra khỏi chảo.', NULL, '2026-05-15 14:51:12', '2026-05-15 14:51:12'),
(3610, 533, 3, 'Đun nóng phần dầu còn lại rồi cho đậu phộng, ớt và hạt dẻ nước vào. Xào trong 2 phút hoặc cho đến khi đậu phộng bắt đầu chuyển màu, sau đó thêm gừng và tỏi vào xào thêm 1 phút nữa. Cho tôm và nước sốt vào đun nhỏ lửa trong 2 phút cho đến khi hơi đặc lại. Ăn kèm cơm.', NULL, '2026-05-15 14:51:12', '2026-05-15 14:51:12'),
(3611, 534, 1, 'Đun nóng dầu trong chảo vừa và thêm ớt. Nấu trong 1 phút, sau đó thêm bột cà ri vào, khuấy đều và nấu thêm 1 phút nữa. Hòa tan viên nước kho trong bình lớn với 700ml nước sôi, sau đó đổ vào chảo và khuấy đều. Đổ nước cốt dừa vào và đun sôi.', NULL, '2026-05-15 14:51:13', '2026-05-15 14:51:13'),
(3612, 534, 2, 'Thêm nước mắm và một ít gia vị. Cho mì vào nấu thêm 3-4 phút cho mì mềm. Vắt nước cốt chanh vào, thêm tôm vào và nấu cho đến khi ấm, khoảng 2-3 phút. Rắc một ít rau mùi lên trên.', NULL, '2026-05-15 14:51:13', '2026-05-15 14:51:13'),
(3613, 534, 3, 'Bày ra bát với phần rau mùi và chanh còn lại ở trên để ép.', NULL, '2026-05-15 14:51:13', '2026-05-15 14:51:13'),
(3614, 535, 1, 'Đun sôi một nồi nước muối lớn', NULL, '2026-05-15 14:51:14', '2026-05-15 14:51:14'),
(3615, 535, 2, 'Thêm mì ống, khuấy một lần và nấu trong khoảng 10 phút hoặc theo hướng dẫn trên gói.', NULL, '2026-05-15 14:51:14', '2026-05-15 14:51:14'),
(3616, 535, 3, 'Trong khi đó, rửa cà chua và cắt làm tư. Cắt ô liu. Rửa húng quế.', NULL, '2026-05-15 14:51:14', '2026-05-15 14:51:14'),
(3617, 535, 4, 'Cho cà chua vào bát salad và rắc lá húng quế lên trên. Thêm một muỗng canh dầu ô liu và trộn.', NULL, '2026-05-15 14:51:14', '2026-05-15 14:51:14'),
(3618, 535, 5, 'Khi mì đã sẵn sàng, đổ mì vào một cái chao và cho nước lạnh chảy qua để mì nguội nhanh.', NULL, '2026-05-15 14:51:14', '2026-05-15 14:51:14'),
(3619, 535, 6, 'Cho mì ống vào bát salad cùng với cà chua và húng quế.', NULL, '2026-05-15 14:51:14', '2026-05-15 14:51:14'),
(3620, 535, 7, 'Thêm ô liu thái lát, quả mozzarella đã ráo nước và khối cá ngừ. Trộn đều và để salad nghỉ ít nhất nửa giờ để hương vị hòa quyện.', NULL, '2026-05-15 14:51:14', '2026-05-15 14:51:14'),
(3621, 535, 8, 'Rắc mì ống với nhiều hạt tiêu đen xay và rưới thêm dầu ô liu còn lại ngay trước khi dùng.', NULL, '2026-05-15 14:51:14', '2026-05-15 14:51:14'),
(3622, 536, 1, 'Tôm khô mang đến cho món ăn Trung Quốc này vị mặn umami. Bạn có thể tìm thấy nó ở khu vực đông lạnh hoặc đông lạnh tại một cửa hàng tạp hóa châu Á. Hãy tìm tôm khô cỡ nhỏ, cỡ khoảng 1/4 inch. Nếu bạn sử dụng tôm khô vừa hoặc lớn, hãy ngâm tôm với nhiều nước hơn (1 cốc đối với tôm cỡ trung bình, 1 1/4 cốc đối với tôm cỡ lớn) và trong thời gian dài hơn (45 đến 60 phút), sau đó cắt tôm thành khối nhỏ hơn 1/4 inch. Để làm món chay theo công thức này, hãy bỏ tôm khô và sử dụng bốn hoặc năm cây nấm hương khô, bù nước và thái lát mỏng.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3623, 536, 2, 'Bù nước cho tôm khô:', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3624, 536, 3, 'Đặt tôm khô vào một cái bát nhỏ và đổ nước sôi lên trên. Đậy lại bằng một chiếc đĩa nhỏ và để yên trong 30 phút để tôm có thể bù nước. Tôm sẽ có màu nhạt hơn và căng mọng hơn một chút.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3625, 536, 4, 'Chuẩn bị bắp cải:', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3626, 536, 5, 'Trong khi đó, chia đôi bắp cải napa theo chiều dọc. Rửa sạch bắp cải và lắc khô. Cắt bỏ phần lõi của bắp cải và bỏ đi.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3627, 536, 6, 'Đặt hai cái bát lớn. Cắt bắp cải còn lại thành từng miếng 1 inch, cho những miếng trắng dày hơn ở dưới cùng của bắp cải vào một cái bát và những miếng lá xanh mỏng hơn ở trên vào bát kia.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3628, 536, 7, 'Xả tôm:', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3629, 536, 8, 'Sau khi tôm đã được bù nước, hãy để ráo nước và loại bỏ chất lỏng.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3630, 536, 9, 'Nấu tôm và bắp cải:', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3631, 536, 10, 'Trong chảo hoặc chảo lớn trên lửa cao, thêm dầu đậu phộng vào, đảo đều để phủ đều lên chảo.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3632, 536, 11, 'Đun nóng cho đến khi dầu trông nóng rực, sau đó cẩn thận thêm hành lá, gừng và tôm đã bù nước vào, đặc biệt chú ý vì nguyên liệu ướt có thể khiến dầu nóng bắn tung tóe. Dùng thìa đảo đều cho đến khi hành lá có màu xanh tươi và toàn bộ hỗn hợp có mùi thơm, khoảng 1 phút.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3633, 536, 12, 'Thêm phần trắng dày hơn của bắp cải napa vào chảo và giảm nhiệt xuống mức trung bình cao. Tiếp tục nấu và khuấy trong 3 đến 4 phút hoặc cho đến khi các cạnh của miếng bắp cải bắt đầu trông hơi mờ nhưng phần giữa của miếng bắp cải vẫn có màu trắng đục.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3634, 536, 13, 'Giảm nhiệt xuống mức trung bình thấp và thêm những miếng bắp cải xanh vào chảo. Nấu cho đến khi lá héo, khoảng 2 phút.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3635, 536, 14, 'Làm hỗn hợp bột bắp:', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3636, 536, 15, 'Trong một bát nhỏ, trộn nước tương, nước lạnh và bột ngô, khuấy đều để tạo thành hỗn hợp sền sệt. Sau đó đổ bắp cải lên trên và tiếp tục nấu và khuấy cho đến khi nước sốt hơi đặc lại như sữa nguyên chất.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3637, 536, 16, 'Nêm gia vị xào:', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3638, 536, 17, 'Nêm hỗn hợp xào với muối và hạt tiêu, sau đó nếm thử và thêm muối và hạt tiêu nếu muốn. Bắp cải sẽ có màu trong và mượt, khắp nơi đều có những đốm tôm khô.', NULL, '2026-05-15 14:51:16', '2026-05-15 14:51:16'),
(3644, 538, 1, 'Đun nóng 1 muỗng canh dầu trong chảo rộng, nông. Thêm đầu tôm và cọng mùi tây vào xào cho đến khi đầu tôm chuyển sang màu hồng, sau đó nghiền bằng máy nghiền khoai tây. Đổ rượu sherry hoặc rượu vang và 300ml nước, nêm muối và đun nhỏ lửa trong 10 phút để làm nước dùng, nghiền nát đầu tôm khi nấu.', NULL, '2026-05-15 14:51:20', '2026-05-16 12:35:34'),
(3646, 538, 2, 'Rải trai vào chảo, đậy nắp hoặc khăn trà lại, sau đó đặt trên lửa lớn trong 3-4 phút cho đến khi trai vừa mở miệng. Khuấy đều để nước hến chảy ra, sau đó đổ lượng chứa trong chảo vào một cái chao đặt trên một tô lớn chứa nghệ tây. Để nghệ tây ngâm trong nước dùng - bạn sẽ cần tổng cộng 700ml, vì vậy hãy đổ thêm nước nếu cần và khuấy đều mọi thứ. Chọn trai ra khỏi rây, sau đó đặt sang một bên.', NULL, '2026-05-15 14:51:20', '2026-05-16 12:35:34'),
(3648, 538, 3, 'Lau sạch chảo và thêm phần dầu ô liu còn lại vào. Xào chorizo ​​cho đến khi tiết ra dầu, sau đó thêm hành và tỏi vào nấu cho đến khi mềm. Thêm mực và lật lại cho đến khi nó chuyển sang màu trắng. Thêm cà chua và nấu trong một phút, sau đó đổ phần lớn nước kho vào, khuấy đều mọi thứ và đun sôi. Rải gạo lên trên, khuấy đều một lần rồi đun sôi mạnh trong 5 phút. Giảm nhiệt xuống mức thấp nhất và đun nhỏ lửa từ từ trong 10 phút mà không khuấy cho đến khi gạo hấp thụ hầu hết chất lỏng.', NULL, '2026-05-15 14:51:20', '2026-05-16 12:35:34');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(3650, 538, 4, 'Nhét đuôi tôm vào cơm và đun nhỏ lửa trong 5 phút, lật lại cho đến khi chín. Khuấy qua trai và đậu tằm hoặc đậu Hà Lan. Nếm thử cơm – nếu cơm vẫn còn hơi sống nhưng chảo đã khô, hãy thêm một chút nước luộc và tiếp tục nấu; nếu nước quá loãng thì hãy tăng lửa để nấu hết nước kho cuối cùng.', NULL, '2026-05-15 14:51:20', '2026-05-16 12:35:34'),
(3652, 538, 5, 'Khi cơm vừa chín, tắt lửa và đậy khăn lại trong vài phút. Rắc lá mùi tây và vỏ chanh lên trên, sau đó nêm muối hun khói nếu bạn thích. Khuấy mọi thứ một lần, sau đó dùng ngay từ chảo, với lát chanh ở bên cạnh.', NULL, '2026-05-15 14:51:20', '2026-05-16 12:35:34'),
(3654, 539, 1, 'Xả sạch đậu rồi cho vào chảo lớn với 2 lít nước. Đun nhỏ lửa với toàn bộ tép tỏi, lá nguyệt quế và húng tây trong 30 phút hoặc cho đến khi chín và mềm. Hủy bỏ nhiệt và đặt sang một bên.', NULL, '2026-05-15 14:51:21', '2026-05-16 12:35:34'),
(3656, 539, 2, 'Trong khi đó, đun nóng 2 muỗng canh dầu trong chảo rán. Chiên bánh mì với tép tỏi còn lại. Khi bánh vàng và giòn thì vớt ra để ráo trên giấy ăn. Cho chorizo ​​vào chảo, chiên cho đến khi giòn, vớt ra và giữ ấm cùng với bánh mì.', NULL, '2026-05-15 14:51:21', '2026-05-16 12:35:34'),
(3658, 539, 3, 'Thêm 2 muỗng canh dầu và hành tây vào chảo, nấu trong 5 phút cho đến khi mềm. Khuấy ớt bột. Để ráo đậu rồi cho hành tây cùng nước luộc gà và 2 thìa cà phê muối vào. Nấu trong 5-10 phút. Khuấy qua mùi tây và giữ ấm.', NULL, '2026-05-15 14:51:21', '2026-05-16 12:35:34'),
(3660, 539, 4, 'Nêm cá tuyết và đun nóng 2 muỗng canh dầu còn lại trong chảo rán. Đặt cá tuyết, mặt da úp xuống, vào chảo và nấu trong 3-5 phút trên lửa vừa cao để da giòn. Lật cá lại và nấu thêm 3-5 phút nữa cho đến khi chín. Múc hỗn hợp đậu trắng vào bát, đặt cá tuyết lên trên và kết thúc với bánh mì chiên, chorizo ​​và thêm một ít húng tây.', NULL, '2026-05-15 14:51:21', '2026-05-16 12:35:34'),
(3661, 540, 1, 'BƯỚC 1', NULL, '2026-05-15 14:51:23', '2026-05-15 14:51:23'),
(3662, 540, 2, 'Đun nóng một chút dầu trong chảo rán sâu lòng, lớn rồi xào hành tây và hạt tiêu trên lửa vừa cho đến khi mềm nhưng không chuyển sang màu nâu. Cắt nhỏ cọng rau mùi (giữ lại lá sau) rồi cho vào chảo cùng với ớt và tỏi băm nhỏ. Chiên thêm vài phút nữa. Thêm rượu vang, nghệ tây và lá nguyệt quế vào đun nhỏ lửa cho đến khi còn một nửa.', NULL, '2026-05-15 14:51:23', '2026-05-15 14:51:23'),
(3663, 540, 3, 'BƯỚC 2', NULL, '2026-05-15 14:51:23', '2026-05-15 14:51:23'),
(3664, 540, 4, 'Cho khoai tây, cà chua và 300ml nước vào đun sôi nhẹ. Dùng thìa đặt cạnh chảo bẻ nhỏ cà chua và đun nhỏ lửa trong 20-25 phút cho đến khi khoai tây vừa mềm và cà chua đã nát.', NULL, '2026-05-15 14:51:23', '2026-05-15 14:51:23'),
(3665, 540, 5, 'BƯỚC 3', NULL, '2026-05-15 14:51:23', '2026-05-15 14:51:23'),
(3666, 540, 6, 'Nêm vừa ăn rồi nhẹ nhàng cho cá vào nước sốt rồi xếp mực, tôm, nghêu, hến lên trên mặt nước. Đậy nắp và nấu khoảng 6-8 phút cho đến khi vỏ trai và nghêu mở ra, tôm chín và cá bong tróc. Nướng bánh mì, chà nhẹ với một nửa tép tỏi và rưới dầu ô liu. Phục vụ món hầm với lá rau mùi cắt nhỏ và bánh mì nướng để nhúng.', NULL, '2026-05-15 14:51:23', '2026-05-15 14:51:23'),
(3668, 541, 1, 'Để hành tím giòn, cho dầu vào chảo đun nóng khoảng 5 cm. Bạn sẽ biết dầu đã đủ nóng khi một miếng hẹ vừa thả vào sẽ kêu xèo xèo. Trộn các lát hẹ với bột mì, giũ sạch phần thừa rồi chiên trong dầu cho đến khi vàng. Họ chiên nhanh, khoảng 1 phút. Xả trên giấy ăn, rắc muối và đặt sang một bên.', NULL, '2026-05-15 14:51:25', '2026-05-16 12:35:34'),
(3670, 541, 2, 'Để làm nước sốt, trộn nước cốt chanh, đường, nước mắm và tỏi rồi để sang một bên. Trong một tô trộn lớn, đổ nước sôi lên mì. Để chúng trong 2 phút hoặc cho đến khi chúng vừa chín, sau đó rửa sạch dưới nước lạnh. Để ráo nước, lắc rây nhiều lần để thoát hết nước rồi đặt lại vào tô. Thêm tôm, hành tây, ớt, dưa chuột và rau thơm. Đổ nước sốt lên trên, trộn đều rồi rắc hẹ tây và đậu phộng.', NULL, '2026-05-15 14:51:25', '2026-05-16 12:35:34'),
(3672, 542, 1, 'Cho tôm vào tô. Cho ớt, tỏi, cọng rau mùi (cắt chúng bằng kéo trước) và đường xay vào máy xay gia vị hoặc máy xay thực phẩm nhỏ rồi xay nhuyễn. Thêm một nửa nước cốt chanh và nước mắm, sau đó rưới lên tôm.', NULL, '2026-05-15 14:51:27', '2026-05-16 12:35:34'),
(3674, 542, 2, 'Đun nóng 1 muỗng canh dầu trong chảo, cho gừng và hành lá vào xào trong 1 phút. Thêm ớt đỏ và xào trong 1 phút cho đến khi ớt bắt đầu mềm. Thêm hạt dẻ nước và giá đỗ vào, trộn đều cho đến khi giá đỗ bắt đầu héo. Thêm nước tương và hạt tiêu đen xay thật nhuyễn, sau đó cho rất nhiều vào đĩa phục vụ.', NULL, '2026-05-15 14:51:27', '2026-05-16 12:35:34'),
(3676, 542, 3, 'Đun nóng lượng dầu còn lại trong chảo rồi cho tôm vào, vớt tôm ra khỏi nước. Đảo khoảng 1-2 phút cho đến khi chúng chuyển sang màu hồng, thêm nước xốt vào và đảo nhanh chảo, sau đó đổ hỗn hợp lên rau. Cắt lá rau mùi và rắc phần chanh còn lại. Dùng với mì có thêm chanh để vắt.', NULL, '2026-05-15 14:51:27', '2026-05-16 12:35:34'),
(3678, 543, 1, 'Chuẩn bị trước - cắt đôi quả ớt theo chiều dọc và loại bỏ hạt và cuống. Lót giấy bạc vào chảo nướng và đặt hai nửa hạt tiêu, mặt da hướng lên trên, lên chảo nướng cùng với cả tép tỏi, ớt và cà chua. Nướng trong 2 phút, lật cà chua rồi nướng thêm 2 phút nữa. Dùng thìa lớn loại bỏ cà chua, sau đó gọt vỏ, làm tư và bỏ hạt. Sau đó cắt nhỏ cà chua.', NULL, '2026-05-15 14:51:28', '2026-05-16 12:35:34'),
(3680, 543, 2, 'Tiếp tục nướng tiêu, ớt và tỏi trong 4-5 phút, cho đến khi vỏ ớt và ớt chuyển sang màu đen và tỏi bắt đầu mềm (vỏ tỏi sẽ bắt đầu tách ra khi chín). Khi đủ nguội để cầm, hãy gọt vỏ và cắt đôi quả ớt, cạo bỏ hạt. Gọt vỏ hạt tiêu và cắt nhỏ cả hạt tiêu và ớt.', NULL, '2026-05-15 14:51:28', '2026-05-16 12:35:34'),
(3682, 543, 3, 'Trải các loại hạt lên giấy bạc và nướng cho đến khi nướng. Cắt nhỏ các loại hạt và mùi tây trong máy xay thực phẩm. Đổ vào một cái bát nhỏ.', NULL, '2026-05-15 14:51:28', '2026-05-16 12:35:34'),
(3684, 543, 4, 'Đun nóng 3 thìa dầu ăn trong chảo, cho tiêu, tỏi, ớt vào xào trong 3 phút. Xé bánh mì và cho vào chảo, cho vào chảo dầu cho đến khi chín vàng nhẹ. Cho cà chua, muối, giấm và dầu vào máy xay thực phẩm cho đến khi cắt nhỏ. Đổ tiền vào một cái bát. Để nguội và bảo quản trong tủ lạnh tối đa 3 ngày.', NULL, '2026-05-15 14:51:28', '2026-05-16 12:35:34'),
(3686, 543, 5, 'Trong ngày, thêm các loại hạt và mùi tây vào nước sốt và trộn. Bày ra một chiếc bát nhỏ cùng với tôm đã bóc vỏ. Cung cấp que cocktail để xiên tôm.', NULL, '2026-05-15 14:51:28', '2026-05-16 12:35:34'),
(3688, 544, 1, 'Yêu cầu người bán cá làm sạch mực; những cái nhỏ thường được làm sạch sẵn. Dùng kéo nhà bếp cắt phần thân và mở ra. Rửa sạch, sau đó lau khô. Nếu bạn có một con mực lớn, hãy cắt thân thành bốn phần, gần như hình vuông. Mực nhỏ chỉ có thể được mở ra.', NULL, '2026-05-15 14:51:32', '2026-05-16 12:35:34'),
(3690, 544, 2, 'Sử dụng đầu của một con dao thật sắc, rạch phần trên theo đường chéo gọn gàng. Quét một lớp dầu lên và đặt sang một bên trong khi hâm nóng vỉ nướng hoặc vỉ nướng cho đến khi sẵn sàng nấu.', NULL, '2026-05-15 14:51:32', '2026-05-16 12:35:34'),
(3692, 544, 3, 'Trộn 2 thìa cà phê muối biển, ngũ vị hương Trung Quốc và 1 thìa cà phê tiêu đen mới xay. Rắc đều lên cả hai mặt của mực ngay trước khi nấu, tùy theo khẩu vị. Bạn có thể không cần tất cả. Làm nóng chảo nướng cho nóng và nướng khoảng 1 phút mỗi mặt cho đến khi chảo bắt đầu cong lại. Dùng kẹp gắp ra đĩa và rưới một ít dầu mè. Khi ăn, trang trí với lá rau mùi và dùng kèm với bát nước sốt ớt ngọt nhỏ để chấm.', NULL, '2026-05-15 14:51:32', '2026-05-16 12:35:34'),
(3693, 545, 1, 'Ngâm tất cả các loại gia vị, gừng, tỏi, cùi me và ớt kashmiri trừ dầu trong giấm.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3694, 545, 2, 'Thêm đường và muối.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3695, 545, 3, 'Ngoài ra còn thêm bột nghệ.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3696, 545, 4, 'Trộn đều tất cả và ướp trong 35-40 phút.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3697, 545, 5, 'Xay hỗn hợp cho đến khi mềm và mịn. Thêm giấm nếu cần nhưng đảm bảo hỗn hợp phải đặc, nên thêm giấm cho phù hợp. Nếu bột masala mỏng thì nó sẽ không dính vào cá.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3698, 545, 6, 'Rửa sạch phần cá ở giữa và rạch một đường từ trên xuống. Bạn có thể nhìn thấy con cá bên dưới để hiểu rõ hơn.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3699, 545, 7, 'Bây giờ hãy nhét miếng dán vào giữa và vào vết mổ. Phủ toàn bộ cá bằng hỗn hợp này. Ướp cá trong 30 phút.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3700, 545, 8, 'Cho dầu vào chảo nông, khi dầu khá nóng, hãy chiên cá thu nhồi bông.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3701, 545, 9, 'Chiên cho đến khi vàng đều hai mặt', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3702, 545, 10, 'Ăn nóng cá thu recheado với salad, chanh, cơm và cà ri.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3703, 545, 11, 'Ghi chú', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3704, 545, 12, '1. Đảm bảo bột masala đặc, nếu không kết quả sẽ không tốt.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3705, 545, 13, '2. Nếu bạn không tìm được ớt kashmiri thì hãy dùng ớt bedgi hoặc bột ớt đỏ kashmiri.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3706, 545, 14, '3. Bạn có thể dùng giấm trắng hoặc giấm dừa.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3707, 545, 15, '4. Phần dán còn sót lại có thể được bảo quản trong tủ lạnh để sử dụng sau.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3708, 545, 16, '5. Có thể tránh dùng quế vì nó là một loại gia vị mạnh thường được sử dụng cho thịt hoặc thịt gà.', NULL, '2026-05-15 14:51:34', '2026-05-15 14:51:34'),
(3709, 546, 1, 'Nêm cá hồi, sau đó chà xát với dầu. Trộn các nguyên liệu làm nước sốt với nhau. Cắt đôi, gọt vỏ và cắt lát quả bơ. Cắt đôi và làm tư quả dưa chuột theo chiều dọc, sau đó cắt thành từng lát. Chia salad, bơ và dưa chuột vào bốn đĩa, sau đó rưới một nửa nước sốt lên.', NULL, '2026-05-15 14:51:36', '2026-05-15 14:51:36'),
(3710, 546, 2, 'Làm nóng chảo chống dính. Thêm cá hồi và chiên trong 3-4 phút mỗi mặt cho đến khi giòn nhưng vẫn ẩm bên trong. Đặt phi lê cá hồi lên trên mỗi món salad và rưới lên phần nước sốt còn lại. Phục vụ ấm áp.', NULL, '2026-05-15 14:51:36', '2026-05-15 14:51:36'),
(3712, 547, 1, 'Đổ nước kho vào chảo lớn, đun sôi rồi cho bột cà ri vào khuấy đều. Thêm mì và nấu trong 8 phút. Cho nấm và ngô vào nấu thêm 2 phút nữa.', NULL, '2026-05-15 14:51:37', '2026-05-16 12:35:34'),
(3714, 547, 2, 'Thêm cá hồi vào chảo và nấu trong 3 phút hoặc cho đến khi chín. Tắt bếp và cho nước cốt chanh, nước tương và một chút đường vào khuấy đều. Múc vào 4 bát và rắc rau mùi lên ngay trước khi dùng.', NULL, '2026-05-15 14:51:37', '2026-05-16 12:35:34'),
(3719, 549, 1, 'Đun chảy bơ trong chảo có đáy dày và nhẹ nhàng nấu hành tây không màu cho đến khi mềm.', NULL, '2026-05-15 14:51:39', '2026-05-15 14:51:39'),
(3720, 549, 2, 'Thêm gạo và khuấy đều để phủ tất cả các hạt trong bơ', NULL, '2026-05-15 14:51:39', '2026-05-15 14:51:39'),
(3721, 549, 3, 'Thêm rượu và nấu khuấy nhẹ nhàng cho đến khi nó được hấp thụ', NULL, '2026-05-15 14:51:39', '2026-05-15 14:51:39'),
(3722, 549, 4, 'Dần dần thêm nước nóng vào, khuấy đều cho đến khi từng chất bổ sung được hấp thụ. Tiếp tục khuấy cho đến khi gạo mềm', NULL, '2026-05-15 14:51:39', '2026-05-15 14:51:39'),
(3723, 549, 5, 'Nêm nước cốt chanh, vỏ và hạt tiêu cho vừa ăn. (chắc cá hồi đã đủ độ mặn nên không cần cho muối) Khuấy nhẹ cho nóng đều', NULL, '2026-05-15 14:51:39', '2026-05-15 14:51:39'),
(3724, 549, 6, 'Ăn kèm với Parmesan và rau theo mùa.', NULL, '2026-05-15 14:51:39', '2026-05-15 14:51:39'),
(3725, 549, 7, 'Nướng cá hồi và nhẹ nhàng đặt tôm và măng tây lên cơm risotto', NULL, '2026-05-15 14:51:39', '2026-05-15 14:51:39'),
(3727, 550, 1, 'Để làm nước chấm, trộn tất cả nguyên liệu vào một chiếc bát nhỏ cho đến khi đường tan hết rồi để riêng. Trộn bột ngô và bột mì với ớt và 2 thìa muối biển vào tô lớn, sau đó đặt sang một bên. Lót giấy ăn vào khay và đảm bảo bạn có nhiều muối để rắc.', NULL, '2026-05-15 14:51:40', '2026-05-16 12:35:34'),
(3729, 550, 2, 'Đun nóng khoảng 7cm dầu đến 180C trong nồi chiên sâu, chảo hoặc chảo sâu lòng. Nếu không có nhiệt kế, bạn có thể kiểm tra bằng một khối bánh mì – nó sẽ chuyển sang màu nâu sau 20 giây. Phủ đều mực với hỗn hợp bột và chiên theo mẻ trong khoảng 2 phút mỗi mẻ hoặc cho đến khi giòn. Dùng thìa có rãnh vớt mực ra, để ráo nước trên giấy bếp và rắc thêm chút muối. Dọn mực với hành lá và ớt, kèm nước chấm bên cạnh.', NULL, '2026-05-15 14:51:40', '2026-05-16 12:35:34'),
(3731, 551, 1, 'Đun nóng một nửa lượng dầu trong chảo rồi xào hành tây trên lửa vừa cho đến khi mềm và có màu vàng nhạt - quá trình này sẽ mất khoảng 8 phút. Lấy ra khỏi chảo, đặt sang một bên và thêm khoai tây vào chảo. Nấu cho đến khi chúng mềm nhưng không bị nát, thỉnh thoảng lật cẩn thận. Đậy chảo một lúc để giúp các lát chín đều. Cho hành tây trở lại chảo cùng với tỏi và nấu thêm 4 phút nữa. Cho trứng, rau mùi tây và một ít gia vị vào tô rồi trộn đều. Để yên trong nửa giờ.', NULL, '2026-05-15 14:51:41', '2026-05-16 12:35:34'),
(3733, 551, 2, 'Trong khi đó, cho cá tuyết vào nồi và đổ ngập nước. Đun nhỏ lửa. Tắt bếp, đậy nắp và để trong 10 phút. Để ráo nước, để nguội và loại bỏ da và xương. Chia thành từng mảnh lớn và thêm vào hỗn hợp khoai tây và trứng.', NULL, '2026-05-15 14:51:41', '2026-05-16 12:35:34'),
(3735, 551, 3, 'Đun nóng phần dầu còn lại trong chảo chống dính. Đổ hỗn hợp bánh tortilla vào và nấu ở lửa vừa-thấp cho đến khi bánh vừa chín và tách ra khỏi thành chảo. Bạn có thể cần phải che nó lại để giúp phần giữa cố định. Hãy cẩn thận để không nấu quá chín. Thỉnh thoảng đặt một chiếc thìa bên dưới bánh tortilla để đảm bảo bánh không bị dính. Đặt bánh tortilla lên đĩa, sau đó đặt chảo lên trên và lật mặt bánh chưa chín vào đó. Nấu trên lửa nhỏ cho đến khi chín vàng hoặc nướng cho đến khi chín. Để nguội một chút trước khi dùng.', NULL, '2026-05-15 14:51:41', '2026-05-16 12:35:34'),
(3736, 552, 1, 'Đối với cá muối, ngâm muối qua đêm, thay nước vài lần.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3737, 552, 2, 'Xả sạch, sau đó cho cá tuyết vào chảo nước sạch lớn và đun sôi. Xả lại, thêm nước sạch và đun sôi lại.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3738, 552, 3, 'Đun nhỏ lửa trong khoảng năm phút hoặc cho đến khi chín, sau đó để ráo nước và vẩy cá thành từng miếng lớn. Loại bỏ da hoặc xương.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3739, 552, 4, 'Đối với bánh bao, trộn bột mì và mỡ với một chút muối và 250ml/9fl oz nước để tạo thành bột nhào.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3740, 552, 5, 'Bọc hỗn hợp trong màng bám và để trong tủ lạnh để nghỉ.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3741, 552, 6, 'Mở hộp ackee, để ráo nước và rửa sạch, sau đó đặt sang một bên.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3742, 552, 7, 'Đun nóng một thìa dầu ô liu trong chảo và xào hành tây cho đến khi mềm nhưng không có màu nâu.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3743, 552, 8, 'Thêm gia vị, hạt nêm, sốt tiêu và ớt thái lát vào rồi tiếp tục xào cho đến khi ớt mềm.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3744, 552, 9, 'Thêm cà chua xắt nhỏ, sau đó thêm muối vào và trộn đều. Cuối cùng khuấy ackee thật nhẹ nhàng và đun nhỏ lửa cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3745, 552, 10, 'Khi bạn gần chuẩn bị ăn, hãy đun nóng dầu thực vật khoảng 1cm/½ inch trong chảo rán và đun nóng cho đến khi bốc khói.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3746, 552, 11, 'Nặn hỗn hợp bánh bao thành những viên tròn cỡ quả mận và chiên nông cho đến khi có màu vàng nâu. (THẬN TRỌNG: dầu nóng có thể nguy hiểm. Không được để chảo không có người trông coi.)', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3747, 552, 12, 'Xả bánh bao trên giấy ăn và dùng kèm với cá muối và ackee.', NULL, '2026-05-15 14:51:42', '2026-05-15 14:51:42'),
(3749, 553, 1, 'Ướp 6 phi lê cá chẽm với muối và hạt tiêu, sau đó rạch da 3 lần.', NULL, '2026-05-15 14:51:42', '2026-05-16 12:35:34'),
(3751, 553, 2, 'Làm nóng chảo rán nặng và thêm 1 muỗng canh dầu hướng dương.', NULL, '2026-05-15 14:51:42', '2026-05-16 12:35:34'),
(3753, 553, 3, 'Sau khi nóng, chiên phi lê cá chẽm, úp mặt xuống trong 5 phút hoặc cho đến khi da rất giòn và vàng. Cá sẽ gần chín hẳn.', NULL, '2026-05-15 14:51:42', '2026-05-16 12:35:34'),
(3755, 553, 4, 'Lật lại, nấu thêm 30 giây - 1 phút nữa thì bày ra đĩa và dùng nóng. Bạn sẽ cần chiên phi lê cá chẽm thành 2 mẻ.', NULL, '2026-05-15 14:51:43', '2026-05-16 12:35:34'),
(3757, 553, 5, 'Đun nóng 2 thìa dầu hướng dương, sau đó cho gừng đã gọt vỏ cắt thành que diêm vào phi thơm, 3 tép tỏi thái mỏng và 3 quả ớt đỏ thái mỏng khoảng 2 phút cho đến khi chín vàng.', NULL, '2026-05-15 14:51:43', '2026-05-16 12:35:34'),
(3759, 553, 6, 'Tắt lửa và cho bó hành lá cắt nhỏ vào. Rắc cá với 1 muỗng canh nước tương và rưới lên cá trong chảo.', NULL, '2026-05-15 14:51:43', '2026-05-16 12:35:34'),
(3760, 554, 1, 'Đun sôi ấm đun nước. Đổ vẹm vào một cái chao và để dưới vòi nước lạnh. Vứt bỏ bất kỳ vỏ nào bị vỡ. Nhặt từng vỏ, gõ nhẹ vào từng vỏ ở thành bồn rửa - chúng nên đóng lại hoặc nên đóng từ từ khi gõ - nếu chúng vẫn mở, hãy vứt chúng đi. Nếu bất kỳ vỏ nào vẫn còn bám hà hoặc râu xơ xác, hãy dùng dao kéo tách chúng ra và rửa sạch vỏ. Giữ trong một cái chao, phủ một miếng vải ẩm và lạnh cho đến khi bạn sẵn sàng nấu ăn. Tôm chỉ bóc vỏ ở phần thân – giữ nguyên đầu và đuôi. Hãy rạch phần lưng và lôi hết phần ruột có sạn ra. Thư giãn cho đến khi bạn sẵn sàng nấu ăn.', NULL, '2026-05-15 14:51:44', '2026-05-15 14:51:44'),
(3761, 554, 2, 'Cho nghệ tây vào cốc nhỏ, đổ 50ml nước nóng vào ấm và để yên trong 10 phút. Nếu dùng bún thì cho vào tô và dùng tay vò nát thành từng miếng nhỏ (dài khoảng 1cm).', NULL, '2026-05-15 14:51:44', '2026-05-15 14:51:44'),
(3762, 554, 3, 'Đun nóng dầu trong chảo rán lớn có mép chảo ít nhất 3cm hoặc chảo paella 40cm. Thêm hành tây vào và đảo đều chảo trong 5 phút cho đến khi mềm. Thêm tỏi và nấu thêm 1 phút nữa, sau đó cho bún vào nấu trong 5 phút, thỉnh thoảng khuấy cho đến khi bún có màu nâu. Khuấy ớt bột.', NULL, '2026-05-15 14:51:44', '2026-05-15 14:51:44'),
(3763, 554, 4, 'Để lửa vừa phải, khuấy đều cá chày, mực và nghệ tây với nước, nêm gia vị vừa đủ. Dàn đều các nguyên liệu, sau đó rưới nước dùng còn nóng lên và rải cà chua lên trên. Đun sôi, sau đó đậy kín toàn bộ món ăn bằng nắp đậy kín (hoặc giấy bạc). Vặn lửa vừa và nấu trong 6 phút.', NULL, '2026-05-15 14:51:44', '2026-05-15 14:51:44'),
(3764, 554, 5, 'Khám phá và khuấy đều để kết hợp lớp mì ống khô trên cùng. Đẩy hến vào trong mì sao cho bản lề chìm vào đáy đĩa và chúng đứng thẳng lên. Xếp tôm lên trên, đậy kín và nấu thêm 6 phút nữa hoặc cho đến khi trai mở miệng, tôm có màu hồng và mì chín. Để lửa nhỏ thêm 2-3 phút nữa để nấu gần hết chất lỏng còn lại (để lại một ít trong chảo để tránh mì ống dính vào nhau). Để yên trong 2-3 phút, sau đó vắt thêm nước cốt chanh và xếp các miếng nêm lên trên. Rắc rau mùi tây trước khi dùng.', NULL, '2026-05-15 14:51:44', '2026-05-15 14:51:44'),
(3766, 555, 1, 'Đun nóng dầu trong chảo sâu lòng, sau đó cho tỏi tây vào xào mềm trong 5 phút mà không bị chuyển sang màu nâu. Thêm chorizo ​​và chiên cho đến khi nó tiết ra dầu. Khuấy nghệ và gạo cho đến khi được dầu bao phủ, sau đó đổ nước kho vào. Đun sôi, sau đó đun nhỏ lửa trong 15 phút, thỉnh thoảng khuấy.', NULL, '2026-05-15 14:51:45', '2026-05-16 12:35:34'),
(3768, 555, 2, 'Cho đậu Hà Lan vào và nấu trong 5 phút, sau đó cho hải sản vào đun nóng trong 1-2 phút cuối cùng hoặc cho đến khi cơm chín. Kiểm tra gia vị và dùng ngay với chanh.', NULL, '2026-05-15 14:51:45', '2026-05-16 12:35:34'),
(3769, 556, 1, 'BƯỚC 1 – NGÂM MÌ', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3770, 556, 2, 'Ngâm bún qua đêm cho mềm', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3771, 556, 3, 'BƯỚC 2 - LUÔN MÌ', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3772, 556, 4, 'Luộc mì trong vòng 10-15 phút rồi xả lại bằng nước lạnh để dừng quá trình nấu mì.', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3773, 556, 5, 'BƯỚC 3 - Ướp TÔM', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3774, 556, 6, 'Cho tôm, trứng, 1 nhúm tiêu trắng, 1 thìa dầu mè, 1 thìa bột ngô và 1 thìa dầu vào tô.', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3775, 556, 7, 'Trộn đều với nhau', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3776, 556, 8, 'BƯỚC 4 - Xào', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3777, 556, 9, 'Cho 2 thìa dầu vào chảo, cho tôm vào xào cho đến khi có màu vàng nâu', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3778, 556, 10, 'Đặt tôm sang một bên', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3779, 556, 11, 'Thêm 1 muỗng canh dầu vào rồi cho tỏi băm, gừng và tất cả các loại rau vào.', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3780, 556, 12, 'Thêm mì vào chảo', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3781, 556, 13, 'Tiếp theo thêm rượu nấu sherry, dầu hào, đường, giấm, dầu mè, 1 nhúm tiêu trắng và nước tương.', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3782, 556, 14, 'Thêm tôm vào lại', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3783, 556, 15, 'Để làm đặc nước sốt, trộn 1 muỗng canh tinh bột ngô và 2 muỗng canh nước vào tô rồi từ từ thêm vào món xào cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:51:47', '2026-05-15 14:51:47'),
(3784, 557, 1, 'Bạn cũng có thể sử dụng đậu Hà Lan có đường cho công thức này. Tiết kiệm thời gian chuẩn bị bằng cách chuẩn bị đậu Hà Lan, gừng và tỏi trong khi ướp tôm.', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3785, 557, 2, 'Ướp tôm:', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3786, 557, 3, 'Trộn tất cả nguyên liệu làm nước xốt vào tô lớn, sau đó cho tôm vào. Quẳng vào áo khoác. Hãy ngồi trong 15 đến 20 phút trong khi chuẩn bị đậu Hà Lan, gừng và tỏi.', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3787, 557, 4, 'Xào gừng và tỏi:', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3788, 557, 5, 'Đun nóng chảo hoặc chảo xào lớn trên lửa cao trong 1 phút. Thêm dầu đậu phộng và để nóng, khoảng 30 giây. Thêm gừng và tỏi và trộn đều. Xào trong khoảng 30 giây.', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3789, 557, 6, 'Thêm tôm, đậu Hà Lan, nước tương, nước dùng:', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3790, 557, 7, 'Cho tôm và toàn bộ nước xốt vào chảo (dùng thìa cao su cạo hết nước xốt). Thêm đậu tuyết, nước tương và nước luộc gà. Xào cho đến khi tôm chuyển sang màu hồng, khoảng 2 phút.', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3791, 557, 8, 'Thêm hành lá và hoàn thiện với dầu mè:', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3792, 557, 9, 'Thêm hành lá và xào thêm 1 phút nữa. Tắt lửa và thêm dầu mè. Trộn đều một lần nữa và dùng kèm cơm trắng.', NULL, '2026-05-15 14:51:48', '2026-05-15 14:51:48'),
(3811, 559, 1, 'Ngâm cá trích trong nước lạnh ít nhất 1 giờ. Nếu mặn quá thì lặp lại, thay nước mỗi lần.', NULL, '2026-05-15 14:51:51', '2026-05-15 14:51:51'),
(3812, 559, 2, 'Xả thật sạch và cắt cá trích thành từng miếng vừa ăn.', NULL, '2026-05-15 14:51:51', '2026-05-15 14:51:51'),
(3813, 559, 3, 'Cho vào một cái lọ đủ lớn để chứa các miếng và phủ dầu, hạt tiêu, hạt tiêu và lá nguyệt quế. Đóng bình lại.', NULL, '2026-05-15 14:51:51', '2026-05-15 14:51:51'),
(3814, 559, 4, 'Để trong tủ lạnh từ 2 đến 3 ngày trước khi ăn. Điều này sẽ giữ lạnh lên đến 2 tuần.', NULL, '2026-05-15 14:51:51', '2026-05-15 14:51:51'),
(3815, 559, 5, 'Ăn kèm với hành tây thái nhỏ hoặc lát hành tây, chanh và rau mùi tây hoặc thì là.', NULL, '2026-05-15 14:51:51', '2026-05-15 14:51:51'),
(3817, 560, 1, 'Đun sôi ấm đun nước. Trong chảo chống dính hoặc chảo nông có nắp, xào hành tây, ớt, chorizo ​​và tỏi trong dầu trên lửa cao trong 3 phút. Cho gạo và cà chua cắt nhỏ vào với 500ml nước sôi, đậy nắp rồi đun trên lửa lớn trong 12 phút.', NULL, '2026-05-15 14:51:53', '2026-05-16 12:35:34'),
(3819, 560, 2, 'Mở nắp rồi khuấy đều - cơm sẽ gần mềm. Khuấy tôm, rưới thêm nước nếu gạo trông khô, sau đó nấu thêm một phút nữa cho đến khi tôm có màu hồng và gạo mềm.', NULL, '2026-05-15 14:51:53', '2026-05-16 12:35:34'),
(3821, 561, 1, 'Đun nóng dầu trong chảo lớn và cho hành tây vào xào mềm trong 6-7 phút. Thêm hạt tiêu và tỏi, nấu thêm 2 phút nữa, sau đó cho cơm paella vào và nấu trong 1 phút, khuấy đều.', NULL, '2026-05-15 14:51:54', '2026-05-16 12:35:34'),
(3823, 561, 2, 'Đổ nước kho vào, thêm nghệ tây và đun sôi. Nấu, không đậy nắp, ở mức bong bóng nhẹ trong 20 phút, thỉnh thoảng khuấy cho đến khi gạo mềm.', NULL, '2026-05-15 14:51:54', '2026-05-16 12:35:34'),
(3825, 561, 3, 'Khuấy hải sản và nước cốt chanh rồi nấu trong 2 phút hoặc cho đến khi nóng và chín hoàn toàn. Phục vụ trong bát ấm rải rác với rau mùi tây.', NULL, '2026-05-15 14:51:54', '2026-05-16 12:35:34'),
(3827, 562, 1, 'Nấu mì theo hướng dẫn trên bao bì, để ráo nước và để riêng cho lần sau. Đun nóng dầu trong chảo lớn rồi đổ trứng đã đánh vào. Xoay quanh chảo để làm món trứng tráng mỏng, nấu trong 1-2 phút, sau đó lật lại và chiên mặt còn lại trong 1 phút. Mẹo ra và cắt thành dải mỏng.', NULL, '2026-05-15 14:51:55', '2026-05-16 12:35:34'),
(3829, 562, 2, 'Cho ớt và gừng vào chảo, xào khoảng 1-2 phút rồi cho mì, tôm và trứng vào. Rưới nước tương vào và xào thêm 1 phút nữa. Cho các loại thảo mộc đã cắt nhỏ vào và rưới nước cốt chanh và vỏ, sau đó rắc lên đậu phộng đã cắt nhỏ và thưởng thức.', NULL, '2026-05-15 14:51:55', '2026-05-16 12:35:34'),
(3830, 563, 1, 'BƯỚC 1', NULL, '2026-05-15 14:51:57', '2026-05-15 14:51:57'),
(3831, 563, 2, 'Để làm bột, bạn chà bơ vào bột mì rồi cho lòng trắng trứng và một nửa lòng đỏ (giữ lại), giấm, một chút muối và nước lạnh vừa đủ để tạo thành khối bột mềm. Nhào trên bề mặt đã rắc bột mì cho đến khi mịn rồi bọc lại và để yên trong 30 phút.', NULL, '2026-05-15 14:51:57', '2026-05-15 14:51:57'),
(3832, 563, 3, 'BƯỚC 2', NULL, '2026-05-15 14:51:57', '2026-05-15 14:51:57'),
(3833, 563, 4, 'Làm nóng lò ở 180c/quạt 160c/gas 4. Cắt bỏ phần đầu còn xanh của hành lá rồi thái nhuyễn phần còn lại. Đun nóng một ít dầu trong chảo và chiên nhẹ nhàng cho đến khi mềm nhưng không bị chín vàng. Thêm ớt và tỏi vào, khuấy đều rồi cho tôm vào nấu cho đến khi có màu đục. Mùa tốt. Múc tôm ra và đun sôi nước cho đến khi đặc lại, sau đó cho tôm vào.', NULL, '2026-05-15 14:51:57', '2026-05-15 14:51:57'),
(3834, 563, 5, 'BƯỚC 3', NULL, '2026-05-15 14:51:57', '2026-05-15 14:51:57'),
(3835, 563, 6, 'Chia bột empanada thành tám quả bóng và cán thành những vòng tròn mỏng trên bề mặt đã rắc bột mì. Cho một ít nhân vào một nửa miếng bột, rắc feta lên trên và gấp nửa còn lại lại. Cắt bớt mép rồi gấp và gấp bột lại với nhau sao cho empanada được đậy kín, đặt lên khay nướng đã phết dầu ở một bên hoặc đặt trên mép không bị gấp nếp giống như một chiếc bánh bột ngô. Lặp lại với bột và hỗn hợp còn lại. Trộn lòng đỏ trứng còn sót lại với một chút nước và phết lên mặt bánh empanadas.', NULL, '2026-05-15 14:51:57', '2026-05-15 14:51:57'),
(3836, 563, 7, 'BƯỚC 4', NULL, '2026-05-15 14:51:57', '2026-05-15 14:51:57'),
(3837, 563, 8, 'Nướng trong 30 phút hoặc cho đến khi vàng và hơi giòn xung quanh các cạnh.', NULL, '2026-05-15 14:51:57', '2026-05-15 14:51:57'),
(3839, 564, 1, 'Nấu toàn bộ ớt dưới vỉ nướng, trên vỉ nướng hoặc vỉ nướng, cho đến khi cháy hoàn toàn. Cho ớt vào tô, đậy bằng đĩa cho đến khi nguội vừa tay rồi gọt vỏ, bỏ hạt và thái lát mỏng. Trong một tô lớn, trộn ớt và bất kỳ loại nước ép nào với đậu xanh, rau mùi tây, ớt và tỏi. Đặt sang một bên.', NULL, '2026-05-15 14:51:58', '2026-05-16 12:35:34'),
(3841, 564, 2, 'Đun nóng chảo lớn cho đến khi bốc khói. Làm việc nhanh chóng và cẩn thận, thêm một chút dầu vào chảo, sau đó là mực. Xào trong khoảng 30 giây. Rắc chorizo ​​lên mực, tiếp tục nấu thêm 30 giây nữa rồi cho ớt vào tô. Nêm mọi thứ với muối và hạt tiêu, sau đó trộn với lượng dầu còn lại, nước cốt chanh và vỏ chanh. Trộn đều, bày ra đĩa và để mọi người tự lấy.', NULL, '2026-05-15 14:51:58', '2026-05-16 12:35:34'),
(3847, 566, 1, 'Đun nóng 1 thìa dầu ăn trong chảo, cho hành, tỏi, ớt vào xào khoảng 2-3 phút cho đến khi chín vàng. Thêm tôm và nấu trong 1 phút. Cho gạo và đậu Hà Lan vào, tiếp tục đảo cho đến khi thật nóng. Thêm nước tương và nước mắm vào, sau đó đảo đều với rau mùi cắt nhỏ. Giữ ấm khi chiên trứng.', NULL, '2026-05-15 14:52:02', '2026-05-16 12:35:34'),
(3849, 566, 2, 'Đun nóng lượng dầu còn lại trong chảo rồi chiên trứng với một ít gia vị. Chia hỗn hợp cơm chiên vào 4 bát và phủ một quả trứng chiên lên trên mỗi bát. Ăn kèm rau mùi, tương ớt nếu thích.', NULL, '2026-05-15 14:52:02', '2026-05-16 12:35:34'),
(3851, 567, 1, 'Đun nóng dầu trong chảo vừa. Cho hành tây và gừng vào, sau đó nấu trong vài phút cho đến khi mềm. Khuấy bột cà ri, sau đó nấu thêm 1 phút nữa. Đổ cà chua xắt nhỏ và nước cốt dừa lên trên. Đun sôi, sau đó để nhỏ lửa trong 5 phút, thêm một chút nước sôi nếu hỗn hợp quá đặc.', NULL, '2026-05-15 14:52:03', '2026-05-16 12:35:34'),
(3853, 567, 2, 'Cho tôm vào, sau đó nấu thêm 5-10 phút nữa, tùy thuộc vào kích thước của chúng. Ăn kèm với một ít cơm trắng và rắc một ít rau mùi xắt nhỏ nếu bạn thích.', NULL, '2026-05-15 14:52:03', '2026-05-16 12:35:34'),
(3855, 568, 1, 'Nấu mì theo hướng dẫn đóng gói. Làm mới trong nước lạnh và thoát nước tốt.', NULL, '2026-05-15 14:52:04', '2026-05-16 12:35:34'),
(3857, 568, 2, 'Cho nước luộc vào nồi lớn rồi cho bột cà ri, lá chanh, nước mắm và 250ml nước lạnh vào khuấy đều. Đun nhỏ lửa và nấu trong 5 phút.', NULL, '2026-05-15 14:52:04', '2026-05-16 12:35:34'),
(3859, 568, 3, 'Cắt cá thành khối khoảng 3cm và cho vào chảo. Đun sôi trở lại, sau đó nấu trong 2 phút không đậy nắp.', NULL, '2026-05-15 14:52:04', '2026-05-16 12:35:34'),
(3861, 568, 4, 'Khuấy mì, tôm và pak choi rồi đun nhỏ lửa trong 2-3 phút hoặc cho đến khi cá và tôm vừa chín. Phục vụ trong bát rải rác với rau mùi.', NULL, '2026-05-15 14:52:04', '2026-05-16 12:35:34'),
(3863, 569, 1, 'Đặt các phi lê cá cạnh nhau trên một tờ giấy bạc hình vuông lớn và rải gừng, tỏi, ớt và vỏ chanh lên trên chúng. Rưới nước cốt chanh lên trên rồi rải các miếng pak choi xung quanh và phía trên con cá. Đổ nước tương lên pak choi và dán giấy bạc lại để tạo thành một gói, đảm bảo bạn chừa khoảng trống ở phía trên để hơi nước lưu thông khi cá chín.', NULL, '2026-05-15 14:52:05', '2026-05-16 12:35:34'),
(3865, 569, 2, 'Hấp trong 15 phút. (Nếu bạn không có nồi hấp, hãy đặt gói hàng lên đĩa cách nhiệt trên chảo nước sôi nhẹ, đậy nắp lại và hấp.)', NULL, '2026-05-15 14:52:05', '2026-05-16 12:35:34'),
(3866, 570, 1, 'Làm nóng lò ở mức 200C/400F/Gas 6 (quạt 180C).', NULL, '2026-05-15 14:52:06', '2026-05-15 14:52:06'),
(3867, 570, 2, 'Cho khoai tây vào nồi nước muối lạnh. Đun sôi và đun nhỏ lửa cho đến khi mềm hoàn toàn. Để ráo nước rồi nghiền với bơ và sữa. Thêm hạt tiêu và nếm thử để kiểm tra gia vị. Thêm muối và thêm hạt tiêu nếu cần thiết.', NULL, '2026-05-15 14:52:06', '2026-05-15 14:52:06'),
(3868, 570, 3, 'Để làm nhân cá, làm tan chảy bơ trong chảo, thêm tỏi tây vào và khuấy đều trên lửa. Đậy nắp và đun nhỏ lửa trong 10 phút hoặc cho đến khi mềm. Đong bột vào một cái bát nhỏ. Thêm rượu vào và đánh đều cho đến khi mịn.', NULL, '2026-05-15 14:52:06', '2026-05-15 14:52:06'),
(3869, 570, 4, 'Thêm sữa vào tỏi tây, đun sôi rồi thêm hỗn hợp rượu vào. Khuấy nhanh cho đến khi đặc lại. Nêm và thêm rau mùi tây và cá. Khuấy trên lửa trong hai phút, sau đó cho vào nồi chịu nhiệt. Rắc đều lên trứng. Để nguội cho đến khi cứng lại.', NULL, '2026-05-15 14:52:06', '2026-05-15 14:52:06'),
(3870, 570, 5, 'Đổ khoai tây nghiền lên hỗn hợp cá và đánh dấu bằng nĩa. Rắc phô mai.', NULL, '2026-05-15 14:52:06', '2026-05-15 14:52:06'),
(3871, 570, 6, 'Nướng trong 30-40 phút hoặc cho đến khi mặt trên có màu nâu vàng nhạt và sủi bọt xung quanh các cạnh.', NULL, '2026-05-15 14:52:06', '2026-05-15 14:52:06'),
(3873, 571, 1, 'Đun sôi nước kho trong nồi cỡ vừa. Thêm sả, riềng, rễ ngò và lá chanh vào đun nhỏ lửa trong 2 phút.', NULL, '2026-05-15 14:52:08', '2026-05-16 12:35:34'),
(3875, 571, 2, 'Thêm tôm, nước mắm, ớt và nước cốt chanh vào, sau đó đun sôi lại. Nêm nếm và điều chỉnh gia vị với thêm nước cốt chanh hoặc nước mắm, sau đó trang trí với lá ngò và dùng.', NULL, '2026-05-15 14:52:08', '2026-05-16 12:35:34'),
(3877, 572, 1, 'Đổ 1,3 lít nước vào nồi lớn trên lửa lớn. Thêm hành tây, cà chua, ớt, riềng, sả, đầu tôm và viên nước luộc gà vào. Khuấy và đun sôi, sau đó giảm nhiệt xuống mức trung bình và đun nhỏ lửa trong 20 phút cho đến khi chất lỏng giảm bớt.', NULL, '2026-05-15 14:52:09', '2026-05-16 12:35:34'),
(3879, 572, 2, 'Cẩn thận lọc nước dùng nóng vào tô hoặc bình chịu nhiệt lớn, sau đó loại bỏ đầu tôm. Cho hỗn hợp rau và thảo mộc đã lọc vào nồi và rưới nước dùng lên. Khuấy nấm và lá chanh rồi nấu trong 3 phút cho đến khi nấm mềm.', NULL, '2026-05-15 14:52:09', '2026-05-16 12:35:34'),
(3881, 572, 3, 'Thêm 1 muỗng canh đường, nước mắm, nước cốt chanh, nước cốt dừa và tôm. Đun sôi và nấu cho đến khi tôm chín, khoảng 1-2 phút. Hủy bỏ khỏi nhiệt. Vớt sả ra, sau đó cho mứt ớt Thái vào trộn đều nếu dùng. Rắc lên rau mùi để hoàn thành nếu bạn thích và thưởng thức.', NULL, '2026-05-15 14:52:09', '2026-05-16 12:35:34'),
(3882, 573, 1, 'Đun nóng 2 muỗng cà phê dầu trong chảo lớn và nấu hành lá trên lửa nhỏ trong 3 phút hoặc cho đến khi bắt đầu mềm. Thêm rau bina vào, đậy nắp kín và nấu thêm 2–3 phút hoặc cho đến khi mềm và héo, khuấy một hoặc hai lần. Đổ hỗn hợp vào rây hoặc chao rồi để ráo nước và nguội.', NULL, '2026-05-15 14:52:10', '2026-05-15 14:52:10'),
(3883, 573, 2, 'Sử dụng một chiếc đĩa làm hướng dẫn, cắt ra 24 vòng có đường kính khoảng 12,5 cm (5 in) từ bánh ngọt filo, cắt 6 vòng từ mỗi tờ. Xếp các cuộn filo thành một đống, sau đó dùng màng bọc thực phẩm bọc lại để chúng không bị khô.', NULL, '2026-05-15 14:52:10', '2026-05-15 14:52:10'),
(3884, 573, 3, 'Khi hỗn hợp rau bina nguội, vắt càng nhiều chất lỏng dư thừa càng tốt, sau đó chuyển vào tô. Thêm cá ngừ, trứng, sốt ớt cay, muối và hạt tiêu cho vừa ăn. Trộn đều.', NULL, '2026-05-15 14:52:10', '2026-05-15 14:52:10'),
(3885, 573, 4, 'Làm nóng lò ở nhiệt độ 200°C (400°F, vạch khí 6). Lấy một vòng filo và chải thật nhẹ với một ít dầu còn lại. Phủ vòng thứ hai lên trên và chải với một ít dầu, sau đó đặt vòng thứ ba lên trên và chải bằng dầu.', NULL, '2026-05-15 14:52:10', '2026-05-15 14:52:10'),
(3886, 573, 5, 'Đặt một muỗng canh nhân vào giữa viên tròn, sau đó gấp bánh lại để tạo thành hình bán nguyệt. Gấp các cạnh, xoắn chúng lại để bịt kín và đặt lên khay nướng chống dính. Lặp lại với phần bánh ngọt và nhân còn lại để tạo thành 8 chiếc bánh tất cả.', NULL, '2026-05-15 14:52:10', '2026-05-15 14:52:10'),
(3887, 573, 6, 'Nhẹ nhàng chải các sợi tóc bằng lượng dầu còn lại. Nướng trong 12–15 phút hoặc cho đến khi bánh giòn và có màu vàng nâu.', NULL, '2026-05-15 14:52:10', '2026-05-15 14:52:10'),
(3888, 573, 7, 'Trong khi đó, trộn cà chua và dưa chuột vào tô rồi rưới nước cốt chanh và gia vị cho vừa ăn. Ăn nóng bánh mì với món salad này và tương ớt.', NULL, '2026-05-15 14:52:10', '2026-05-15 14:52:10'),
(3889, 574, 1, 'Làm nóng lò ở 200C/quạt 180C/gas 6. Trộn khoai tây với 2 thìa cà phê dầu và một ít gia vị. Đặt lên một khay nướng lớn, sau đó nướng trong 20 phút, khuấy nửa chừng cho đến khi giòn, vàng và chín đều.', NULL, '2026-05-15 14:52:12', '2026-05-15 14:52:12'),
(3890, 574, 2, 'Trong khi đó, cho trứng vào chảo nước nhỏ, đun sôi rồi đun nhỏ lửa trong 8-10 phút, tùy thuộc vào cách bạn muốn trứng chín. Ngâm vào tô nước lạnh để nguội trong vài phút. Bóc vỏ, sau đó cắt làm đôi.', NULL, '2026-05-15 14:52:12', '2026-05-15 14:52:12'),
(3891, 574, 3, 'Trong một bát salad lớn, trộn đều dầu còn lại, giấm rượu vang đỏ, nụ bạch hoa và cà chua cắt nhỏ. Nêm, cho hành tây, rau bina, cá ngừ và khoai tây vào, sau đó nhẹ nhàng trộn đều. Phủ trứng lên trên, sau đó dùng ngay.', NULL, '2026-05-15 14:52:12', '2026-05-15 14:52:12'),
(3893, 575, 1, 'Cho đường vào một cái chảo nông lớn cùng với một chút nước. Đun nóng nhẹ, xoay chảo cho đến khi đường tan. Tăng nhiệt và đun sôi xi-rô cho đến khi nó chuyển sang màu hổ phách đậm. Cho nước mắm, phần lớn ớt và gừng vào, sau đó cho vào 1 thìa canh nước cho loãng. Đun sôi lại cho đến khi có nước siro, sau đó thêm phi lê cá, có da úp xuống, và cải chíp, cắt úp xuống.', NULL, '2026-05-15 14:52:14', '2026-05-16 12:35:34'),
(3895, 575, 2, 'Đậy nắp chảo và đun nhỏ lửa trong 4-5 phút cho đến khi cá chín và cải chíp héo. Tắt bếp, vắt chanh lên rồi rải đều ớt, gừng và nhánh ngò còn lại. Ăn kèm cơm.', NULL, '2026-05-15 14:52:14', '2026-05-16 12:35:34'),
(3897, 576, 1, 'Trộn tất cả các nguyên liệu làm nước chấm cùng với 50ml nước vào tô và đặt sang một bên để đường tan và hương vị ngấm.', NULL, '2026-05-15 14:52:15', '2026-05-16 12:35:34'),
(3899, 576, 2, 'Để gói các cuộn bánh, hãy đổ đầy nước ấm vào một chiếc bát rộng và lấy một chiếc khăn trà ẩm sạch để thực hiện. Nhúng giấy gói bánh tráng vào nước trong vài giây cho đến khi mềm rồi cẩn thận đặt lên khăn.', NULL, '2026-05-15 14:52:15', '2026-05-16 12:35:34'),
(3901, 576, 3, 'Đặt một ít lá bạc hà và rau mùi vào giữa giấy gói, sau đó đặt hai con tôm và một ít rau xoắn ốc lên trên, có thể cần phải cắt nhỏ nếu xoắn ốc quá dài.', NULL, '2026-05-15 14:52:15', '2026-05-16 12:35:34'),
(3903, 576, 4, 'Gấp các cạnh của giấy gói vào giữa, phủ lên trên phần nhân, sau đó gấp các cạnh sao cho phần nhân được bọc hoàn toàn, sau đó cuộn thật chặt. Lặp lại cho đến khi sử dụng hết giấy gói và phần nhân. Khi dùng, cắt chéo và ăn cùng nước chấm.', NULL, '2026-05-15 14:52:15', '2026-05-16 12:35:34'),
(3905, 577, 1, 'Cho tỏi vào tô cùng với gừng, nước cốt chanh, dầu, gia vị và hạt nêm. Dùng máy xay cầm tay xay nhuyễn cho đến khi mịn, sau đó dùng để phết sườn cừu lên cả hai mặt. Để ướp trong tủ lạnh vài giờ hoặc qua đêm.', NULL, '2026-05-15 14:52:17', '2026-05-16 12:35:34'),
(3907, 577, 2, 'Đun nóng thịt nướng cho đến khi nóng. Nướng sườn trên than khoảng 3 phút mỗi mặt cho đến khi chín nhưng vẫn còn màu hồng và mọng nước ở giữa.', NULL, '2026-05-15 14:52:17', '2026-05-16 12:35:34'),
(3908, 578, 1, 'Đặt freekeh vào một cái bát nhỏ và đậy lại bằng nước lạnh. Đặt sang một bên.', NULL, '2026-05-15 14:52:19', '2026-05-15 14:52:19'),
(3909, 578, 2, 'Cho thịt cừu, hành tây, tiêu đen, ớt bột, quế và muối vào nồi. Khuấy dầu, 1/2 củ ngò, 1/2 lá bạc hà và cọng cần tây cho đến khi hòa quyện. Đun nhỏ lửa ở nhiệt độ thấp trong 15 phút. Khuấy đậu xanh; đổ nước vừa đủ ngập rồi đun nhỏ lửa. Khuấy bí xanh, cà rốt và bột cà chua.', NULL, '2026-05-15 14:52:19', '2026-05-15 14:52:19'),
(3910, 578, 3, 'Đặt nồi hấp lên trên nồi; thêm cà chua. Đậy nắp và hấp cà chua cho đến khi mềm, khoảng 5 phút. Nghiền cà chua bằng thìa gỗ để bã cà chua nhỏ vào súp. Lấy nồi hấp ra và loại bỏ vỏ cà chua còn sót lại.', NULL, '2026-05-15 14:52:19', '2026-05-15 14:52:19'),
(3911, 578, 4, 'Thêm khoai tây vào súp và lượng nước vừa đủ. Đun nhỏ lửa cho đến khi khoai tây mềm, khoảng 10 phút.', NULL, '2026-05-15 14:52:19', '2026-05-15 14:52:19'),
(3912, 578, 5, 'Xả freekeh và thêm vào súp. Đun nhỏ lửa cho đến khi mềm, khoảng 15 phút. Loại bỏ cuống cần tây và loại bỏ. Rắc súp với 1/2 ngò còn lại và 1/2 lá bạc hà còn lại trước khi dùng.', NULL, '2026-05-15 14:52:19', '2026-05-15 14:52:19'),
(3913, 579, 1, 'Cắt thịt cừu thành miếng lớn.', NULL, '2026-05-15 14:52:20', '2026-05-15 14:52:20'),
(3914, 579, 2, 'Cắt bắp cải thành từng miếng lớn, giữ nguyên phần lõi.', NULL, '2026-05-15 14:52:20', '2026-05-15 14:52:20'),
(3915, 579, 3, 'Xếp một lớp miếng thịt cừu vào đáy nồi lớn, úp mặt mỡ xuống. Rắc hạt tiêu và muối. Thêm một lớp bắp cải nêm lên trên. Lặp lại với nhiều lớp thịt cừu, hạt tiêu và bắp cải hơn, kết thúc bằng bắp cải ở trên.', NULL, '2026-05-15 14:52:20', '2026-05-15 14:52:20'),
(3916, 579, 4, 'Tùy chọn: Rắc một vài thìa lên trên miếng thịt cừu để có món hầm đặc hơn.', NULL, '2026-05-15 14:52:20', '2026-05-15 14:52:20'),
(3917, 579, 5, 'Thêm nước vào nồi và đun sôi. Che và giảm nhiệt. Nấu trên lửa nhỏ trong 2 – 3 giờ, cho đến khi thịt cừu nhẹ nhàng rời khỏi xương.', NULL, '2026-05-15 14:52:20', '2026-05-15 14:52:20'),
(3918, 579, 6, 'Ăn kèm với khoai tây luộc và rau mùi tây tươi, phủ đều nước dùng fårikål.', NULL, '2026-05-15 14:52:20', '2026-05-15 14:52:20'),
(3920, 580, 1, 'Làm nóng chảo nướng. Xoa thịt cừu bít tết với dầu, thì là và một ít gia vị. Nướng khoảng 3-4 phút mỗi mặt hoặc cho đến khi chín theo ý thích của bạn. Đặt sang một bên trên đĩa để nghỉ ngơi.', NULL, '2026-05-15 14:52:21', '2026-05-16 12:35:34'),
(3922, 580, 2, 'Trong một tô lớn, khuấy đường vào giấm cho đến khi hòa tan. Thêm cà rốt, hành lá, bắp cải và một ít gia vị vào rồi trộn đều.', NULL, '2026-05-15 14:52:21', '2026-05-16 12:35:34'),
(3924, 580, 3, 'Nghiền toàn bộ ớt và mayo trong máy xay thực phẩm. Thêm một đống salad vào mỗi chiếc bánh mì dẹt. Cắt lát thịt cừu, cắt bỏ phần mỡ thừa và đặt lên trên món salad, rưới nước trái cây còn lại. Rưới sốt mayo lên và rắc một ít ớt cắt lát. Cuộn lại và ăn. Nếu sử dụng pitta, chia nhỏ và nhồi. Phục vụ thêm bất kỳ món salad nào ở bên cạnh.', NULL, '2026-05-15 14:52:21', '2026-05-16 12:35:34'),
(3926, 581, 1, 'Làm nóng lò nướng ở mức quạt/khí 190C/170C 5. Cắt đôi quả cà tím theo chiều dọc và khía sâu vào mặt thịt, phết một lớp dầu ô liu vừa phải rồi đặt lên khay nướng. Nướng trong 20 phút hoặc cho đến khi thịt đủ mềm để múc ra.', NULL, '2026-05-15 14:52:22', '2026-05-16 12:35:34'),
(3928, 581, 2, 'Chiên hành tây với một ít dầu cho đến khi mềm, thêm tỏi và quế vào xào trong 1 phút. Sau khi cà tím đủ nguội để cầm, hãy múc phần giữa của cà tím. Cắt nhỏ thịt và thêm vào hành tây. Cắt đôi quả cà chua, múc hạt và nước ép vào rây đặt trên bát, sau đó cắt nhỏ thịt. Thêm cà chua xắt nhỏ vào chảo và nấu mọi thứ trong 10 phút cho đến khi mềm và ngon. Thêm một chút dầu nếu bạn cần. Khuấy mùi tây, để lại một ít để rải ở cuối.', NULL, '2026-05-15 14:52:22', '2026-05-16 12:35:34'),
(3930, 581, 3, 'Đặt hai nửa cà tím vào đĩa nướng và chia hỗn hợp cà chua vào giữa chúng. Đổ nước ép từ cà chua lên, rưới thêm dầu ô liu và nướng trong 30 phút cho đến khi cà tím xẹp xuống.', NULL, '2026-05-15 14:52:22', '2026-05-16 12:35:34'),
(3932, 581, 4, 'Trong khi đó, trộn các nguyên liệu tzatziki với nhau và cho vào tô nhỏ.', NULL, '2026-05-15 14:52:22', '2026-05-16 12:35:34'),
(3934, 581, 5, 'Nêm thịt cừu với muối, hạt tiêu đen và một chút ớt bột. Nướng, nướng hoặc nướng thịt trong 3 phút mỗi mặt hoặc cho đến khi mỡ có màu nâu vàng đẹp mắt, sau đó đặt vào đĩa phục vụ và vắt lên nửa quả chanh. Rắc cà tím với rau mùi tây, sau đó dùng kèm với thịt cừu và tzatziki.', NULL, '2026-05-15 14:52:22', '2026-05-16 12:35:34'),
(3936, 582, 1, 'Cho thịt băm vào một cái tô lớn (dùng bát rửa sạch nếu bạn không có thứ gì đủ lớn) cùng với tất cả các nguyên liệu làm bánh mì kẹp thịt khác và một chút muối. Xắn tay áo lên, nhúng tay vào hỗn hợp và trộn mọi thứ lại với nhau bằng ngón tay cho đến khi trộn hoàn toàn. Đổ hỗn hợp vào 16 chiếc bánh mì kẹp thịt nhỏ. Bây giờ chúng có thể được đông lạnh trong tối đa 1 tháng hoặc làm lạnh trước một ngày.', NULL, '2026-05-15 14:52:25', '2026-05-16 12:35:34'),
(3938, 582, 2, 'Để nấu, hãy làm nóng vỉ nướng ở mức cao nhất và xếp bánh mì kẹp thịt thành một lớp trên khay nướng (bạn có thể cần thực hiện việc này theo từng mẻ, tùy thuộc vào kích thước khay của bạn). Nướng ở kệ cao nhất trong 5-6 phút mỗi mặt cho đến khi chín vàng và chín đều. Xếp bánh mì kẹp thịt lên đĩa và phục vụ cùng với tất cả các món ăn kèm để mọi người có thể tự làm bánh sandwich cho mình.', NULL, '2026-05-15 14:52:25', '2026-05-16 12:35:34'),
(3940, 583, 1, 'Đun nóng 2 muỗng cà phê dầu trong chảo và cho hành tây vào xào mềm trong 5 phút. Thêm tỏi và gia vị và nấu thêm vài phút nữa. Múc một nửa hỗn hợp hành tây vào tô và để nguội. Thêm cà chua, đường và gia vị vào số hành còn lại trong chảo và đun nhỏ lửa trong khoảng 10 phút cho đến khi chín.', NULL, '2026-05-15 14:52:26', '2026-05-16 12:35:34'),
(3942, 583, 2, 'Trong khi đó, thêm bạc hà, thịt cừu, quả mơ và vụn bánh mì vào hành đã nguội, nêm gia vị và dùng tay trộn đều. Tạo hình thành những viên thịt nhỏ.', NULL, '2026-05-15 14:52:26', '2026-05-16 12:35:34'),
(3944, 583, 3, 'Đun nóng phần dầu còn lại trong chảo chống dính và chiên thịt viên cho đến khi vàng (theo từng mẻ nếu bạn cần). Khuấy nước sốt với một chút nước và nấu nhẹ mọi thứ trong vài phút cho đến khi thịt viên chín. Ăn kèm bánh mì pitta và salad.', NULL, '2026-05-15 14:52:26', '2026-05-16 12:35:35'),
(3945, 584, 1, 'Nghiền tỏi với muối biển bằng chày và cối (hoặc dùng máy xay thực phẩm nhỏ) cho đến khi tỏi tạo thành hỗn hợp sệt. Trộn đều dầu, nước cốt chanh, vỏ, thì là và tỏi. Trộn thịt cừu vào và trộn đều. Đậy nắp và ướp ít nhất 2 tiếng hoặc qua đêm trong tủ lạnh. Nếu bạn định sử dụng xiên tre, hãy ngâm chúng trong nước lạnh.', NULL, '2026-05-15 14:52:27', '2026-05-15 14:52:27'),
(3946, 584, 2, 'Nếu bạn đã chuẩn bị thịt cừu vào ngày hôm trước, hãy lấy thịt ra khỏi tủ lạnh 30 phút trước khi nấu. Xiên thịt vào xiên đã ngâm nước hoặc kim loại. Làm nóng lò nướng ở mức cao hoặc chuẩn bị sẵn chảo nướng nóng hoặc món nướng. Nướng xiên trong 2-3 phút mỗi mặt, phết phần nước xốt còn lại. Đun nóng bánh pitta hoặc bánh mì dẹt trong thời gian ngắn, sau đó nhồi souvlaki vào. Thêm salad Hy Lạp (xem \'Rất hợp\', bên phải) và Tzatziki (bên dưới), nếu bạn thích.', NULL, '2026-05-15 14:52:27', '2026-05-15 14:52:27'),
(3947, 585, 1, 'Rắc thịt bằng bột mì để phủ nhẹ.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3948, 585, 2, 'Đun nóng lượng dầu thực vật vừa đủ trong một cái chảo lớn để đổ đầy đế rồi xào hành tây và thịt cho đến khi chín vàng nhạt. Nêm muối và hạt tiêu.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3949, 585, 3, 'Thêm cà rốt, nước luộc và thêm gia vị cho vừa ăn.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3950, 585, 4, 'Đun sôi, đậy nắp và giảm nhiệt cho sôi. Đun nhỏ lửa ít nhất một giờ hoặc cho đến khi thịt mềm. Hãy dành thời gian nấu thịt, để càng lâu thì hương vị sẽ càng ngon.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3951, 585, 5, 'Làm nóng lò ở 180C/350F/Gas 4.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3952, 585, 6, 'Thêm khối khoai tây đã ráo nước vào thịt cừu.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3953, 585, 7, 'Biến hỗn hợp thành đĩa bánh hoặc món thịt hầm và phủ một lớp vỏ bánh ngọt lên trên. Tạo ba khe ở mặt trên của bánh ngọt để thoát hơi nước trong khi nấu.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3954, 585, 8, 'Quét một lớp trứng đã đánh lên và nướng trong khoảng 40 phút cho đến khi bánh có màu vàng nâu.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3955, 585, 9, 'Phục vụ.', NULL, '2026-05-15 14:52:28', '2026-05-15 14:52:28'),
(3956, 586, 1, 'Nghiền hạt điều, hạt anh túc và hạt thì là thành bột nhão mịn, sử dụng càng ít nước càng tốt. Đặt sang một bên.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3957, 586, 2, 'Chiên hành tây thái lát khi còn nóng. Đừng đổ quá nhiều dầu. Khi hành tây chuyển sang màu nâu nhạt, vớt ra để ráo dầu trên khăn giấy. Hành tây chiên sẽ giòn khi để ráo nước. Cũng chiên hạt điều cho đến khi vàng nâu. Đặt sang một bên.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3958, 586, 3, 'Vo gạo và ngâm trong nước trong hai mươi phút.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3959, 586, 4, 'Trong khi đó, lấy một chiếc chảo lớn, cho dầu vào lửa vừa, cho hành tây thái lát, thêm hỗn hợp đã trộn vào, thêm ớt xanh, gừng, tỏi và tỏi vào xào trong một phút.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3960, 586, 5, 'Sau đó cho cà chua vào xào chín và không bị nhão.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3961, 586, 6, 'Sau đó, thêm bột ớt đỏ, bột biryani, bạc hà, lá rau mùi và xào đều.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3962, 586, 7, 'Thêm sữa chua và trộn đều. Tôi luôn di chuyển chảo ra xa nguồn nhiệt khi thêm sữa chua để tránh sữa đông lại.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3963, 586, 8, 'Bây giờ sau khi đặt chảo trở lại bếp, cho thịt cừu đã rửa sạch, muối và ½ cốc nước vào trộn đều. Nấu trong 1 giờ và đun ở lửa vừa thấp hoặc cho vào nồi áp suất trong 6 tiếng còi. Nếu nước chưa thoát hết, hãy làm nóng nó bằng cách mở nắp.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3964, 586, 9, 'Lấy một cái chảo lớn khác, cho gấp ba chén gạo bạn dùng vào rồi đun sôi. Khi nước sôi cao, cho gạo, muối và jeera vào rồi trộn đều. Chính xác là sau 7 phút hoặc khi cơm chín được 80%. Tắt và xả gạo.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3965, 586, 10, 'Bây giờ, việc phân lớp bắt đầu. Để thịt cừu, vỗ nhẹ và san bằng nó. Thêm cơm nóng đã ráo nước lên trên. Trang trí với hành tây chiên, bơ sữa trâu, bạc hà, lá rau mùi và nghệ tây hòa tan trong sữa.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3966, 586, 11, 'Đậy đĩa và nướng trong lò 350f trong 15 phút hoặc cho đến khi chín nhưng không nhão. Hoặc nấu trên bếp lửa vừa trong 12 phút và lửa nhỏ nhất trong 5 phút. Và tắt đi. Trộn và dùng nóng!', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3967, 586, 12, 'Ghi chú', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3968, 586, 13, '1. Nếu bạn nấu trong lò nướng, hãy đảm bảo nấu trong chảo lớn an toàn cho lò nướng và đậy nắp kín rồi cho vào lò nướng cho bước cuối cùng.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3969, 586, 14, '2. Bạn có thể bỏ qua biryani masala nếu không có và chỉ thêm garam masala (1 thìa cà phê và bột ớt đỏ – 3 thìa cà phê thay vì 1 thìa cà phê)', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3970, 586, 15, '3. Nếu cuối cùng nó cay, hãy vắt một ít chanh, nó sẽ làm giảm nhiệt và tăng hương vị.', NULL, '2026-05-15 14:52:29', '2026-05-15 14:52:29'),
(3971, 587, 1, 'Đặt nho khô và mận vào một cái bát nhỏ và đổ lượng nước vừa đủ. Thêm nước cốt chanh và ngâm ít nhất 1 giờ. Làm khô hạn. Cắt nhỏ mận.', NULL, '2026-05-15 14:52:31', '2026-05-15 14:52:31');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(3972, 587, 2, 'Trong khi đó, đun nóng bơ trong chảo lớn, thêm hành tây và nấu trong 5 phút. Thêm thịt cừu thái miếng, thịt cừu xay và tép tỏi nghiền. Chiên trong 5 phút, khuấy liên tục cho đến khi chín vàng.', NULL, '2026-05-15 14:52:31', '2026-05-15 14:52:31'),
(3973, 587, 3, 'Đổ 2/3 cốc (150 ml) nước dùng vào chảo. Đun sôi, sau đó giảm nhiệt, đậy nắp và đun nhỏ lửa trong 1 giờ hoặc cho đến khi thịt cừu mềm.', NULL, '2026-05-15 14:52:31', '2026-05-15 14:52:31'),
(3974, 587, 4, 'Thêm lượng nước còn lại vào và đun sôi. Thêm gạo trắng hạt dài đã vo sạch và một nhúm nghệ tây lớn. Khuấy đều, sau đó đậy nắp và đun nhỏ lửa trong 15 phút hoặc cho đến khi gạo mềm.', NULL, '2026-05-15 14:52:31', '2026-05-15 14:52:31'),
(3975, 587, 5, 'Thêm nho khô đã ráo nước, mận cắt nhỏ để ráo nước, muối và hạt tiêu cho vừa ăn. Đun nóng trong vài phút, sau đó bày ra đĩa đã hâm nóng và trang trí với những nhánh mùi tây lá dẹt.', NULL, '2026-05-15 14:52:31', '2026-05-15 14:52:31'),
(3976, 588, 1, 'Cho hành tây vào máy xay thực phẩm và xay cho đến khi thái nhỏ. Đun nóng dầu trong chảo lớn có đế dày, sau đó đậy nắp lại cho hành tây vào chiên, thỉnh thoảng đảo đều cho đến khi hành tây thật vàng và mềm. Thêm tỏi và gừng, sau đó chiên thêm 5 phút nữa.', NULL, '2026-05-15 14:52:32', '2026-05-15 14:52:32'),
(3977, 588, 2, 'Cho bột cà ri, tất cả gia vị và lá nguyệt quế vào chảo cùng với cà chua xay nhuyễn. Khuấy đều trên lửa khoảng 30 giây rồi cho thịt và 300ml nước vào. Khuấy đều, giảm lửa, sau đó thêm sữa chua.', NULL, '2026-05-15 14:52:32', '2026-05-15 14:52:32'),
(3978, 588, 3, 'Đậy nắp chảo, sau đó đun nhỏ lửa trong 40-60 phút cho đến khi thịt mềm và nước sốt đặc và đẹp mắt. Ăn kèm với rau mùi, cơm basmati hoặc cơm pilau.', NULL, '2026-05-15 14:52:32', '2026-05-15 14:52:32'),
(3979, 589, 1, 'Đun nóng dầu ô liu trong chảo có đáy dày rồi cho hành tây và cà rốt vào. Nấu trong 3-4 phút cho đến khi mềm.', NULL, '2026-05-15 14:52:35', '2026-05-15 14:52:35'),
(3980, 589, 2, 'Thêm thịt cừu thái hạt lựu và nâu khắp mặt. Khuấy tỏi và tất cả các loại gia vị và nấu thêm vài phút nữa hoặc cho đến khi mùi thơm tỏa ra.', NULL, '2026-05-15 14:52:35', '2026-05-15 14:52:35'),
(3981, 589, 3, 'Thêm mật ong và quả mơ, nghiền nát thành viên và đổ khoảng 500ml nước sôi hoặc đủ ngập thịt. Khuấy đều và đun sôi. Vặn lửa nhỏ, đậy nắp và nấu trong 1 giờ.', NULL, '2026-05-15 14:52:35', '2026-05-15 14:52:35'),
(3982, 589, 4, 'Đậy nắp và nấu thêm 30 phút nữa thì cho bí vào khuấy đều. Nấu thêm 20 – 30 phút nữa cho đến khi bí mềm và thịt cừu mềm. Ăn kèm với cơm hoặc couscous và rắc rau mùi tây và hạt thông, nếu dùng.', NULL, '2026-05-15 14:52:35', '2026-05-15 14:52:35'),
(3983, 590, 1, 'Ở đây dùng lá nho ngâm chua, bảo quản trong nước muối. Những chiếc lá nhỏ mỏng manh sẽ tốt hơn những chiếc lá lớn có nhiều lông, tuy nhiên, nếu chỉ dùng những chiếc lá lớn thì hãy cắt chúng thành khoảng 12 x 12 cm để không có quá nhiều lớp lá xung quanh nhân bánh. Và loại bỏ bất kỳ thân cây nào. Xả sạch lá đã bảo quản, ngâm trong nước sôi trong 10 phút rồi để khô trên khăn trước khi sử dụng.', NULL, '2026-05-15 14:52:36', '2026-05-15 14:52:36'),
(3984, 590, 2, 'Cơm basmati với bơ và hạt thông là món ăn kèm lý tưởng. Couscous cũng tuyệt vời. Phục vụ bốn.', NULL, '2026-05-15 14:52:36', '2026-05-15 14:52:36'),
(3985, 590, 3, 'Đầu tiên làm nhân. Cho tất cả nguyên liệu, trừ cà chua, vào tô. Cắt cà chua làm đôi, xay thô cho vào bát và bỏ vỏ. Thêm nửa muỗng cà phê muối và một ít hạt tiêu đen vào rồi khuấy đều. Để sang một bên hoặc trong tủ lạnh tối đa một ngày. Trước khi sử dụng, dùng tay bóp nhẹ và chắt hết nước chảy ra.', NULL, '2026-05-15 14:52:36', '2026-05-15 14:52:36'),
(3986, 590, 4, 'Để làm nước sốt, đun nóng dầu trong chảo vừa. Thêm gừng và tỏi, nấu trong một hoặc hai phút, chú ý không làm cháy chúng, sau đó thêm cà chua, nước cốt chanh và đường. Nêm, đun nhỏ lửa trong 20 phút.', NULL, '2026-05-15 14:52:36', '2026-05-15 14:52:36'),
(3987, 590, 5, 'Trong khi nước sốt đang sủi bọt, chuẩn bị lá nho. Dùng những chiếc lá rách hoặc gãy để lót đáy một cái chảo rộng và nặng. Cắt bỏ hết lá thì là, cắt dọc thành từng lát dày 0,5cm rồi trải lên đáy chảo cho kín.', NULL, '2026-05-15 14:52:36', '2026-05-15 14:52:36'),
(3988, 590, 6, 'Đặt một chiếc lá nho đã chuẩn bị sẵn (xem phần giới thiệu) lên bề mặt làm việc, mặt có gân hướng lên trên. Đặt hai thìa cà phê nhân ở gốc lá thành một dải dài 2cm x rộng 1cm. Gấp các cạnh của chiếc lá lên trên phần nhân, sau đó cuộn chặt từ dưới lên trên theo hình điếu xì gà. Đặt vào chảo, khâu lại và lặp lại với những chiếc lá còn lại, đặt chúng sát cạnh nhau theo đường thẳng hoặc hình tròn (thành hai lớp nếu cần).', NULL, '2026-05-15 14:52:36', '2026-05-15 14:52:36'),
(3989, 590, 7, 'Đổ nước sốt lên lá (và nếu cần, thêm nước vừa đủ). Đặt một cái đĩa lên trên, để cân lá xuống rồi đậy nắp lại. Đun sôi, giảm nhiệt và nấu trên lửa nhỏ trong 70 phút. Hầu hết chất lỏng sẽ bay hơi. Tắt bếp và để nguội một chút - tốt nhất nên dùng khi còn ấm. Khi phục vụ, hãy mang ra bàn trong chảo - trông rất tuyệt. Ăn một ít lá nho và lát thì là với cơm ấm. Múc nước cốt om lên trên và trang trí với rau mùi.', NULL, '2026-05-15 14:52:36', '2026-05-15 14:52:36'),
(3990, 591, 1, 'Đổ bulghar vào chảo, đổ nước vào và đun sôi trong 10 phút. Xả thật kỹ trong một cái rây, ép hết nước thừa.', NULL, '2026-05-15 14:52:38', '2026-05-15 14:52:38'),
(3991, 591, 2, 'Để làm món tzatziki, hãy ép và ép lấy nước từ dưa chuột, sau đó trộn vào sữa chua cùng với lá bạc hà cắt nhỏ và một chút muối.', NULL, '2026-05-15 14:52:38', '2026-05-15 14:52:38'),
(3992, 591, 3, 'Trộn bulghar vào thịt cừu với gia vị, tỏi (nếu dùng) và gia vị, sau đó tạo hình thành 4 chiếc bánh mì kẹp thịt. Quét một ít dầu rồi chiên hoặc nướng mỗi mặt khoảng 5 phút cho đến khi chín hẳn. Ăn kèm với bánh mì (nướng nếu bạn thích) với tzatziki, cà chua, hành tây và một ít lá bạc hà.', NULL, '2026-05-15 14:52:38', '2026-05-15 14:52:38'),
(3993, 592, 1, 'Làm nóng lò nướng ở 160C/quạt 140C/gas 3. Đun nóng một ít bơ hoặc bơ trong một đĩa thịt hầm lớn, nông, làm chín thịt cừu theo từng mẻ, gắp ra đĩa, sau đó lặp lại với thận.', NULL, '2026-05-15 14:52:39', '2026-05-15 14:52:39'),
(3994, 592, 2, 'Chiên hành tây và cà rốt trong chảo với độ nhỏ giọt nhỏ hơn một chút cho đến khi vàng. Rắc bột lên trên, để chín trong vài phút, rưới nước sốt Worcestershire lên, đổ nước kho vào, sau đó đun sôi. Cho thịt và lá nguyệt quế vào trộn đều rồi tắt bếp. Xếp khoai tây thái lát lên trên miếng thịt, sau đó rưới thêm một ít nước nhỏ giọt. Đậy nắp lại rồi cho vào lò nướng khoảng 1 tiếng rưỡi cho đến khi khoai tây chín.', NULL, '2026-05-15 14:52:39', '2026-05-15 14:52:39'),
(3995, 592, 3, 'Mở nắp, quét khoai tây với một chút nước nhỏ giọt, sau đó bật lò nướng để khoai tây chín vàng hoặc nướng chín trong 5-8 phút cho đến khi chín vàng.', NULL, '2026-05-15 14:52:39', '2026-05-15 14:52:39'),
(3996, 593, 1, 'Làm nóng chảo lớn và nướng hạt thì là trong vài phút, sau đó đặt sang một bên. Đun nóng dầu trong cùng một chảo rồi xào hành, tỏi, ớt, tiêu và một chút muối trong khoảng 8 phút cho đến khi không còn độ ẩm. Tắt bếp, cho hạt thì là đã nướng, hạt nhục đậu khấu (hoặc nhục đậu khấu) và rau mùi xay vào trộn đều. Để nguội.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(3997, 593, 2, 'Trong một tô lớn, trộn thịt cừu băm, tiêu trắng, rau mùi tươi và hỗn hợp hành tây đã nguội với gia vị cho đến khi hòa quyện. Đặt sang một bên, đậy kín, cho vào tủ lạnh.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(3998, 593, 3, 'Làm nóng lò nướng ở nhiệt độ 200C/400F/Gas 6 và bôi mỡ mỡ vào khuôn bánh hình tròn có đáy rời hoặc dạng lò xo có đường kính 20cm/8in.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(3999, 593, 4, 'Để làm bánh ngọt, rây bột mì và muối vào tô lớn rồi tạo một cái giếng ở giữa.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(4000, 593, 5, 'Cho sữa, mỡ lợn và 90ml/3fl oz nước vào nồi và đun nóng nhẹ. Khi mỡ lợn đã tan chảy, tăng lửa và đun sôi.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(4001, 593, 6, 'Đổ nước sôi vào bột, dùng thìa gỗ trộn đều cho đến khi đủ nguội để cầm. Tập hợp lại thành một quả bóng.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(4002, 593, 7, 'Phủi bột mì lên bề mặt làm việc và nhào bột nhanh chóng - bột sẽ mềm và ẩm. Dành một phần ba số bánh ngọt và lăn phần còn lại trên bề mặt đã rắc bột mì. Lót đĩa bánh với bánh ngọt, ấn thẳng vào các cạnh cho đến khi nó nhô lên trên mặt hộp thiếc.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(4003, 593, 8, 'Thêm từng chút nhân vào khuôn đã lót bánh ngọt. Khi bạn đạt đến đỉnh, hãy tạo thành một đỉnh nhẹ. Cán mỏng phần bánh ngọt đã dành riêng và phủ lên trên chiếc bánh. Chụm các cạnh để bịt kín và cắt bớt phần thừa. Đục một lỗ trên mặt bánh rồi nhét một ống nhỏ làm từ lá nhôm vào để hơi nước thoát ra ngoài.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(4004, 593, 9, 'Quét một ít lòng đỏ trứng đã đánh bông lên mặt bánh rồi nướng trong lò đã làm nóng trước trong 30 phút (đặt một cái khay lên kệ bên dưới để hứng những giọt nước nhỏ xuống). Sau đó giảm nhiệt độ xuống 160C/325F/Gas 3 và nấu thêm 1¼ giờ cho đến khi có màu vàng nâu. Để nguội hoàn toàn trước khi cho vào tủ lạnh trong hai giờ hoặc qua đêm.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(4005, 593, 10, 'Dùng dao chạy quanh mép bánh, lấy ra khỏi khuôn và dùng kèm tương ớt, salad hoặc dưa chua.', NULL, '2026-05-15 14:52:40', '2026-05-15 14:52:40'),
(4006, 594, 1, 'Đun nóng một thìa dầu trong chảo xào lớn có nắp đậy. Thêm các miếng xúc xích vào và chiên trên lửa vừa cao trong 10 phút, khuấy đều cho đến khi có màu vàng nâu. Chuyển xúc xích ra đĩa, sau đó cho hành tây và thì là vào chảo nóng xào trong 15 phút, thỉnh thoảng đảo đều cho đến khi mềm và có màu caramen; nếu chảo hơi khô, hãy thêm một thìa cà phê dầu. Khuấy ớt bột, tỏi và một nửa hạt thì là, chiên thêm hai phút, sau đó đổ rượu vào và đun sôi trong 30 giây, giảm còn một nửa. Cho cà chua, đường, 100ml nước, xúc xích xào và nửa thìa muối vào, đậy nắp đun nhỏ lửa trong 30 phút; mở nắp sau 10 phút và nấu cho đến khi nước sốt đặc và đậm đà. Tắt bếp, khuấy đều ô liu và hạt thì là còn lại rồi đặt sang một bên cho đến khi bạn sẵn sàng dùng.', NULL, '2026-05-15 14:52:42', '2026-05-15 14:52:42'),
(4007, 594, 2, 'Đun sôi một nồi nước muối lớn, cho mì ống vào và nấu trong 12-14 phút (hoặc theo hướng dẫn trên gói) cho đến khi chín. Trong khi đó, hâm nóng lại nước sốt. Xả sạch mì ống, cho vào nồi, cho một thìa dầu vào đảo đều rồi chia ra các bát.', NULL, '2026-05-15 14:52:42', '2026-05-15 14:52:42'),
(4008, 594, 3, 'Cho tất cả nguyên liệu pesto trừ húng quế vào tô nhỏ của máy xay thực phẩm. Thêm một thìa nước và blitz để tạo thành hỗn hợp sệt. Thêm húng quế vào, sau đó xay nhuyễn cho đến khi hòa quyện (món pesto có kết cấu ngon hơn nhiều nếu húng quế không được trộn quá kỹ).', NULL, '2026-05-15 14:52:42', '2026-05-15 14:52:42'),
(4009, 594, 4, 'Rưới lên miếng ragù và phủ một thìa pesto lên trên. Kết thúc bằng việc rắc lá thì là xắt nhỏ, nếu có, và dùng ngay.', NULL, '2026-05-15 14:52:42', '2026-05-15 14:52:42'),
(4011, 595, 1, 'Cho thịt cừu vào túi đựng thức ăn lớn cùng với toàn bộ nước cốt và ướp qua đêm.', NULL, '2026-05-15 14:52:43', '2026-05-16 12:35:35'),
(4013, 595, 2, 'Ngày hôm sau, lấy thịt cừu ra khỏi tủ lạnh 1 giờ trước khi bạn muốn nấu. Làm nóng lò ở mức quạt/gas 220C/200C 7. Lấy thịt cừu ra khỏi nước ướp (dự trữ nước ướp còn lại) và lau khô. Xoa với một nửa lượng dầu và nướng trong 15-20 phút cho đến khi chín vàng. Lấy thịt cừu ra và giảm nhiệt độ lò xuống 160C/140C quạt/gas 3.', NULL, '2026-05-15 14:52:43', '2026-05-16 12:35:35'),
(4015, 595, 3, 'Trộn vỏ, dầu còn lại, mật ong, gia vị và tỏi với nhiều gia vị. Đặt một tờ giấy nướng lớn lên một tờ giấy bạc lớn. Đặt chân cừu lên trên, thoa hỗn hợp lên khắp người và kéo các cạnh của giấy bạc lên. Rưới nước xốt vào đế và vò giấy bạc để bịt kín.', NULL, '2026-05-15 14:52:43', '2026-05-16 12:35:35'),
(4017, 595, 4, 'Nướng trong 4 giờ, cho đến khi rất mềm. Nghỉ ngơi, vẫn quấn trong 30 phút. Mở gói và phục vụ với nước trái cây.', NULL, '2026-05-15 14:52:43', '2026-05-16 12:35:35'),
(4019, 596, 1, 'Để làm hỗn hợp gia vị, trộn tất cả nguyên liệu lại với nhau với một nhúm muối lớn. Dùng dao sắc chém khắp vai cừu và chà xát. Nếu có thời gian, hãy ướp trong tối đa 24 giờ, nhưng điều này không cần thiết.', NULL, '2026-05-15 14:52:45', '2026-05-16 12:35:35'),
(4021, 596, 2, 'Làm nóng lò nướng ở mức quạt/khí 150C/130C 2. Đun nóng dầu trong đĩa thịt hầm lớn chống cháy hoặc hộp nướng trên lửa vừa cao, thêm hành tây, cà rốt và tỏi vào rồi đun nhỏ lửa trong 5 phút cho đến khi hành tây và cà rốt mềm. Đổ nước kho vào, sau đó đun sôi. Nhúng thịt cừu vào chảo và đậy nắp, sau đó chuyển vào lò nướng và nướng trong 2 giờ.', NULL, '2026-05-15 14:52:45', '2026-05-16 12:35:35'),
(4023, 596, 3, 'Khám phá và chuyển thịt cừu vào đĩa bằng kẹp. Khuấy đậu, ớt và ô liu với nước luộc trong chảo, đặt thịt cừu lên trên rồi cho vào lò nướng, không đậy nắp, trong 1 giờ 30 phút cho đến khi thịt cừu chín. Chuyển thịt cừu sang thớt và dùng hai chiếc nĩa xé nhỏ. Khuấy mùi tây qua đậu om trước khi dùng.', NULL, '2026-05-15 14:52:45', '2026-05-16 12:35:35'),
(4024, 597, 1, 'Làm nóng lò ở mức quạt/khí 180C/160C 4. Cắt bỏ phần ngọn của cà chua và để dành. Dùng thìa cà phê múc phần lớn cùi, cẩn thận để không làm rách vỏ. Cắt nhỏ bã và giữ lại nước trái cây. Rắc một ít đường vào bên trong cà chua để khử bớt axit rồi đặt cà chua lên khay nướng.', NULL, '2026-05-15 14:52:46', '2026-05-15 14:52:46'),
(4025, 597, 2, 'Đun nóng 2 muỗng canh dầu ô liu trong chảo lớn, cho hành tây và tỏi vào, sau đó xào nhẹ khoảng 10 phút cho đến khi mềm nhưng không có màu. Thêm thịt cừu, quế và cà chua xay nhuyễn vào, vặn lửa lớn rồi chiên cho đến khi thịt chín vàng. Thêm bột cà chua và nước ép, gạo và nước kho. Mùa một cách hào phóng. Đun sôi, sau đó đun nhỏ lửa trong 15 phút hoặc cho đến khi gạo mềm và chất lỏng đã được hấp thụ. Đặt sang một bên để nguội một chút, sau đó khuấy đều các loại thảo mộc.', NULL, '2026-05-15 14:52:46', '2026-05-15 14:52:46'),
(4026, 597, 3, 'Nhồi cà chua đến miệng, đậy nắp cà chua lại, rưới thêm 2 thìa dầu ô liu, rưới 3 thìa nước vào khay rồi nướng trong 35 phút. Ăn kèm salad và bánh mì giòn, nóng hoặc lạnh.', NULL, '2026-05-15 14:52:46', '2026-05-15 14:52:46'),
(4027, 598, 1, 'Cho thịt cừu vào nồi và nấu trên lửa cao. Khi chín vàng, tắt bếp và đặt sang một bên.', NULL, '2026-05-15 14:52:47', '2026-05-15 14:52:47'),
(4028, 598, 2, 'Giữ một thìa mỡ trong nồi và loại bỏ phần còn lại. Giảm lửa vừa rồi cho tỏi, hành tây và rau bina vào nấu cho đến khi hành tây trong và rau bina héo hoặc khoảng 5 phút.', NULL, '2026-05-15 14:52:47', '2026-05-15 14:52:47'),
(4029, 598, 3, 'Cho thịt cừu trở lại hầm với hỗn hợp hành tây-rau bina, thêm cà chua xay nhuyễn, thì là, harissa, thịt gà, đậu xanh, nước cốt chanh, muối và hạt tiêu vào chảo. Đun sôi trên lửa nhỏ trong khoảng 20 phút.', NULL, '2026-05-15 14:52:47', '2026-05-15 14:52:47'),
(4030, 598, 4, 'Thêm mì ống và nấu trong 15 phút hoặc cho đến khi mì ống chín.', NULL, '2026-05-15 14:52:47', '2026-05-15 14:52:47'),
(4032, 599, 1, 'Chiên khô hạt thông hoặc hạnh nhân trong chảo lớn cho đến khi nướng nhẹ, sau đó cho ra đĩa. Thêm dầu vào chảo, sau đó xào hành tây và quế với nhau cho đến khi bắt đầu chuyển sang màu vàng. Tăng lửa, cho thịt cừu vào xào cho đến khi thịt đổi màu thì cho cơm vào nấu trong 1 phút, khuấy đều.', NULL, '2026-05-15 14:52:49', '2026-05-16 12:35:35'),
(4034, 599, 2, 'Đổ 500ml nước sôi vào, vo viên, cho mơ vào, nêm gia vị cho vừa ăn. Giảm nhiệt, đậy nắp và đun nhỏ lửa trong 12 phút cho đến khi gạo mềm và nước luộc đã ngấm. Cho hạt thông và bạc hà vào rồi thưởng thức.', NULL, '2026-05-15 14:52:49', '2026-05-16 12:35:35'),
(4036, 600, 1, 'Làm nóng vỉ nướng ở mức cao. Nêm thịt cừu, sau đó nướng mỗi mặt trong 2 phút cho đến khi chín vàng nhưng vẫn rất tái. Trong khi đó, trộn gia vị, lá oregano và một nửa lá bạc hà vào một trong các hộp sữa chua, phết hỗn hợp này lên thịt cừu, sau đó quay lại nướng thêm 2-3 phút nữa hoặc cho đến khi sữa chua phồng rộp và thịt chín theo ý thích của bạn.', NULL, '2026-05-15 14:52:50', '2026-05-16 12:35:35'),
(4038, 600, 2, 'Để thịt nằm trên thớt trong vài phút trong khi nướng bánh pittas, cắt nhỏ rau diếp và cắt mỏng hành tím. Khuấy phần bạc hà còn lại vào bồn sữa chua thứ hai. Cắt lát dày thịt và nhồi vào bánh mì pitta cùng với salad và sữa chua bạc hà. Vắt thêm nước cốt chanh trước khi nhét vào, nếu bạn thích.', NULL, '2026-05-15 14:52:50', '2026-05-16 12:35:35'),
(4040, 601, 1, 'Làm nóng lò nướng ở nhiệt độ quạt/khí 160C/140C 3. Đun nóng 1 muỗng canh dầu trong nồi có đáy dày, nêm gia vị cho các chân gà, sau đó chiên vàng 2 mặt mỗi lần, thêm lượng dầu còn lại cho mẻ thứ hai. Lấy thịt cừu ra và thêm hành tây. Chiên chúng khá nhanh, khoảng 30 giây, thêm gừng, tỏi và ớt băm nhỏ, sau đó giảm lửa và nấu trong 1 phút. Thêm 1 thìa đường vào, khuấy đều rồi cho hoa hồi, sả, nước kho, xay nhuyễn và gia vị vào. Đun sôi.', NULL, '2026-05-15 14:52:52', '2026-05-16 12:35:35'),
(4042, 601, 2, 'Đậy nắp và cho vào lò nướng khoảng 1 tiếng rưỡi, sau đó cho khoai lang vào nấu thêm 1 giờ nữa. Thịt cừu phải mềm hoàn toàn và gần như rơi ra khỏi xương. Khuấy nước mắm, nước cốt chanh và 1 thìa đường để tăng hương vị, sau đó rắc bạc hà, húng quế và ớt thái lát vào để thưởng thức.', NULL, '2026-05-15 14:52:52', '2026-05-16 12:35:35'),
(4043, 602, 1, 'Đun chảy mỡ trong chảo chống dính, để mỡ nóng và đẹp, sau đó cho thịt xông khói vào. Khi nó bắt đầu chuyển sang màu nâu, thêm hành và tỏi. Tiếp theo, thêm mầm hoặc bắp cải thái lát vào và để hơi màu. Tất cả điều này sẽ mất 5-6 phút.', NULL, '2026-05-15 14:52:55', '2026-05-15 14:52:55'),
(4044, 602, 2, 'Tiếp theo, thêm khoai tây. Trộn mọi thứ lại với nhau trong chảo và ấn xuống để hỗn hợp phủ kín đáy chảo - để hỗn hợp bám nhẹ vào đáy chảo trước khi lật lại và làm lại như vậy. Chính những miếng khoai tây dính vào chảo sẽ xác định thuật ngữ \'bong bóng và tiếng kêu\', vì vậy hãy dũng cảm và để hỗn hợp có màu. Cắt thành nêm và phục vụ.', NULL, '2026-05-15 14:52:55', '2026-05-15 14:52:55'),
(4046, 603, 1, 'Làm nóng lò ở nhiệt độ 200C/180C/gas 6. Đun nóng một nửa dầu trong chảo sâu lòng hoặc chảo xào (hoặc đĩa hầm nông) có đường kính khoảng 30cm. Ở nhiệt độ cao, nhuộm các lát thịt ba chỉ ở mỗi bên thành nhiều mẻ, sau đó chuyển sang tô. Thêm lượng dầu còn lại vào chảo và giảm lửa ở mức vừa, sau đó cho bánh pudding đen và thịt xông khói vào chiên trong vài phút. Loại bỏ bằng một cái muỗng có rãnh. Chiên hành tây và ớt trong khoảng 10 phút cho đến khi mềm và có màu vàng nhạt, sau đó cho cà chua vào nấu cho đến khi mềm. Thêm tỏi, ớt bột hun khói và ớt bột vào nấu thêm 2 phút nữa, sau đó cho thịt lợn, bánh pudding đen và thịt xông khói vào chảo. Thêm đậu, nước luộc và bất kỳ loại thảo mộc nào bạn đang sử dụng vào rồi đun sôi mọi thứ.', NULL, '2026-05-15 14:52:58', '2026-05-16 12:35:35'),
(4048, 603, 2, 'Rắc cơm xung quanh bụng lợn, đẩy nó xuống bên dưới nước luộc. Đun sôi lại nước kho, nêm gia vị vừa đủ rồi chuyển vào lò nướng (không đậy nắp). Nấu trong 20 phút mà không khuấy, sau đó kiểm tra xem cơm chín như thế nào. Gạo phải mềm và nước ngấm. Nếu chưa chín, hãy cho bánh vào lò nướng thêm 5 phút nữa rồi kiểm tra lại. Nêm nếm gia vị.', NULL, '2026-05-15 14:52:58', '2026-05-16 12:35:35'),
(4050, 603, 3, 'Vắt nước cốt chanh lên trên và rưới lên một ít dầu ô liu nguyên chất ngay trước khi dùng, nếu bạn thích.', NULL, '2026-05-15 14:52:58', '2026-05-16 12:35:35'),
(4052, 604, 1, 'Làm nóng lò ở 200C/quạt 180C/gas. Trộn đường vào hỗn hợp bánh mì trong tô lớn, sau đó thêm nước theo hướng dẫn trên bao bì. Dùng thìa gỗ trộn bột lại, sau đó nhào trên bề mặt đã rắc chút bột mì trong 5 phút cho đến khi mịn. Cho vào tô lớn, phủ màng dính dầu rồi để ở nơi ấm áp cho đến khi nở gấp đôi.', NULL, '2026-05-15 14:52:59', '2026-05-16 12:35:35'),
(4054, 604, 2, 'Trong khi đó, làm nóng dầu trong chảo, sau đó chiên thịt xông khói cho đến khi giòn, khoảng 5 phút. Thêm gừng và tỏi vào xào trong 1 phút cho đến khi mềm, sau đó cho đậu nành, mật ong và cà chua xay nhuyễn vào khuấy đều. Có thể thực hiện trước 3 ngày.', NULL, '2026-05-15 14:52:59', '2026-05-16 12:35:35'),
(4056, 604, 3, 'Đổ bột ra và nhào nhẹ, sau đó vo thành 12 viên có kích thước đều nhau. Dùng tay ấn dẹt, sau đó cho một viên nhân có kích thước bằng thìa cà phê vào giữa. Kéo bột lên và kẹp lại như một cái ví, sau đó lật bánh lại và đặt lên khay nướng lớn. Dùng màng bọc dầu bọc lại và để bột nở khoảng 30 phút cho đến khi bột có cảm giác dẻo. Quét trứng lên và nướng trong 20 phút cho đến khi vàng. Ăn nóng với nước chấm. Có thể đông lạnh sau lần ủ thứ hai trong tối đa 1 tháng hoặc nướng trước một ngày và hâm nóng lại.', NULL, '2026-05-15 14:52:59', '2026-05-16 12:35:35'),
(4057, 605, 1, 'Làm nóng lò ở 450 độ. Rửa và lau khô tất cả sản phẩm. Cắt khoai lang thành miếng dày ½ inch. Đổ một ít dầu, muối và hạt tiêu lên khay nướng. Nướng cho đến khi chín vàng và mềm, khoảng 20-25 phút.', NULL, '2026-05-15 14:53:01', '2026-05-15 14:53:01'),
(4058, 605, 2, 'Trong khi đó, cắt đôi và gọt vỏ hành tây. Cắt càng mỏng càng tốt cho đến khi bạn còn ¼ cốc (½ cốc cho 4 phần ăn); thái nhỏ hành tây còn lại. Bóc vỏ và băm nhuyễn tỏi. Vôi giảm một nửa; vắt nước trái cây vào một cái bát nhỏ. Bánh mì cắt đôi. Thêm 1 muỗng canh bơ (2 muỗng canh cho 4 người) vào một bát nhỏ riêng biệt dùng được cho lò vi sóng; lò vi sóng cho đến khi tan chảy, 30 giây. Chải lên các mặt đã cắt của bánh.', NULL, '2026-05-15 14:53:01', '2026-05-15 14:53:01'),
(4059, 605, 3, 'Để tô với nước cốt chanh, thêm hành tây thái lát, ¼ thìa cà phê đường (½ thìa cho 4 phần ăn) và một chút muối. Khuấy để kết hợp; dành riêng để ngâm nhanh.', NULL, '2026-05-15 14:53:01', '2026-05-15 14:53:01'),
(4060, 605, 4, 'Đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm hành tây xắt nhỏ và nêm muối và hạt tiêu. Nấu, khuấy đều cho đến khi mềm, 4-5 phút. Thêm tỏi và nấu cho đến khi có mùi thơm, thêm 30 giây nữa. Thêm thịt lợn và nêm muối và hạt tiêu. Nấu, chia thịt thành từng miếng cho đến khi chín vàng, khoảng 4-6 phút.', NULL, '2026-05-15 14:53:01', '2026-05-15 14:53:01'),
(4061, 605, 5, 'Trong khi nấu thịt lợn, trong tô nhỏ thứ ba, trộn nước sốt BBQ, nước ngâm từ hành tây, 3 muỗng canh tương cà (6 muỗng canh cho 4 phần ăn), ½ muỗng cà phê đường (1 muỗng cà phê cho 4 người) và ¼ cốc nước (⅓ cốc cho 4 người). Sau khi thịt lợn chín, thêm hỗn hợp sốt BBQ vào chảo. Nấu, khuấy đều cho đến khi nước sốt đặc lại, 2-3 phút. Hương vị và nêm muối và hạt tiêu.', NULL, '2026-05-15 14:53:01', '2026-05-15 14:53:01'),
(4062, 605, 6, 'Trong khi đó, nướng bánh trong lò nướng hoặc lò nướng bánh mì cho đến khi vàng, khoảng 3-5 phút. Chia bánh mì nướng vào các đĩa và đổ đầy thịt lợn BBQ tùy thích. Đổ hành ngâm và nước sốt nóng lên trên. Ăn kèm với khoai lang nêm ở bên cạnh.', NULL, '2026-05-15 14:53:01', '2026-05-15 14:53:01'),
(4063, 606, 1, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C).', NULL, '2026-05-15 14:53:02', '2026-05-15 14:53:02'),
(4064, 606, 2, 'Đun nóng nồi lớn trên lửa vừa. Thêm thịt xông khói và kielbasa; nấu và khuấy cho đến khi thịt xông khói chuyển sang màu mỡ và xúc xích có màu nâu nhạt. Dùng thìa có rãnh để lấy thịt và chuyển sang nồi lớn hoặc lò nướng kiểu Hà Lan.', NULL, '2026-05-15 14:53:02', '2026-05-15 14:53:02'),
(4065, 606, 3, 'Phủ nhẹ các khối thịt lợn bằng bột mì và chiên chúng trong nước sốt thịt xông khói trên lửa vừa cao cho đến khi có màu vàng nâu. Dùng thìa có rãnh để chuyển thịt lợn vào nồi. Thêm tỏi, hành tây, cà rốt, nấm tươi, bắp cải và dưa cải bắp. Giảm nhiệt xuống mức trung bình; nấu và khuấy cho đến khi cà rốt mềm, khoảng 10 phút. Đừng để rau có màu nâu.', NULL, '2026-05-15 14:53:02', '2026-05-15 14:53:02'),
(4066, 606, 4, 'Khử men chảo bằng cách đổ rượu vang đỏ vào và khuấy đều để loại bỏ hết thức ăn và bột mì dính dưới đáy. Nêm lá nguyệt quế, húng quế, kinh giới, ớt bột, muối, tiêu, hạt caraway và ớt cayenne; nấu trong 1 phút.', NULL, '2026-05-15 14:53:02', '2026-05-15 14:53:02'),
(4067, 606, 5, 'Trộn nấm khô, sốt ớt cay, sốt Worcestershire, thịt bò kho, bột cà chua và cà chua. Đun nóng cho đến khi sôi. Đổ rau và tất cả chất lỏng vào đĩa thịt hầm cùng với thịt. Đậy nắp.', NULL, '2026-05-15 14:53:02', '2026-05-15 14:53:02'),
(4068, 606, 6, 'Nướng trong lò làm nóng trước từ 2 tiếng rưỡi đến 3 giờ, cho đến khi thịt rất mềm.', NULL, '2026-05-15 14:53:02', '2026-05-15 14:53:02'),
(4069, 607, 1, 'BƯỚC 1', NULL, '2026-05-15 14:53:04', '2026-05-15 14:53:04'),
(4070, 607, 2, 'Trước khi bắt đầu, hãy đặt lò nướng ở mức thấp nhất để sẵn sàng giữ ấm mọi thứ. Gọt vỏ khoai tây, xay 2 củ rồi đặt sang một bên. Cắt 2 cái còn lại thành từng miếng lớn, sau đó đun sôi trong 10-15 phút hoặc cho đến khi mềm. Trong khi đó, dùng khăn sạch vắt càng nhiều chất lỏng từ khoai tây nghiền càng tốt. Nghiền nhuyễn khoai tây luộc rồi trộn với khoai tây bào sợi, hành lá và bột mì.', NULL, '2026-05-15 14:53:04', '2026-05-15 14:53:04'),
(4071, 607, 3, 'BƯỚC 2', NULL, '2026-05-15 14:53:04', '2026-05-15 14:53:04'),
(4072, 607, 4, 'Đánh lòng trắng trứng trong một tô lớn cho đến khi có chóp mềm. Cho bơ sữa vào, sau đó thêm bicarbonate soda. Gấp vào hỗn hợp khoai tây.', NULL, '2026-05-15 14:53:04', '2026-05-15 14:53:04'),
(4073, 607, 5, 'BƯỚC 3', NULL, '2026-05-15 14:53:04', '2026-05-15 14:53:04'),
(4074, 607, 6, 'Đun nóng chảo chống dính lớn trên lửa vừa, sau đó thêm 1 muỗng canh bơ và một ít dầu. Thả 3-4 thìa hỗn hợp khoai tây vào chảo, sau đó nấu nhẹ mỗi mặt trong 3-5 phút cho đến khi vàng và giòn. Giữ ấm trên đĩa trong lò trong khi nấu mẻ tiếp theo, cho thêm bơ và dầu vào chảo trước khi làm. Bạn sẽ nhận được 16 chiếc hộp cỡ nhỏ từ hỗn hợp. Có thể làm vào ngày hôm trước, để ráo nước trên giấy ăn, sau đó hâm nóng trong lò ở nhiệt độ thấp trong 20 phút.', NULL, '2026-05-15 14:53:04', '2026-05-15 14:53:04'),
(4075, 607, 7, 'BƯỚC 4', NULL, '2026-05-15 14:53:04', '2026-05-15 14:53:04'),
(4076, 607, 8, 'Làm nóng lò nướng ở mức vừa và cho cà chua vào chảo có đáy dày. Thêm một ít bơ và một ít dầu vào, sau đó chiên khoảng 5 phút cho đến khi chín mềm. Nướng thịt xông khói rồi bày ra đĩa, dùng nóng. Xếp hộp, thịt xông khói và trứng lên rồi dọn kèm cà chua lên một bên.', NULL, '2026-05-15 14:53:04', '2026-05-15 14:53:04'),
(4077, 608, 1, 'Làm nóng lò ở nhiệt độ 200 độ C.', NULL, '2026-05-15 14:53:07', '2026-05-15 14:53:07'),
(4078, 608, 2, 'Cắt thịt xông khói hoặc chorizo ​​thành miếng vừa và ớt bột thành dải.', NULL, '2026-05-15 14:53:07', '2026-05-15 14:53:07'),
(4079, 608, 3, 'Rưới một ít nước sốt cà chua và phô mai mozzarella lên từng phần sắn.', NULL, '2026-05-15 14:53:07', '2026-05-15 14:53:07'),
(4080, 608, 4, 'Thêm thịt xông khói hoặc chorizo, ngô, giăm bông gà tây, một ít ô liu và ớt bột.', NULL, '2026-05-15 14:53:07', '2026-05-15 14:53:07'),
(4081, 608, 5, 'Nướng trong 7 đến 10 phút.', NULL, '2026-05-15 14:53:07', '2026-05-15 14:53:07'),
(4082, 608, 6, 'Lấy ra khỏi lò và thưởng thức.', NULL, '2026-05-15 14:53:07', '2026-05-15 14:53:07'),
(4084, 609, 1, 'Đun nóng dầu trong chảo lớn, sau đó nhẹ nhàng xào hành tây trong 3-4 phút cho đến khi hành mềm. Khuấy cà rốt, cần tây, húng tây và lá nguyệt quế. Nêm gia vị, sau đó nấu trong 2-3 phút, thỉnh thoảng khuấy. Thêm tỏi, chorizo, quế và ớt bột hun khói. Nhẹ nhàng chiên cho đến khi rau mềm và chorizo ​​bắt đầu tiết ra dầu và giòn.', NULL, '2026-05-15 14:53:09', '2026-05-16 12:35:35'),
(4086, 609, 2, 'Khuấy đậu xanh, giấm và 150ml nước, sau đó đun nhỏ lửa trong 1-2 phút cho đến khi đậu xanh nóng lên. Thêm rau chân vịt vào, sau đó đảo đều đậu xanh cho đến khi đậu hơi héo. Tắt bếp, nêm nếm vừa ăn rồi dùng nóng với bánh mì giòn.', NULL, '2026-05-15 14:53:09', '2026-05-16 12:35:35'),
(4088, 610, 1, 'Đặt một chiếc chảo vừa lên lửa và cho cà chua vào, tiếp theo là một lon nước. Trong khi cà chua đang nóng, nhanh chóng cắt chorizo ​​thành từng miếng nhỏ (bỏ hết vỏ) và cắt nhỏ bắp cải.', NULL, '2026-05-15 14:53:11', '2026-05-16 12:35:35'),
(4090, 610, 2, 'Cho xúc xích và bắp cải vào chảo cùng với ớt và đậu xanh, sau đó nghiền thành khối nước dùng. Khuấy đều, đậy nắp và để sôi ở lửa lớn trong 6 phút hoặc cho đến khi bắp cải mềm. Múc ra bát ăn với bánh mì giòn hoặc bánh mì tỏi.', NULL, '2026-05-15 14:53:11', '2026-05-16 12:35:35'),
(4092, 611, 1, 'Nấu khoai tây trong chảo lớn có nước muối sôi trong 12 phút, thêm trứng sau 6 phút và đậu vào trong 2 phút cuối cùng. Xả hết mọi thứ và làm nguội trứng dưới vòi nước lạnh.', NULL, '2026-05-15 14:53:14', '2026-05-16 12:35:35'),
(4094, 611, 2, 'Trong khi đó, chiên các lát chorizo ​​trong 1-2 phút cho đến khi bắt đầu giòn. Dùng thìa có rãnh lấy ra khỏi chảo và đặt sang một bên, để lại dầu từ chorizo ​​trong chảo. Thêm tỏi vào chảo và nấu nhẹ trong 1 phút.', NULL, '2026-05-15 14:53:14', '2026-05-16 12:35:35'),
(4096, 611, 3, 'Nhấc chảo ra khỏi bếp, cho giấm và mùi tây vào khuấy đều, sau đó trộn khoai tây, đậu, chorizo và gia vị. Trứng bóc vỏ, cắt làm tư và thêm vào món salad.', NULL, '2026-05-15 14:53:14', '2026-05-16 12:35:35'),
(4098, 612, 1, 'Cho cà chua vào tô cùng với hành tây và húng tây. Nêm, sau đó rưới giấm và dầu lên. Hãy để hương vị hòa quyện trong khi bạn nấu chorizo.', NULL, '2026-05-15 14:53:18', '2026-05-16 12:35:35'),
(4100, 612, 2, 'Trong chảo khô, nóng, chiên các lát chorizo cho đến khi chín vàng cả hai mặt. Phục vụ cà chua với chorizo ​​​​chiên, rưới một ít dầu từ chảo.', NULL, '2026-05-15 14:53:18', '2026-05-16 12:35:35'),
(4102, 613, 1, 'Luộc khoai tây trong nước sôi khoảng 8-10 phút hoặc cho đến khi mềm. Xả và để khô bằng hơi nước. Đun nóng dầu trong chảo trứng tráng, thêm chorizo ​​và nấu trong 2 phút. Thêm khoai tây và nấu thêm 5 phút nữa cho đến khi khoai tây bắt đầu giòn. Múc hết nội dung trong chảo ra, lau chảo và nấu món trứng tráng 2 hoặc 3 quả trong cùng một chảo. Khi gần chín, rải đều với chorizo ​​và khoai tây, rau mùi tây và phô mai. Gấp món trứng tráng vào chảo và nấu thêm 1 phút nữa để làm tan chảy phô mai.', NULL, '2026-05-15 14:53:20', '2026-05-16 12:35:35'),
(4103, 614, 1, 'BƯỚC 1', NULL, '2026-05-15 14:53:22', '2026-05-15 14:53:22'),
(4104, 614, 2, 'Đun nóng bơ trong chảo cho đến khi nóng hổi, sau đó chiên thịt lợn trong 2-3 phút mỗi mặt cho đến khi chín vàng. Lấy ra khỏi chảo.', NULL, '2026-05-15 14:53:22', '2026-05-15 14:53:22'),
(4105, 614, 3, 'BƯỚC 2', NULL, '2026-05-15 14:53:22', '2026-05-15 14:53:22'),
(4106, 614, 4, 'Cho thịt xông khói, cà rốt, khoai tây và thịt Thụy Điển vào chảo, sau đó chiên nhẹ cho đến khi có màu hơi nhạt. Khuấy bắp cải, đặt miếng sườn lên trên, thêm lá nguyệt quế, sau đó rưới rượu táo lên và kho. Đậy nắp chảo, sau đó để mọi thứ sôi nhẹ trong 20 phút cho đến khi thịt lợn chín và rau mềm.', NULL, '2026-05-15 14:53:22', '2026-05-15 14:53:22'),
(4107, 614, 5, 'BƯỚC 3', NULL, '2026-05-15 14:53:22', '2026-05-15 14:53:22'),
(4108, 614, 6, 'Phục vụ tại bàn được múc thẳng từ đĩa.', NULL, '2026-05-15 14:53:22', '2026-05-15 14:53:22'),
(4109, 615, 1, 'Làm nóng lò ở nhiệt độ 350°. Loại bỏ phần cuống của một bó cải xoăn Tuscan và xé lá thành từng miếng 1 inch (mù tạt xanh, cải rổ, rau bina và củ cải cũng rất tuyệt). Cắt thô nửa đầu bắp cải xanh. Cho các loại rau xanh vào một đĩa nướng lớn và thêm 4 tép tỏi thái lát mỏng. Thêm một ít hành tây thái lát và nấm đông cô vào thời điểm này là tùy chọn, nhưng rất khuyến khích (Tôi sẽ xào hành và nấm trong đĩa nướng gang ngay trên bếp trước khi thêm vào phủ rau xanh với một ít dầu ô liu và đổ ½ cốc nước luộc gà hoặc nước dùng lên trên mọi thứ. Dùng giấy bạc đậy đĩa lại và nướng cho đến khi rau héo, khoảng 15 phút. Lấy giấy bạc ra và nêm muối và hạt tiêu.', NULL, '2026-05-15 14:53:24', '2026-05-15 14:53:24'),
(4110, 615, 2, 'Trong khi đó, đun nóng một ít dầu ô liu trong chảo lớn trên lửa vừa cao. Dùng nĩa đâm bốn chiếc xúc xích Ý ngọt và nấu cho đến khi chín vàng các mặt và chín đều trong vòng 10 đến 12 phút. Khi rau đã chín, hãy cắt xúc xích và trộn vào rau với một chút giấm yêu thích của bạn (tôi thích rượu sherry hoặc rượu vang đỏ).', NULL, '2026-05-15 14:53:24', '2026-05-15 14:53:24'),
(4112, 616, 1, 'Để làm nhân, đun nóng dầu ô liu trong chảo cho đến khi dầu bắt đầu sủi bọt. Thêm tỏi tây và xào cho đến khi mềm nhưng không có màu. Dùng thìa gỗ khuấy thịt giăm bông, chiên trong 1 phút, sau đó cho bột mì vào và chiên trên lửa vừa, thỉnh thoảng khuấy cho đến khi hỗn hợp vàng nhưng không bị cháy - quá trình này sẽ mất khoảng 5 phút.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4114, 616, 2, 'Trong khi đó, cho nước kho và sữa vào chảo nhỏ và đun nóng cho đến khi hấp nhưng không sôi. Nêm với một ít hạt nhục đậu khấu. Dần dần thêm chất lỏng, mỗi lần một vài muỗng canh, khuấy liên tục.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4116, 616, 3, 'Sau khi bạn đã trộn hết nước kho sữa, hãy tiếp tục nấu phần nhân ở lửa vừa trong khoảng 10 phút hoặc cho đến khi nhân đặc lại và rời khỏi thành chảo khi bạn khuấy.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4118, 616, 4, 'Nêm hạt tiêu đen, nếm và điều chỉnh muối nếu cần - lúc đầu giăm bông có thể rất mặn. Phần nhân bây giờ đã xong: nó phải thật dày vì bạn không muốn bánh croquetas biến thành bánh kếp.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4120, 616, 5, 'Dàn đều hỗn hợp lên khay nướng (30 x 20cm là được). Khi bánh đã ngừng hấp, hãy dùng màng bọc thực phẩm bọc lại để bánh không bị khô. Để nguội trước khi cho vào tủ lạnh khoảng 1h.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4122, 616, 6, 'Khi bạn đã sẵn sàng cho giai đoạn tiếp theo, hãy xếp ba cái bát: cái thứ nhất chứa đầy bột mì, cái thứ hai chứa trứng đánh và cái thứ ba chứa vụn bánh mì. Lấy hỗn hợp giăm bông ra khỏi tủ lạnh. Thoa một ít dầu ô liu lên tay để cuộn bánh croquetas dễ dàng hơn.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4124, 616, 7, 'Lăn một thìa hỗn hợp giữa lòng bàn tay của bạn. Kích thước và hình dạng của croquetas tùy thuộc vào bạn, nhưng dễ nhất là một quả bóng có kích thước bằng quả óc chó. Sau đó bắt đầu phủ như sau.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4126, 616, 8, 'Nhúng bánh croquetas vào bột mì - bạn muốn có một lớp bột - tiếp theo là trứng, sau đó là vụn bánh mì. Đặt chúng lên khay và khi bạn đã sử dụng hết hỗn hợp, hãy đặt chúng vào tủ lạnh trong 30 phút.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4128, 616, 9, 'Nếu bạn có nồi chiên ngập dầu, hãy đun nóng dầu đến 180C và chiên trong vài phút. Nếu không, hãy đun nóng dầu trong chảo sâu lòng, có đáy nặng cho đến khi dầu bắt đầu sủi bọt. Sau đó thêm 5-6 croquetas cùng một lúc và chiên cho đến khi vàng đều. Sau khi chín, để ráo trên giấy ăn và ăn ngay.', NULL, '2026-05-15 14:53:26', '2026-05-16 12:35:35'),
(4129, 617, 1, 'BƯỚC 1', NULL, '2026-05-15 14:53:29', '2026-05-15 14:53:29'),
(4130, 617, 2, 'Gọt vỏ và cắt khoai tây thành những khối đều nhau, cỡ vừa. Cho vào một cái chảo lớn chứa đầy nước muối lạnh, đun sôi và nấu trong vòng 10 - 15 phút cho đến khi có thể đâm dao vào khoai tây dễ dàng.', NULL, '2026-05-15 14:53:29', '2026-05-15 14:53:29'),
(4131, 617, 3, 'BƯỚC 2', NULL, '2026-05-15 14:53:29', '2026-05-15 14:53:29'),
(4132, 617, 4, 'Trong khi đó, làm tan bơ trong chảo xào lớn trên lửa vừa. Thêm tỏi, bắp cải, hành lá và một ít gia vị. Thỉnh thoảng đảo đều cho đến khi bắp cải héo nhưng vẫn còn dính một ít thì để sang một bên.', NULL, '2026-05-15 14:53:29', '2026-05-15 14:53:29'),
(4133, 617, 5, 'BƯỚC 3', NULL, '2026-05-15 14:53:29', '2026-05-15 14:53:29'),
(4134, 617, 6, 'Để ráo khoai tây, để khô trong vài phút, sau đó nghiền với kem, mù tạt và gia vị trong cùng một chảo. Khuấy bắp cải và giăm bông. Giữ ấm ở nhiệt độ thấp.', NULL, '2026-05-15 14:53:29', '2026-05-15 14:53:29'),
(4135, 617, 7, 'BƯỚC 4', NULL, '2026-05-15 14:53:29', '2026-05-15 14:53:29'),
(4136, 617, 8, 'Làm nóng lại chảo bạn dùng để nấu bắp cải (không cần rửa trước), thêm một chút dầu, đập trứng vào và chiên theo ý thích của bạn. Để phục vụ, hãy chia colcannon vào các bát và phủ một quả trứng chiên lên trên mỗi bát.', NULL, '2026-05-15 14:53:29', '2026-05-15 14:53:29'),
(4137, 618, 1, 'BƯỚC 1 - LÀM Súp', NULL, '2026-05-15 14:53:31', '2026-05-15 14:53:31'),
(4138, 618, 2, 'Cho nước luộc gà vào chảo và đợi sôi.', NULL, '2026-05-15 14:53:31', '2026-05-15 14:53:31'),
(4139, 618, 3, 'Tiếp theo thêm muối, đường, dầu hạt mè, tiêu trắng, sốt ớt cay, giấm và nước tương vào rồi khuấy đều trong vài giây.', NULL, '2026-05-15 14:53:31', '2026-05-15 14:53:31'),
(4140, 618, 4, 'Cho Đậu phụ, nấm hương, mộc nhĩ đen vào chảo.', NULL, '2026-05-15 14:53:31', '2026-05-15 14:53:31'),
(4141, 618, 5, 'Để làm đặc nước sốt, trộn 1 thìa bột ngô và 2 thìa nước vào tô rồi từ từ thêm vào súp cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:53:31', '2026-05-15 14:53:31'),
(4142, 618, 6, 'Tiếp theo, thêm 1 quả trứng đánh nhẹ bằng dao hoặc nĩa rồi thêm vào súp và khuấy trong 8 giây', NULL, '2026-05-15 14:53:31', '2026-05-15 14:53:31'),
(4143, 618, 7, 'Múc súp ra bát rồi thêm thịt lợn bbq và hành lá thái lát lên trên.', NULL, '2026-05-15 14:53:31', '2026-05-15 14:53:31'),
(4145, 619, 1, 'Rửa sạch lá tỏi dại trong một cái chao, sau đó đổ nước sôi từ ấm vào cho đến khi héo. Rửa sạch ngay dưới vòi nước lạnh, sau đó vắt bớt nước và thái nhỏ.', NULL, '2026-05-15 14:53:34', '2026-05-16 12:35:35'),
(4147, 619, 2, 'Đun nóng sữa trong chảo ở lửa nhỏ cho đến khi sôi. Đun nóng dầu hoặc bơ trong chảo thứ hai và sau khi ấm hoặc tan chảy, cho bột vào khuấy trong vài phút cho đến khi bột bắt đầu chuyển sang màu nâu một chút. Dần dần thêm sữa ấm, từng chút một, cho đến khi bạn có được nước sốt đặc và mượt. Tạo bọt trong một hoặc hai phút, khuấy đều để đảm bảo bột đã chín hết. Mùa.', NULL, '2026-05-15 14:53:34', '2026-05-16 12:35:35'),
(4149, 619, 3, 'Thêm manchego, jamón và tỏi rừng vào chảo rồi đánh đều. Đổ ra khay hoặc đĩa nướng đã phết một ít dầu, dàn đều rồi đậy nắp và để nguội ít nhất 1 giờ. Sẽ giữ lạnh lên đến 24 giờ.', NULL, '2026-05-15 14:53:34', '2026-05-16 12:35:35'),
(4151, 619, 4, 'Thoa nhẹ dầu lên tay và nặn hỗn hợp thành 18-20 quả bóng có kích thước đều nhau. Xếp lên khay nướng và để đông trong 30 phút cho cứng lại.', NULL, '2026-05-15 14:53:34', '2026-05-16 12:35:35'),
(4153, 619, 5, 'Đánh trứng vào đĩa nông với một ít gia vị. Đổ panko vào món thứ hai. Nhúng từng chiếc croquetas vào trứng, sau đó lăn qua bột chiên xù. Tại thời điểm này, croquetas thô có thể được đông lạnh đến ba tháng. Đổ dầu vào chảo lớn, sâu lòng, đảm bảo ngập không quá 1/3 dầu và đun nóng đến 170C hoặc cho đến khi một khối bánh mì chín vàng nhẹ trong 30 giây. Chiên croquetas theo mẻ trong 2-3 phút cho đến khi vàng đậm. Để nấu từ món đông lạnh, hãy chiên ở nhiệt độ 160C thêm vài phút nữa cho đến khi chúng nóng bên trong. Dùng thìa có rãnh vớt ra một tờ giấy ăn và để ráo nước. Ăn ấm với một ly rượu sherry.', NULL, '2026-05-15 14:53:34', '2026-05-16 12:35:35'),
(4154, 620, 1, 'BƯỚC 1', NULL, '2026-05-15 14:53:36', '2026-05-15 14:53:36'),
(4155, 620, 2, 'Đun nóng dầu trong chảo, xào hành tây thái lát cho đến khi vàng nâu, sau đó thêm tonkatsu (xem công thức ở đây), đặt vào giữa chảo. Trộn dashi, đậu nành, mirin và đường với nhau rồi đổ 3/4 hỗn hợp xung quanh tonkatsu. Đun sôi trong vài phút để nước sốt đặc lại một chút và tonkatsu sẽ nóng lại.', NULL, '2026-05-15 14:53:36', '2026-05-15 14:53:36'),
(4156, 620, 3, 'BƯỚC 2', NULL, '2026-05-15 14:53:36', '2026-05-15 14:53:36'),
(4157, 620, 4, 'Đổ trứng đã đánh xung quanh tonkatsu và nấu trong 2-3 phút cho đến khi trứng chín nhưng vẫn còn hơi chảy nước. Chia cơm vào hai bát, sau đó phủ một nửa quả trứng và hỗn hợp tonkatsu lên trên, rắc hẹ lên và dùng ngay, rưới thêm một chút đậu nành nếu bạn muốn thêm vị umami.', NULL, '2026-05-15 14:53:36', '2026-05-15 14:53:36'),
(4165, 622, 1, 'Làm nóng lò ở mức quạt/khí 140C/120C 1. Đặt một chiếc chảo chịu nhiệt lớn (có nắp đậy kín) lên lửa cao. Cho mỡ và thịt thái hạt lựu vào, nấu trong vài phút cho kín các mép, đảo nhanh để chín đều. Giảm nhiệt xuống thấp, thêm hành tây thái lát, cả tép tỏi, cà rốt và hạt thì là vào nấu nhẹ để rau mềm trong vài phút.', NULL, '2026-05-15 14:53:39', '2026-05-15 14:53:39'),
(4166, 622, 2, 'Đổ giấm rượu vang đỏ lên trên, cạo hết phần thịt còn sót lại dưới đáy chảo. Thêm nước luộc, cà chua xay nhuyễn, một nửa lá hương thảo và rau mùi tây. Đun sôi và đun nhỏ lửa trong 10 phút, sau đó nêm gia vị, đậy nắp và cho vào lò nướng trong 2 giờ, tháo nắp trong giờ nấu cuối cùng. Thỉnh thoảng khuấy đều và thêm đậu vào sau 30 phút.', NULL, '2026-05-15 14:53:39', '2026-05-15 14:53:39'),
(4167, 622, 3, 'Lấy chảo ra khỏi lò và làm nóng vỉ nướng. Rắc các loại thảo mộc và vụn bánh mì còn lại lên trên, rưới một ít dầu lên trên rồi cho vào lò nướng trong 5-10 phút cho đến khi vụn bánh mì vàng. Ăn kèm bánh mì giòn và rau xanh.', NULL, '2026-05-15 14:53:39', '2026-05-15 14:53:39'),
(4169, 623, 1, 'Cắt thịt thành từng miếng lớn, cho vào nồi lớn nhất và đổ 5 lít nước vào. Đun sôi ở nhiệt độ cao, hớt hết bọt nổi lên bề mặt. Thêm lá nguyệt quế. Mùa. Giảm nhiệt xuống đun nhỏ lửa và nấu trong 1 giờ hoặc cho đến khi thịt mềm và rơi ra khỏi xương. Thêm đậu nếu sử dụng khô.', NULL, '2026-05-15 14:53:41', '2026-05-16 12:35:35'),
(4171, 623, 2, 'Tăng nhiệt lên. Đun sôi trở lại, sau đó giảm nhiệt và đun thêm 20 phút nữa – đậu vẫn còn hơi thô. Thêm cà rốt, hành tây, tỏi và hạt tiêu. Khuấy đều, sau đó thêm ớt nếu dùng. Nấu thêm 15 phút nữa.', NULL, '2026-05-15 14:53:41', '2026-05-16 12:35:35'),
(4173, 623, 3, 'Khuấy củ cải đường và nấu trong 10 phút trước khi thêm khoai tây. Sau 15 phút, thêm cà chua xay nhuyễn cho vừa ăn và đậu, nếu dùng đóng hộp, rồi đun sôi. Nấu trong 5 phút, thêm bắp cải và nấu thêm 5 phút nữa. Nêm gia vị, sau đó trang trí với rau mùi tây và thì là. Tắt lửa và để yên trong 5 phút. Ăn kèm với kem chua ở bên cạnh.', NULL, '2026-05-15 14:53:41', '2026-05-16 12:35:35'),
(4174, 624, 1, 'BƯỚC 1', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4175, 624, 2, 'Cắt thăn thành 5 miếng có kích thước bằng nhau, để phần đuôi dài hơn một chút. Lấy một túi nhựa trong và nhét một trong các mảnh vào. Dùng cán lăn đập nó vào một cái thang có kích thước bằng tấm bên và lặp lại với các mảnh còn lại.', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4176, 624, 3, 'BƯỚC 2', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4177, 624, 4, 'Cho rượu vang, ớt bột, một ít muối, tiêu và nước cốt của ½ quả chanh vào tô rồi thêm thịt lợn vào. Để ướp trong 20-30 phút, trong khi bạn nướng thịt nướng đến giai đoạn than đỏ rực nhưng không có ngọn lửa.', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4178, 624, 5, 'BƯỚC 3', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4179, 624, 6, 'Để làm khoai tây chiên, hãy đổ đầy nước mát vào chậu và cắt khoai tây thành những miếng khoai tây chiên dày 3 cm. Ngâm chúng trong nước khoảng 5 phút rồi thay nước. Để thêm 5 phút nữa. Để ráo nước rồi lau khô trên khăn hoặc giấy ăn.', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4180, 624, 7, 'BƯỚC 4', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4181, 624, 8, 'Đun nóng dầu trong nồi chiên ngập dầu hoặc chảo sâu lòng có nắp đậy ở nhiệt độ 130C rồi thả khoai tây chiên vào dầu (theo mẻ). Chần trong 8-10 phút. Lấy ra khỏi dầu và để ráo nước. Đặt lên khay để nguội. Đun nóng dầu đến 180C (đảm bảo dầu nóng, nếu không khoai tây chiên của bạn sẽ bị sũng nước) và thả giỏ khoai tây chiên vào dầu (một lần nữa, hãy làm theo từng mẻ). Để nấu trong 2 phút rồi lắc nhẹ. Nấu thêm khoảng một phút nữa cho đến khi chúng có màu sắc đẹp và giòn khi chạm vào. Để ráo nước trong vài phút, đổ vào tô và rắc muối biển.', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4182, 624, 9, 'BƯỚC 5', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4183, 624, 10, 'Thịt lợn sẽ chín nhanh nên làm thành 2 mẻ. Lấy các miếng ra khỏi nước xốt, thoa dầu rồi thả chúng vào vỉ nướng (bạn cũng có thể sử dụng vỉ nướng). Nấu mỗi mặt trong 1 phút - chúng có thể bùng lên khi bạn làm như vậy. Khoảng thời gian này thực sự là đủ vì họ sẽ tiếp tục nấu ăn. Lấy chúng ra khỏi vỉ nướng và xếp lên đĩa. Lặp lại với lô còn lại.', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4184, 624, 11, 'BƯỚC 6', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4185, 624, 12, 'Phục vụ bằng cách xếp khoai tây chiên lên đĩa, thả thịt lợn lên trên mỗi chồng và đổ nước ép từ đĩa lên trên để khoai tây chiên thấm hết hương vị. Phủ một thìa sốt mayonnaise và một lát chanh lên trên.', NULL, '2026-05-15 14:53:42', '2026-05-15 14:53:42'),
(4186, 625, 1, 'Raspeballer & Thịt Muối (Tùy Chọn)', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4187, 625, 2, 'Nếu bạn làm món thịt lợn, hãy luộc trong nước sôi khoảng 3 giờ cho đến khi thịt rời khỏi xương. Lấy thịt lợn ra và để dành nước dùng để nấu món raspeballer.', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4188, 625, 3, 'Luộc khoai tây luộc và gọt vỏ sau khi nguội. Ngoài ra, hãy gọt vỏ khoai tây sống, sau đó xay hoặc cho vào máy xay thực phẩm. Dùng khăn giấy để loại bỏ bớt hơi ẩm trên khoai tây nghiền.', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4189, 625, 4, 'Nghiền khoai tây luộc trong máy nghiền khoai tây hoặc bằng máy nghiền. Hãy chắc chắn rằng không có cục u. Cho khoai tây sống đã bào vào một tô trộn lớn và trộn đều với khoai tây nghiền. Thêm bột lúa mạch, bột mì đa dụng và muối vào rồi trộn đều bằng tay cho đến khi hỗn hợp hòa quyện hoàn toàn.', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4190, 625, 5, 'Bạn có thể nấu bánh raspeballer trong nước luộc rau hoặc thịt bò, hoặc nếu bạn đang làm món thịt lợn, hãy nấu chúng trong nước dùng từ thịt lợn. Đun sôi nước dùng thật nhẹ - bạn không muốn nước luộc sôi hoàn toàn vì khi đó bánh raspeballer có thể bị vỡ.', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4191, 625, 6, 'Dùng một thìa canh nhúng vào nước lạnh để tạo hình từng quả raspeball trong tay. Cố gắng làm sao cho chúng mịn nhất có thể rồi nhẹ nhàng thả vào nồi nước dùng đang sôi. Nhúng thìa vào bát nước lạnh giữa mỗi quả raspeball.', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4192, 625, 7, 'Để raspeballer sôi trong khoảng 30 phút. Nếu bạn làm xúc xích hun khói, bạn có thể hâm nóng xúc xích trong cùng một nồi với dụng cụ nướng xúc xích. Rắc mùi tây tươi xắt nhỏ lên trên.', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4193, 625, 8, 'Rutabaga nghiền', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4194, 625, 9, 'Gọt vỏ rutabaga và cà rốt rồi cắt thành từng miếng nhỏ. Đun sôi trong nước khoảng 30 phút hoặc cho đến khi mềm. Sau đó để ráo nước, thêm kem/sữa, bơ và hạt nhục đậu khấu vào rồi xay cho đến khi mịn.', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4195, 625, 10, 'Phục vụ cùng với raspeballer và thịt.', NULL, '2026-05-15 14:53:44', '2026-05-15 14:53:44'),
(4197, 626, 1, 'Cho bắp cải vào máy xay thực phẩm và xay cho đến khi thái nhỏ. Nêm ½ thìa muối, đảo đều và để yên trong 15 phút. Đổ vào một chiếc khăn trà sạch và vắt càng nhiều nước càng tốt. Cho cà rốt, nấm, thịt lợn băm, tỏi, gừng, nước tương, dầu mè và hành lá vào tô. Nêm hạt tiêu đen. Dùng tay trộn đều mọi thứ lại với nhau, trộn đều cho đến khi mọi thứ hòa quyện.', NULL, '2026-05-15 14:53:46', '2026-05-16 12:35:35'),
(4199, 626, 2, 'Ngâm các miếng chả giò trong vài giây trong một đĩa nước ấm, sau đó chuyển sang thớt đã phết dầu. Làm từng tờ một, múc 1 muỗng canh nhân vào giữa, sau đó gấp phần dưới lên và phủ lên trên. Gấp phần trên của tờ giấy xuống, sau đó gấp các cạnh lại và tạo thành một hình vuông gọn gàng. Nếu bánh bao có cảm giác hơi giòn, hãy ngâm một tờ giấy khác và bọc lại. Lặp lại với các tờ giấy và phần nhân còn lại, chuyển bánh bao vào đĩa đã phết dầu trong khi thực hiện.', NULL, '2026-05-15 14:53:46', '2026-05-16 12:35:35'),
(4201, 626, 3, 'Đun nóng dầu trong chảo chống dính lớn (đảm bảo không đầy quá một phần ba) trên lửa vừa cao và chiên bánh bao trong 3-5 phút cho đến khi có màu vàng nâu. Dùng thìa có rãnh hoặc con nhện để lật chúng, sau đó đậy nắp lại và nấu thêm 3-4 phút nữa cho đến khi chín vàng. Mở nắp và nấu trong 1-2 phút.', NULL, '2026-05-15 14:53:46', '2026-05-16 12:35:35'),
(4203, 626, 4, 'Trong khi đó, trộn tất cả nguyên liệu làm nước chấm vào tô nhỏ. Dọn bánh bao với nước chấm ở bên cạnh.', NULL, '2026-05-15 14:53:46', '2026-05-16 12:35:35'),
(4205, 627, 1, 'Cắt đôi bắp cải, loại bỏ phần cuống cứng và thái lát mỏng. Cho vào chảo lớn cùng tất cả các nguyên liệu khác trừ xúc xích, sau đó trộn với 300ml nước và một ít muối, tiêu.', NULL, '2026-05-15 14:53:47', '2026-05-16 12:35:35'),
(4207, 627, 2, 'Đun sôi, sau đó giảm nhiệt, đậy nắp vừa vặn và nấu nhẹ trong 1 tiếng rưỡi, khuấy thường xuyên. Nếu khô quá có thể cho thêm chút nước.', NULL, '2026-05-15 14:53:47', '2026-05-16 12:35:35'),
(4209, 627, 3, 'Thêm kabanos vào hỗn hợp bắp cải, đậy nắp chảo và đun nhỏ lửa trong 20 phút. Mở nắp và nấu thêm 10 phút nữa. Ăn kèm với khoai tây nghiền hoặc luộc đơn giản.', NULL, '2026-05-15 14:53:47', '2026-05-16 12:35:35'),
(4210, 628, 1, 'Phục vụ 2', NULL, '2026-05-15 14:53:48', '2026-05-15 14:53:48'),
(4211, 628, 2, 'Điều chỉnh giá đỡ ở vị trí trên cùng và giữa và làm nóng lò trước ở nhiệt độ 450 độ. Rửa và lau khô tất cả sản phẩm. Cắt khoai lang thành từng miếng 1/2 inch. Đổ một ít dầu, muối và hạt tiêu lên khay nướng. Nướng trên giá trên cùng trong 12 phút (sau đó chúng ta sẽ nướng bí xanh).', NULL, '2026-05-15 14:53:48', '2026-05-15 14:53:48'),
(4212, 628, 3, 'Trong khi đó, nửa quả táo và lõi; thái mỏng thành hình bán nguyệt. Bóc vỏ và băm nhuyễn tỏi. Quả chanh quý. Cắt và cắt đôi bí xanh theo chiều dọc; cắt ngang thành hình bán nguyệt dày 1/2 inch. Đổ một ít dầu và một chút muối và hạt tiêu lên khay nướng thứ hai. Đặt sang một bên.', NULL, '2026-05-15 14:53:48', '2026-05-15 14:53:48'),
(4213, 628, 4, 'Lau khô thịt lợn bằng khăn giấy và rắc muối và hạt tiêu lên trên. Đun nóng một ít dầu trong chảo lớn trên lửa vừa cao. Thêm thịt lợn vào và nấu cho đến khi chín vàng, khoảng 4-5 phút mỗi mặt. Tắt nhiệt; chuyển sang đĩa.', NULL, '2026-05-15 14:53:48', '2026-05-15 14:53:48'),
(4214, 628, 5, 'Sau khi nướng khoai lang được 12 phút, chuyển khay nướng có bí xanh sang giá giữa và tiếp tục nướng cho đến khi cả hai loại rau đều chín vàng và mềm, thêm 12-15 phút nữa.', NULL, '2026-05-15 14:53:48', '2026-05-15 14:53:48');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(4215, 628, 6, 'Trong khi đó, làm tan chảy 1 muỗng canh bơ (2 muỗng canh cho 4 phần ăn) trong chảo dùng cho thịt lợn ở lửa vừa cao. Thêm táo và nêm muối và hạt tiêu. Nấu, cạo hết những phần có màu nâu dưới đáy chảo cho đến khi táo hơi mềm, khoảng 2-3 phút. Thêm tỏi; nấu cho đến khi có mùi thơm, 30 giây. Thêm 1/z cốc nước (3/4 cốc cho 4 người), nước cô đặc và 11/2 thìa cà phê đường (3 thìa cà phê cho 4 người). Nấu, khuấy đều cho đến khi nước sốt đặc lại và táo rất mềm, khoảng 3-5 phút. Nêm muối và hạt tiêu.', NULL, '2026-05-15 14:53:48', '2026-05-15 14:53:48'),
(4216, 628, 7, 'Lấy chảo có táo ra khỏi bếp; khuấy 1 muỗng canh bơ (2 muỗng canh cho 4 phần ăn) và vắt nước cốt chanh. Chia thịt lợn, bí xanh và khoai lang vào các đĩa. Thịt lợn phủ sốt táo. Top zucchini với một vắt nước chanh.', NULL, '2026-05-15 14:53:48', '2026-05-15 14:53:48'),
(4218, 629, 1, 'Làm nóng lò nướng ở nhiệt độ quạt/khí 200C/180C 6. Dùng chày và cối giã tỏi, lá xô thơm, vỏ chanh, muối và tiêu với nhau cho đến khi hỗn hợp trở thành hỗn hợp sệt. Khuấy dầu, sau đó phết hỗn hợp lên vai lợn, tránh phần da bên trên. Dùng dao sắc rạch da, sau đó chà một nhúm muối lớn vào da. Buộc thịt lợn lại với nhau bằng dây bếp.', NULL, '2026-05-15 14:53:50', '2026-05-16 12:35:35'),
(4220, 629, 2, 'Lót một khay nướng lớn với một lớp giấy bạc hai lớp và đặt thịt lợn lên trên, mặt da hướng lên trên. Dùng giấy bạc bọc các cạnh của miếng thịt lại để tạo thành một gói, sau đó đổ rượu vào khay xung quanh các cạnh. Chuyển vào lò nướng và giảm nhiệt độ xuống 140C/120C quạt/gas 1. Nướng trong 4-5 giờ hoặc cho đến khi nhiệt kế thịt đưa vào phần dày nhất của thịt lợn ghi 70C.', NULL, '2026-05-15 14:53:50', '2026-05-16 12:35:35'),
(4222, 629, 3, 'Vặn lò nướng lên đến 240C/220C quạt/khí 9. Cẩn thận múc nước nướng thịt lợn từ chảo vào nồi và nấu trên lửa vừa trong 10-15 phút hoặc cho đến khi giảm một phần ba. Nêm nếm vừa miệng.', NULL, '2026-05-15 14:53:50', '2026-05-16 12:35:35'),
(4224, 629, 4, 'Trong khi đó, xếp giấy bạc xung quanh miếng thịt sao cho chỉ lộ ra phần da, sau đó cho vào lò nướng khoảng 10 - 15 phút cho đến khi phần da phồng lên và chín vàng toàn bộ. Để yên khoảng 20 phút trước khi cắt. Ăn kèm với nước sốt rưới lên.', NULL, '2026-05-15 14:53:50', '2026-05-16 12:35:35'),
(4226, 630, 1, 'Bắc một chảo nước lên bếp đun sôi với lửa lớn. Trong khi đó, dùng kéo cắt chorizo ​​thành từng dải rồi cắt nhỏ mùi tây và ớt (trước tiên hãy kiểm tra xem có hạt lạc không).', NULL, '2026-05-15 14:53:51', '2026-05-16 12:35:35'),
(4228, 630, 2, 'Khi nước sôi mạnh, cho mì spaghetti cùng một lượng muối vừa đủ vào, khuấy đều và đun sôi trở lại. Nấu trong 3 phút.', NULL, '2026-05-15 14:53:51', '2026-05-16 12:35:35'),
(4230, 630, 3, 'Trong một chảo lớn, đun nóng dầu, cho chorizo, ớt và nhiều tiêu đen vào. Nấu trong khoảng một phút cho đến khi nóng hoàn toàn và nước ép có màu đỏ từ ớt bột trong chorizo. Múc nửa cốc nước mì ống ra khỏi chảo, chắt phần còn lại và cho mì spaghetti vào chảo rán.', NULL, '2026-05-15 14:53:51', '2026-05-16 12:35:35'),
(4232, 630, 4, 'Thêm rau mùi tây và parmesan, trộn đều và vẩy nước mì ống vào để làm ẩm. Đưa thêm parmesan lên bàn.', NULL, '2026-05-15 14:53:51', '2026-05-16 12:35:35'),
(4234, 631, 1, 'Trộn đều cà chua xắt nhỏ, tép tỏi, dầu ô liu, muối và tiêu. Giữ trong tủ lạnh cho đến khi cần thiết.', NULL, '2026-05-15 14:53:53', '2026-05-16 12:35:35'),
(4236, 631, 2, 'Để phục vụ, hãy nướng 20 lát bánh mì baguette. Múc một ít cà chua phủ lên trên từng miếng bánh mì nướng. Xé 5-6 lát jamón Serrano thành từng miếng và đặt từng miếng lên mỗi lát bánh mì.', NULL, '2026-05-15 14:53:53', '2026-05-16 12:35:35'),
(4237, 632, 1, 'Rửa và gọt vỏ khoai tây rồi cắt thành từng miếng có kích thước tương tự để chín đều.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4238, 632, 2, 'Trong một nồi súp lớn, luộc khoai tây và lá nguyệt quế trong nước muối trong 20 phút. Bỏ lá nguyệt quế đi.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4239, 632, 3, 'Nếu bạn không sử dụng túi cải xoăn xoăn cắt sẵn, hãy rửa kỹ các bó dưới vòi nước mát để loại bỏ hết đất - bạn sẽ không muốn có kết cấu sạn trong món ăn đã hoàn thành của mình. Cắt bỏ những cành thô và loại bỏ những lá màu nâu. Dùng một con dao sắc, cắt cải xoăn thành những dải mỏng.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4240, 632, 4, 'Gọt vỏ và cắt nhỏ hẹ.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4241, 632, 5, 'Trong chảo rán hoặc chảo, làm tan chảy 1 muỗng canh. bơ và xào hẹ trong vài phút trước khi thêm cải xoăn xoăn và 2 muỗng canh. của nước. Nêm và nấu trong khoảng 10 phút hoặc cho đến khi mềm.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4242, 632, 6, 'Đun nóng sữa trên bếp hoặc trong lò vi sóng.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4243, 632, 7, 'Để ráo nước, lắc và lau khô khoai tây bằng khăn bếp trước khi nghiền bằng máy nghiền hoặc máy xay khoai tây. Thao tác nhanh chóng, thêm sữa ấm và phần bơ còn lại vào. Nêm nếm với hạt nhục đậu khấu, muối và hạt tiêu.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4244, 632, 8, 'Trộn cải xoăn đã nấu chín với hỗn hợp khoai tây nghiền đã nấu chín.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4245, 632, 9, 'Xếp các lát xúc xích hun khói lên trên và dùng nóng với mù tạt hoặc nước thịt yêu thích của bạn.', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4246, 632, 10, 'Phục vụ và thưởng thức!', NULL, '2026-05-15 14:53:54', '2026-05-15 14:53:54'),
(4247, 633, 1, 'Chuẩn bị', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4248, 633, 2, '1. Đập trứng vào tô. Tách lòng trắng và lòng đỏ trứng.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4249, 633, 3, 'Thịt lợn chua ngọt', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4250, 633, 4, '2. Cắt thăn lợn thành từng dải.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4251, 633, 5, '3. Chuẩn bị nước xốt bằng cách sử dụng một chút muối, một thìa cà phê tinh bột, hai thìa cà phê nước tương nhạt và một lòng trắng trứng.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4252, 633, 6, '4. Ướp các dải thịt lợn trong khoảng 20 phút.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4253, 633, 7, '5. Cho phần tinh bột còn lại vào tô. Thêm một ít nước và giấm để tạo thành nước sốt có tinh bột.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4254, 633, 8, 'Thịt lợn chua ngọt', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4255, 633, 9, 'Hướng dẫn nấu ăn', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4256, 633, 10, '1. Đổ dầu ăn vào chảo và đun nóng đến 190°C (375°F). Thêm các dải thịt lợn đã ướp vào và chiên cho đến khi chúng chuyển sang màu nâu. Lấy thịt lợn đã nấu chín ra khỏi chảo và đặt lên đĩa.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4257, 633, 11, '2. Để lại một ít dầu trong chảo. Cho nước sốt cà chua và đường trắng vào chảo, đun nóng cho đến khi dầu và nước sốt hòa quyện hoàn toàn.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4258, 633, 12, '3. Thêm một ít nước vào chảo và đun nóng kỹ nước sốt chua ngọt trước khi thêm thịt lợn vào.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4259, 633, 13, '4. Đổ nước sốt tinh bột vào. Xào tất cả các nguyên liệu cho đến khi thịt lợn và nước sốt được trộn đều với nhau.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4260, 633, 14, '5. Bày ra đĩa và thêm một ít rau mùi để trang trí.', NULL, '2026-05-15 14:53:56', '2026-05-15 14:53:56'),
(4262, 634, 1, 'Đun nóng dầu trong chảo lớn hoặc nồi chống cháy. Thêm hành lá và cọng rau mùi vào nấu trong 1 phút. Thêm các lát thịt lợn và nấu trong 5 phút cho đến khi bắt đầu có màu nâu.', NULL, '2026-05-15 14:53:57', '2026-05-16 12:35:35'),
(4264, 634, 2, 'Khuấy bột cà ri và bơ đậu phộng. Sau 30 giây, thêm đường, đậu nành và nước cốt dừa cùng ½ lon nước. Trộn đều, đậy nắp và đun nhỏ lửa trong 15 phút, thỉnh thoảng khuấy.', NULL, '2026-05-15 14:53:58', '2026-05-16 12:35:35'),
(4266, 634, 3, 'Mở nắp, thêm bắp non vào và tăng lửa. Đánh bong bóng trong 3 phút cho đến khi ngô chín và nước sốt hơi đặc lại. Khuấy nước cốt chanh và kiểm tra gia vị. Bây giờ có thể được đông lạnh lên đến 2 tháng. Để nấu từ món đông lạnh: rã đông kỹ, sau đó đun trên chảo trên bếp cho đến khi cà ri nóng hoàn toàn. Ăn rải rác với lá rau mùi và cơm.', NULL, '2026-05-15 14:53:58', '2026-05-16 12:35:35'),
(4267, 635, 1, 'Làm nóng lò ở 200°C/quạt180°C/gas 6. Chiên xúc xích trong chảo chống dính cho đến khi chín vàng.', NULL, '2026-05-15 14:53:59', '2026-05-15 14:53:59'),
(4268, 635, 2, 'Rưới dầu thực vật vào khay nướng sâu 30 cm x 25 cm x 6 cm rồi cho vào lò nướng khoảng 5 phút.', NULL, '2026-05-15 14:53:59', '2026-05-15 14:53:59'),
(4269, 635, 3, 'Cho bột mì vào tô, đập trứng cỡ vừa vào, sau đó cho cải ngựa bào vào trộn đều. Dần dần đánh vào sữa bán gầy. Mùa.', NULL, '2026-05-15 14:53:59', '2026-05-15 14:53:59'),
(4270, 635, 4, 'Đặt xúc xích vào khay nướng nóng và đổ bột lên trên. Phủ cà chua bi lên trên và nấu trong 30 phút cho đến khi phồng lên và vàng.', NULL, '2026-05-15 14:53:59', '2026-05-15 14:53:59'),
(4271, 636, 1, 'BƯỚC 1', NULL, '2026-05-15 14:54:00', '2026-05-15 14:54:00'),
(4272, 636, 2, 'Loại bỏ miếng mỡ lớn ở mép mỗi miếng thăn lợn, sau đó đập từng miếng thăn vào giữa hai miếng giấy nướng cho đến khi dày khoảng 1 cm – bạn có thể làm điều này bằng cách sử dụng dụng cụ làm mềm thịt hoặc cây cán bột. Sau khi đập, dùng tay nắn lại hình dạng và độ dày ban đầu của thịt – bước này sẽ đảm bảo thịt mọng nước nhất có thể.', NULL, '2026-05-15 14:54:00', '2026-05-15 14:54:00'),
(4273, 636, 3, 'BƯỚC 2', NULL, '2026-05-15 14:54:00', '2026-05-15 14:54:00'),
(4274, 636, 4, 'Cho bột mì, trứng và vụn bánh mì panko vào ba tô có viền rộng riêng biệt. Nêm thịt, sau đó nhúng vào bột mì, sau đó là trứng, sau đó là vụn bánh mì.', NULL, '2026-05-15 14:54:00', '2026-05-15 14:54:00'),
(4275, 636, 5, 'BƯỚC 3', NULL, '2026-05-15 14:54:00', '2026-05-15 14:54:00'),
(4276, 636, 6, 'Trong chảo rán hoặc chảo xào lớn, cho lượng dầu vừa đủ sao cho ngập thành chảo 2cm. Đun nóng dầu đến 180C – nếu không có nhiệt kế, bạn cho một ít panko vào dầu, nếu thấy hơi chìm xuống thì bắt đầu chiên là dầu đã chín. Thêm hai miếng sườn heo và nấu trong 1 phút 30 giây mỗi mặt, sau đó lấy ra và để trên giá lưới trong 5 phút. Lặp lại với phần sườn heo còn lại.', NULL, '2026-05-15 14:54:00', '2026-05-15 14:54:00'),
(4277, 636, 7, 'BƯỚC 4', NULL, '2026-05-15 14:54:00', '2026-05-15 14:54:00'),
(4278, 636, 8, 'Trong khi thịt lợn đang nghỉ, hãy làm nước sốt bằng cách trộn các nguyên liệu lại với nhau, thêm một chút nước nếu nước sốt đặc biệt đặc. Cắt tonkatsu và dùng kèm với nước sốt.', NULL, '2026-05-15 14:54:00', '2026-05-15 14:54:00'),
(4279, 637, 1, 'Cắt lát mỏng thịt lợn chưa nấu chín, khoảng ⅛\". Nó giúp đông lạnh thịt một chút (tùy chọn).', NULL, '2026-05-15 14:54:03', '2026-05-15 14:54:03'),
(4280, 637, 2, 'Băm tỏi và hẹ. Trộn trong tô với đường, nước mắm, nước tương đặc, hạt tiêu và dầu cho đến khi đường tan.', NULL, '2026-05-15 14:54:03', '2026-05-15 14:54:03'),
(4281, 637, 3, 'Ướp thịt trong 1 giờ hoặc qua đêm để có kết quả tốt hơn.', NULL, '2026-05-15 14:54:03', '2026-05-15 14:54:03'),
(4282, 637, 4, 'Nướng thịt lợn ở nhiệt độ 375F trong 10-15 phút hoặc cho đến khi chín khoảng 80%. Kết thúc quá trình nấu bằng cách nướng trong lò cho đến khi có màu nâu vàng đẹp mắt, lật các miếng giữa chừng.', NULL, '2026-05-15 14:54:03', '2026-05-15 14:54:03'),
(4283, 637, 5, 'Lắp bát của bạn với rau, mì và trang trí. Nhiều người thích trộn cả tô lên và rưới nước mắm lên trên nhưng mình thích làm từng miếng nhỏ và rưới nước mắm từ từ.', NULL, '2026-05-15 14:54:03', '2026-05-15 14:54:03'),
(4285, 638, 1, 'Ngày hôm trước: làm băng. Cho đường và nước cốt chanh vào chảo cùng 1 muỗng canh nước rồi đun sôi để hòa tan đường. Thêm ớt và rau mùi vào rồi khuấy đều, sau đó cho vào máy xay cho đến khi mịn. Đổ vào tô, sau đó cho dầu mè, nước mắm, nước tương và hạt mè vào trộn đều để làm nước sốt. Đậy nắp và làm lạnh cho đến khi cần thiết.', NULL, '2026-05-15 14:54:04', '2026-05-16 12:35:35'),
(4287, 638, 2, 'Hai giờ trước khi ăn: làm nóng chảo nướng. Làm nóng lò ở mức 200C/gas 6/quạt 180C. Quét dầu lên thịt lợn và nướng đều các mặt trong vài phút cho đến khi chín. Chuyển sang khay nướng và cho vào lò nướng khoảng 10-12 phút cho đến khi chín. Để nguội, thái lát mỏng theo thớ thịt. Đổ vào một cái bát và đổ lên một nửa nước sốt.', NULL, '2026-05-15 14:54:04', '2026-05-16 12:35:35'),
(4289, 638, 3, 'Cách dùng: cho các nguyên liệu salad còn lại vào tô cùng với nước sốt còn lại. Xếp ra đĩa, đặt các lát thịt lợn lên trên và rưới lên bất kỳ loại nước trái cây nào.', NULL, '2026-05-15 14:54:04', '2026-05-16 12:35:35'),
(4291, 639, 1, 'Đun nóng 1 muỗng canh dầu trong chảo trên lửa lớn rồi xào từng mẻ thịt lợn cho đến khi chín vàng đều. Loại bỏ bằng một cái muỗng có rãnh và đặt sang một bên.', NULL, '2026-05-15 14:54:06', '2026-05-16 12:35:35'),
(4293, 639, 2, 'Giảm lửa xuống và thêm lượng dầu còn lại vào, sau đó cho hẹ, gừng và ớt vào đảo đều. Nấu trên lửa nhỏ trong vài phút cho đến khi bắt đầu mềm. Cho đường, nước mắm và 200ml nước vào chảo rồi khuấy đều. Đun sôi, khuấy đều cho đường tan hết rồi cho thịt lợn vào chảo. Đánh bong bóng mạnh trong 8-10 phút cho đến khi nước sốt đặc lại, phủ lên thịt và trở nên bóng. Hương vị và khuấy thêm một chút nước mắm, nếu cần, cùng với tương ớt. Rắc hành lá và ăn kèm cơm trắng và pak choi.', NULL, '2026-05-15 14:54:06', '2026-05-16 12:35:35'),
(4295, 640, 1, 'Làm nóng lò ở 200C/Gas 6/quạt 180C. Cắt bỏ phần đầu gỗ của măng tây và bỏ đi. Xếp măng tây thành một lớp trong khay nướng có các cạnh. Cắt cà chua làm đôi theo chiều ngang, trộn chúng với măng tây, nêm muối biển và hạt tiêu rồi rưới dầu ô liu. Cuộn từng miếng thịt xông khói thành một cuộn chặt (nếu lớn, trước tiên hãy cắt làm đôi theo chiều ngang) và xếp vào khay. Rưới mật ong lên cuộn thịt xông khói và nướng trong 20 phút cho đến khi cà chua mềm và thịt xông khói giòn.', NULL, '2026-05-15 14:54:11', '2026-05-16 12:35:35'),
(4297, 640, 2, 'Trong lúc đó, luộc khoai tây cho đến khi mềm. Đánh đều giấm, dầu ô liu, mù tạt, một ít muối biển và hạt tiêu vào tô lớn cho đến khi hòa quyện. Cho lá tên lửa hoặc rau bina vào một nửa nước sốt và bày lên đĩa phục vụ lớn.', NULL, '2026-05-15 14:54:11', '2026-05-16 12:35:35'),
(4299, 640, 3, 'Xả khoai tây và cắt làm đôi. Nhẹ nhàng trộn chúng với phần nước sốt còn lại và xếp lên đĩa cùng với măng tây. Nhét cà chua và thịt xông khói vào.', NULL, '2026-05-15 14:54:11', '2026-05-16 12:35:35'),
(4300, 641, 1, 'Kết hợp thịt lợn, tỏi, gừng, nước tương, dầu mè và rau vào tô.', NULL, '2026-05-15 14:54:12', '2026-05-15 14:54:12'),
(4301, 641, 2, 'Tách vỏ hoành thánh.', NULL, '2026-05-15 14:54:12', '2026-05-15 14:54:12'),
(4302, 641, 3, 'Đặt một thìa cà phê nhân vào giữa hoành thánh.', NULL, '2026-05-15 14:54:12', '2026-05-15 14:54:12'),
(4303, 641, 4, 'Quét nước lên 2 viền da, cách mép 1/4 inch.', NULL, '2026-05-15 14:54:12', '2026-05-15 14:54:12'),
(4304, 641, 5, 'Gấp da lại để tạo thành hình tam giác, dán kín các cạnh.', NULL, '2026-05-15 14:54:12', '2026-05-15 14:54:12'),
(4305, 641, 6, 'Chụm hai điểm dài bên ngoài lại với nhau.', NULL, '2026-05-15 14:54:12', '2026-05-15 14:54:12'),
(4306, 641, 7, 'Đun nóng dầu đến 450 độ và chiên lần lượt 4 đến 5 miếng cho đến khi vàng.', NULL, '2026-05-15 14:54:12', '2026-05-15 14:54:12'),
(4307, 641, 8, 'Xả và phục vụ với nước sốt.', NULL, '2026-05-15 14:54:12', '2026-05-15 14:54:12'),
(4308, 642, 1, 'Trộn các nguyên liệu làm nước sốt vào một bát nhỏ và nêm muối và hạt tiêu. Đặt sang một bên.', NULL, '2026-05-15 14:54:14', '2026-05-15 14:54:14'),
(4309, 642, 2, 'Nấu mì ống theo hướng dẫn trên gói. Thêm đậu Hà Lan có đường vào phút cuối cùng của thời gian nấu.', NULL, '2026-05-15 14:54:14', '2026-05-15 14:54:14'),
(4310, 642, 3, 'Trong khi đó, làm nóng dầu trong chảo hoặc chảo rán lớn, cho tỏi và ớt vào nấu trên lửa khá nhẹ trong khoảng 30 giây mà không để tỏi chuyển sang màu nâu. Cho tôm vào nấu trên lửa lớn, khuấy thường xuyên trong khoảng 3 phút cho đến khi tôm chuyển sang màu hồng.', NULL, '2026-05-15 14:54:14', '2026-05-15 14:54:14'),
(4311, 642, 4, 'Thêm cà chua vào và nấu, thỉnh thoảng khuấy trong 3 phút cho đến khi chúng bắt đầu mềm. Xả sạch mì và đường rồi trộn vào hỗn hợp tôm. Xé lá húng quế, khuấy đều và nêm muối và hạt tiêu.', NULL, '2026-05-15 14:54:14', '2026-05-15 14:54:14'),
(4312, 642, 5, 'Ăn kèm lá salad rưới nước sốt chanh và bánh mì giòn nóng.', NULL, '2026-05-15 14:54:14', '2026-05-15 14:54:14'),
(4313, 643, 1, 'Trong một cái chảo vừa, khuấy kem đông, bơ và bột ngô trên lửa nhỏ và đun nhỏ lửa. Tắt lửa và giữ ấm.', NULL, '2026-05-15 14:54:16', '2026-05-15 14:54:16'),
(4314, 643, 2, 'Trong khi đó, cho phô mai và hạt nhục đậu khấu vào một cái bát nhỏ rồi thêm một ít tiêu đen xay nhuyễn, sau đó khuấy đều mọi thứ lại với nhau (không thêm muối ở giai đoạn này).', NULL, '2026-05-15 14:54:16', '2026-05-15 14:54:16'),
(4315, 643, 3, 'Cho mì ống vào một chảo khác với 2 thìa cà phê muối, đổ một ít nước sôi và nấu theo hướng dẫn trên bao bì (thường là 3-4 phút). Khi nấu chín, múc một ít nước nấu vào bình hoặc ca chịu nhiệt rồi để ráo mì nhưng không quá kỹ.', NULL, '2026-05-15 14:54:16', '2026-05-15 14:54:16'),
(4316, 643, 4, 'Thêm mì ống vào chảo với hỗn hợp kem đông, sau đó rắc phô mai lên và nhẹ nhàng gấp mọi thứ lại với nhau trên lửa nhỏ bằng thìa cao su. Khi kết hợp, cho 3 muỗng canh nước nấu vào. Lúc đầu, mì sẽ trông ướt và luộm thuộm: tiếp tục khuấy cho đến khi nước ngấm và nước sốt sánh bóng. Kiểm tra gia vị trước khi chuyển sang bát đã đun nóng. Rắc lên một ít hẹ hoặc rau mùi tây, sau đó dùng ngay.', NULL, '2026-05-15 14:54:16', '2026-05-15 14:54:16'),
(4317, 644, 1, 'Làm mac và phô mai', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4318, 644, 2, '1. Đun sôi một nồi nước vừa có nhiều muối (bạn muốn nước có vị như nước biển). Thêm mì ống vào và nấu, thỉnh thoảng khuấy cho đến khi chín tới, từ 8 đến 10 phút hoặc theo hướng dẫn trên bao bì. Sợi mì phải mềm nhưng vẫn dai.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4319, 644, 3, '2. Trong khi nấu mì ống, trong một tô nhỏ, trộn đều bột mì, bột mù tạt, bột tỏi, muối, tiêu đen và ớt cayenne.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4320, 644, 4, '3. Xả mì ống vào một cái chao. Đặt chảo mì ống rỗng (không cần rửa) trên lửa nhỏ và thêm bơ vào. Khi bơ tan chảy, cho hỗn hợp bột vào tiếp tục nấu, đánh đều cho đến khi hỗn hợp bắt đầu chuyển sang màu nâu và có mùi thơm hấp dẫn dễ chịu, khoảng 1 phút. Chú ý canh cẩn thận để không bị cháy sém dưới đáy chảo.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4321, 644, 5, '4. Từ từ đánh sữa và kem vào hỗn hợp bột cho đến khi mọi thứ thật sự hòa quyện. Nấu, khuấy liên tục cho đến khi nước sốt nóng lên và bắt đầu đặc lại, khoảng 2 phút. Hủy bỏ khỏi nhiệt. Dần dần thêm phô mai vào trong khi khuấy liên tục bằng thìa gỗ hoặc thìa silicone và tiếp tục khuấy cho đến khi phô mai tan chảy vào nước sốt. Sau đó cho mì đã luộc chín vào trộn đều.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4322, 644, 6, '5. Lót giấy nến hoặc giấy nhôm vào khay nướng có viền kích thước 9 x 13 inch (23 x 33 cm). Phủ giấy hoặc giấy bạc bằng bình xịt nấu ăn không dính hoặc bôi bơ. Đổ mac và phô mai ấm lên khay nướng đã chuẩn bị sẵn và dùng thìa trải đều. Phủ một miếng giấy da khác bằng bình xịt nấu ăn hoặc bơ rồi đặt mặt đã phết dầu hoặc bơ xuống dưới, trực tiếp lên bề mặt của mac và pho mát. Làm lạnh cho đến khi nguội và chắc, khoảng 1 giờ.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4323, 644, 7, 'Làm phô mai nướng', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4324, 644, 8, '6. Đun nóng chảo gang lớn hoặc chảo chống dính trên lửa vừa và nhỏ.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4325, 644, 9, '7. Trong một tô nhỏ, khuấy đều 4 thìa canh (55 gam) bơ và bột tỏi cho đến khi hòa quyện.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4326, 644, 10, '8. Lấy mac và phô mai ra khỏi tủ lạnh và bóc lớp giấy da trên cùng. Cẩn thận cắt thành 8 miếng bằng nhau. Mỗi miếng sẽ làm được 1 chiếc bánh mì mac nướng và phô mai. (Bạn có thể bảo quản từng phần riêng lẻ trong túi nhựa hai lớp có thể khóa lại và để trong tủ lạnh tối đa 3 ngày hoặc đông lạnh tối đa 1 tháng.)', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4327, 644, 11, '9. Phết 3/4 thìa cà phê bơ tỏi lên một mặt của mỗi lát bánh mì. Đặt một nửa số lát đã phết bơ úp xuống trên thớt sạch. Trên mỗi miếng có một lát Cheddar, sau đó là 1 miếng mac và pho mát. (Chuyển từ khay nướng bằng cách quét tay hoặc thìa dưới từng miếng mac và phô mai, sau đó lật nó lên trên một chiếc bánh sandwich.) Đặt 1 lát Jack lên trên mỗi miếng. Kết thúc với những lát bánh mì còn lại, phết bơ lên ​​trên.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4328, 644, 12, '10. Dùng một chiếc thìa rộng, đặt càng nhiều bánh sandwich vào chảo càng tốt mà không làm bánh bị dồn. Đậy nắp và nấu cho đến khi mặt dưới có màu nâu đẹp mắt, khoảng 4 phút. Lật và nấu cho đến khi các mặt thứ hai chuyển sang màu nâu, phô mai tan chảy, mac và phô mai được đun nóng trong khoảng 4 phút nữa.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4329, 644, 13, '11. Lặp lại với các nguyên liệu còn lại. Cắt đôi bánh sandwich nếu muốn và thưởng thức.', NULL, '2026-05-15 14:54:17', '2026-05-15 14:54:17'),
(4330, 645, 1, '1. Trong một bát nhỏ, trộn bốn nguyên liệu đầu tiên; phết lên bốn lát bánh mì. Lớp với thịt xông khói, cà chua và phô mai; phủ bánh mì còn lại lên trên.', NULL, '2026-05-15 14:54:19', '2026-05-15 14:54:19'),
(4331, 645, 2, '2. Làm tan chảy 2 thìa bơ trong chảo hoặc vỉ nướng lớn. Nướng bánh mì sandwich cho đến khi vàng nhạt cả hai mặt và phô mai tan chảy, thêm bơ nếu cần.', NULL, '2026-05-15 14:54:19', '2026-05-15 14:54:19'),
(4332, 645, 3, 'Thành phần dinh dưỡng', NULL, '2026-05-15 14:54:19', '2026-05-15 14:54:19'),
(4333, 645, 4, '1 bánh sandwich: 445 calo, 24g chất béo (12g chất béo bão hòa), 66mg cholesterol, 1094mg natri, 35g carbohydrate (3g đường, 2g chất xơ), 21g protein.', NULL, '2026-05-15 14:54:19', '2026-05-15 14:54:19'),
(4334, 646, 1, 'Nấu mì ống theo hướng dẫn gói. Đun nóng dầu trong chảo chống dính rồi cho hành, tỏi, ớt vào xào khoảng 3-4 phút cho mềm. Khuấy nhuyễn cà chua và nấu trong 1 phút, sau đó thêm hành tây với nước sốt của chúng. Nấu chín, dùng thìa gỗ bẻ cá, sau đó thêm ô liu vào và tiếp tục nấu thêm vài phút nữa.', NULL, '2026-05-15 14:54:20', '2026-05-15 14:54:20'),
(4335, 646, 2, 'Xả mì ống và cho vào chảo cùng với 2-3 muỗng canh nước nấu. Trộn đều mọi thứ lại với nhau, sau đó chia ra các đĩa và thưởng thức, rải đều với Parmesan.', NULL, '2026-05-15 14:54:20', '2026-05-15 14:54:20'),
(4336, 647, 1, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C). Bôi mỡ vào đĩa nướng 9x13 inch.', NULL, '2026-05-15 14:54:23', '2026-05-15 14:54:23'),
(4337, 647, 2, 'Đun sôi một nồi lớn nước muối nhẹ. Thêm spaghetti và nấu trong 8 đến 10 phút hoặc cho đến khi chín; để ráo nước và khuấy đều với nước sốt cà chua, bột cà chua, quế, dầu, muối và hạt tiêu. Chuyển sang món ăn đã chuẩn bị.', NULL, '2026-05-15 14:54:23', '2026-05-15 14:54:23'),
(4338, 647, 3, 'Nướng trong lò làm nóng trước trong 1 giờ hoặc cho đến khi mặt trên giòn.', NULL, '2026-05-15 14:54:23', '2026-05-15 14:54:23'),
(4339, 648, 1, 'Đun nóng dầu trong chảo lớn. Thêm chân vịt vào và chiên chín vàng các mặt trong khoảng 10 phút. Đổ ra đĩa và đặt sang một bên. Thêm hành tây vào chảo và nấu trong 5 phút cho đến khi mềm. Thêm tỏi và nấu thêm 1 phút nữa, sau đó cho quế và bột mì vào đảo đều và nấu thêm một phút nữa. Cho vịt trở lại chảo, thêm rượu, cà chua, nước kho, rau thơm, đường và gia vị. Đun sôi, sau đó giảm nhiệt, đậy nắp và nấu trong 2 giờ, thỉnh thoảng khuấy.', NULL, '2026-05-15 14:54:24', '2026-05-15 14:54:24'),
(4340, 648, 2, 'Cẩn thận nhấc chân vịt ra khỏi nước sốt và đặt vào đĩa - chúng sẽ rất mềm nên cố gắng không để mất miếng thịt nào. Gọt vỏ và loại bỏ mỡ, sau đó dùng 2 nĩa xé thịt và bỏ xương. Cho thịt trở lại nước sốt với sữa và đun nhỏ lửa, không đậy nắp, thêm 10-15 phút nữa trong khi nấu mì ống.', NULL, '2026-05-15 14:54:24', '2026-05-15 14:54:24'),
(4341, 648, 3, 'Nấu mì ống theo hướng dẫn trên bao bì, sau đó để ráo nước, chừa lại một cốc nước mì ống và thêm mì ống vào ragu. Khuấy để phủ tất cả mì ống vào nước sốt và nấu thêm 1 phút nữa, thêm một chút nước nấu nếu thấy khô. Ăn kèm với Parmesan bào, nếu bạn thích.', NULL, '2026-05-15 14:54:24', '2026-05-15 14:54:24'),
(4343, 649, 1, 'Làm nóng lò ở 180C/quạt 160C/gas 4. Cho yến mạch, dừa, bột mì và đường vào tô. Đun chảy bơ trong chảo nhỏ và cho xi-rô vàng vào khuấy đều. Thêm bicarbonate soda vào 2 muỗng canh nước sôi, sau đó khuấy đều vào hỗn hợp xi-rô vàng và bơ.', NULL, '2026-05-15 14:54:27', '2026-05-16 12:35:35'),
(4345, 649, 2, 'Tạo một cái giếng ở giữa nguyên liệu khô và đổ hỗn hợp bơ và xi-rô vàng vào. Khuấy nhẹ nhàng để kết hợp các thành phần khô.', NULL, '2026-05-15 14:54:27', '2026-05-16 12:35:35'),
(4347, 649, 3, 'Đặt các thìa hỗn hợp tráng miệng lên khay nướng đã phết bơ, cách nhau khoảng 2,5cm/1in để có chỗ trải đều. Nướng từng mẻ trong 8-10 phút cho đến khi vàng. Chuyển sang giá dây để nguội.', NULL, '2026-05-15 14:54:27', '2026-05-16 12:35:35'),
(4348, 650, 1, 'Trộn sữa, dầu và trứng với nhau. Rây bột mì, bột nở và muối vào hỗn hợp. Khuấy đều cho đến khi tất cả các thành phần được kết hợp đồng đều.', NULL, '2026-05-15 14:54:29', '2026-05-15 14:54:29'),
(4349, 650, 2, 'Trải một ít bột lên chảo. Trải một lớp bột mỏng lên thành chảo. Đậy chảo trong 30-60 giây cho đến khi xuất hiện bọt khí nhỏ.', NULL, '2026-05-15 14:54:29', '2026-05-15 14:54:29'),
(4350, 650, 3, 'Thêm bơ, bắp kem, đậu phộng giã nhuyễn và đường vào bánh pancake. Gấp chiếc bánh pancake làm đôi khi mặt dưới đã chín vàng.', NULL, '2026-05-15 14:54:29', '2026-05-15 14:54:29'),
(4351, 650, 4, 'Cắt thành từng miếng vừa ăn và ăn ngon nhất khi còn ấm.', NULL, '2026-05-15 14:54:29', '2026-05-15 14:54:29'),
(4352, 651, 1, 'Làm nóng lò ở nhiệt độ 190C/170C quạt/gas 5. Cho bột mì và đường vào tô lớn. Thêm bơ, sau đó dùng đầu ngón tay chà xát vào bột để tạo kết cấu vụn bánh mì nhẹ. Đừng làm việc quá sức nếu không mảnh vụn sẽ trở nên nặng nề. Rắc đều hỗn hợp lên khay nướng và nướng trong 15 phút hoặc cho đến khi có màu nhạt.', NULL, '2026-05-15 14:54:30', '2026-05-15 14:54:30'),
(4353, 651, 2, 'Trong khi đó, đối với món compote, gọt vỏ, bỏ lõi và cắt táo thành xúc xắc 2cm. Cho bơ và đường vào nồi vừa và đun chảy với lửa vừa. Nấu trong 3 phút cho đến khi hỗn hợp chuyển sang màu caramel nhẹ. Cho táo vào và nấu trong 3 phút. Thêm quả mâm xôi và quế vào nấu thêm 3 phút nữa. Đậy nắp, tắt bếp, sau đó để khoảng 2-3 phút để tiếp tục nấu trên chảo ấm.', NULL, '2026-05-15 14:54:30', '2026-05-15 14:54:30'),
(4354, 651, 3, 'Để phục vụ, hãy múc trái cây còn ấm vào đĩa gratin chịu nhiệt, phủ hỗn hợp vụn lên trên, sau đó hâm nóng trong lò trong 5-10 phút. Ăn kèm với kem vani.', NULL, '2026-05-15 14:54:30', '2026-05-15 14:54:30'),
(4355, 652, 1, 'Làm nóng lò ở nhiệt độ 180°C. (350˚F) Bôi mỡ vào chảo bánh và lót giấy nướng.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4356, 652, 2, 'Trong một tô lớn, đập bốn quả trứng với đường và đánh cho đến khi chúng nở gấp ba lần và trở nên bông xốp.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4357, 652, 3, 'Rây bột nở tự nổi và thêm vào hỗn hợp trứng của bạn. Gấp cái này lại, bảo quản càng nhiều không khí càng tốt. Thêm bơ tan chảy (và hơi nguội) vào và trộn cho đến khi hòa quyện.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4358, 652, 4, 'Thêm quế, một chút muối và chiết xuất vani.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4359, 652, 5, 'Thêm táo thái hạt lựu vào bột và nhẹ nhàng gấp chúng vào bột để các miếng táo được phân bố đều. Bạn có thể lăn những miếng táo qua một ít quế.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4360, 652, 6, 'Đổ bột vào chảo bánh đã chuẩn bị sẵn và dùng thìa làm mịn phần trên.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4361, 652, 7, 'Đặt các lát táo lên trên mặt bột và ấn nhẹ. Tùy ý rắc một ít vỏ hạnh nhân.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4362, 652, 8, 'Nướng bánh táo trong lò làm nóng trước khoảng 45-50 phút, hoặc cho đến khi xiên que gỗ vào giữa bánh thấy tăm sạch sẽ.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4363, 652, 9, 'Lấy bánh ra khỏi lò và để nguội trong khuôn vài phút. Sau đó cẩn thận lấy bánh ra khỏi khuôn và để nguội hoàn toàn trên giá lưới.', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4364, 652, 10, 'Rắc đường bột lên bánh táo đã nguội', NULL, '2026-05-15 14:54:33', '2026-05-15 14:54:33'),
(4365, 653, 1, 'Làm nóng lò ở mức quạt/gas 200C/180C 6.', NULL, '2026-05-15 14:54:34', '2026-05-15 14:54:34'),
(4366, 653, 2, 'Đặt bánh quy vào một túi đông lạnh lớn có thể bịt kín lại và dùng cán cán thành từng miếng vụn mịn. Đun chảy bơ trong chảo nhỏ, sau đó cho vụn bánh quy vào và khuấy đều cho đến khi bơ phủ đều. Đổ bánh tart vào khuôn và dùng mặt sau của thìa ấn lên đáy và các cạnh của khuôn để tạo thành một lớp đều. Làm lạnh trong tủ lạnh trong khi bạn làm nhân.', NULL, '2026-05-15 14:54:34', '2026-05-15 14:54:34'),
(4367, 653, 3, 'Đánh bơ và đường cùng nhau cho đến khi mịn và nhạt màu. Bạn có thể làm điều này trong máy xay thực phẩm nếu có. Quá trình trong 2-3 phút. Trộn trứng vào, sau đó thêm hạnh nhân xay và chiết xuất hạnh nhân vào, trộn đều cho đến khi hòa quyện.', NULL, '2026-05-15 14:54:34', '2026-05-15 14:54:34'),
(4368, 653, 4, 'Gọt vỏ táo, cắt thành từng lát mỏng. Làm điều này vào phút cuối để táo không bị chuyển sang màu nâu. Xếp các lát bánh lên trên đế bánh quy. Trải đều nhân frangipane lên trên. Làm phẳng bề mặt và rắc hạnh nhân vụn.', NULL, '2026-05-15 14:54:34', '2026-05-15 14:54:34'),
(4369, 653, 5, 'Nướng trong 20-25 phút cho đến khi có màu vàng nâu và chín.', NULL, '2026-05-15 14:54:34', '2026-05-15 14:54:34'),
(4370, 653, 6, 'Lấy ra khỏi lò và để nguội trong 15 phút. Loại bỏ các cạnh của thiếc. Một cách dễ dàng để làm điều này là đặt hộp thiếc lên trên một lon đậu và ấn nhẹ xuống các cạnh của hộp thiếc.', NULL, '2026-05-15 14:54:34', '2026-05-15 14:54:34'),
(4371, 653, 7, 'Chuyển bánh tart đã gắn đế thiếc vào đĩa phục vụ. Ăn nóng với kem, crème fraiche hoặc kem.', NULL, '2026-05-15 14:54:34', '2026-05-15 14:54:34'),
(4373, 654, 1, 'Cho mascarpone, sữa chua, đường và nước hoa cam vào tô lớn và đánh đều cho đến khi đặc lại. Gấp các nguyên liệu còn lại lại, sau đó chia hỗn hợp vào 2 ly hoặc bát tráng miệng và trang trí thêm bạc hà nếu bạn thích.', NULL, '2026-05-15 14:54:35', '2026-05-16 12:35:35'),
(4374, 655, 1, 'Nghiền hạnh nhân trong máy xay hạnh nhân hoặc máy chế biến thực phẩm.', NULL, '2026-05-15 14:54:37', '2026-05-15 14:54:37'),
(4375, 655, 2, 'Trộn hạnh nhân và đường bột với nhau trong một tô trộn lớn. Thêm ba lòng trắng trứng vào và dùng tay nhào bột cho đến khi bột thành một khối. Bọc trong màng bám và để trong tủ lạnh ít nhất một giờ, tốt nhất là đến ngày hôm sau.', NULL, '2026-05-15 14:54:37', '2026-05-15 14:54:37'),
(4376, 655, 3, 'Bôi mỡ kỹ vào các khuôn kransekake và phủ một lớp bột báng, bột mì hoặc vụn bánh mì.', NULL, '2026-05-15 14:54:37', '2026-05-15 14:54:37'),
(4377, 655, 4, 'Làm nóng lò ở nhiệt độ trên và dưới là 210°C (410°F). Chia bột thành sáu phần.', NULL, '2026-05-15 14:54:37', '2026-05-15 14:54:37'),
(4378, 655, 5, 'Từ từ thêm lòng trắng trứng còn lại vào bột và nhào cho đến khi bạn có thể cuộn thành những chiếc xúc xích dài dày bằng ngón trỏ. Đổ xúc xích bột vào khuôn, ghim các đầu lại với nhau để tạo thành các vòng.', NULL, '2026-05-15 14:54:37', '2026-05-15 14:54:37'),
(4379, 655, 6, 'Đặt các khuôn lên khay nướng và đặt lại vào giữa lò trong khoảng 10 - 12 phút, cho đến khi mặt trên có màu nâu vàng.', NULL, '2026-05-15 14:54:37', '2026-05-15 14:54:37'),
(4380, 656, 1, 'Để làm bánh ngọt, hãy đo lượng bột mì cho vào tô và dùng đầu ngón tay xoa bơ cho đến khi hỗn hợp giống như vụn bánh mì mịn. Thêm nước vào, trộn đều để tạo thành bột mềm.', NULL, '2026-05-15 14:54:38', '2026-05-15 14:54:38'),
(4381, 656, 2, 'Cán bột trên bề mặt đã rắc chút bột mì và dùng để lót khuôn bánh flan 20 cm/8 inch. Để trong tủ lạnh để ướp trong 30 phút.', NULL, '2026-05-15 14:54:38', '2026-05-15 14:54:38'),
(4382, 656, 3, 'Làm nóng lò ở mức 200C/400F/Gas 6 (quạt 180C).', NULL, '2026-05-15 14:54:38', '2026-05-15 14:54:38'),
(4383, 656, 4, 'Lót giấy bạc vào vỏ bánh ngọt và đổ đậu nướng vào. Nướng mù khoảng 15 phút, sau đó lấy đậu và giấy bạc ra rồi nấu thêm 5 phút nữa để đế khô.', NULL, '2026-05-15 14:54:38', '2026-05-15 14:54:38'),
(4384, 656, 5, 'Để dũa, phết một lớp mứt mâm xôi lên phần đế của chiếc bánh flan.', NULL, '2026-05-15 14:54:38', '2026-05-15 14:54:38'),
(4385, 656, 6, 'Đun chảy bơ trong chảo, tắt bếp rồi cho đường vào khuấy đều. Thêm hạnh nhân xay, trứng và chiết xuất hạnh nhân. Đổ vào khuôn bánh flan và rắc hạnh nhân đã vỡ vụn lên trên.', NULL, '2026-05-15 14:54:38', '2026-05-15 14:54:38'),
(4386, 656, 7, 'Nướng trong khoảng 35 phút. Nếu hạnh nhân có vẻ chín vàng quá nhanh, hãy dùng giấy bạc bọc nhẹ bánh tart để tránh bị cháy.', NULL, '2026-05-15 14:54:38', '2026-05-15 14:54:38'),
(4388, 657, 1, 'Đầu tiên, làm xi-rô. Cho đường vào nồi lớn cùng 650ml nước. Khuấy trên lửa nhỏ cho đến khi đường tan hết thì vặn lửa lớn và đun sôi. Giảm nhiệt để đun nhỏ lửa và nấu trong 15 phút, sau đó vắt vào vài giọt nước cốt chanh và đun nhỏ lửa thêm 5 phút nữa. Hủy bỏ nhiệt và để nguội. Trong khi đó, để làm baklava sau này, hãy đun chảy bơ trong chảo nhỏ trên lửa nhỏ trong 5 phút, hớt bọt và loại bỏ bọt nổi lên trên bề mặt.', NULL, '2026-05-15 14:54:39', '2026-05-16 12:35:35'),
(4390, 657, 2, 'Để làm nhân, hãy nghiền nát tất cả các loại hạt bằng chày và cối, hoặc xay nhuyễn trong máy chế biến thực phẩm - bạn muốn có một hỗn hợp các loại hạt xay mịn với một vài miếng vụn. Đổ vào tô, trộn đều gia vị và đặt sang một bên.', NULL, '2026-05-15 14:54:39', '2026-05-16 12:35:35'),
(4392, 657, 3, 'Trong một bát riêng, trộn ricotta với vỏ chanh, vỏ cam và vani. Làm nóng lò nướng ở nhiệt độ 180C/160C quạt/gas 4. Quét một ít bơ tan chảy vào đáy khay nướng lớn (khoảng 35 x 47cm). Mỗi lần xử lý từng tờ filo (che phần còn lại bằng khăn trà ẩm để tránh bị khô), trải tờ giấy lên bảng sao cho một trong các đầu ngắn hướng về phía bạn. Rắc đều 30g hỗn hợp hạt lên toàn bộ tờ giấy, sau đó múc 1 muỗng canh hỗn hợp ricotta ở đầu gần bạn nhất. Gấp đầu này lại để bọc nhân, sau đó đặt một xiên dài và mỏng cạnh mép gấp rồi cuộn bánh ngọt xung quanh để tạo thành một cuộn dài. Khi cuộn lại hoàn toàn, nó sẽ có độ dày gần bằng xúc xích chipolata. Trong khi giữ một đầu của que cán hoặc xiên, nhẹ nhàng bóp cuộn filo như đàn xếp và cẩn thận đẩy nó ra khỏi xiên và lên khay đã chuẩn bị sẵn. Lặp lại với phần filo và phần nhân còn lại - bạn sẽ có được khoảng 12 cuộn. Cắt mỗi cuộn thành bốn để tạo thành 48 chiếc baklava lớn hoặc tám để tạo thành 96 chiếc bánh nhỏ.', NULL, '2026-05-15 14:54:39', '2026-05-16 12:35:35'),
(4394, 657, 4, 'Chải với bơ tan chảy còn lại. Nướng trong 20-25 phút cho đến khi vàng đều, lật khay lại nửa chừng. Khi còn nóng, đổ ngay 5-6 muôi si-rô vào. Bạn sẽ nghe thấy tiếng xi-rô xèo xèo khi chạm vào bánh baklava nóng. Đặt sang một bên để nguội và hấp thụ.', NULL, '2026-05-15 14:54:39', '2026-05-16 12:35:35'),
(4396, 657, 5, 'Đun chảy sô cô la đen trong một chiếc bát chịu nhiệt đặt trên chảo nước sôi, đảm bảo bát không chạm vào nước hoặc cho vào lò vi sóng trong thời gian ngắn. Rưới thứ này lên baklava đã nguội và rắc quả hồ trăn đã xay.', NULL, '2026-05-15 14:54:39', '2026-05-16 12:35:35'),
(4397, 658, 1, 'Trong một cái bát, nghiền chuối bằng nĩa cho đến khi nó giống như một hỗn hợp nhuyễn. Khuấy trứng, bột nở và vani.', NULL, '2026-05-15 14:54:41', '2026-05-15 14:54:41'),
(4398, 658, 2, 'Đun nóng chảo chống dính lớn hoặc chảo pancake trên lửa vừa và phết một nửa lượng dầu. Dùng một nửa lượng bột, múc hai chiếc bánh vào chảo, nướng mỗi mặt khoảng 1-2 phút rồi úp ra đĩa. Lặp lại quá trình với dầu và bột còn lại. Phủ hồ đào và quả mâm xôi lên trên bánh kếp.', NULL, '2026-05-15 14:54:41', '2026-05-15 14:54:41'),
(4399, 659, 1, 'Làm nóng lò nướng ở mức quạt/khí 4 180C/160C rồi lót giấy nến vào đáy và các cạnh của hộp thiếc vuông 20 cm (cách dễ nhất là đặt các dải dài 2 x 20 cm lên trên đế). Để làm bánh bông lan hạnh nhân, hãy cho bơ, đường, bột mì, hạnh nhân xay, bột nở, trứng, vani và chiết xuất hạnh nhân vào tô lớn. Đánh bằng máy đánh trứng điện cho đến khi hỗn hợp hòa quyện với nhau mịn màng. Cạo vào khuôn, dàn đều ra các góc và nướng trong 25-30 phút - khi bạn chọc xiên vào, xiên sẽ sạch. Làm nguội trong hộp thiếc trong 10 phút, sau đó chuyển sang giá lưới để nguội hoàn tất trong khi bạn làm miếng bọt biển thứ hai.', NULL, '2026-05-15 14:54:43', '2026-05-15 14:54:43'),
(4400, 659, 2, 'Đối với miếng bọt biển màu hồng, hãy lót hộp thiếc như trên. Trộn tất cả các thành phần với nhau như trên, nhưng không thêm chiết xuất hạnh nhân. Gấp một ít màu thực phẩm màu hồng vào. Sau đó cạo tất cả vào khuôn và nướng như trước. Mát mẻ.', NULL, '2026-05-15 14:54:43', '2026-05-15 14:54:43'),
(4401, 659, 3, 'Để lắp ráp, đun nóng mứt trong chảo nhỏ cho đến khi chảy nước, sau đó rây. Chỉ cần cắt tỉa hai cạnh đối diện của miếng bọt biển hạnh nhân, sau đó tỉa kỹ cạnh thứ ba. Đo đại khái chiều cao của miếng bọt biển, sau đó cắt từ mép đã được cắt tỉa cẩn thận, dùng thước giúp bạn cắt 4 lát, mỗi lát có chiều rộng bằng chiều cao của miếng bọt biển. Vứt bỏ hoặc gặm miếng bọt biển còn sót lại. Lặp lại với bánh màu hồng.', NULL, '2026-05-15 14:54:43', '2026-05-15 14:54:43'),
(4402, 659, 4, 'Lấy 2 x lát hạnh nhân và 2 x lát màu hồng và cắt sao cho chúng có cùng chiều dài. Cán một khối bánh hạnh nhân trên bề mặt có phủ một ít đường bột với chiều rộng chỉ hơn 20 cm, sau đó tiếp tục lăn theo chiều dọc cho đến khi bánh hạnh nhân dày khoảng 0,5 cm. Quét một lớp mứt mơ, sau đó đặt một lát bánh hạnh nhân và một lát màu hồng cạnh nhau ở một đầu của bánh hạnh nhân, phết mứt vào giữa để dính bọt biển và chừa lại phần bánh hạnh nhân trong suốt 4cm ở cuối. Quét thêm mứt lên trên miếng bọt biển, sau đó kẹp 2 lát còn lại lên trên, xen kẽ các màu để tạo hiệu ứng bàn cờ. Cắt bánh hạnh nhân theo chiều dài của bánh.', NULL, '2026-05-15 14:54:43', '2026-05-15 14:54:43'),
(4403, 659, 5, 'Cẩn thận nhấc bánh hạnh nhân lên và dùng tay dàn đều trên mặt bánh, nhưng để lại một nếp bánh hạnh nhân nhỏ dọc theo mép dưới trước khi dán vào mặt đầu tiên. Cắt cạnh đối diện để phù hợp với kích thước của nếp gấp, sau đó dùng ngón tay cái và ngón cái bấm các cạnh (hoặc đơn giản hơn là ấn bằng ngạnh nĩa). Nếu bạn thích, hãy đánh dấu 10 lát bằng cách sử dụng nĩa.', NULL, '2026-05-15 14:54:43', '2026-05-15 14:54:43'),
(4404, 659, 6, 'Lắp ráp Battenberg thứ hai và giữ trong hộp kín hoặc bọc kỹ trong màng bám trong tối đa 3 ngày. Có thể đông lạnh đến một tháng.', NULL, '2026-05-15 14:54:43', '2026-05-15 14:54:43'),
(4405, 660, 1, 'Trong tô của máy trộn đứng, thêm nước ấm, một chút đường và men. Để yên cho đến khi nổi bọt.', NULL, '2026-05-15 14:54:45', '2026-05-15 14:54:45'),
(4406, 660, 2, 'Trong cùng một bát, thêm 1/2 cốc đường, sữa ấm, bơ tan chảy, trứng và muối vào rồi đánh đều cho đến khi hòa quyện.', NULL, '2026-05-15 14:54:45', '2026-05-15 14:54:45'),
(4407, 660, 3, 'Đặt một cái móc bột vào máy trộn, thêm bột mì vào máy, cho đến khi tạo thành một khối bột mịn nhưng hơi dính.', NULL, '2026-05-15 14:54:45', '2026-05-15 14:54:45'),
(4408, 660, 4, 'Đặt bột vào tô, bọc bằng màng bọc thực phẩm và để bột ủ trong 1 tiếng rưỡi.', NULL, '2026-05-15 14:54:45', '2026-05-15 14:54:45'),
(4409, 660, 5, 'Cắt bột thành 12 miếng và cán thành những hình bầu dục dài dày khoảng 1/4 inch giống đuôi hải ly.', NULL, '2026-05-15 14:54:45', '2026-05-15 14:54:45'),
(4410, 660, 6, 'Trong một chiếc nồi lớn và sâu, đun nóng dầu ở nhiệt độ 350 độ. Nhẹ nhàng cho bột đuôi hải ly vào dầu nóng và chiên mỗi mặt từ 30 đến 45 giây cho đến khi có màu vàng nâu.', NULL, '2026-05-15 14:54:45', '2026-05-15 14:54:45'),
(4411, 660, 7, 'Xả trên khăn giấy và trang trí theo ý muốn. Thêm đường quế, đường trắng với một chút chanh hoặc với một ít Nutella và một ít hạnh nhân nướng. Thưởng thức!', NULL, '2026-05-15 14:54:45', '2026-05-15 14:54:45'),
(4413, 661, 1, 'Cho củ cải đường vào bình cùng với sữa và dùng máy xay sinh tố xay cho đến khi mịn. Đổ vào tô cùng với các nguyên liệu làm bánh pancake còn lại và đánh cho đến khi mịn và có màu tím rực rỡ.', NULL, '2026-05-15 14:54:48', '2026-05-16 12:35:35'),
(4415, 661, 2, 'Đặt một miếng bơ nhỏ vào chảo chống dính lớn và đun nóng ở lửa vừa-thấp cho đến khi tan chảy và nổi bọt. Bây giờ hãy tạo 3 hoặc 4 chiếc bánh kếp, mỗi chiếc được làm từ 2 muỗng canh bột. Nấu khoảng 2-3 phút rồi lật lại và nấu thêm một phút nữa cho đến khi chín. Lặp lại với bất kỳ bột còn lại. Làm nóng lò ở mức thấp nhất và giữ ấm bánh kếp trong đó cho đến khi cần.', NULL, '2026-05-15 14:54:48', '2026-05-16 12:35:35'),
(4417, 661, 3, 'Ăn kèm với lớp phủ bánh kếp yêu thích của bạn hoặc làm một món chế biến đơn giản bằng cách đun sôi quả mọng đông lạnh với 1 muỗng canh mứt lý chua đen cho đến khi sủi bọt và có dạng siro (khoảng 5-10 phút). Trong một bát nhỏ khuấy đều phần mứt còn lại và sữa chua. Xếp những chiếc bánh đã nấu chín với sữa chua và đổ hỗn hợp quả mọng ấm lên trên.', NULL, '2026-05-15 14:54:48', '2026-05-16 12:35:35'),
(4418, 662, 1, 'Đối với bánh quy, làm nóng lò nướng ở nhiệt độ 200C/180C (quạt)/Gas 6 và lót giấy nướng vào hai khay nướng lớn. Rải các loại hạt lên khay nướng và nướng trong lò khoảng 6-8 phút hoặc cho đến khi có màu vàng nâu. Hãy quan sát chúng cẩn thận để chúng không có cơ hội bị cháy. Lấy ra khỏi lò, đặt lên một tấm ván và để nguội.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4419, 662, 2, 'Cho bơ và đường vào tô lớn và đánh bằng thìa gỗ cho đến khi mịn và mịn như kem. Cắt nhỏ các loại hạt đã nguội rồi thêm vào bơ đánh kem và đường, cùng với vỏ chanh, bột mì và bột nở. Khuấy đều cho đến khi hỗn hợp hòa quyện và tạo thành một khối - bạn có thể phải dùng tay.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4420, 662, 3, 'Chia bột bánh quy thành 24 phần đều nhau và vo thành từng viên nhỏ. Đặt các viên bánh vào khay nướng đã chuẩn bị sẵn, cách đều nhau để có thể trải đều.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4421, 662, 4, 'Nhấn bánh quy để làm phẳng độ dày khoảng 1 cm/½ inch. Nướng bánh quy từng khay một trong 12 phút hoặc cho đến khi có màu nâu vàng nhạt. Để nguội trên khay. Chúng sẽ rất mềm khi bạn lấy chúng ra khỏi lò, nhưng sẽ giòn khi nguội.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4422, 662, 5, 'Bảo quản trong hộp kín và ăn trong vòng năm ngày.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4423, 662, 6, 'Đối với kẻ ngốc, hãy rửa quả mâm xôi trong một cái chao để rửa sạch bụi bẩn. Cho quả mâm xôi vào chảo chống dính và rắc đường lên trên.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4424, 662, 7, 'Khuấy nước cốt chanh và đun nóng nhẹ trong hai phút hoặc cho đến khi quả mâm xôi bắt đầu mềm và tiết ra nước. Lấy và để dành 12 quả mâm xôi để trang trí và tiếp tục nấu phần còn lại.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4425, 662, 8, 'Đun nhỏ quả mâm xôi thật nhẹ nhàng trong 15 phút, khuấy thường xuyên cho đến khi thật mềm và có độ sệt. Tắt bếp và ép quả mọng và nước ép qua rây trên một cái bát, sử dụng đáy muôi để giúp bạn chiết xuất được càng nhiều nước ép nhuyễn càng tốt. Để hỗn hợp nhuyễn nguội và loại bỏ hạt. Bạn sẽ thu được khoảng 325ml/11fl oz bột nhuyễn.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4426, 662, 9, 'Cho kem và sữa chua vào một tô lớn và dùng máy đánh trứng đánh cho đến khi lấy máy đánh trứng ra khỏi bát để tạo thành chóp mềm – tính axit của trái cây sẽ làm kem đặc hơn, vì vậy đừng đánh quá xa.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4427, 662, 10, 'Khi hỗn hợp đã nguội hoàn toàn, hãy điều chỉnh độ ngọt theo khẩu vị bằng cách thêm đường nếu cần. Đổ nó vào bát cùng với kem đánh bông và sữa chua rồi khuấy chỉ một hoặc hai lần cho đến khi hòa quyện rất nhẹ.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4428, 662, 11, 'Múc từng quả dâu đen vào các đĩa thủy tinh rộng, riêng lẻ - hoặc một bát lớn, đơn. Nó sẽ trông khá giống đá cẩm thạch, vì vậy đừng khuấy quá kỹ. Rắc một vài lá bạc hà nhỏ lên trên và trang trí với quả mâm xôi dành riêng. Rắc một chút đường nếu thích và dùng kèm với bánh quy hạt phỉ.', NULL, '2026-05-15 14:54:49', '2026-05-15 14:54:49'),
(4430, 663, 1, 'Làm nóng lò nướng ở mức quạt 180C/200C thông thường/khí 6. Bơ nhiều bơ vào sáu hộp bánh rán hoặc bánh nướng xốp chống dính. Đun chảy bơ và để nguội.', NULL, '2026-05-15 14:54:50', '2026-05-16 12:35:35'),
(4432, 663, 2, 'Rây đường bột và bột mì vào tô. Thêm hạnh nhân và trộn mọi thứ giữa các ngón tay của bạn.', NULL, '2026-05-15 14:54:50', '2026-05-16 12:35:35'),
(4434, 663, 3, 'Đánh lòng trắng trứng vào một cái bát khác cho đến khi tạo thành bọt mềm, nhẹ. Tạo một cái giếng ở giữa các nguyên liệu khô, cho lòng trắng trứng và vỏ chanh vào, sau đó khuấy nhẹ bơ để tạo thành hỗn hợp bột mềm.', NULL, '2026-05-15 14:54:50', '2026-05-16 12:35:35'),
(4436, 663, 4, 'Chia bột vào các hộp thiếc, một chiếc thìa lớn là hoàn hảo cho công việc này. Rắc một ít quả việt quất lên mỗi chiếc bánh và nướng trong 15-20 phút cho đến khi sờ vào thấy cứng và có màu vàng nâu.', NULL, '2026-05-15 14:54:50', '2026-05-16 12:35:35'),
(4438, 663, 5, 'Để nguội trong hộp thiếc trong 5 phút, sau đó lấy ra và để nguội trên giá lưới. Để phục vụ, rắc nhẹ với đường bột.', NULL, '2026-05-15 14:54:50', '2026-05-16 12:35:35'),
(4439, 664, 1, 'Làm nóng lò ở nhiệt độ 180°C/350˚F (lò nướng thông thường).', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4440, 664, 2, 'Cho bơ đã làm mềm và đường vào tô máy trộn đứng và đánh cho đến khi thành kem.', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4441, 664, 3, 'Thêm bột mì và muối vào rồi nhào bằng tay cho đến khi thu được khối bột mịn. Chia thành hai phần.', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4442, 664, 4, 'Lót giấy nến vào đế khuôn bánh hình vuông hoặc tròn (không phải khuôn dạng lò xo) và đặt nửa đầu của chiếc bánh lên trên. Làm phẳng bằng ngón tay và thìa.', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4443, 664, 5, 'Dùng một thìa cà phê, rắc một ít dulce de leche lên trên đế. Rắc sô cô la cắt nhỏ và phủ nửa sau của chiếc bánh ngọt lên.', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4444, 664, 6, 'Việc này phức tạp hơn một chút, nhưng nếu bạn làm không đúng thì cũng đừng lo lắng, sau khi nướng xong sẽ ổn thôi! Quét bánh ngọt bằng trứng đã đánh.', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4445, 664, 7, 'Nướng trong lò khoảng 30 phút hoặc cho đến khi có màu vàng nâu. Nó sẽ chao đảo. Đó là vì bánh bơ chỉ cứng lại khi nguội.', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4446, 664, 8, 'Cắt thành miếng nhỏ khi nó nguội hoàn toàn!', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4447, 664, 9, 'Ghi chú', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4448, 664, 10, 'Bảo quản: Bảo quản trong hộp kín, để ngoài tủ lạnh khoảng 2-3 ngày hoặc để trong tủ lạnh khoảng 5 ngày. Đóng băng lên đến ba tháng.', NULL, '2026-05-15 14:54:51', '2026-05-15 14:54:51'),
(4449, 665, 1, 'Bôi bơ vào đĩa bánh 1 lít/2 pint.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4450, 665, 2, 'Cắt vỏ bánh mì. Trải từng lát bơ lên ​​một mặt, sau đó cắt thành hình tam giác.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4451, 665, 3, 'Xếp một lớp bánh mì phết bơ lên ​​trên dưới đáy đĩa, sau đó thêm một lớp nho sultanas. Rắc một ít quế, sau đó lặp lại các lớp bánh mì và nho, rắc quế cho đến khi bạn dùng hết bánh mì. Kết thúc bằng một lớp bánh mì rồi đặt sang một bên.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4452, 665, 4, 'Nhẹ nhàng làm ấm sữa và kem trong chảo trên lửa nhỏ đến mức sôi. Đừng để nó sôi.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4453, 665, 5, 'Đập trứng vào tô, thêm 3/4 lượng đường vào rồi đánh nhẹ cho đến khi nhạt màu.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4454, 665, 6, 'Thêm hỗn hợp sữa và kem ấm vào rồi khuấy đều, sau đó lọc sữa trứng vào tô.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4455, 665, 7, 'Đổ sữa trứng lên các lớp bánh mì đã chuẩn bị sẵn và rắc hạt nhục đậu khấu và lượng đường còn lại rồi để yên trong 30 phút.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4456, 665, 8, 'Làm nóng lò ở 180C/355F/Gas 4.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4457, 665, 9, 'Đặt món ăn vào lò nướng và nướng trong 30-40 phút hoặc cho đến khi sữa trứng đông lại và mặt trên có màu nâu vàng.', NULL, '2026-05-15 14:54:52', '2026-05-15 14:54:52'),
(4458, 666, 1, 'Làm nóng lò nướng ở nhiệt độ quạt 170C/ thông thường 190C/gas 5. Cán bột bánh trên bề mặt đã rắc chút bột mì sao cho mỏng hơn một chút so với khi lấy bánh ra khỏi gói. Sau đó cắt 18-20 vòng bằng dao cắt rãnh 7,5cm, cuộn lại các phần trang trí. Sử dụng các vòng tròn để lót hai hộp bánh tart 12 lỗ sâu (không phải hộp bánh nướng xốp). Nếu chỉ có khuôn bánh tart 12 lỗ cỡ thông thường, bạn có thể làm một số loại bánh tart nông hơn một chút.', NULL, '2026-05-15 14:54:54', '2026-05-15 14:54:54'),
(4459, 666, 2, 'Đánh trứng vào tô lớn và kết hợp với các nguyên liệu còn lại trừ quả óc chó. Đổ hỗn hợp này vào chảo và khuấy liên tục trong 3-4 phút cho đến khi bơ tan chảy, hỗn hợp sủi bọt và bắt đầu đặc lại. Nó phải đủ dày để phủ mặt sau của một chiếc thìa gỗ. Đừng nấu quá chín và nhớ khuấy liên tục vì hỗn hợp có thể dễ bị cháy. Tắt bếp và cho các loại hạt vào khuấy đều.', NULL, '2026-05-15 14:54:54', '2026-05-15 14:54:54'),
(4460, 666, 3, 'Múc nhân vào vỏ bánh tart chưa nướng sao cho ngang bằng với bánh ngọt. Nướng trong 15-18 phút cho đến khi chín và có màu vàng nhạt. Để trong hộp thiếc nguội vài phút trước khi nhấc lên giá lưới. Phục vụ ấm hoặc lạnh.', NULL, '2026-05-15 14:54:54', '2026-05-15 14:54:54');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(4461, 667, 1, 'Cho bã me và 1 cốc đường vào tô rồi dùng thìa hoặc nĩa nghiền nhuyễn. Lấy một lượng nhỏ hỗn hợp me và đường rồi vo thành những quả bóng nhỏ bằng cách lăn chúng trong tay. Làm cho chúng có kích thước bằng một viên bi hoặc lớn hơn một chút, tùy thích.', NULL, '2026-05-15 14:54:55', '2026-05-15 14:54:55'),
(4462, 667, 2, 'Thêm lượng đường còn lại vào một bề mặt phẳng, chẳng hạn như đĩa hoặc chảo. Lăn những quả me trong đường cát cho đến khi chúng được phủ đều.', NULL, '2026-05-15 14:54:55', '2026-05-15 14:54:55'),
(4463, 667, 3, 'Bạn có thể ăn me viên ngay hoặc có thể để vài giờ hoặc qua đêm. Để chúng đông lại sẽ mang lại cho chúng kết cấu chắc chắn hơn và lớp phủ đường kết tinh hơn. Thưởng thức.', NULL, '2026-05-15 14:54:55', '2026-05-15 14:54:55'),
(4464, 668, 1, 'Đối với bánh cà rốt, làm nóng lò nướng ở nhiệt độ 160C/325F/Gas 3. Bôi mỡ và lót khuôn bánh dạng lò xo 26cm/10in.', NULL, '2026-05-15 14:54:56', '2026-05-15 14:54:56'),
(4465, 668, 2, 'Trộn tất cả nguyên liệu làm bánh cà rốt, trừ cà rốt và quả óc chó, vào tô cho đến khi hòa quyện. Khuấy cà rốt và quả óc chó.', NULL, '2026-05-15 14:54:56', '2026-05-15 14:54:56'),
(4466, 668, 3, 'Múc hỗn hợp vào khuôn bánh và nướng trong 1 giờ 15 phút, hoặc cho đến khi xiên que vào giữa thấy tăm sạch sẽ. Lấy bánh ra khỏi lò và để nguội trong 10 phút, sau đó cẩn thận lấy bánh ra khỏi khuôn và để nguội hoàn toàn trên giá làm mát.', NULL, '2026-05-15 14:54:56', '2026-05-15 14:54:56'),
(4467, 668, 4, 'Trong khi đó, để làm kem, đánh kem phô mai, đường bột và bơ với nhau trong tô cho đến khi mịn. Dùng dao tạo lớp kem phủ lên mặt bánh.', NULL, '2026-05-15 14:54:56', '2026-05-15 14:54:56'),
(4468, 669, 1, 'Làm nóng lò ở 180 C / Gas 4. Lót khay nướng bằng giấy thấm mỡ.', NULL, '2026-05-15 14:54:57', '2026-05-15 14:54:57'),
(4469, 669, 2, 'Trong một cái bát, trộn hạt điều và đường bột. Thêm lòng đỏ trứng và nước hoa cam vào rồi trộn đều thành hỗn hợp đồng nhất mịn.', NULL, '2026-05-15 14:54:57', '2026-05-15 14:54:57'),
(4470, 669, 3, 'Lấy từng cục bột điều và vo thành những quả bóng nhỏ. Lăn các quả bóng trong đường bột và chuyển vào khay nướng. Đẩy một quả hạnh nhân vào giữa mỗi chiếc ghribia.', NULL, '2026-05-15 14:54:57', '2026-05-15 14:54:57'),
(4471, 669, 4, 'Nướng cho đến khi bánh quy có màu vàng nhẹ, khoảng 20 phút. Hãy để mắt tới chúng, chúng sẽ cháy rất nhanh.', NULL, '2026-05-15 14:54:57', '2026-05-15 14:54:57'),
(4472, 670, 1, 'Rây bột mì và muối vào tô lớn. Tạo một cái giếng ở giữa và thêm men vào.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4473, 670, 2, 'Trong khi đó, làm ấm sữa và bơ trong chảo cho đến khi bơ tan chảy và hỗn hợp còn âm ấm.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4474, 670, 3, 'Thêm hỗn hợp sữa và trứng vào hỗn hợp bột và khuấy cho đến khi các thành phần trong bát hòa quyện với nhau thành một khối bột mềm. (Bạn có thể cần thêm một ít bột mì.)', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4475, 670, 4, 'Đổ bột lên một bề mặt làm việc đã được rải đầy bột mì. Nhào trong năm phút, thêm bột mì nếu cần, cho đến khi bột mịn, đàn hồi và không còn cảm giác dính.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4476, 670, 5, 'Thoa nhẹ một ít dầu thực vật vào bát. Đặt bột vào tô và đảo cho đến khi phủ đầy dầu. Đậy bát bằng màng dính và để ở nơi ấm áp trong một giờ hoặc cho đến khi bột nở gấp đôi.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4477, 670, 6, 'Bôi nhẹ một lớp mỡ lên khay nướng.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4478, 670, 7, 'Để làm nhân, đập bột trở lại kích thước ban đầu và đặt lên bề mặt đã rắc một lớp bột mì nhẹ. Cán bột thành hình chữ nhật dày 0,5 cm/¼ inch. Quét bơ tan chảy lên khắp mặt, sau đó rắc đường nâu, quế và trái cây khô lên trên.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4479, 670, 8, 'Cán bột thành hình trụ thật chặt, cắt mười lát 4 cm/1½ inch và đặt chúng lên khay nướng đã phết một ít dầu mỡ, chừa một khoảng trống nhỏ giữa mỗi lát. Che lại bằng một chiếc khăn trà và đặt sang một bên để ủ trong 30 phút.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4480, 670, 9, 'Làm nóng lò ở 190C/375F/Gas 5.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4481, 670, 10, 'Nướng bánh trong lò khoảng 20-25 phút hoặc cho đến khi bánh nở và có màu vàng nâu.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4482, 670, 11, 'Trong khi đó, đối với phần men, đun nóng sữa và đường trong nồi cho đến khi sôi. Giảm nhiệt và đun nhỏ lửa trong 2-3 phút.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4483, 670, 12, 'Lấy bánh ra khỏi lò và phết một lớp men, sau đó đặt sang một bên để nguội trên giá lưới.', NULL, '2026-05-15 14:54:58', '2026-05-15 14:54:58'),
(4484, 671, 1, 'Để làm thạch rượu vang đỏ, cho rượu vang đỏ, đường mứt, hoa hồi, đinh hương, thanh quế, hạt tiêu, vỏ vani tách đôi và hạt vào một cái chảo vừa. Khuấy đều, sau đó đun nóng nhẹ để hòa tan đường. Tăng nhiệt và đun sôi trong 20 phút cho đến khi giảm bớt và có dạng siro. Lọc vào lọ mứt nhỏ đã khử trùng và để nguội hoàn toàn. Sẽ giữ trong tủ lạnh lên đến 1 tháng.', NULL, '2026-05-15 14:55:00', '2026-05-15 14:55:00'),
(4485, 671, 2, 'Lấy bánh ra khỏi tủ lạnh và để ở nhiệt độ phòng trong 10 phút, sau đó mở ra. Làm nóng lò nướng ở mức cao và làm nóng lò ở mức quạt/gas 180C/160C 4. Cắt những miếng bánh ngọt hình tròn 2 x 13cm, dùng đĩa làm hướng dẫn và đặt lên khay nướng chống dính. Rắc từng khoanh tròn 1 thìa đường rồi nướng trong 5 phút cho caramen, quan sát cẩn thận để đường không bị cháy. Lấy ra khỏi vỉ nướng. Có thể làm trước vài giờ và để trong tủ lạnh, đậy kín.', NULL, '2026-05-15 14:55:00', '2026-05-15 14:55:00'),
(4486, 671, 3, 'Gọt vỏ, cắt đôi và bỏ lõi táo, cắt thành lát mỏng 2mm và xếp lên trên mặt bánh. Rắc lên lượng đường còn lại rồi cho vào lò nướng khoảng 20-25 phút cho đến khi bánh chín và vàng đều, táo mềm. Lấy ra và để nguội một chút. Đun nóng 3 thìa thạch rượu vang đỏ trong chảo nhỏ trên lửa nhỏ với 1 thìa cà phê nước để thạch chảy hơn một chút, sau đó quét lên trên mặt bánh tart.', NULL, '2026-05-15 14:55:00', '2026-05-15 14:55:00'),
(4487, 671, 4, 'Đổ kem tươi vào tô, rây đường bột và bạch đậu khấu rồi trộn đều. Cẩn thận nhấc những chiếc bánh tart còn ấm lên đĩa phục vụ và dùng kèm với kem bạch đậu khấu.', NULL, '2026-05-15 14:55:00', '2026-05-15 14:55:00'),
(4488, 672, 1, 'Đầu tiên, làm bánh ngọt. Cho nguyên liệu vào máy xay thực phẩm với 1/4 thìa cà phê muối. Trộn cho đến khi hỗn hợp giống như vụn bánh mì. Rưới 2-3 thìa cà phê nước lạnh vào phễu trong khi lưỡi dao đang chạy – hỗn hợp sẽ bắt đầu kết tụ lại với nhau. Đổ lên bề mặt làm việc và tập hợp lại với nhau, nhào nhanh thành một quả bóng. Đổ vào đĩa, bọc trong màng bám và để lạnh ít nhất 20 phút. Làm nóng lò ở mức quạt/gas 200C/180C 6.', NULL, '2026-05-15 14:55:01', '2026-05-15 14:55:01'),
(4489, 672, 2, 'Lấy bánh ra khỏi tủ lạnh và để ở nhiệt độ phòng trong 5 phút cho mềm. Phủ bột lên bề mặt làm việc, sau đó mở bánh ra và cuộn thành hình tròn có độ dày bằng đồng xu £ 1. Dùng bánh ngọt để lót một khuôn bánh có rãnh tròn, đường kính 23 cm – của tôi sâu khoảng 3 cm. Nhấn bánh ngọt vào các góc và hướng lên trên, đảm bảo không có khoảng trống. Để lại phần bánh ngọt nhô ra 1cm (để dành một số mẩu bánh ngọt cho lần sau). Lót giấy nến nướng (nhớ trước để dẻo hơn) và đổ đậu nướng vào. Nướng kín trong 15-20 phút cho đến khi các mặt chín hẳn, sau đó lấy giấy da và đậu ra rồi cho vào lò nướng trong 5 phút cho đến khi có màu vàng nâu. Cắt bánh sao cho phẳng với mặt trên của hộp thiếc - tốt nhất nên dùng một con dao có răng cưa nhỏ cho việc này. Nếu có bất kỳ vết nứt nào, hãy vá chúng bằng vụn bánh ngọt.', NULL, '2026-05-15 14:55:01', '2026-05-15 14:55:01'),
(4490, 672, 3, 'Trong khi đó, cân bơ, xi-rô và đường vào chảo, thêm 1/4 thìa cà phê muối. Đun nóng cho đến khi bơ tan chảy và đường tan, khuấy đều cho đến khi mịn. Tắt bếp và để nguội trong 10 phút. Giảm nhiệt độ lò/quạt xuống 160C/140C 3.', NULL, '2026-05-15 14:55:01', '2026-05-15 14:55:01'),
(4491, 672, 4, 'Đánh trứng vào tô. Thêm hỗn hợp xi-rô, vani và hồ đào vào và trộn cho đến khi kết hợp tốt. Đổ một nửa hỗn hợp vào hộp bánh tart, rải lên một nửa số sô cô la chip, sau đó phủ phần nhân còn lại và sô cô la chip lên. Nướng trên kệ giữa trong 50-55 phút cho đến khi chín. Lấy ra khỏi lò và để nguội, sau đó để lạnh ít nhất 2 giờ trước khi dùng.', NULL, '2026-05-15 14:55:01', '2026-05-15 14:55:01'),
(4492, 673, 1, 'Đối với bánh quy, đánh bơ với đường trong vài phút. Sau đó thêm trứng và mật ong vào và trộn đều. Thêm bột mì, bột ngô, ca cao, baking soda và bột nở vào rồi trộn cho đến khi thu được khối bột. Bọc trong màng bọc thực phẩm và để lạnh ít nhất nửa giờ hoặc qua đêm.', NULL, '2026-05-15 14:55:02', '2026-05-15 14:55:02'),
(4493, 673, 2, 'Lót giấy nến vào hai khay nướng, làm nóng lò ở nhiệt độ 200 độ C.', NULL, '2026-05-15 14:55:02', '2026-05-15 14:55:02'),
(4494, 673, 3, 'Chia bột thành hai phần, một phần để vào tủ lạnh trước khi dùng. Cán phần thứ hai khoảng 2 mm và cắt những chiếc bánh quy tròn có đường kính 5-6 cm. Điều này có thể được thực hiện bằng máy cắt bánh quy hoặc ly. Bạn sẽ nhận được tổng cộng 30 chiếc bánh quy hoặc thậm chí nhiều hơn, tôi nhận được khoảng 40 chiếc. Nướng một khay nướng mỗi lần trong khoảng 8-10 phút. Để bánh nguội.', NULL, '2026-05-15 14:55:02', '2026-05-15 14:55:02'),
(4495, 673, 4, 'Để làm nhân bánh, hãy tìm hai chiếc bánh quy có cùng kích thước và đặt khoảng một thìa cà phê dulce de leche lên chiếc bánh dưới cùng trước khi kẹp lại với nhau.', NULL, '2026-05-15 14:55:02', '2026-05-15 14:55:02'),
(4496, 673, 5, 'Cắt nhỏ sô cô la vừa ngọt và làm tan chảy với bơ và vỏ cam ở lửa nhỏ. Nhúng từng chiếc bánh sandwich vào sô cô la và để nguội trên giấy da trước khi dùng.', NULL, '2026-05-15 14:55:02', '2026-05-15 14:55:02'),
(4497, 674, 1, '1. Trộn tất cả nguyên liệu mousse lại với nhau trong máy xay thực phẩm cho đến khi mịn. Trước tiên hãy thêm bột cacao và khi trộn, bạn có sẵn tất cả các nguyên liệu để điều chỉnh tỷ lệ một chút vì kích thước của quả bơ và chuối rất khác nhau. Tỷ lệ hoàn hảo để tránh món ăn nếm quá nhiều một trong hai là sử dụng lượng bằng nhau của cả hai.', NULL, '2026-05-15 14:55:03', '2026-05-15 14:55:03'),
(4498, 674, 2, '2. Nếm thử và thêm vài giọt stevia nếu bạn cảm thấy cần thêm vị ngọt.', NULL, '2026-05-15 14:55:03', '2026-05-15 14:55:03'),
(4499, 674, 3, '3. Đổ mousse vào các cốc nhỏ hoặc ly nhỏ, rắc bột cacao hoặc ngòi cacao và thưởng thức.', NULL, '2026-05-15 14:55:03', '2026-05-15 14:55:03'),
(4500, 674, 4, 'Mẹo Nếu không có sẵn chuối đông lạnh, bạn có thể sử dụng chuối bình thường rồi làm lạnh mousse trước khi dùng làm món tráng miệng giải nhiệt.', NULL, '2026-05-15 14:55:03', '2026-05-15 14:55:03'),
(4501, 675, 1, 'Bôi mỡ và lót giấy nến vào khuôn nướng 20 x 20cm/8\" x 8\".', NULL, '2026-05-15 14:55:06', '2026-05-15 14:55:06'),
(4502, 675, 2, 'Đặt các thanh mars và bơ vào tô chịu nhiệt rồi đặt lên chảo nước vừa sôi. Trộn bằng máy đánh trứng, đun chảy cho đến khi hỗn hợp mịn.', NULL, '2026-05-15 14:55:06', '2026-05-15 14:55:06'),
(4503, 675, 3, 'Đổ bánh gạo vào tô trộn và trộn cho đến khi tất cả các nguyên liệu hòa quyện đều nhau. Nhấn đều vào khuôn nướng đã chuẩn bị và đặt sang một bên.', NULL, '2026-05-15 14:55:06', '2026-05-15 14:55:06'),
(4504, 675, 4, 'Làm tan chảy sô cô la sữa trong lò vi sóng hoặc trên chảo nước vừa sôi.', NULL, '2026-05-15 14:55:06', '2026-05-15 14:55:06'),
(4505, 675, 5, 'Rải sô cô la tan chảy lên hỗn hợp bánh gạo krispie và để ở nơi mát mẻ. Sau khi đặt lát thành hình vuông và phục vụ!', NULL, '2026-05-15 14:55:06', '2026-05-15 14:55:06'),
(4507, 676, 1, 'Để làm nước sốt, bạn cho đường và bơ vào nồi đun nhỏ lửa cho đến khi đường tan, sau đó cho kem vào khuấy đều và đun nhỏ lửa cho đến khi có nước sốt sánh mịn, khoảng 2-3 phút. Tắt bếp, khuấy đều với một chút muối biển và sô cô la, rồi tiếp tục khuấy trong 2-3 phút hoặc cho đến khi tan chảy hoàn toàn. Giữ ấm hoặc để nguội để hâm nóng sau. Đối với lớp phủ, trộn đường với quế và một chút muối biển mịn rồi để sang một bên.', NULL, '2026-05-15 14:55:07', '2026-05-16 12:35:35'),
(4509, 676, 2, 'Đối với bánh churros, cho bột mì, ca cao, bột nở và một chút muối vào tô. Thêm chiết xuất vani và bơ tan chảy, sau đó cẩn thận đổ 250-300ml nước sôi vào và đánh đều để tạo thành hỗn hợp bột mịn, rất đặc. Để nguội trong vài phút, sau đó cạo hỗn hợp vào túi bắt kem có gắn vòi hình sao cỡ trung bình.', NULL, '2026-05-15 14:55:07', '2026-05-16 12:35:35'),
(4511, 676, 3, 'Đổ dầu hướng dương vào nồi chiên ngập dầu theo hướng dẫn của nhà sản xuất hoặc chảo đế nặng, đảm bảo dầu không đầy quá một phần ba. Đun nóng đến 170C hoặc cho đến khi một khối bánh mì chuyển sang màu nâu trong 30 giây. Đổ những đoạn bột dài 12-15cm vào dầu, dùng kéo cắt bỏ phần cuối của mỗi cục bột. Cho bốn hoặc năm ống mỗi lần và nấu trong khoảng 4 phút, hoặc cho đến khi vàng và giòn, xoay chúng bằng kẹp hoặc thìa có rãnh khi nấu. Lấy ra khỏi dầu và đặt trên giá dây. Lặp lại với phần bột còn lại. Để nguội nếu hâm nóng sau, nếu không thì lăn churros trong đường quế và dùng ngay với sốt sô cô la ấm và kem. Để hâm nóng bánh churros, hãy đặt lên khay và nướng trong 5-8 phút, sau đó lăn trong lớp đường phủ. Trong khi đó, đun nóng nước sốt trong chảo và dùng kèm để chấm.', NULL, '2026-05-15 14:55:07', '2026-05-16 12:35:35'),
(4513, 677, 1, 'Làm nóng lò ở 180C/quạt 160C/gas 4. Bơ bơ và lót đáy khuôn nướng hình vuông 20cm. Đánh bơ và đường cho đến khi nhạt màu, sau đó cho trứng vào đánh đều. Thêm 1 muỗng canh bột mì nếu hỗn hợp bắt đầu đặc lại.', NULL, '2026-05-15 14:55:08', '2026-05-16 12:35:35'),
(4515, 677, 2, 'Rây bột mì, bột nở và ca cao vào rồi dùng thìa kim loại trộn đều. Khuấy sữa. Cạo hỗn hợp vào hộp thiếc và san bằng mặt trên. Nướng trong 18-20 phút hoặc cho đến khi ấn bánh lại. Để nguội trong hộp thiếc.', NULL, '2026-05-15 14:55:08', '2026-05-16 12:35:35'),
(4517, 677, 3, 'Để làm kem, cho sô cô la, bơ và 4 muỗng canh nước vào chảo và đun nóng nhẹ cho đến khi tan chảy. Để nguội một chút rồi cho đường bột vào đánh đều.', NULL, '2026-05-15 14:55:08', '2026-05-16 12:35:35'),
(4519, 677, 4, 'Lấy bánh ra khỏi khuôn và bóc giấy. Cắt thành 16 hình vuông. Nhúng các hình vuông vào kem, sau đó lăn vào dừa. Cho phép đặt trên giá làm mát.', NULL, '2026-05-15 14:55:08', '2026-05-16 12:35:35'),
(4520, 678, 1, 'Để làm đầy, đặt lon vào một cái nồi lớn và đổ đầy nước vào. Đun sôi trong hai tiếng rưỡi, thỉnh thoảng thêm nước. Để nguội trước khi mở. Để biết thêm lời khuyên, vui lòng kiểm tra ở đây.', NULL, '2026-05-15 14:55:11', '2026-05-15 14:55:11'),
(4521, 678, 2, 'Đối với bột, trộn bột mì, bột ca cao và muối vào tô lớn. Thêm bơ lạnh thành từng miếng nhỏ và dùng ngón tay chà thành từng mảnh vụn. Thêm trứng và nhào thành bột. Bạn có thể phải thêm sữa, mỗi lần một thìa sữa nếu sữa vẫn khô. Bọc và thư giãn ít nhất nửa giờ hoặc qua đêm.', NULL, '2026-05-15 14:55:11', '2026-05-15 14:55:11'),
(4522, 678, 3, 'Lót giấy nến vào khay nướng và làm nóng lò trước ở nhiệt độ 180 độ C.', NULL, '2026-05-15 14:55:11', '2026-05-15 14:55:11'),
(4523, 678, 4, 'Cán bột trên một bề mặt đã rắc chút bột mì, bột phải mỏng. Cắt các hình tròn có kích thước 12cm bằng khuôn cắt bánh quy hoặc bằng đĩa/đĩa nhỏ hơn. Đặt hai đến ba muỗng cà phê dulce de leche vào giữa mỗi vòng tròn. Quét sữa lên các cạnh, tôi làm điều này với ngón út của mình. Gấp mỗi vòng tròn làm đôi để có hình bán nguyệt và dùng nĩa ấn các cạnh xuống. Bạn cũng có thể xoay các cạnh khoảng nửa centimet vào trong mỗi centimet hoặc lâu hơn để tạo hoa văn.', NULL, '2026-05-15 14:55:11', '2026-05-15 14:55:11'),
(4524, 678, 5, 'Đặt bánh empanadas đã chuẩn bị lên khay nướng và phết nước rửa trứng lên. Nướng trong khoảng 20-25 phút.', NULL, '2026-05-15 14:55:11', '2026-05-15 14:55:11'),
(4525, 678, 6, 'Đến cuối thời gian nướng, làm tan chảy phần bơ còn lại rồi trộn đường và quế vào một cái bát nhỏ. Sau khi bạn lấy empanadas ra, ngay lập tức phết bơ lên ​​và rắc hỗn hợp đường. Empanadas có thể được thưởng thức khi còn ấm hoặc lạnh. Nếu ăn ấm, hãy cẩn thận đừng để bị bỏng với nhân nóng!', NULL, '2026-05-15 14:55:11', '2026-05-15 14:55:11'),
(4526, 679, 1, 'Làm nóng lò ở 180°C/350°F/Mã khí 4. Bôi mỡ và lót đế của khuôn bánh lò xo tròn 8 inch bằng giấy nướng', NULL, '2026-05-15 14:55:13', '2026-05-15 14:55:13'),
(4527, 679, 2, 'Đập sô-cô-la vào tô chịu nhiệt rồi đặt lên nồi nước sôi nhẹ và khuấy đều cho đến khi sô-cô-la tan chảy. (hoặc làm tan chảy trong lò vi sóng trong 2-3 phút thỉnh thoảng khuấy)', NULL, '2026-05-15 14:55:13', '2026-05-15 14:55:13'),
(4528, 679, 3, 'Cho bơ và đường vào tô trộn và dùng thìa gỗ trộn kem cho đến khi mềm và mịn. Từ từ đánh trứng vào, thêm một ít bột mì nếu hỗn hợp bắt đầu đặc lại. Trộn phần bột còn lại với sô-cô-la tan chảy đã nguội và sữa. Trộn cho đến khi mịn.', NULL, '2026-05-15 14:55:13', '2026-05-15 14:55:13'),
(4529, 679, 4, 'Trải hỗn hợp vào khuôn bánh và nướng trong 50-55 phút hoặc cho đến khi cứng ở giữa và xiên que ra sạch sẽ. Để nguội trong 10 phút, sau đó tắt và nguội hoàn toàn.', NULL, '2026-05-15 14:55:13', '2026-05-15 14:55:13'),
(4530, 680, 1, 'Làm nóng lò nướng ở mức quạt/khí 180C/160C 4. Lót giấy nướng vào khay nướng 20 x 30cm. Cho sô cô la, bơ và đường vào chảo và đun chảy nhẹ nhàng, thỉnh thoảng khuấy bằng thìa gỗ. Hủy bỏ khỏi nhiệt.', NULL, '2026-05-15 14:55:13', '2026-05-15 14:55:13'),
(4531, 680, 2, 'Khuấy từng quả trứng vào hỗn hợp sô cô la tan chảy. Rây bột mì và ca cao rồi khuấy đều. Khuấy một nửa quả mâm xôi, cạo vào khay, sau đó rải lên số quả mâm xôi còn lại. Nướng trên kệ giữa trong 30 phút hoặc nếu bạn thích kết cấu chắc hơn thì nướng thêm 5 phút. Làm nguội trước khi cắt thành hình vuông. Bảo quản trong hộp kín tối đa 3 ngày.', NULL, '2026-05-15 14:55:13', '2026-05-15 14:55:13'),
(4532, 681, 1, 'Làm nóng lò nướng ở mức 220C/quạt 200C/gas 7 và đặt khay nướng lên kệ trên cùng. Đối với nước sốt, đun nóng kem và đường cho đến khi sôi. Tắt bếp, cho sô cô la và bơ vào khuấy đều cho đến khi tan chảy rồi giữ ấm.', NULL, '2026-05-15 14:55:14', '2026-05-15 14:55:14'),
(4533, 681, 2, 'Quét 6 x 150ml ramekins bằng bơ tan chảy, rắc 2 muỗng canh đường bột, sau đó loại bỏ phần thừa. Đun chảy sô-cô-la và kem trong tô trên chảo nước sôi, để nguội rồi trộn với lòng đỏ trứng. Đánh lòng trắng trứng cho đến khi giữ được hình dạng, sau đó thêm đường, mỗi lần 1 muỗng canh, đánh lại để có độ đặc như cũ. Trộn một thìa vào sô-cô-la, sau đó nhẹ nhàng trộn phần còn lại vào.', NULL, '2026-05-15 14:55:14', '2026-05-15 14:55:14'),
(4534, 681, 3, 'Làm việc nhanh chóng, đổ đầy khuôn ramekins, lau sạch vành và chạy ngón tay cái quanh các cạnh. Giảm nhiệt độ lò xuống 200C/quạt 180C/gas 6, đặt ramekins lên khay nướng, sau đó nướng trong 8-10 phút cho đến khi bánh đứng dậy và hơi lắc lư. Không mở cửa lò quá sớm vì có thể làm cửa lò bị sập.', NULL, '2026-05-15 14:55:14', '2026-05-15 14:55:14'),
(4535, 681, 4, 'Sau khi bánh soufflé đã sẵn sàng, hãy rắc đường bột, khoét một lỗ nhỏ trên bề mặt bánh, sau đó đổ một ít nước sốt sô cô la nóng vào. Đậy nắp lại và dùng ngay.', NULL, '2026-05-15 14:55:14', '2026-05-15 14:55:14'),
(4536, 682, 1, 'Làm nóng lò ở 160C/quạt 140C/gas 3. Lót đáy và các cạnh của khuôn bánh tròn 20 cm, sâu 7,5 cm. Đánh bơ và đường bằng máy trộn cầm tay điện trong 1-2 phút cho đến khi có màu kem và nhạt, cạo dọc thành bát nửa chừng. Khuấy một thìa bột mì, sau đó lần lượt cho trứng đã đánh và phần bột còn lại vào, mỗi lần một phần tư, dùng thìa gỗ đánh đều. Khuấy hạnh nhân.', NULL, '2026-05-15 14:55:17', '2026-05-15 14:55:17'),
(4537, 682, 2, 'Trộn rượu sherry (hỗn hợp sẽ trông như vón cục), sau đó thêm vỏ, quả anh đào, nho khô, quả anh đào, các loại hạt, vỏ chanh, gia vị, nước hoa hồng và vani. Đánh đều cho hòa quyện rồi cho bột nở vào trộn đều.', NULL, '2026-05-15 14:55:17', '2026-05-15 14:55:17'),
(4538, 682, 3, 'Múc hỗn hợp vào khuôn và làm phẳng phần trên, tạo một vết lõm nhẹ ở giữa. Nướng trong 30 phút, sau đó giảm nhiệt độ xuống 150C/quạt 130C/gas 2 và nướng thêm 2-2¼ giờ, cho đến khi xiên que vào giữa xiên ra sạch sẽ. Để nguội trong hộp thiếc rồi lấy ra khỏi hộp, bóc lớp giấy lót. Khi nguội hoàn toàn, bọc kỹ trong màng bám và giấy bạc để bảo quản cho đến khi sẵn sàng trang trí. Bánh sẽ giữ được vài tháng.', NULL, '2026-05-15 14:55:17', '2026-05-15 14:55:17'),
(4539, 683, 1, 'Làm nóng lò ở 180°C/quạt 160°C/mã gas 4 rồi bôi mỡ và lót khuôn 25 cm x 20 cm. Đun chảy bơ, đường, xi-rô và vỏ cam trong chảo lớn trên lửa vừa. Mục đích là để hòa tan tất cả các thành phần sao cho chúng mịn, nhưng không bị mất thể tích khi đun sôi, vì vậy hãy cẩn thận không để quá nóng.', NULL, '2026-05-15 14:55:18', '2026-05-15 14:55:18'),
(4540, 683, 2, 'Thêm yến mạch và khuấy đều cho đến khi được phủ đều. Khuấy phần bánh pudding Giáng sinh còn sót lại và đổ vào hộp thiếc đã chuẩn bị sẵn. Dùng thìa cán phẳng mặt trên và nướng trong 40 phút cho đến khi các cạnh bắt đầu chuyển sang màu nâu. Trong khi vẫn còn ấm trong hộp thiếc, hãy chia thành 12 ô vuông. Để nguội hoàn toàn trước khi cắt dọc theo điểm số.', NULL, '2026-05-15 14:55:18', '2026-05-15 14:55:18'),
(4541, 683, 3, 'Bảo quản trong hộp kín 5 ngày hoặc để đông trong 1 tháng.', NULL, '2026-05-15 14:55:18', '2026-05-15 14:55:18'),
(4542, 684, 1, 'Dùng dao gọt vỏ cam, đảm bảo loại bỏ hết phần cùi. Cắt càng mỏng càng tốt và bày lên đĩa ăn tối. Rắc đường demerara, sau đó là Grand Marnier và đặt sang một bên.', NULL, '2026-05-15 14:55:19', '2026-05-15 14:55:19'),
(4543, 684, 2, 'Nghiền bánh pudding Giáng sinh thành từng miếng lớn và rải dưới đáy một chiếc bát nhỏ. Xếp từng lớp cam lên bánh pudding và đổ nước ép lên trên.', NULL, '2026-05-15 14:55:19', '2026-05-15 14:55:19'),
(4544, 684, 3, 'Đánh mascarpone cho đến khi mịn, sau đó cho sữa trứng vào khuấy đều. Đổ hỗn hợp lên trên những quả cam.', NULL, '2026-05-15 14:55:19', '2026-05-15 14:55:19'),
(4545, 684, 4, 'Đánh nhẹ kem và dùng thìa phủ lên sữa trứng. Rắc hạnh nhân và sô-cô-la bào lên trên. Bạn có thể làm món này trước một ngày nếu thích, thư giãn cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:55:19', '2026-05-15 14:55:19'),
(4547, 685, 1, 'Đun sôi ấm, sau đó đo 300ml nước sôi cho vào bình rồi cho bơ tan chảy và chiết xuất vani vào. Rây bột mì và bột nở vào tô trộn lớn cùng với một chút muối lớn. Tạo một cái giếng ở giữa, sau đó đổ lượng chứa trong bình vào và dùng thìa gỗ đánh thật nhanh vào bột cho đến khi không còn vón cục. Nghỉ khoảng 10-15 phút trong lúc làm nước sốt.', NULL, '2026-05-15 14:55:20', '2026-05-16 12:35:35'),
(4549, 685, 2, 'Cho tất cả nguyên liệu làm nước sốt vào chảo và đun chảy nhẹ nhàng với nhau, thỉnh thoảng khuấy đều cho đến khi có được nước sốt mịn bóng. Giữ ấm ở nhiệt độ thấp.', NULL, '2026-05-15 14:55:20', '2026-05-16 12:35:35'),
(4551, 685, 3, 'Đổ đầy một cái chảo sâu lòng lớn vào một phần ba dầu. Nấu bằng dầu nóng có thể nguy hiểm – trước khi bắt đầu, hãy đọc cách chiên ngập dầu an toàn để tránh tai nạn trong nhà bếp. Đun nóng cho đến khi một khối bánh mì có màu nâu trong vòng 45 giây đến 1 phút. Đậy khay bằng giấy ăn và trộn đường bột và quế với nhau.', NULL, '2026-05-15 14:55:20', '2026-05-16 12:35:35'),
(4553, 685, 4, 'Lắp đầu hút hình sao vào túi bắt kem – rộng 1,5-2cm là kích thước phù hợp. Đổ đầy bột đã nghỉ, sau đó đổ trực tiếp 2-3 dải bột vào chảo, dùng kéo nhà bếp cắt từng dải bột. Chiên cho đến khi vàng nâu và giòn. Hãy hết sức cẩn thận ở đây – nếu bọt khí hình thành trong bánh churros, chúng có thể nổ tung, đặc biệt nếu dầu quá nóng hoặc bạn sử dụng bột mì cũ. Nấu bằng dầu nóng có thể nguy hiểm – trước khi bắt đầu, hãy đọc cách chiên ngập dầu an toàn để tránh tai nạn trong nhà bếp. Giữ trẻ em không vào bếp và tự bảo vệ mình bằng cách mặc áo dài tay, đeo kính bảo vệ mắt và tránh để mặt bạn chạm vào chảo.', NULL, '2026-05-15 14:55:20', '2026-05-16 12:35:35'),
(4555, 685, 5, 'Khi bánh churros đã giòn và có màu nâu vàng, dùng thìa có rãnh vớt chúng ra khỏi dầu và để ráo trên khay có lót giấy nhà bếp. Tiếp tục nấu phần bột còn lại theo từng đợt, rắc một ít đường quế lên bánh churros đã nấu chín. Khi bạn đã nấu xong tất cả các món churros, trộn với lượng đường quế còn lại và dùng kèm với sốt sô cô la để chấm.', NULL, '2026-05-15 14:55:20', '2026-05-16 12:35:35'),
(4556, 685, 6, 'Để xem video về cách chuẩn bị bánh churros, hãy xem công thức làm bánh mì kẹp kem churros của chúng tôi.', NULL, '2026-05-15 14:55:20', '2026-05-16 12:35:35'),
(4557, 686, 1, 'Trong một cái chảo nhỏ, đun nóng bơ, sữa và muối cho đến khi bơ tan chảy. Để hỗn hợp nguội cho đến khi còn âm ấm.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4558, 686, 2, 'Trong một tô lớn, khuấy đều bột mì, men, bạch đậu khấu và đường cho đến khi hòa quyện.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4559, 686, 3, 'Tạo một cái giếng ở giữa và đập trứng vào. Đổ hỗn hợp sữa ấm vào và khuấy đều mọi thứ lại với nhau để tạo thành một khối bột dính. Bạn có thể phải dùng tay khi bột trở nên cứng hơn.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4560, 686, 4, 'Bôi dầu lên bề mặt làm việc bằng một thìa cà phê dầu ô liu. Lật bột lên bề mặt đã phết dầu và nhào mạnh trong 5–8 phút, dùng nạo nhựa nếu cần để gạt bột ra khỏi bề mặt làm việc. Đừng cố thêm bột mì vì điều này sẽ làm cho bánh bị khô và dai. Tiếp tục nhào cho đến khi bột bớt dính, mịn và đàn hồi hơn đáng kể.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4561, 686, 5, 'Tạo thành một quả bóng và cho vào một cái tô lớn đã bôi mỡ. Đậy bát bằng một chiếc khăn trà sạch và đặt ở nơi ấm áp để ủ trong một giờ hoặc cho đến khi kích thước tăng gấp đôi.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4562, 686, 6, 'Trong khi đó, để làm nhân và phủ, trộn bơ đã làm mềm vào tô với một nửa lượng đường và 1 thìa quế. Dùng nĩa trộn đường và gia vị vào bơ cho đến khi hòa quyện hoàn toàn.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4563, 686, 7, 'Trộn phần đường và quế còn lại vào một bát riêng rồi đặt sang một bên.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4564, 686, 8, 'Khi bột đã nổi lên, đặt lên bề mặt đã rắc bột mì và nhẹ nhàng cán thành hình chữ nhật có kích thước 36x24cm/14x9½in. Trải đều quế-đường-bơ lên ​​bột bằng bàn hoặc dao pha màu.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4565, 686, 9, 'Với cạnh dài nhất gần bạn nhất, cuộn bột thành hình trụ. Cắt thành 12 lát đều nhau.', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4566, 686, 10, 'Đặt từng lát lên hộp đựng bánh cupcake bằng giấy dẹt trên khay nướng hoặc vào khuôn làm bánh nướng xốp đã phết mỡ. (Nướng trong khuôn làm bánh nướng xốp sẽ làm cho bánh quế của bạn cao hơn và có hình vòm.)', NULL, '2026-05-15 14:55:21', '2026-05-15 14:55:21'),
(4567, 686, 11, 'Che lại bằng một chiếc khăn trà sạch và đặt sang một bên để ủ lại trong 30–45 phút hoặc cho đến khi nổi lên.', NULL, '2026-05-15 14:55:22', '2026-05-15 14:55:22'),
(4568, 686, 12, 'Làm nóng lò ở mức quạt/gas 200C/180C 6.', NULL, '2026-05-15 14:55:22', '2026-05-15 14:55:22'),
(4569, 686, 13, 'Quét trứng đánh lên mặt bánh và rắc đường quế lên mặt bánh. Nướng trong 12 phút cho đến khi bánh có màu nâu vàng đậm. Thưởng thức ấm áp với một tách cà phê.', NULL, '2026-05-15 14:55:22', '2026-05-15 14:55:22'),
(4570, 687, 1, 'Chuẩn bị mọi thứ cho món bánh pudding. Hạnh nhân cắt nhỏ. Gọt vỏ, bỏ lõi và cắt nhỏ táo nấu ăn. Làm sắc nét con dao của bạn và cắt vỏ kẹo. (Bạn có thể cắt hạnh nhân và táo trong máy xay thực phẩm, nhưng vỏ phải được thực hiện bằng tay.) Nghiền 3/4 số hạt nhục đậu khấu (nghe có vẻ nhiều nhưng chính xác là như vậy).', NULL, '2026-05-15 14:55:23', '2026-05-15 14:55:23'),
(4571, 687, 2, 'Trộn hạnh nhân, táo, vỏ kẹo, nhục đậu khấu, nho khô, bột mì, vụn bánh mì, đường muscovado nhẹ, trứng và 2 muỗng canh rượu mạnh hoặc rượu cognac trong một tô lớn.', NULL, '2026-05-15 14:55:23', '2026-05-15 14:55:23'),
(4572, 687, 3, 'Giữ bơ trong vỏ bọc, bào một phần tư bơ vào tô, sau đó khuấy mọi thứ lại với nhau. Lặp lại cho đến khi tất cả bơ được nghiền mịn, sau đó khuấy trong 3-4 phút – hỗn hợp đã sẵn sàng khi nó lắng xuống một chút sau mỗi lần khuấy. Yêu cầu cả nhà khuấy đều và kêu gọi mọi người cùng ước.', NULL, '2026-05-15 14:55:23', '2026-05-15 14:55:23'),
(4573, 687, 4, 'Thoa đều bơ vào hai tô 1,2 lít và lót một vòng giấy nướng bánh vào đáy mỗi tô. Gói trong hỗn hợp bánh pudding. Phủ hai lớp giấy nướng, xếp nếp để giãn nở, sau đó buộc bằng dây (giữ tờ giấy cố định bằng dây chun trong khi buộc). Cắt bỏ phần giấy thừa.', NULL, '2026-05-15 14:55:23', '2026-05-15 14:55:23'),
(4574, 687, 5, 'Bây giờ, đặt mỗi chiếc bát lên một tờ giấy bạc lớn và úp các cạnh lên trên, sau đó đặt một tờ giấy bạc khác lên trên và úp xuống bên dưới để tạo thành một gói đôi (điều này làm cho bánh pudding không bị thấm nước). Buộc thêm dây và làm tay cầm để dễ dàng nhấc vào và lấy ra khỏi chảo. Hãy xem video của chúng tôi để biết cách buộc bánh pudding đúng cách.', NULL, '2026-05-15 14:55:23', '2026-05-15 14:55:23'),
(4575, 687, 6, 'Đun sôi hoặc hấp bánh pudding trong 8 giờ, thêm nước nếu cần. Lấy ra khỏi chảo và để nguội qua đêm. Khi nguội, loại bỏ lớp giấy gói lộn xộn và bọc lại bằng giấy nướng, giấy bạc và dây mới. Bảo quản ở nơi khô ráo, thoáng mát cho đến Giáng sinh.', NULL, '2026-05-15 14:55:23', '2026-05-15 14:55:23'),
(4576, 687, 7, 'Để làm bơ brandy, đánh bơ với vỏ cam và đường bột. Đổ dần dần rượu mạnh hoặc rượu cognac và gừng cắt nhỏ vào. Cho vào tô nhỏ, nĩa đẹp mắt rồi cho vào tủ lạnh để định hình. Bơ sẽ giữ được một tuần trong tủ lạnh hoặc có thể đông lạnh đến sáu tuần.', NULL, '2026-05-15 14:55:23', '2026-05-15 14:55:23'),
(4577, 687, 8, 'Vào ngày Giáng sinh, đun sôi hoặc hấp trong lò trong 1 giờ. Mở gói và bật ra. Để đốt lửa, làm ấm 3-4 muỗng canh rượu mạnh trong chảo nhỏ, đổ lên bánh pudding và đốt lửa.', NULL, '2026-05-15 14:55:23', '2026-05-15 14:55:23'),
(4578, 688, 1, 'Làm nóng lò ở nhiệt độ 300 độ F (150 độ C). Lót một tấm nướng bằng giấy da. Trải hạnh nhân lên khay nướng.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4579, 688, 2, 'Nướng trong lò làm nóng trước cho đến khi hạnh nhân thơm và rang, khoảng 20 đến 25 phút.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4580, 688, 3, 'Chuẩn bị bột làm bánh ngọt trong khi rang hạnh nhân. Trộn bột mì, 1/2 cốc cộng với 1 thìa bơ và muối vào tô rồi chà xát với nhau cho đến khi hỗn hợp giống như vụn bánh mì. Thêm trứng, dầu và 1 1/2 thìa nước hoa cam; nhào tất cả mọi thứ thành một khối bột bánh ngọt mịn. Thêm một ít nước, mỗi lần 1 thìa cà phê, nếu bột quá khô. Nặn bột bánh ngọt thành một quả bóng, bọc trong màng bọc thực phẩm và để yên trong 30 phút.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4581, 688, 4, 'Lấy hạnh nhân ra khỏi lò và để nguội một chút, khoảng 5 phút. Cho hạnh nhân vào tô của máy xay thực phẩm; xử lý cho đến khi được nghiền mịn và đồng đều. Thêm 3/4 cốc cộng với 1 thìa đường, quế, trứng và 1 thìa nước hoa cam vào máy xay thực phẩm, xay sau mỗi lần thêm cho đến khi hỗn hợp được kết hợp đồng đều và giống như một hỗn hợp sệt.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4582, 688, 5, 'Loại bỏ những phần nhân nhỏ cỡ quả óc chó bằng tay đã bôi mỡ. Cuộn chúng thành những khúc gỗ nhỏ có đầu mỏng. Đặt sang một bên.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4583, 688, 6, 'Làm nóng lò ở nhiệt độ 325 độ F (165 độ C). Lót một tấm nướng bằng giấy da.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4584, 688, 7, 'Cán một nửa số bột bánh ngọt trên bề mặt đã rắc chút bột mì cho đến khi thật mỏng. Đặt một trong những miếng bột hạnh nhân lên mép bánh ngọt, gấp bánh ngọt lên trên phần nhân, phủ kín hoàn toàn và bịt kín các mép. Dùng ngón tay nặn thành hình lưỡi liềm. Dùng dao cắt bánh ngọt, cắt xung quanh hình lưỡi liềm và chuyển sang khay nướng đã chuẩn bị sẵn. Lặp lại với phần bột và nhân còn lại.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4585, 688, 8, 'Nướng trong lò làm nóng trước cho đến khi sừng linh dương có màu vàng nhạt và nướng trong khoảng 20 phút. Chúng không nên quá tối. Để nguội một chút, khoảng 3 phút.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4586, 688, 9, 'Đun nóng mật ong trong chảo nhỏ trên lửa vừa và nhỏ. Tắt bếp và khuấy đều với 1 thìa nước hoa cam. Nhúng sừng linh dương vào mật ong và đặt lên đĩa phục vụ. Rắc quả hồ trăn nghiền nát.', NULL, '2026-05-15 14:55:24', '2026-05-15 14:55:24'),
(4587, 689, 1, 'Làm nóng lò ở nhiệt độ 350°F (180°C). Bôi mỡ vào chảo nướng hình vuông 8 inch (20 cm).', NULL, '2026-05-15 14:55:25', '2026-05-15 14:55:25'),
(4588, 689, 2, 'Để làm ngày tháng: Cho chà là và nước vào nồi vừa trên lửa cao và đun sôi. Giảm nhiệt xuống thấp và đun nhỏ lửa, thỉnh thoảng khuấy cho đến khi hỗn hợp đặc lại, khoảng 6 đến 8 phút. Tắt bếp, cho vani vào khuấy đều và để nguội. Đặt sang một bên.', NULL, '2026-05-15 14:55:25', '2026-05-15 14:55:25'),
(4589, 689, 3, 'Kết hợp yến mạch cán, bột mì, đường, baking soda và muối trong máy xay thực phẩm. Xung 3 lần (cẩn thận không trộn quá kỹ, không muốn hỗn hợp bị nhão mà chỉ hòa quyện thôi). Thêm bơ và xay lại cho đến khi hỗn hợp vụn thành từng cục cỡ hạt đậu. Chuyển sang tô trộn để trộn đều bơ.', NULL, '2026-05-15 14:55:25', '2026-05-15 14:55:25'),
(4590, 689, 4, 'Rải một nửa hỗn hợp yến mạch xuống đáy chảo nướng đã chuẩn bị sẵn, sau đó ấn xuống để tạo thành đáy phẳng, bằng phẳng. Thêm hỗn hợp chà là lên trên lớp vỏ và sau đó trải đều. Phủ hỗn hợp yến mạch còn lại lên và ấn xuống để làm phẳng lớp trên cùng.', NULL, '2026-05-15 14:55:25', '2026-05-15 14:55:25'),
(4591, 689, 5, 'Nướng ở giữa lò cho đến khi mặt trên có màu vàng nâu, từ 30 đến 35 phút. Để nguội hoàn toàn trong chảo trước khi cắt và phục vụ. Hình vuông chà là được bảo quản tốt, đậy kín trong tủ lạnh tối đa một tuần và đông lạnh từ 2 đến 3 tháng.', NULL, '2026-05-15 14:55:25', '2026-05-15 14:55:25'),
(4592, 690, 1, 'Cho hạnh nhân vào một cái bát nhỏ và đổ nước sôi vừa đủ. Để trong 5 phút rồi lọc qua rây và để khô.', NULL, '2026-05-15 14:55:28', '2026-05-15 14:55:28'),
(4593, 690, 2, 'Làm nóng lò nướng ở nhiệt độ 180C/160 C quạt/Mã gas 4. Lót giấy nướng vào khuôn bánh có đáy rộng 20cm có đáy sâu.', NULL, '2026-05-15 14:55:28', '2026-05-15 14:55:28'),
(4594, 690, 3, 'Cho bơ vào tô lớn và đánh đều cho đến khi mềm. Thêm đường và đánh cho đến khi nhẹ và mịn. Khuấy vỏ cam và mứt mơ.', NULL, '2026-05-15 14:55:28', '2026-05-15 14:55:28'),
(4595, 690, 4, 'Rây bột mì và bột nở lại với nhau. Thêm từng quả trứng vào bơ kem và đường, đánh đều sau mỗi lần thêm. Nếu hỗn hợp bắt đầu đông lại, hãy thêm một ít bột mì vào.', NULL, '2026-05-15 14:55:28', '2026-05-15 14:55:28'),
(4596, 690, 5, 'Thêm bột mì còn lại và hạnh nhân xay vào, trộn đều. Trộn sữa vào sau đó cho hoa quả khô và quả anh đào vào trộn nhẹ nhàng.', NULL, '2026-05-15 14:55:28', '2026-05-15 14:55:28'),
(4597, 690, 6, 'Múc hỗn hợp vào khuôn đã chuẩn bị sẵn và dàn đều bằng mặt sau của thìa. Xếp các quả hạnh nhân gần nhau thành vòng tròn gọn gàng trên mặt bánh. Nướng trong lò trong 45 phút.', NULL, '2026-05-15 14:55:28', '2026-05-15 14:55:28'),
(4598, 690, 7, 'Hạ nhiệt độ lò xuống 160C/140 C quạt/Gas Mark 3 và nấu thêm 60–80 phút nữa. Kiểm tra bánh sau 50 phút bằng cách dùng que xiên bằng gỗ hoặc kim loại đâm vào bánh. Khi hoàn thành, nó chỉ còn lại một vài mẩu vụn. Kiểm tra 10 phút một lần - điều quan trọng là không nên nấu quá chín chiếc bánh này vì phần giữa sẽ hơi mềm.', NULL, '2026-05-15 14:55:28', '2026-05-15 14:55:28'),
(4599, 690, 8, 'Khi bánh chín, lấy bánh ra khỏi lò một thời gian ngắn, cho sữa và đường vào chảo nhỏ, đun nóng nhẹ cho đến khi đường tan. Quét lên mặt bánh và cho bánh vào lò nướng trong 2-3 phút. Lấy ra và để bánh nguội trong khuôn. Khi bánh khá nguội, lấy ra khỏi hộp thiếc, bọc trong giấy bạc và để ít nhất 2 ngày trước khi cắt.', NULL, '2026-05-15 14:55:28', '2026-05-15 14:55:28'),
(4600, 691, 1, 'Cho bột mì, 150 g đường, chút muối và 1 lòng đỏ trứng vào tô máy xay thực phẩm. Cắt bơ thành khối nhỏ và thêm vào bát. Biến nó thành một khối bột cứng. Đừng chế biến quá kỹ, bạn sẽ không muốn bột bị nóng. Kiểm tra xem nó có dính hay không bằng cách kẹp nó giữa các ngón tay của bạn.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4601, 691, 2, 'Biến thành một miếng bọc nhựa. Dùng tay tạo thành một quả bóng tròn và cuộn nó vào trong nhựa. Cho vào tủ lạnh nửa tiếng cho nguội.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4602, 691, 3, 'Lấy một khuôn nướng tròn có đường kính 22 cm và phủ giấy nướng lên trên. Chải các mặt bằng bơ.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4603, 691, 4, 'Làm nóng lò ở nhiệt độ 170˚C (340˚F)', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4604, 691, 5, 'Cắt táo thành khối vuông và trộn với nho khô, lượng đường còn sót lại và quế.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4605, 691, 6, 'Đặt khối bột đã nguội lên một mặt phẳng có rắc bột mì rồi cán thành tấm mỏng. Đặt cái này vào khay nướng và đậy kín đáy và các mặt. Tôi thường chỉ ấn nó vào hộp thiếc mà không lăn nó ra. Mình thấy đó là cách dễ nhất nhưng nó kém mượt mà hơn. Chỉ cần làm bất cứ điều gì có ích cho bạn.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4606, 691, 7, 'Hãy chắc chắn rằng bạn giữ riêng 1/4 khối bột để tạo thành các dải ở trên.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4607, 691, 8, 'Khi phần dưới và các mặt đã được phủ bột, hãy lấy những chiếc bánh quy và vò nát chúng ở phía dưới. Bạn cũng có thể sử dụng breadcrumbs cho việc này. Lắc nó một chút để nó được chia đều ở phía dưới.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4608, 691, 9, 'Thêm hỗn hợp táo và chia đều trên hộp thiếc. Cán phần bột còn lại và cắt thành dải. Đặt nó lên trên mặt bánh theo hình kim cương. Quét các đường và các mặt bằng lòng đỏ trứng còn lại rồi cho vào lò nướng đã làm nóng trước.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4609, 691, 10, 'Nướng bánh táo trong khoảng 1 giờ hoặc cho đến khi chín vàng. Để nguội trong hộp thiếc và đảm bảo các cạnh được lỏng ra trước khi mở hộp thiếc.', NULL, '2026-05-15 14:55:29', '2026-05-15 14:55:29'),
(4610, 692, 1, 'Cho bột vào tô lớn rồi thêm men và đường. Nếu sữa lạnh, hãy đảm bảo đun nóng đến mức ấm. Trộn từng chút hỗn hợp bột với sữa cho đến khi thu được hỗn hợp bột mịn. Thêm muối và trộn bằng thìa gỗ cho đến khi bột mịn và lỏng.', NULL, '2026-05-15 14:55:30', '2026-05-15 14:55:30'),
(4611, 692, 2, 'Đậy lại bằng một chiếc khăn trà sạch và để ở nơi ấm áp trong khoảng một giờ cho bột nở.', NULL, '2026-05-15 14:55:30', '2026-05-15 14:55:30'),
(4612, 692, 3, 'Đun nóng nồi chiên sâu hoặc thêm dầu vào nồi lớn. Dầu phải ở nhiệt độ 180˚C (350˚F) để có kết quả tốt nhất.', NULL, '2026-05-15 14:55:30', '2026-05-15 14:55:30'),
(4613, 692, 4, 'Trước khi bắt đầu khuấy đều bột và múc bột bằng hai thìa hoặc thìa kem. Hãy để nó thả vào dầu một cách cẩn thận. Cách dễ nhất để làm điều này là bạn nhúng thìa hoặc múc vào dầu trước khi nhúng vào bột. Bằng cách đó nó sẽ trượt thìa dễ dàng. Đừng để chảo chiên quá đông để tránh dầu nguội quá nhanh và mọi thứ dính vào nhau. Khi một mặt có màu nâu vàng, nó thường tự động quay sang mặt còn lại. Nếu không giúp nó cùng với hai nĩa.', NULL, '2026-05-15 14:55:30', '2026-05-15 14:55:30'),
(4614, 692, 5, 'Lấy những quả bóng ra khi đã có màu vàng nâu và để ráo nước trên một tờ giấy ăn.', NULL, '2026-05-15 14:55:30', '2026-05-15 14:55:30'),
(4615, 693, 1, 'Làm nóng lò ở 160˚C (320˚F) Lót giấy nến vào khay bánh và đặt sang một bên.', NULL, '2026-05-15 14:55:31', '2026-05-15 14:55:31'),
(4616, 693, 2, 'Trộn tất cả nguyên liệu khô với nhau trong một tô lớn. Cho sữa vào nồi nhỏ và đun nóng cho đến khi gần sôi nhưng chưa sôi hẳn.', NULL, '2026-05-15 14:55:31', '2026-05-15 14:55:31'),
(4617, 693, 3, 'Đổ sữa từ từ vào nguyên liệu khô trong khi đánh. Đừng trộn quá nhiều! Ngay sau khi nó được kết hợp thành một khối bột mịn, bạn đổ nó vào chảo bánh. Rắc đường trân châu lên trên và nướng trong lò khoảng 1 giờ.', NULL, '2026-05-15 14:55:31', '2026-05-15 14:55:31'),
(4618, 693, 4, 'Kiểm tra sau khoảng 50 phút bánh đang tiến triển như thế nào. Nếu người thử bánh bước ra làm sạch bánh đã chín. Nếu không hãy để nó nấu lâu hơn một chút.', NULL, '2026-05-15 14:55:31', '2026-05-15 14:55:31'),
(4619, 694, 1, 'Kết hợp sữa và men trong một cái bát. Để yên một lúc cho men tan hết.', NULL, '2026-05-15 14:55:33', '2026-05-15 14:55:33'),
(4620, 694, 2, 'Trong một tô khác, trộn bột mì, bơ, đường, trứng và muối. Đổ hỗn hợp men vào và nhào cho đến khi mịn. Đậy bát và để bột nở trong một giờ.', NULL, '2026-05-15 14:55:33', '2026-05-15 14:55:33'),
(4621, 694, 3, 'Khi bột gần như đã sẵn sàng, hãy làm nhân bánh. Cho tất cả nguyên liệu vào nồi và khuấy đều cho đến khi bơ tan chảy và đường tan. Hãy để nó sôi một lúc. Chất Stroop sẽ tiếp tục dày lên khi nó nguội đi.', NULL, '2026-05-15 14:55:33', '2026-05-15 14:55:33'),
(4622, 694, 4, 'Nặn bột thành từng viên nặng khoảng 35g. Tổng cộng là 14. Bật bàn ủi Stroopwafel của bạn ở cài đặt cao nhất.', NULL, '2026-05-15 14:55:33', '2026-05-15 14:55:33'),
(4623, 694, 5, 'Đặt một viên bột vào bàn ủi và đóng bàn ủi lại. Đừng làm phẳng bánh quế quá nhiều; bạn vẫn có thể vượt qua nó. Nướng trong 1-2 phút cho đến khi bánh quế có màu vàng nâu đẹp mắt.', NULL, '2026-05-15 14:55:33', '2026-05-15 14:55:33'),
(4624, 694, 6, 'Khi bánh quế đã xong, hãy làm việc nhanh chóng. Lấy bánh quế ra khỏi bàn ủi và ngay lập tức dùng dao cắt tròn cắt ra một hình tròn đẹp có đường kính khoảng 8 đến 9 cm (3 đến 3,5 inch).', NULL, '2026-05-15 14:55:33', '2026-05-15 14:55:33'),
(4625, 694, 7, 'Đặt bánh quế nóng lên thớt và dùng dao sắc cắt theo chiều ngang. Stroopwafel rất nóng nên hãy dùng găng tay lò nướng để giữ cố định.', NULL, '2026-05-15 14:55:33', '2026-05-15 14:55:33'),
(4626, 694, 8, 'Lấy một nửa chiếc bánh quế và phết nước sốt (nóng!) lên đó. Đặt nửa còn lại lên trên, ấn nhẹ nếu cần và đặt bánh quế lên giá lưới để nguội. Lặp lại cho tất cả các quả bóng.', NULL, '2026-05-15 14:55:33', '2026-05-15 14:55:33'),
(4627, 695, 1, 'Chuẩn bị hạnh nhân vào ngày hôm trước. Đun sôi 6 cốc nước. Tắt bếp và thêm hạnh nhân vào. Hạnh nhân ngâm trong nước khoảng 5 phút rồi vớt ra để ráo nước. Trải hạnh nhân lên khay nướng và nướng ở nhiệt độ 200 độ F (95 độ C) cho đến khi khô hoàn toàn và nướng. Việc này mất vài giờ và cần được chuẩn bị trước. Hãy cẩn thận để không làm cháy các loại hạt vì điều này sẽ tạo ra vị đắng cho nhân.', NULL, '2026-05-15 14:55:34', '2026-05-15 14:55:34'),
(4628, 695, 2, 'Cho 1 cốc đường và 1 cốc nước vào nồi, đun sôi. Thêm 1 thìa cà phê nước cốt chanh, giảm nhiệt xuống thấp và đun nhỏ lửa cho đến khi có dạng siro, khoảng 30 đến 40 phút. Khuấy nước hoa cam và tắt bếp. Đặt xi-rô đường sang một bên.', NULL, '2026-05-15 14:55:34', '2026-05-15 14:55:34'),
(4629, 695, 3, 'Trộn bột mì và muối vào một tô trộn lớn. Tạo một lỗ ở giữa rồi đổ dầu, trứng, 1/2 thìa nước cốt chanh và 1 thìa nước hoa cam vào giữa. Trộn bằng ngón tay cho đến khi bột giống như vụn thô. Dần dần rắc nước ấm trong khi trộn cho đến khi bột trở nên mềm và dẻo. Chia thành 4 phần bằng nhau. Che bột bằng một miếng vải ướt và đặt sang một bên.', NULL, '2026-05-15 14:55:34', '2026-05-15 14:55:34'),
(4630, 695, 4, 'Trong máy xay thực phẩm, nghiền mịn hạnh nhân. Đong 3 cốc hạnh nhân nghiền mịn cho vào tô trộn, khuấy đều với 1 cốc đường, bột nở, bột vani, vỏ chanh và 2 thìa nước hoa cam. Trộn lần lượt ba quả trứng vào, khuấy liên tục; trộn cho đến khi bạn có được một hỗn hợp dính, giống như bột nhão.', NULL, '2026-05-15 14:55:34', '2026-05-15 14:55:34'),
(4631, 695, 5, 'Rắc bột ngô lên mặt cán để chống dính. Cán từng phần bột thật mỏng, từ 1 đến 2 mm (1/16 inch). Cắt bột đã cán thành các hình tròn có đường kính khoảng 10 cm (4 inch). Lau nhẹ bề mặt của từng hình tròn bằng bột ngô rồi cho vào khuôn bánh tart, úp mặt bột ngô xuống để chống dính. Nhẹ nhàng ấn bột vào các cạnh và đáy khuôn, đồng thời cắt bớt phần bột thừa ở xung quanh viền. Đổ nhân hạnh nhân vào 3/4 mỗi khuôn.', NULL, '2026-05-15 14:55:34', '2026-05-15 14:55:34'),
(4632, 695, 6, 'Nướng trên kệ trên cùng ở nhiệt độ 350 độ F (175 độ C) trong 20 đến 25 phút hoặc cho đến khi bề mặt bánh vàng và bột cứng. Lấy bánh tart ra khỏi khuôn ngay khi chúng ra khỏi lò. Nhúng từng chiếc bánh tart vào nước đường khi còn nóng. Dán một hạt thông vào giữa mỗi chiếc bánh để trang trí. Đặt trên giá lưới cho ráo nước.', NULL, '2026-05-15 14:55:34', '2026-05-15 14:55:34'),
(4633, 696, 1, 'Để làm bánh ngọt, hãy cắt bơ thành hạt lựu và cho vào ngăn đá tủ lạnh cho thật cứng. Đổ bột mì vào tô của máy xay thực phẩm cùng với một nửa bơ và xay theo kết cấu vụn bánh mì. Đổ nước cốt chanh và 100ml nước đá vào, trộn đều thành khối. Đổ phần bơ còn lại vào và đập vài lần cho đến khi bột dính nhiều bơ. Điều quan trọng là bạn không nên lạm dụng quá nhiều vì những hạt bơ chính là nguyên nhân khiến bánh bị bong tróc.', NULL, '2026-05-15 14:55:36', '2026-05-15 14:55:36'),
(4634, 696, 2, 'Trên bề mặt đã phủ bột mì, cán bánh thành hình chữ nhật gọn gàng có kích thước khoảng 20 x 30cm. Gấp 2 đầu bánh vào giữa (xem hình 1), sau đó gấp làm đôi (ảnh 2). Lăn bánh ra một lần nữa và gấp lại theo cách tương tự thêm 3 lần nữa, để bánh nghỉ ít nhất 15 phút, mỗi lần giữa cuộn và gấp, sau đó để bánh nghỉ trong tủ lạnh ít nhất 30 phút trước khi sử dụng.', NULL, '2026-05-15 14:55:36', '2026-05-15 14:55:36'),
(4635, 696, 3, 'Để làm nhân, làm tan chảy bơ trong một cái chảo lớn. Tắt lửa và khuấy tất cả các thành phần khác cho đến khi trộn hoàn toàn, sau đó đặt sang một bên.', NULL, '2026-05-15 14:55:36', '2026-05-15 14:55:36'),
(4636, 696, 4, 'Để làm bánh, hãy cán bánh ra cho đến khi nó dày hơn đồng xu 1 bảng một chút và cắt ra 8 vòng tròn có chiều ngang khoảng 12 cm. Cuộn lại phần cắt tỉa nếu cần. Đặt một thìa hỗn hợp đã trộn đều vào giữa mỗi viên tròn, phết nước lên các cạnh của viên tròn, sau đó gom bánh ngọt xung quanh phần nhân và ép lại với nhau (ảnh 3). Lật chúng lại để phần trên nhẵn hướng lên trên và vỗ chúng thành một vòng tròn mịn. Dùng cán cán dẹt từng vòng thành hình bầu dục cho đến khi quả vừa bắt đầu xuyên qua thì đặt lên khay nướng. Cắt 2 khe nhỏ trên mỗi chiếc bánh Eccles, phết một lớp lòng trắng trứng lên trên và rắc đường (ảnh 4).', NULL, '2026-05-15 14:55:36', '2026-05-15 14:55:36'),
(4637, 696, 5, 'Làm nóng lò ở nhiệt độ 220C/200C quạt/gas 8. Nướng bánh Eccles trong 15-20 phút cho đến khi vừa chuyển sang màu nâu vàng và dính. Để nguội trên giá và thưởng thức khi còn ấm hoặc lạnh với một tách trà. Nếu bạn thích, bánh Eccles cũng rất hợp ăn kèm với một miếng pho mát Anh cứng và thơm như Lancashire hoặc cheddar.', NULL, '2026-05-15 14:55:36', '2026-05-15 14:55:36'),
(4638, 697, 1, 'Nghiền một nửa quả dâu tây trong máy xay sinh tố. Cắt nhỏ những quả dâu tây còn lại, để dành 4 quả để trang trí.', NULL, '2026-05-15 14:55:37', '2026-05-15 14:55:37'),
(4639, 697, 2, 'Đánh kem đôi cho đến khi tạo thành chóp cứng, sau đó cho dâu tây xay nhuyễn và bánh trứng đường nghiền vào. Cho dâu tây cắt nhỏ và nước gừng vào nếu dùng.', NULL, '2026-05-15 14:55:37', '2026-05-15 14:55:37'),
(4640, 697, 3, 'Múc một lượng hỗn hợp bằng nhau vào bốn ly rượu lạnh. Phục vụ trang trí với dâu tây còn lại và một nhánh bạc hà.', NULL, '2026-05-15 14:55:37', '2026-05-15 14:55:37'),
(4641, 698, 1, 'Đối với caramen, cho 100 gam đường vào chảo rán không có mỡ và đun chảy ở lửa vừa. Cố gắng không khuấy bằng thìa mà hãy xoay chảo. Để tan chảy cho đến khi bạn có màu hổ phách và đường tan chảy hoàn toàn. Đổ đầy vào đáy bốn hộp đựng bánh flan. Caramel sẽ cứng lại ngay nên bạn cần phải nhanh tay. Thùng chứa của tôi mang lại khoảng 120 ml mỗi thùng.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4642, 698, 2, 'Làm nóng lò nướng ở nhiệt độ 150 độ C và tìm một cái nồi hoặc hộp đựng vừa đủ bốn hộp đựng bánh flan của bạn.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4643, 698, 3, 'Đun nóng sữa với 45 gam đường rồi cắt vỏ vani. Sữa không cần đun sôi, chỉ cần đun nóng. Lấy vỏ vani ra sau vài phút. Trong khi đó, khuấy nhẹ lòng đỏ trứng và trứng, cố gắng không để lẫn không khí vào. Họ đổ hỗn hợp sữa vào hỗn hợp trứng và chỉ khuấy lại thật nhẹ nhàng. Đổ vào các hộp đựng bánh flan đã chuẩn bị sẵn và đặt chúng vào nồi hoặc hộp đựng của bạn. Đun sôi nước và đổ nước vào nồi lớn. Đảm bảo không chạm vào hỗn hợp bánh flan. Đặt trên giá giữa trong lò và nướng trong khoảng 35-40 phút. Một cây tăm được cắm vào sẽ sạch sẽ.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4644, 698, 4, 'Để nguội bên trong hộp trong một giờ trước khi chuyển vào tủ lạnh. Thư giãn qua đêm. Ngày hôm sau nhẹ nhàng thả vành bánh ra rồi úp ngược ra đĩa. Ăn kèm với một ít dulce de leche bên cạnh.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4645, 699, 1, 'Làm nóng lò ở nhiệt độ 350˚F.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4646, 699, 2, 'Trộn tất cả nguyên liệu làm vỏ bánh (mụn bánh quy giòn graham, bơ tan chảy, đường cát và quế xay) trong tô vừa. Dành khoảng 2 muỗng canh (30 mL) cho lần sau và ấn hỗn hợp vào đĩa bánh sâu 9 inch ở dưới cùng và lên trên các mặt. Nướng vỏ bánh trong 10 phút, bánh sẽ chỉ hơi nâu.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4647, 699, 3, 'Kết hợp các nguyên liệu làm nhân sữa trứng vani (sữa, đường cát, bột ngô, lòng đỏ trứng, chiết xuất vani và muối với nhau) và nấu trên lửa vừa, khuấy liên tục cho đến khi sủi bọt và đặc lại như kết cấu của bánh pudding. Đặt sang một bên để nguội trong khi bạn làm lớp phủ meringue.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4648, 699, 4, 'Trong tô của máy trộn đứng có gắn phụ kiện máy đánh trứng hoặc trong tô lớn sử dụng máy trộn điện, đánh đều các nguyên liệu làm bánh trứng đường (lòng trắng trứng, đường cát, kem tartar) với nhau cho đến khi có chóp cứng và bóng.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4649, 699, 5, 'Để gói bánh, đổ nhân vào vỏ bánh và phủ một lớp bánh trứng đường dày lên trên, tạo thành những chiếc gai nhỏ sẽ có màu nâu ở trên. Rắc phần vụn bánh đã để sẵn lên trên và cho vào lò nướng đã làm nóng trước.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4650, 699, 6, 'Nướng cho đến khi bánh trứng đường có màu nâu, khoảng 10 phút, nhớ quan sát cẩn thận.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(4651, 699, 7, 'Làm lạnh trong tủ lạnh và ăn trong vòng vài giờ sau khi nướng. Bánh này ngon nhất nên ăn trong ngày vì bánh trứng đường sẽ mềm và lỏng.', NULL, '2026-05-15 14:55:39', '2026-05-15 14:55:39'),
(4652, 700, 1, 'vỏ bánh', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4653, 700, 2, 'Trộn đường, vani và bơ cho đến khi mịn và nhẹ. Trộn lòng đỏ trứng vào. Cho bột mì và bột nở vào, dùng tay nhào cho đến khi bột mịn.', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4654, 700, 3, 'Gói bột trong màng bọc thực phẩm và để lạnh trong tủ lạnh ít nhất 30 phút.', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4655, 700, 4, 'nhân hạnh nhân', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4656, 700, 5, 'Cho hạnh nhân và đường vào máy xay thực phẩm cho đến khi hạnh nhân được nghiền mịn (bạn có thể tự quyết định độ thô hay mịn mà mình muốn).', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4657, 700, 6, 'Khuấy bơ, trứng, rượu cognac và/hoặc chiết xuất hạnh nhân (nếu sử dụng).', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4658, 700, 7, 'Lót giấy nướng vào đáy khuôn bánh và bôi mỡ vào các cạnh của khuôn.', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4659, 700, 8, 'Làm nóng lò ở nhiệt độ 350°F (175°C).', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4660, 700, 9, 'Cắt 2/3 phần bột vỏ bánh thành từng lát rồi ấn xuống thành dạng bánh. Phủ bột vào phần dưới của khuôn bánh và đưa bột lên 2-3 cm (1 inch) lên các cạnh của khuôn, ấn cho đến khi đều.', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4661, 700, 10, 'Múc nhân hạnh nhân lên trên vỏ bánh, dàn đều khắp khuôn bánh.', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4662, 700, 11, 'Cán phần bột còn lại và cắt thành dải dài. Xếp các dải bột lên bánh theo dạng lưới. Đừng lo lắng về việc các dải giấy bị đứt - chỉ cần ấn chúng lại với nhau trên bánh.', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4663, 700, 12, 'Nhẹ nhàng chải bột bằng nước rửa trứng.', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4664, 700, 13, 'Nướng trong khoảng 45 phút. Mặt trên của bánh phải có màu nâu vàng trong khi nhân hạnh nhân vẫn mềm.', NULL, '2026-05-15 14:55:40', '2026-05-15 14:55:40'),
(4665, 701, 1, 'Trộn bột mì tự nổi, đường, hỗn hợp gia vị speculaas và muối. Thêm bơ và sữa vào rồi nhào thành một khối bột cứng. Bắt đầu với 6 thìa sữa, nếu bột quá cứng bạn có thể cho thêm sữa.', NULL, '2026-05-15 14:55:42', '2026-05-15 14:55:42'),
(4666, 701, 2, 'Bọc bột trong màng bọc thực phẩm và để lạnh qua đêm. Bạn có thể chế biến và nướng ngay nhưng hương vị sẽ ngon hơn rất nhiều nếu bạn để yên.', NULL, '2026-05-15 14:55:42', '2026-05-15 14:55:42'),
(4667, 701, 3, 'Trộn bột hạnh nhân với một nửa quả trứng đã đánh và nhào đều. Điều này làm cho nó dễ dàng hơn để làm việc và mang lại cho nó một kết cấu tốt hơn và ngon hơn.', NULL, '2026-05-15 14:55:42', '2026-05-15 14:55:42'),
(4668, 701, 4, 'Lấy một nửa khối bột và cán thành kích thước 20 x 20 cm. Đặt vào khay nướng có lót giấy da. Trải đều hỗn hợp bột hạnh nhân. Cán mỏng phần bột còn lại và đặt lên trên lớp bột hạnh nhân.', NULL, '2026-05-15 14:55:42', '2026-05-15 14:55:42'),
(4669, 701, 5, 'Phủ phần trứng đã đánh còn lại lên trên. Trang trí với hạnh nhân và phủ một lớp trứng khác lên trên.', NULL, '2026-05-15 14:55:42', '2026-05-15 14:55:42'),
(4670, 701, 6, 'Nướng những chiếc bánh đã làm đầy trong 40 phút ở 180°C/350℉ (lò nướng thông thường) hoặc cho đến khi chín.', NULL, '2026-05-15 14:55:42', '2026-05-15 14:55:42'),
(4671, 702, 1, 'Trong một tô lớn, sử dụng máy trộn điện để đánh kem đặc lạnh cho đến khi tạo thành chóp cứng. Nhẹ nhàng trộn sữa đặc có đường và chiết xuất vani vào cho đến khi hòa quyện.', NULL, '2026-05-15 14:55:43', '2026-05-15 14:55:43'),
(4672, 702, 2, 'Cho ngũ cốc vào và khuấy đều cho đến khi phân bố đều khắp hỗn hợp.', NULL, '2026-05-15 14:55:43', '2026-05-15 14:55:43'),
(4673, 702, 3, 'Đổ hỗn hợp vào hộp đựng an toàn trong tủ đông (chẳng hạn như khuôn làm bánh mì). Đặt màng bọc thực phẩm lên trên kem để tránh bị cháy tủ đông. Đậy nắp hộp và để đông ít nhất 6 giờ hoặc cho đến khi cứng lại.', NULL, '2026-05-15 14:55:43', '2026-05-15 14:55:43'),
(4674, 702, 4, 'Sau khi đông lạnh, hãy để kem ở nhiệt độ phòng trong vài phút để hơi mềm trước khi múc và dùng.', NULL, '2026-05-15 14:55:43', '2026-05-15 14:55:43'),
(4675, 703, 1, 'Làm nóng lò ở nhiệt độ quạt/khí 160C/140C 3. Dùng cán cán nghiền nát bánh quy và hầu hết hạnh nhân bên trong túi nhựa đựng thực phẩm. Trộn với bơ, sau đó ấn vào đáy đĩa sâu, hình bầu dục, đường kính 23cm (hoặc vật gì đó có kích thước tương tự - khuôn nướng, khuôn nướng hoặc khuôn làm bánh đều phù hợp). Nướng trong 10 phút cho đến khi giòn.', NULL, '2026-05-15 14:55:44', '2026-05-15 14:55:44'),
(4676, 703, 2, 'Khuấy hoặc nghiền nhuyễn sữa chua và mascarpone, sau đó cho từng quả trứng vào đánh đều. Khuấy vỏ chanh và cam, sau đó cho phần lớn mật ong vào, chừa lại khoảng 3 muỗng canh. Trải đều trên đế bánh quy, phủ nhẹ bằng giấy bạc và nấu trong 1 giờ. Lấy giấy bạc ra và nấu thêm 15 phút cho đến khi vàng nhạt và mặt trên cứng lại, chỉ hơi rung nhẹ ở giữa. Để nguội. Có thể bảo quản trong tủ lạnh tối đa 2 ngày.', NULL, '2026-05-15 14:55:44', '2026-05-15 14:55:44'),
(4677, 703, 3, 'Để phục vụ, hãy rắc hạnh nhân, rưới lên lượng mật ong còn lại và đưa trái cây tươi đi kèm.', NULL, '2026-05-15 14:55:44', '2026-05-15 14:55:44'),
(4678, 704, 1, 'Lót một khay nướng hình vuông 8 inch bằng giấy sáp hoặc giấy bạc và phủ một lớp xịt chống dính.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4679, 704, 2, 'Trong một chiếc bát an toàn với lò vi sóng, trộn sô cô la đen, kem béo và một nửa sữa đặc có đường. Cho hỗn hợp sô cô la đen vào lò vi sóng trong khoảng thời gian 20 giây, khuấy đều giữa mỗi khoảng thời gian cho đến khi sô cô la tan chảy.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4680, 704, 3, 'Thêm chiết xuất vani vào hỗn hợp sô cô la đen và khuấy đều cho đến khi mịn.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4681, 704, 4, 'Chuyển hỗn hợp sô cô la đen vào chảo đã chuẩn bị sẵn và dàn đều thành một lớp.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4682, 704, 5, 'Trong một bát riêng, trộn sô cô la trắng với nửa sữa đặc có đường còn lại. Cho hỗn hợp sô cô la trắng vào lò vi sóng trong khoảng thời gian 20 giây, khuấy đều giữa mỗi khoảng thời gian cho đến khi sô cô la tan chảy.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4683, 704, 6, 'Trải đều hỗn hợp sô cô la trắng lên trên lớp sô cô la đen.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4684, 704, 7, 'Phủ Mallow Bits hoặc kẹo dẻo thu nhỏ lên trên các lớp sô cô la và nhẹ nhàng ấn chúng xuống.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4685, 704, 8, 'Làm lạnh trong 4 giờ hoặc cho đến khi đông lại.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4686, 704, 9, 'Lấy giấy nến và giấy sáp ra khỏi chảo. Cẩn thận bóc toàn bộ giấy sáp ra khỏi kẹo mềm.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4687, 704, 10, 'Cắt kẹo mềm thành từng miếng vừa ăn và thưởng thức.', NULL, '2026-05-15 14:55:45', '2026-05-15 14:55:45'),
(4688, 705, 1, 'Làm nóng lò ở nhiệt độ 350°F (180°C) và lót giấy nến vào khay nướng lớn.', NULL, '2026-05-15 14:55:46', '2026-05-15 14:55:46'),
(4689, 705, 2, 'Trong máy trộn đứng có gắn cánh khuấy, đánh bơ, đường trắng và trứng cho đến khi hòa quyện, sau đó thêm mật đường và vani vào và trộn cho đến khi mịn.', NULL, '2026-05-15 14:55:46', '2026-05-15 14:55:46'),
(4690, 705, 3, 'Sau khi kết hợp, thêm hỗn hợp nước baking soda và trộn thêm một phút nữa để kết hợp.', NULL, '2026-05-15 14:55:46', '2026-05-15 14:55:46'),
(4691, 705, 4, 'Kết hợp các thành phần khô; trộn bột nở, quế, bột mì và muối trong một bát riêng, sau đó thêm từng chút một vào nguyên liệu ướt, trộn ở mức thấp cho đến khi hòa quyện hoàn toàn và cạo các mặt để đảm bảo mọi thứ được hòa quyện. Bột phải dễ tạo hình.', NULL, '2026-05-15 14:55:46', '2026-05-15 14:55:46'),
(4692, 705, 5, 'Chia bột bằng một chiếc thìa nhỏ, vo thành từng quả bóng và đặt chúng lên khay bánh quy đã lót giấy, dùng cốc thủy tinh có bột mì hoặc lòng bàn tay ẩm ấn chúng thành những đĩa phẳng.', NULL, '2026-05-15 14:55:46', '2026-05-15 14:55:46'),
(4693, 705, 6, 'Đặt bánh lên khay nướng có lót giấy nến và nướng trong vòng 10-12 phút. Lấy ra khỏi lò và để chúng nguội trong ít nhất 10 phút.', NULL, '2026-05-15 14:55:46', '2026-05-15 14:55:46'),
(4694, 705, 7, 'Sau khi làm nguội bánh quy bằng cách phết ít nhất hai thìa cà phê mứt yêu thích của bạn vào giữa hai chiếc bánh quy. Lặp lại và thưởng thức với một tách trà.', NULL, '2026-05-15 14:55:46', '2026-05-15 14:55:46'),
(4695, 706, 1, 'Đặt một khay nướng sâu lòng vào kệ dưới cùng của lò và đảm bảo có một kệ khác ngay phía trên nó. Kéo khay nướng ra trên kệ, đổ nước sôi vào 2/3 ấm rồi cẩn thận trượt khay trở lại. Làm nóng lò ở mức quạt/khí 180C/160C 4. Xé một tờ giấy bạc và giấy thấm dầu lớn (khoảng 30 x 40cm). Đặt lớp chống thấm dầu lên trên giấy bạc và phết bơ lên ​​trên.', NULL, '2026-05-15 14:55:48', '2026-05-15 14:55:48'),
(4696, 706, 2, 'Cho bơ, bột mì và hạt vani vào máy xay thực phẩm; đập cho đến khi bơ biến mất. Đổ vào tô trộn. Khuấy đều mỡ, đổ sữa vào và dùng dao nĩa nhào cho đến khi thu được khối bột dính. Bạn có thể cần thêm một giọt sữa, tùy thuộc vào loại bột của bạn.', NULL, '2026-05-15 14:55:48', '2026-05-15 14:55:48'),
(4697, 706, 3, 'Đổ bột ra bề mặt đã rắc bột mì, vỗ nhanh cho bột mịn rồi cán thành hình vuông khoảng 25 x 25 cm. Trải mứt khắp nơi, để lại một khoảng trống dọc theo một cạnh, sau đó cuộn lên từ cạnh đối diện. Chụm phần mép không bị kẹt vào miếng bột nơi nó tiếp xúc và cũng kẹp thật mạnh phần cuối. Cẩn thận nhấc tờ giấy đã phết dầu lên, úp mặt xuống (bạn có thể thấy một tấm nướng phẳng hữu ích cho việc này), nhẹ nhàng đưa giấy và giấy bạc xung quanh nó lên, sau đó kẹp lại dọc theo các cạnh và đầu để bịt kín. Roly-poly sẽ phồng lên khá nhiều trong khi nấu nên đừng quấn chặt. Nhấc gói trực tiếp lên giá phía trên hộp thiếc và nấu trong 1 giờ.', NULL, '2026-05-15 14:55:48', '2026-05-15 14:55:48'),
(4698, 706, 4, 'Để bánh pudding trong 5 phút trước khi mở gói, sau đó cẩn thận mở giấy bạc và giấy bạc rồi cắt thành lát dày để thưởng thức.', NULL, '2026-05-15 14:55:48', '2026-05-15 14:55:48'),
(4699, 707, 1, 'Nghiền chuối bằng nĩa trong bát.', NULL, '2026-05-15 14:55:50', '2026-05-15 14:55:50'),
(4700, 707, 2, 'Thêm đường nâu, vani, chiết xuất, quế, nhục đậu khấu và một chút muối. Rây bột vào và dùng thìa khuấy đều cho đến khi hòa quyện hoàn toàn.', NULL, '2026-05-15 14:55:50', '2026-05-15 14:55:50'),
(4701, 707, 3, 'Thêm dầu vào chảo 10 inch trên lửa vừa cao. Khi dầu nóng, thả từng thìa bột chiên chuối vào dầu. Khi một mặt đã vàng và xuất hiện bong bóng ở trên, hãy lật bánh rán và nấu cho đến khi mặt còn lại cũng chuyển sang màu nâu.', NULL, '2026-05-15 14:55:50', '2026-05-15 14:55:50'),
(4702, 707, 4, 'Loại bỏ rán và để ráo trên khăn giấy. Thưởng thức', NULL, '2026-05-15 14:55:50', '2026-05-15 14:55:50'),
(4703, 708, 1, 'Ngâm nho khô, nho khô và anh đào vào 1 cốc bia. Đặt sang một bên và để ngâm trong 30 phút.', NULL, '2026-05-15 14:55:51', '2026-05-15 14:55:51'),
(4704, 708, 2, 'Làm nóng lò ở nhiệt độ 325 độ F. Bôi mỡ vào chảo ổ bánh mì 8x4. Đặt sang một bên.', NULL, '2026-05-15 14:55:51', '2026-05-15 14:55:51'),
(4705, 708, 3, 'Trộn bột mì đa dụng, bột nở, quế xay, muối vào tô lớn và đặt sang một bên.', NULL, '2026-05-15 14:55:51', '2026-05-15 14:55:51'),
(4706, 708, 4, 'Trong một bát khác, trộn đường nâu, trứng, sữa, mật ong, bơ tan chảy, mật đường, đường nâu, chiết xuất vani và bia ngâm trái cây. Đừng đổ trái cây vào lúc này, chỉ đổ bia thôi. Trộn để kết hợp.', NULL, '2026-05-15 14:55:51', '2026-05-15 14:55:51'),
(4707, 708, 5, 'Lấy 2 thìa bột mì ra khỏi hỗn hợp bột và cho trái cây vào đó. Đặt sang một bên.', NULL, '2026-05-15 14:55:51', '2026-05-15 14:55:51'),
(4708, 708, 6, 'Tạo một cái giếng ở giữa bát nguyên liệu khô rồi đổ hỗn hợp ướt vào, khuấy đều cho đến khi hòa quyện hoàn toàn. Và các loại trái cây cho vào hỗn hợp và khuấy đều cho đến khi hòa quyện.', NULL, '2026-05-15 14:55:51', '2026-05-15 14:55:51'),
(4709, 708, 7, 'Đổ hỗn hợp vào khuôn ổ bánh đã chuẩn bị sẵn và nướng trong lò đã làm nóng trước trong 50-60 phút hoặc cho đến khi tăm rút ra sạch sẽ.', NULL, '2026-05-15 14:55:51', '2026-05-15 14:55:51'),
(4710, 708, 8, 'Làm nguội trong chảo trong 5 phút rồi chuyển sang giá làm mát để làm mát xong. Ăn kèm với lát phô mai cheddar.', NULL, '2026-05-15 14:55:51', '2026-05-15 14:55:51'),
(4711, 709, 1, 'Làm nóng lò ở nhiệt độ 350°F (175°C). Bôi mỡ và lót một chiếc chảo tròn 9 inch hoặc chảo ổ bánh mì bằng giấy da.', NULL, '2026-05-15 14:55:52', '2026-05-15 14:55:52'),
(4712, 709, 2, 'Đặt khoai lang đã cắt vào tô của máy xay thực phẩm và chế biến cho đến khi nghiền mịn. Trong một bát nhỏ, trộn nho khô với 2 thìa cà phê bột mì từ ½ cốc. Đặt sang một bên.', NULL, '2026-05-15 14:55:52', '2026-05-15 14:55:52'),
(4713, 709, 3, 'Trong một tô lớn, trộn khoai lang bào, đường nâu nhạt, bột mì đa dụng, chiết xuất vani, hạt tiêu, quế, nhục đậu khấu, gừng và muối. Khuấy 1½ cốc nước cốt dừa cho đến khi tạo thành bột. Gấp nho khô đã được trộn vào bột mì.', NULL, '2026-05-15 14:55:52', '2026-05-15 14:55:52'),
(4714, 709, 4, 'Đổ bột vào chảo đã chuẩn bị sẵn và làm phẳng phần trên. Nướng không đậy nắp trong 1 giờ 30 phút, cho đến khi gần chín nhưng vẫn hơi mềm ở giữa', NULL, '2026-05-15 14:55:52', '2026-05-15 14:55:52'),
(4715, 710, 1, 'Làm nóng lò nướng ở nhiệt độ 160C/quạt 140C/gas 3. Đánh bánh quy thành vụn trong máy xay thực phẩm (hoặc cho vào túi nhựa chắc chắn và dùng chày cán bột đập vụn bánh quy). Trộn với bơ tan chảy và ấn vào đế và các cạnh của khuôn bánh tart có đế rời 22cm. Nướng trong lò trong 10 phút. Hủy bỏ và làm mát.', NULL, '2026-05-15 14:55:53', '2026-05-15 14:55:53'),
(4716, 710, 2, 'Cho lòng đỏ trứng vào tô lớn và đánh đều trong một phút bằng máy đánh trứng. Thêm sữa đặc và đánh trong 3 phút, sau đó thêm vỏ và nước trái cây vào và đánh lại trong 3 phút. Đổ nhân vào đế đã nguội rồi cho vào lò nướng trong 15 phút. Để nguội rồi để lạnh ít nhất 3 tiếng hoặc qua đêm nếu thích.', NULL, '2026-05-15 14:55:53', '2026-05-15 14:55:53'),
(4717, 710, 3, 'Khi bạn đã sẵn sàng phục vụ, hãy cẩn thận lấy bánh ra khỏi hộp thiếc và đặt lên đĩa phục vụ. Để trang trí, đánh nhẹ kem và đường bột với nhau. Đổ hoặc phết kem lên mặt bánh và phủ thêm vỏ chanh.', NULL, '2026-05-15 14:55:53', '2026-05-15 14:55:53'),
(4718, 711, 1, 'Hòa tan men trong nước ấm trong bát 2 1/2 lít. Thêm sữa, đường, muối, trứng, mỡ và 2 chén bột mì. Đánh ở tốc độ thấp trong 30 giây, cạo bát liên tục. Đánh ở tốc độ trung bình trong 2 phút, thỉnh thoảng cạo bát. Khuấy bột còn lại cho đến khi mịn. Đậy nắp và để tăng gấp đôi, 50-60 phút. (Bột đã sẵn sàng khi chạm vào vẫn còn vết lõm.) Lật bột lên bề mặt đã rắc bột mì; cuộn nhẹ xung quanh để phủ bột. Nhẹ nhàng cán bột dày 1/2 inch bằng cán bột. Cắt bằng máy cắt bánh rán bột. Đậy nắp và để tăng gấp đôi, 30-40 phút.', NULL, '2026-05-15 14:55:55', '2026-05-15 14:55:55'),
(4719, 711, 2, 'Đun nóng dầu thực vật trong nồi chiên sâu đến 350°. Trượt bánh rán vào dầu nóng bằng thìa rộng. Xoay bánh rán khi chúng nổi lên trên bề mặt. Chiên cho đến khi có màu vàng nâu, khoảng 1 phút mỗi mặt. Cẩn thận loại bỏ dầu (không chích vào bề mặt); làm khô hạn. Nhúng bánh rán vào lớp men kem đặt trên giá.', NULL, '2026-05-15 14:55:55', '2026-05-15 14:55:55'),
(4720, 711, 3, 'Đun nóng bơ cho đến khi tan chảy. Loại bỏ khỏi nhiệt. Khuấy đường bột và vani cho đến khi mịn. Khuấy trong nước, mỗi lần 1 muỗng canh, cho đến khi có độ đặc mong muốn.', NULL, '2026-05-15 14:55:55', '2026-05-15 14:55:55'),
(4721, 712, 1, 'sữa trứng vani', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4722, 712, 2, 'Tách lòng đỏ trứng và để riêng lòng trắng để dùng làm bánh trứng đường.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4723, 712, 3, 'Đánh đều lòng đỏ trứng, bột ngô và đường trong tô.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4724, 712, 4, 'Đun nóng kem và sữa trong chảo. Tách vỏ vani và thêm đậu vào nồi. Khi sữa bắt đầu sủi bọt, đổ khoảng một nửa vào bát cùng với hỗn hợp trứng, đánh liên tục. Sau đó bắc chảo lên bếp rồi đổ hỗn hợp trứng vào nồi cùng với phần sữa còn lại, khuấy liên tục. Khi hỗn hợp đặc lại thì giảm nhiệt và tiếp tục đánh trong khoảng 30 giây.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4725, 712, 5, 'Đổ sữa trứng vào tô sạch và dùng màng bọc thực phẩm bọc lại, đặt màng nhựa trực tiếp lên lớp trên cùng của sữa trứng. Thư giãn trong tủ lạnh.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4726, 712, 6, 'bánh ngọt', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4727, 712, 7, 'Trộn đều bơ và đường cho đến khi mịn và nhẹ. Thêm từng lòng đỏ trứng vào, để riêng lòng trắng trứng để làm bánh trứng đường. Thêm bột mì trộn với bột nở. Khuấy sữa, đánh cho đến khi mịn (bạn có thể sử dụng máy trộn điện nếu thích).', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4728, 712, 8, 'Làm nóng lò ở nhiệt độ 320°F (160°C). Phủ giấy nướng bánh lên khay nướng và dàn bột thành hình chữ nhật lớn, đều.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4729, 712, 9, 'topping meringue', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4730, 712, 10, 'Đánh đều lòng trắng trứng và đường cho đến khi thu được chóp cứng và bóng. Bánh trứng đường phải giữ nguyên hình dạng – nếu nó vẫn tan thì tiếp tục đánh.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4731, 712, 11, 'Trải meringue lên trên mặt bột bánh. Dùng thìa tạo sóng ánh sáng với bánh trứng đường. Rắc hạnh nhân lên trên meringue. Nướng trong khoảng 30 phút, cho đến khi bánh trứng đường và hạnh nhân chuyển sang màu vàng.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4732, 712, 12, 'Nhân kem', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4733, 712, 13, 'Đánh kem thành chóp cứng. Cẩn thận gấp sữa trứng vani vào.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4734, 712, 14, 'Khi bánh đã nguội, cắt làm đôi. Bạn có thể dùng kéo hoặc dao đặt trên thớt để cắt giấy nướng bánh.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4735, 712, 15, 'Đặt một nửa chiếc bánh lên đĩa phục vụ với mặt meringue úp xuống và bóc giấy nướng.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4736, 712, 16, 'Trải phần nhân kem lên khắp mặt bánh. Sau đó cẩn thận lấy nửa còn lại của chiếc bánh ra khỏi giấy nướng và đặt nó lên trên phần nhân kem, mặt meringue hướng lên trên.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4737, 712, 17, 'Ăn kèm với quả mọng tươi.', NULL, '2026-05-15 14:55:57', '2026-05-15 14:55:57'),
(4739, 713, 1, 'Làm nóng lò nướng ở nhiệt độ 200C/180C quạt/khí 6. Bơ bơ và lót khuôn hình chữ nhật 20 x 30cm.', NULL, '2026-05-15 14:55:58', '2026-05-16 12:35:35'),
(4741, 713, 2, 'Đánh bơ và đường trong máy trộn đứng cho đến khi nhạt và mịn. Thêm từng quả trứng vào và đánh đều. Đánh đều bột mì, sữa và muối cho đến khi hòa quyện hoàn toàn rồi cho vào khuôn. Nướng trong lò trong 25 phút hoặc cho đến khi vàng và chắc khi chạm vào. Đặt sang một bên để nguội hoàn toàn.', NULL, '2026-05-15 14:55:58', '2026-05-16 12:35:35'),
(4743, 713, 3, 'Cắt miếng bọt biển theo chiều ngang để tạo thành hai nửa. Cắt các cạnh để tạo thành các góc hoàn hảo. Cắt miếng bọt biển thành 18 hình vuông. Đánh nhẹ kem với đường bột cho đến khi đạt chóp mềm. Phết một ít mứt lên một nửa miếng bọt biển hình vuông sau đó phết hoặc phết lên một ít kem. Kẹp từng miếng với một miếng bọt biển hình vuông thứ hai sau đó để vào tủ lạnh để làm lạnh.', NULL, '2026-05-15 14:55:58', '2026-05-16 12:35:35'),
(4745, 713, 4, 'Để làm kem, trộn bơ tan chảy và sữa vào tô. Rây bột cacao và đường bột vào một bát riêng. Từ từ thêm cacao và đường vào hỗn hợp bơ và sữa, đánh liên tục để đảm bảo không bị vón cục. Nếu nó bị vón cục, hãy xay bằng máy xay cầm tay cho đến khi mịn.', NULL, '2026-05-15 14:55:58', '2026-05-16 12:35:35'),
(4747, 713, 5, 'Chia dừa vào ba chiếc bát nông (điều này giúp dừa không bị phủ quá nhiều sô cô la khi bạn nhúng).', NULL, '2026-05-15 14:55:58', '2026-05-16 12:35:35'),
(4749, 713, 6, 'Nhúng từng lamington vào kem cho đến khi phủ kín hoàn toàn. Cuộn dừa và đặt trên giá lưới. Lặp lại với miếng bọt biển còn lại. Thư giãn tối thiểu 1 giờ.', NULL, '2026-05-15 14:55:58', '2026-05-16 12:35:35'),
(4750, 714, 1, 'Làm nóng lò trước ở nhiệt độ 180C/350F/Gas 4. Bôi mỡ vào khuôn bánh tròn 18cm/7in, lót giấy thấm mỡ vào đế và phết giấy.', NULL, '2026-05-15 14:56:00', '2026-05-15 14:56:00'),
(4751, 714, 2, 'Đánh bơ và đường vào tô cho đến khi mịn và nhạt màu. Đánh từng quả trứng vào, đánh đều hỗn hợp giữa từng quả và thêm một thìa bột mì với quả trứng cuối cùng để tránh hỗn hợp bị vón cục.', NULL, '2026-05-15 14:56:00', '2026-05-15 14:56:00'),
(4752, 714, 3, 'Rây bột và trộn nhẹ nhàng, cho lượng sữa vừa đủ để tạo thành hỗn hợp rơi từ từ ra khỏi thìa. Gấp vỏ chanh vào.', NULL, '2026-05-15 14:56:00', '2026-05-15 14:56:00'),
(4753, 714, 4, 'Múc hỗn hợp vào khuôn đã chuẩn bị sẵn và san nhẹ mặt trên. Nướng trên kệ giữa của lò trong 30-40 phút, hoặc cho đến khi mặt trên có màu nâu vàng và cắm xiên vào giữa thấy tăm sạch sẽ.', NULL, '2026-05-15 14:56:00', '2026-05-15 14:56:00'),
(4754, 714, 5, 'Lấy ra khỏi lò và để nguội trong hộp thiếc trong 10 phút, sau đó đặt nó lên giá lưới và để nguội hoàn toàn.', NULL, '2026-05-15 14:56:00', '2026-05-15 14:56:00'),
(4755, 714, 6, 'Để phục vụ, trang trí bánh với vỏ kẹo.', NULL, '2026-05-15 14:56:00', '2026-05-15 14:56:00'),
(4756, 715, 1, 'Trộn bơ với đường cho đến khi thành kem.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4757, 715, 2, 'Thêm bột dầu và bột báng vào trộn đều.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4758, 715, 3, 'Thêm sữa ấm và không nhào quá nhiều', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4759, 715, 4, 'Đậy nắp và để yên trong một giờ hoặc ít hơn cho đến khi bạn chuẩn bị nhân', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4760, 715, 5, 'Để làm nhân chà là, hãy chiên một ít vừng trong chảo rồi thêm bơ. Thêm chà là và trộn đều với vừng và bơ. Sau đó cho thêm một ít nước vào cho đến khi sệt lại. Hãy cẩn thận đừng làm cho nó quá nhão.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4761, 715, 6, 'Lấy nó ra khỏi chảo, cho vào đĩa cho đến khi nguội. Sau đó bắt đầu tạo hình những quả bóng nặng 15 gm.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4762, 715, 7, 'Làm lạnh trong 1/2 giờ.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4763, 715, 8, 'Quay trở lại khối bột và tạo hình thành những quả bóng nặng 30 gm.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4764, 715, 9, 'Lấy quả chà là ra khỏi tủ lạnh và bắt đầu nhồi từng viên bột bằng quả chà là.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4765, 715, 10, 'Sau đó dùng khuôn mamoul để tạo hình dạng này.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4766, 715, 11, 'Cho vào lò nướng đã làm nóng trước ở nhiệt độ 180 độ, cho vào lò nướng trong 20 phút cho đến khi vàng từ bên dưới và một chút vàng từ bên trên.', NULL, '2026-05-15 14:56:02', '2026-05-15 14:56:02'),
(4767, 716, 1, 'Trộn bột mì và đường bột trong máy xay thực phẩm. Thêm bơ và xung cho đến khi nó được phân bổ đều. Thêm trứng và đập cho đến khi bột quyện lại với nhau.', NULL, '2026-05-15 14:56:04', '2026-05-15 14:56:04'),
(4768, 716, 2, 'Cán bột trên bề mặt đã rắc bột mì. Cắt bột thành hình tròn bằng cốc lớn. Nhấn các vòng tròn xuống chảo muffin đã phết mỡ. Đặt chảo vỏ vào tủ lạnh trong khi chuẩn bị nhân hạnh nhân.', NULL, '2026-05-15 14:56:04', '2026-05-15 14:56:04'),
(4769, 716, 3, 'nhân hạnh nhân', NULL, '2026-05-15 14:56:04', '2026-05-15 14:56:04'),
(4770, 716, 4, 'Làm nóng lò ở nhiệt độ 355°F (180°C).', NULL, '2026-05-15 14:56:04', '2026-05-15 14:56:04'),
(4771, 716, 5, 'Đánh trứng và đường bột với nhau cho đến khi đặc và thoáng. Đun chảy bơ và khuấy đều vào hỗn hợp trứng. Khuấy vani, bột mì và chiết xuất hạnh nhân. Khuấy bột hạnh nhân.', NULL, '2026-05-15 14:56:04', '2026-05-15 14:56:04'),
(4772, 716, 6, 'Đổ hoặc dùng thìa nhân hạnh nhân lên vỏ, đổ đầy vỏ khoảng 3/4.', NULL, '2026-05-15 14:56:04', '2026-05-15 14:56:04'),
(4773, 716, 7, 'Nướng mazariner trong 20 – 25 phút, cho đến khi có màu vàng nhạt. Làm nguội trên giá dây.', NULL, '2026-05-15 14:56:04', '2026-05-15 14:56:04'),
(4774, 716, 8, 'Trộn đường bột và chất lỏng cho đến khi bạn có được một lớp men có thể phết được. Trải lớp men lên trên mazariner và nếu bạn muốn, hãy trang trí bằng rắc hoặc bất cứ thứ gì bạn thích.', NULL, '2026-05-15 14:56:04', '2026-05-15 14:56:04'),
(4775, 717, 1, 'Để làm bánh ngọt, chà 225g bơ lạnh thái hạt lựu vào 350g bột mì thường, sau đó trộn với 100g đường vàng và một chút muối.', NULL, '2026-05-15 14:56:07', '2026-05-15 14:56:07'),
(4776, 717, 2, 'Trộn bánh ngọt thành một quả bóng - không thêm chất lỏng - và nhào nhẹ. Bột sẽ khá cứng, giống như bột bánh mì ngắn. Bạn có thể sử dụng bột ngay lập tức hoặc để nguội để dùng sau.', NULL, '2026-05-15 14:56:07', '2026-05-15 14:56:07'),
(4777, 717, 3, 'Làm nóng lò ở mức 200C/gas 6/quạt 180C. Khoanh 18 lỗ của hai khuôn bánh 12 lỗ, bằng cách ấn những viên bánh ngọt nhỏ cỡ quả óc chó vào mỗi lỗ.', NULL, '2026-05-15 14:56:07', '2026-05-15 14:56:07'),
(4778, 717, 4, 'Múc 280g thịt băm vào bánh.', NULL, '2026-05-15 14:56:07', '2026-05-15 14:56:07'),
(4779, 717, 5, 'Lấy những viên bánh ngọt nhỏ hơn một chút so với trước đây và dùng tay vỗ nhẹ để tạo thành những chiếc nắp tròn, đủ lớn để đậy kín những chiếc bánh.', NULL, '2026-05-15 14:56:07', '2026-05-15 14:56:07'),
(4780, 717, 6, 'Đậy nắp lên trên những chiếc bánh nướng, ấn nhẹ các cạnh lại với nhau để bịt kín - bạn không cần bọc chúng bằng sữa hoặc trứng vì chúng sẽ tự dính. (Bánh bây giờ có thể được đông lạnh tối đa 1 tháng).', NULL, '2026-05-15 14:56:07', '2026-05-15 14:56:07'),
(4781, 717, 7, 'Đánh 1 quả trứng nhỏ và phết lên mặt bánh. Nướng trong 20 phút cho đến khi vàng. Để nguội trong hộp thiếc trong 5 phút, sau đó lấy ra giá lưới.', NULL, '2026-05-15 14:56:07', '2026-05-15 14:56:07'),
(4782, 717, 8, 'Để phục vụ, rắc nhẹ với đường bột.', NULL, '2026-05-15 14:56:07', '2026-05-15 14:56:07'),
(4784, 718, 1, 'Làm nóng lò nướng ở nhiệt độ quạt/khí 180C/160C 4. Đun chảy 25g bơ và phết đều vào các lỗ của hộp thiếc nhỏ. Đổ một ít bột mì vào từng lỗ và lắc đều, sau đó đổ phần thừa ra. Đánh bơ, đường và một chút muối với nhau bằng máy đánh trứng điện. Thêm từng quả trứng vào, đánh đều sau mỗi lần thêm. Trộn bột mì và bột nở vào một bát riêng, sau đó rây bột mì vào nguyên liệu ướt và khuấy đều cho đến khi mịn. Trộn bột cacao và sữa vào tô nhỏ cho đến khi mịn.', NULL, '2026-05-15 14:56:11', '2026-05-16 12:35:35'),
(4786, 718, 2, 'Múc 1 muỗng canh bột mì vào từng lỗ của hộp thiếc. Trộn phần bột thô còn lại với hỗn hợp bột ca cao, sau đó chia phần bột này vào các lỗ. Nướng trong vòng 15-18 phút hoặc cho đến khi xiên que vào bánh thấy tăm sạch sẽ. Để nguội trong hộp thiếc trong 5 phút, sau đó đặt lên giá lưới và để nguội hoàn toàn. Rắc đường bột để phục vụ.', NULL, '2026-05-15 14:56:11', '2026-05-16 12:35:35'),
(4788, 718, 3, 'Đổ 1 thìa bột nhẹ vào mỗi khuôn. Trộn phần bột còn lại với hỗn hợp cacao đã khuấy rồi dùng thìa đổ đầy khuôn.', NULL, '2026-05-15 14:56:11', '2026-05-16 12:35:35'),
(4790, 718, 4, 'Nướng bánh Bundt mini trong lò làm nóng trước trong 15-18 phút, tùy thuộc vào kích thước khuôn. Sau 15 phút nướng, dùng tăm xiên thử và nếu cần, nướng thêm 3 phút nữa. Để bánh Bundt mini nguội hoàn toàn trong hộp thiếc. Sau đó cẩn thận lấy ra khỏi khuôn. Rắc một ít đường bột và thưởng thức. Thưởng thức bữa ăn của bạn!', NULL, '2026-05-15 14:56:11', '2026-05-16 12:35:35'),
(4791, 719, 1, 'Bắt đầu bằng cách làm đế bánh quy. Trong một cái bát, đặt trên chảo nước sôi, làm tan bơ với đường và bột ca cao, thỉnh thoảng khuấy cho đến khi mịn. Đánh trứng trong 2 đến 3 phút cho đến khi hỗn hợp đặc lại. Tắt bếp và trộn vụn bánh quy, dừa và hạnh nhân nếu dùng, sau đó ấn vào đáy hộp thiếc vuông có lót giấy 20cm. Thư giãn trong 10 phút.', NULL, '2026-05-15 14:56:13', '2026-05-15 14:56:13'),
(4792, 719, 2, 'Đối với lớp giữa, làm kem sữa trứng; đánh đều bơ, kem và bột sữa trứng cho đến khi mềm và mịn, sau đó thêm dần đường bột cho đến khi hòa quyện hoàn toàn. Trải lên lớp dưới cùng và để lạnh trong tủ lạnh ít nhất 10 phút cho đến khi sữa trứng không còn mềm nữa.', NULL, '2026-05-15 14:56:13', '2026-05-15 14:56:13'),
(4793, 719, 3, 'Đun chảy sô cô la và bơ với nhau trong lò vi sóng, sau đó phết lên các thanh đã nguội và cho vào tủ lạnh. Để cho đến khi sô cô la đông lại hoàn toàn (khoảng 2 giờ). Lấy hỗn hợp ra khỏi khuôn và cắt thành từng miếng vuông vừa ăn.', NULL, '2026-05-15 14:56:13', '2026-05-15 14:56:13'),
(4794, 720, 1, 'Đặt kệ lò ở giữa lò. Làm nóng lò ở mức quạt 160C/thông thường 180C/gas 4. Lót giấy da vào đế khuôn bánh dạng lò xo 23cm. Đối với lớp vỏ, làm tan bơ trong chảo vừa. Khuấy vụn bánh quy và đường để hỗn hợp được làm ẩm đều. Nhấn hỗn hợp vào đáy chảo và nướng trong 10 phút. Làm nguội trên giá lưới trong khi chuẩn bị nhân.', NULL, '2026-05-15 14:56:16', '2026-05-15 14:56:16'),
(4795, 720, 2, 'Để làm đầy, tăng nhiệt độ lò lên quạt 200C/thông thường 240C/gas 9. Trong máy trộn đặt trên bàn có gắn phụ kiện cánh khuấy, đánh phô mai mềm ở tốc độ trung bình thấp cho đến khi thành kem, khoảng 2 phút. Để máy trộn ở mức thấp nhất, thêm dần đường, sau đó là bột mì và một chút muối, cạo thành bát và mái chèo hai lần.', NULL, '2026-05-15 14:56:16', '2026-05-15 14:56:16'),
(4796, 720, 3, 'Trao đổi phần đính kèm mái chèo cho máy đánh trứng. Tiếp tục bằng cách thêm vani, vỏ chanh và nước trái cây. Đánh từng quả trứng và lòng đỏ vào, cạo bát và đánh ít nhất hai lần. Khuấy hộp kem chua 284ml cho đến khi mịn, sau đó đong 200ml/7fl oz (chỉ hơn 3⁄4 hộp). Tiếp tục ở tốc độ thấp khi bạn thêm kem chua đã đo (dự trữ phần còn lại). Đánh đều để hòa quyện, nhưng đừng đánh quá kỹ. Bột phải mịn, nhẹ và hơi thoáng.', NULL, '2026-05-15 14:56:16', '2026-05-15 14:56:16'),
(4797, 720, 4, 'Quét bơ tan chảy lên các mặt của khuôn lò xo và đặt lên khay nướng. Đổ nhân vào - nếu có vón cục, hãy dùng dao nhấn chìm chúng - phần trên phải càng mịn càng tốt. Nướng trong 10 phút. Giảm nhiệt độ lò xuống quạt 90C/thông thường 110C/khí 1⁄4 và nướng thêm 25 phút. Nếu bạn lắc nhẹ hộp thiếc, phần nhân sẽ hơi lắc lư. Tắt lò và mở cửa lò để làm bánh pho mát có nhân kem ở giữa hoặc đóng cửa lại nếu bạn thích kết cấu khô hơn. Để nguội trong lò trong 2 giờ. Bánh pho mát có thể bị nứt nhẹ ở mặt trên khi nguội.', NULL, '2026-05-15 14:56:16', '2026-05-15 14:56:16'),
(4798, 720, 5, 'Kết hợp kem chua dành riêng với hộp 142ml, đường và nước cốt chanh để phủ lên trên. Trải đều trên bánh pho mát đến tận các cạnh. Đậy kín bằng giấy bạc và để trong tủ lạnh ít nhất 8 giờ hoặc qua đêm.', NULL, '2026-05-15 14:56:16', '2026-05-15 14:56:16'),
(4799, 720, 6, 'Chạy một con dao có lưỡi tròn xung quanh các cạnh của hộp thiếc để nới lỏng các cạnh bị kẹt. Mở khóa mặt bên, trượt bánh pho mát ra khỏi đáy hộp thiếc lên đĩa, sau đó trượt giấy da từ bên dưới ra.', NULL, '2026-05-15 14:56:16', '2026-05-15 14:56:16'),
(4800, 721, 1, 'Đun nóng rượu rum trong nồi nhỏ trên lửa vừa cho đến khi ấm (không đun sôi). Tắt bếp và cho nho khô và chiết xuất vani vào khuấy đều. Để hỗn hợp ngồi trong ít nhất 30 phút. Sau khi ngâm, chắt hết rượu rum, nhưng giữ lại ¼ cốc rượu rum và dự trữ để trộn vào đế kem.', NULL, '2026-05-15 14:56:19', '2026-05-15 14:56:19'),
(4801, 721, 2, 'Trong một tô lớn, trộn đều sữa đặc có đường, đường nâu sẫm, quế, hạt tiêu, muối và rượu rum dành riêng (¼ cốc). Khuấy đều cho đến khi đường nâu tan hoàn toàn.', NULL, '2026-05-15 14:56:19', '2026-05-15 14:56:19'),
(4802, 721, 3, 'Trong một bát riêng, đánh kem đặc lạnh bằng máy trộn điện cho đến khi tạo thành chóp cứng.', NULL, '2026-05-15 14:56:19', '2026-05-15 14:56:19'),
(4803, 721, 4, 'Nhẹ nhàng trộn kem đã đánh bông vào hỗn hợp sữa đặc cho đến khi hòa quyện hoàn toàn, cẩn thận không làm xẹp kem. Gấp nho khô đã ngâm rượu rum đã ráo nước vào để phân bố đều.', NULL, '2026-05-15 14:56:19', '2026-05-15 14:56:19'),
(4804, 721, 5, 'Đổ hỗn hợp vào chảo ổ bánh mì hoặc hộp đựng an toàn trong tủ đông. Làm mịn mặt trên và bọc bằng màng bọc thực phẩm hoặc nắp đậy kín. Đóng băng ít nhất 6 giờ, hoặc cho đến khi cứng lại.', NULL, '2026-05-15 14:56:19', '2026-05-15 14:56:19'),
(4805, 721, 6, 'Để kem ở nhiệt độ phòng trong 5–10 phút trước khi múc để có kết cấu tốt nhất.', NULL, '2026-05-15 14:56:19', '2026-05-15 14:56:19'),
(4806, 722, 1, 'Đánh trứng và đường cho đến khi hỗn hợp đặc lại.', NULL, '2026-05-15 14:56:23', '2026-05-15 14:56:23'),
(4807, 722, 2, 'Đun chảy bơ và để nguội một chút rồi cho bơ vào hỗn hợp trứng.', NULL, '2026-05-15 14:56:23', '2026-05-15 14:56:23'),
(4808, 722, 3, 'Trộn gia vị rồi từ từ cho bột mì vào khuấy đều để tránh bị vón cục.', NULL, '2026-05-15 14:56:23', '2026-05-15 14:56:23'),
(4809, 722, 4, 'Để bột nghỉ ít nhất 30 phút. Điều này cải thiện kết cấu của krumkaker.', NULL, '2026-05-15 14:56:23', '2026-05-15 14:56:23'),
(4810, 722, 5, 'Múc khoảng một thìa bột lên bàn ủi và nướng. Nếu bột quá đặc, hãy thêm một ít nước vào.', NULL, '2026-05-15 14:56:23', '2026-05-15 14:56:23'),
(4811, 722, 6, 'Khi còn nóng, tạo hình krumkake bằng cây lăn krumkake bằng gỗ hoặc trên cốc (nếu dùng cốc, hãy làm chúng dày hơn một chút). Krumkaker cứng lại nhanh chóng, vì vậy bạn có thể để chúng trên ống lăn/cốc cho đến khi chiếc krumkake tiếp theo sẵn sàng được tạo hình.', NULL, '2026-05-15 14:56:23', '2026-05-15 14:56:23'),
(4812, 722, 7, 'Sau khi nguội hoàn toàn, bảo quản krumkaker trong hộp kim loại hoặc thủy tinh có lót khăn giấy ở phía dưới. Bạn cũng có thể đóng băng chúng!', NULL, '2026-05-15 14:56:23', '2026-05-15 14:56:23'),
(4813, 723, 1, 'Cho bột mì, trứng, sữa, 1 thìa canh dầu và một chút muối vào tô hoặc bình lớn, sau đó đánh đều thành hỗn hợp bột mịn. Dành 30 phút để nghỉ ngơi nếu bạn có thời gian hoặc bắt đầu nấu ngay.', NULL, '2026-05-15 14:56:25', '2026-05-15 14:56:25'),
(4814, 723, 2, 'Đặt chảo rán cỡ vừa hoặc chảo bánh crêpe trên lửa vừa và cẩn thận lau sạch bằng một ít giấy ăn đã thấm dầu. Khi còn nóng, hãy nướng bánh kếp mỗi mặt trong 1 phút cho đến khi vàng, giữ ấm trong lò nướng nhỏ trong khi nướng.', NULL, '2026-05-15 14:56:25', '2026-05-15 14:56:25'),
(4815, 723, 3, 'Ăn kèm với chanh và đường, hoặc loại nhân yêu thích của bạn. Sau khi nguội, bạn có thể xếp bánh kếp vào giữa giấy nướng, sau đó bọc trong màng bám và để đông trong tối đa 2 tháng.', NULL, '2026-05-15 14:56:25', '2026-05-15 14:56:25'),
(4816, 724, 1, 'Làm nóng lò nướng ở mức quạt/khí 160C/140C 3. Bôi mỡ vào khuôn bánh hình vuông sâu 22cm/9in và lót giấy nướng bánh. Đánh trứng và sữa cùng nhau bằng nĩa.', NULL, '2026-05-15 14:56:31', '2026-05-15 14:56:31'),
(4817, 724, 2, 'Nhẹ nhàng đun chảy xi-rô, mật đường, đường và bơ với nhau trong chảo lớn cho đến khi đường tan. Hủy bỏ khỏi nhiệt. Trộn bột yến mạch, bột mì và gừng rồi khuấy đều vào hỗn hợp xi-rô, tiếp theo là trứng và sữa.', NULL, '2026-05-15 14:56:31', '2026-05-15 14:56:31'),
(4818, 724, 3, 'Đổ hỗn hợp vào khuôn và nướng trong 50 phút - 1 giờ cho đến khi bánh có cảm giác cứng và hơi giòn ở trên. Làm nguội trong hộp thiếc, sau đó bọc thêm giấy da và giấy bạc và giữ trong 3-5 ngày trước khi ăn nếu bạn có thể - nó sẽ trở nên mềm và dính hơn nếu bạn để lâu hơn, tối đa 2 tuần.', NULL, '2026-05-15 14:56:31', '2026-05-15 14:56:31'),
(4819, 725, 1, 'Cho gelatin và ¼ cốc nước ở nhiệt độ phòng vào tô nhỏ; để yên cho đến khi gelatin mềm, khoảng 5 phút. Trong chảo vừa trên lửa vừa cao, khuấy đều hỗn hợp bột chanh dây, đường và gelatin. Nấu, thỉnh thoảng khuấy cho đến khi hỗn hợp hòa quyện và mịn màng (hỗn hợp không nên sôi). Hủy bỏ nhiệt; nguội hoàn toàn. Khuấy sữa đặc.', NULL, '2026-05-15 14:56:34', '2026-05-15 14:56:34'),
(4820, 725, 2, 'Trong khi đó, trong tô trộn sạch, dùng máy trộn điện, đánh lòng trắng trứng cho đến khi bông cứng (đỉnh lòng trắng trứng không bị xẹp xuống và lòng trắng trứng không xê dịch khi nghiêng bát).', NULL, '2026-05-15 14:56:34', '2026-05-15 14:56:34'),
(4821, 725, 3, 'Khuấy 1/3 lòng trắng trứng vào hỗn hợp chanh dây đã nguội cho đến khi hòa quyện. Dùng thìa trộn nhẹ nhàng phần lòng trắng trứng còn lại cho đến khi hòa quyện. Chia đều mousse vào các cốc thủy tinh trong suốt; che phủ. Làm lạnh mousse cho đến khi nguội hẳn, ít nhất 2 giờ.', NULL, '2026-05-15 14:56:34', '2026-05-15 14:56:34'),
(4822, 725, 4, 'Phục vụ ướp lạnh. Trang trí với bạc hà, nếu muốn.', NULL, '2026-05-15 14:56:34', '2026-05-15 14:56:34'),
(4823, 726, 1, 'Làm nóng lò ở mức quạt/khí 190C/170C 5. Bơ một đĩa rộng, nông, chịu nhiệt cho lò nướng. Trộn bột ngô với vỏ cam và nước ép, rồi cho vào chảo lớn cùng đường. Cắt đôi, cắt lát những quả đào rồi cho vào chảo. Đun sôi từ từ, khuấy nhẹ cho đến khi nước sốt sáng bóng và đặc lại, khoảng 3-4 phút. Tắt bếp, cho quả việt quất vào khuấy đều và cho vào đĩa đã chuẩn bị sẵn.', NULL, '2026-05-15 14:56:37', '2026-05-15 14:56:37'),
(4824, 726, 2, 'Đổ bột vào tô trộn và thêm 50g bơ. Chà bơ vào bột cho đến khi giống như vụn bánh mì mịn, sau đó cho một nửa đường vào trộn đều. Trộn phần đường còn lại với quế và để sang một bên.', NULL, '2026-05-15 14:56:37', '2026-05-15 14:56:37'),
(4825, 726, 3, 'Thêm sữa vào nguyên liệu khô và trộn thành bột mềm. Đổ ra một bề mặt có phủ bột nhẹ và nhào nhẹ. Cán thành hình thuôn dài khoảng 16 x 24cm. Quét bơ tan chảy và rắc đều đường cay. Cuộn lại từ một cạnh dài và cắt thành 12 lát. Xếp xung quanh mặt trên của đĩa, không để lộ phần giữa.', NULL, '2026-05-15 14:56:37', '2026-05-15 14:56:37'),
(4826, 726, 4, 'Nướng trong 20-25 phút, cho đến khi mặt trên giòn và vàng. Phục vụ ấm áp.', NULL, '2026-05-15 14:56:37', '2026-05-15 14:56:37'),
(4827, 727, 1, 'Thoa dầu và lót một khuôn bánh hình tròn có đáy rộng 20cm bằng màng dính, làm cho khuôn bánh càng mịn càng tốt. Đun chảy bơ trong chảo. Nghiền nát bánh quy bằng cách dùng cán lăn cho vào túi, sau đó khuấy đều với bơ cho đến khi bánh được tráng đều. Nhấn mạnh hỗn hợp vào đáy hộp thiếc và để nguội.', NULL, '2026-05-15 14:56:40', '2026-05-15 14:56:40'),
(4828, 727, 2, 'Ngâm gelatine vào nước trong lúc làm nhân. Cho ricotta vào tô, sau đó cho bơ đậu phộng và xi-rô vào đánh đều. Ricotta có kết cấu hơi sần sùi nên hãy xay nhuyễn cho đến khi mịn bằng máy xay dạng que để có kết cấu mịn hơn nếu bạn thích.', NULL, '2026-05-15 14:56:40', '2026-05-15 14:56:40'),
(4829, 727, 3, 'Lấy gelatine đã ngâm ra khỏi nước và vắt khô. Cho vào chảo cùng với sữa và đun nóng thật nhẹ cho đến khi gelatine tan. Đánh đều hỗn hợp đậu phộng, sau đó đổ lên đế bánh quy. Thư giãn cho đến khi thiết lập.', NULL, '2026-05-15 14:56:40', '2026-05-15 14:56:40'),
(4830, 727, 4, 'Để đông lạnh, hãy để trong hộp thiếc và ngay khi nó cứng lại, phủ màng bám lên bề mặt, sau đó bọc hộp thiếc bằng màng bám và giấy bạc.', NULL, '2026-05-15 14:56:40', '2026-05-15 14:56:40'),
(4831, 727, 5, 'Để rã đông, rã đông trong tủ lạnh qua đêm.', NULL, '2026-05-15 14:56:40', '2026-05-15 14:56:40'),
(4832, 727, 6, 'Để phục vụ, cẩn thận lấy ra khỏi hộp thiếc. Đánh kem với đường cho đến khi giữ được hình dạng, sau đó phết lên trên mặt bánh phô mai và rắc đậu phộng giòn.', NULL, '2026-05-15 14:56:40', '2026-05-15 14:56:40'),
(4833, 728, 1, 'Làm nóng lò ở nhiệt độ 350°F (180°C).', NULL, '2026-05-15 14:56:42', '2026-05-15 14:56:42'),
(4834, 728, 2, 'Trong một tô lớn, trộn đều bơ đậu phộng, đường và trứng.', NULL, '2026-05-15 14:56:42', '2026-05-15 14:56:42'),
(4835, 728, 3, 'Múc một thìa bột và vo thành một quả bóng. Đặt các viên bánh quy lên khay nướng chống dính.', NULL, '2026-05-15 14:56:42', '2026-05-15 14:56:42'),
(4836, 728, 4, 'Để trang trí thêm và khiến chúng chín đều hơn, hãy làm phẳng các viên bánh quy bằng cách ấn một cái nĩa xuống phía trên chúng, sau đó ấn xuống một góc 90 độ một lần nữa để tạo thành hình chữ thập.', NULL, '2026-05-15 14:56:42', '2026-05-15 14:56:42'),
(4837, 728, 5, 'Nướng trong 8-10 phút hoặc cho đến khi mặt dưới của bánh có màu vàng nâu.', NULL, '2026-05-15 14:56:42', '2026-05-15 14:56:42'),
(4838, 728, 6, 'Lấy ra khỏi tấm nướng và để nguội.', NULL, '2026-05-15 14:56:42', '2026-05-15 14:56:42'),
(4839, 728, 7, 'Thưởng thức!', NULL, '2026-05-15 14:56:42', '2026-05-15 14:56:42'),
(4840, 729, 1, 'Bỏ lõi quả lê, sau đó gọt vỏ càng gọn gàng càng tốt và cắt đôi. Nếu muốn, chúng có thể được chuẩn bị trước một ngày và để trong tủ lạnh, không đậy nắp để chúng khô.', NULL, '2026-05-15 14:56:45', '2026-05-15 14:56:45'),
(4841, 729, 2, 'Cho đường, bơ, hoa hồi, bạch đậu khấu và quế vào chảo chịu nhiệt, rộng khoảng 20cm rồi đun trên lửa lớn cho đến khi sủi bọt. Lắc chảo và khuấy nước sốt bơ cho đến khi tách ra và đường chuyển sang màu kẹo bơ cứng.', NULL, '2026-05-15 14:56:45', '2026-05-15 14:56:45'),
(4842, 729, 3, 'Đặt lê vào chảo, sau đó nấu với nước sốt trong 10-12 phút, thỉnh thoảng đảo cho đến khi có màu caramen hoàn toàn. Đừng lo lắng về việc chúng sẽ cháy - sẽ không đâu - nhưng bạn muốn caramen chúng càng nhiều càng tốt. Rưới rượu mạnh vào và để nó bốc cháy, sau đó đặt quả lê sang một bên.', NULL, '2026-05-15 14:56:45', '2026-05-15 14:56:45'),
(4843, 729, 4, 'Làm nóng lò ở 200C/quạt 180C/gas 6. Cán bánh ngọt có độ dày bằng đồng xu £1. Dùng một chiếc đĩa lớn hơn mặt chảo một chút, cắt thành một hình tròn, sau đó ấn các mép của hình tròn bánh ngọt để làm mỏng chúng ra.', NULL, '2026-05-15 14:56:45', '2026-05-15 14:56:45'),
(4844, 729, 5, 'Khi lê đã nguội một chút, xếp chúng vào chảo, cắt cạnh theo hình bông hoa, với mép xung quanh mép hướng vào trong. Đặt thanh quế lên trên ở giữa, với vỏ bạch đậu khấu rải rác xung quanh.', NULL, '2026-05-15 14:56:45', '2026-05-15 14:56:45'),
(4845, 729, 6, 'Phủ bánh ngọt lên những quả lê, sau đó nhét các cạnh xuống thành chảo và bên dưới quả lê (xem hướng dẫn của Gordon). Đâm bánh vài lần rồi nướng trong 15 phút. Nếu có nhiều nước trái cây nổi lên thành chảo, hãy đổ nó đi ở giai đoạn này (xem hướng dẫn). Giảm nhiệt độ lò xuống 180C/quạt 160C/gas 4 và nướng thêm 15 phút nữa cho đến khi bánh vàng. Để bánh tart đứng trong 10 phút, sau đó cẩn thận úp bánh vào đĩa phục vụ.', NULL, '2026-05-15 14:56:45', '2026-05-15 14:56:45'),
(4846, 730, 1, 'Làm nóng lò ở mức quạt/khí 160C/140C 3. Bôi mỡ và lót đế và các mặt của khuôn bánh sâu 20 cm bằng giấy nướng. Cho mật ong, đường và bơ vào nồi vừa và nấu trên lửa vừa cho đến khi tan chảy hoàn toàn. Tắt bếp và để nguội. Cho bột mì và gia vị vào tô lớn rồi trộn đều mọi thứ lại với nhau.', NULL, '2026-05-15 14:56:48', '2026-05-15 14:56:48'),
(4848, 730, 2, 'Khi các thành phần lỏng đã nguội, đánh trứng vào. Đổ các nguyên liệu khô lên trên, đánh đều để tạo thành hỗn hợp bột mịn - cẩn thận không trộn quá kỹ vì có thể khiến bánh bị khô. Đổ vào khuôn đã chuẩn bị sẵn và nướng trong 50-55 phút hoặc cho đến khi bánh nở ra và xiên vào giữa bánh sẽ thấy tăm sạch sẽ. Để bánh nguội trong khuôn khoảng 20 phút trước khi chuyển ra giá lưới cho bánh nguội hoàn toàn.', NULL, '2026-05-15 14:56:48', '2026-05-16 12:35:35'),
(4850, 730, 3, 'Sau khi nguội, dùng dao răng cưa lớn cắt bánh thành 3 lớp. Trải mứt lên 2 lớp bánh dưới cùng, sau đó xếp lại bánh và đặt sang một bên trong khi bạn làm lớp men. Cho kem, sô cô la và mật ong vào chảo vừa và nấu trên lửa vừa thấp cho đến khi sô cô la tan chảy và bạn có một hỗn hợp mịn, có thể rót được. Đặt bánh lên giá lưới đặt trên khay nướng có lót giấy da và rưới lớp men lên trên, đảm bảo phủ kín toàn bộ bánh. Dùng một lát cá để cẩn thận chuyển bánh vào đĩa phục vụ và để lớp men đông lại. Để trang trí, rắc một ít bột vàng ăn được, nếu bạn thích. Unice, chiếc bánh này sẽ giữ được tới 5 ngày. Sau khi đá, thưởng thức trong vòng 3 ngày - chỉ cần bảo quản trong tủ lạnh nhưng lấy ra trước khi dùng và ăn ở nhiệt độ phòng.', NULL, '2026-05-15 14:56:48', '2026-05-16 12:35:35'),
(4851, 731, 1, 'Làm nóng lò nướng ở nhiệt độ 180C/160C quạt/khí 4. Bơ và lót khuôn bánh dạng lò xo 23cm. Cho 150g quả hồ trăn vào máy xay thực phẩm và xay cho đến khi nghiền mịn. Cho bột mì, bột nở và một chút muối vào tô trộn đều. Đánh bơ và đường trong một tô riêng cho đến khi mịn và nhạt màu, khoảng 5 phút. Đập từng quả trứng vào, đánh đều trong 1 phút sau mỗi lần thêm trứng cho đến khi hết trứng. Đánh đều vani, sau đó trộn nhẹ nhàng hỗn hợp bột vào. Cẩn thận múc từng thìa vào khuôn đã chuẩn bị sẵn và nướng trong 35-40 phút cho đến khi xiên que vào giữa que xiên ra sạch sẽ. Đặt sang một bên để nguội hoàn toàn trên giá lưới trong hộp thiếc.', NULL, '2026-05-15 14:56:50', '2026-05-15 14:56:50'),
(4853, 731, 2, 'Trong khi đó, rây đường bột vào tô, sau đó cho mascarpone, kem đôi và bột hồ trăn vào. Đánh đều cho đến khi hòa quyện, sau đó để vào tủ lạnh khoảng 20-30 phút cho đến khi đặc lại như thìa.', NULL, '2026-05-15 14:56:50', '2026-05-16 12:35:35'),
(4855, 731, 3, 'Dùng dao răng cưa cắt đôi chiếc bánh đã nguội theo chiều ngang để bạn có hai lớp. Đặt lớp dưới cùng lên đĩa hoặc đế bánh và phết lên một thìa kem hồ trăn. Phủ một ít quả mâm xôi lên trên để phủ kín bánh. Phủ nửa miếng bọt biển còn lại lên trên, sau đó phủ phần kem còn lại lên trên và các mặt của bánh. Rải phần quả mâm xôi cuối cùng, quả hồ trăn còn lại và vỏ chanh để phục vụ. Sẽ giữ lạnh trong hộp kín trong hai ngày.', NULL, '2026-05-15 14:56:50', '2026-05-16 12:35:35'),
(4856, 732, 1, 'Đối với bánh sô cô la: Chuẩn bị sẵn sàng tất cả nguyên liệu. Bột bánh quy oreo, chút muối và trộn sữa ấm nếu cần và làm bột bánh. Thêm bột nở và giấm vào rồi trộn đều.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4857, 732, 2, 'Bôi mỡ vào một hộp thiếc có đáy lỏng lẻo. Đổ một lớp bột dày 1 cm.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4858, 732, 3, 'Nướng trong lò đã làm nóng trước ở nhiệt độ 160°C trong 7-8 phút hoặc cho đến khi lấy dao ra sạch sẽ. Làm mát trên giá dây.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4859, 732, 4, 'Đối với bột hồ trăn tự làm: Chuẩn bị tất cả các nguyên liệu làm bột hồ trăn. Làm tan chảy một chút sô cô la trắng trên nồi hơi đôi. (nếu không lưỡi trộn có thể bị gãy) Nghiền thành bột thô quả hồ trăn trong máy trộn. Thêm sữa đặc vào.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4860, 732, 5, 'Thêm sô cô la trắng và sữa đã đun nóng nhẹ và hơi tan chảy vào theo yêu cầu rồi nghiền thành bột nhão mịn. (Có thể thêm màu thực phẩm xanh. Tôi thì không.)', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4861, 732, 6, 'Đối với Kunafa: Trong kadhaai, hãy lấy ghee và nướng sevaiiya ở tốc độ chậm. Tiếp tục khuấy cho đến khi tỏa ra mùi thơm rang dễ chịu. Làm mát nó. Thêm bột hồ trăn tự làm vào. Trộn đều.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4862, 732, 7, 'Đánh môi Kunafa đã sẵn sàng. Trải một lớp 2 cm lên bánh sô cô la đã nguội.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4863, 732, 8, 'Đun chảy sô cô la đen và malai đã lọc và chuẩn bị ganache sô cô la. Làm nguội và đổ lên lớp Kunafa.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4864, 732, 9, 'Trang trí bánh sô cô la Pistachio Kunafa với quả hồ trăn cắt nhỏ và quả bóng bạc. Để trong tủ lạnh 2-3 tiếng. Sau đó tháo bánh Kunafa ra.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4865, 732, 10, 'Tôi cũng đã chuẩn bị bánh nướng Kunafa. Cắt và thưởng thức. Chiếc bánh trông đẹp đến mức chúng ta có thể lưu nó hoặc có nó!! ☺', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4866, 732, 11, 'Mặt cắt ngang của Bánh sô cô la Pistachio Kunafa.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4867, 732, 12, 'Hãy cùng gia đình và bạn bè thưởng thức món ngon ngọt ngào mới trong mùa lễ hội này nhé.', NULL, '2026-05-15 14:56:52', '2026-05-15 14:56:52'),
(4868, 733, 1, 'Làm nóng lò ở nhiệt độ 170C/150C quạt/gas 3½. Lót giấy nướng vào khay nướng nông có kích thước 30 x 22cm. Rây bột mì và trộn với cacao rồi để sang một bên. Đánh lòng trắng trứng cho đến khi bông cứng, sau đó thêm đường vào từng mẻ nhỏ. Cho từng lòng đỏ trứng vào, đánh liên tục. Đổ hỗn hợp bột vào và nhẹ nhàng gấp mọi thứ lại với nhau bằng thìa. Đổ bột đã chuẩn bị vào khuôn có lót giấy nến và nướng trong 35 phút. Để nguội trong 5 phút, lấy ra khỏi khuôn và lót lại khuôn bằng giấy nướng.', NULL, '2026-05-15 14:56:55', '2026-05-15 14:56:55'),
(4870, 733, 2, 'Để làm bánh trứng đường, đánh lòng trắng cho đến khi cứng, sau đó cho từ từ đường vào, mỗi lần một muỗng canh. Khi bạn có một chiếc bánh trứng đường cứng và sáng bóng, hãy cho quả óc chó cắt nhỏ, bột mì và củ hành vào. Đổ hỗn hợp vào khuôn đã lót lại và nấu trong 40 phút ở cùng nhiệt độ. Lấy ra khỏi lò và để nguội.', NULL, '2026-05-15 14:56:55', '2026-05-16 12:35:35'),
(4872, 733, 3, 'Đối với phần men sô-cô-la, đun kem trên lửa nhỏ rồi tắt bếp, đổ sô-cô-la cắt nhỏ vào và trộn đều cho đến khi tan chảy và trở nên sáng bóng.', NULL, '2026-05-15 14:56:55', '2026-05-16 12:35:35'),
(4874, 733, 4, 'Cắt bánh bông lan sô cô la đã nguội và bánh trứng đường thành hai lớp. Đặt meringue hạt lên trên lớp xốp dưới cùng và rắc một ít quả óc chó đã để sẵn lên trên. Thêm một lớp meringue nữa và sau đó là lớp bánh xốp sô cô la phía trên và phủ men sô cô la lên trên. Trang trí với quả óc chó. Bánh đã làm xong cho vào tủ lạnh khoảng 1-2 tiếng trước khi ăn.', NULL, '2026-05-15 14:56:55', '2026-05-16 12:35:35'),
(4876, 734, 1, 'Để làm men, trộn men với đường và bột mì rồi cho sữa ấm vào khuấy đều. Đặt sang một nơi ấm áp trong 30 phút.', NULL, '2026-05-15 14:56:59', '2026-05-16 12:35:35'),
(4878, 734, 2, 'Đối với phần bột, cho lòng đỏ trứng vào tô chịu nhiệt rồi thêm đường và đường vani vào. Đặt bát lên chảo nước sôi và đánh cho đến khi mịn và đặc.', NULL, '2026-05-15 14:56:59', '2026-05-16 12:35:35'),
(4880, 734, 3, 'Rây bột vào tô của máy trộn đứng, thêm lòng đỏ đã đánh bông và kem ấm vào, trộn đều, sau đó thêm một chút muối và men. Tập hợp lại thành khối bột và nhào trong 10 phút (hoặc 15-20 nếu làm bằng tay).', NULL, '2026-05-15 14:56:59', '2026-05-16 12:35:35'),
(4882, 734, 4, 'Khi bột hết dính tay, đổ bơ tan chảy đã nguội vào và nhào thêm vài phút. Che lại bằng một miếng vải và để ở nơi ấm áp để ủ ít nhất 1 giờ-1 giờ 30 phút.', NULL, '2026-05-15 14:56:59', '2026-05-16 12:35:35');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(4884, 734, 5, 'Trộn mứt với hạnh nhân xay và cho vào túi bắt kem hoặc ống tiêm mứt. Chia bột thành 16 phần và tạo hình thành bánh rán. Đậy nắp và để tăng trong 30 phút.', NULL, '2026-05-15 14:56:59', '2026-05-16 12:35:35'),
(4886, 734, 6, 'Đổ một phần ba dầu hoặc mỡ lợn đun chảy vào chảo sâu lòng hoặc nồi chiên ngập dầu rồi đun nóng đến nhiệt độ 180C – nếu bạn không có nhiệt kế, hãy cho một miếng bánh mì nhỏ vào. Dầu đã sẵn sàng khi có màu nâu trong khoảng 30 giây. Thêm bánh rán và chiên, lật chúng một lần trong khoảng 1-2 phút cho mỗi mặt (một vòng mỏng nhẹ hơn sẽ hình thành ở giữa). Sau khi vớt ra, hãy chắt bớt mỡ thừa trên giấy ăn.', NULL, '2026-05-15 14:56:59', '2026-05-16 12:35:35'),
(4887, 735, 1, 'Cho bột mì, trứng, sữa, nước và muối vào tô lớn rồi dùng máy trộn cầm tay trộn đều cho đến khi thu được hỗn hợp bột mịn, không vón cục.', NULL, '2026-05-15 14:57:01', '2026-05-15 14:57:01'),
(4888, 735, 2, 'Lúc này, trộn bơ hoặc dầu thực vật vào. Ngoài ra, bạn có thể dùng chúng để phết dầu vào chảo trước khi chiên từng chiếc bánh.', NULL, '2026-05-15 14:57:01', '2026-05-15 14:57:01'),
(4889, 735, 3, 'Làm nóng chảo chống dính trên lửa vừa, sau đó đổ bột vào, xoay chảo để bột dàn đều.', NULL, '2026-05-15 14:57:01', '2026-05-15 14:57:01'),
(4890, 735, 4, 'Khi bánh bắt đầu bong ra một chút ở hai bên và mặt trên không còn ướt nữa, hãy lật bánh và chiên nhanh mặt còn lại.', NULL, '2026-05-15 14:57:01', '2026-05-15 14:57:01'),
(4891, 735, 5, 'Chuyển sang đĩa. Nấu phần bột còn lại cho đến khi hết.', NULL, '2026-05-15 14:57:01', '2026-05-15 14:57:01'),
(4892, 735, 6, 'Ăn nóng với nhân tùy thích.', NULL, '2026-05-15 14:57:01', '2026-05-15 14:57:01'),
(4893, 736, 1, 'BƯỚC 1', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4894, 736, 2, 'Cuộn bánh ngọt', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4895, 736, 3, 'Trộn bột mì và đường bột rồi dùng bột này để phủi bụi lên bề mặt làm việc. Cán bột thành hình chữ nhật có kích thước 45 x 30cm. Cuộn lại theo chiều dọc để tạo thành hình xúc xích dài.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4896, 736, 4, 'BƯỚC 2', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4897, 736, 5, 'Cắt bánh thành từng viên tròn', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4898, 736, 6, 'Cắt bánh thành 24 bánh, dày khoảng 1-2 cm.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4899, 736, 7, 'BƯỚC 3', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4900, 736, 8, 'Cán mỏng từng phần bánh ngọt', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4901, 736, 9, 'Dùng cán cán lăn nhẹ từng bánh sao cho vừa với 2 hộp bánh cổ tích chống dính 12 lỗ.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4902, 736, 10, 'BƯỚC 4', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4903, 736, 11, 'Nhấn bánh ngọt vào hộp thiếc', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4904, 736, 12, 'Nhấn các vòng bánh ngọt vào khuôn và nặn vào khuôn để tạo thành những chiếc vỏ mỏng. Thư giãn cho đến khi cần thiết.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4905, 736, 13, 'BƯỚC 5', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4906, 736, 14, 'Làm xi-rô truyền', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4907, 736, 15, 'Làm nóng lò ở 220C/quạt 200C/gas 7. Làm si-rô đường bằng cách cho đường, 200ml nước, vỏ chanh và thanh quế vào đun sôi. Giảm cho đến khi có dạng siro, để nguội, sau đó loại bỏ quế và chanh. Đánh trứng, lòng đỏ trứng và bột ngô cho đến khi mịn trong một chảo lớn khác.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4908, 736, 16, 'BƯỚC 6', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4909, 736, 17, 'Làm sữa trứng', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4910, 736, 18, 'Đun nóng sữa và hạt vani trong chảo riêng cho đến khi vừa sôi. Từ từ đổ sữa nóng lên trứng và bột ngô, sau đó đun trên lửa nhỏ, khuấy liên tục.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4911, 736, 19, 'BƯỚC 7', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4912, 736, 20, 'Thêm xi-rô vào sữa trứng', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4913, 736, 21, 'Thêm xi-rô đường đã nguội vào sữa trứng và đánh cho đến khi hơi đặc lại.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4914, 736, 22, 'BƯỚC 8', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4915, 736, 23, 'Đổ sữa trứng vào hộp thiếc', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4916, 736, 24, 'Đổ sữa trứng qua rây. Đổ vào các hộp bánh ngọt và nướng trong 15 phút cho đến khi bánh vàng và sữa trứng chuyển sang màu sẫm.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4917, 736, 25, 'BƯỚC 9', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4918, 736, 26, 'mát mẻ và bụi với đường đóng băng', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4919, 736, 27, 'Để nguội hoàn toàn trong hộp thiếc, sau đó rây đường bột và quế xay để thưởng thức.', NULL, '2026-05-15 14:57:03', '2026-05-15 14:57:03'),
(4920, 737, 1, 'Đối với bánh xốp, làm nóng lò nướng ở nhiệt độ 180 độ C và chuẩn bị một hoặc hai khuôn bánh 20cm/8 inch. Dòng dưới cùng với giấy da. Sau đó chia trứng thành lòng trắng và lòng đỏ trứng. Dùng tô lớn hơn để đựng lòng đỏ trứng. Nếu bạn có bát thủy tinh hoặc kim loại, hãy dùng bát đó để đánh lòng trắng trứng. Hãy chắc chắn rằng bát không có chất béo/dầu mỡ và máy trộn của bạn đã được làm sạch đúng cách. Đầu tiên, đánh lòng trắng trứng ở tốc độ trung bình với một chút muối cho đến khi tạo thành chóp mềm. Đặt sang một bên. Không cần làm sạch máy trộn, hãy đánh lòng đỏ trứng với đường. Đánh cho đến khi màu trở nên nhạt hơn nhiều và bạn có được hỗn hợp kem đặc. Việc này thường mất vài phút.', NULL, '2026-05-15 14:57:05', '2026-05-15 14:57:05'),
(4921, 737, 2, 'Nhẹ nhàng đổ 1/3 lòng trắng trứng lên trên hỗn hợp lòng đỏ trứng rồi rây bột mì và bột bắp lên trên. Đừng bỏ qua bước này. Điều quan trọng là hỗn hợp bột đã được rây. Nhẹ nhàng trộn tất cả các thành phần bằng thìa. Cố gắng kết hợp hỗn hợp bột mì và lòng trắng trứng mà không làm mất khối lượng. Thêm 2/3 lòng trắng trứng đã đánh bông cuối cùng vào và trộn nhẹ nhàng. Đừng trộn quá nhiều. Đổ bột vào khuôn bánh đã chuẩn bị sẵn và nướng ngay. Đừng để bột nghỉ quá lâu vì bột sẽ nhanh bị mất khối lượng. Nướng trong 35 phút nếu sử dụng một dạng lò xo hoặc 25 phút nếu sử dụng hai dạng. Để nguội một chút trước khi nhẹ nhàng lấy chúng ra khỏi khuôn. Mẹo: nếu làm hôm trước, hãy bọc trong màng bọc thực phẩm, khi nguội sẽ dễ cắt làm đôi hơn nhiều.', NULL, '2026-05-15 14:57:05', '2026-05-15 14:57:05'),
(4922, 737, 3, 'Đối với meringue, đánh lòng trắng trứng cho đến khi tạo thành chóp mềm, thêm chút muối và tiếp tục đánh ở tốc độ cao đồng thời thêm đường. Đánh ít nhất ba phút nữa cho đến khi bóng và sáng bóng. Dùng bánh trứng đường tạo hình những ngôi sao nhỏ hoặc các hình dạng khác trên khay nướng có lót giấy da. Sấy khô khoảng 45 phút ở nhiệt độ 100 độ C trong lò. Giữ trong hộp kín cho đến khi sử dụng tiếp.', NULL, '2026-05-15 14:57:05', '2026-05-15 14:57:05'),
(4923, 737, 4, 'Đối với phần nhân, đánh kem đặc, chiết xuất vani và đường cho đến khi tạo thành chóp cứng, cắt đào thành từng lát mỏng. Cắt bánh thành bốn lớp, việc này sẽ dễ thực hiện hơn nhiều khi các lớp bánh nguội. Quét một ít nước đào còn sót lại lên lớp bánh, sau đó phết một lớp kem mỏng xung quanh mép, đặt những lát đào vào giữa trên lớp đầu tiên trên bánh, lớp thứ hai chỉ phết dulce de leche. Lặp lại lớp với nước ép đào, kem tươi và đào cho lớp thứ ba và lớp cuối cùng. Hãy nhớ dự trữ đủ lát đào cho phần trên cùng. Phết một lớp kem mỏng lên các mặt bánh và trang trí vài bông hoa hồng xung quanh mép nếu muốn. Đun nóng nước đào rồi trộn bột bắp với một chút nước cho đến khi không còn vón cục. Khi nước ép đã nóng, thêm bột bắp vào và khuấy đều cho đến khi men đặc lại. Đổ đào của lớp bánh trên cùng. Nghiền nát meringue và vỗ nhẹ xung quanh các mặt. Phục vụ ngay lập tức.', NULL, '2026-05-15 14:57:05', '2026-05-15 14:57:05'),
(4924, 738, 1, 'Trong một tô lớn, dùng máy trộn điện, trộn bơ và đường cho đến khi hỗn hợp nhạt màu.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4925, 738, 2, 'Thêm trứng và vani và trộn.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4926, 738, 3, 'Trong một bát khác, trộn bột mì và bột nở.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4927, 738, 4, 'Thay thế hỗn hợp bột và sữa vào hỗn hợp bơ.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4928, 738, 5, 'Đổ vào chảo mỡ 13 inch x 9 inch.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4929, 738, 6, 'SỐT MAPLE.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4930, 738, 7, 'Trong một cái nồi lớn, đun sôi xi-rô, đường nâu, kem và bơ rồi khuấy liên tục.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4931, 738, 8, 'Giảm nhiệt và nấu nhẹ nhàng trong 2 phút hoặc cho đến khi nước sốt giảm đi một chút.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4932, 738, 9, 'Đổ nước sốt nhẹ nhàng lên bánh.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4933, 738, 10, 'Nướng ở nhiệt độ 325°f (160°c) khoảng 35 phút hoặc cho đến khi bánh có màu nâu nhạt và khi cắm tăm vào thấy tăm sạch sẽ.', NULL, '2026-05-15 14:57:08', '2026-05-15 14:57:08'),
(4934, 739, 1, 'Đặt bí ngô vào nồi lớn, đổ nước vào và đun sôi. Đậy nắp và đun nhỏ lửa trong 15 phút hoặc cho đến khi mềm. Xả bí ngô; để nguội.', NULL, '2026-05-15 14:57:15', '2026-05-15 14:57:15'),
(4935, 739, 2, 'Làm nóng lò nướng ở nhiệt độ quạt/gas 180C/160C 4. Cán bột bánh trên bề mặt đã rắc bột mì nhẹ và dùng khuôn này lót khuôn bánh tart có đáy rời 22cm. Thư giãn trong 15 phút. Lót bánh bằng giấy nướng và đậu nướng, sau đó nướng trong 15 phút. Lấy đậu và giấy ra, nấu thêm 10 phút nữa cho đến khi phần đế có màu vàng nhạt và giống bánh quy. Lấy ra khỏi lò và để nguội một chút.', NULL, '2026-05-15 14:57:15', '2026-05-15 14:57:15'),
(4936, 739, 3, 'Tăng lò nướng lên 220C/200C quạt/gas 7. Đẩy bí ngô đã nguội qua rây vào tô lớn. Trong một bát riêng, trộn đường, muối, nhục đậu khấu và một nửa số quế. Trộn trứng đã đánh tan, bơ tan chảy và sữa, sau đó thêm vào bí đỏ nghiền nhuyễn và khuấy đều. Đổ vào vỏ bánh tart và nấu trong 10 phút, sau đó giảm nhiệt độ xuống 180C/160C quạt/gas 4. Tiếp tục nướng trong 35-40 phút cho đến khi nhân vừa chín.', NULL, '2026-05-15 14:57:15', '2026-05-15 14:57:15'),
(4937, 739, 4, 'Để nguội rồi lấy bánh ra khỏi khuôn. Trộn phần quế còn lại với đường bột và phủ lên mặt bánh. Phục vụ ướp lạnh.', NULL, '2026-05-15 14:57:15', '2026-05-15 14:57:15'),
(4939, 740, 1, 'Cho lá gelatine vào tô, đổ nước ấm vào và ngâm trong 5 phút. Xả và vắt hết nước thừa.', NULL, '2026-05-15 14:57:19', '2026-05-16 12:35:35'),
(4941, 740, 2, 'Cho quả mâm xôi vào chảo trên lửa vừa thấp cùng với đường và nước cốt chanh. Nấu trong 5-6 phút cho đến khi quả mọng bị hỏng hoàn toàn. Đẩy hỗn hợp qua rây đặt trên bát, loại bỏ hạt. Khuấy lá gelatine cho đến khi tan (nếu không tan thì đổ hỗn hợp vào chảo sạch và đun nóng nhẹ cho đến khi tan). Đặt sang một bên để nguội trong 15 phút.', NULL, '2026-05-15 14:57:19', '2026-05-16 12:35:35'),
(4943, 740, 3, 'Dùng máy đánh trứng đánh kem đến bông mềm, sau đó nhẹ nhàng trộn hỗn hợp quả mâm xôi vào. Múc từng thìa ramekins hoặc khuôn và để lạnh qua đêm hoặc ít nhất 6 giờ. Ăn kèm với quả mâm xôi rải rác trên đầu.', NULL, '2026-05-15 14:57:19', '2026-05-16 12:35:35'),
(4944, 741, 1, 'Làm nóng lò ở 180C/350F/Gas 4 và lót giấy nướng vào khay nướng.', NULL, '2026-05-15 14:57:22', '2026-05-15 14:57:22'),
(4945, 741, 2, 'Trộn bột mì, đường và bột nở vào tô rồi trộn đều với bơ đã cắt nhỏ cho đến khi hỗn hợp trông giống như vụn bánh mì, sau đó trộn hoa quả khô vào.', NULL, '2026-05-15 14:57:22', '2026-05-15 14:57:22'),
(4946, 741, 3, 'Trong một tô sạch, đánh trứng và sữa cùng với chiết xuất vani.', NULL, '2026-05-15 14:57:22', '2026-05-15 14:57:22'),
(4947, 741, 4, 'Thêm hỗn hợp trứng vào các nguyên liệu khô và dùng thìa khuấy đều cho đến khi hỗn hợp hòa quyện với nhau thành một khối bột dày, vón cục. Thêm một thìa cà phê sữa nếu bạn thực sự cần để làm cho hỗn hợp dính lại với nhau.', NULL, '2026-05-15 14:57:22', '2026-05-15 14:57:22'),
(4948, 741, 5, 'Đặt thìa hỗn hợp có kích thước bằng quả bóng golf lên khay nướng đã chuẩn bị sẵn. Chừa khoảng trống giữa chúng vì chúng sẽ dẹt và nở ra để tăng gấp đôi kích thước trong quá trình nướng.', NULL, '2026-05-15 14:57:22', '2026-05-15 14:57:22'),
(4949, 741, 6, 'Nướng trong 15-20 phút, cho đến khi có màu vàng nâu. Lấy ra khỏi lò, để nguội trong vài phút rồi đặt chúng lên giá lưới cho nguội.', NULL, '2026-05-15 14:57:22', '2026-05-15 14:57:22'),
(4950, 742, 1, 'Lót một khay nướng hình vuông 8 inch bằng giấy sáp hoặc giấy bạc và phủ một lớp xịt chống dính.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4951, 742, 2, 'Đổ ½ cốc kẹo dẻo thu nhỏ vào đáy đĩa nướng đã lót giấy.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4952, 742, 3, 'Trong một chiếc bát an toàn với lò vi sóng, trộn sô-cô-la chip và bơ đậu phộng. Cho hỗn hợp sô cô la vào lò vi sóng trong khoảng thời gian 20 giây, khuấy đều giữa mỗi khoảng thời gian cho đến khi sô cô la tan chảy.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4953, 742, 4, 'Thêm chiết xuất vani và khuấy đều cho đến khi mịn.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4954, 742, 5, 'Dự trữ 2 muỗng canh hạnh nhân hoặc đậu phộng cắt nhỏ và đặt sang một bên.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4955, 742, 6, 'Gấp 1 ½ cốc kẹo dẻo thu nhỏ và các loại hạt cắt nhỏ còn lại vào hỗn hợp sô cô la.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4956, 742, 7, 'Chuyển hỗn hợp sô cô la vào chảo đã chuẩn bị sẵn và dàn đều thành một lớp. Ngay lập tức phủ các loại hạt đã cắt nhỏ dành riêng và các miếng cẩm quỳ hoặc kẹo dẻo thu nhỏ bổ sung nếu sử dụng.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4957, 742, 8, 'Làm lạnh trong 4 giờ hoặc cho đến khi đông lại.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4958, 742, 9, 'Lấy giấy nến và giấy sáp ra khỏi chảo. Cẩn thận bóc toàn bộ giấy sáp ra khỏi kẹo mềm.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4959, 742, 10, 'Cắt kẹo mềm thành từng miếng vừa ăn và thưởng thức.', NULL, '2026-05-15 14:57:24', '2026-05-15 14:57:24'),
(4960, 743, 1, 'Trong một tô vừa, trộn lòng đỏ trứng, phô mai philly và bột nở bằng máy trộn cầm tay. Cẩn thận bắt đầu thêm bột. Khi hỗn hợp không được trộn đều và trông giống như dăm gỗ, hãy tắt máy trộn và dùng tay nhào bột.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4961, 743, 2, 'Tạo một cuộn và bọc trong giấy bạc và để đông trong 15 phút. Lúc này làm nóng lò ở nhiệt độ 375.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4962, 743, 3, 'Lấy bột ra và tách làm đôi. Cuộn và cắt trangle 3 inch.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4963, 743, 4, 'Làm càng nhiều càng tốt và đặt một thìa mứt nhỏ vào giữa mỗi miếng. Cuộn chúng thành hình bánh sừng bò.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4964, 743, 5, 'Đặt bánh sừng bò lên khay nướng đã phết dầu mỡ và nướng trong 10-12 phút hoặc cho đến khi vàng.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4965, 743, 6, 'Lặp lại với phần bột còn lại.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4966, 743, 7, 'Khi lấy ra, bạn đặt sang một bên và rắc đường bột lên trên.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4967, 743, 8, 'Điều này tạo ra khoảng 3 mẻ, mỗi mẻ 20 bánh.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4968, 743, 9, 'Tổng số khoảng 60 cookie.', NULL, '2026-05-15 14:57:31', '2026-05-15 14:57:31'),
(4969, 744, 1, '1) Nghiền bánh quy và bánh quy xoắn trong máy xay thực phẩm và trộn bánh quy với bơ tan chảy. Trải trên đáy hộp thiếc dạng lò xo sâu 8 inch/20cm và ấn chặt xuống. Để trong tủ lạnh trong khi bạn làm phần còn lại!', NULL, '2026-05-15 14:57:33', '2026-05-15 14:57:33'),
(4970, 744, 2, '2) Sử dụng máy trộn điện, tôi sử dụng KitchenAid có kèm theo máy đánh trứng, đánh kem phô mai, vani và đường bột cho đến khi mịn, sau đó thêm caramen và đánh lại cho đến khi mịn và không bị vón cục – việc này có thể mất vài phút, tôi đánh ở tốc độ nửa tốc độ nên không quá nhanh hay quá chậm!', NULL, '2026-05-15 14:57:33', '2026-05-15 14:57:33'),
(4971, 744, 3, '3) Đổ kem đôi & muối mảnh vào và tiếp tục đánh trong vài phút cho đến khi nó đặc và giống như mousse (tôi trộn ở tốc độ trung bình, cấp 6/10) – Bây giờ, việc này có thể mất tới 5 phút tùy thuộc vào máy trộn của bạn, nhưng bạn phải kiên trì – nó sẽ tự giữ hoàn toàn khi trộn xong (giống như bánh trứng đường!) Nếu bạn không trộn đủ, nó sẽ không đủ cứng, nhưng đừng mất kiên nhẫn và đánh thật nhanh vì điều đó sẽ làm it split! Trải đều trên đế bánh quy và để trong tủ lạnh qua đêm.', NULL, '2026-05-15 14:57:33', '2026-05-15 14:57:33'),
(4972, 744, 4, '4) Cẩn thận lấy Bánh Phô mai ra khỏi hộp thiếc và trang trí bánh pho mát – Tôi rưới một ít caramen dự phòng, sau đó là một ít Bắp rang bơ bơ cứng và nhiều bánh quy xoắn nữa!', NULL, '2026-05-15 14:57:33', '2026-05-15 14:57:33'),
(4973, 745, 1, 'Để làm bánh ngọt, cho bột mì và muối vào tô lớn. Trộn đều. Thêm các khối bơ và mỡ vào rồi trộn (tôi thích dùng tay để trộn chất béo vào bột, nhưng bạn có thể dùng máy xay bánh ngọt) cho đến khi nó trông giống như bột yến mạch thô với một ít hạt đậu còn lại. Đặt quả trứng vào khuôn có kích thước 2 cốc và đánh bằng nĩa. Đổ giấm và nước lạnh vừa đủ vào đến vạch 1 cốc. Khuấy hỗn hợp này vào hỗn hợp bột, cho đến khi bột dính vào nhau. Tôi cũng thích sử dụng tay cho phần này, nhưng một chiếc thìa gỗ cũng có thể dùng được. Cố gắng không trộn nó quá nhiều.', NULL, '2026-05-15 14:57:36', '2026-05-15 14:57:36'),
(4974, 745, 2, 'Trên một mặt phẳng đã rắc chút bột mì, vo khối bột thành một khối và chia thành 5 phần đều nhau. Định hình từng phần vào đĩa và bọc chặt bằng nhựa. Làm lạnh 2 đĩa này trong 1 giờ. Đông lạnh 3 cái còn lại trong túi đông lạnh có thể khóa lại để sử dụng sau này. Bánh bảo quản tốt trong tủ đông tối đa 2 tháng.', NULL, '2026-05-15 14:57:36', '2026-05-15 14:57:36'),
(4975, 745, 3, 'Làm nóng lò ở nhiệt độ 350°F. Đặt giá đỡ ở phần dưới của lò. Lót giấy nhôm lên khay nướng để hứng những giọt nước nhỏ giọt.', NULL, '2026-05-15 14:57:36', '2026-05-15 14:57:36'),
(4976, 745, 4, 'Trên một bề mặt đã phủ bột nhẹ, cán 1 đĩa bánh ngọt thành hình tròn 12 inch hoặc khoảng đó. Đặt nó vào đáy đĩa bánh 9 inch, với phần bánh ngọt nhô ra các cạnh của đĩa bánh.', NULL, '2026-05-15 14:57:36', '2026-05-15 14:57:36'),
(4977, 745, 5, 'Để làm nhân, cho quả saskatoon vào tô lớn rồi cho 1/2 cốc đường và bột ngô vào khuấy đều cho đến khi hòa quyện. Đổ hỗn hợp quả mọng vào đáy bánh. Chấm với bơ. Trên một bề mặt đã phủ bột mì nhẹ, lăn bánh ngọt thành một vòng tròn 12 inch khác để làm lớp vỏ trên cùng. Sử dụng thước kẻ để hướng dẫn bạn khi cắt bánh ngọt thành 6 dải dài, rộng để giữ cho các cạnh thẳng. Lưu 2 phần cuối trong trường hợp bạn cần thực hiện bất kỳ thao tác vá nào. Tôi thích những dải bánh rộng, nhưng nếu bạn thích vẻ ngoài mỏng hơn, hãy thoải mái cắt những dải bánh ngọt mỏng. Đan các dải bánh ngọt từ trên xuống dưới, đảm bảo chúng kết nối với các mép của vỏ bánh. Gấp các cạnh của lớp vỏ dưới cùng, nhét các đầu lưới vào. Điều này sẽ giúp giữ nước và mang lại vẻ ngoài mộc mạc.', NULL, '2026-05-15 14:57:36', '2026-05-15 14:57:36'),
(4978, 745, 6, 'Nếu muốn có vẻ ngoài gọn gàng, sạch sẽ hơn, bạn có thể cắt bớt những phần nhô ra và gấp mép bằng nĩa. Quét mặt trên của chiếc bánh bằng nước rửa trứng. Rắc muỗng canh đường còn lại. Đặt chiếc bánh lên khay nướng đã chuẩn bị sẵn và nướng trong khoảng 90 – 100 phút cho đến khi bánh có màu nâu vàng và sủi bọt. Lấy bánh ra khỏi lò và đặt lên giá lưới cho nguội.', NULL, '2026-05-15 14:57:36', '2026-05-15 14:57:36'),
(4979, 745, 7, 'Phục vụ bánh ấm hoặc ở nhiệt độ phòng với kem tươi hoặc kem tươi. Làm 6 phần ăn. Điều này sẽ giữ tốt nếu được bọc bằng nhựa và để trong tủ lạnh tối đa 4 ngày.', NULL, '2026-05-15 14:57:36', '2026-05-15 14:57:36'),
(4980, 746, 1, 'Ngâm gạo nếp với nước ít nhất 1 tiếng rưỡi trước khi sử dụng. Làm khô hạn.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4981, 746, 2, 'Chuẩn bị một khuôn bánh tròn hoặc vuông 9 inch và xịt bằng bình xịt nấu ăn hoặc lót bằng màng bọc thực phẩm.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4982, 746, 3, 'Trộn nước cốt dừa, nước, muối và gạo. Đổ nó vào chảo bánh, phủ các nút lá dứa lên trên.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4983, 746, 4, 'Hấp trong 30 phút.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4984, 746, 5, 'Sau 30 phút, xới cơm và gỡ bỏ nút lá dứa. Sau đó, dùng thìa phết dầu mỡ, dàn phẳng cơm. Đảm bảo không có lỗ/bọt khí và khoảng trống trên cơm, đặc biệt là các mặt.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4985, 746, 6, 'Hấp thêm 10 phút nữa.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4986, 746, 7, 'Trộn nước ép lá dứa, nước cốt dừa, bột mì đa dụng, bột ngô và đường. Trộn đều.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4987, 746, 8, 'Thêm trứng vào và đánh đều rồi lọc vào tô hoặc nồi kim loại cỡ vừa.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4988, 746, 9, 'Đặt hỗn hợp lá dứa lên trên nước sôi (nồi hơi đôi hoặc bain-marie)', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4989, 746, 10, 'Khuấy liên tục và nấu cho đến khi sữa trứng bắt đầu đặc lại. (15 phút)', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4990, 746, 11, 'Đổ mãng cầu lá dứa vào lớp nếp, gõ nhẹ (để tạo bọt khí) rồi hấp tiếp trong 30 phút.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4991, 746, 12, 'Lấy kuih seri muka ra khỏi nồi hấp và để nguội hoàn toàn trước khi cắt thành hình chữ nhật hoặc hình kim cương.', NULL, '2026-05-15 14:57:39', '2026-05-15 14:57:39'),
(4992, 747, 1, 'Đánh trứng, đường và đường vani cho đến khi mịn và bông xốp. Tôi đánh hỗn hợp này bằng máy trộn đứng ở tốc độ trung bình cao trong khoảng 10 phút.', NULL, '2026-05-15 14:57:43', '2026-05-15 14:57:43'),
(4993, 747, 2, 'Rây bột mì và bột bắp rồi thêm vào hỗn hợp. Gấp nhẹ nhàng vào hỗn hợp này; bạn không muốn tất cả không khí bạn thổi vào biến mất.', NULL, '2026-05-15 14:57:43', '2026-05-15 14:57:43'),
(4994, 747, 3, 'Đổ bột vào chảo nướng đã phết dầu mỡ. Nướng đế bánh ở nhiệt độ 180°C/350°F (lò nướng thông thường) trong 30 phút. Bánh chín khi bạn ấn nhẹ lên trên và bánh sẽ đàn hồi trở lại. Để bánh nguội trong khuôn vài phút trước khi lấy bánh ra giá đựng bánh.', NULL, '2026-05-15 14:57:43', '2026-05-15 14:57:43'),
(4995, 747, 4, 'Trong khi đó, hãy chuẩn bị kẹo dẻo và mứt theo công thức nếu bạn chưa làm.', NULL, '2026-05-15 14:57:43', '2026-05-15 14:57:43'),
(4996, 747, 5, 'Để bánh nguội hoàn toàn trước khi cắt. Nếu giống như tôi, bạn sử dụng khuôn lò xo 20 cm/8 inch, hãy cắt bánh thành ba lớp.', NULL, '2026-05-15 14:57:43', '2026-05-15 14:57:43'),
(4998, 748, 1, 'Cho hạnh nhân vào máy xay thực phẩm cho đến khi hầu hết được thái nhỏ, sau đó cho vào tô lớn. Cắt nhỏ quả sung, sau đó xay thành hỗn hợp sệt mịn. Sau đó, cạo hạnh nhân lên, dùng tay trộn đều với trái cây khô, rượu mạnh, mật ong và đinh hương.', NULL, '2026-05-15 14:57:46', '2026-05-16 12:35:35'),
(5000, 748, 2, 'Chia hỗn hợp thành 6 và vo thành từng viên tròn. Đổ hạt mè lên khay, sau đó lăn từng viên vào đó cho đến khi phủ kín. Đậy khay bằng khăn sạch, sau đó để quả sung khô trong một tuần trước khi đóng gói. Sẽ giữ ở nơi mát mẻ trong 2 tháng.', NULL, '2026-05-15 14:57:46', '2026-05-16 12:35:35'),
(5001, 749, 1, 'Cho bột mì và muối vào tô. Thêm mỡ, nho, đường, vỏ chanh và cam.', NULL, '2026-05-15 14:57:49', '2026-05-15 14:57:49'),
(5002, 749, 2, 'Đổ 150ml sữa vào và trộn thành khối bột cứng nhưng ẩm, thêm sữa nếu cần.', NULL, '2026-05-15 14:57:49', '2026-05-15 14:57:49'),
(5003, 749, 3, 'Nặn thành cuộn mỡ dài khoảng 20 cm. Đặt trên một hình chữ nhật lớn của giấy nướng. Quấn lỏng để bánh pudding nổi lên và buộc các đầu bằng dây giống như bánh quy Giáng sinh.', NULL, '2026-05-15 14:57:49', '2026-05-15 14:57:49'),
(5004, 749, 4, 'Đặt nồi hấp lên trên một chảo nước sôi lớn, cho bánh pudding vào nồi hấp, đậy nắp và hấp trong 1 tiếng rưỡi. Thỉnh thoảng đổ nước vào chảo.', NULL, '2026-05-15 14:57:49', '2026-05-15 14:57:49'),
(5005, 749, 5, 'Lấy ra khỏi nồi hấp và để nguội một chút trước khi mở gói. Ăn cắt lát với sữa trứng.', NULL, '2026-05-15 14:57:49', '2026-05-15 14:57:49'),
(5006, 750, 1, 'Làm nóng lò nướng ở nhiệt độ 180C/160C Quạt/Khí 4. Bơ một đĩa chịu nhiệt rộng, nông, dung tích 1,7 lít/3 pint.', NULL, '2026-05-15 14:57:52', '2026-05-15 14:57:52'),
(5007, 750, 2, 'Cho bơ, đường, trứng, bột mì, bột nở, soda bicarbonate và mật đường vào tô trộn. Đánh bằng máy đánh trứng cầm tay điện trong khoảng 30 giây hoặc cho đến khi hòa quyện. Đổ dần dần sữa vào và đánh lại cho đến khi mịn. Đổ vào món ăn đã chuẩn bị. Nướng trong 35–40 phút hoặc cho đến khi nổi lên và có độ đàn hồi ở giữa.', NULL, '2026-05-15 14:57:52', '2026-05-15 14:57:52'),
(5008, 750, 3, 'Để làm nước sốt, cho tất cả nguyên liệu vào nồi và khuấy trên lửa nhỏ cho đến khi đường tan và bơ tan chảy. Đun sôi, khuấy trong một phút.', NULL, '2026-05-15 14:57:52', '2026-05-15 14:57:52'),
(5009, 750, 4, 'Để phục vụ, đổ một nửa nước sốt lên trên bánh pudding trong đĩa nướng. Ăn kèm với kem hoặc kem.', NULL, '2026-05-15 14:57:52', '2026-05-15 14:57:52'),
(5010, 751, 1, 'Đá và cắt chà là thật nhỏ, cho vào tô, sau đó đổ nước sôi vào. Để khoảng 30 phút cho đến khi nguội và ngấm đều, sau đó dùng nĩa nghiền một chút. Khuấy chiết xuất vani. Bơ và bột mì, bảy hộp bánh pudding nhỏ (mỗi hộp khoảng 200ml/7fl oz) và đặt chúng lên khay nướng. Làm nóng lò ở 180C/quạt 160C/gas 4.', NULL, '2026-05-15 14:57:54', '2026-05-15 14:57:54'),
(5011, 751, 2, 'Trong khi ngâm chà là, hãy làm bánh pudding. Trộn bột mì và bicarbonate soda với nhau rồi đánh trứng vào một bát riêng. Đánh bơ và đường với nhau trong một tô lớn trong vài phút cho đến khi hơi kem (hỗn hợp sẽ có dạng hạt do đường). Thêm từng ít trứng vào, đánh đều giữa các lần thêm trứng. Sau đó, đánh trong mật đường đen, dùng thìa kim loại lớn, nhẹ nhàng trộn 1/3 lượng bột mì, sau đó là một nửa sữa vào, cẩn thận không đánh quá kỹ. Lặp lại cho đến khi hết bột và sữa. Khuấy chà là đã ngâm vào bột bánh pudding. Hỗn hợp lúc này có thể trông hơi vón cục và sẽ giống như một khối bột mềm, đặc. Múc đều hỗn hợp vào giữa các khuôn và nướng trong 20-25 phút cho đến khi bánh phồng lên và cứng lại.', NULL, '2026-05-15 14:57:54', '2026-05-15 14:57:54'),
(5012, 751, 3, 'Trong khi đó, cho đường và bơ làm nước sốt vào nồi vừa cùng với một nửa số kem. Đun sôi trên lửa vừa, khuấy đều cho đến khi đường tan hoàn toàn. Khuấy mật đường đen, tăng lửa nhẹ và để hỗn hợp sủi bọt trong 2-3 phút cho đến khi có màu kẹo bơ cứng đậm, thỉnh thoảng khuấy đều để đảm bảo hỗn hợp không bị cháy. Nhấc chảo ra khỏi bếp và đánh phần kem còn lại.', NULL, '2026-05-15 14:57:54', '2026-05-15 14:57:54'),
(5013, 751, 4, 'Lấy bánh pudding ra khỏi lò. Để trong hộp thiếc trong vài phút, sau đó nới lỏng chúng ra khỏi các cạnh của hộp thiếc bằng một con dao pha màu nhỏ trước khi lật chúng ra. Bây giờ bạn có thể phục vụ chúng với nước sốt rưới lên trên, nhưng chúng sẽ còn dính hơn nếu để trong một hoặc hai ngày phủ nước sốt. Để làm điều này, đổ khoảng một nửa nước sốt vào một hoặc hai đĩa phục vụ dùng được trong lò nướng. Đặt những chiếc bánh pudding úp ngược lên trên nước sốt, sau đó đổ phần nước sốt còn lại lên trên. Dùng một lớp giấy bạc bọc lại để nước sốt không bị lem (không cần để lạnh).', NULL, '2026-05-15 14:57:54', '2026-05-15 14:57:54'),
(5014, 751, 5, 'Khi sẵn sàng phục vụ, làm nóng lò nướng ở nhiệt độ 180C/quạt 160C/gas 4. Làm nóng bánh pudding, vẫn đậy nắp trong 15-20 phút hoặc cho đến khi nước sốt sủi bọt. Phục vụ chúng một mình, hoặc với kem hoặc sữa trứng.', NULL, '2026-05-15 14:57:54', '2026-05-15 14:57:54'),
(5015, 752, 1, 'Trong một bát vừa, trộn dâu tây đã cắt vỏ và cắt thành từng phần, 4 muỗng canh đường và 4 muỗng canh rượu mùi, khuấy đều rồi đậy nắp và để trong tủ lạnh ít nhất 1 giờ và tối đa 2 giờ, khuấy một hoặc hai lần.', NULL, '2026-05-15 14:57:56', '2026-05-15 14:57:56'),
(5016, 752, 2, 'Hai bức ảnh dâu tây cắt miếng cho vào bát và một bức ảnh được thêm đường vào bát Hai bức ảnh dâu tây cắt lát cho Strawberry Romanoff', NULL, '2026-05-15 14:57:56', '2026-05-15 14:57:56'),
(5017, 752, 3, 'Ngay trước khi dùng, trong một tô trộn lớn, trộn 1 cốc kem đặc lạnh và 1/4 cốc đường bột, rồi đánh bằng máy trộn điện cho đến khi tạo thành chóp cứng. Dùng thìa trộn 1/4 cốc kem chua vào cho đến khi hòa quyện.', NULL, '2026-05-15 14:57:56', '2026-05-15 14:57:56'),
(5018, 752, 4, 'Để phục vụ, khuấy dâu tây sau đó chia cho 6 ly hoặc bát phục vụ. Bạn có thể rưới một ít xi-rô lên quả mọng nếu thích. Bạn cũng có thể dùng xi-rô này để ngâm bánh. Múc kem lên dâu tây, chia đều. Bạn cũng có thể sử dụng muỗng múc kem có nút bấm để tạo ra một lớp kem tròn đẹp mắt. Phục vụ ngay hoặc ướp lạnh và thưởng thức trong vòng 2 giờ sau khi lắp ráp.', NULL, '2026-05-15 14:57:56', '2026-05-15 14:57:56'),
(5019, 753, 1, 'Vỏ bánh: Cho bột mì, muối và đường vào máy xay thực phẩm rồi xay cho đến khi hòa quyện. Thêm bơ vào và xay cho đến khi hỗn hợp trở nên thô', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5020, 753, 2, 'bữa ăn (khoảng 15 giây). Đổ 1/4 cốc (60 ml) nước chảy chậm và đều qua ống cấp liệu cho đến khi bột vừa dính lại với nhau khi bị ép. Nếu cần thiết, thêm nhiều nước hơn. Không xử lý quá 30 giây.', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5021, 753, 3, 'Lật bột lên bề mặt làm việc của bạn và tập hợp thành một quả bóng. Chia bột làm đôi, ấn dẹt mỗi nửa thành đĩa, bọc lại bằng màng bọc thực phẩm và để trong tủ lạnh khoảng một giờ trước khi sử dụng. Điều này sẽ làm lạnh bơ và làm dịu gluten trong bột.', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5022, 753, 4, 'Sau khi bột đã đủ nguội, lấy một phần bột ra khỏi tủ lạnh và đặt lên bề mặt đã rắc chút bột áo.  Cuộn bánh thành hình tròn 12 inch (30 cm). (Để bánh không bị dính vào quầy và đảm bảo độ dày đồng đều, hãy nhấc bánh lên và xoay một phần tư vòng khi cuộn (luôn lăn từ giữa bánh ra ngoài).) Gấp bột làm đôi và nhẹ nhàng chuyển sang khuôn nướng bánh 9 inch (23 cm). Phủi sạch phần bột thừa và cắt bớt phần bánh ngọt nhô ra thành cạnh 1/2 inch (1,5 cm). Làm lạnh bánh ngọt, bọc bằng màng bọc thực phẩm trong khi bạn làm nhân.', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5023, 753, 5, 'Lấy vòng bánh ngọt thứ hai ra và cuộn thành hình tròn 13 inch (30 cm). Dùng dụng cụ cắt bánh ngọt hoặc dao cắt bánh pizza, cắt bánh ngọt thành các dải khoảng 2 cm (3/4 inch). Đặt các dải bánh ngọt lên khay nướng có lót giấy da, dùng màng bọc thực phẩm bọc lại và để trong tủ lạnh khoảng 10 phút.', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5024, 753, 6, 'Làm nhân đại hoàng dâu tây: Cho dâu tây cắt lát và đại hoàng vào tô lớn. Trong một bát nhỏ trộn đều bột ngô, đường và quế xay.', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5025, 753, 7, 'Lấy vỏ bánh ướp lạnh ra khỏi tủ lạnh. Rắc khoảng 2 thìa hỗn hợp đường lên đáy vỏ bánh. Thêm hỗn hợp đường còn lại vào dâu tây và đại hoàng rồi trộn nhẹ nhàng để kết hợp. Đổ hỗn hợp trái cây vào vỏ bánh đã chuẩn bị sẵn. Rắc trái cây với khoảng 1 thìa nước cốt chanh và chấm 2 thìa bơ.', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5026, 753, 8, 'Lấy bánh lưới ra khỏi tủ lạnh và bắt đầu từ giữa với các dải dài nhất và hướng ra ngoài, đặt một nửa các dải, cách nhau khoảng 1 inch (2,5 cm), lên trên phần nhân. (Sử dụng các dải bánh ngọt ngắn nhất ở các cạnh bên ngoài.) Sau đó, nhẹ nhàng gấp lại khoảng một nửa các dải bánh ngọt khác. Lấy một dải bánh ngọt khác và đặt nó vuông góc lên trên dải bánh ngọt đầu tiên. Mở các dải bánh ngọt phía dưới rồi gấp lại các dải chưa được gấp lại lần đầu. Đặt một dải bánh ngọt khác vuông góc lên trên phần nhân rồi tiếp tục với các dải còn lại. Cắt bớt các cạnh của dải bánh ngọt, để lại phần nhô ra 1 inch (2,5 cm). Bịt kín các mép của dải bánh ngọt bằng cách gấp chúng dưới lớp vỏ bánh ngọt phía dưới và tạo rãnh cho các mép bánh ngọt. Quét sữa lên bánh lưới và rắc một ít đường. Đậy nắp và đặt vào tủ lạnh trong khi làm nóng lò trước ở nhiệt độ 400 độ F (205 độ C) và đặt giá đỡ lò ở một phần ba phía dưới của lò. Đặt một khay nướng có lót giấy nhôm lên giá lò (để hứng bất kỳ vết tràn nào.)', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5027, 753, 9, 'Đặt khay bánh lên khay nướng nóng và nướng bánh trong khoảng 35 phút, sau đó, nếu các mép bánh chuyển sang màu nâu quá nhiều, hãy dùng giấy bạc bọc lại. Tiếp tục nướng bánh khoảng 10 phút nữa hoặc cho đến khi vỏ bánh có màu nâu vàng và nước trái cây bắt đầu sủi bọt.', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5028, 753, 10, 'Lấy bánh ra khỏi lò và đặt lên giá lưới để nguội trong vài giờ. Phục vụ ở nhiệt độ phòng với kem đánh bông nhẹ hoặc kem vani. Thức ăn thừa có thể bảo quản trong tủ lạnh khoảng 3 ngày. Đun nóng lại trước khi phục vụ. Chiếc bánh này có thể được đông lạnh.', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5029, 753, 11, 'Làm một chiếc bánh 9 inch (23 cm).', NULL, '2026-05-15 14:57:59', '2026-05-15 14:57:59'),
(5030, 754, 1, 'Làm nóng lò ở nhiệt độ 350 độ F (175 độ C). Mỡ một đĩa bánh 9 inch.', NULL, '2026-05-15 14:58:01', '2026-05-15 14:58:01'),
(5031, 754, 2, 'Cho đường nâu và bơ vào tô trộn, dùng máy trộn điện đánh đều cho đến khi thành dạng kem và hòa quyện rất tốt, không bị vón cục. Đánh từng quả trứng một, kết hợp quả trứng đầu tiên trước khi thêm quả tiếp theo. Thêm chiết xuất vani và muối; đánh từng ít bột mì vào, sau đó cho sữa vào, tạo thành hỗn hợp bột kem. Đổ bột vào đĩa bánh đã chuẩn bị.', NULL, '2026-05-15 14:58:01', '2026-05-15 14:58:01'),
(5032, 754, 3, 'Nướng trong lò làm nóng trước trong 35 phút; lấy bánh ra, dùng giấy nhôm bọc lại để bánh không bị cháy. Quay trở lại lò nướng và nướng cho đến khi phần giữa và phần trên tạo thành một lớp giòn, khoảng 15 phút nữa. Để bánh nguội đến nhiệt độ phòng, sau đó cho vào tủ lạnh ít nhất 1 giờ trước khi dùng.', NULL, '2026-05-15 14:58:01', '2026-05-15 14:58:01'),
(5033, 755, 1, 'Đế hạnh nhân', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5034, 755, 2, 'Làm nóng lò ở nhiệt độ 345°F (175°C) và tạo khuôn bánh mỡ (tôi dùng khuôn lò xo dài 27 cm) – bạn có thể lót giấy nướng dưới đáy nếu muốn.', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5035, 755, 3, 'Nghiền hạnh nhân trong máy xay hạnh nhân hoặc máy chế biến thực phẩm. Tôi thích giữ chúng thô một chút.', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5036, 755, 4, 'Nhẹ nhàng đánh trứng và đường với nhau cho đến khi hòa quyện (không còn nữa). Khuấy hạnh nhân, bột mì và bột nở.', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5037, 755, 5, 'Đổ bột vào khuôn bánh và nướng trong khoảng 45 – 50 phút, theo dõi để đảm bảo mặt trên không bị cháy.', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5038, 755, 6, 'Kem trứng vàng', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5039, 755, 7, 'Cho lòng đỏ trứng, kem đặc, đường và vani vào nồi. Đun trên lửa vừa/nhỏ trong khi khuấy liên tục cho đến khi hỗn hợp đặc lại – khoảng 15 phút. Tăng lửa nếu hỗn hợp không đặc lại nhưng cẩn thận không đun sôi.', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5040, 755, 8, 'Để hỗn hợp nguội đến nhiệt độ phòng rồi thêm bơ vào. Bạn có thể sử dụng máy trộn điện để đánh kem trứng bông xốp.', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5041, 755, 9, 'Đợi bánh nguội hoàn toàn trước khi lấy ra khỏi khuôn và phủ kem.', NULL, '2026-05-15 14:58:07', '2026-05-15 14:58:07'),
(5042, 756, 1, '1. Chuẩn bị khoai tây', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5043, 756, 2, 'Luộc khoai tây cả vỏ cho đến khi mềm.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5044, 756, 3, 'Để chúng nguội hoàn toàn (tốt nhất là qua đêm), sau đó gọt vỏ và nghiền mịn.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5045, 756, 4, '2. Làm bột', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5046, 756, 5, 'Trong một cái bát, trộn khoai tây nghiền, bột mì, bột báng và muối.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5047, 756, 6, 'Nhào hỗn hợp cho đến khi thu được khối bột mịn, không dính.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5048, 756, 7, '3. Tạo hình Šúĺlance', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5049, 756, 8, 'Chia bột thành nhiều phần và cuộn từng sợi thành sợi dây mỏng (đường kính khoảng 1,5 cm).', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5050, 756, 9, 'Cắt thành từng miếng dài 3 cm và cuộn giữa hai lòng bàn tay để tạo thành những chiếc bánh bao nhỏ.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5051, 756, 10, '4. Nấu bánh bao', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5052, 756, 11, 'Đun sôi một nồi nước muối.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5053, 756, 12, 'Thả từng mẻ bánh bao vào và nấu cho đến khi chúng nổi lên mặt nước (khoảng 2-3 phút).', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5054, 756, 13, 'Xả và chuyển vào một cái bát.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5055, 756, 14, '5. Chuẩn bị Topping', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5056, 756, 15, 'Trong một bát riêng, trộn hạt anh túc xay và đường bột.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5057, 756, 16, 'Đun chảy bơ và giữ nó sẵn sàng.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5058, 756, 17, '6. Lắp ráp món ăn', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5059, 756, 18, 'Rắc bánh bao đã nấu chín với bơ tan chảy.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5060, 756, 19, 'Quăng chúng vào hỗn hợp đường-hạt anh túc cho đến khi được phủ đều.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5061, 756, 20, '7. Phục vụ và thưởng thức', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5062, 756, 21, 'Dùng khi còn ấm, tùy ý có thể rắc thêm đường bột hoặc một chút mật ong.', NULL, '2026-05-15 14:58:12', '2026-05-15 14:58:12'),
(5063, 757, 1, 'Lấy nước ép: Rửa sạch trái cây và lau khô nhẹ nhàng trên giấy ăn – để riêng dâu tây. Cho đường và 3 thìa nước vào chảo lớn. Đun nóng nhẹ cho đến khi đường tan – khuấy vài lần. Đun sôi trong 1 phút, sau đó cho trái cây (không phải dâu tây) vào. Nấu trong 3 phút ở nhiệt độ thấp, khuấy 2-3 lần. Quả sẽ mềm, hầu như còn nguyên vẹn và được bao quanh bởi nước ép màu đỏ sẫm. Đặt một cái rây lên trên một cái bát và đổ trái cây và nước trái cây vào.', NULL, '2026-05-15 14:58:17', '2026-05-15 14:58:17'),
(5064, 757, 2, 'Lót bát bằng màng dính và chuẩn bị bánh mì: Phủ màng bám vào chậu 1,25 lít vì điều này sẽ giúp bạn tạo ra bánh pudding. Chồng hai miếng màng bám vào giữa bát vì việc này sẽ dễ dàng hơn việc cố gắng lấy một tấm giấy dính vào tất cả các đường cong. Để các cạnh nhô ra khoảng 15 cm. Cắt vỏ bánh mì. Cắt đôi 4 miếng bánh mì, hơi nghiêng một chút để tạo thành 2 hình chữ nhật lệch nhau trên mỗi miếng. Cắt 2 lát thành 4 hình tam giác và để nguyên miếng cuối cùng.', NULL, '2026-05-15 14:58:17', '2026-05-15 14:58:17'),
(5065, 757, 3, 'Làm bánh pudding: Nhúng toàn bộ miếng bánh mì vào nước trái cây trong vài giây để tạo lớp phủ. Đẩy cái này vào đáy chậu. Bây giờ nhúng từng miếng hình chữ nhật có hình chữ nhật và ấn xung quanh các cạnh của chậu sao cho chúng khớp với nhau một cách gọn gàng, lần lượt đặt các đầu rộng và hẹp lên nhau. Nếu bạn không thể nhét miếng bánh mì cuối cùng vào cũng không thành vấn đề, chỉ cần cắt thành hình tam giác, nhúng vào nước trái cây và cho vào. Bây giờ, hãy múc trái cây đã mềm vào, thêm dâu tây vào đây đó khi bạn ăn.', NULL, '2026-05-15 14:58:17', '2026-05-15 14:58:17'),
(5066, 757, 4, 'Để hương vị hòa quyện rồi thưởng thức: Nhúng các hình tam giác bánh mì vào nước trái cây và đặt lên trên – dùng kéo cắt bớt phần nhô ra. Giữ nước trái cây còn sót lại cho sau này. Mang màng bám lên và dán lỏng lẻo. Đặt một tấm bên lên trên và đặt lon xuống trọng lượng. Thư giãn trong 6 giờ hoặc qua đêm. Khi thưởng thức, hãy mở màng bọc thực phẩm ra sau đó úp ngược đĩa phục vụ lên trên và lật úp lại. dùng với nước trái cây còn sót lại, bất kỳ loại quả mọng và kem bổ sung nào.', NULL, '2026-05-15 14:58:17', '2026-05-15 14:58:17'),
(5067, 758, 1, 'Đun nóng sữa cho đến khi còn ấm. Thêm men và hòa tan.', NULL, '2026-05-15 14:58:19', '2026-05-15 14:58:19'),
(5068, 758, 2, 'Thêm đường, bạch đậu khấu, vani và khoảng 2/3 lượng bột mì.', NULL, '2026-05-15 14:58:19', '2026-05-15 14:58:19'),
(5069, 758, 3, 'Trộn bột bằng tay hoặc bằng máy trộn có móc bột, từ từ thêm phần bột còn lại vào. Bạn có thể cần nhiều hoặc ít bột mì hơn để tạo thành khối bột không quá dính khi nhào. Khi bột tạo thành một khối đẹp mắt, thêm bơ đã làm mềm vào và tiếp tục nhào bột trong khoảng 10 phút.', NULL, '2026-05-15 14:58:19', '2026-05-15 14:58:19'),
(5070, 758, 4, 'Cán bột thành hình trụ và cắt thành sáu phần bằng nhau. Cuộn từng miếng thành một chiếc bánh tròn và đặt chúng vào khuôn làm bánh muffin/bánh ngọt đã phết dầu mỡ. Đậy nắp và ủ cho đến khi nở gấp đôi (khoảng một giờ).', NULL, '2026-05-15 14:58:19', '2026-05-15 14:58:19'),
(5071, 759, 1, 'Cán bánh ngọt thành hình tròn dày 3 mm trên bề mặt đã phủ bột mì nhẹ và cắt hình tròn 24 cm, dùng đĩa làm hướng dẫn. Dùng nĩa châm nhẹ khắp nơi, bọc màng dính trên khay nướng và để đông trong khi chuẩn bị táo.', NULL, '2026-05-15 14:58:21', '2026-05-15 14:58:21'),
(5072, 759, 2, 'Làm nóng lò ở mức quạt/khí 180C/160C 4. Gọt vỏ, làm tư và bỏ lõi táo. Cho đường vào đĩa Tatin bằng gốm chống cháy 20 cm hoặc chảo rán đế nặng chịu nhiệt 20 cm và đặt trên lửa vừa cao. Nấu đường khoảng 5-7 phút cho đến khi si-rô caramen màu hổ phách sẫm bắt đầu bốc khói thì tắt bếp và cho 60g bơ ướp lạnh thái hạt lựu vào khuấy đều.', NULL, '2026-05-15 14:58:21', '2026-05-15 14:58:21'),
(5073, 759, 3, 'Để làm món Tarte Tatin, trước tiên hãy sắp xếp các miếng táo thật chặt thành hình tròn xung quanh mép đĩa, bo tròn cạnh xuống, sau đó đổ vào giữa theo cách tương tự. Dùng tay ấn nhẹ để đảm bảo không có khoảng trống. Quét trái cây bằng bơ tan chảy.', NULL, '2026-05-15 14:58:21', '2026-05-15 14:58:21'),
(5074, 759, 4, 'Nướng trong lò khoảng 30 phút, sau đó lấy ra và đặt đĩa bánh phồng đông lạnh lên trên - nó sẽ rã đông nhanh chóng. Gấp các cạnh xuống bên trong đĩa và dùng dao chọc vài lỗ trên bánh ngọt để hơi nước thoát ra ngoài. Nướng thêm 40-45 phút nữa cho đến khi bánh có màu vàng nâu và giòn.', NULL, '2026-05-15 14:58:21', '2026-05-15 14:58:21'),
(5075, 759, 5, 'Để nguội đến nhiệt độ phòng trong 1 giờ trước khi dùng dao chạy quanh mép đĩa và úp đĩa lên một đĩa lớn đủ sâu để đựng nước trái cây. Ăn kèm với kem crème fraîche hoặc kem vani.', NULL, '2026-05-15 14:58:21', '2026-05-15 14:58:21'),
(5076, 760, 1, 'Rây các nguyên liệu khô lại với nhau.', NULL, '2026-05-15 14:58:25', '2026-05-15 14:58:25'),
(5077, 760, 2, 'Trộn các thành phần ướt lại với nhau và trộn vào thành phần khô. Khuấy cho đến khi mịn.', NULL, '2026-05-15 14:58:25', '2026-05-15 14:58:25'),
(5078, 760, 3, 'Nhỏ từng thìa cà phê (không lớn hơn) vào dầu nóng (365 độ, không nóng hơn), đảo một lúc cho đến khi có màu vàng nâu đều các mặt.', NULL, '2026-05-15 14:58:25', '2026-05-15 14:58:25'),
(5079, 760, 4, 'Loại bỏ và thoát nước.', NULL, '2026-05-15 14:58:25', '2026-05-15 14:58:25'),
(5080, 760, 5, 'Lăn đường quế khi còn ấm và thưởng thức.', NULL, '2026-05-15 14:58:25', '2026-05-15 14:58:25'),
(5081, 761, 1, 'Làm nóng lò ở nhiệt độ 180°C. Đối với bột, trộn bột mì và đường vào tô. Đun nóng 100 gram sữa đến ấm và hòa tan men trong đó. Hãy đứng một lúc cho đến khi nó bắt đầu bong bóng. Sau đó cho bột mì cùng dầu dừa vào trộn đều thành một khối bột mịn. Để yên trong 30 phút, đậy kín, ở nơi ấm áp.', NULL, '2026-05-15 14:58:27', '2026-05-15 14:58:27'),
(5082, 761, 2, 'Trong khi đó, làm bánh gạo bằng cách cho gạo với đường, sữa và chiết xuất vani vào nồi. Thêm bạch đậu khấu, hoa hồi và quế. Đun sôi và nấu, khuấy liên tục. Lấy gia vị ra. Trong một bát nhỏ, trộn baking soda với nước cốt chanh/giấm táo. Khuấy đều cho đến khi baking soda tan hết rồi trộn vào bánh gạo.', NULL, '2026-05-15 14:58:27', '2026-05-15 14:58:27'),
(5083, 761, 3, 'Cán bột trên một bề mặt đã rắc bột mì (nó rất dính, nhưng đừng căng thẳng vì nó sẽ ổn thôi) rồi lót bột vào đáy và các cạnh của khuôn đã phết dầu. Trải bánh gạo lên trên và nướng trong khoảng 25 đến 30 phút.', NULL, '2026-05-15 14:58:27', '2026-05-15 14:58:27'),
(5084, 762, 1, 'Đầu tiên, làm bánh ngọt vỏ ngắn: đo lượng bột mì cho vào tô lớn và dùng đầu ngón tay xoa bơ cho đến khi hỗn hợp giống như vụn bánh mì mịn (cách khác, có thể thực hiện việc này trong máy chế biến thực phẩm). Thêm khoảng ba thìa nước lạnh vào trộn đều thành khối bột cứng, bọc màng bọc thực phẩm và để trong tủ lạnh khoảng 20 phút.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5085, 762, 2, 'Làm nóng lò ở nhiệt độ 200C/400F/Gas 6 và đặt một khay nướng nặng vào lò để làm nóng. Bôi bơ vào khuôn bánh flan có đáy rộng 18 cm/7 inch.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5086, 762, 3, 'Lấy khoảng 150g/5½oz bánh ngọt ra khỏi quả bóng chính và dành riêng cho phần lưới trên cùng.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5087, 762, 4, 'Cán mỏng phần còn lại của chiếc bánh ngọt trên bề mặt đã phủ bột mì nhẹ và lót bánh flan đã chuẩn bị sẵn vào bánh ngọt.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5088, 762, 5, 'Dùng nĩa đâm vào đế để ngăn đế nổi lên trong quá trình nướng.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5089, 762, 6, 'Đặt phần bánh ngọt dành riêng cho lưới lên trên màng bám và cán mỏng. Trứng rửa sạch bánh ngọt và để nguội trong tủ lạnh (màng bám giúp di chuyển dễ dàng hơn). Không cắt thành dải ở giai đoạn này. Không rửa trứng khi các dải này đã ở trên bánh tart vì nó sẽ nhỏ giọt vào hỗn hợp mật đường.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5090, 762, 7, 'Để làm nhân, đun nhẹ xi-rô trong chảo lớn nhưng không đun sôi.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5091, 762, 8, 'Sau khi tan chảy, thêm vụn bánh mì, nước cốt chanh và vỏ vào xi-rô. (Bạn có thể thêm ít chanh hơn nếu muốn ít vị cam quýt hơn.) Nếu hỗn hợp có vẻ lỏng, hãy thêm một ít vụn bánh mì.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5092, 762, 9, 'Đổ hỗn hợp xi-rô vào hộp thiếc đã lót giấy và san phẳng bề mặt.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5093, 762, 10, 'Lấy bánh ngọt đã để sẵn ra khỏi tủ lạnh và cắt thành dải dài, rộng 1 cm/½ inch. Hãy chắc chắn rằng tất cả chúng đều dài hơn các cạnh của khuôn bánh tart.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5094, 762, 11, 'Trứng rửa sạch mép bánh trong hộp thiếc và bắt đầu tạo họa tiết lưới dệt trên hỗn hợp, để các dải treo trên mép hộp thiếc.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5095, 762, 12, 'Sau khi lưới đã vào đúng vị trí, hãy dùng cạnh thiếc để cắt các dải bằng cách dùng tay ấn xuống để tạo thành lớp hoàn thiện gọn gàng.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5096, 762, 13, 'Nướng trên khay nướng đã làm nóng trước trong lò nóng khoảng 10 phút cho đến khi bánh bắt đầu có màu, sau đó giảm nhiệt độ lò xuống 180C/350F/Gas 4. Nếu ở giai đoạn này, lưới có vẻ chuyển sang màu nâu quá đậm, hãy bọc bánh tart bằng giấy thiếc.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5097, 762, 14, 'Nướng thêm 25-30 phút nữa cho đến khi bánh có màu nâu vàng và nhân bánh chín hẳn.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5098, 762, 15, 'Lấy bánh tart ra khỏi lò và để trong hộp thiếc cho cứng lại. Phục vụ ấm hoặc lạnh.', NULL, '2026-05-15 14:58:30', '2026-05-15 14:58:30'),
(5099, 763, 1, 'Làm nóng lò ở 190 C / Gas 5. Bôi mỡ vào khuôn lò xo tròn 23cm.', NULL, '2026-05-15 14:58:33', '2026-05-15 14:58:33'),
(5100, 763, 2, 'Cắt bỏ phần cứng ở phần trên và phần dưới của quả cam. Cắt lát cam và loại bỏ tất cả hạt. Nghiền nhuyễn cam cả vỏ trong máy xay thực phẩm. Thêm một phần ba đường và dầu ô liu và tiếp tục trộn cho đến khi kết hợp tốt.', NULL, '2026-05-15 14:58:33', '2026-05-15 14:58:33'),
(5101, 763, 3, 'Rây bột mì và bột nở lại với nhau.', NULL, '2026-05-15 14:58:33', '2026-05-15 14:58:33'),
(5102, 763, 4, 'Đánh trứng và lượng đường còn lại bằng máy trộn cầm tay điện trong ít nhất năm phút cho đến khi bông mịn. Gấp một nửa hỗn hợp bột, sau đó là cam và vani, sau đó cho phần bột còn lại vào. Trộn đều nhưng không để quá lâu.', NULL, '2026-05-15 14:58:33', '2026-05-15 14:58:33'),
(5103, 763, 5, 'Đổ hỗn hợp bánh vào khuôn đã chuẩn bị sẵn và dàn đều. Nướng trong lò làm nóng trước trong 20 phút. Giảm nhiệt độ lò xuống 160 C / Gas 2 và nướng lại trong 30 phút. Nướng cho đến khi bánh có màu vàng nâu và xiên ra sạch sẽ là được. Làm nguội trên giá bánh lưới.', NULL, '2026-05-15 14:58:33', '2026-05-15 14:58:33'),
(5104, 764, 1, 'Đối với bánh quy sandwich, cho bơ mềm vào trong khoảng một phút, sau đó thêm đường và kem vào thêm hai phút nữa. Trộn đều trứng trước khi trộn với lòng đỏ trứng. Sau khi mọi thứ đã được kết hợp hoàn hảo, hãy thêm tất cả nguyên liệu còn lại và trộn thêm một lần nữa. Tạo khối bột thành một quả bóng và bọc trong màng bọc thực phẩm. Thư giãn ít nhất nửa giờ hoặc qua đêm.', NULL, '2026-05-15 14:58:39', '2026-05-15 14:58:39'),
(5105, 764, 2, 'Làm nóng lò ở 180 độ C và lót hai tấm nướng bằng giấy da.', NULL, '2026-05-15 14:58:39', '2026-05-15 14:58:39'),
(5106, 764, 3, 'Chia bột làm đôi, cho một phần vào tủ lạnh và cán phần còn lại thật dày trên bề mặt đã rắc chút bột mì. Cắt bánh quy bằng đáy ly hoặc khuôn cắt bánh quy có đường kính khoảng 6cm. Lặp lại với tất cả bột.', NULL, '2026-05-15 14:58:39', '2026-05-15 14:58:39'),
(5107, 764, 4, 'Nướng khoảng 8-10 phút, bánh sẽ có màu nhạt. Để nguội trước khi đổ đầy một nửa thìa cà phê dulce de leche. Đặt nửa số bánh quy còn lại lên trên và lăn các mặt của từng chiếc bánh quy trong dừa vụn (sẽ hữu ích nếu dulce de leche được ép xuống các cạnh của bánh quy). Thưởng thức.', NULL, '2026-05-15 14:58:39', '2026-05-15 14:58:39'),
(5108, 765, 1, 'Trộn tất cả nguyên liệu làm bột lại với nhau và nhào đều. Đậy bột lại và ủ cho bột nở gấp đôi, mất khoảng 2 tiếng. Gõ bột lại và nhào nhẹ.', NULL, '2026-05-15 14:58:47', '2026-05-15 14:58:47');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(5109, 765, 2, 'Chia bột thành hai phần bằng nhau; cuộn từng miếng thành hình thuôn dài khoảng 12 inch x 8 inch. Trộn các nguyên liệu làm nhân lại với nhau và chia thành các phần bột, trải đều trên từng miếng. Cuộn các hình chữ nhật càng chặt càng tốt để có được hai chiếc xúc xích 12 inch. Đặt những thứ này cạnh nhau, chạm vào nhau trên khay nướng đã phết mỡ. Che và để tăng trong khoảng 40 phút. Làm nóng lò ở nhiệt độ 200°C (425°F). Nướng khoảng 30-35 phút cho đến khi chín đều và có màu vàng nâu. Bánh mì sẽ phát ra âm thanh rỗng khi gõ nhẹ vào đế.', NULL, '2026-05-15 14:58:47', '2026-05-15 14:58:47'),
(5110, 765, 3, 'Lấy ra khỏi lò và phết sữa nóng lên mặt bánh mì nóng. Rây với một lớp đường bột phủ rộng rãi.', NULL, '2026-05-15 14:58:47', '2026-05-15 14:58:47'),
(5112, 766, 1, 'Làm nóng lò ở 160C/Gas 3/lò quạt 140C. Lót giấy thấm mỡ vào đế và các cạnh dài của hộp thiếc 900g/2lb, phết bơ vào hộp thiếc và giấy.', NULL, '2026-05-15 14:58:50', '2026-05-16 12:35:35'),
(5114, 766, 2, 'Cho bột mì, quế, bơ, đường, 2 thìa mật ong và trứng vào tô trộn lớn. Nghiền chuối và cắt nhỏ chà là (dùng kéo nhà bếp là cách dễ nhất để thực hiện việc này) rồi cho vào bát. Đánh hỗn hợp trong 2-3 phút bằng thìa gỗ hoặc máy trộn cầm tay cho đến khi hòa quyện.', NULL, '2026-05-15 14:58:50', '2026-05-16 12:35:35'),
(5116, 766, 3, 'Múc từng thìa vào hộp thiếc đã chuẩn bị sẵn và san bằng mặt trên. Rải các miếng quả óc chó lên trên. Nướng trong 1 giờ, sau đó ấn nhẹ lên trên - bánh chín sẽ có cảm giác chắc. Nếu chưa thì nướng thêm 10 phút nữa.', NULL, '2026-05-15 14:58:50', '2026-05-16 12:35:35'),
(5118, 766, 4, 'Để nguội trong 15 phút, sau đó lấy giấy ra khỏi hộp thiếc. Khi nguội, rưới lượng mật ong còn lại lên. Cắt thành lát dày.', NULL, '2026-05-15 14:58:50', '2026-05-16 12:35:35'),
(5119, 767, 1, 'Đun nóng kem, sô cô la và vỏ vani trong chảo cho đến khi sô cô la tan chảy. Tắt lửa và để ngấm trong 10 phút, cạo hạt vỏ vào kem. Nếu sử dụng chiết xuất vani, hãy thêm ngay vào. Làm nóng lò ở nhiệt độ 160C/quạt 140C/gas 3.', NULL, '2026-05-15 14:58:53', '2026-05-15 14:58:53'),
(5120, 767, 2, 'Đánh lòng đỏ và đường cho đến khi nhạt màu. khuấy kem sô cô la. Lọc vào bình và đổ vào ramekins. Đặt vào khay nướng sâu lòng và đổ nước sôi lên giữa các mặt. Nướng trong 15-20 phút cho đến khi phần giữa bánh hơi lung lay. Làm lạnh trong tủ lạnh ít nhất 4 giờ.', NULL, '2026-05-15 14:58:53', '2026-05-15 14:58:53'),
(5121, 767, 3, 'Để phục vụ, rắc một ít đường lên trên bánh brûlées và làm caramen bằng đèn khò hoặc nướng nhanh trên vỉ nướng nóng. Để caramen cứng lại rồi dùng.', NULL, '2026-05-15 14:58:53', '2026-05-15 14:58:53'),
(5122, 768, 1, 'Đặt men khô, sữa và đường vào tô của máy xay thực phẩm. Trộn và để yên trong vài phút cho đến khi nó bắt đầu nổi bọt.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5123, 768, 2, 'Sau đó thêm bột mì, trứng, bơ, muối, 1 thìa quế và thảo quả vào rồi xay cho đến khi mịn.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5124, 768, 3, 'Tạo khối bột thành một khối, đậy kín tô và ủ trong 1 giờ hoặc cho đến khi bột nở gấp đôi.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5125, 768, 4, 'Trộn đường bột với 1 thìa bột quế, rưới lên bột và cán mỏng.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5126, 768, 5, 'Tạo thành 10 quả bóng bằng nhau (mỗi quả khoảng 75 gam) và để chúng “đổ mồ hôi” một lúc. Đường sẽ tan một chút. Khi bạn cuộn lại lần sau, phần bột còn lại sẽ hấp thụ đường tốt hơn.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5127, 768, 6, 'Sau đó lăn viên bột thành sợi dài khoảng 35-40 cm đồng thời lăn qua lớp đường bột.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5128, 768, 7, 'Gấp sợi quanh một đầu và nhét đầu còn lại vào dưới viên thuốc. Đẩy vật gì đó vào giữa cuộn để cố định phần cuối.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5129, 768, 8, 'Đặt lên khay nướng có lót khay nướng, dùng màng bọc thực phẩm bọc lại và để bột nở trong ½-1 giờ.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5130, 768, 9, 'Trong khi đó, làm nóng lò ở nhiệt độ trên và dưới ở 250 độ C/480 Fahrenheit.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5131, 768, 10, 'Nướng Zeeland Boluses trong khoảng 8 phút cho đến khi chín. Hãy cẩn thận - nếu bạn nướng chúng quá lâu, chúng sẽ bị khô và bạn sẽ muốn thứ gì đó dính 😉.', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5132, 768, 11, 'Để chúng nguội trong lò trong 1 phút, sau đó lật chúng lại và để nguội thêm (trên giá lưới nếu cần). Thưởng thức!', NULL, '2026-05-15 14:58:57', '2026-05-15 14:58:57'),
(5134, 769, 1, 'Ngâm khoai tây trong nước vừa đun sôi trong 30 phút, sau đó để ráo nước và để khô tự nhiên trong 5 phút. Làm nóng nồi chiên không dầu đến 200C. Cho khoai tây vào tô và rưới 1 muỗng canh dầu, thêm 1/2 muỗng cà phê muối và hạt tiêu đen mới xay. Trộn đều để khoai tây phủ đều, sau đó cho vào rổ chiên không khí và nấu trong 20-30 phút cho đến khi giòn và vàng.', NULL, '2026-05-15 14:59:00', '2026-05-16 12:35:35'),
(5136, 769, 2, 'Trong khi đó, đun nóng lượng dầu còn lại trong chảo nhỏ trên lửa vừa thấp và xào hành tây trong 8-10 phút cho đến khi mềm nhưng không vàng. Khuấy tỏi và nấu trong một phút trước khi thêm ớt bột và nấu thêm 30 giây nữa. Khuấy nhuyễn cà chua, nấu trong 1 phút, sau đó cho cà chua cắt nhỏ vào. Nấu trong 5-10 phút trên lửa vừa cho đến khi hơi đặc lại.', NULL, '2026-05-15 14:59:00', '2026-05-16 12:35:35'),
(5138, 769, 3, 'Sau khi khoai tây đã chín, bạn bày ra đĩa và rưới nước sốt cà chua lên trên. Rắc lá húng quế lên rồi thưởng thức.', NULL, '2026-05-15 14:59:00', '2026-05-16 12:35:35'),
(5139, 770, 1, 'Làm nóng lò nướng ở nhiệt độ 450 độ F (230 độ C). Đặt toàn bộ quả ớt lên giấy nhôm. Nướng cho đến khi vỏ có đốm đen và ớt mềm, khoảng 30 đến 45 phút, lật ớt một lần nếu cần.', NULL, '2026-05-15 14:59:04', '2026-05-15 14:59:04'),
(5140, 770, 2, 'Lấy ớt ra khỏi lò và để nguội trong 10 phút. Gọt vỏ và loại bỏ cuống và hạt. Cắt ớt nướng thành miếng nửa inch.', NULL, '2026-05-15 14:59:04', '2026-05-15 14:59:04'),
(5141, 770, 3, 'Đun nóng dầu ô liu trong chảo trên lửa vừa. Cho hành tây vào và nấu, khuấy thường xuyên cho đến khi hành tây mềm và chuyển sang màu trong, khoảng 5 phút. Thêm tỏi, muối và hạt tiêu; khuấy trong ớt xắt nhỏ và cà chua. Nấu trên lửa vừa, thỉnh thoảng khuấy cho đến khi cà chua mềm và hỗn hợp hòa quyện, khoảng 5 phút.', NULL, '2026-05-15 14:59:04', '2026-05-15 14:59:04'),
(5143, 771, 1, 'Xếp cà tím thành một lớp trên khay nướng lớn. Chải một ít dầu thực vật, sau đó nêm nhiều gia vị. Nướng trong 15 phút, lật hai lần và phết dầu cho đến khi các lát thịt mềm và chín đều. Trong khi đó, vo bánh mì thành vụn. Thêm 2 muỗng cà phê dầu và đánh nhanh một lần nữa để phủ đều.', NULL, '2026-05-15 14:59:06', '2026-05-16 12:35:35'),
(5145, 771, 2, 'Rưới một vài thìa sốt hummus lên trên mỗi lát cà tím. Đổ vụn bánh mì lên một đĩa lớn, sau đó ấn phần hummus của cà tím vào trong vụn bánh mì để phủ đều. Nướng lại, đặt mặt vụn bánh lên trên, trong khoảng 3 phút cho đến khi chín vàng.', NULL, '2026-05-15 14:59:06', '2026-05-16 12:35:35'),
(5147, 771, 3, 'Cho quả óc chó, mùi tây và cà chua bi vào tô, nêm gia vị, sau đó thêm nước cốt chanh và dầu ô liu rồi đảo lại. Phục vụ món nướng với salad, thêm một ít hummus và một ít bánh mì pitta.', NULL, '2026-05-15 14:59:06', '2026-05-16 12:35:35'),
(5149, 772, 1, 'Làm nóng vỉ nướng ở mức cao. Đặt cà tím lên khay nướng, phết dầu và nêm gia vị. Nướng trong khoảng 15 phút, lật mặt và phết thêm một nửa dầu cho đến khi chín vàng và mềm.', NULL, '2026-05-15 14:59:09', '2026-05-16 12:35:35'),
(5151, 772, 2, 'Trong khi đó, đổ couscous vào tô lớn, rưới nước dùng lên, sau đó đậy nắp và để trong 10 phút. Trộn cà chua, bạc hà, phô mai dê và dầu còn lại với nhau. Dùng nĩa trộn đều couscous, sau đó cho cà tím, hỗn hợp cà chua và nước cốt chanh vào khuấy đều.', NULL, '2026-05-15 14:59:09', '2026-05-16 12:35:35'),
(5153, 773, 1, 'Trộn nửa phần thịt quả bơ với sữa chua, nước cốt chanh, chanh và gia vị. Cắt nhỏ quả bơ còn lại, sau đó nhẹ nhàng khuấy đều với phần lớn vỏ chanh. Đậy nắp, sau đó làm lạnh cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:59:11', '2026-05-16 12:35:35'),
(5155, 773, 2, 'Luộc khoai tây trong 6 phút, sau đó để ráo nước và trộn với dầu ô liu, bột ớt và hạt thì là. Bây giờ hãy dành nửa giờ trước khi khách của bạn đến.', NULL, '2026-05-15 14:59:11', '2026-05-16 12:35:35'),
(5157, 773, 3, 'Làm nóng lò ở nhiệt độ 200C/180C quạt/gas 6, sau đó nướng khoai tây trong khoảng 30 phút, lắc khay nửa chừng cho đến khi vàng và mềm. Chuyển nước chấm vào một hoặc hai bát, rắc vỏ chanh còn lại và dùng kèm với khoai tây nóng và bánh tortilla để chấm.', NULL, '2026-05-15 14:59:11', '2026-05-16 12:35:35'),
(5158, 774, 1, 'Rửa sạch baingan (cà tím hoặc cà tím) trong nước. Lau khô bằng khăn ăn nhà bếp. Thoa một ít dầu lên khắp người và', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5159, 774, 2, 'giữ nó để rang trên ngọn lửa trần. Bạn cũng có thể nướng baingan hoặc nướng trong lò. Nhưng sau đó bạn sẽ không nhận được', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5160, 774, 3, 'hương vị khói của baingan. Tiếp tục đảo cà tím sau 2 đến 3 phút trên lửa để cà tím chín đều.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5161, 774, 4, 'nấu chín. Bạn cũng có thể nhúng vài tép tỏi vào baingan rồi nướng.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5162, 774, 5, '2. Rang cà tím cho đến khi chín hẳn và mềm. Dùng dao kiểm tra độ chín. Con dao sẽ trượt', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5163, 774, 6, 'dễ dàng trong cà tím mà không gặp bất kỳ sự kháng cự nào. Vớt baingan ra và ngâm vào tô nước cho đến khi nguội', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5164, 774, 7, 'xuống.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5165, 774, 8, '3. Bạn cũng có thể thực hiện kỹ thuật dhungar để truyền hương vị khói than vào baingan. Đây là một bước tùy chọn.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5166, 774, 9, 'Sử dụng than tự nhiên cho phương pháp này. Đun một mẩu than nhỏ trên lửa cho đến khi than nóng và có màu đỏ.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5167, 774, 10, '4. Dùng dao rạch những đường nhỏ trên baingan. Đặt than nóng đỏ vào cùng một đĩa nơi nướng', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5168, 774, 11, 'cà tím được giữ lại. Thêm một vài giọt dầu vào than. Than sẽ bắt đầu bốc khói.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5169, 774, 12, '5. Ngay khi khói bắt đầu bốc ra từ than, hãy đậy kín toàn bộ đĩa bằng một cái tô lớn. Cho phép', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5170, 774, 13, 'khói than để ngấm trong 1 đến 2 phút. Bạn càng làm nhiều thì baingan bharta sẽ càng có nhiều khói', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5171, 774, 14, 'trở thành. Tôi chỉ giữ trong một phút. Ngoài ra, bạn cũng có thể thực hiện phương pháp dhungar này sau khi baingan bharta được thực hiện.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5172, 774, 15, 'nấu chín, giống như cách chúng tôi làm với Dal Tadka.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5173, 774, 16, '6. Gọt vỏ cà tím nướng và hun khói.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5174, 774, 17, '7. Cắt nhỏ cà tím đã nấu chín hoặc thậm chí có thể nghiền nát.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5175, 774, 18, '8. Đun nóng dầu trong chảo hoặc chảo kadai. Sau đó thêm hành và tỏi thái nhỏ.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5176, 774, 19, '9. Xào hành tây cho đến khi trong suốt. Đừng làm nâu chúng.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5177, 774, 20, '10. Thêm ớt xanh xắt nhỏ vào xào trong một phút.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5178, 774, 21, '11. Thêm cà chua cắt nhỏ vào và trộn đều.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5179, 774, 22, '12. Bhuno (xào) cà chua cho đến khi dầu bắt đầu tách ra khỏi hỗn hợp.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5180, 774, 23, '13. Bây giờ thêm bột ớt đỏ vào. Khuấy và trộn đều.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5181, 774, 24, '14. Thêm baingan đã nấu chín cắt nhỏ vào.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5182, 774, 25, '15. Khuấy và trộn đều baingan đã cắt nhỏ với hỗn hợp masala hành tây.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5183, 774, 26, '16. Nêm muối. Khuấy và xào thêm khoảng 4 đến 5 phút nữa.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5184, 774, 27, '17. Cuối cùng, trộn lá rau mùi với baingan bharta hoặc trang trí bằng chúng. Phục vụ Baingan Bharta với', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5185, 774, 28, 'phulkas, rotis hoặc chapatis. Nó phù hợp ngay cả với bánh mì, bánh mì nướng hoặc nướng và cơm trắng hoặc cơm jeera.', NULL, '2026-05-15 14:59:14', '2026-05-15 14:59:14'),
(5195, 776, 1, 'Làm nóng lò nướng ở nhiệt độ quạt/khí 180C/160C 4. Làm món latke bằng cách kết hợp tất cả nguyên liệu.', NULL, '2026-05-15 14:59:20', '2026-05-16 12:35:35'),
(5197, 776, 2, 'Đun nóng dầu trong chảo chống dính lớn. Đổ hỗn hợp vào để tạo thành sáu cốc tròn. Chiên mỗi mặt khoảng 4-5 phút, sau đó chuyển sang khay nướng và nướng trong 10 phút.', NULL, '2026-05-15 14:59:20', '2026-05-16 12:35:35'),
(5199, 776, 3, 'Kết hợp sữa chua và bạc hà trong một bát nhỏ. Trộn lá salad và cà chua với nhau, sau đó dùng latke với sữa chua bạc hà và salad.', NULL, '2026-05-15 14:59:20', '2026-05-16 12:35:35'),
(5200, 777, 1, 'Cắt nhỏ củ cải đường, thêm nước và đun sôi trong 15 phút', NULL, '2026-05-15 14:59:24', '2026-05-15 14:59:24'),
(5201, 777, 2, 'Thêm các thành phần khác và đun sôi cho đến khi mềm', NULL, '2026-05-15 14:59:24', '2026-05-15 14:59:24'),
(5202, 777, 3, 'Cuối cùng thêm đậu và nấu trong 5 phút', NULL, '2026-05-15 14:59:24', '2026-05-15 14:59:24'),
(5203, 777, 4, 'Phục vụ trong nồi súp', NULL, '2026-05-15 14:59:24', '2026-05-15 14:59:24'),
(5205, 778, 1, 'Làm nóng lò ở 180C/quạt 160C/gas 4. Bỏ phần cuống cứng ở giữa lá bắp cải. Đun sôi một chảo nước muối lớn, cho bắp cải vào đun khoảng 1-2 phút cho đến khi lá bắt đầu héo. Xả và làm mới dưới vòi nước lạnh. Xả sạch, sau đó lau khô bằng khăn trà.', NULL, '2026-05-15 14:59:28', '2026-05-16 12:35:35'),
(5207, 778, 2, 'Đun nóng dầu trong chảo, cho hành tây vào xào trong 5 phút cho đến khi chín vàng. Thêm hương thảo và cần tây, sau đó nấu thêm 8 phút nữa. Khuấy gạo, sau đó nấu trong khoảng một phút cho đến khi các hạt gạo sáng bóng. Tắt bếp, cho hạt dẻ và quả nam việt quất vào khuấy đều rồi nêm gia vị.', NULL, '2026-05-15 14:59:28', '2026-05-16 12:35:35'),
(5209, 778, 3, 'Múc một ít nhân lên lá bắp cải, cuộn lại và gấp các cạnh để bọc nhân. Đặt một lớp duy nhất vào một đĩa nông, lớn, có bôi dầu, chịu nhiệt với phần nối bên dưới. Đổ đầy các lá còn lại theo cách tương tự. Trộn nước kho, giấm và mật ong, sau đó rưới lên bắp cải. Đậy kín đĩa bằng giấy bạc, nướng trong 1 giờ, mở nắp rồi nấu thêm 15 phút nữa.', NULL, '2026-05-15 14:59:28', '2026-05-16 12:35:35'),
(5210, 779, 1, 'Cho bơ vào lò nướng kiểu Hà Lan lớn hoặc nồi nặng khác ở lửa vừa. Khi bơ tan chảy, thêm hành tây và xào cho đến khi trong suốt.', NULL, '2026-05-15 14:59:31', '2026-05-15 14:59:31'),
(5211, 779, 2, 'Thêm bắp cải, cà rốt và cần tây. Xào cho đến khi rau bắt đầu mềm, khuấy thường xuyên, khoảng 3 phút.', NULL, '2026-05-15 14:59:31', '2026-05-15 14:59:31'),
(5212, 779, 3, 'Thêm lá nguyệt quế và nước luộc rau vào đun sôi ở nhiệt độ cao. Giảm nhiệt xuống thấp và đun nhỏ lửa, đậy nắp cho đến khi rau mềm, khoảng 15 phút.', NULL, '2026-05-15 14:59:31', '2026-05-15 14:59:31'),
(5213, 779, 4, 'Thêm khoai tây và đun sôi lại ở nhiệt độ cao. Giảm nhiệt xuống thấp và đun nhỏ lửa, đậy nắp cho đến khi khoai tây mềm, khoảng 10 phút.', NULL, '2026-05-15 14:59:31', '2026-05-15 14:59:31'),
(5214, 779, 5, 'Thêm cà chua (hoặc cà chua đóng hộp không ráo nước) và đun sôi lại súp ở nhiệt độ cao. Giảm nhiệt xuống thấp và đun nhỏ lửa, không đậy nắp trong 5 phút. Nêm muối và tiêu cho vừa ăn.', NULL, '2026-05-15 14:59:31', '2026-05-15 14:59:31'),
(5215, 779, 6, 'vớt và bỏ lá nguyệt quế ra khỏi nồi.', NULL, '2026-05-15 14:59:31', '2026-05-15 14:59:31'),
(5216, 779, 7, 'Ăn kèm với kem chua tươi và thì là tươi.', NULL, '2026-05-15 14:59:31', '2026-05-15 14:59:31'),
(5217, 780, 1, 'Làm nóng lò nướng ở mức quạt/khí 200C/180C 6 và lót giấy bạc vào khay nướng. Để ráo đậu xanh, lau khô và đổ lên khay nướng đã chuẩn bị sẵn. Thêm dầu và ớt bột, trộn đều rồi nướng trong 20-25 phút cho đến khi chín vàng và giòn, lắc đều trong khi nấu.', NULL, '2026-05-15 14:59:33', '2026-05-15 14:59:33'),
(5218, 780, 2, 'Trong khi đó, cho cà chua và hành tây vào một cái bát nhỏ với giấm và để riêng để ngâm. Cho quả bơ vào một cái bát khác và dùng nĩa nghiền nhuyễn, để lại những miếng lớn hơn. Khuấy nước cốt chanh và nêm đều. Trộn kem chua với harissa và đặt sang một bên cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 14:59:33', '2026-05-15 14:59:33'),
(5219, 780, 3, 'Làm nóng chảo nướng cho đến khi gần bốc khói. Thêm từng chiếc bánh ngô vào, nướng từng mặt cho đến khi nóng bằng các đường vỉ nướng.', NULL, '2026-05-15 14:59:33', '2026-05-15 14:59:33'),
(5220, 780, 4, 'Đặt mọi thứ lên bàn và làm món fajitas: phết một ít kem harissa lên bánh tortilla, phủ đậu xanh rang, guacamole, salsa ngâm và rau mùi lên trên, nếu bạn thích. Ăn kèm với chanh để ép.', NULL, '2026-05-15 14:59:33', '2026-05-15 14:59:33'),
(5221, 781, 1, 'Bạn có thể dùng nước luộc gà thay cho bột nước luộc gà. Thêm 1/4 cốc nước dùng, sau đó là 2 thìa cà phê bột ngô hòa tan trong 1 thìa. Chuẩn bị cà chua:', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5222, 781, 2, 'Cắt cà chua làm đôi. Loại bỏ phần cuống cứng ở mỗi nửa nối với cây nho. Cắt mỗi nửa thành những phần bằng nhau (bạn sẽ có 6 lát từ mỗi quả cà chua).', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5223, 781, 3, 'Làm món trứng bác mềm:', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5224, 781, 4, 'Trong chảo chống dính 8 đến 10 inch lạnh, thêm dầu thực vật và trứng đã đánh. Vặn lửa ở mức trung bình. Khi lớp trứng mỏng vừa bắt đầu chín ở dưới đáy, hãy đẩy trứng theo một hướng để tạo thành các lớp trứng bác.', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5225, 781, 5, 'Nấu, khuấy nhẹ trong suốt thời gian cho đến khi trứng bác gần như đông lại nhưng vẫn hơi ướt và sáng bóng, từ 2 đến 5 phút. Gắp trứng ra đĩa và nếu cần, hãy lau sạch chảo.', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5226, 781, 6, 'Xào cà chua và gia vị:', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5227, 781, 7, 'Cho dầu mè vào chảo, sau đó cho cà chua vào xào trên lửa vừa cho đến khi cà chua mềm nhưng không nhão, khoảng 3 phút. Thêm bột nước dùng gà, đường và hạt tiêu trắng. Trộn cho đến khi hòa quyện, đường và nước dùng đã tan hết, khoảng 1 phút.', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5228, 781, 8, 'Thêm trứng, xào và trang trí:', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5229, 781, 9, 'Thêm trứng trở lại chảo cùng với cà chua. Xào khoảng 2 phút cho nóng và hòa quyện. Hương vị, chỉ thêm muối nếu cần thiết. Rắc hành lá và ăn kèm cơm trắng với nước, thêm muối cho vừa ăn.', NULL, '2026-05-15 14:59:36', '2026-05-15 14:59:36'),
(5230, 782, 1, 'Cho tỏi, ớt, thì là, ớt bột, tiêu đen, ớt cayenne và muối vào cối; xay bằng chày cho đến khi tạo thành hỗn hợp sệt. Thêm dầu ô liu và trộn đều dersa.', NULL, '2026-05-15 14:59:41', '2026-05-15 14:59:41'),
(5231, 782, 2, 'Đun nóng một chảo lớn trên lửa vừa và xào dersa cho đến khi có mùi thơm, từ 2 đến 4 phút. Thêm nửa củ khoai tây và khuấy đều để kết hợp với dersa. Khuấy bột cà chua. Đổ nước vừa đủ ngập khoai tây và đun sôi. Giảm nhiệt và đun nhỏ lửa cho đến khi khoai tây mềm, khoảng 40 phút.', NULL, '2026-05-15 14:59:41', '2026-05-15 14:59:41'),
(5232, 782, 3, 'Múc khoai tây vào tô phục vụ. Rưới phần nước sốt còn lại lên khoai tây.', NULL, '2026-05-15 14:59:41', '2026-05-15 14:59:41'),
(5233, 783, 1, 'Cắt cà tím thành lát 1 cm (0,4 inch). Đặt chúng vào một cái bát và rắc muối. để chúng ngồi trong 30 phút để tiết ra một ít chất lỏng và vị đắng.', NULL, '2026-05-15 14:59:44', '2026-05-15 14:59:44'),
(5234, 783, 2, '2. Sau 30 phút, rửa sạch các lát cà tím khỏi muối và lau khô bằng khăn bếp.', NULL, '2026-05-15 14:59:44', '2026-05-15 14:59:44'),
(5235, 783, 3, '3. Cho vụn bánh mì và hạt vừng vào tô/đĩa lớn. Trong một tô khác đánh 2 quả trứng với chút muối và tiêu.', NULL, '2026-05-15 14:59:44', '2026-05-15 14:59:44'),
(5236, 783, 4, '4. Đun nóng dầu trong chảo lớn trên lửa cao.', NULL, '2026-05-15 14:59:44', '2026-05-15 14:59:44'),
(5237, 783, 5, '5. Nhúng các lát cà tím vào trứng, sau đó nhúng vào vụn bánh mì rồi cho vào dầu nóng. Chiên từ 2 đến 3 phút mỗi mặt hoặc cho đến khi có màu vàng nâu. Xả trên khăn giấy.', NULL, '2026-05-15 14:59:44', '2026-05-15 14:59:44'),
(5239, 784, 1, 'Cho dưa chuột vào rây. Rắc 1 thìa muối và đường rồi để trong 10 phút. Thêm thì là.', NULL, '2026-05-15 14:59:47', '2026-05-16 12:35:35'),
(5241, 784, 2, 'Trộn kem chua, nước cốt chanh, giấm và thì là, sau đó nêm hạt tiêu đen và thêm vào hỗn hợp thì là.', NULL, '2026-05-15 14:59:47', '2026-05-16 12:35:35'),
(5242, 785, 1, 'Rửa và ngâm toor dal trong khoảng. 3 cốc nước, trong ít nhất một giờ. Dal sẽ có thể tích gấp đôi sau khi ngâm. Xả nước.', NULL, '2026-05-15 14:59:49', '2026-05-15 14:59:49'),
(5243, 785, 2, 'Nấu dal với 2/2 cốc nước và thêm muối, bột nghệ, trên lửa vừa cao, cho đến khi mềm (khoảng 30 phút), nó sẽ giống như súp đặc.', NULL, '2026-05-15 14:59:49', '2026-05-15 14:59:49'),
(5244, 785, 3, 'Trong chảo rán, làm nóng ghee. Thêm hạt thì là và hạt mù tạt. Sau khi hạt nứt ra thì cho lá nguyệt quế, ớt xanh, gừng và ớt bột vào. Khuấy trong vài giây.', NULL, '2026-05-15 14:59:49', '2026-05-15 14:59:49'),
(5245, 785, 4, 'Thêm cà chua, muối và đường vào khuấy đều và nấu cho đến khi cà chua mềm và nhão.', NULL, '2026-05-15 14:59:49', '2026-05-15 14:59:49'),
(5246, 785, 5, 'Thêm rau mùi và garam masala nấu trong khoảng một phút.', NULL, '2026-05-15 14:59:49', '2026-05-15 14:59:49'),
(5247, 785, 6, 'Đổ gia vị lên trên, trộn đều và nấu thêm một phút nữa.', NULL, '2026-05-15 14:59:49', '2026-05-15 14:59:49'),
(5248, 785, 7, 'Phục vụ với Naan.', NULL, '2026-05-15 14:59:49', '2026-05-15 14:59:49'),
(5249, 786, 1, 'Cho nước luộc gà vào chảo và đợi sôi.', NULL, '2026-05-15 14:59:52', '2026-05-15 14:59:52'),
(5250, 786, 2, 'Tiếp theo thêm muối, đường, tiêu trắng, dầu mè.', NULL, '2026-05-15 14:59:52', '2026-05-15 14:59:52'),
(5251, 786, 3, 'Khi nước luộc gà sôi thì cho rau vào chảo.', NULL, '2026-05-15 14:59:52', '2026-05-15 14:59:52'),
(5252, 786, 4, 'Để làm đặc nước sốt, trộn 1 thìa bột ngô và 2 thìa nước vào tô rồi từ từ thêm vào súp cho đến khi có độ đặc phù hợp.', NULL, '2026-05-15 14:59:52', '2026-05-15 14:59:52'),
(5253, 786, 5, 'Tiếp theo, thêm 1 quả trứng đánh nhẹ bằng dao hoặc nĩa rồi thêm từ từ vào súp và khuấy trong 8 giây', NULL, '2026-05-15 14:59:52', '2026-05-15 14:59:52'),
(5254, 786, 6, 'Múc súp ra bát và thêm hành lá lên trên.', NULL, '2026-05-15 14:59:52', '2026-05-15 14:59:52'),
(5255, 787, 1, '1. Cắt 1 lb cà tím nhỏ của Nhật Bản hoặc Ý (khoảng 3 quả) thành các phần tư theo chiều dọc, sau đó cắt chéo thành từng miếng rộng 2 inch. Cho vào tô vừa. Thêm 1 thìa canh đường, 1 thìa cà phê Diamond Crystal hoặc ½ thìa cà phê muối Morton kosher và ½ thìa cà phê tiêu đen mới xay. Trộn đều để cà tím phủ đều và để ở nhiệt độ phòng ít nhất 20 phút và tối đa 2 giờ.', NULL, '2026-05-15 14:59:55', '2026-05-15 14:59:55'),
(5256, 787, 2, '2. Gọt vỏ và thái mỏng 8 tép tỏi. Thêm 3 muỗng canh. dầu thực vật và một nửa số tỏi vào lò kiểu Hà Lan cỡ vừa hoặc nồi nặng khác. Nấu trên lửa vừa cao, khuấy liên tục bằng thìa gỗ cho đến khi vàng nhạt và giòn, khoảng 5 phút. Dùng thìa có rãnh chuyển tỏi phi vào đĩa; nêm nhẹ với muối.', NULL, '2026-05-15 14:59:55', '2026-05-15 14:59:55'),
(5257, 787, 3, '3. Đặt 4 oz. xay thịt lợn trong cùng một nồi và chia thành từng miếng nhỏ bằng thìa gỗ. Nêm với ¼ muỗng cà phê. Muối Diamond Crystal hoặc Morton kosher và nấu, không quấy rầy, cho đến khi bên dưới có màu nâu đậm, khoảng 5 phút. Dùng thìa có rãnh chuyển sang đĩa khác, để lại mỡ trong nồi.', NULL, '2026-05-15 14:59:55', '2026-05-15 14:59:55'),
(5258, 787, 4, '4. Đặt cà tím lên một chiếc khăn bếp sạch và thấm bớt hơi ẩm mà muối đã hút ra.', NULL, '2026-05-15 14:59:55', '2026-05-15 14:59:55'),
(5259, 787, 5, '5. Làm theo từng mẻ và thêm dầu nếu cần, nấu cà tím trong cùng một nồi cho đến khi có màu nâu nhạt, khoảng 3 phút mỗi mặt. Chuyển sang đĩa với thịt lợn.', NULL, '2026-05-15 14:59:55', '2026-05-15 14:59:55'),
(5260, 787, 6, '6. Đổ 1½ cốc nước vào nồi và dùng thìa gỗ cạo sạch những phần màu nâu ở đáy nồi. Thêm tỏi còn lại, 3 muỗng canh. giấm dừa hoặc giấm gạo chưa chín, 2 muỗng canh. nước tương, 2 lá nguyệt quế, 1 muỗng cà phê. hạt tiêu đen mới xay và 1 muỗng canh còn lại. đường. Đun sôi rồi cho thịt lợn và cà tím vào nồi. Giảm nhiệt xuống mức vừa phải, đậy nắp một phần và đun nhỏ lửa cho đến khi cà tím mềm và mượt và nước sốt giảm đi một nửa, trong 20–25 phút. Hương vị và nêm thêm muối và hạt tiêu và thêm một chút đường nếu cần.', NULL, '2026-05-15 14:59:55', '2026-05-15 14:59:55'),
(5261, 787, 7, '7. Xếp tỏi phi lên trên và dùng với cơm trắng đã nấu chín.', NULL, '2026-05-15 14:59:55', '2026-05-15 14:59:55'),
(5263, 788, 1, 'Cho cà chua và tất cả ớt vào máy xay thực phẩm và xay nhuyễn cho đến khi thái nhỏ. Đổ ra rây, đặt lên tô và để ráo. Cho hành, tỏi và mùi tây vào máy xay thực phẩm và xay cho đến khi thái nhỏ, sau đó đặt sang một bên.', NULL, '2026-05-15 15:00:00', '2026-05-16 12:35:35'),
(5265, 788, 2, 'Thêm bột ớt đỏ, cà chua xay nhuyễn, mật lựu, bột biber, cây thù du, bạc hà khô và hầu hết dầu ô liu nguyên chất vào tô phục vụ và đánh đều để mọi thứ hòa quyện với nhau thành nước sốt. Đổ hỗn hợp hành tây phi thơm và hỗn hợp hạt tiêu đã lọc cùng với 1 thìa cà phê muối biển. Khuấy đều, sau đó rưới dầu ô liu nguyên chất còn lại lên để thưởng thức.', NULL, '2026-05-15 15:00:00', '2026-05-16 12:35:35'),
(5267, 789, 1, 'Đun nóng 1 muỗng canh dầu trong chảo lớn, sau đó xào hành tây và tỏi trên lửa nhỏ trong 5 phút cho đến khi mềm. Cho đậu xanh và gia vị vào tô trộn lớn, sau đó dùng nĩa hoặc dụng cụ nghiền khoai tây nghiền đều cho đến khi đậu xanh nát hoàn toàn. Khuấy rau mùi tây hoặc các loại thảo mộc khô, với gia vị cho vừa ăn. Thêm trứng vào, sau đó dùng tay bóp đều hỗn hợp.', NULL, '2026-05-15 15:00:02', '2026-05-16 12:35:35'),
(5269, 789, 2, 'Nặn hỗn hợp thành 6 viên, sau đó dẹt thành từng miếng. Đun nóng lượng dầu còn lại trong chảo, sau đó chiên falafel ở lửa vừa trong 3 phút mỗi mặt cho đến khi có màu vàng nâu và săn chắc. Ăn nóng hoặc lạnh với couscous, bánh mì pitta hoặc salad.', NULL, '2026-05-15 15:00:02', '2026-05-16 12:35:35'),
(5270, 790, 1, 'Làm nóng lò ở nhiệt độ 450 độ F (230 độ C). Đặt món falafel lên khay nướng.', NULL, '2026-05-15 15:00:05', '2026-05-15 15:00:05'),
(5271, 790, 2, 'Nướng trong lò làm nóng trước cho đến khi nóng hoàn toàn, từ 8 đến 10 phút.', NULL, '2026-05-15 15:00:05', '2026-05-15 15:00:05'),
(5272, 790, 3, 'Trong khi nướng falafel, trộn tahini, nước, nước cốt chanh, tỏi và ớt bột với nhau trong một cái bát.', NULL, '2026-05-15 15:00:05', '2026-05-15 15:00:05'),
(5273, 790, 4, 'Cắt khoảng 1 inch từ đầu mỗi pita để tạo thành một cái túi. Thêm 2 món falafel vào mỗi bánh pita với lượng rau diếp, cà chua, dưa chuột, dưa chua và hành đỏ bằng nhau. Rắc mỗi thứ khoảng 1 muỗng canh nước sốt tahini và một ít harissa.', NULL, '2026-05-15 15:00:05', '2026-05-15 15:00:05'),
(5274, 791, 1, 'Đối với bánh ngọt, rây bột mì và muối vào tô của máy xay thực phẩm, thêm bơ và mỡ lợn, sau đó đánh nhanh với nhau cho đến khi hỗn hợp trông giống như vụn bánh mì mịn. Đổ hỗn hợp vào tô, sau đó cho phô mai và lượng nước vừa đủ vào khuấy đều để hỗn hợp hòa quyện với nhau. Đổ bột ra một bề mặt đã rắc nhẹ bột mì và nhào nhanh cho đến khi mịn. Cán mỏng và lót một khuôn bánh flan có đáy có rãnh, kích thước 23cm x 4cm. Đâm vào đế bằng một cái nĩa. Thư giãn trong 20 phút.', NULL, '2026-05-15 15:00:12', '2026-05-15 15:00:12'),
(5275, 791, 2, '02. Đun chảy 75g bơ trong chảo trên lửa nhỏ, sau đó cho tỏi tây và muối vào. Đậy nắp và nấu trong khoảng 10 phút cho đến khi mềm. Mở nắp chảo, tăng lửa và nấu trong 2 phút, thỉnh thoảng khuấy cho đến khi chất lỏng bay hơi hết. Múc từng thìa ra đĩa và để nguội.', NULL, '2026-05-15 15:00:12', '2026-05-15 15:00:12'),
(5276, 791, 3, '03. Làm nóng lò ở 200°C/quạt180°C/gas 6. Lót giấy nướng và đậu nướng hoặc gạo hoặc gạo vào khuôn rồi nướng trong 15-20 phút cho đến khi các cạnh có màu bánh quy. Lấy giấy và đậu/gạo ra rồi cho hộp vào lò nướng trong 7-10 phút cho đến khi phần đế giòn và vàng nhẹ. Loại bỏ và đặt sang một bên. Giảm nhiệt độ lò xuống 190°C/quạt170°C/gas 5.', NULL, '2026-05-15 15:00:12', '2026-05-15 15:00:12'),
(5277, 791, 4, '04. Cho kem tươi vào tô cùng với cả quả trứng, lòng đỏ trứng và hạt nhục đậu khấu. Đánh nhẹ vào nhau rồi nêm gia vị. Khuấy tỏi tây. Múc hỗn hợp vào khuôn bánh tart và nướng trong 35-40 phút cho đến khi chín và có màu vàng nhạt. Lấy ra khỏi lò và để trong 10 phút. Lấy ra khỏi hộp thiếc và phục vụ.', NULL, '2026-05-15 15:00:12', '2026-05-15 15:00:12'),
(5278, 792, 1, 'Vì thời gian nấu thay đổi tùy thuộc vào chất lượng và độ tuổi của đậu, nên bạn nên nấu trước và hâm nóng lại khi sẵn sàng phục vụ. Nấu đậu đã ráo nước với một phần nước mới không muối trong nồi lớn có nắp đậy cho đến khi mềm, thêm nước để ngập đậu và thêm muối khi đậu đã mềm. Đun sôi nhẹ nhàng trong 2–2 tiếng rưỡi. Khi đậu mềm, để nước giảm bớt. Người ta thường lấy một hoặc hai muôi đậu ra và nghiền chúng với một ít nước nấu, sau đó khuấy lại vào đậu. Điều này là để làm đặc nước sốt.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5279, 792, 2, 'Dọn đậu vào bát súp có rắc mùi tây cắt nhỏ và kèm theo bánh mì Ả Rập.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5280, 792, 3, 'Chuyển các nguyên liệu làm nước sốt cho mọi người tự dùng: một chai dầu ô liu nguyên chất, chanh cắt đôi, muối và tiêu, một ít đĩa đựng tỏi nghiền, một đĩa đựng ớt bột và một đĩa với thìa là xay.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5281, 792, 4, 'Đậu được nghiền nhẹ bằng nĩa để chúng thấm nước sốt.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5282, 792, 5, 'Trang trí tùy chọn', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5283, 792, 6, 'Bóc vỏ trứng luộc chín—mỗi người 1 quả—để cắt vào tô cùng với đậu.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5284, 792, 7, 'Phủ lên đậu một lớp salad dưa chuột và cà chua cắt nhỏ cùng hành tây hoặc hành lá thái lát mỏng. Nếu không, hãy chuyền một bó hành lá, cà chua và dưa chuột cắt thành từng miếng.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5285, 792, 8, 'Ăn kèm sốt kem tahina (trang 65) hoặc salad (trang 67), kèm dưa chua và hành tây thái lát ngâm dấm trong 30 phút.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5286, 792, 9, 'Một cách khác để phục vụ món medames đầy đủ là sốt cà chua tỏi (xem trang 464).', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5287, 792, 10, 'Ở Syria và Lebanon, họ ăn ful medames với sữa chua hoặc phô mai feta, ô liu và dưa chuột nhỏ.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5288, 792, 11, 'Các biến thể', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5289, 792, 12, 'Cách làm đặc nước sốt truyền thống là cho một nắm đậu lăng đỏ (1/4 cốc) vào nước khi bắt đầu nấu.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5290, 792, 13, 'Ở Iraq, đậu nâu lớn được sử dụng thay cho đậu Ai Cập nhỏ, trong món ăn gọi là badkila, món này cũng được bán cho bữa sáng trên đường phố.', NULL, '2026-05-15 15:00:15', '2026-05-15 15:00:15'),
(5291, 793, 1, 'Ngâm đậu qua đêm trong nhiều nước. Xả, rửa sạch, sau đó đặt vào chảo phủ đầy nước. Đun sôi, giảm nhiệt, sau đó đun nhỏ lửa trong khoảng 50 phút cho đến khi hơi mềm nhưng không mềm. Xả nước, sau đó đặt sang một bên.', NULL, '2026-05-15 15:00:17', '2026-05-15 15:00:17'),
(5292, 793, 2, 'Làm nóng lò nướng ở mức quạt/khí 180C/160C 4. Đun nóng dầu ô liu trong chảo lớn, cho hành và tỏi vào, sau đó nấu trên lửa vừa trong 10 phút cho đến khi mềm nhưng không chuyển sang màu nâu. Thêm cà chua xay nhuyễn, nấu thêm một phút nữa, thêm các nguyên liệu còn lại vào, sau đó đun nhỏ lửa trong 2-3 phút. Nêm thật đậm đà rồi cho đậu vào khuấy đều. Đổ đậu vào một đĩa chịu nhiệt lớn, sau đó nướng trong khoảng 1 giờ, không đậy nắp và không khuấy cho đến khi đậu mềm. Đậu sẽ hấp thụ tất cả các hương vị tuyệt vời và nước sốt sẽ đặc lại. Để nguội, sau đó rắc rau mùi tây và rưới thêm một ít dầu ô liu để thưởng thức.', NULL, '2026-05-15 15:00:17', '2026-05-15 15:00:17'),
(5294, 794, 1, 'Quét từng lát cà tím một ít dầu rồi nêm gia vị. Làm nóng chảo nướng hoặc vỉ nướng. Khi còn nóng, nướng các lát cà tím trong 2-3 phút mỗi mặt cho đến khi có màu vàng nâu và mềm.', NULL, '2026-05-15 15:00:20', '2026-05-16 12:35:35'),
(5296, 794, 2, 'Trộn sữa chua với tahini, tỏi, nước cốt chanh và các loại thảo mộc, sau đó nêm gia vị. Rưới nước sốt lên cà tím và rải lên các lá thảo mộc còn lại.', NULL, '2026-05-15 15:00:21', '2026-05-16 12:35:35'),
(5298, 795, 1, 'Đun nóng 2 muỗng canh dầu trong chảo, cho hành tây vào xào cho đến khi mềm và có màu nâu nhạt trong khoảng 10 phút. Thêm ớt, gừng và gia vị vào rồi trộn đều. Cho đậu xanh, cà chua và 5 muỗng canh nước vào, đun sôi rồi đun nhỏ lửa trong 10 phút. Thêm một chút muối và hạt tiêu và nước cốt chanh.', NULL, '2026-05-15 15:00:26', '2026-05-16 12:35:35'),
(5300, 795, 2, 'Xếp cà tím lên chảo nướng. Quét nhẹ dầu, rắc muối và tiêu rồi nướng cho đến khi vàng. Lật chúng lại, phết dầu lại, nêm gia vị và nướng lại cho đến khi mềm và vàng.', NULL, '2026-05-15 15:00:26', '2026-05-16 12:35:35'),
(5302, 795, 3, 'Trộn sữa chua với tỏi, hầu hết quả óc chó, rau mùi và một chút muối và hạt tiêu. Xếp các lát cà tím lên đĩa ấm và rưới lên hỗn hợp đậu xanh. Rưới nước sốt quả óc chó và rải đều quả óc chó và rau mùi còn lại.', NULL, '2026-05-15 15:00:26', '2026-05-16 12:35:35'),
(5307, 797, 1, 'Đầu tiên, nấu rau của bạn. Mang một nồi nước muối lớn đun sôi. Nấu chung cà rốt và khoai tây trong năm phút cho đến khi cà rốt và khoai tây mềm, sau đó chần đậu Hà Lan và đậu khoảng một phút trong cùng một nồi. Lọc rau và đặt sang một bên.', NULL, '2026-05-15 15:00:30', '2026-05-15 15:00:30'),
(5308, 797, 2, 'Trong nồi có đáy nặng hoặc lò nướng kiểu Hà Lan, làm tan chảy bơ trên lửa vừa, thêm rau vào và nấu cho đến khi ấm.', NULL, '2026-05-15 15:00:30', '2026-05-15 15:00:30'),
(5309, 797, 3, 'Thêm sữa và kem vào rồi đun sôi súp. Giảm nhiệt xuống thấp và nêm muối và hạt tiêu.', NULL, '2026-05-15 15:00:30', '2026-05-15 15:00:30'),
(5310, 797, 4, 'Thêm thì là và hẹ và đun nhỏ lửa trong ít nhất 10 phút. Phục vụ ấm áp.', NULL, '2026-05-15 15:00:30', '2026-05-15 15:00:30'),
(5311, 798, 1, 'Hướng dẫn', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5312, 798, 2, 'Đặt Instant Pot thành \"Xào\". Khi nóng, thêm dầu ô liu. Sau đó thêm hành tây vàng vào và khuấy cho đến khi mềm, khoảng 3 phút. Thêm tỏi và hành lá và khuấy thêm khoảng 30 giây.', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5313, 798, 3, 'Nhấn “Hủy” trên Instant Pot. Thêm gạo, nước cốt dừa, nước, muối, hạt tiêu và hạt tiêu đen vào rồi khuấy đều.', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5314, 798, 4, 'Đổ đậu thận chưa ráo nước lên trên hỗn hợp gạo. Đừng khuấy động. Đặt nhánh húng tây lên trên. Đậy nắp Instant Pot, đảm bảo van được đặt ở chế độ “Niêm phong”.', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5315, 798, 5, 'Nhấn “Thủ công” hoặc “Nấu áp suất” trên Nồi ăn liền và đặt ở Áp suất cao trong 6 phút.', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5316, 798, 6, 'Sau khi hoàn thành thời gian nấu áp suất, hãy để nó xả tự nhiên trong 10 phút, sau đó nhanh chóng xả hết áp suất còn lại bằng cách di chuyển van sang \"Thông hơi\"', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5317, 798, 7, 'Mở nắp và loại bỏ nhánh húng tây. Xới cơm bằng nĩa và thưởng thức!', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5318, 798, 8, 'Hướng dẫn sử dụng bếp hàng đầu', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5319, 798, 9, 'Đun nóng dầu ô liu trong nồi lớn trên lửa vừa. Thêm hành tây vàng và khuấy cho đến khi mềm, khoảng 3 phút. Thêm tỏi và hành lá và khuấy thêm khoảng 30 giây.', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5320, 798, 10, 'Thêm gạo, đậu thận chưa ráo nước, nước cốt dừa, nước, muối, hạt tiêu và hạt tiêu đen vào rồi khuấy đều cho đến khi hòa quyện. Đặt húng tây lên trên. Đun sôi hỗn hợp.', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5321, 798, 11, 'Đậy nắp và giảm nhiệt xuống thấp. Để nấu trong 18 phút ở nhiệt độ thấp, sau đó tắt bếp. Đậy nắp thêm 5 phút nữa.', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5322, 798, 12, 'Mở nắp và lấy húng tây ra. Xới cơm bằng nĩa. Thưởng thức.', NULL, '2026-05-15 15:00:32', '2026-05-15 15:00:32'),
(5323, 799, 1, 'Thiết bị', NULL, '2026-05-15 15:00:37', '2026-05-15 15:00:37'),
(5324, 799, 2, 'lò Hà Lan', NULL, '2026-05-15 15:00:37', '2026-05-15 15:00:37'),
(5325, 799, 3, 'Cho gạo, nước cốt dừa, đậu thận, nước, muối kosher, hạt tiêu và hạt tiêu đen vào nồi lớn và khuấy đều cho đến khi hòa quyện. Xếp hành lá, húng tây và hạt tiêu Scotch lên trên. Đun sôi hỗn hợp.', NULL, '2026-05-15 15:00:37', '2026-05-15 15:00:37'),
(5326, 799, 4, 'Sau khi sôi, giảm nhiệt xuống thấp và đậy nắp lại. Đậy nắp nấu trong 18 phút ở lửa nhỏ, sau đó tắt bếp. Đậy nắp thêm 5 phút nữa.', NULL, '2026-05-15 15:00:37', '2026-05-15 15:00:37'),
(5327, 799, 5, 'Mở nắp và lấy hành lá, ớt Scotch và húng tây ra. Xới cơm và đậu Hà Lan bằng nĩa. Phục vụ và thưởng thức.', NULL, '2026-05-15 15:00:37', '2026-05-15 15:00:37'),
(5328, 800, 1, 'Gọt vỏ khoai tây và cắt thành khối 5 cm.', NULL, '2026-05-15 15:00:41', '2026-05-15 15:00:41'),
(5329, 800, 2, 'Đổ 1-2 cm dầu ô liu vào chảo lớn và đun nóng thật nóng. Chiên khoai tây cho đến khi vàng nâu trong 20 phút, thỉnh thoảng đảo mặt. Đặt lên giấy bếp cho ráo nước.', NULL, '2026-05-15 15:00:41', '2026-05-15 15:00:41'),
(5330, 800, 3, 'Cắt ớt làm đôi và loại bỏ hạt. Xoa một ít dầu ô liu lên chúng và đặt mặt cắt xuống khay nướng. Đặt chúng dưới vỉ nướng. Nướng cho đến khi da sẫm màu và sủi bọt. Trong khi ớt vẫn còn nóng, hãy cho chúng vào túi nhựa đựng bánh sandwich và buộc kín. Lấy chúng ra sau 15 phút và loại bỏ da.', NULL, '2026-05-15 15:00:41', '2026-05-15 15:00:41'),
(5331, 800, 4, 'Trong lúc đó, đun nóng thêm dầu ô liu vào một chảo khác. Gọt vỏ hành tây và cắt thành từng khoanh mỏng. Chiên trong 15 phút cho đến khi vàng nâu, đảo thường xuyên. Thêm Ras el hanout vào cuối.', NULL, '2026-05-15 15:00:41', '2026-05-15 15:00:41'),
(5332, 800, 5, 'Cắt bí ngô thành khối vuông 5cm và chiên trong chảo mà bạn đã dùng cho khoai tây trong vòng 10-15 phút cho đến khi bí mềm và hơi chín vàng. Đặt trên giấy ăn.', NULL, '2026-05-15 15:00:41', '2026-05-15 15:00:41'),
(5333, 800, 6, 'Đổ lượng dầu ô liu còn lại ra khỏi chảo rồi cho tất cả các loại rau đã nấu chín vào chảo rồi trộn đều. Đánh trứng và đổ chúng lên rau. Đậy nắp chảo để trứng chín. Đặt lượng chứa trong chảo lên một chiếc thớt lớn, thêm muối và hạt tiêu rồi cắt nhỏ rồi trộn mọi thứ bằng một con dao lớn.', NULL, '2026-05-15 15:00:41', '2026-05-15 15:00:41'),
(5334, 801, 1, 'Đun nóng dầu trong chảo lớn trên lửa vừa và nhỏ. Thêm hành tây và một chút muối vào nấu từ từ, thỉnh thoảng khuấy cho đến khi mềm và bắt đầu có màu. Thêm tỏi, gừng và cọng rau mùi vào nấu thêm 2 phút nữa cho đến khi có mùi thơm.', NULL, '2026-05-15 15:00:48', '2026-05-15 15:00:48'),
(5335, 801, 2, 'Thêm gia vị vào chảo và nấu thêm 1 phút nữa, lúc đó mọi thứ sẽ có mùi thơm. Cho cà chua cắt nhỏ và đậu thận vào nước, sau đó đun sôi.', NULL, '2026-05-15 15:00:48', '2026-05-15 15:00:48'),
(5336, 801, 3, 'Giảm nhiệt và đun nhỏ lửa trong 15 phút cho đến khi cà ri chín và đặc. Nêm nếm vừa ăn rồi dùng kèm cơm basmati và lá rau mùi.', NULL, '2026-05-15 15:00:48', '2026-05-15 15:00:48'),
(5337, 802, 1, 'Nấu đậu lăng. Đun sôi đậu lăng và 4 cốc nước trong nồi hoặc nồi vừa trên lửa lớn. Giảm nhiệt xuống thấp và nấu cho đến khi đậu lăng mềm (15-17 phút). Vớt ra để ráo nước và nêm chút muối. (Lưu ý: đậu lăng khi đã chín không nên nấu chín hoàn toàn mà chỉ nên nấu sơ sơ và vẫn còn miếng khi nấu xong với cơm).', NULL, '2026-05-15 15:00:51', '2026-05-15 15:00:51'),
(5338, 802, 2, 'Bây giờ, về cơm. Xả gạo ra khỏi nước ngâm. Cho đậu lăng đã nấu chín và gạo vào chảo trên lửa vừa cao cùng 1 muỗng canh dầu ăn, muối, tiêu và rau mùi. Nấu trong 3 phút, khuấy thường xuyên. Thêm nước ấm để ngập hỗn hợp gạo và đậu lăng khoảng 1 1/2 inch (bạn có thể sẽ sử dụng khoảng 3 cốc nước ở đây). Đun sôi; nước sẽ giảm đi một chút. Bây giờ đậy nắp và nấu cho đến khi tất cả chất lỏng đã được hấp thụ và cả gạo và đậu lăng đều chín kỹ (khoảng 20 phút).  Giữ kín và không bị xáo trộn trong 5 phút hoặc lâu hơn.', NULL, '2026-05-15 15:00:51', '2026-05-15 15:00:51'),
(5339, 802, 3, 'Bây giờ làm mì ống. Trong khi nấu cơm và đậu lăng, hãy làm mì ống theo hướng dẫn trên bao bì bằng cách cho mì ống vào nước sôi có thêm một chút muối và một ít dầu. Nấu cho đến khi mì ống chín đều. Làm khô hạn.', NULL, '2026-05-15 15:00:51', '2026-05-15 15:00:51'),
(5340, 802, 4, 'Đậy đậu xanh và hâm nóng trong lò vi sóng một thời gian ngắn trước khi dùng.', NULL, '2026-05-15 15:00:51', '2026-05-15 15:00:51'),
(5341, 802, 5, 'Làm lớp phủ hành tây giòn.', NULL, '2026-05-15 15:00:51', '2026-05-15 15:00:51'),
(5342, 802, 6, 'Rắc muối lên các khoanh hành tây, sau đó lăn chúng vào bột mì cho bám đều. Lắc bột thừa.', NULL, '2026-05-15 15:00:51', '2026-05-15 15:00:51'),
(5343, 802, 7, 'Trong chảo lớn, đun nóng dầu ăn ở lửa vừa cao, cho hành tây vào xào, đảo thường xuyên cho đến khi chúng chuyển sang màu nâu caramen đẹp mắt. Hành tây phải giòn nhưng không bị cháy (15-20 phút).', NULL, '2026-05-15 15:00:51', '2026-05-15 15:00:51'),
(5344, 803, 1, 'Đun nóng dầu trong nồi lớn. Thêm hành tây và nấu cho đến khi trong suốt.', NULL, '2026-05-15 15:00:53', '2026-05-15 15:00:53'),
(5345, 803, 2, 'Xả sạch đậu xanh đã ngâm và cho vào nồi cùng với nước luộc rau. Đun sôi, sau đó giảm nhiệt và đậy nắp. Đun nhỏ lửa trong 30 phút.', NULL, '2026-05-15 15:00:53', '2026-05-15 15:00:53'),
(5346, 803, 3, 'Trong lúc đó, nướng thì là trong chảo rán nhỏ không phết dầu mỡ, sau đó xay trong cối. Thêm tỏi và muối rồi giã thành bột nhão.', NULL, '2026-05-15 15:00:53', '2026-05-15 15:00:53'),
(5347, 803, 4, 'Thêm bột nhão và harissa vào súp và đun nhỏ lửa cho đến khi đậu xanh mềm, khoảng 30 phút.', NULL, '2026-05-15 15:00:53', '2026-05-15 15:00:53'),
(5348, 803, 5, 'Nêm muối, tiêu, nước cốt chanh cho vừa miệng rồi dùng nóng.', NULL, '2026-05-15 15:00:53', '2026-05-15 15:00:53'),
(5349, 804, 1, 'Đun nóng dầu trong chảo trên lửa cao cho đến khi dầu nóng. Thêm paneer, sau đó giảm nhiệt xuống một chút. Chiên cho đến khi bắt đầu có màu nâu ở các cạnh, sau đó lật lại và chín vàng từng mặt - miếng bánh sẽ chín nhanh hơn bạn nghĩ, vì vậy đừng bỏ đi. Lấy khay ra khỏi chảo và để ráo trên giấy ăn.', NULL, '2026-05-15 15:00:55', '2026-05-15 15:00:55'),
(5350, 804, 2, 'Cho gừng, thì là, nghệ, rau mùi xay và ớt vào chảo rồi xào mọi thứ trong 1 phút. Thêm cà chua vào, dùng thìa nghiền nhuyễn và đun nhỏ lửa mọi thứ trong 5 phút cho đến khi nước sốt có mùi thơm. Thêm một chút nước nếu nó quá đặc. Mùa tốt. Thêm đậu Hà Lan và đun nhỏ lửa thêm 2 phút nữa, sau đó cho khay vào khuấy đều và rắc lên garam masala. Chia thành hai bát, rắc lá rau mùi lên trên và dùng kèm với bánh mì naan, bánh roti hoặc cơm.', NULL, '2026-05-15 15:00:55', '2026-05-15 15:00:55'),
(5351, 805, 1, 'Đặt đậu khô vào lò kiểu Hà Lan với 6 cốc (1,5 L) nước. Ngâm qua đêm.', NULL, '2026-05-15 15:00:58', '2026-05-15 15:00:58'),
(5352, 805, 2, 'Xả sạch đậu và đổ lại vào nồi với lượng nước vừa đủ ngập đậu khoảng vài inch, nấu trong 30 phút cho đến khi đậu mềm nhưng vẫn cứng. Để ráo đậu, đảm bảo dự trữ nước nấu, đặt sang một bên.', NULL, '2026-05-15 15:00:58', '2026-05-15 15:00:58'),
(5353, 805, 3, 'Làm nóng lò ở nhiệt độ 325°F (160°C). Trong khi lò đang làm nóng trước, hãy nấu thịt lợn ở lửa vừa cao trong Lò nướng Hà Lan cho đến khi mỡ chảy ra và thịt lợn bắt đầu chuyển sang màu nâu, sau đó cho hành tây vào nấu cho đến khi mềm.', NULL, '2026-05-15 15:00:58', '2026-05-15 15:00:58'),
(5354, 805, 4, 'Cho đậu trở lại nồi cùng với mật đường, đường nâu, giấm táo, mù tạt xay, muối, tiêu và 3 cốc (750 mL) nước đậu dành riêng.', NULL, '2026-05-15 15:00:58', '2026-05-15 15:00:58'),
(5355, 805, 5, 'Nướng không đậy nắp trong 3 đến 5 giờ cho đến khi đậu mềm, nước sốt đặc lại và thành nồi dính lại.', NULL, '2026-05-15 15:00:58', '2026-05-15 15:00:58'),
(5356, 805, 6, '(Lưu ý: nếu đậu khô thì cho thêm 1 cốc nước nữa nhé).', NULL, '2026-05-15 15:00:58', '2026-05-15 15:00:58'),
(5358, 806, 1, 'Làm nóng lò ở nhiệt độ 180°C.', NULL, '2026-05-15 15:01:00', '2026-05-16 12:35:35'),
(5360, 806, 2, 'Cho cà rốt, hành tây, tỏi, hạt thì là, hạt rau mùi, muối và dầu ô liu vào tô và trộn đều. Chuyển lên khay nướng.', NULL, '2026-05-15 15:01:00', '2026-05-16 12:35:35'),
(5362, 806, 3, 'Đặt khay nướng vào lò nướng đã làm nóng trước và nướng trong vòng 10-12 phút hoặc cho đến khi cà rốt mềm. Hủy bỏ nhiệt và mát mẻ.', NULL, '2026-05-15 15:01:00', '2026-05-16 12:35:35'),
(5364, 806, 4, 'Nghiền hỗn hợp cà rốt nướng cùng với một ít nước để tạo thành hỗn hợp mịn và lọc vào tô.', NULL, '2026-05-15 15:01:00', '2026-05-16 12:35:35'),
(5366, 806, 5, 'Đun nóng hỗn hợp cà rốt trong chảo chống dính. Thêm hai cốc nước và đun sôi. Thêm bột garam masala và trộn. Thêm muối và trộn đều.', NULL, '2026-05-15 15:01:00', '2026-05-16 12:35:35'),
(5368, 806, 6, 'Tắt bếp, thêm nước cốt chanh và trộn đều.', NULL, '2026-05-15 15:01:00', '2026-05-16 12:35:35'),
(5370, 806, 7, 'Ăn nóng.', NULL, '2026-05-15 15:01:00', '2026-05-16 12:35:35'),
(5371, 807, 1, 'Ngâm nấm khô trong 350ml nước sôi và để riêng cho đến khi cần. Nghiền ¾ hạt dẻ với 150ml nước cho đến khi thành kem. Cắt nhỏ số hạt dẻ còn lại.', NULL, '2026-05-15 15:01:03', '2026-05-15 15:01:03'),
(5372, 807, 2, 'Đun nóng 2 muỗng canh dầu ô liu trong chảo chống dính lớn. Chiên hẹ với một chút muối cho đến khi mềm, sau đó thêm tỏi, hạt dẻ cắt nhỏ và hương thảo vào xào thêm 2 phút nữa. Thêm nấm hoang dã, 2 muỗng canh dầu và một ít gia vị. Nấu trong 3 phút cho đến khi chúng bắt đầu mềm. Để ráo nước và cắt nhỏ nấm khô (dự trữ nước ngâm), sau đó thêm chúng vào cùng với nước tương và chiên thêm 2 phút nữa.', NULL, '2026-05-15 15:01:03', '2026-05-15 15:01:03'),
(5373, 807, 3, 'Đánh đều rượu vang, nước nấm dành riêng và kem hạt dẻ với nhau để tạo thành nước sốt. Nêm gia vị, sau đó cho một nửa vào hỗn hợp nấm trong chảo và nấu trong 1 phút cho đến khi nước sốt trở nên bóng. Loại bỏ các nhánh hương thảo, sau đó đặt hỗn hợp sang một bên.', NULL, '2026-05-15 15:01:03', '2026-05-15 15:01:03'),
(5374, 807, 4, 'Làm nóng lò ở mức quạt/gas 180C/160C 4. Đun sôi một chảo nước muối lớn và chuẩn bị sẵn một tô nước đá lớn. Thả các tấm lasagne vào nước sôi trong 2 phút hoặc cho đến khi mềm và chín một chút, sau đó ngâm ngay vào nước lạnh. Dùng ngón tay cẩn thận tách các tờ giấy ra và chuyển vào một chiếc khăn trà sạch. Rưới một thìa nước sốt vừa đủ lên 2/3 dưới cùng của mỗi tờ giấy, sau đó lăn ra xa, cuộn các đầu ngắn hơn lại. Cắt mỗi cuộn làm đôi, sau đó đặt các cuộn mì ống đã cắt úp vào đĩa bánh mà bạn sẵn lòng phục vụ tại bàn. Nếu bạn còn sót lại nước sốt nấm sau khi cuộn tất cả các tờ giấy lại, bạn chỉ cần ấn nó vào một số cuộn mì ống lộ ra ngoài.', NULL, '2026-05-15 15:01:03', '2026-05-15 15:01:03'),
(5375, 807, 5, 'Đổ phần nước sốt còn lại lên trên mì ống, sau đó nướng trong 10 phút hoặc cho đến khi mì ống không còn lực cản khi thử bằng xiên.', NULL, '2026-05-15 15:01:03', '2026-05-15 15:01:03'),
(5376, 807, 6, 'Trong khi đó, cho vụn bánh mì, 2 muỗng canh dầu ô liu cuối cùng, lá xô thơm và một ít gia vị vào tô rồi trộn mọi thứ lại với nhau. Rải bánh quay với vụn bánh mì và lá xô thơm, sau đó nướng thêm 10 phút nữa cho đến khi mặt trên vàng và lá xô thơm giòn. Để nguội trong 10 phút để mì ống thấm nước sốt, sau đó rưới một ít dầu truffle nếu bạn thích trước khi dọn món ăn ra bàn.', NULL, '2026-05-15 15:01:03', '2026-05-15 15:01:03'),
(5377, 808, 1, 'Để làm kem cải ngựa, trộn kem tươi, cải ngựa nghiền, nước cốt chanh, muối và tiêu trắng vào tô. Làm lạnh cho đến khi phục vụ.', NULL, '2026-05-15 15:01:07', '2026-05-15 15:01:07'),
(5378, 808, 2, 'Để làm hẹ tây giòn, hãy đun nóng một ít dầu thực vật trong chảo rán trên lửa vừa. Thêm hẹ tây thái lát và chiên cho đến khi vàng nâu và giòn.', NULL, '2026-05-15 15:01:07', '2026-05-15 15:01:07'),
(5379, 808, 3, 'Dùng thìa có rãnh vớt ra và để ráo nước trên đĩa có lót giấy ăn. Nêm một chút muối.', NULL, '2026-05-15 15:01:07', '2026-05-15 15:01:07'),
(5380, 808, 4, 'Để làm bánh sandwich mở, hãy đun sôi một nồi nước muối lớn, sau đó chần một nửa số măng tây (bốn măng tây trắng và bốn măng xanh) cho đến khi mềm giòn, khoảng 2–3 phút.', NULL, '2026-05-15 15:01:07', '2026-05-15 15:01:07'),
(5381, 808, 5, 'Thêm đá vào tô nước lạnh. Dùng thìa có rãnh vớt măng tây ra khỏi nước sôi rồi chuyển ngay sang nước đá để ngừng nấu. Cắt mỏng măng tây còn lại theo chiều dọc để dùng sống.', NULL, '2026-05-15 15:01:07', '2026-05-15 15:01:07'),
(5382, 808, 6, 'Làm nóng lò nướng trước cho đến khi nóng. Phết bơ lên ​​bánh mì lúa mạch đen và nướng cho đến khi vàng và giòn.', NULL, '2026-05-15 15:01:07', '2026-05-15 15:01:07'),
(5383, 808, 7, 'Để phục vụ, đặt các lát bánh mì nướng lên đĩa phục vụ. Xếp cả măng tây đã chần và măng tây sống lên trên bánh mì. Rưới kem cải ngựa, sau đó rắc phô mai bào lên trên. Trang trí với hẹ tây giòn và một ít thì là tươi để hoàn thành.', NULL, '2026-05-15 15:01:07', '2026-05-15 15:01:07'),
(5385, 809, 1, 'Đun nóng dầu trong chảo rồi cho hành tây vào xào khoảng 5 phút cho đến khi mềm. Thêm tỏi, cà chua xắt nhỏ, cà chua xay nhuyễn, ớt bột ngọt, bột ớt, đường và một chút muối, sau đó đun sôi, thỉnh thoảng khuấy. Hạ nhỏ lửa và nấu trong 10 phút cho đến khi mềm. Có thể giữ lạnh lên đến 24 giờ.', NULL, '2026-05-15 15:01:10', '2026-05-16 12:35:35');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(5387, 809, 2, 'Làm nóng lò nướng ở mức quạt/gas 200C/180C 6. Dùng giấy ăn thấm khô khoai tây, sau đó cho vào hộp thiếc nướng và cho dầu ô liu cùng một ít gia vị vào. Nướng trong 40-50 phút cho đến khi giòn và vàng. Đổ khoai tây vào đĩa và rưới nước sốt cà chua lên trên. Rắc một ít rau mùi tây tươi để phục vụ.', NULL, '2026-05-15 15:01:10', '2026-05-16 12:35:35'),
(5389, 810, 1, 'Đun nóng dầu trong chảo lớn chống cháy hoặc chảo gang ở lửa nhỏ. Thêm hành tây và rắc muối, đậy nắp và nấu nhẹ trong 15 phút, thỉnh thoảng khuấy. Thêm tỏi và nấu thêm 2 phút nữa.', NULL, '2026-05-15 15:01:13', '2026-05-16 12:35:35'),
(5391, 810, 2, 'Tiếp theo, cho ớt vào nấu trên lửa vừa, đậy nắp trong khoảng 5 phút, thỉnh thoảng khuấy đều cho đến khi ớt vừa mềm.', NULL, '2026-05-15 15:01:13', '2026-05-16 12:35:35'),
(5393, 810, 3, 'Trộn lá oregano, húng tây, lá nguyệt quế, một ít hạt tiêu đen và một chút muối nếu cần. Cho bí và cà tím vào, trộn kỹ và nấu trên lửa vừa, đậy nắp trong 10 phút. Cho cà chua vào, đậy nắp và nấu trong 20 phút, thỉnh thoảng khuấy.', NULL, '2026-05-15 15:01:13', '2026-05-16 12:35:35'),
(5395, 810, 4, 'Cẩn thận đập trứng vào khuôn – cố gắng không làm vỡ lòng đỏ. Nấu trong nước sốt ở lửa vừa trong 5-6 phút cho đến khi trứng chín nhưng vẫn hơi mềm, sau đó rắc rau mùi tây trước khi dùng', NULL, '2026-05-15 15:01:13', '2026-05-16 12:35:35'),
(5397, 811, 1, 'Kết hợp dầu ô liu, nước cốt chanh, mật ong và lá húng tây trong một tô lớn. Nêm gia vị thật kỹ, sau đó cho rau diếp, cà chua, hành lá và ớt vào trộn đều.', NULL, '2026-05-15 15:01:16', '2026-05-16 12:35:35'),
(5399, 811, 2, 'Múc hạt lựu ra bát và loại bỏ lớp màng trắng. Xếp salad đã trộn lên đĩa, sau đó rải lên hạt lựu và feta.', NULL, '2026-05-15 15:01:16', '2026-05-16 12:35:35'),
(5400, 812, 1, 'Cắt khoai tây và cà rốt thành những khối nhỏ đều nhau.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5401, 812, 2, 'Đặt chúng vào một cái nồi lớn và đổ đầy nước.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5402, 812, 3, 'Thêm muối và giấm. Đun sôi ở lửa vừa cao, sau đó giảm lửa xuống mức vừa và tiếp tục nấu cho đến khi khoai tây chín hẳn, khoảng 15 phút. Xả khoai tây và để nguội đến nhiệt độ phòng.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5403, 812, 4, 'Trong khi đó, cắt xúc xích và dưa chua thành khối nhỏ và cắt nhỏ hành lá.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5404, 812, 5, 'Trứng luộc chín cũng cắt thành khối nhỏ.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5405, 812, 6, 'Nếu sử dụng thì là tươi, hãy cắt nhỏ chúng.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5406, 812, 7, 'Trong một tô lớn, trộn khoai tây, cà rốt, xúc xích, dưa chua, đậu Hà Lan và hành lá.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5407, 812, 8, 'Thêm mayo và thì là và trộn cho đến khi kết hợp tốt.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5408, 812, 9, 'Muối và hạt tiêu cho vừa ăn. Đậy lại bằng màng bọc thực phẩm và để lạnh ít nhất 1 giờ trước khi dùng.', NULL, '2026-05-15 15:01:18', '2026-05-15 15:01:18'),
(5409, 813, 1, 'Đập trứng vào hai cái bát, mỗi cái năm cái. Đánh nhẹ và nêm muối và hạt tiêu. Đun nóng dầu trong chảo, cho bí và hành lá vào xào nhẹ khoảng 10 phút cho đến khi mềm. Để nguội rồi cho trứng vào tô trộn cùng chút muối và tiêu. Thêm ớt nướng vào tô trứng còn lại cùng với tỏi, ớt, muối và tiêu.', NULL, '2026-05-15 15:01:21', '2026-05-15 15:01:21'),
(5410, 813, 2, 'Đun nóng một ít dầu trong chảo rán 20-23cm, tốt nhất là không dính. Đổ trứng và bí xanh vào bình đong, sau đó đổ khoảng 1/3 hỗn hợp vào chảo, xoay sao cho ngập đáy chảo. Nấu cho đến khi trứng chín và chín vàng nhẹ bên dưới, sau đó dùng đĩa đậy chảo lại và úp trứng tráng lên trên. Trượt nó trở lại chảo để nấu mặt còn lại. Lặp lại với hỗn hợp còn lại để làm thêm hai món trứng tráng nữa, mỗi lần thêm một ít dầu vào chảo. Xếp trứng tráng lên đĩa. Làm ba món trứng tráng theo cách tương tự với hỗn hợp ớt đỏ, sau đó xếp chúng ra một đĩa riêng.', NULL, '2026-05-15 15:01:21', '2026-05-15 15:01:21'),
(5411, 813, 3, 'Bây giờ làm nhân. Đánh phô mai cho mềm, sau đó cho sữa vào đánh để tạo thành hỗn hợp sệt dễ phết. Khuấy các loại thảo mộc, muối và hạt tiêu. Lót màng dính vào khuôn bánh tròn sâu 20-23 cm (dùng khuôn có cùng kích thước với chảo rán). Chọn món trứng tráng ớt đỏ ngon nhất và đặt vào hộp thiếc, mặt đẹp nhất hướng xuống dưới. Trải một lớp phô mai mỏng lên trên, sau đó phủ một lớp trứng tráng bí xanh. Lặp lại, xen kẽ các lớp cho đến khi tất cả trứng tráng và nhân đều ở trong hộp thiếc, kết thúc bằng trứng tráng. Lật màng bọc thực phẩm lên món trứng tráng, sau đó để lạnh trong tối đa 24 giờ.', NULL, '2026-05-15 15:01:21', '2026-05-15 15:01:21'),
(5412, 813, 4, 'Để phục vụ, hãy úp bánh trứng tráng lên đĩa phục vụ và bóc lớp màng bám. Xếp tên lửa lên trên và rải lên phô mai, một chút dầu ô liu và một ít hạt tiêu đen mới xay. Phục vụ cắt thành nêm.', NULL, '2026-05-15 15:01:21', '2026-05-15 15:01:21'),
(5413, 814, 1, 'Cắt cà tím làm đôi theo chiều dọc. Đặt chúng lên bảng, cắt úp xuống, cắt làm đôi theo chiều dọc rồi cắt thành từng đoạn 1,5 cm. Cắt bỏ hai đầu bí, sau đó cắt thành từng lát dày 1,5cm. Gọt vỏ ớt từ cuống đến đáy. Giữ thẳng, cắt quanh cuống rồi cắt làm 3 khúc. Cắt bỏ phần màng rồi cắt thành từng miếng vừa ăn.', NULL, '2026-05-15 15:01:23', '2026-05-15 15:01:23'),
(5414, 814, 2, 'Chấm một đường chéo nhỏ lên gốc mỗi quả cà chua, sau đó cho vào tô chịu nhiệt. Đổ nước sôi lên cà chua, để khoảng 20 giây rồi vớt ra. Đổ nước đi, thay cà chua vào và tráng lại bằng nước lạnh. Để nguội rồi lột bỏ vỏ. Cà chua cắt làm tư, dùng thìa cạo bỏ hạt, sau đó cắt nhỏ phần thịt.', NULL, '2026-05-15 15:01:23', '2026-05-15 15:01:23'),
(5415, 814, 3, 'Đặt chảo xào trên lửa vừa và khi nóng, đổ 2 muỗng canh dầu ô liu vào. Chiên cà tím trong 5 phút mỗi mặt cho đến khi các miếng cà tím mềm. Đặt chúng sang một bên và chiên bí trong một muỗng canh dầu khác trong 5 phút, cho đến khi vàng cả hai mặt. Lặp lại với ớt. Đừng nấu rau quá chín ở giai đoạn này vì rau vẫn còn được nấu ở bước tiếp theo.', NULL, '2026-05-15 15:01:23', '2026-05-15 15:01:23'),
(5416, 814, 4, 'Xé lá húng quế và đặt sang một bên. Nấu hành tây trong chảo trong 5 phút. Thêm tỏi và chiên thêm một phút nữa. Khuấy giấm và đường, sau đó cho cà chua và một nửa húng quế vào. Cho rau vào chảo cùng chút muối và tiêu rồi nấu trong 5 phút. Ăn kèm với húng quế.', NULL, '2026-05-15 15:01:23', '2026-05-15 15:01:23'),
(5417, 815, 1, 'Cho 2 muỗng canh dầu vào nồi lớn trên lửa vừa. Khi nóng thì cho hành tây, cà rốt, cần tây và tỏi vào; rắc muối và hạt tiêu rồi nấu, thỉnh thoảng khuấy đều cho đến khi rau mềm, từ 5 đến 10 phút.', NULL, '2026-05-15 15:01:25', '2026-05-15 15:01:25'),
(5418, 815, 2, 'Làm nóng lò ở nhiệt độ 500 độ. Xả đậu; nếu chúng được đóng hộp, hãy rửa sạch chúng. Thêm chúng vào nồi cùng với cà chua và nước ép của chúng, nước kho, hương thảo và húng tây. Đun sôi, sau đó giảm nhiệt để súp sủi bọt đều; đậy nắp và nấu, khuấy một hoặc hai lần để làm vỡ cà chua, cho đến khi hương vị hòa quyện, từ 15 đến 20 phút.', NULL, '2026-05-15 15:01:25', '2026-05-15 15:01:25'),
(5419, 815, 3, 'Vớt cá ra và loại bỏ cọng hương thảo và húng tây nếu bạn thích rồi cho cải xoăn vào trộn. Hương vị và điều chỉnh gia vị. Đặt các lát bánh mì lên trên món hầm sao cho chúng phủ kín mặt trên và ít chồng lên nhau nhất có thể. Rắc các lát hành tây đỏ lên trên, rưới 3 thìa dầu còn lại và rắc Parmesan.', NULL, '2026-05-15 15:01:25', '2026-05-15 15:01:25'),
(5420, 815, 4, 'Đặt nồi vào lò nướng và nướng cho đến khi bánh mì, hành tây và phô mai chín vàng và giòn, khoảng 10 đến 15 phút. (Nếu nồi của bạn vừa với gà thịt, bạn cũng có thể nướng phần trên ở đó.) Chia súp và bánh mì cho 4 bát và dùng.', NULL, '2026-05-15 15:01:25', '2026-05-15 15:01:25'),
(5422, 816, 1, 'Làm nóng lò ở mức quạt/khí 200C/180C 6. Quét 1 muỗng canh dầu lên các lát cà tím, sau đó nêm gia vị. Xếp lên khay hoặc khay nướng và nướng trong 20 phút cho đến khi chín vàng, xếp cà chua lên khay trong 5 phút cuối cùng. Xé bánh mì dẹt thành từng miếng và đặt lên một khay nướng riêng. Nướng trong lò khoảng 8 phút hoặc cho đến khi giòn thì lấy ra.', NULL, '2026-05-15 15:01:29', '2026-05-16 12:35:35'),
(5424, 816, 2, 'Để làm nước sốt, trong một bát nhỏ, trộn giấm, bạc hà, hẹ tây xắt nhỏ, ớt, dầu còn lại và một ít muối và hạt tiêu.', NULL, '2026-05-15 15:01:29', '2026-05-16 12:35:35'),
(5426, 816, 3, 'Rải các lát cà tím, cà chua, hẹ tây thái lát và bánh mì dẹt giòn vào tô phục vụ. Đổ nước sốt lên trên, rắc phô mai dê và rải lên một ít tên lửa.', NULL, '2026-05-15 15:01:29', '2026-05-16 12:35:35'),
(5427, 817, 1, 'Đối với Đậu lăng: Điều chỉnh giá đỡ của lò về vị trí chính giữa và làm nóng lò trước ở nhiệt độ 450°F để chuẩn bị rang cà tím. Trong khi đó, đun nóng 2 muỗng canh dầu ô liu trong chảo vừa trên lửa vừa cho đến khi sủi bọt. Thêm cà rốt, cần tây và hành tây vào nấu, khuấy đều cho đến khi mềm nhưng không chuyển sang màu nâu, khoảng 4 phút. Thêm tỏi và nấu, khuấy đều cho đến khi có mùi thơm, khoảng 30 giây. Thêm đậu lăng, lá nguyệt quế, nước luộc hoặc nước và một chút muối. Đun sôi, đậy nắp hé mở một phần và nấu cho đến khi đậu lăng mềm, khoảng 30 phút. (Thêm nước nếu đậu lăng chưa ngập hoàn toàn.) Mở nắp, cho giấm vào khuấy đều và đun nhỏ lửa cho đến khi đậu lăng ẩm nhưng không bị nhão. Nêm muối và hạt tiêu cho vừa ăn, đậy nắp và giữ ấm cho đến khi sẵn sàng phục vụ.', NULL, '2026-05-15 15:01:31', '2026-05-15 15:01:31'),
(5428, 817, 2, 'Đối với cà tím: Trong khi nấu đậu lăng, hãy cắt từng quả cà tím làm đôi. Dùng đầu dao gọt thịt theo hình chữ thập với khoảng cách 1 inch. Chuyển sang khay nướng có viền có lót giấy bạc, cắt mặt lên và phết 1 thìa dầu vào mỗi nửa quả cà tím, để mỗi nét cọ thấm hoàn toàn trước khi phết thêm dầu. Nêm muối và hạt tiêu. Đặt một nhánh hương thảo lên trên mỗi cành. Chuyển vào lò nướng và nướng cho đến khi mềm hoàn toàn và cháy kỹ, từ 25 đến 35 phút. Lấy ra khỏi lò và loại bỏ hương thảo.', NULL, '2026-05-15 15:01:31', '2026-05-15 15:01:31'),
(5429, 817, 3, 'Cách dùng: Đun nóng 2 muỗng canh dầu ô liu và hạt thông trong chảo vừa đặt trên lửa vừa. Nấu, đảo hạt thường xuyên cho đến khi có màu vàng nâu và thơm, khoảng 4 phút. Chuyển sang tô để tạm dừng nấu. Khuấy một nửa mùi tây và hương thảo vào đậu lăng rồi chuyển sang đĩa phục vụ. Xếp nửa quả cà tím lên trên. Rưới một vài thìa nước sốt tahini lên mỗi nửa quả cà tím và rắc hạt thông. Rắc thêm mùi tây và hương thảo còn lại, rưới thêm dầu ô liu và thưởng thức.', NULL, '2026-05-15 15:01:31', '2026-05-15 15:01:31'),
(5431, 818, 1, 'Đầu tiên, làm hẹ giòn. Đun nóng dầu trong chảo đến 180C (một khối bánh mì sẽ chuyển sang màu vàng sau 15 giây). Trộn hẹ tây với một ít bột mì và chiên ngập dầu trong 1 phút hoặc cho đến khi vàng nhạt và giòn. Xả trên giấy ăn. Có thể pha trước hai ngày và bảo quản trong hộp kín.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5433, 818, 2, 'Để làm nhân, đun nóng dầu trong chảo chống dính vừa và nhẹ nhàng chiên hẹ trong 10 phút cho đến khi bắt đầu chuyển sang màu vàng.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5435, 818, 3, 'Thêm dưa cải bắp và bắp cải vào nấu trong 5-10 phút cho đến khi bắp cải mềm. Nếm thử và thêm một chút muối nếu chưa chín hoặc thêm đường nếu đặc. Cạo vào tô và để nguội hoàn toàn.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5437, 818, 4, 'Để làm bột, trộn trứng và dầu với 125ml nước, sau đó cho từ từ bột mì vào, dùng tay trộn đều. Nhào bột trên bề mặt đã rắc bột mì kỹ cho đến khi bột hết dính vào tay. Bạn sẽ có được khối bột chắc và đàn hồi. Bọc nó trong màng dính và để trong tủ lạnh ít nhất 30 phút hoặc qua đêm.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5439, 818, 5, 'Đổ bột lên bề mặt làm việc của bạn một cách hào phóng. Cán bột thành hình tròn có đường kính 40cm hoặc cho đến khi bột dày bằng đồng xu £1.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5441, 818, 6, 'Sử dụng khuôn cắt bánh quy 9 cm, cắt các khoanh tròn trong bột – bạn sẽ có khoảng 25 khoanh tròn. Đừng vứt bỏ những phần thừa – chúng tôi cho chúng vào cùng với bánh pierogi khi đun sôi để giảm thiểu lãng phí.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5443, 818, 7, 'Chuẩn bị sẵn một khay bột mì. Cho 1 thìa nhân vào giữa mỗi đĩa. Dùng tay gấp đôi phần nhân lại và dán kín để tạo thành hình bán nguyệt. Đặt chúng lên khay đã tráng bột mì, đảm bảo chúng không chạm vào nhau.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5445, 818, 8, 'Đun sôi một nồi nước muối lớn rồi cẩn thận thả bánh pierogi vào. Đun sôi trong 2 phút hoặc cho đến khi chúng nổi lên trên.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5447, 818, 9, 'Để ráo nước và dùng kèm với một ít bơ và một ít kem chua. Kết thúc bằng việc rắc hẹ tây giòn lên trên để thưởng thức.', NULL, '2026-05-15 15:01:34', '2026-05-16 12:35:35'),
(5449, 819, 1, 'Đầu tiên, làm hẹ giòn. Đun nóng dầu trong chảo đến 180C (một khối bánh mì sẽ chuyển sang màu vàng sau 15 giây). Trộn hẹ tây với một ít bột mì và chiên ngập dầu trong 1 phút hoặc cho đến khi vàng nhạt và giòn. Xả trên giấy ăn. Có thể pha trước hai ngày và bảo quản trong hộp kín.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5451, 819, 2, 'Để làm nhân, đun nóng dầu trong chảo chống dính vừa và nhẹ nhàng chiên hẹ trong 10 phút cho đến khi bắt đầu chuyển sang màu vàng.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5453, 819, 3, 'Thêm dưa cải bắp và bắp cải vào nấu trong 5-10 phút cho đến khi bắp cải mềm. Nếm thử và thêm một chút muối nếu chưa chín hoặc thêm đường nếu đặc. Cạo vào tô và để nguội hoàn toàn.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5455, 819, 4, 'Để làm bột, trộn trứng và dầu với 125ml nước, sau đó cho từ từ bột mì vào, dùng tay trộn đều. Nhào bột trên bề mặt đã rắc bột mì kỹ cho đến khi bột hết dính vào tay. Bạn sẽ có được khối bột chắc và đàn hồi. Bọc nó trong màng dính và để trong tủ lạnh ít nhất 30 phút hoặc qua đêm.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5457, 819, 5, 'Đổ bột lên bề mặt làm việc của bạn một cách hào phóng. Cán bột thành hình tròn có đường kính 40cm hoặc cho đến khi bột dày bằng đồng xu £1.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5459, 819, 6, 'Sử dụng khuôn cắt bánh quy 9 cm, cắt các khoanh tròn trong bột – bạn sẽ có khoảng 25 khoanh tròn. Đừng vứt bỏ những phần thừa – chúng tôi cho chúng vào cùng với bánh pierogi khi đun sôi để giảm thiểu lãng phí.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5461, 819, 7, 'Chuẩn bị sẵn một khay bột mì. Cho 1 thìa nhân vào giữa mỗi đĩa. Dùng tay gấp đôi phần nhân lại và dán kín để tạo thành hình bán nguyệt. Đặt chúng lên khay đã tráng bột mì, đảm bảo chúng không chạm vào nhau.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5463, 819, 8, 'Đun sôi một nồi nước muối lớn rồi cẩn thận thả bánh pierogi vào. Đun sôi trong 2 phút hoặc cho đến khi chúng nổi lên trên.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5465, 819, 9, 'Để ráo nước và dùng kèm với một ít bơ và một ít kem chua. Kết thúc bằng việc rắc hẹ tây giòn lên trên để thưởng thức.', NULL, '2026-05-15 15:01:36', '2026-05-16 12:35:35'),
(5466, 820, 1, 'Đun nóng dầu trong chảo có nắp, sau đó cho hành, ớt, tỏi và cọng rau mùi vào phi thơm trong 5 phút cho đến khi mềm. Khuấy cà chua và đường, sau đó đun sôi trong 8-10 phút cho đến khi đặc lại. Có thể trữ đông trong 1 tháng.', NULL, '2026-05-15 15:01:39', '2026-05-15 15:01:39'),
(5467, 820, 2, 'Dùng mặt sau của một chiếc thìa lớn chấm nước sốt 4 lần, sau đó đập một quả trứng vào mỗi thìa. Đậy nắp chảo, sau đó nấu ở lửa nhỏ trong 6-8 phút cho đến khi trứng chín như ý muốn. Rắc lá rau mùi và dùng kèm với bánh mì giòn.', NULL, '2026-05-15 15:01:39', '2026-05-15 15:01:39'),
(5468, 821, 1, 'Công thức này yêu cầu cà tím châu Á hoặc cà tím Nhật Bản. Chúng dài và mỏng so với cà tím châu Âu hoặc cà tím toàn cầu, đồng thời mềm và tinh tế hơn nhiều. Nếu không tìm được, bạn có thể thay thế bằng cà tím cầu, nhưng món ăn này thực sự ngon nhất bằng cà tím châu Á.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5469, 821, 2, '*Hiện nay rất nhiều cửa hàng tạp hóa có lối đi bán nguyên liệu Châu Á. Bạn có thể tìm thấy tương ớt, hỗn hợp ớt bảo quản trộn với đậu nành nghiền ở đó hoặc tại bất kỳ chợ châu Á nào. (Đừng nhầm lẫn với tương đen hoặc tương ớt).', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5470, 821, 3, '**Hạt tiêu Tứ Xuyên có bán tại một số cửa hàng và trực tuyến với giá khá rẻ. Chúng không cay như các loại ớt khác mà có hương vị cam quýt và gây cảm giác tê tê như đồ uống có ga.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5471, 821, 4, 'Chuẩn bị cà tím, tương ớt, bột bắp, dấm và hành lá:', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5472, 821, 5, 'Bắt đầu công việc của bạn tại chỗ. Cắt đôi cà tím theo chiều dọc và cắt thành từng miếng lớn rồi đặt sang một bên.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5473, 821, 6, 'Trong một bát nhỏ, trộn đều nước luộc gà, đường và nước tương rồi đặt sang một bên.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5474, 821, 7, 'Trong bát thứ hai, trộn tương ớt, tỏi, gừng và hạt tiêu Tứ Xuyên rồi đặt sang một bên.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5475, 821, 8, 'Trong bát thứ ba, trộn bột ngô với một thìa nước và đặt sang một bên.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5476, 821, 9, 'Cuối cùng, trong bát thứ tư, trộn hành lá và giấm rồi đặt sang một bên.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5477, 821, 10, 'Cà tím xào:', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5478, 821, 11, 'Cho dầu vào chảo hoặc chảo xào lớn trên lửa vừa cao cho đến khi dầu gần như bốc khói. Thêm cà tím vào và xào, để yên trong vài giây mỗi lần bạn di chuyển để cà tím chuyển sang màu nâu và phồng rộp. Nếu cà tím hút hết dầu và một số miếng không lấy được thì hãy thêm một chút dầu.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5479, 821, 12, 'Thêm tương ớt, tỏi, gừng và hạt tiêu Tứ Xuyên vào xào:', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5480, 821, 13, 'cho đến khi có mùi thơm, khoảng 30 giây.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5481, 821, 14, 'Thêm hỗn hợp nước luộc gà:', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5482, 821, 15, 'vặn lửa ở mức trung bình thấp và đun nhỏ lửa trong 90 giây.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5483, 821, 16, 'Thêm hỗn hợp bột ngô:', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5484, 821, 17, 'và khuấy đều cho đến khi nước sốt đặc lại một chút.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5485, 821, 18, 'Thêm hành lá và giấm:', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5486, 821, 19, 'và nấu trong 15 giây để khuếch tán hương vị gắt của chúng một chút.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5487, 821, 20, 'Trang trí với rau mùi và phục vụ.', NULL, '2026-05-15 15:01:42', '2026-05-15 15:01:42'),
(5488, 822, 1, 'Đậu dài Trung Quốc có thể được tìm thấy ở cả hai loại xanh và tím. Cả hai đều có hương vị và kết cấu tương tự nhau và cả hai loại đều có thể được sử dụng cho công thức này.', NULL, '2026-05-15 15:01:44', '2026-05-15 15:01:44'),
(5489, 822, 2, 'Nếu bạn không có chảo, hãy sử dụng một chiếc chảo xào lớn, chắc chắn và có mép dày ít nhất 2 inch.', NULL, '2026-05-15 15:01:44', '2026-05-15 15:01:44'),
(5490, 823, 1, 'Chuẩn bị đậu phụ:', NULL, '2026-05-15 15:01:47', '2026-05-15 15:01:47'),
(5491, 823, 2, 'Để ráo đậu phụ và nhẹ nhàng lấy đậu ra khỏi bao bì đặt trên một đĩa lớn. Cẩn thận cắt đậu phụ thành các tấm có chiều rộng 1/2 inch. Dùng lòng bàn tay nhẹ nhàng đẩy đậu phụ đã thái lát sang một bên để chúng tỏa ra khắp đĩa.', NULL, '2026-05-15 15:01:47', '2026-05-15 15:01:47'),
(5492, 823, 3, 'Trang trí với topping và thưởng thức:', NULL, '2026-05-15 15:01:47', '2026-05-15 15:01:47'),
(5493, 823, 4, 'Rưới nước tương và mè lên trên. Sau đó trang trí với hành lá và hạt mè rồi thưởng thức.', NULL, '2026-05-15 15:01:47', '2026-05-15 15:01:47'),
(5494, 823, 5, 'Đậy kín thức ăn thừa và để trong tủ lạnh tối đa 2 ngày. Bạn có thể thưởng thức nó khi nguội ngay khi lấy ra khỏi tủ lạnh hoặc bạn có thể hâm nóng lại bằng cách cho vào lò vi sóng trong khoảng thời gian 30 giây cho đến khi ấm hoàn toàn.', NULL, '2026-05-15 15:01:47', '2026-05-15 15:01:47'),
(5495, 824, 1, 'Bắt đầu bằng cách nướng bí. Cắt nó thành những hình lưỡi liềm mỏng và rưới một ít dầu và rắc muối biển. Tôi đã thêm một ít cây xô thơm tươi có trong tủ lạnh, nhưng điều đó không cần thiết. Nướng bí ở nhiệt độ 205 C (400 F) trong 20-30 phút, lật nửa chừng cho đến khi mềm và vàng. Để nguội và cắt thành khối.', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5496, 824, 2, 'Trong khi đó, rửa sạch đậu lăng và đổ nước vào. Đun sôi rồi vặn nhỏ lửa và nấu (không đậy nắp) trong 20-30 phút hoặc cho đến khi mềm. Xả và đặt sang một bên.', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5497, 824, 3, 'Trong khi nấu đậu lăng, đun nóng 1 muỗng canh. dầu ở mức thấp trong nồi vừa. Thêm hành tây và tỏi tây vào xào khoảng 5 phút hoặc cho đến khi chúng bắt đầu mềm. Thêm tỏi tiếp theo cùng với thì là và rau mùi, nấu thêm vài phút. Thêm các loại gia vị còn lại – ớt bột, quế, ớt, ca cao, sốt Worcestershire, muối và lá oregano. Tiếp theo, thêm hộp cà chua, nước hoặc nước kho và cà rốt. Đun nhỏ lửa, đậy nắp trong 20 phút hoặc cho đến khi rau mềm và hỗn hợp đặc lại. Bạn sẽ cần kiểm tra nồi định kỳ để biết độ khuấy và lượng chất lỏng trên cùng nếu cần.', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5498, 824, 4, 'Thêm đậu lăng và bí nướng xắt nhỏ. Để nấu thêm 10 phút nữa cho nóng.', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5499, 824, 5, 'Ăn kèm với ớt jalapeno thái lát, chanh, ngò, hành lá và kem chua hạt điều.', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5500, 824, 6, 'KEM CHUA ĐIỀU ĐƠN GIẢN', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5501, 824, 7, '1 cốc hạt điều sống không muối', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5502, 824, 8, 'Nhấm muối biển', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5503, 824, 9, '1 muỗng cà phê. Giấm táo', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5504, 824, 10, 'Nước', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5505, 824, 11, 'Đun sôi một ít nước và dùng nước đó để ngâm hạt điều trong ít nhất bốn giờ. Ngoài ra, bạn có thể dùng nước lạnh và ngâm hạt điều qua đêm, nhưng mình hay quên/lười nên thường dùng phương pháp đun sôi sẽ nhanh hơn rất nhiều.', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5506, 824, 12, 'Sau khi hạt điều đã ngâm, để ráo nước và cho vào máy xay tốc độ cao. Bắt đầu xay nhuyễn, từ từ thêm khoảng 1/2 cốc nước ngọt cho đến khi đạt được độ sệt như kem. Bạn có thể cần thêm ít hoặc nhiều nước hơn để đạt được độ đặc mong muốn.', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5507, 824, 13, 'Thêm một chút muối biển và giấm (hoặc nước cốt chanh).', NULL, '2026-05-15 15:01:50', '2026-05-15 15:01:50'),
(5508, 825, 1, 'Đặt một chiếc chảo chống dính lớn ở lửa nhỏ. Nấu hành tây từ từ trong dầu và bơ cho đến khi mềm nhưng không có màu nâu – quá trình này sẽ mất khoảng 15 phút. Thêm khoai tây, đậy nắp chảo và nấu thêm 15-20 phút nữa, thỉnh thoảng khuấy để đảm bảo chúng chiên đều.', NULL, '2026-05-15 15:01:53', '2026-05-15 15:01:53'),
(5509, 825, 2, 'Khi khoai tây mềm và hành tây bóng thì đập dập 2 tép tỏi rồi đảo đều, sau đó cho trứng đánh vào.', NULL, '2026-05-15 15:01:53', '2026-05-15 15:01:53'),
(5510, 825, 3, 'Đậy nắp lại chảo và để bánh tortilla chín nhẹ. Sau 20 phút, các cạnh và đế sẽ có màu vàng, phần trên đã ổn định nhưng phần giữa vẫn hơi lung lay. Để lật nó lại, hãy trượt nó lên một cái đĩa và đặt một cái đĩa khác lên trên, lật lại toàn bộ và trượt lại vào chảo để nấu xong. Sau khi nấu chín, chuyển ra đĩa và dùng bánh tortilla ấm hoặc nguội, rải rác với rau mùi tây cắt nhỏ.', NULL, '2026-05-15 15:01:53', '2026-05-15 15:01:53'),
(5511, 825, 4, 'Để đi kèm, hãy lấy những lát bánh mì đã ấm, dùng nĩa đâm khắp nơi và chà xát với số tỏi còn lại, xếp lên cà chua bào và nêm muối biển và một chút dầu ô liu.', NULL, '2026-05-15 15:01:53', '2026-05-15 15:01:53'),
(5516, 827, 1, 'Đun sôi một nồi nước lớn. Thêm muối kosher vào nước sôi, sau đó thêm mì ống. Nấu theo hướng dẫn trên bao bì, khoảng 9 phút.', NULL, '2026-05-15 15:01:57', '2026-05-15 15:01:57'),
(5517, 827, 2, 'Trong chảo lớn trên lửa vừa cao, thêm dầu ô liu và đun nóng cho đến khi dầu bắt đầu sủi bọt. Thêm tỏi và nấu, khuấy đều cho đến khi có mùi thơm, từ 1 đến 2 phút. Thêm cà chua xắt nhỏ, mảnh ớt đỏ, gia vị Ý và muối và hạt tiêu cho vừa ăn. Đun sôi và nấu trong 5 phút. Tắt bếp và thêm húng quế cắt nhỏ.', NULL, '2026-05-15 15:01:57', '2026-05-15 15:01:57'),
(5518, 827, 3, 'Xả mì ống và thêm nó vào nước sốt. Trang trí với mảnh Parmigiano-Reggiano và thêm húng quế và dùng nóng.', NULL, '2026-05-15 15:01:57', '2026-05-15 15:01:57'),
(5519, 828, 1, 'Nấu khoai tây - cho khoai tây vào nồi nước lạnh rồi đun sôi. Đun sôi 20 phút hoặc cho đến khi khoai tây mềm. Bạn biết chúng đã chín khi bạn có thể đâm một con dao vào chúng và con dao sẽ đâm thẳng vào.', NULL, '2026-05-15 15:02:04', '2026-05-15 15:02:04'),
(5520, 828, 2, 'Kết hợp gia vị harissa, dầu ô liu, muối, hạt tiêu và nước cốt chanh vào một cái bát nhỏ và đánh cho đến khi hòa quyện.', NULL, '2026-05-15 15:02:04', '2026-05-15 15:02:04'),
(5521, 828, 3, 'Sau khi khoai tây chín, để ráo nước và cắt khoai tây làm đôi.', NULL, '2026-05-15 15:02:04', '2026-05-15 15:02:04'),
(5522, 828, 4, 'Thêm hỗn hợp harissa và hành lá/hành lá vào khoai tây rồi khuấy đều.', NULL, '2026-05-15 15:02:04', '2026-05-15 15:02:04'),
(5523, 828, 5, 'Trong một bát salad lớn, bày rau arugula/tên lửa.', NULL, '2026-05-15 15:02:04', '2026-05-15 15:02:04'),
(5524, 828, 6, 'Top với hỗn hợp khoai tây và quăng.', NULL, '2026-05-15 15:02:04', '2026-05-15 15:02:04'),
(5525, 828, 7, 'Thêm fetta, bạc hà và rắc lên hạt thông.', NULL, '2026-05-15 15:02:04', '2026-05-15 15:02:04'),
(5526, 828, 8, 'Điều chỉnh muối và hạt tiêu cho vừa ăn.', NULL, '2026-05-15 15:02:04', '2026-05-15 15:02:04'),
(5527, 829, 1, 'Đầu tiên làm nước sốt cà chua. Đun nóng dầu trong chảo lớn và xào tỏi trong 1 phút. Thêm đường, giấm, cà chua và một ít gia vị rồi đun nhỏ lửa trong 20 phút, thỉnh thoảng khuấy đều cho đến khi đặc lại. Thêm húng quế và chia nước sốt cho 2 hoặc nhiều đĩa chịu nhiệt trong lò nướng (xem Mẹo đông lạnh bên dưới). Đặt sang một bên. Làm nước sốt bằng cách đánh mascarpone với sữa cho đến khi mịn, nêm gia vị rồi đặt sang một bên.', NULL, '2026-05-15 15:02:08', '2026-05-15 15:02:08'),
(5528, 829, 2, 'Cho rau bina vào một cái chao lớn và đổ vào ấm nước sôi để làm héo nó (bạn có thể phải làm theo từng đợt). Khi đủ nguội để xử lý, vắt bớt nước thừa. Cắt nhỏ rau bina và trộn vào tô lớn với 100g Parmesan và ricotta. Nêm kỹ với muối, hạt tiêu và hạt nhục đậu khấu.', NULL, '2026-05-15 15:02:08', '2026-05-15 15:02:08'),
(5529, 829, 3, 'Làm nóng lò ở mức quạt/khí 200C/180C 6. Dùng túi bắt kem hoặc túi nhựa đựng thực phẩm đã cắt bớt một góc, bóp nhân vào các ống cannelloni. Đặt các ống cạnh nhau lên trên nước sốt cà chua và rưới lên nước sốt mascarpone. Top với Parmesan và mozzarella. Bây giờ bạn có thể đông lạnh cannelloni, chưa nấu chín hoặc bạn có thể nấu chín trước rồi đông lạnh. Nướng trong 30-35 phút cho đến khi vàng và sủi bọt. Lấy ra khỏi lò và để yên trong 5 phút trước khi dùng.', NULL, '2026-05-15 15:02:08', '2026-05-15 15:02:08'),
(5530, 830, 1, 'Làm nóng lò ở mức quạt/gas 200C/180C 6. Đặt bí và tỏi lên khay nướng rồi rưới dầu ô liu lên. Nướng trong 35-40 phút cho đến khi mềm. Mùa.', NULL, '2026-05-15 15:02:11', '2026-05-15 15:02:11'),
(5531, 830, 2, 'Nấu mì ống theo hướng dẫn trên bao bì. Xả nước, dự trữ nước. Dùng máy xay sinh tố dạng que xay nhuyễn bí với 400ml nước nấu. Đun nóng một ít dầu trong chảo, chiên cây xô thơm cho đến khi giòn rồi vớt ra giấy thấm dầu. Đổ mì ống và nước sốt vào chảo và hâm nóng. Rải cây xô thơm.', NULL, '2026-05-15 15:02:11', '2026-05-15 15:02:11'),
(5532, 831, 1, 'Đun nóng dầu trong chảo 12 inch trên lửa cao cho đến khi sủi bọt. Thêm cà tím và giảm nhiệt xuống mức trung bình. Nêm muối và hạt tiêu khi bạn xoay cà tím, cho chúng chín vàng đều các mặt. Tiếp tục nấu, đảo thường xuyên cho đến khi chiếc nĩa cắm vào cà tím không gặp lực cản (bạn có thể phải đặt chúng lên trên đầu mỡ của chúng để nấu xong những phần dày nhất), khoảng 20 phút, giảm nhiệt và rưới nước vào chảo nếu cần thiết nếu cà tím có nguy cơ cháy hoặc bốc khói quá mức.', NULL, '2026-05-15 15:02:13', '2026-05-15 15:02:13'),
(5533, 831, 2, 'Trộn harissa, đậu xanh và cà chua với nhau, sau đó thêm vào cà tím. Nấu cho đến khi cà chua phồng rộp và nát ra, khoảng 5 phút nữa. Nêm muối và hạt tiêu và thêm nước khi cần thiết để tạo thành hỗn hợp sệt. Trong khi đó, kết hợp sữa chua và thì là vào bát phục vụ. Nêm muối và hạt tiêu.', NULL, '2026-05-15 15:02:13', '2026-05-15 15:02:13'),
(5534, 831, 3, 'Rắc mùi tây lên trên hỗn hợp cà tím, rưới thêm dầu ô liu nguyên chất và dùng kèm với sữa chua.', NULL, '2026-05-15 15:02:13', '2026-05-15 15:02:13'),
(5535, 832, 1, '1. Làm nóng lò nướng ở nhiệt độ 375°F (190°C). Bôi nhẹ một ít dầu vào đĩa nướng 9x13 inch hoặc đĩa thịt hầm có kích thước tương tự.', NULL, '2026-05-15 15:02:15', '2026-05-15 15:02:15'),
(5536, 832, 2, '2. Đặt hai nửa quả ớt chuông vào khay nướng đã chuẩn bị sẵn, cắt mặt hướng lên trên. Nướng trong 15-20 phút, hoặc cho đến khi hơi mềm.', NULL, '2026-05-15 15:02:15', '2026-05-15 15:02:15'),
(5537, 832, 3, '3. Trong khi nướng ớt chuông, chuẩn bị phần nhân. Trong chảo lớn, đun nóng dầu ô liu trên lửa vừa. Thêm hành tây xắt nhỏ vào nấu trong 3-4 phút cho đến khi mềm. Thêm tỏi và nấu thêm 1 phút nữa cho đến khi có mùi thơm.', NULL, '2026-05-15 15:02:15', '2026-05-15 15:02:15'),
(5538, 832, 4, '4. Cho hạt quinoa nấu chín, đậu đen, ngô, cà chua thái hạt lựu, thì là xay, bột ớt, ớt bột xông khói, muối và tiêu vào. Nấu trong 5 - 7 phút, cho đến khi nóng qua. Lấy chảo ra khỏi bếp và cho 1 cốc phô mai cắt nhỏ vào nếu dùng.', NULL, '2026-05-15 15:02:15', '2026-05-15 15:02:15'),
(5539, 832, 5, '5. Lấy ớt chuông ra khỏi lò và cẩn thận nhét từng nửa quả ớt với hỗn hợp quinoa và đậu đen. Phủ 1/2 cốc phô mai cắt nhỏ còn lại lên trên ớt nhồi nếu dùng.', NULL, '2026-05-15 15:02:15', '2026-05-15 15:02:15'),
(5540, 832, 6, '6. Cho ớt đã nhồi vào lò nướng và nướng thêm 15-20 phút nữa cho đến khi phô mai tan chảy và ớt mềm.', NULL, '2026-05-15 15:02:15', '2026-05-15 15:02:15'),
(5541, 832, 7, '7. Lấy ra khỏi lò và để ớt nhồi nguội trong 5 phút trước khi dùng. Trang trí với rau mùi tươi xắt nhỏ.', NULL, '2026-05-15 15:02:15', '2026-05-15 15:02:15'),
(5542, 833, 1, 'Đun nóng 2 thìa dầu trong chảo hoặc nồi lớn trên lửa vừa cho đến khi sủi bọt. Thêm hành vào và nấu, thỉnh thoảng khuấy cho đến khi mềm, từ 5 đến 7 phút.', NULL, '2026-05-15 15:02:19', '2026-05-15 15:02:19'),
(5543, 833, 2, 'Thêm cải xoăn cắt nhỏ vào hành tây và trộn đều. Vặn lửa ở mức trung bình thấp, đậy nắp và nấu trong 5 phút.', NULL, '2026-05-15 15:02:19', '2026-05-15 15:02:19'),
(5544, 833, 3, 'Sau 5 phút, mở nắp, thêm muối vừa ăn rồi cho kem vào khuấy đều. Tiếp tục nấu thêm 5 phút nữa, không đậy nắp, thỉnh thoảng khuấy. Kem sẽ đặc lại một chút, tạo nên món cải xoăn và hành tây có kem thơm ngon. Ngon quá!', NULL, '2026-05-15 15:02:19', '2026-05-15 15:02:19'),
(5545, 833, 4, 'Hãy phục vụ nó với món hầm Kenya yêu thích của bạn và một phần ugali!', NULL, '2026-05-15 15:02:19', '2026-05-15 15:02:19'),
(5546, 834, 1, 'Đun nóng dầu trong chảo lớn rồi xào tỏi tây và bí xanh trong 5 phút cho mềm. Đổ nước luộc vào, thêm 3/4 số đậu haricot cùng với đậu xanh, một nửa số cà chua vào đun nhỏ lửa trong 5-8 phút cho đến khi rau mềm.', NULL, '2026-05-15 15:02:22', '2026-05-15 15:02:22'),
(5547, 834, 2, 'Trong khi đó, xay phần đậu và cà chua còn lại, tỏi và húng quế trong máy xay thực phẩm (hoặc trong tô bằng máy xay sinh tố) cho đến khi mịn, sau đó cho Parmesan vào khuấy đều. Khuấy nước sốt vào súp, nấu trong 1 phút, sau đó múc một nửa vào bát hoặc đổ vào bình để chuẩn bị bữa trưa đóng hộp. Làm lạnh phần còn lại. Sẽ giữ trong một vài ngày.', NULL, '2026-05-15 15:02:22', '2026-05-15 15:02:22'),
(5549, 835, 1, 'Làm nóng lò nướng ở mức quạt/gas 200C/180C 6. Trộn các miếng khoai lang với dầu ô liu và một ít gia vị rồi trải lên khay nướng có lót giấy da. Nướng trong 30 - 35 phút cho đến khi mềm và vàng. Làm mát ở nhiệt độ phòng.', NULL, '2026-05-15 15:02:27', '2026-05-16 12:35:35'),
(5551, 835, 2, 'Khi vừa nguội, trộn đều tất cả các nguyên liệu làm nước sốt với thêm một chút gia vị và nhẹ nhàng trộn từng miếng khoai tây – dùng tay để tránh làm chúng bị nát.', NULL, '2026-05-15 15:02:27', '2026-05-16 12:35:35'),
(5552, 836, 1, 'Trong một cái bình, trộn tahini với vỏ và nước cốt chanh cùng 50ml nước lạnh để làm nước sốt. Nêm nếm vừa miệng rồi đặt sang một bên.', NULL, '2026-05-15 15:02:30', '2026-05-15 15:02:30'),
(5553, 836, 2, 'Đun nóng dầu trong chảo hoặc chảo lớn trên lửa vừa cao. Thêm hành tím cùng với một chút muối vào xào trong 2 phút cho đến khi bắt đầu mềm và có màu. Thêm tỏi, hạt tiêu, đậu xanh và bí vào xào trong 5 phút, khuấy thường xuyên.', NULL, '2026-05-15 15:02:30', '2026-05-15 15:02:30'),
(5554, 836, 3, 'Thêm cải xoăn, đậu lăng và nước sốt tahini. Giữ chảo trên lửa trong vài phút, khuấy mọi thứ lại với nhau cho đến khi cải xoăn héo và tất cả được phủ một lớp nước sốt kem.', NULL, '2026-05-15 15:02:30', '2026-05-15 15:02:30'),
(5555, 837, 1, 'Ngâm đậu trong nước qua đêm. Để ráo nước. Nếu không có đậu không vỏ thì chà xát cho vỏ bong ra, sau đó bỏ vỏ. Lau khô đậu bằng khăn.', NULL, '2026-05-15 15:02:32', '2026-05-15 15:02:32'),
(5556, 837, 2, 'Xay đậu trong máy xay thực phẩm hoặc máy xay thịt. Nếu không có sẵn thiết bị, hãy xay chúng trong máy xay thực phẩm nhưng chỉ cho đến khi đậu tạo thành hỗn hợp sệt. (Nếu trộn quá mịn, bột có xu hướng bị nát trong khi nấu.) Thêm hành lá, tỏi, ngò, thì là, bột nở, ớt cayenne, muối, tiêu và rau mùi, nếu sử dụng.  Làm lạnh trong ít nhất 30 phút.', NULL, '2026-05-15 15:02:32', '2026-05-15 15:02:32'),
(5557, 837, 3, 'Nặn hỗn hợp đậu thành những quả bóng có kích thước 1 inch. Làm phẳng một chút và phủ một lớp bột mì.', NULL, '2026-05-15 15:02:32', '2026-05-15 15:02:32'),
(5558, 837, 4, 'Đun nóng ít nhất 1 inch dầu trên lửa vừa đến 365 độ.', NULL, '2026-05-15 15:02:32', '2026-05-15 15:02:32'),
(5559, 837, 5, 'Chiên từng miếng chả, quay một lần, cho đến khi vàng nâu tất cả các mặt, khoảng 5 phút. Lấy ra bằng dụng cụ hớt lưới thép hoặc thìa có rãnh. Dùng như một phần của món meze hoặc bánh mì pita với salad cà chua-dưa chuột và sốt tahina.', NULL, '2026-05-15 15:02:32', '2026-05-15 15:02:32'),
(5561, 838, 1, 'Trộn đều sốt mayonnaise, vỏ chanh và nước ép, giấm, mù tạt và muối cần tây trong một cái bát nhỏ, sau đó nêm gia vị vừa đủ.', NULL, '2026-05-15 15:02:36', '2026-05-16 12:35:35'),
(5563, 838, 2, 'Thêm bắp cải, cà rốt, hành tây và cần tây. Trộn đều và để lạnh. Có thể thực hiện trước 1 ngày.', NULL, '2026-05-15 15:02:36', '2026-05-16 12:35:35'),
(5565, 839, 1, 'Cho cà rốt, bắp cải và hành tây vào tô. Làm nước sốt bằng cách khuấy đều các nguyên liệu với nhau cho đến khi đường tan. Đổ salad lên trên, trộn rau vào nước sốt. Thêm các loại thảo mộc, đảo lại lần nữa, sau đó rắc lên đậu phộng.', NULL, '2026-05-15 15:02:38', '2026-05-16 12:35:35'),
(5567, 840, 1, 'Đặt bột cà ri vào chảo lớn hoặc chảo có dầu. Xào trong 1 phút cho đến khi có mùi thơm. Đổ nước luộc rau, nước cốt dừa và đường nâu vào. Đun nhỏ lửa trong 3 phút.', NULL, '2026-05-15 15:02:42', '2026-05-16 12:35:35'),
(5569, 840, 2, 'Thêm mì, cà rốt và lá tàu vào đun nhỏ lửa trong 4-6 phút cho đến khi tất cả mềm. Trộn giá đỗ và cà chua. Thêm nước cốt chanh cho vừa miệng và thêm chút gia vị nếu thích. Múc ra bát và rắc hành lá và rau mùi.', NULL, '2026-05-15 15:02:42', '2026-05-16 12:35:35'),
(5571, 841, 1, 'Làm nóng lò nướng ở mức quạt/khí 200C/180C 6. Cho bí ngô hoặc bí vào hộp rang với một nửa dầu và gia vị, sau đó nướng trong 30 phút cho đến khi vàng và mềm.', NULL, '2026-05-15 15:02:45', '2026-05-16 12:35:35'),
(5573, 841, 2, 'Trong khi đó, cho lượng dầu còn lại vào chảo cùng hành, gừng và sả. Nấu nhẹ nhàng trong 8-10 phút cho đến khi mềm. Khuấy bột cà ri trong 1 phút, tiếp theo là bí ngô nướng, tất cả trừ 3 muỗng canh nước cốt dừa và nước kho. Đun nhỏ lửa, đun trong 5 phút thì vớt sả ra. Để nguội trong vài phút, sau đó xay cho đến khi mịn bằng máy xay cầm tay hoặc trong máy xay lớn theo mẻ. Bắc chảo lên bếp đun nóng, nêm muối, tiêu, nước cốt chanh và đường nếu cần. Ăn kèm với nước cốt dừa còn lại và rắc ớt nếu bạn thích.', NULL, '2026-05-15 15:02:45', '2026-05-16 12:35:35'),
(5575, 842, 1, 'Đặt mì và giá đỗ vào tô chịu nhiệt và đậy lại bằng nước sôi. Để trong 4 phút hoặc cho đến khi mì mềm. Xả, sau đó làm nguội dưới vòi nước lạnh và xả lại. Quay trở lại cái bát.', NULL, '2026-05-15 15:02:51', '2026-05-16 12:35:35'),
(5577, 842, 2, 'Khuấy đều vỏ chanh và nước cốt, cá hoặc nước tương và đường. Khuấy mì với hành tím và rau diếp.', NULL, '2026-05-15 15:02:51', '2026-05-16 12:35:35'),
(5579, 842, 3, 'Để làm thịt băm, đun nóng một ít dầu trong chảo chống dính rồi xào 500g thịt lợn băm, một ít gừng nạo và một nhúm ớt cayenne hoặc bột ớt trong 10 phút, cho đến khi thịt băm chín vàng. Trộn mì vào, chia ra 4 bát và dùng nóng.', NULL, '2026-05-15 15:02:51', '2026-05-16 12:35:35'),
(5581, 842, 4, 'Để làm món bít tết, hãy làm món salad bún. Đun nóng 1 muỗng cà phê dầu hướng dương trong chảo rán. Múc 2 muỗng canh hạt vừng ra đĩa. Xoa 1 thìa cà phê dầu vào 4 miếng thịt thăn x 175g rồi ấn vào hạt vừng. Chiên trong 5 phút ở mức chín vừa, lật nửa chừng. Để yên khoảng 5 phút rồi thái mỏng. Cho 1 quả ớt đỏ thái sợi và bỏ hạt cùng một nắm lá bạc hà vào mì. Top với bít tết để phục vụ.', NULL, '2026-05-15 15:02:51', '2026-05-16 12:35:35'),
(5583, 843, 1, 'Đun nóng dầu trong chảo chống dính. Thêm bông cải xanh vào, sau đó chiên ở nhiệt độ cao trong 5 phút hoặc cho đến khi mềm, thêm một ít nước nếu nó bắt đầu bắt. Thêm tỏi và ớt, xào trong 1 phút, sau đó trộn hành lá, đậu nành, pak choi và đậu phụ. Xào trong 2-3 phút. Thêm tương đen, đậu nành và các loại hạt vào để hâm nóng.', NULL, '2026-05-15 15:02:53', '2026-05-16 12:35:35'),
(5584, 844, 1, '0. Nướng cà tím cho đến khi màu vỏ gần như đen', NULL, '2026-05-15 15:02:57', '2026-05-15 15:02:57'),
(5585, 844, 2, '1. Để cà tím nguội một lúc rồi gọt vỏ. Đặt sang một bên.', NULL, '2026-05-15 15:02:57', '2026-05-15 15:02:57'),
(5586, 844, 3, '2. Đập trứng và cho vào tô', NULL, '2026-05-15 15:02:57', '2026-05-15 15:02:57'),
(5587, 844, 4, '3. Thêm muối và đánh đều', NULL, '2026-05-15 15:02:57', '2026-05-15 15:02:57'),
(5588, 844, 5, '4. Đặt cà tím lên một mặt phẳng và dùng nĩa làm phẳng.', NULL, '2026-05-15 15:02:57', '2026-05-15 15:02:57'),
(5589, 844, 6, '5. Nhúng cà tím đã dẹt vào hỗn hợp trứng đã đánh bông', NULL, '2026-05-15 15:02:57', '2026-05-15 15:02:57'),
(5590, 844, 7, '6. Làm nóng chảo và đổ dầu ăn vào', NULL, '2026-05-15 15:02:57', '2026-05-15 15:02:57'),
(5591, 844, 8, '7. Chiên cà tím (đã nhúng vào hỗn hợp đã đánh). Hãy chắc chắn rằng cả hai mặt đều được nấu chín. Thời gian chiên sẽ mất khoảng 3 đến 4 phút mỗi mặt ở lửa vừa.', NULL, '2026-05-15 15:02:57', '2026-05-15 15:02:57'),
(5592, 845, 1, 'Đun nóng dầu trong chảo lớn, đế nặng. Thêm hành tây và nấu nhẹ nhàng trong 5 – 10 phút cho đến khi mềm.', NULL, '2026-05-15 15:02:59', '2026-05-15 15:02:59'),
(5593, 845, 2, 'Thêm tỏi, gia vị, húng tây khô, cà rốt, cần tây và ớt vào nấu trong 5 phút.', NULL, '2026-05-15 15:02:59', '2026-05-15 15:02:59'),
(5594, 845, 3, 'Thêm cà chua, nước kho, bí xanh và húng tây tươi vào nấu trong 20 - 25 phút.', NULL, '2026-05-15 15:02:59', '2026-05-15 15:02:59'),
(5595, 845, 4, 'Lấy nhánh húng tây ra. Khuấy đậu lăng và đun nhỏ lửa. Ăn kèm với cơm basmati hoang dã và trắng, nghiền hoặc quinoa.', NULL, '2026-05-15 15:02:59', '2026-05-15 15:02:59'),
(5596, 846, 1, 'Làm nóng lò ở nhiệt độ 200C/180C quạt/gas 6', NULL, '2026-05-15 15:03:01', '2026-05-15 15:03:01'),
(5597, 846, 2, 'Nấu rau trong đĩa hầm trong 15 phút', NULL, '2026-05-15 15:03:01', '2026-05-15 15:03:01'),
(5598, 846, 3, 'Cho đậu và cà chua vào, nêm gia vị và nấu thêm 10-15 phút nữa cho đến khi nóng', NULL, '2026-05-15 15:03:01', '2026-05-15 15:03:01'),
(5599, 846, 4, 'Đun nóng túi trong lò vi sóng ở mức Cao trong 1 phút và dùng kèm với ớt', NULL, '2026-05-15 15:03:01', '2026-05-15 15:03:01'),
(5600, 847, 1, 'Xào hành tây và tiêu với lửa vừa cho đến khi hành mềm', NULL, '2026-05-15 15:03:05', '2026-05-15 15:03:05'),
(5601, 847, 2, 'Thêm hạt tỏi, nấu trong một phút', NULL, '2026-05-15 15:03:05', '2026-05-15 15:03:05'),
(5602, 847, 3, 'Thêm cà chua xắt nhỏ và các gia vị còn lại vào, khuấy đều', NULL, '2026-05-15 15:03:05', '2026-05-15 15:03:05'),
(5603, 847, 4, 'Đun sôi khoảng 20 phút', NULL, '2026-05-15 15:03:05', '2026-05-15 15:03:05'),
(5604, 847, 5, 'Tạo vết lõm trong nước sốt và đập một quả trứng vào từng miếng', NULL, '2026-05-15 15:03:05', '2026-05-15 15:03:05'),
(5605, 847, 6, 'Sau khi lòng trắng trứng đã chín, trang trí và dùng kèm với bánh mì nướng', NULL, '2026-05-15 15:03:05', '2026-05-15 15:03:05'),
(5607, 848, 1, 'Ngâm gạo trong bánh xèo theo hướng dẫn trên bao bì hoặc trong nước sôi trong 30 giây. Lấy ra và để nguội trên giấy ăn. Ngâm bún theo hướng dẫn trên bao bì, sau đó để ráo nước và cắt thành từng sợi dài 2cm.', NULL, '2026-05-15 15:03:08', '2026-05-16 12:35:35'),
(5609, 848, 2, 'Đặt chiếc bánh xèo lên thớt rồi xếp một ít bún, thịt gà, rau và lá thơm khoảng 1/3 lên trên, chừa lại mép 1cm. Gấp các cạnh của rau lại rồi cuộn theo chiều dọc để làm điếu xì gà. Bảo quản trong tủ lạnh, phủ giấy ăn ẩm trong tối đa 1 ngày.', NULL, '2026-05-15 15:03:08', '2026-05-16 12:35:35'),
(5611, 848, 3, 'Trộn đều các nguyên liệu làm nước chấm rồi cho vào tô. Khi dùng, xếp các cuộn bánh ra đĩa cùng với lá và rau thơm. Khi ăn, hãy gói từng cuộn trong một miếng rau diếp cùng với một nhánh rau thơm rồi chấm vào nước sốt.', NULL, '2026-05-15 15:03:08', '2026-05-16 12:35:35'),
(5613, 849, 1, 'Đun nóng dầu trong chảo cỡ vừa, có nắp đậy. Thêm gừng và tỏi vào, sau đó xào khoảng 5 phút. Thêm bí, nước tương, đường và nước kho. Đậy nắp, sau đó đun nhỏ lửa trong 10 phút. Mở nắp, cho đậu xanh vào nấu thêm 3 phút nữa cho đến khi bí và đậu mềm. Phi thơm hành lá vào phút cuối rồi rắc rau mùi và dùng với cơm.', NULL, '2026-05-15 15:03:09', '2026-05-16 12:35:35'),
(5614, 850, 1, 'Đun sôi một ít nước trong nồi lớn. Thêm 250ml nước lạnh và mì udon. (Vì chúng rất đặc nên việc thêm nước lạnh sẽ giúp chúng chín chậm hơn một chút để phần giữa chín đều). Nếu sử dụng mì tươi hoặc đông lạnh, hãy nấu trong 2 phút hoặc cho đến khi chín; khô sẽ lâu hơn, khoảng 5-6 phút. Xả và để trong một cái chao.', NULL, '2026-05-15 15:03:12', '2026-05-15 15:03:12'),
(5615, 850, 2, 'Đun nóng 1 muỗng canh dầu, cho hành tây và bắp cải vào xào trong 5 phút cho đến khi mềm. Thêm nấm và một ít hành lá vào xào thêm 1 phút nữa. Đổ dầu mè còn lại và mì vào. Nếu sử dụng mì lạnh, hãy đun nóng mì trước khi thêm nguyên liệu làm nước sốt - nếu không thì cho mì vào ngay và tiếp tục xào cho đến khi dính và nóng. Rắc hành lá còn lại.', NULL, '2026-05-15 15:03:12', '2026-05-15 15:03:12'),
(5616, 851, 1, 'Cho đậu xanh vào nồi lớn và rưới dầu ô liu. Nêm muối vừa ăn rồi đậy nắp nồi. Nấu trên lửa vừa cao, thỉnh thoảng khuấy đều cho đến khi đậu chín đến độ chín như bạn mong muốn. Người Syria thích nấu chín cho đến khi đậu xanh chuyển sang màu nâu. Ý tưởng không phải là xào chúng mà là để chúng hấp trong hơi ẩm do các tinh thể băng tiết ra.', NULL, '2026-05-15 15:03:15', '2026-05-15 15:03:15'),
(5617, 851, 2, 'Thêm ngò và tỏi vào đậu và tiếp tục nấu cho đến khi ngò bắt đầu héo. Ăn như món chính bằng cách ăn kèm với bánh mì pita ấm hoặc dùng như món ăn phụ.', NULL, '2026-05-15 15:03:15', '2026-05-15 15:03:15'),
(5619, 852, 1, 'Đun nóng dầu ô liu trong chảo lớn trên lửa cao hoặc nếu sử dụng nồi chiên không khí, hãy đun nóng đến 205C trong 3 phút. Chiên ớt, khuấy thường xuyên trong 5 phút cho đến khi phồng rộp và héo. Ớt phải mềm và hơi cháy.', NULL, '2026-05-15 15:03:18', '2026-05-16 12:35:35'),
(5621, 852, 2, 'Chuyển ớt vào đĩa phục vụ và nêm một ít muối biển. Ăn kèm với nước chấm hoặc dùng như một phần của món tapas, nếu bạn thích.', NULL, '2026-05-15 15:03:18', '2026-05-16 12:35:35'),
(5622, 853, 1, 'Gọt vỏ hành tây, cắt làm đôi từ trên xuống dưới và thái thành từng miếng hình bán nguyệt. Đặt vào một cái chao đặt trên một cái bát và rắc muối, dùng tay lật nhẹ các miếng hành tây để phủ đều các bề mặt. Dành khoảng một giờ để ngâm nước muối.', NULL, '2026-05-15 15:03:20', '2026-05-15 15:03:20'),
(5623, 853, 2, 'Trong khi đó cho giấm, 50ml/2fl oz nước và đường vào nồi. Đun nhỏ lửa, khuấy đều để giúp đường tan và nấu trong vài phút. Đặt sang một bên.', NULL, '2026-05-15 15:03:20', '2026-05-15 15:03:20'),
(5624, 853, 3, 'Cho hành tây vào lọ khử trùng, rắc một ít hạt tiêu lên trên. Phủ giấm ấm lên và kết thúc bằng cách nhét vài chiếc lá nguyệt quế xuống thành lọ. Niêm phong. Tốt nhất nên bảo quản hành tây trong tủ lạnh và sử dụng trong vòng 4 tuần.', NULL, '2026-05-15 15:03:20', '2026-05-15 15:03:20'),
(5625, 854, 1, '1 Cho thì là, cà tím, hạt tiêu và bí vào khay rang. Thêm một chút dầu ô liu, nêm muối và hạt tiêu rồi đảo đều để rau ngập trong dầu. Nướng trong lò khoảng 20 phút, đảo vài lần cho đến khi rau chín hẳn và chuyển sang màu vàng.', NULL, '2026-05-15 15:03:23', '2026-05-15 15:03:23'),
(5626, 854, 2, '2 Trong khi đó, làm nóng chảo paella hoặc chảo rán lớn trên lửa vừa và nhỏ và thêm một chút dầu ô liu. Xào hành tây trong 8–10 phút cho đến khi mềm. Tăng lửa vừa và cho gạo, ớt bột và nghệ tây vào khuấy đều. Nấu khoảng 1 phút để gạo bắt đầu nở, sau đó cho rượu trắng vào. Giảm khoảng một nửa trước khi khuấy 2/3 lượng nước dùng. Giảm lửa nhỏ và nấu trong 10 phút mà không đậy nắp, khuấy vài lần.', NULL, '2026-05-15 15:03:23', '2026-05-15 15:03:23'),
(5627, 854, 3, '3 Khuấy đậu Hà Lan, thêm một ít gia vị, sau đó trộn nhẹ nhàng với rau đã rang. Đổ phần nước còn lại lên trên, xếp các lát chanh lên trên và đậy nắp lại hoặc một ít giấy nhôm. Nấu thêm 10 phút nữa.', NULL, '2026-05-15 15:03:23', '2026-05-15 15:03:23'),
(5628, 854, 4, '4 Để đảm bảo bạn có được lớp cơm nướng cổ điển ở đáy chảo, hãy tăng lửa lên cao cho đến khi bạn nghe thấy tiếng nổ nhẹ. Tắt bếp và để yên trong 5 phút trước khi rắc lên rau mùi tây và thưởng thức.', NULL, '2026-05-15 15:03:23', '2026-05-15 15:03:23'),
(5630, 855, 1, 'Cho rau củ đã cắt nhỏ vào tô rồi thêm giấm, đường và 1 thìa cà phê muối. Trộn tất cả mọi thứ lại với nhau, sau đó đặt sang một bên để ngâm nhanh trong khi chuẩn bị phần còn lại của bánh sandwich.', NULL, '2026-05-15 15:03:24', '2026-05-16 12:35:35'),
(5632, 855, 2, 'Làm nóng lò ở mức quạt/khí 180C/160C 4. Cắt bánh mì baguette thành bốn, sau đó cắt từng miếng làm đôi theo chiều ngang. Đặt các miếng bánh mì baguette vào lò nướng trong 5 phút cho đến khi nướng nhẹ và ấm. Trải từng miếng một một lớp hummus, sau đó phủ các lát tempeh lên bốn miếng và xếp rau ngâm lên trên. Để phục vụ, rắc các loại thảo mộc lên trên và rưới một ít nước sốt nóng, sau đó phủ các miếng bánh mì baguette khác lên trên để làm bánh mì sandwich.', NULL, '2026-05-15 15:03:24', '2026-05-16 12:35:35'),
(5633, 856, 1, 'Đơn giản chỉ cần trộn tất cả các thành phần khô với các thành phần ướt và trộn hoàn toàn', NULL, '2026-05-15 15:03:30', '2026-05-15 15:03:30'),
(5634, 856, 2, 'Nướng trong 45 phút ở 180 độ', NULL, '2026-05-15 15:03:30', '2026-05-15 15:03:30'),
(5635, 856, 3, 'Trang trí với một ít sô cô la thuần chay tan chảy', NULL, '2026-05-15 15:03:30', '2026-05-15 15:03:30'),
(5636, 857, 1, '1) Làm nóng lò ở nhiệt độ 180 độ C.', NULL, '2026-05-15 15:03:33', '2026-05-15 15:03:33'),
(5637, 857, 2, '2) Luộc rau trong 5-7 phút cho đến khi mềm. Thêm đậu lăng và đun sôi nhẹ, thêm khối nước luộc nếu muốn. Tiếp tục nấu và khuấy cho đến khi đậu lăng mềm, quá trình này sẽ mất khoảng 20 phút.', NULL, '2026-05-15 15:03:33', '2026-05-15 15:03:33'),
(5638, 857, 3, '3) Chần lá rau bina trong chảo vài phút trước khi lấy ra và đặt sang một bên.', NULL, '2026-05-15 15:03:33', '2026-05-15 15:03:33'),
(5639, 857, 4, '4) Đổ nước vào chảo và nấu các tấm lasagne. Khi nấu chín, để ráo nước và đặt sang một bên.', NULL, '2026-05-15 15:03:33', '2026-05-15 15:03:33'),
(5640, 857, 5, '5) Để làm nước sốt, làm tan chảy bơ và thêm bột mì, sau đó thêm dần sữa đậu nành cùng với mù tạt và giấm. Nấu và khuấy cho đến khi mịn rồi xếp lasagne theo ý muốn vào đĩa nướng.', NULL, '2026-05-15 15:03:33', '2026-05-15 15:03:33'),
(5641, 857, 6, '6) Nướng trong lò làm nóng trước khoảng 25 phút.', NULL, '2026-05-15 15:03:33', '2026-05-15 15:03:33'),
(5643, 858, 1, 'Đổ bánh mì vào tô và đổ 350ml nước. Để ngâm trong 10 phút.', NULL, '2026-05-15 15:03:38', '2026-05-16 12:35:35'),
(5645, 858, 2, 'Trộn các nguyên liệu với nhau với 350ml nước và 1 muỗng cà phê muối.', NULL, '2026-05-15 15:03:38', '2026-05-16 12:35:35'),
(5647, 858, 3, 'Để súp nguội trong tủ lạnh khoảng 1 giờ, sau đó dùng với một chút dầu và một ít hạt tiêu đen.', NULL, '2026-05-15 15:03:38', '2026-05-16 12:35:35'),
(5648, 859, 1, 'Đun nóng dầu hạt cải trong chảo lớn rồi cho hành tây vào. Nấu trên lửa vừa cho đến khi mềm. Thêm một chút nước nếu hành bắt đầu bị dính.', NULL, '2026-05-15 15:03:40', '2026-05-15 15:03:40'),
(5649, 859, 2, 'Thêm cần tây, tỏi tây, khoai tây và một ít bơ. Khuấy cho đến khi tan chảy, sau đó đậy nắp lại. Để mồ hôi trong 5 phút. Tháo nắp.', NULL, '2026-05-15 15:03:40', '2026-05-15 15:03:40'),
(5650, 859, 3, 'Đổ nước dùng vào và thêm bất kỳ cọng bông cải xanh nào. Nấu trong vòng 10 – 15 phút cho đến khi tất cả các loại rau đều mềm.', NULL, '2026-05-15 15:03:40', '2026-05-15 15:03:40'),
(5651, 859, 4, 'Thêm phần còn lại của bông cải xanh và nấu thêm 5 phút nữa. Cẩn thận chuyển vào máy xay và xay cho đến khi mịn. Khuấy stilton, để lại một vài cục. Nêm hạt tiêu đen và phục vụ.', NULL, '2026-05-15 15:03:40', '2026-05-15 15:03:40');
INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `description`, `image`, `created_at`, `updated_at`) VALUES
(5652, 860, 1, 'Rửa nghêu qua nhiều lần nước lạnh và để ráo nước. Cho nghêu vào chảo lớn với 500ml nước. Đậy nắp, đun sôi và đun nhỏ lửa trong 2 phút cho đến khi nghêu vừa mở miệng. Đổ lượng chứa trong chảo vào một cái rây phía trên một cái bát để hứng nước luộc ngao. Khi đủ nguội để xử lý, hãy lấy nghêu ra khỏi vỏ - dành một ít vỏ rỗng để trình bày nếu bạn muốn. Lọc nước ngao vào bình, để lại cặn sạn ở đáy bát. Bạn nên có khoảng 800ml nước dự trữ.', NULL, '2026-05-15 15:03:45', '2026-05-15 15:03:45'),
(5653, 860, 2, 'Đun nóng bơ trong cùng chảo và xào thịt xông khói trong 3-4 phút cho đến khi bắt đầu có màu nâu. Khuấy hành tây, húng tây và lá nguyệt quế rồi nấu mọi thứ nhẹ nhàng trong 10 phút cho đến khi hành tây mềm và vàng. Rải bột mì lên và khuấy đều để tạo thành hỗn hợp sệt, nấu thêm 2 phút, sau đó cho dần nước luộc ngao vào, sau đó là sữa và kem.', NULL, '2026-05-15 15:03:45', '2026-05-15 15:03:45'),
(5654, 860, 3, 'Cho khoai tây vào, đun nhỏ lửa và để sôi nhẹ trong 10 phút hoặc cho đến khi khoai tây chín. Dùng nĩa ấn một vài miếng khoai tây vào thành chảo để làm dày - tuy nhiên, bạn vẫn muốn có nhiều miếng khoai tây xác định. Khuấy thịt nghêu và một ít vỏ ngao nếu bạn đã làm theo cách đó và đun nhỏ lửa trong một phút để hâm nóng. Nêm nhiều hạt tiêu đen và một chút muối, nếu cần, sau đó khuấy qua mùi tây ngay trước khi múc vào bát hoặc cuộn giòn rỗng.', NULL, '2026-05-15 15:03:45', '2026-05-15 15:03:45'),
(5655, 861, 1, 'Vỏ bánh: làm bột từ 250g bột mì (tôi thích trộn các loại bột khác nhau như bột mì thường và bột mì nguyên hạt), 125g bơ, 1 quả trứng và một chút muối, ép thành dạng bánh tart rồi cho vào tủ lạnh', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5656, 861, 2, 'Nhân: khuấy 300g kem phô mai và 100ml sữa cho đến khi mịn, thêm 3 quả trứng, 100g phô mai parmesan bào vào và nêm muối, tiêu, nhục đậu khấu', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5657, 861, 3, 'Lấy lớp vỏ ra khỏi tủ lạnh và dùng nĩa chọc vào đáy', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5658, 861, 4, 'Đổ nhân vào và nướng ở nhiệt độ 175 độ C trong khoảng 25 phút', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5659, 861, 5, 'Đậy bánh tart bằng một ít giấy nhôm sau một nửa thời gian', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5660, 861, 6, 'Trong lúc đó, cắt lát khoảng 350g cà chua nhỏ', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5661, 861, 7, 'Trong chảo nhỏ đun nóng 3 thìa canh dầu ô liu, 3 thìa canh giấm trắng, 1 thìa canh mật ong, muối và tiêu rồi trộn đều', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5662, 861, 8, 'Đổ các lát cà chua lên trên và trộn đều', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5663, 861, 9, 'Dùng thìa đặt các lát cà chua lên bánh tart, tránh để quá nhiều chất lỏng lên trên', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5664, 861, 10, 'Trang trí với lá húng quế và thưởng thức', NULL, '2026-05-15 15:03:48', '2026-05-15 15:03:48'),
(5665, 862, 1, 'Cho dầu, hành tây, cần tây, cà rốt, khoai tây và lá nguyệt quế vào một cái nồi lớn hoặc hai cái chảo. Chiên nhẹ nhàng cho đến khi hành tây mềm – khoảng 10-15 phút. Đổ đầy ấm và đun sôi.', NULL, '2026-05-15 15:03:51', '2026-05-15 15:03:51'),
(5666, 862, 2, 'Khuấy nhuyễn cà chua, đường, giấm, cà chua cắt nhỏ và passata, sau đó nghiền thành khối vuông. Thêm 1 lít nước sôi vào đun nhỏ lửa. Đậy nắp và đun nhỏ lửa trong 15 phút cho đến khi khoai tây mềm thì vớt lá nguyệt quế ra. Nghiền nhuyễn bằng máy xay sinh tố (hoặc múc từng mẻ vào máy xay) cho đến khi thật mịn. Nêm nếm vừa ăn và thêm chút đường nếu cần. Súp hiện có thể được làm lạnh và ướp lạnh tối đa 2 ngày hoặc đông lạnh tối đa 3 tháng.', NULL, '2026-05-15 15:03:51', '2026-05-15 15:03:51'),
(5667, 862, 3, 'Khi dùng, hâm nóng súp, khuấy sữa - cố gắng không để sôi. Phục vụ trong bát nhỏ với cuộn xúc xích phô mai.', NULL, '2026-05-15 15:03:51', '2026-05-15 15:03:51'),
(5669, 863, 1, 'Trong máy xay sinh tố (hoặc bằng máy xay dạng que), trộn đều passata, ớt đỏ, ớt, tỏi, giấm sherry và nước cốt chanh cho đến khi mịn. Nêm nếm vừa ăn rồi dùng kèm đá viên', NULL, '2026-05-15 15:03:54', '2026-05-16 12:35:35'),
(5672, 866, 1, 'cho nước vào đun củi', NULL, '2026-05-17 00:27:04', '2026-05-17 00:27:04');
